INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('059b4eb3-f42e-460b-b4bb-dd373cc0c964', 817, 'odd_one_out', 'B2', 'money', 'Three of these relate to economic problems. Which is the odd one out?', 'dividend', '["inflation", "recession", "deficit", "dividend"]', NULL, NULL, NULL, NULL, 'Inflation (rising prices), recession (economic decline), and deficit (spending more than you earn) are all economic problems. A dividend is a positive payout to investors — not a problem unless you are the one paying it!', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{Vocabulary}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('b49debe5-3d38-4742-b491-39f39d7f00a8', 1897, 'matching', 'A1', 'vocabulary', 'Match the picture to the correct word.', 'match_all_pairs', '[{"left": {"type": "image", "content": "https://dyxmgicedabvmsbuvxny.supabase.co/storage/v1/object/public/audio/matching/suitcase.png"}, "right": {"type": "text", "content": "suitcase"}}, {"left": {"type": "image", "content": "https://dyxmgicedabvmsbuvxny.supabase.co/storage/v1/object/public/audio/matching/backpack.png"}, "right": {"type": "text", "content": "backpack"}}, {"left": {"type": "image", "content": "https://dyxmgicedabvmsbuvxny.supabase.co/storage/v1/object/public/audio/matching/briefcase.png"}, "right": {"type": "text", "content": "briefcase"}}]', NULL, NULL, NULL, NULL, NULL, '2026-04-08 18:25:27.713957+00', NULL, NULL, 'en', '{Travel,Vocabulary}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('20305b9c-673b-4c71-b3a7-689bc5bb0aad', 2213, 'multiple_choice', 'A2', 'phrasal_verbs', 'Can you ___ the light? It''s dark in here.', 'turn on', '["turn on", "turn off", "put off", "take on"]', NULL, NULL, NULL, 'Switch it on so it works.', '"Turn on" means to switch on a device so it works.', '2026-06-01 07:29:20.293249+00', NULL, NULL, 'en', '{"Phrasal verb"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('6647ebea-a59a-4a99-b4ae-20b0a5df7e81', 2214, 'multiple_choice', 'A2', 'phrasal_verbs', 'She ___ her grandmother on Sundays.', 'looks after', '["looks after", "looks for", "looks up", "looks out"]', NULL, NULL, NULL, 'Takes care of someone.', '"Look after" someone means to take care of them.', '2026-06-01 07:29:20.293249+00', NULL, NULL, 'en', '{"Phrasal verb"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('210dbe1b-10cc-4e4f-a83f-fe86495340a7', 1953, 'odd_one_out', 'B1', 'collocations', 'Three of these verbs collocate naturally with "decision". Which is the odd one out?', 'do', '["make", "reach", "take", "do"]', NULL, NULL, NULL, NULL, 'We "make a decision", "reach a decision", or "take a decision". We never "do a decision".', '2026-04-08 18:26:42.653742+00', NULL, NULL, 'en', '{Vocabulary,Collocation}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('e92d6a28-5cc4-4ab5-956f-23971b747ede', 1916, 'matching', 'B2', 'grammar', 'Match each sentence to the correct conditional type.', 'match_all_pairs', '[{"left": {"type": "text", "label": "", "content": "If you heat water to 100°C, it boils."}, "right": {"type": "text", "label": "", "content": "zero conditional (general truth)"}}, {"left": {"type": "text", "label": "", "content": "If it rains tomorrow, I''ll stay at home."}, "right": {"type": "text", "label": "", "content": "first conditional (real future)"}}, {"left": {"type": "text", "label": "", "content": "If I won the lottery, I''d travel the world."}, "right": {"type": "text", "label": "", "content": "second conditional (unreal present)"}}, {"left": {"type": "text", "label": "", "content": "If she had left earlier, she wouldn''t have missed the train."}, "right": {"type": "text", "label": "", "content": "third conditional (unreal past)"}}]', NULL, NULL, NULL, NULL, NULL, '2026-04-08 18:25:27.713957+00', NULL, NULL, 'en', '{Grammar,Conditional}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('af4d14e4-e179-4d19-9d98-39b8be460e37', 1898, 'matching', 'A1', 'vocabulary', 'Match the picture to the correct word.', 'match_all_pairs', '[{"left": {"type": "image", "content": "https://dyxmgicedabvmsbuvxny.supabase.co/storage/v1/object/public/audio/matching/phone%20charger.png"}, "right": {"type": "text", "content": "phone charger"}}, {"left": {"type": "image", "content": "https://dyxmgicedabvmsbuvxny.supabase.co/storage/v1/object/public/audio/matching/cable.png"}, "right": {"type": "text", "content": "cable"}}, {"left": {"type": "image", "content": "https://dyxmgicedabvmsbuvxny.supabase.co/storage/v1/object/public/audio/matching/plug%20socket.png"}, "right": {"type": "text", "content": "plug socket"}}]', NULL, NULL, NULL, NULL, NULL, '2026-04-08 18:25:27.713957+00', NULL, NULL, 'en', '{Technology,Vocabulary}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('be7be936-c0b2-4b34-866f-766185cbdfd5', 1899, 'matching', 'A1', 'vocabulary', 'Match the picture to the correct word.', 'match_all_pairs', '[{"left": {"type": "image", "content": "https://dyxmgicedabvmsbuvxny.supabase.co/storage/v1/object/public/audio/matching/glasses.png"}, "right": {"type": "text", "content": "glasses"}}, {"left": {"type": "image", "content": "https://dyxmgicedabvmsbuvxny.supabase.co/storage/v1/object/public/audio/matching/a%20glass.png"}, "right": {"type": "text", "content": "a glass"}}, {"left": {"type": "image", "content": "https://dyxmgicedabvmsbuvxny.supabase.co/storage/v1/object/public/audio/matching/glass.png"}, "right": {"type": "text", "content": "glass"}}]', NULL, NULL, NULL, NULL, NULL, '2026-04-08 18:25:27.713957+00', NULL, NULL, 'en', '{Vocabulary}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('fc72be5a-02ad-4f3c-a762-293ac5825866', 1900, 'matching', 'A2', 'idioms', 'Match each idiom to its meaning.', 'match_all_pairs', '[{"left": {"type": "text", "label": "", "content": "a piece of cake"}, "right": {"type": "text", "label": "", "content": "very easy"}}, {"left": {"type": "text", "label": "", "content": "under the weather"}, "right": {"type": "text", "label": "", "content": "feeling unwell"}}, {"left": {"type": "text", "label": "", "content": "hit the road"}, "right": {"type": "text", "label": "", "content": "start a journey"}}, {"left": {"type": "text", "label": "", "content": "break a leg"}, "right": {"type": "text", "label": "", "content": "good luck"}}]', NULL, NULL, NULL, NULL, NULL, '2026-04-08 18:25:27.713957+00', NULL, NULL, 'en', '{Idioms}', true, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('063dfdf1-79a4-41e8-9340-aa3eb46f0e21', 1901, 'matching', 'A2', 'idioms', 'Match each idiom to its meaning.', 'match_all_pairs', '[{"left": {"type": "text", "label": "", "content": "in the end"}, "right": {"type": "text", "label": "", "content": "finally"}}, {"left": {"type": "text", "label": "", "content": "for good"}, "right": {"type": "text", "label": "", "content": "permanently"}}, {"left": {"type": "text", "label": "", "content": "once in a while"}, "right": {"type": "text", "label": "", "content": "occasionally"}}, {"left": {"type": "text", "label": "", "content": "no wonder"}, "right": {"type": "text", "label": "", "content": "it''s not surprising"}}]', NULL, NULL, NULL, NULL, NULL, '2026-04-08 18:25:27.713957+00', NULL, NULL, 'en', '{Idioms}', true, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('575b0d75-f7b3-4c49-8cea-32e82e9d7151', 72, 'gap_fill', 'B1', 'countable_uncountable', 'Would you like ___ (a / an / some) apple?', 'an', NULL, NULL, NULL, NULL, 'Apple is countable', 'Use a/an with singular countable nouns.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{"Uncountable noun"}', false, 'Apple starts with a vowel sound — needs "an", not "a".', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('adc88b04-78bc-4be4-b09a-0096d9a141ec', 1122, 'multiple_choice', 'A2', 'bathroom_vocabulary', 'A tile with a rough, uneven surface texture is described as _______.', 'textured', '["textured", "matte", "glazed", "polished"]', NULL, NULL, NULL, 'Adjective for a surface that''s not smooth.', 'A textured tile has an uneven, tactile surface. This increases grip — making textured tiles suitable for wet areas or floor applications where slip resistance matters.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Bathroom vocabulary","Confusable words"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('d24c203b-4396-4a17-84c9-9a34cf7d1b78', 1123, 'multiple_choice', 'A2', 'bathroom_vocabulary', 'The thing which we sit or lay in to wash ourselves is called a _______.', 'bath', '["basin", "bath", "sink", "bowl"]', NULL, NULL, NULL, 'A large container of water you sit or lie in.', 'Some people may use bathtub as an equivalent to bath, it means the same thing.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Bathroom vocabulary"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('dc1cfe35-efe7-4ad8-a7b6-752fd82cbb57', 2215, 'multiple_choice', 'A2', 'phrasal_verbs', 'We ___ at 6 a.m. to catch the train.', 'set off', '["set off", "set up", "put off", "get off"]', NULL, NULL, NULL, 'Started the journey.', '"Set off" means to start a journey.', '2026-06-01 07:29:20.293249+00', NULL, NULL, 'en', '{"Phrasal verb"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('99a89e58-4a73-44ed-a6c7-f09c67fbcf2f', 2216, 'multiple_choice', 'A2', 'phrasal_verbs', 'He ___ smoking last year.', 'gave up', '["gave up", "gave in", "gave back", "gave away"]', NULL, NULL, NULL, 'Stopped a habit.', '"Give up" means to stop doing something, often a habit.', '2026-06-01 07:29:20.293249+00', NULL, NULL, 'en', '{"Phrasal verb"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('3df8a275-6cdc-409f-be67-f5ba282dbeed', 910, 'sentence_auction', 'A2', 'spanish', 'Theme: Tener Expressions', 'auction', '[{"correct": true, "sentence": "Tengo mucho frío — necesito un abrigo.", "explanation": "Correct! Use tener frío for the physical sensation of being cold."}, {"correct": false, "sentence": "Estoy mucha hambre después del entreno.", "explanation": "Wrong — use tener for physical sensations, not estar: Tengo mucha hambre."}, {"correct": true, "sentence": "El niño tiene sueño y quiere dormir.", "explanation": "Correct! Tener sueño means to be sleepy."}, {"correct": false, "sentence": "Soy veintiocho años.", "explanation": "Wrong — use tener for age, not ser: Tengo veintiocho años."}, {"correct": true, "sentence": "Tenemos prisa — el tren sale en cinco minutos.", "explanation": "Correct! Tener prisa means to be in a hurry."}, {"correct": false, "sentence": "¿Estás sed? Hay agua en la mesa.", "explanation": "Wrong — use tener for thirst: ¿Tienes sed?"}]', NULL, NULL, NULL, NULL, NULL, '2026-03-03 14:15:59.915911+00', NULL, NULL, 'es', '{Vocabulario}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('6e2696bb-f2bc-4731-9e9d-f498afe3ebdb', 892, 'multiple_choice', 'A2', 'spanish', 'Which word means "always" in Spanish?', 'siempre', '["siempre", "nunca", "a veces", "también"]', NULL, NULL, NULL, NULL, '"Siempre" = always. Other frequency adverbs: "nunca" = never, "a veces" = sometimes, "también" = also/too.', '2026-03-03 14:10:39.181019+00', NULL, NULL, 'es', '{Vocabulario}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('09b848ea-514d-4093-ad89-407963aee04e', 888, 'multiple_choice', 'A2', 'spanish', 'What does "el desayuno" mean in English?', 'Breakfast', '["Breakfast", "Lunch", "Dinner", "Snack"]', NULL, NULL, NULL, NULL, '"El desayuno" means breakfast. The other meals are: "la comida/el almuerzo" (lunch), "la cena" (dinner), and "la merienda" (afternoon snack).', '2026-03-03 14:10:39.181019+00', NULL, NULL, 'es', '{Vocabulario}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('862ad02a-8822-4812-aa36-a0fb58e1204c', 734, 'multiple_choice', 'A1', 'grammar', 'Which sentence is correct?', 'She has a dog.', '["She have a dog.", "She has a dog.", "She haves a dog.", "She is have a dog."]', NULL, NULL, NULL, 'Look for correct subject-verb agreement: she + has (not have).', 'With he/she/it, the verb "have" becomes "has" in present simple.', '2026-02-26 08:30:21.753626+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('22bfc29f-cc28-4b87-9c8f-679dfa6c9bcb', 891, 'multiple_choice', 'A2', 'spanish', 'What is the plural of "el libro"?', 'los libros', '["los libros", "las libros", "los libro", "el libros"]', NULL, NULL, NULL, NULL, 'To make a noun plural in Spanish, add -s to words ending in a vowel. The article also changes: "el" becomes "los". So "el libro" becomes "los libros".', '2026-03-03 14:10:39.181019+00', NULL, NULL, 'es', '{Vocabulario}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('f2961b1b-c283-47fb-abdc-36934feb2028', 904, 'multiple_choice', 'A2', 'spanish', 'How do you make a polite request in Spanish? "_____ un café, por favor."', 'Quisiera', '["Quisiera", "Quiero", "Tengo", "Necesito"]', NULL, NULL, NULL, NULL, '"Quisiera" (I would like) is the polite form for requests — it is the conditional of "querer". "Quiero" (I want) is correct but less polite. Use "quisiera" in shops and restaurants and formal settings. Me gustaría tener/tomar is similar: I would like to have. In Spanish we are often more direct.', '2026-03-03 14:10:39.181019+00', NULL, NULL, 'es', '{Vocabulario}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('c837c352-a8a4-407d-bc51-51c1e09e57ef', 895, 'multiple_choice', 'A2', 'spanish', 'Choose the correct sentence: "_____ las tres de la tarde."', 'Son', '["Son", "Es", "Están", "Hay"]', NULL, NULL, NULL, NULL, 'Use "son" for all times except 1 o''clock: "Son las tres." Use "es" only for "Es la una." "Están" and "hay" are never used for telling the time.', '2026-03-03 14:10:39.181019+00', NULL, NULL, 'es', '{Vocabulario}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('dd0df7ca-6f0f-4341-afa5-5a31aa331fd9', 1250, 'gap_fill', 'C2', 'business_phrasal_verbs', 'The legal team spent weeks _____ the terms of the licensing agreement.', 'thrashing out', NULL, NULL, NULL, NULL, 'To work out (terms, agreements) through intense discussion.', 'Thrash out means to discuss something at length until an agreement is reached. Compare: hammer out, iron out, work out.', '2026-03-18 19:58:52.376507+00', NULL, NULL, 'en', '{}', false, 'Stronger than "ironing out".', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('efd2ab30-7a02-44f3-aa85-1b0002ce2a09', 2217, 'multiple_choice', 'A2', 'phrasal_verbs', 'We need to ___ for the meeting now.', 'set off', '["set off", "set up", "put off", "get off"]', NULL, NULL, NULL, 'Begin a journey.', '"Set off" means to begin a journey or leave for somewhere.', '2026-06-01 07:29:20.293249+00', NULL, NULL, 'en', '{"Phrasal verb"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('1c9fc51a-6c1c-4a05-b593-faaba543afa8', 897, 'multiple_choice', 'A2', 'spanish', 'Which adjective means "tired" in Spanish?', 'cansado', '["cansado", "contento", "enfadado", "aburrido"]', NULL, NULL, NULL, NULL, '"Cansado" = tired. "Contento" = happy, "enfadado" = angry, "aburrido" = bored. Remember adjectives change ending for gender: "cansada" for feminine.', '2026-03-03 14:10:39.181019+00', NULL, NULL, 'es', '{Vocabulario}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('d7e4394a-d3b9-495c-99e8-6a081b0f351a', 2218, 'multiple_choice', 'A2', 'phrasal_verbs', 'Could you ___ the TV? I''m trying to sleep.', 'turn off', '["turn off", "turn on", "put on", "take off"]', NULL, NULL, NULL, 'Switch it off.', '"Turn off" means to switch off a device.', '2026-06-01 07:29:20.293249+00', NULL, NULL, 'en', '{"Phrasal verb"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('7ca22b50-1cee-4dfc-ad33-2b5573ce5c88', 900, 'multiple_choice', 'A2', 'spanish', 'Which sentence is grammatically correct?', 'Me gustan los libros', '["Me gusta los libros", "Me gustan los libros", "Me gusta el libros", "Me gustas los libros"]', NULL, NULL, NULL, NULL, '"Gustar" agrees with the subject (the thing that is liked), not the person. Since "los libros" is plural, use "gustan". Literally: books are pleasing to me.', '2026-03-03 14:10:39.181019+00', NULL, NULL, 'es', '{Vocabulario}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('063bde28-8585-4e2c-8d9b-f1425ef95fee', 902, 'multiple_choice', 'A2', 'spanish', 'How do you say "I get up at 7 in the morning" in Spanish?', 'Me levanto a las 7', '["Me levanto a las 7", "Me levanto las 7", "Levanto a las 7", "Me levantó a las 7"]', NULL, NULL, NULL, NULL, '"Levantarse" is a reflexive verb, so it needs a reflexive pronoun: "me levanto". Always use "a las" before the time. "Me levantó" is a past tense form, not present.', '2026-03-03 14:10:39.181019+00', NULL, NULL, 'es', '{Vocabulario}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('a3beb944-2911-4887-9632-5abf78cbbe21', 903, 'multiple_choice', 'A2', 'spanish', 'What is the opposite of "barato" in Spanish?', 'caro', '["caro", "pequeño", "lejos", "tarde"]', NULL, NULL, NULL, NULL, '"Barato" = cheap, so its opposite is "caro" = expensive. "Pequeño" = small, "lejos" = far, "tarde" = late.', '2026-03-03 14:10:39.181019+00', NULL, NULL, 'es', '{Vocabulario}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('7ff3c738-9a7c-4f38-97d1-dc3e7bc3cf5c', 893, 'multiple_choice', 'A2', 'spanish', 'How do you say "I have a headache" in Spanish?', 'Tengo dolor de cabeza', '["Tengo dolor de cabeza", "Estoy dolor de cabeza", "Tengo duele de cabeza", "Soy dolor de cabeza"]', NULL, NULL, NULL, 'Spanish uses "tener" (to have) for physical states + "dolor de" (pain of).', 'Use "tener dolor de + body part" for pain: "tengo dolor de cabeza" (headache), "tengo dolor de espalda" (backache), "tengo dolor de estómago" (stomach ache).', '2026-03-03 14:10:39.181019+00', NULL, NULL, 'both', '{Vocabulario}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('cc708416-6bd3-4000-bd38-026d88a6af36', 2219, 'multiple_choice', 'A2', 'phrasal_verbs', 'They ___ a new café in town.', 'opened up', '["opened up", "opened off", "put up", "set in"]', NULL, NULL, NULL, 'Started or established it.', '"Open up" means to start or establish a new business.', '2026-06-01 07:29:20.293249+00', NULL, NULL, 'en', '{"Phrasal verb"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('cf08ad09-66d9-4ab5-a960-164b75b42083', 2220, 'gap_fill', 'B2', 'phrasal_verbs', 'The meeting was ___ until next week.', 'put off', '[]', NULL, NULL, NULL, 'Postponed to a later time.', '"Put off" means to postpone something to a later time.', '2026-06-01 07:29:20.293249+00', NULL, NULL, 'en', '{"Phrasal verb"}', false, 'Two words; the particle is "off".', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('9382e0d4-1c93-4296-bf3c-4f56abf8875f', 905, 'multiple_choice', 'A2', 'spanish', 'Which sentence uses "estar" correctly?', 'El café está frío', '["El café está frío", "El café es frío", "El café está grande", "El café es delicioso"]', NULL, NULL, NULL, NULL, 'Use "estar" for temporary states or conditions. "El café está frío" = the coffee is cold right now. "Es grande" describes permanent size and "es delicioso" is a permanent characteristic, so "ser" is correct for those.', '2026-03-03 14:10:39.181019+00', NULL, NULL, 'es', '{Vocabulario}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('05f32418-3655-4bfb-baa0-01b5765112a4', 2221, 'gap_fill', 'B2', 'phrasal_verbs', 'I can''t ___ why she''s so upset.', 'work out', '[]', NULL, NULL, NULL, 'Understand or figure something out.', '"Work out" means to understand or figure something out.', '2026-06-01 07:29:20.293249+00', NULL, NULL, 'en', '{"Phrasal verb"}', false, '"work ___" — particle "out".', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('8a3e79a5-3502-4eaf-a517-ffdd60c9b1de', 907, 'multiple_choice', 'A2', 'spanish', 'Which word correctly completes the sentence: "Fui al supermercado _____ comprar leche."', 'para', '["para", "por", "que", "a"]', NULL, NULL, NULL, NULL, 'Use "para" to express purpose (in order to): "fui al supermercado para comprar leche" = I went to the supermarket to buy milk. "Por" is used for cause or reason, not purpose with an infinitive.', '2026-03-03 14:10:39.181019+00', NULL, NULL, 'es', '{Vocabulario}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('00440d6d-f043-4484-ba89-40ac23b4bac5', 908, 'sentence_auction', 'A2', 'spanish', 'Theme: Ser vs Estar', 'auction', '[{"correct": true, "sentence": "El café está frío.", "explanation": "Correct! Use estar for a temporary state — the coffee is cold right now."}, {"correct": false, "sentence": "Ella es cansada hoy.", "explanation": "Wrong — use estar for temporary states: Ella está cansada hoy."}, {"correct": true, "sentence": "Mi hermano es médico.", "explanation": "Correct! Use ser for permanent characteristics like profession."}, {"correct": false, "sentence": "Estoy de España.", "explanation": "Wrong — use ser for origin: Soy de España."}, {"correct": true, "sentence": "La reunión es a las tres.", "explanation": "Correct! Use ser for scheduled events and times."}, {"correct": false, "sentence": "El mercado es cerrado los domingos.", "explanation": "Wrong — use estar for states and conditions: El mercado está cerrado los domingos."}]', NULL, NULL, NULL, NULL, NULL, '2026-03-03 14:15:59.915911+00', NULL, NULL, 'es', '{Vocabulario}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('a1b2c3d4-0926-0926-0926-000000000926', 926, 'matching', 'A2', 'spanish', 'Match each Spanish verb to its English meaning.', 'match_all_pairs', '[{"left": {"type": "text", "content": "madrugar"}, "right": {"type": "text", "content": "to get up early"}}, {"left": {"type": "text", "content": "quedarse"}, "right": {"type": "text", "content": "to stay / to remain"}}, {"left": {"type": "text", "content": "llevar"}, "right": {"type": "text", "content": "to carry / to wear"}}, {"left": {"type": "text", "content": "tardar"}, "right": {"type": "text", "content": "to take a long time / to be late"}}, {"left": {"type": "text", "content": "apagar"}, "right": {"type": "text", "content": "to turn off / to switch off"}}]', NULL, NULL, NULL, NULL, NULL, '2026-03-03 19:54:35.474351+00', NULL, NULL, 'es', '{Vocabulario}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('a1b2c3d4-0927-0927-0927-000000000927', 927, 'matching', 'A2', 'spanish', 'Match each Spanish adjective to its opposite.', 'match_all_pairs', '[{"left": {"type": "text", "content": "temprano"}, "right": {"type": "text", "content": "tarde"}}, {"left": {"type": "text", "content": "lleno"}, "right": {"type": "text", "content": "vacío"}}, {"left": {"type": "text", "content": "limpio"}, "right": {"type": "text", "content": "sucio"}}, {"left": {"type": "text", "content": "tranquilo"}, "right": {"type": "text", "content": "ruidoso"}}, {"left": {"type": "text", "content": "seguro"}, "right": {"type": "text", "content": "peligroso"}}]', NULL, NULL, NULL, NULL, NULL, '2026-03-03 19:54:35.474351+00', NULL, NULL, 'es', '{Vocabulario}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('0f3c6463-684d-4e02-8b7c-622227842870', 1902, 'matching', 'A2', 'grammar', 'Match each sentence to the correct tense.', 'match_all_pairs', '[{"left": {"type": "text", "label": "", "content": "She lives here."}, "right": {"type": "text", "label": "", "content": "present simple"}}, {"left": {"type": "text", "label": "", "content": "She lived here in 2010."}, "right": {"type": "text", "label": "", "content": "past simple"}}, {"left": {"type": "text", "label": "", "content": "She is living here now."}, "right": {"type": "text", "label": "", "content": "present continuous"}}, {"left": {"type": "text", "label": "", "content": "She has lived here for years."}, "right": {"type": "text", "label": "", "content": "present perfect"}}]', NULL, NULL, NULL, NULL, NULL, '2026-04-08 18:25:27.713957+00', NULL, NULL, 'en', '{Grammar,Tenses}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('a1b2c3d4-0929-0929-0929-000000000929', 929, 'matching', 'A2', 'spanish', 'Match each Spanish time expression to its English meaning.', 'match_all_pairs', '[{"left": {"type": "text", "content": "a veces"}, "right": {"type": "text", "content": "sometimes"}}, {"left": {"type": "text", "content": "hace poco"}, "right": {"type": "text", "content": "a short time ago"}}, {"left": {"type": "text", "content": "de vez en cuando"}, "right": {"type": "text", "content": "from time to time"}}, {"left": {"type": "text", "content": "enseguida"}, "right": {"type": "text", "content": "straight away / immediately"}}, {"left": {"type": "text", "content": "a partir de ahora"}, "right": {"type": "text", "content": "from now on"}}]', NULL, NULL, NULL, NULL, NULL, '2026-03-03 19:54:35.474351+00', NULL, NULL, 'es', '{Vocabulario}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('a1b2c3d4-0930-0930-0930-000000000930', 930, 'matching', 'A2', 'spanish', 'Match each Spanish phrase to its English meaning.', 'match_all_pairs', '[{"left": {"type": "text", "content": "¿Qué tal?"}, "right": {"type": "text", "content": "How are things? / How are you?"}}, {"left": {"type": "text", "content": "Me da igual."}, "right": {"type": "text", "content": "I don''t mind. / It''s all the same to me."}}, {"left": {"type": "text", "content": "No me apetece."}, "right": {"type": "text", "content": "I don''t feel like it."}}, {"left": {"type": "text", "content": "Está bien."}, "right": {"type": "text", "content": "It''s fine. / OK."}}, {"left": {"type": "text", "content": "¿A qué hora quedamos?"}, "right": {"type": "text", "content": "What time shall we meet?"}}]', NULL, NULL, NULL, NULL, NULL, '2026-03-03 19:54:35.474351+00', NULL, NULL, 'es', '{Vocabulario}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('23babafa-9812-4d6e-a5bd-a62c27eee6ce', 738, 'multiple_choice', 'A1', 'grammar', 'Which word completes the sentence? "I ___ hungry. Can we eat soon?"', 'am', '["am", "is", "are", "be"]', NULL, NULL, NULL, 'I + verb "to be" in present.', 'Use "am" with "I". Remember: I am, you are, he/she/it is. Easy once you know it!', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('c3f6f4e3-a70d-4835-a4c6-6969d6e4d975', 740, 'multiple_choice', 'A1', 'grammar', '"She ___ to school by bus every day."', 'goes', '["go", "goes", "going", "gone"]', NULL, NULL, NULL, 'She + verb — add -s. (Go → goes.)', 'With he/she/it in the present simple, we add -s or -es to the verb. She goes.', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('dadcecae-85d0-4b4d-8e88-041778061344', 124, 'multiple_choice', 'B2', 'phrasal_verbs', 'The meeting has been ___ until next week.', 'put off', '["put on", "put off", "put down", "put up"]', NULL, NULL, NULL, 'To postpone — push the date back.', 'Put off means to postpone.', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{"Phrasal verb"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('d424f9fa-a123-43e3-a867-73d25ca16f4f', 1625, 'gap_fill', 'B2', 'travel', 'The resort was so popular that rooms were _______ months in advance.', 'booked up', NULL, NULL, NULL, NULL, 'Fully reserved — no availability.', '"Booked up" means all available rooms (or seats, places etc.) are reserved. There is no availability left.', '2026-03-27 08:23:03.995534+00', NULL, NULL, 'en', '{}', false, 'Form: passive — "rooms were ___".', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('88d0ef97-75fc-41b7-8e4c-ccbba76d3cfe', 194, 'multiple_choice', 'B2', 'phrasal_verbs_separable', 'I need to ___ this word ___ in the dictionary.', 'look / up', '["look / after", "look / up", "look / for", "look / into"]', NULL, NULL, NULL, 'Separable phrasal verb — the object goes between the two parts.', 'Look up = search for information.', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{"Phrasal verb"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('521aac83-c8bb-4e62-ad73-39f31c30fd15', 503, 'multiple_choice', 'C1', 'advanced_phrasal_verbs', 'The company is trying to ___ costs by reducing staff.', 'cut down on', '["cut up", "cut off", "cut out", "cut down on"]', NULL, NULL, NULL, 'To reduce — like trimming back a bush.', 'Cut down on = reduce the amount of something.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Phrasal verb"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('35587e4d-44d8-463e-a4fa-f99cb3fc215a', 741, 'multiple_choice', 'A1', 'vocabulary', 'Which word means the opposite of "cheap"?', 'expensive', '["expensive", "small", "new", "fast"]', NULL, NULL, NULL, 'High price = the opposite of cheap.', 'Cheap means low price. Expensive means high price. The others describe size, age, and speed.', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('9b0de821-3f61-4484-8a45-583e7b33191f', 742, 'multiple_choice', 'A1', 'social', 'What do you say when you leave someone at the end of the day?', 'Goodbye', '["Good morning", "How are you?", "Goodbye", "Nice to meet you"]', NULL, NULL, NULL, 'A farewell at the end of an encounter.', '"Goodbye" is used when you leave or end a conversation. "Good morning" is a greeting, not a farewell.', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{Vocabulary}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('a0c68e2d-b29e-4b57-8979-4bbfb124a077', 743, 'multiple_choice', 'A1', 'grammar', '"There ___ a lot of people at the market today."', 'are', '["is", "are", "am", "be"]', NULL, NULL, NULL, '"A lot of people" = plural. There + ___?', '"People" is a plural noun, so we use "are". There are many people. There is one person.', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('3da3f215-3ad1-4b66-8141-12aeb97e4159', 744, 'multiple_choice', 'A1', 'home', 'Which of these is a room in a house?', 'All of these', '["balcony", "corridor", "kitchen", "All of these"]', NULL, NULL, NULL, 'Think about whether all of the options are rooms in a typical home.', 'A kitchen is where you cook, a corridor connects rooms, and a balcony is an outdoor platform. All are parts of a home!', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{Vocabulary}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('b7cc2ab4-42cd-4784-8cd4-61b8bd442b55', 745, 'multiple_choice', 'A2', 'grammar', '"We ___ football last Saturday."', 'played', '["play", "plays", "played", "playing"]', NULL, NULL, NULL, '"Last Saturday" — past simple. Play is regular.', '"Last Saturday" tells us this is in the past, so we use the past simple: played.', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('9d150a71-0027-4e0e-85b3-234a3b8faaaa', 746, 'multiple_choice', 'A2', 'health', 'Which word means "a doctor who looks after your teeth"?', 'dentist', '["dentist", "pharmacist", "surgeon", "optician"]', NULL, NULL, NULL, 'From "dent-" (Latin for tooth).', 'A dentist looks after your teeth. An optician checks your eyes, a pharmacist gives you medicine, and a surgeon performs operations.', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{Vocabulary}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('3f423eea-0d4c-44c3-89ed-fcb9ef70f12e', 818, 'odd_one_out', 'C1', 'language/rhetoric', 'Three of these are figures of speech. Which is the odd one out?', 'conjunction', '["metaphor", "simile", "alliteration", "conjunction"]', NULL, NULL, NULL, NULL, 'Metaphor, simile, and alliteration are all literary or rhetorical figures of speech. A conjunction (and, but, because) is a grammatical function word — useful, but not a figure of speech.', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{"Academic English"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('c18ddb51-0cbc-47ee-8a00-892ce523ca48', 824, 'odd_one_out', 'C2', 'academic vocabulary', 'Three of these are philosophical traditions or schools of thought. Which is the odd one out?', 'capitalism', '["empiricism", "rationalism", "utilitarianism", "capitalism"]', NULL, NULL, NULL, NULL, 'Empiricism, rationalism, and utilitarianism are philosophical traditions concerned with knowledge and ethics. Capitalism is primarily an economic and political system — though it intersects with philosophy, it belongs to a different category here.', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{"Academic English"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('f638c126-6af9-4863-99ac-ecee6483e125', 1199, 'sentence_building', 'B2', 'routines', 'La mayoría deseamos poder desarrollar mejores hábitos de sueño.', 'Most of us wish we could develop better sleep habits.', '["most", "of", "us", "wish", "we", "could", "develop", "better", "sleep", "habits", "all", "want", "build", "improve"]', NULL, NULL, NULL, NULL, 'Wish + could expresses a desire about the present that is not currently true. Could is the past form of can used in wish clauses.', '2026-03-16 09:04:17.945706+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('9e6506e1-8e1c-41ed-8bcb-a79fd4949ac6', 1200, 'sentence_building', 'B1', 'routines', 'Me cuesta un rato sentirme completamente despierto por la mañana.', 'It takes me a while to feel fully awake in the morning.', '["it", "takes", "me", "a", "while", "to", "feel", "fully", "awake", "in", "the", "morning", "long", "be", "totally"]', NULL, NULL, NULL, NULL, 'It takes someone a while to do something describes the time needed to reach a state. Fully awake is more natural than totally awake.', '2026-03-16 09:04:17.945706+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('2c100f83-064f-4bd4-b5e8-750d70173455', 1201, 'sentence_building', 'B2', 'routines', 'Mucha gente ha reducido poco a poco la cantidad de café que bebe.', 'Many people have gradually cut down on the amount of coffee they drink.', '["many", "people", "have", "gradually", "cut", "down", "on", "the", "amount", "of", "coffee", "they", "drink", "reduce", "slow", "quantity"]', NULL, NULL, NULL, NULL, 'Cut down on is a phrasal verb meaning to reduce the amount of something. The present perfect shows a change that connects past to present.', '2026-03-16 09:04:17.945706+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('e211ba1f-744a-43d5-92ae-e33f03ebc604', 1202, 'sentence_building', 'B1', 'routines', 'Siempre se me olvida tomar las vitaminas por la mañana.', 'I keep forgetting to take my vitamins in the morning.', '["I", "keep", "forgetting", "to", "take", "my", "vitamins", "in", "the", "morning", "forget", "missed", "always", "remember"]', NULL, NULL, NULL, NULL, 'Keep + gerund describes a repeated action, often one that is frustrating or unintentional. Forgetting to take means repeatedly failing to remember.', '2026-03-16 09:04:17.945706+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('47c8a61c-9cf3-4524-8704-9b367bac048f', 1203, 'sentence_building', 'B2', 'routines', 'Dormir lo suficiente ha marcado una gran diferencia en mi productividad.', 'Getting enough sleep has made a huge difference to my productivity.', '["getting", "enough", "sleep", "has", "made", "a", "huge", "difference", "to", "my", "productivity", "make", "big", "sleeping", "great"]', NULL, NULL, NULL, NULL, 'A gerund (Getting) can be the subject of a sentence. Make a difference to is the correct collocation — not make a difference for.', '2026-03-16 09:04:17.945706+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('17663dea-889f-445c-a1cb-c9ade387608c', 1238, 'multiple_choice', 'B2', 'business_phrasal_verbs', 'The new CEO plans to _____ the entire management structure.', 'shake up', '["shake up", "shake off", "shake down", "shake out"]', NULL, NULL, NULL, 'To reorganise dramatically — disturb the structure.', 'Shake up means to make major changes to an organisation or system. It implies disruption intended to improve things.', '2026-03-18 19:58:52.376507+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('4e8f7951-bc86-42b1-bc9b-26cf7fd3fec6', 747, 'multiple_choice', 'A2', 'grammar', '"How long ___ you been learning English?"', 'have', '["have", "did", "are", "do"]', NULL, NULL, NULL, '"How long ___ you been..." — present perfect continuous question.', '"How long have you been...?" uses the present perfect continuous. It asks about something that started in the past and continues now.', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('150f4c9c-6e3e-4b5d-abb5-a33ee4babf9f', 748, 'multiple_choice', 'A2', 'grammar', 'Which sentence is correct?', 'She is taller than me.', '["She is more tall than me.", "She is taller than me.", "She is tallest than me.", "She is tall than me."]', NULL, NULL, NULL, 'Look for the right comparative form (-er or "more"?) and correct word order.', 'For short adjectives (one syllable), we add -er to compare two things: taller, shorter, cheaper.', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('854422b4-d4c2-41fe-85f0-dd4f1c5d16f6', 749, 'multiple_choice', 'A2', 'grammar', '"I ___ watch TV when I was young, but now I prefer reading."', 'used to', '["used to", "use to", "was used to", "would use to"]', NULL, NULL, NULL, 'Past habit no longer true. Form: "___ to" + base verb.', '"Used to + infinitive" describes habits or states in the past that are no longer true. "I used to watch TV" means I don''t watch much anymore.', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('2ddd5e7b-666e-4b79-926e-931befd19785', 1727, 'multiple_choice', 'A1', 'sport', 'What do you call the exercise where you lift a bar with weights attached to each end?', 'a barbell lift', '["a barbell lift", "a dumbbell curl", "a kettlebell swing", "a cable row"]', NULL, NULL, NULL, 'A long bar held in both hands, with weighted plates loaded on each end.', 'A barbell is the long bar with weights on each end, used in exercises such as squats, bench press, and deadlifts. A dumbbell is a shorter weight held in one hand. A kettlebell is a round weight with a handle used for swinging movements. Weight training with a barbell is one of the most effective ways to build strength.', '2026-03-30 08:52:38.502672+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('314fa5e9-31b5-4dbb-ab56-df3496965c03', 683, 'odd_one_out', 'B2', 'phrasal_verbs', 'Which phrasal verb does NOT mean "to cancel"?', 'carry out', '["call off", "put off", "carry out", "pull out of"]', NULL, NULL, NULL, NULL, '"Carry out" means to complete or execute something, not cancel it.', '2026-02-20 19:09:17.848852+00', NULL, NULL, 'en', '{"Phrasal verb"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('35f6829d-dbcc-439b-9a0a-328ddd607090', 848, 'error_correction', 'C1', 'collocations', 'The findings lend credibility for the hypothesis.', 'The findings lend credibility to the hypothesis.', '[]', NULL, NULL, NULL, NULL, '"Lend credibility to something" is the fixed collocation — not "lend credibility for". Similarly: "lend weight to", "give credibility to". Preposition errors at C1 are often collocation errors.', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{Collocation}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('e15d4a02-63fa-4831-a3de-1e7b31f00339', 750, 'multiple_choice', 'A2', 'vocabulary', 'Which word completes the sentence? "Can you ___ me how to get to the station?"', 'tell', '["say", "tell", "speak", "talk"]', NULL, NULL, NULL, 'When there''s a person ("me"), use this verb. (Compare: "say to me".)', 'We "tell someone something". We "say something". So: "Can you tell me...?" not "Can you say me...?"', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('0302fa0a-8945-4fef-b32b-85382367a7a6', 443, 'gap_fill', 'C1', 'collocations', 'The company needs to ___ measures to reduce pollution.', 'take', NULL, '["introduce", "investigate"]', 'Alternate verb possibilities, investigate sounds as if the measures will not happen any time soon.', NULL, 'A common verb-noun pairing with "measures".', 'Take measures = implement actions to deal with a problem. Common business collocation.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{Collocation}', false, '___ measures, ___ action, ___ steps — same verb works for all.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('744e2c6f-c1cc-41bd-b1e0-f8a96ceb45f4', 664, 'sentence_building', 'C1', 'concessive_clauses', 'Por mucho que lo intente, no consigo entenderlo.', 'no matter how hard I try I cannot seem to understand it', '["no", "matter", "how", "hard", "I", "try", "I", "cannot", "seem", "to", "understand", "it", "can", "trying", "hardly"]', NULL, NULL, '["no matter how hard I try I cannot understand it", "I cannot understand it no matter how hard I try "]', NULL, 'No matter how + adjective/adverb + subject + verb: concessive clause.', '2026-02-17 09:58:54.170896+00', NULL, NULL, 'en', '{"Linking word"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('6730b07e-d3ce-4418-9570-cdd65e010aee', 2222, 'gap_fill', 'B2', 'phrasal_verbs', 'We''ve ___ petrol — we need to stop.', 'run out of', '[]', NULL, NULL, NULL, 'Used all of something so none is left.', '"Run out of" something means to use it all up so none is left.', '2026-06-01 07:29:20.293249+00', NULL, NULL, 'en', '{"Phrasal verb"}', false, 'Three words: "run ___ ___".', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('f102d248-786a-4935-992c-fb03a43538a8', 751, 'multiple_choice', 'A2', 'grammar', '"She hasn''t phoned me ___ three weeks."', 'for', '["since", "for", "ago", "during"]', NULL, NULL, NULL, 'Three weeks is a duration, not a starting point.', 'Use "for" with a period of time (for three weeks, for an hour). Use "since" with a point in time (since Monday, since 2020).', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('339f1888-38a9-4716-813b-73847b0b88e6', 752, 'multiple_choice', 'A2', 'social', 'What does "Can I have the bill, please?" mean in a restaurant?', 'I want to pay.', '["I want to pay.", "I want more food.", "I want a table.", "I want the menu."]', NULL, NULL, NULL, 'Asking for the bill = preparing to settle up.', '"The bill" is the piece of paper showing how much you owe. Asking for it means you are ready to pay.', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{Vocabulary}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('5968c5e0-d61f-40e8-b7ef-58f29d00c632', 1121, 'multiple_choice', 'A1', 'bathroom_vocabulary', 'The thing which water comes out of is called a _______.', 'tap', '["tap", "top", "tip", "trap"]', NULL, NULL, NULL, 'A valve at the end of a pipe — turn to release water.', 'A tap if it is singular, or a mixer, but pluralised if there are two separate ''taps''. They also control the flow of water. ', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Bathroom vocabulary"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('8a92f5b5-0a9e-4143-b054-13b29a74bf7a', 2223, 'gap_fill', 'B2', 'phrasal_verbs', 'He ___ his father — they look identical.', 'takes after', '[]', NULL, NULL, NULL, 'Resembles an older relative.', '"Take after" someone means to resemble an older relative.', '2026-06-01 07:29:20.293249+00', NULL, NULL, 'en', '{"Phrasal verb"}', false, '"take ___" — particle "after".', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('ebe05009-ab79-432f-9a78-d7416f5f92c6', 2224, 'gap_fill', 'B2', 'phrasal_verbs', 'The plane ___ on time despite the storm.', 'took off', '[]', NULL, NULL, NULL, 'Left the ground and rose into the air.', '"Take off" means a plane leaves the ground and rises into the air.', '2026-06-01 07:29:20.293249+00', NULL, NULL, 'en', '{"Phrasal verb"}', false, 'Past tense of "take ___".', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('ea79ba2a-31ee-4f50-b0ca-d443a666a9bb', 1240, 'gap_fill', 'B1', 'business_phrasal_verbs', 'The lawyers need to _____ the contract before we can proceed.', 'draw up', NULL, NULL, NULL, NULL, 'To prepare a formal document.', 'Draw up means to prepare a formal document such as a contract, plan, or list.', '2026-03-18 19:58:52.376507+00', NULL, NULL, 'en', '{}', false, 'Often used with "contract", "plan", "agreement".', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('e4411fd6-5b11-44af-bd0d-fd2ff7713c48', 826, 'odd_one_out', 'C2', 'collocations', 'Three of these can precede the word "reform" as a natural collocation. Which is the odd one out?', 'deliberate', '["sweeping", "radical", "wide-ranging", "deliberate"]', NULL, NULL, NULL, NULL, 'We speak of "sweeping reform", "radical reform", and "wide-ranging reform" — all describe the scope or extent of change. "Deliberate reform" is grammatically possible, but not a standard collocation; it sounds awkward.', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{Collocation}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('8eb8b013-c6c8-4b38-b779-2148740de0d3', 444, 'gap_fill', 'C1', 'collocations', 'She ___ a complaint about the noise.', 'made', NULL, NULL, NULL, NULL, 'A verb-noun pairing with "complaint".', 'Make/file/lodge a complaint = formally report dissatisfaction.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{Collocation}', false, '___ a complaint, ___ a noise, ___ a difference — same verb.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('ab5b66ad-c2ed-40d9-af56-95e6232d2f47', 445, 'gap_fill', 'C1', 'collocations', 'The doctor ___ her a thorough examination.', 'gave', NULL, NULL, NULL, NULL, 'A doctor doesn''t "do" or "make" an examination.', 'Give someone an examination. Also: carry out an examination.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{Collocation}', false, '___ an examination, ___ a presentation, ___ advice — same verb.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('ff9768bd-47c4-4a58-b950-0413925e40f9', 753, 'multiple_choice', 'A2', 'grammar', '"The film ___ two hours ago."', 'started', '["starts", "has started", "started", "is starting"]', NULL, NULL, NULL, '"Two hours ago" — past simple. Start is regular.', '"Two hours ago" is a finished time in the past, so we use the past simple: started.', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('4a1b40c8-8cf1-4cb4-a71d-bb5d3e1fea47', 889, 'multiple_choice', 'A2', 'spanish', 'Which Spanish verb means "to live"?', 'vivir', '["vivir", "volver", "comer", "dormir"]', NULL, NULL, NULL, NULL, '"Vivir" means to live. "Volver" = to return, "comer" = to eat, "dormir" = to sleep.', '2026-03-03 14:10:39.181019+00', NULL, NULL, 'es', '{Vocabulario}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('30afa853-58ed-4749-b13a-05ce00ce4151', 890, 'multiple_choice', 'A2', 'spanish', 'How do you say "I am cold" in Spanish?', 'Tengo frío', '["Tengo frío", "Estoy frío", "Soy frío", "Hace frío"]', NULL, NULL, NULL, NULL, 'In Spanish, use "tener" (to have) for physical sensations: tengo frío, tengo calor, tengo hambre. "Estoy frío" and "soy frío" are incorrect for this meaning. "Hace frío" means it''s cold.', '2026-03-03 14:10:39.181019+00', NULL, NULL, 'es', '{Vocabulario}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('9fdd76fe-fa5b-432c-a2b2-1bd65cb21d09', 754, 'multiple_choice', 'A2', 'money', 'Which of these is NOT a way to pay in a shop?', 'receipt', '["cash", "credit card", "contactless", "receipt"]', NULL, NULL, NULL, 'A receipt is what you get AFTER paying — it''s not how you pay.', 'A receipt is the piece of paper you get AFTER paying — it is not a payment method. Cash, card, and contactless are all ways to pay.', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{Vocabulary}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('e2ba56c8-5c3d-4ade-8cb6-e257b32cf408', 1728, 'multiple_choice', 'A1', 'sport', 'What do you call the slow run at the beginning of a training session to prepare?', 'a warm-up', '["a warm-up", "a sprint", "a tempo run", "a cool-down"]', NULL, NULL, NULL, 'Getting your body ready by gently raising your temperature before training.', 'A warm-up is a slow, easy run at the start of a session to prepare the body for more intense exercise. A cool-down walk or jog at the end helps the body recover. Skipping the warm-up increases the risk of injury, especially in high-intensity activities like crossfit or running.', '2026-03-30 08:52:38.502672+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('4bb929e1-cbb7-4b58-876b-6e1431717462', 1729, 'multiple_choice', 'A1', 'sport', 'In yoga, what do you call the resting pose where you lie flat on your back at the end of a session?', 'savasana', '["savasana", "downward dog", "child''s pose", "warrior"]', NULL, NULL, NULL, 'Sanskrit for "corpse pose" — the final relaxation, lying still on your back.', 'Savasana (corpse pose) is the final resting pose in a yoga class, where students lie still and allow the body and mind to absorb the benefits of the practice. Downward dog and warrior are active poses. Child''s pose is a resting pose done face down. Learning basic yoga pose names in English is very useful for attending international classes.', '2026-03-30 08:52:38.502672+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('33cd034b-39a8-4368-9445-6bf2de3d98b0', 1730, 'multiple_choice', 'A2', 'sport', 'What is the main difference between padel and tennis?', 'padel is played in a court with walls', '["padel is played in a court with walls", "padel uses a heavier ball", "padel has no net", "padel is played with four players only"]', NULL, NULL, NULL, 'Padel courts are enclosed — the ball can be played off the back of the court.', 'Padel is played in an enclosed glass and metal court where the walls are in play — like squash, but with tennis-style scoring. The racket is solid with no strings. It is almost always played in doubles. Padel originated in Mexico and is now one of the fastest-growing sports in the world, particularly in Spain.', '2026-03-30 08:52:38.502672+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('72298fa5-fcfa-47c8-ae69-51c335eb8bd1', 1731, 'multiple_choice', 'A2', 'sport', 'What does it mean to do a "personal best" (PB) in running?', 'to run a distance faster than you have ever run it before', '["to run a distance faster than you have ever run it before", "to finish a race in first place", "to run your longest distance ever", "to complete a race without stopping"]', NULL, NULL, NULL, 'PB stands for "personal best" — your own fastest time, no one else''s.', 'A personal best (PB) — or personal record (PR) in American English — is the fastest time you have ever run a particular distance. Runners track PBs for distances like 5km, 10km, half marathon, and marathon. Getting a PB is one of the most motivating achievements in recreational running.', '2026-03-30 08:52:38.502672+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('ea319c86-0a1c-498f-9092-72ce10576792', 2225, 'multiple_choice', 'B2', 'phrasal_verbs', 'The deal fell ___ at the last minute.', 'through', '["through", "off", "down", "out"]', NULL, NULL, NULL, '"fall ___" = fail to happen.', '"Fall through" means a plan or deal fails to happen.', '2026-06-01 07:29:20.293249+00', NULL, NULL, 'en', '{"Phrasal verb"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('7c12e740-d676-4fa0-9d08-3135321022a9', 1733, 'multiple_choice', 'A2', 'sport', 'What is the purpose of "stretching" after a workout?', 'to help the muscles recover and reduce stiffness', '["to help the muscles recover and reduce stiffness", "to build muscle strength", "to burn more calories", "to warm the body up"]', NULL, NULL, NULL, 'After a workout, gentle pulls help muscles return to their normal length.', 'Stretching after exercise — known as a cool-down or post-workout stretch — helps reduce muscle tension and stiffness, improves flexibility over time, and aids recovery. It is different from a warm-up, which is done before exercise to prepare the body. Both are important parts of a well-structured training session.', '2026-03-30 08:52:38.502672+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('b5e6c980-b3fa-4018-9d99-83fcaf03891d', 1734, 'multiple_choice', 'A2', 'sport', 'In CrossFit, what does "WOD" stand for?', 'Workout of the Day', '["Workout of the Day", "Weight or Distance", "Warm-up or Drill", "Winner of Division"]', NULL, NULL, NULL, 'WOD is the daily challenge that defines a CrossFit class.', 'WOD stands for Workout of the Day — the specific training session prescribed for that day in a CrossFit class. CrossFit uses a lot of specific terminology: AMRAP (as many rounds as possible), EMOM (every minute on the minute), and Rx (as prescribed — completing the workout at the standard weight). Learning this vocabulary helps in international CrossFit gyms.', '2026-03-30 08:52:38.502672+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('1fdfb436-3c68-44c6-970f-f8e7f5331cd1', 1251, 'gap_fill', 'C1', 'business_phrasal_verbs', 'She _____ an impressive performance in the boardroom despite the hostile questioning.', 'pulled off', NULL, NULL, NULL, NULL, 'To achieve something difficult — succeed against the odds.', 'Pull off means to succeed in doing something difficult or unexpected. Compare: bring off, carry off.', '2026-03-18 19:58:52.376507+00', NULL, NULL, 'en', '{}', false, 'Often paired with "deal", "stunt", "performance".', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('c63f13d3-5f16-4e09-9948-f9b9bd1d97ec', 2226, 'multiple_choice', 'B2', 'phrasal_verbs', 'I came ___ an old photo while tidying up.', 'across', '["across", "over", "round", "by"]', NULL, NULL, NULL, '"come ___" = find by chance.', '"Come across" something means to find it by chance.', '2026-06-01 07:29:20.293249+00', NULL, NULL, 'en', '{"Phrasal verb"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('02228da9-5d15-42a9-8c4f-1d9440613bb0', 2227, 'multiple_choice', 'B2', 'phrasal_verbs', 'She''s really looking ___ to the holiday.', 'forward', '["forward", "up", "out", "after"]', NULL, NULL, NULL, '"look ___ to" = anticipate happily.', '"Look forward to" something means to anticipate it happily.', '2026-06-01 07:29:20.293249+00', NULL, NULL, 'en', '{"Phrasal verb"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('4c132a1b-5324-4aa1-8baf-df56f39048e8', 2228, 'multiple_choice', 'B2', 'phrasal_verbs', 'We had to put ___ with the noise all night.', 'up', '["up", "off", "out", "on"]', NULL, NULL, NULL, '"put ___ with" = tolerate.', '"Put up with" something means to tolerate it.', '2026-06-01 07:29:20.293249+00', NULL, NULL, 'en', '{"Phrasal verb"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('09eb4a1b-1957-4b36-a0aa-adb82123d43a', 2229, 'multiple_choice', 'B2', 'phrasal_verbs', 'The company was taken ___ by a rival.', 'over', '["over", "off", "up", "in"]', NULL, NULL, NULL, '"take ___" = gain control of a business.', '"Take over" a company means to gain control of it.', '2026-06-01 07:29:20.293249+00', NULL, NULL, 'en', '{"Phrasal verb"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('3fe83116-101a-4c34-9327-83ba027e3868', 2230, 'gap_fill', 'C1', 'phrasal_verbs', 'The negotiations ___ after both sides refused to budge.', 'broke down', '[]', NULL, NULL, NULL, 'Collapsed; stopped working.', '"Break down" means to collapse or stop working.', '2026-06-01 07:29:20.293249+00', NULL, NULL, 'en', '{"Phrasal verb"}', false, 'Past tense of "break ___".', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('54ba30af-f9cf-409a-a99a-f1804c3894ae', 909, 'sentence_auction', 'A2', 'spanish', 'Theme: Gustar and Similar Verbs', 'auction', '[{"correct": true, "sentence": "Me gustan las películas de acción.", "explanation": "Correct! Gustan agrees with the plural noun las películas."}, {"correct": false, "sentence": "Me gusta los libros de historia.", "explanation": "Wrong — los libros is plural so use gustan: Me gustan los libros de historia."}, {"correct": true, "sentence": "A mi hermana le encanta el chocolate.", "explanation": "Correct! Encantar works like gustar — it agrees with el chocolate (singular)."}, {"correct": false, "sentence": "Nos gustan mucho la música.", "explanation": "Wrong — la música is singular so use gusta: Nos gusta mucho la música."}, {"correct": true, "sentence": "¿Te apetece un café?", "explanation": "Correct! Apetecer works like gustar. Un café is singular so use apetece."}, {"correct": false, "sentence": "A ellos les gusta los deportes.", "explanation": "Wrong — los deportes is plural so use gustan: A ellos les gustan los deportes."}]', NULL, NULL, NULL, NULL, NULL, '2026-03-03 14:15:59.915911+00', NULL, NULL, 'es', '{Vocabulario}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('6b2e9d58-ac8c-4c90-91b0-7ead2dad54d4', 2231, 'gap_fill', 'C1', 'phrasal_verbs', 'She managed to ___ a difficult childhood.', 'get over', '[]', NULL, NULL, NULL, 'Recover from something hard.', '"Get over" something means to recover from a difficult experience.', '2026-06-01 07:29:20.293249+00', NULL, NULL, 'en', '{"Phrasal verb"}', false, '"get ___" — particle "over".', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('aa35fb32-2c9d-4b4b-825a-fa6ebee4cab1', 708, 'odd_one_out', 'B1', 'collocations', 'Which does NOT collocate with "make"?', 'homework', '["a decision", "a mistake", "homework", "progress"]', NULL, NULL, NULL, NULL, 'We say "do homework", not "make homework".', '2026-02-20 19:09:17.848852+00', NULL, NULL, 'en', '{Collocation}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('59f9778a-1b2c-4252-a986-986e61ab99c7', 201, 'gap_fill', 'A1', 'present_simple', 'She ___ (live) in Madrid.', 'lives', NULL, NULL, NULL, NULL, 'She/he/it adds -s in present simple.', 'Third person singular: add -s to the verb.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Present tense"}', false, 'He works, she lives, it rains.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('94bfbd4d-4d8a-4e27-b681-55c0e640fd63', 839, 'error_correction', 'B1', 'collocations', 'He insisted in paying for dinner.', 'He insisted on paying for dinner.', '[]', NULL, NULL, NULL, NULL, '"Insist on + ing" is the correct pattern: "He insisted on paying." "Insist in" is not correct in English — common error for Spanish speakers as "insistir en" exists in Spanish!', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{Collocation}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('1e878f55-bd11-4601-8038-a1dd73e49e66', 755, 'multiple_choice', 'A2', 'grammar', '"You ___ take an umbrella — it might rain later."', 'should', '["should", "must", "can", "will"]', NULL, NULL, NULL, 'Soft advice for a probable rain situation.', '"Should" gives friendly advice. "Must" is stronger (a rule or obligation). Here we are just suggesting — take an umbrella!', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('146e8950-78dd-4cbd-975f-885857e188f3', 756, 'multiple_choice', 'A2', 'travel', 'Which word means "a trip you take for pleasure, usually abroad"?', 'holiday', '["errand", "journey", "holiday", "commute"]', NULL, NULL, NULL, 'A trip away from your normal life — rest and pleasure.', 'A holiday is time off for rest and enjoyment. A commute is your daily travel to work. A journey is the act of travelling. An errand is a short task.', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{Vocabulary}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('52d00ce8-ee78-438a-b163-40340cf14f24', 758, 'multiple_choice', 'B2', 'grammar', '"By the time she arrived at the station, the train ___."', 'had left', '["left", "has left", "had left", "was leaving"]', NULL, NULL, NULL, 'One past action happened before another. Form: had + past participle.', 'When one past action happens before another, the earlier action uses the past perfect (had + past participle). The train left first, then she arrived.', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('5bf12df6-e56c-41f0-af23-bd6200bf7712', 759, 'multiple_choice', 'B1', 'grammar', '"I wish I ___ a foreign language when I was at school."', 'had studied', '["study", "studied", "had studied", "would study"]', NULL, NULL, NULL, 'Past regret. Form: wish + had + past participle.', '"I wish + past perfect" expresses regret about the past — something we didn''t do but wish we had. School was a long time ago!', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('7c2daee1-6154-4e35-963b-86befb122726', 760, 'multiple_choice', 'B1', 'phrasal verbs', 'Which phrasal verb means "to cancel something that was planned"?', 'call off', '["call off", "call out", "call up", "call on"]', NULL, NULL, NULL, 'Phrasal verb meaning to cancel — like calling off a search.', '"Call off" means to cancel. "Call up" means to phone. "Call on" means to visit or ask someone. "Call out" means to shout or to challenge.', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{"Phrasal verb"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('df1b39c5-1de2-4bf6-b84e-234bfbfe44d2', 761, 'multiple_choice', 'B1', 'grammar', '"The new hospital ___ by the end of next year."', 'will be built', '["will build", "will be built", "is building", "builds"]', NULL, NULL, NULL, 'The hospital won''t build itself. Future passive: will be + past participle.', 'The hospital doesn''t build itself — it is built by someone. We need the passive: will be built.', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('d17a58b5-aca8-400b-afad-280637fcdff7', 762, 'multiple_choice', 'B1', 'grammar', '"Despite ___ for the interview, he didn''t get the job."', 'preparing', '["to prepare", "prepare", "prepared", "preparing"]', NULL, NULL, NULL, 'After "despite", use the -ing form (or a noun).', '"Despite" is always followed by a noun or gerund (-ing form). "Despite preparing" / "Despite his preparation" — never "despite to prepare".', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('3b9a1e2e-b189-45d2-8d21-af473f1529a3', 764, 'multiple_choice', 'B2', 'vocabulary', '"She is ___ to get the promotion — she seems far more qualified the other candidates."', 'bound', '["bound", "supposed", "probably", "due"]', NULL, NULL, NULL, 'Sure to happen — "she''s ___ to win".', '"Bound to" expresses strong certainty about the future — almost certain to happen. "Due to" suggests imminent timing, not certainty.', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('c18341f0-d84e-4937-a451-f6ca29c42655', 1140, 'gap_fill', 'C2', 'bathroom_vocabulary', 'A finish that makes tiles appear worn and aged rather than new is called a _______ finish.', 'distressed', NULL, NULL, NULL, '["aged", "antique"]', 'Made to look worn and aged on purpose.', 'A distressed finish is created by tumbling, sandblasting, or acid-treating tiles to give them a worn, weathered appearance. It is popular in rustic, industrial, and vintage-style interiors.', '2026-03-11 18:12:09.553883+00', NULL, NULL, 'en', '{}', false, 'Like "___ leather" or "___ jeans".', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('6d9a2d95-7d85-4cd4-88b5-1f47c4597499', 2232, 'gap_fill', 'C1', 'phrasal_verbs', 'We need to ___ exactly what went wrong.', 'pin down', '[]', NULL, NULL, NULL, 'Identify or define something precisely.', '"Pin down" means to identify or define something precisely.', '2026-06-01 07:29:20.293249+00', NULL, NULL, 'en', '{"Phrasal verb"}', false, '"pin ___" — particle "down".', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('4af11445-80f7-443d-83f0-ea695b1ad8c9', 2233, 'gap_fill', 'C1', 'phrasal_verbs', 'He ___ the offer without a second thought.', 'turned down', '[]', NULL, NULL, NULL, 'Rejected or refused it.', '"Turn down" an offer means to reject or refuse it.', '2026-06-01 07:29:20.293249+00', NULL, NULL, 'en', '{"Phrasal verb"}', false, 'Past tense of "turn ___".', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('732be982-c924-44c0-926d-15e677802575', 352, 'multiple_choice', 'A1', 'food_and_drink', 'I''d like a ___ of coffee.', 'cup', '["glass", "plate", "cup", "bottle"]', NULL, NULL, NULL, 'A small container for hot drinks — has a handle.', 'A cup of coffee / a cup of tea.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{Vocabulary}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('488b3b32-c3ef-4847-85a1-b3ad92b63ddb', 622, 'sentence_building', 'A2', 'present_simple', 'Ella trabaja en un hospital.', 'she works in a hospital', '["she", "works", "in", "a", "hospital", "is", "one", "work"]', NULL, NULL, NULL, NULL, 'In present simple, we add -s to the verb for he/she/it. ''She works'' not ''she work''. In English we normally use ''a/an'' not ''one'' in situations like these. ', '2026-02-13 08:00:10.850224+00', NULL, NULL, 'en', '{"Present tense"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('8cad6ac2-5c72-46ff-8b60-52c51f6b47ba', 765, 'multiple_choice', 'B1', 'grammar', 'Which reported speech sentence is correct? He said: "I will call you tomorrow."', 'He said he would call me the next day.', '["He said he will call me tomorrow.", "He said he would call me the next day.", "He said he calls me the next day.", "He said he had called me tomorrow."]', NULL, NULL, NULL, 'Backshift: will → would. And "tomorrow" → "the next day" in reported speech.', 'In reported speech: "will" becomes "would", and "tomorrow" becomes "the next day" (since time shifts when we report later).', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('1d5530dc-18d2-4b52-b5d6-7967f665c535', 766, 'multiple_choice', 'B1', 'vocabulary', '"He spoke so quietly that I could ___ hear him."', 'barely', '["barely", "nearly", "slightly", "mostly"]', NULL, NULL, NULL, 'Almost not — only just able to hear him.', '"Barely" means almost not at all. "I could barely hear him" = I could hear him, but only just. Don''t confuse it with "nearly" (almost).', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('da817ce9-85a4-41dc-bc3a-fcec490372b6', 767, 'multiple_choice', 'B1', 'grammar', '"If I ___ you, I would apologise immediately."', 'were', '["am", "was", "were", "had been"]', NULL, NULL, NULL, 'Hypothetical — second conditional uses "were" for all persons.', 'In the second conditional, we use "were" for all persons in formal English: "If I were you...", "If he were here...". Some speakers use "was" informally, but "were" is correct.', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('d702b99c-e229-45ac-805c-0de668b47ef3', 770, 'multiple_choice', 'B1', 'academic writing', 'Which linking word shows contrast?', 'nevertheless', '["therefore", "consequently", "nevertheless", "furthermore"]', NULL, NULL, NULL, 'Formal contrast — like "however" or "still".', '"Nevertheless" means "despite this" or "even so" — it shows contrast. "Therefore" and "consequently" show result. "Furthermore" adds information.', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{"Academic English"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('1c94e112-fdae-4e9c-afba-70309248abed', 771, 'multiple_choice', 'B2', 'grammar', '"You ___ told me earlier — I could have helped you!"', 'should have', '["should have", "must have", "would", "could"]', NULL, NULL, NULL, 'Past regret — you didn''t tell me, but you ought to have.', '"Should have + past participle" expresses criticism or regret about a past action. You had the opportunity to tell me, but you didn''t — and you should have.', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('16a76d82-b869-49b6-b7bd-49a9611955ea', 772, 'multiple_choice', 'B2', 'grammar', '"The higher the temperature, ___ the bacteria grow."', 'the faster', '["the faster", "faster", "the fast", "more faster"]', NULL, NULL, NULL, '"The X-er, the Y-er" — proportional change pattern.', '"The + comparative, the + comparative" is a fixed structure showing that two things increase or change together. The hotter it gets, the more you sweat!', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('66df07b6-da3a-4726-8c62-ee57ad43377b', 773, 'multiple_choice', 'B1', 'vocabulary', 'Which word is a synonym for "reluctant"?', 'unwilling', '["unwilling", "unable", "unaware", "unusual"]', NULL, NULL, NULL, 'Not wanting to do something.', '"Reluctant" means not wanting to do something. A synonym is "unwilling". "Unable" means lacking the ability, not the desire.', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('94e96897-2b74-44ce-aeff-28217d5a9147', 774, 'multiple_choice', 'B2', 'collocations', '"The new policy has been met ___ considerable opposition."', 'with', '["with", "by", "from", "of"]', NULL, NULL, NULL, '"Met ___ opposition" — same preposition as "met ___ resistance".', '"Met with" is a fixed expression meaning "received" or "encountered". The policy was met with opposition = it received opposition.', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{Collocation}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('f81b2532-d755-4d5c-87fa-1cc185689118', 775, 'multiple_choice', 'B2', 'money', 'Which word means "the money left after all costs have been paid"?', 'profit', '["profit", "revenue", "turnover", "budget"]', NULL, NULL, NULL, 'What''s left after expenses are paid.', '"Profit" = income minus costs. "Revenue" = total income before costs. "Turnover" = total sales (similar to revenue). "Budget" = a plan for spending money.', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{Vocabulary}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('91784d39-3c29-47ac-932e-62cded490d47', 776, 'multiple_choice', 'B1', 'collocations', '"I am not ___ this change — I think it will cause more problems than it solves."', 'in favour of', '["in favour of", "in support to", "for favour of", "in the favour of"]', NULL, NULL, NULL, 'Phrase: "___ favour of" = supporting.', '"In favour of" is the correct fixed expression meaning "supporting something". British English spells it "favour"; American English spells it "favor".', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{Collocation}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('61f900f2-5431-4b0a-b49d-c7c9d981e641', 779, 'multiple_choice', 'C1', 'grammar', '"It is high time the government ___ decisive action on housing costs."', 'took', '["takes", "take", "took", "has taken"]', NULL, NULL, NULL, '"It''s high time" is followed by past simple, even for present meaning.', '"It is high time + past simple subjunctive" expresses that something should already have happened. The past form does not refer to the past — it refers to the present urgency.', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('e28bcf2d-7505-43a9-b4ba-c488a97f5169', 720, 'odd_one_out', 'B2', 'synonyms', 'Which word is NOT a synonym for "big"?', 'moderate', '["vast", "enormous", "moderate", "immense"]', NULL, NULL, NULL, NULL, '"Moderate" means medium or average, the opposite of big.', '2026-02-20 19:09:17.848852+00', NULL, NULL, 'en', '{"Confusable words"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('f2595671-f2f4-4bf9-944b-4ec23b46d7b0', 723, 'error_correction', 'B2', 'uncountable_nouns', 'The informations you gave me was very useful.', 'The information you gave me was very useful.', '[]', NULL, NULL, NULL, NULL, '"Information" is uncountable — no plural "s".', '2026-02-20 19:09:17.848852+00', NULL, NULL, 'en', '{"Uncountable noun"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('76d0f589-1ecf-4908-9379-116a662152e1', 126, 'multiple_choice', 'B1', 'countable_uncountable', 'Could I have ___ information about the course?', 'some', '["an", "some", "a", "many"]', NULL, NULL, NULL, '"Information" is uncountable. (You''d never say "an information".)', 'Some with uncountable nouns in requests.', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{"Uncountable noun"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('d3685bff-2700-4873-8905-2b95860fe0f4', 175, 'multiple_choice', 'B1', 'countable_a_an', 'She''s ___ engineer.', 'an', '["a", "an", "the", "-"]', NULL, NULL, NULL, '"Engineer" starts with a vowel sound.', 'An before vowel sounds.', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{"Uncountable noun"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('aaf582a6-007e-4b27-a071-a83af2728a91', 266, 'gap_fill', 'A1', 'prepositions_of_place', 'He is ___ home.', 'at', NULL, NULL, NULL, NULL, 'Specific location — at home.', 'Use at with home: at home (not in home).', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Preposition of place"}', false, '___ home, ___ work, ___ school.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('a3911dfe-1576-487f-afc4-10859d5db15d', 560, 'multiple_choice', 'C1', 'confusing_words', 'The ___ between the two reports is striking.', 'disparity', '["dispute", "disparity", "display", "dispatch"]', NULL, NULL, NULL, 'A noticeable, often unfair, difference.', 'Disparity = a great difference, inequality.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Confusable words"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('349991fb-3866-4742-830a-589cdd638bb0', 581, 'multiple_choice', 'C1', 'nuance', 'I ___ to inform you that your application has been unsuccessful.', 'regret', '["apologise", "regret", "am afraid", "sorry"]', NULL, NULL, NULL, 'Formal phrase to deliver bad news.', 'I regret to inform you = very formal way of delivering bad news.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Confusable words"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('cd58f689-5c0b-4ccf-a090-adf7f3a75981', 583, 'multiple_choice', 'C2', 'nuance', 'His remarks were ___ inappropriate for such a formal occasion.', 'wholly', '["solely", "wholly", "holy", "lonely"]', NULL, NULL, NULL, 'Completely — formal alternative to "totally".', 'Wholly = completely, entirely. Formal emphasis.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Confusable words"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('4d668676-b713-47de-9e6b-f7c44123d1d0', 588, 'multiple_choice', 'C1', 'nuance', 'The scheme was abandoned ___ to a lack of funding.', 'due', '["since", "due", "owe", "because"]', NULL, NULL, NULL, '"Abandoned ___ to" = because of.', 'Due to = because of. Slightly more formal than because of.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Confusable words"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('2aebb3e6-3622-428f-a69c-ac4a0b0f467d', 780, 'multiple_choice', 'C2', 'grammar', '"Hardly ___ sat down when the phone rang."', 'had I', '["I had", "had I", "I have", "have I"]', NULL, NULL, NULL, 'Inversion after fronted "Hardly" — auxiliary + subject.', 'When "hardly" begins a sentence, subject and auxiliary invert: "Hardly had I sat down..." This inversion gives the sentence a formal, literary feel.', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('849b1a14-8ac0-448e-96e0-f2b413b7f7d9', 782, 'multiple_choice', 'C2', 'grammar', '"Not until the final results were published ___ the true extent of the crisis."', 'did we realise', '["we realised", "did we realise", "we did realise", "had we realised"]', NULL, NULL, NULL, 'Inversion after fronted "Not until" — auxiliary + subject + verb.', 'When a negative adverbial (Not until, Never, Rarely) starts a sentence, auxiliary and subject must invert: "Not until X did we realise..." This is a key C2 feature.', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('8c04bf69-ae27-4b02-874f-84a3a31f3058', 1735, 'multiple_choice', 'A2', 'sport', 'What is the difference between freestyle and breaststroke in swimming?', 'freestyle allows any stroke', '["freestyle allows any stroke", "freestyle uses only the legs", "breaststroke uses only the arms", "freestyle must be swum on your back"]', NULL, NULL, NULL, 'Freestyle literally means "free choice of stroke" — most swimmers choose front crawl.', 'Freestyle technically allows any stroke, but in competition it almost always refers to front crawl — the fastest stroke. Breaststroke uses a simultaneous pull-and-kick movement and is generally the slowest competitive stroke. The four main competitive strokes are freestyle, breaststroke, backstroke, and butterfly.', '2026-03-30 08:52:38.502672+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('d371b21c-0593-44a0-8d9c-a3a5959dc2cf', 2234, 'gap_fill', 'C1', 'phrasal_verbs', 'The scheme was ___ due to lack of funding.', 'wound up', '[]', NULL, NULL, NULL, 'Brought to an end; closed down.', '"Wind up" means to bring something to an end or close it down.', '2026-06-01 07:29:20.293249+00', NULL, NULL, 'en', '{"Phrasal verb"}', false, 'Past tense of "wind ___".', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('7289c778-ef73-45a3-8bb6-43bea242160a', 1737, 'multiple_choice', 'B1', 'sport', 'What is the difference between aerobic and anaerobic exercise?', 'aerobic uses oxygen to produce energy over a longer period; anaerobic produces energy in short bursts without oxygen', '["aerobic uses oxygen to produce energy over a longer period; anaerobic produces energy in short bursts without oxygen", "aerobic is done outdoors; anaerobic is done indoors", "aerobic builds muscle; anaerobic burns fat", "aerobic uses weights; anaerobic uses bodyweight"]', NULL, NULL, NULL, 'Aerobic literally means "with oxygen"; anaerobic means "without oxygen".', 'Aerobic exercise (running, swimming, cycling) uses oxygen to sustain effort over time and is associated with cardiovascular fitness. Anaerobic exercise (sprinting, weightlifting, crossfit) produces energy rapidly without oxygen and builds strength and power. Most sports combine both types. The word aerobic comes from the Greek for air.', '2026-03-30 08:52:38.502672+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('c1999f91-72f9-4347-85a4-4cabc16a6518', 1738, 'multiple_choice', 'B1', 'sport', 'What does it mean to "plateau" in training?', 'to stop making progress despite continuing to train', '["to stop making progress despite continuing to train", "to reach your personal best", "to overtrain and get injured", "to complete a training block successfully"]', NULL, NULL, NULL, 'From the French — a flat area. In training, a level patch where progress flattens out.', 'A plateau is a period where performance or fitness stops improving despite consistent training. It is very common in weightlifting, running, and yoga. To break through a plateau, athletes typically change their training stimulus — increasing intensity, varying the exercises, or adding rest. The word comes from the French for flat elevated land.', '2026-03-30 08:52:38.502672+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('0f9e7075-e47e-420e-a39d-ab1c6adffe93', 783, 'multiple_choice', 'C2', 'grammar', '"___ it not for the team''s resilience, the project would have collapsed entirely."', 'Were', '["Were", "Had", "Should", "Did"]', NULL, NULL, NULL, 'Inversion replacing "If it were not for" — formal style.', '"Were it not for..." is an inverted conditional equivalent to "If it were not for...". It is formal and commonly found in written English.', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('8f3463b3-d249-4596-819e-a1f794b8b356', 2235, 'gap_fill', 'C1', 'phrasal_verbs', 'I won''t ___ this kind of behaviour any longer.', 'put up with', '[]', NULL, NULL, NULL, 'Tolerate something unpleasant.', '"Put up with" something means to tolerate something unpleasant.', '2026-06-01 07:29:20.293249+00', NULL, NULL, 'en', '{"Phrasal verb"}', false, 'Three words: "put ___ ___".', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('c6d27f2b-eb43-4d03-acef-396fcdde7343', 784, 'multiple_choice', 'C1', 'vocabulary', '"The CEO ___ in her speech that redundancies were likely, without ever using the word."', 'implied', '["implied", "inferred", "suggested", "insinuated"]', NULL, NULL, NULL, 'To suggest indirectly, without stating openly.', '"Imply" = to suggest something without saying it directly (speakers imply). "Infer" = to draw a conclusion from evidence (listeners infer). A classic mix-up — even at C2!', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('ae270178-a7be-45f1-8b56-02890d66bdbd', 785, 'multiple_choice', 'C2', 'vocabulary', '"The author''s later work is characterised by a ___ economy of line and colour."', 'studied', '["studied", "deliberate", "careful", "conscious"]', NULL, NULL, NULL, 'Deliberate, considered — chosen with care. (Not the past tense of "study".)', '"Studied" as an adjective means "deliberately considered and refined" — a sophisticated collocation used in art and literary criticism.', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('e72e74bc-18f9-42eb-8445-0cc9d031519a', 786, 'multiple_choice', 'C1', 'vocabulary', '"The report ___ to several systemic failures that had been ignored for years."', 'alluded', '["alluded", "referred", "pointed", "indicated"]', NULL, NULL, NULL, 'Referred to indirectly — sharing a root with "allusion".', '"Allude to" means to refer to something indirectly. "Refer to" is direct and explicit. The distinction matters: the report suggested the failures without stating them plainly.', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('f1ddfdc6-2061-4ac3-b8f0-aa8e89194b09', 118, 'multiple_choice', 'B1', 'prepositions_time', 'The meeting is ___ Tuesday morning.', 'on', '["at", "on", "in", "by"]', NULL, NULL, NULL, 'Days of the week take a particular preposition: ___ Monday, ___ Tuesday.', 'On for days of the week.', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{"Preposition of time"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('8534e842-fe3d-47b2-9f69-ee9dee04f271', 119, 'multiple_choice', 'B1', 'prepositions_time', 'I usually go swimming ___ the weekend.', 'at', '["by", "on", "in", "at"]', NULL, NULL, NULL, '"The weekend" takes its own preposition — different from morning/afternoon/evening.', 'At the weekend (British English) or on the weekend (American English).', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{"Preposition of time"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('0b97bb3e-99e2-4f7c-a17b-01aadc460cb5', 137, 'multiple_choice', 'B1', 'prepositions_place', 'The post office is ___ the bank and the supermarket.', 'between', '["in", "among", "at", "between"]', NULL, NULL, NULL, 'Two things on either side — the bank on one side, the supermarket on the other.', 'Between for two things.', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{"Preposition of place"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('a457037b-b24c-4e24-8a5c-909208b347ee', 255, 'gap_fill', 'A1', 'prepositions_of_time', 'The class starts ___ 9 am.', 'at', NULL, NULL, NULL, NULL, 'Clock times take a particular preposition.', 'Use at with specific times.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Preposition of time"}', false, '___ 9, ___ 12, ___ 3 pm.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('f4e392d6-016d-4251-983a-cc4125d3e7b0', 256, 'gap_fill', 'A2', 'prepositions_of_time', 'We have a meeting ___ Friday morning.', 'on', NULL, NULL, NULL, NULL, 'Days of the week take a particular preposition (even with "morning").', 'Use on with specific days, even with morning/afternoon.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Preposition of time"}', false, '___ Friday morning. (Different from "in the morning"!)', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('72f8a632-a3da-4ac3-bdcc-6ccd6389e5fb', 787, 'multiple_choice', 'C1', 'formal/legal vocabulary', '"The treaty was ___ by both parliaments after a lengthy ratification process."', 'ratified', '["ratified", "validated", "endorsed", "approved"]', NULL, NULL, NULL, 'Formally approved by a parliament or other authority.', '"Ratify" specifically means to formally approve an agreement at the highest level (parliament, government). It is the precise legal term here.', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{"Formal register"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('2e798b78-d217-440c-9e7e-e31584e8e2f5', 663, 'sentence_building', 'C1', 'complex_sentences', '', 'the project is unlikely to be completed on time unless additional funding is approved', '["the", "project", "is", "unlikely", "to", "be", "completed", "on", "time", "unless", "additional", "funding", "is", "approved", "will", "complete", "probable"]', '["unless additional funding is approved the project is unlikely to be completed on time."]', NULL, NULL, NULL, 'Complex sentence combining "unlikely to be" (passive probability) with "unless" (conditional).', '2026-02-17 09:58:54.170896+00', NULL, NULL, 'en', '{"Linking word"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('4d5f394d-716c-436a-9d8f-bf926587a8d8', 1138, 'gap_fill', 'C1', 'bathroom_vocabulary', 'When a product is no longer manufactured and cannot be reordered, we say it has been _______.', 'discontinued', NULL, NULL, NULL, NULL, 'No longer manufactured — out of production.', 'A discontinued product has been taken out of production by the manufacturer. It is important to inform customers early if a tile is being discontinued so they can order extra stock for future repairs or extensions.', '2026-03-11 18:12:09.553883+00', NULL, NULL, 'en', '{}', false, 'Dis- (not) + continue = stopped continuing.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('a9793213-2ff3-4dc8-a537-81063fb6bc3f', 610, 'sentence_building', 'C1', 'concessive_clauses', 'A pesar de las dificultades, conseguimos terminar a tiempo.', 'despite the difficulties we managed to finish on time', '["despite", "the", "difficulties", "we", "managed", "to", "finish", "on", "time", "although", "succeeded", "at"]', NULL, NULL, NULL, NULL, '"Despite" + noun (no "of"). "Managed to" = conseguir (implies effort and success). "On time" = a tiempo.', '2026-02-12 15:08:31.507807+00', NULL, NULL, 'en', '{"Linking word"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('f4a8977b-8eb7-4b71-94d0-153275e30bdf', 661, 'sentence_building', 'C1', 'inversion', '', 'had I known about the delay I would have taken a different route', '["had", "I", "known", "about", "the", "delay", "I", "would", "have", "taken", "a", "different", "route", "did", "took", "taking"]', '["I would have taken a different route had I known about the delay.", "I would have taken a different route had I known about the delay ."]', NULL, NULL, NULL, 'Inverted third conditional: Had + subject + past participle (formal alternative to If I had known...).', '2026-02-17 09:58:54.170896+00', NULL, NULL, 'en', '{Inversion}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('174ead82-20ad-4c43-b68a-9c8c926bda0e', 649, 'sentence_building', 'A2', 'comparatives', 'Hay mas restaurantes que el año pasado.', 'there are more restaurants than last year', '["there", "are", "more", "restaurants", "than", "last", "year", "less", "is", "next", "fewer"]', NULL, NULL, NULL, NULL, 'Comparatives with nouns: more + noun + than.', '2026-02-17 09:58:54.170896+00', NULL, NULL, 'both', '{Comparative}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('950424c1-5e17-4dcb-ad25-e1fb0c6d9fc5', 1204, 'sentence_building', 'B2', 'routines', 'Tener una hora de dormir constante ha mejorado enormemente la calidad de mi sueño.', 'Having a consistent bedtime has improved my sleep quality enormously.', '["having", "a", "consistent", "bedtime", "has", "improved", "my", "sleep", "quality", "enormously", "regular", "make", "better", "very"]', NULL, NULL, NULL, NULL, 'A gerund (Having) acts as the subject of this sentence. Consistent means happening at the same time every day.', '2026-03-16 09:04:17.945706+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('70be9156-a889-497d-838d-eaa8784c5699', 658, 'sentence_building', 'B2', 'gerunds_and_infinitives', 'Me arrepiento de no haber ido a la universidad.', 'I regret not having gone to university', '["I", "regret", "not", "having", "gone", "to", "university", "going", "go", "the", "have", "being"]', NULL, NULL, NULL, NULL, 'Regret + not having + past participle: expressing regret about a past decision.', '2026-02-17 09:58:54.170896+00', NULL, NULL, 'en', '{"Gerund & infinitive"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('6585e4e8-0017-474e-a901-490201f2cace', 1206, 'sentence_building', 'C1', 'routines', 'Está haciendo un esfuerzo consciente por relajarse antes de acostarse.', 'She has been making a conscious effort to wind down before bed.', '["she", "has", "been", "making", "a", "conscious", "effort", "to", "wind", "down", "before", "bed", "deliberate", "relax", "sleep", "make"]', NULL, NULL, NULL, NULL, 'Wind down is a phrasal verb meaning to relax gradually after a period of activity. Conscious effort means a deliberate, intentional attempt.', '2026-03-16 09:04:17.945706+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('b1e841a9-581d-44b7-bdbc-ef704071f7b5', 1903, 'matching', 'A2', 'grammar', 'Match each question word to what it asks about.', 'match_all_pairs', '[{"left": {"type": "text", "label": "", "content": "When?"}, "right": {"type": "text", "label": "", "content": "time"}}, {"left": {"type": "text", "label": "", "content": "Where?"}, "right": {"type": "text", "label": "", "content": "place"}}, {"left": {"type": "text", "label": "", "content": "Why?"}, "right": {"type": "text", "label": "", "content": "reason"}}, {"left": {"type": "text", "label": "", "content": "How?"}, "right": {"type": "text", "label": "", "content": "manner or method"}}, {"left": {"type": "text", "label": "", "content": "How much?"}, "right": {"type": "text", "label": "", "content": "quantity or price"}}]', NULL, NULL, NULL, NULL, NULL, '2026-04-08 18:25:27.713957+00', NULL, NULL, 'en', '{Grammar}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('19e0204d-ce1c-44dd-9a45-87a708af7e02', 158, 'multiple_choice', 'B1', 'prepositions_dependent', 'She''s afraid ___ spiders.', 'of', '["from", "of", "about", "with"]', NULL, NULL, NULL, '"Afraid" always pairs with the same preposition.', 'Afraid of + noun/gerund.', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{"Dependent preposition"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('bdef8a57-6448-4e08-94ab-ddbbc708251e', 1102, 'gap_fill', 'B1', 'business_vocabulary', 'The company invested in a new _______ system to track everything from raw materials to delivery.', 'supply chain', NULL, NULL, NULL, NULL, 'Two words — the full network from producer to customer.', 'A supply chain is the full network of people, processes, and organisations involved in producing and delivering a product — from raw materials to the end customer.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Business vocabulary",Collocation}', false, 'From raw cotton to T-shirt on shelf — every link in between.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('ffdac307-d148-4ba7-90b1-102f3a88460f', 1207, 'sentence_building', 'C2', 'routines', 'A menudo se subestima hasta qué punto los hábitos diarios conforman nuestro sentido de identidad.', 'The extent to which daily habits shape our sense of identity is often underestimated.', '["the", "extent", "to", "which", "daily", "habits", "shape", "our", "sense", "of", "identity", "is", "often", "underestimated", "routine", "degree"]', NULL, NULL, NULL, NULL, 'The extent to which is a sophisticated structure introducing a degree or measure. The whole noun clause is the subject of is often underestimated.', '2026-03-16 09:04:17.945706+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('df1fc12a-87e5-45af-b516-9366bde73db0', 174, 'multiple_choice', 'B2', 'gerunds_prepositions', 'I''m looking forward to ___ you again.', 'seeing', '["see", "seeing", "saw", "seen"]', NULL, NULL, NULL, 'After "to" as a preposition (not the infinitive!), use the -ing form. Compare: "look forward to + -ing".', 'Prepositions (to, for, of, etc.) are followed by gerunds.', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{"Dependent preposition"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('6f3ec0d8-8049-404d-a786-89f6f1c6013e', 258, 'gap_fill', 'A2', 'prepositions_of_time', 'The shop is open ___ 9 am to 6 pm.', 'from', NULL, NULL, NULL, NULL, 'Range from X to Y — paired with "to".', 'From...to/until shows a period of time with start and end.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Preposition of time"}', false, '___ 9 ___ 6 — start and end of a range.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('60c3614f-2ff7-44d1-b7f9-e302ae7e7d82', 531, 'multiple_choice', 'C1', 'idioms', 'Let''s not beat around the ___. What''s the real problem?', 'bush', '["hedge", "bush", "tree", "garden"]', NULL, NULL, NULL, 'Idiom about being evasive — involves a plant in a garden.', 'Beat around the bush = avoid talking about something directly.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Fixed expression"}', true, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('887f40bf-12b2-4821-ac6a-413ebbba9ccd', 788, 'multiple_choice', 'C2', 'academic language', '"The notion that growth and sustainability are mutually exclusive is a ___."', 'false dichotomy', '["false dichotomy", "false economy", "red herring", "straw man"]', NULL, NULL, NULL, 'A misleading "either-or" — when more options actually exist.', 'A "false dichotomy" presents two options as if they are the only possibilities, when in reality there are more. A "straw man" misrepresents an argument. A "red herring" distracts from the real issue.', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{"Academic English"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('1c6b2783-713f-4029-95bd-8b6c5ccab1e5', 789, 'multiple_choice', 'C2', 'vocabulary', '"The government''s economic measures were ___ by critics as short-sighted and damaging."', 'lambasted', '["lambasted", "criticised", "condemned", "denounced"]', NULL, NULL, NULL, 'Severely criticised in public.', '"Lambasted" is a more vivid and forceful word than "criticised". It implies harsh, vigorous public attack. While the others work grammatically, "lambasted" is the most precise and expressive choice here.', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('b6370b7d-e47c-4cce-be1b-553a841c14fe', 1904, 'matching', 'A2', 'vocabulary', 'Match each cooking verb to its meaning.', 'match_all_pairs', '[{"left": {"type": "text", "label": "", "content": "boil"}, "right": {"type": "text", "label": "", "content": "cook in hot water"}}, {"left": {"type": "text", "label": "", "content": "fry"}, "right": {"type": "text", "label": "", "content": "cook in oil"}}, {"left": {"type": "text", "label": "", "content": "grill"}, "right": {"type": "text", "label": "", "content": "cook over direct heat"}}, {"left": {"type": "text", "label": "", "content": "bake"}, "right": {"type": "text", "label": "", "content": "cook in an oven"}}]', NULL, NULL, NULL, NULL, NULL, '2026-04-08 18:25:27.713957+00', NULL, NULL, 'en', '{Vocabulary,Food}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('893bd003-d7e3-43a6-80f6-0fe4f24146b8', 1905, 'matching', 'A2', 'vocabulary', 'Match each word to its meaning.', 'match_all_pairs', '[{"left": {"type": "text", "label": "", "content": "borrow"}, "right": {"type": "text", "label": "", "content": "take something temporarily"}}, {"left": {"type": "text", "label": "", "content": "lend"}, "right": {"type": "text", "label": "", "content": "give something temporarily"}}, {"left": {"type": "text", "label": "", "content": "buy"}, "right": {"type": "text", "label": "", "content": "pay money for something"}}, {"left": {"type": "text", "label": "", "content": "rent"}, "right": {"type": "text", "label": "", "content": "pay to use something for a period of time"}}]', NULL, NULL, NULL, NULL, NULL, '2026-04-08 18:25:27.713957+00', NULL, NULL, 'en', '{Vocabulary}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('cce1b16b-778a-4c2b-b4f3-b27d76293df9', 356, 'multiple_choice', 'A2', 'food_and_drink', 'How ___ eggs do we need?', 'many', '["much", "many", "some", "any"]', NULL, NULL, NULL, 'Eggs are countable: 1 egg, 2 eggs, 3 eggs.', 'How many + countable plural noun (eggs are countable).', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{Vocabulary}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('103a5537-6214-47a7-a615-46e613e5e955', 1088, 'multiple_choice', 'A1', 'business_vocabulary', 'A(/an) _______ is a formal meeting between a job applicant and an employer.', 'interview', '["interview", "appointment", "session", "review"]', NULL, NULL, NULL, 'Think of the meeting you''d have *before* you get the job, not after.', 'An interview is a formal meeting to assess a candidate for a job. Compare: appraisal = a performance review for an existing employee.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Business vocabulary","HR vocabulary"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('599b4b5a-61c2-4992-94b1-7ab3b6c485a4', 1087, 'multiple_choice', 'A1', 'business_vocabulary', 'The money a company earns from selling its products is called _______.', 'revenue', '["revenue", "profit", "salary", "budget"]', NULL, NULL, NULL, 'This is the *total* money coming in — before paying for anything.', 'Revenue is the total money a company earns from sales before any costs are deducted. Profit is what remains after costs. These are commonly confused.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Business vocabulary","Financial vocabulary","Confusable words"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('90fcd7a6-14cb-4f19-ac77-84dfbe4ea100', 1092, 'multiple_choice', 'A2', 'business_vocabulary', 'The people responsible for running a company are called the _______.', 'board of directors', '["board of directors", "shareholders", "investors", "workforce"]', NULL, NULL, NULL, 'Not the owners — the people who *manage* the company day-to-day.', 'The board of directors is the group of people elected to govern a company on behalf of the shareholders. They set strategy and oversee senior management.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Business vocabulary",Collocation}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('3895390d-c54d-4176-80af-3a28b49239a3', 100, 'gap_fill', 'B1', 'everyday_expressions', 'I''m not sure. ___ (May be / Maybe) we should wait.', 'maybe', NULL, NULL, NULL, NULL, 'Maybe (one word) means perhaps', 'Maybe (one word) is an adverb meaning perhaps. May be expresses a different idea, like could be: it may be a good idea to get the car serviced.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{"Fixed expression"}', false, '"Maybe" (one word) = perhaps. ("May be" two words = a verb form.)', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('50cea5dc-52be-4b12-849d-2db50edfd600', 353, 'multiple_choice', 'A1', 'food_and_drink', 'Would you like ___ sugar in your tea?', 'some', '["a", "an", "some", "a lot"]', NULL, NULL, NULL, 'Sugar is uncountable — needs an indefinite quantity.', 'Some with uncountable nouns in offers: Would you like some...?', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{Vocabulary}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('8c03979e-5642-4257-9402-c0c44993a30b', 354, 'multiple_choice', 'A2', 'food_and_drink', 'We need to buy a ___ of bread.', 'loaf', '["bag", "bottle", "loaf", "cup"]', NULL, NULL, NULL, 'A specific quantity word for bread (the whole shape).', 'A loaf of bread = the whole bread from the bakery.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{Vocabulary}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('a4045bf1-71da-4787-88b8-612213e86b2e', 355, 'multiple_choice', 'A1', 'food_and_drink', 'There isn''t ___ milk in the fridge.', 'any', '["some", "any", "a", "many"]', NULL, NULL, NULL, 'Negative sentence + indefinite quantity → ___.', 'Any in negatives: There isn''t any + uncountable noun.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{Vocabulary}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('ba2882df-f415-4026-946f-36abc7f08b17', 357, 'multiple_choice', 'A2', 'food_and_drink', 'How ___ sugar do you want?', 'much', '["any", "many", "some", "much"]', NULL, NULL, NULL, 'Sugar is uncountable — you can''t count grains.', 'How much + uncountable noun (sugar is uncountable).', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{Vocabulary}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('1bc76918-eeb8-426e-9fb6-ee77d2b3867d', 636, 'sentence_building', 'A2', 'question_forms', '', 'are you coming to the party', '["are", "you", "coming", "to", "the", "party", "do", "will"]', NULL, NULL, NULL, NULL, 'To make a present continuous question, put ''are'' before the subject: ''Are you coming?'' not ''You are coming?''', '2026-02-13 08:00:10.850224+00', NULL, NULL, 'en', '{"Question form"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('bd04acef-a694-4abe-af40-dddbb328fbcf', 358, 'multiple_choice', 'A1', 'food_and_drink', 'I''m hungry. I want ___ to eat.', 'something', '["anything", "something", "nothing", "everything"]', NULL, NULL, NULL, '"I want ___ to eat" — an unspecified thing.', 'Something in positive statements: I want something.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{Vocabulary}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('ccf2d918-2d06-49c5-b995-47f6dfedcc00', 359, 'multiple_choice', 'A2', 'food_and_drink', 'There are ___ oranges in the bowl.', 'a few', '["a", "any", "much", "a few"]', NULL, NULL, NULL, 'A small number of countable things.', 'A few + countable plural = a small number (positive meaning).', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{Vocabulary}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('5122f5c8-c89a-4c08-9c6b-6f2cde047368', 360, 'multiple_choice', 'A1', 'food_and_drink', 'She doesn''t eat ___ meat.', 'any', '["some", "any", "a", "many"]', NULL, NULL, NULL, 'Negative + indefinite quantity → ___.', 'Any in negative sentences: She doesn''t eat any meat.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{Vocabulary}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('f7996f98-4bb3-4354-a2aa-868fb57196bd', 364, 'multiple_choice', 'A1', 'basic_questions', '___ do you live?', 'Where', '["What", "Who", "Where", "How"]', NULL, NULL, NULL, 'Asking about a place (where you live).', 'Where for location: Where do you live?', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Question form"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('876e6f44-b13a-404a-bac8-d3ad1dde98d4', 763, 'multiple_choice', 'B2', 'business', 'Which word best completes the sentence? "The company ___ a significant loss last quarter."', 'made', '["made", "did", "took", "had"]', NULL, NULL, NULL, 'Common collocation: companies ___ a profit or ___ a loss.', '"Make a loss" and "make a profit" are fixed business collocations. You can also "make a decision", "make progress" — "make" is very busy in business English!', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{"Business vocabulary"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('fbcd1e44-305e-4d2e-8fed-4943f9e7263e', 768, 'multiple_choice', 'B2', 'business', 'Which word means "to officially end a business relationship or agreement"?', 'terminate', '["terminate", "resign", "retire", "dismiss"]', NULL, NULL, NULL, 'Sharing a root with "terminus" — to bring to an end.', '"Terminate" is used for contracts and agreements. "Resign" is when an employee leaves voluntarily. "Dismiss" is when an employer removes an employee. "Retire" is when someone stops work permanently at the end of their career.', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{"Business vocabulary"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('e4783b4a-b78a-421f-b523-76d40e83cb68', 811, 'odd_one_out', 'B1', 'business', 'Three of these words relate to job applications. Which is the odd one out?', 'payslip', '["CV", "covering letter", "reference", "payslip"]', NULL, NULL, NULL, NULL, 'A CV, cover letter, and references are all things you provide when applying for a job. A payslip is what your employer gives you after you''ve got the job and been paid — so save it for later!', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{"Business vocabulary"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('4340f0e3-6dd6-478f-ade4-7f6e503f09a0', 777, 'multiple_choice', 'B2', 'business', '"The figures ___ that sales increased significantly in Q3."', 'indicate', '["indicate", "say", "tell", "speak"]', NULL, NULL, NULL, 'Formal verb meaning to show or suggest.', 'Data, figures, and statistics "indicate" or "suggest" things — they don''t "say" or "tell" like people do. "Indicate" is the professional choice here.', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{"Business vocabulary"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('15579c71-cc18-4dff-92d9-4ce3a3e4e6cd', 790, 'multiple_choice', 'C1', 'vocabulary', '"She ___ accepted responsibility, admitting fault only under sustained pressure."', 'grudgingly', '["grudgingly", "openly", "willingly", "frankly"]', NULL, NULL, NULL, 'With visible reluctance — like holding a grudge while doing it.', '"Grudgingly" means reluctantly, with resistance. The clause "only under sustained pressure" confirms she didn''t want to accept responsibility.', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('7c07fc9a-6c95-4d8a-9202-adf845ae43ce', 791, 'multiple_choice', 'C1', 'grammar', '"Which sentence correctly uses a cleft construction?"', 'It was the marketing team that identified the problem.', '["It was the marketing team that identified the problem.", "It was the marketing team who has identified the problem.", "It is the marketing team that have identified the problem.", "It was the marketing team which identified the problem."]', NULL, NULL, NULL, 'Cleft sentence pattern: "It + be + X + that/who + verb".', 'A cleft sentence splits information for emphasis: "It was X that/who did Y." For groups and things, "that" is preferred. "Which" is used for non-defining relative clauses, not cleft structures.', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('cfb10f89-ea2b-4226-a39b-ffa6f2106efb', 792, 'multiple_choice', 'C1', 'vocabulary', '"The witness''s account ___ that of the defendant in several crucial respects."', 'contradicted', '["contradicted", "conflicted", "clashed", "disputed"]', NULL, NULL, NULL, 'Said the opposite of — "contra-" = against.', '"Contradict" means to state the opposite of something — one account said X, the other said not-X. "Conflict" and "clash" imply tension but not necessarily direct opposition. "Dispute" means to challenge, often actively.', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('7c3dca8a-ad54-4c6d-a625-7ee8840536c3', 793, 'multiple_choice', 'C2', 'vocabulary', '"The philosopher''s ___ style — dense with allusion — rewards patient, careful reading."', 'allusive', '["allusive", "elusive", "illusive", "inclusive"]', NULL, NULL, NULL, 'Full of indirect references — adjective form of "allusion".', '"Allusive" means full of allusions (indirect references). "Elusive" means hard to catch or define. "Illusive" means based on illusion (less common). Easy to confuse, but very different!', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('3c708a8d-084c-45d7-bb30-6f1e6592e504', 794, 'multiple_choice', 'C1', 'academic vocabulary', '"The study''s findings were ___; they neither confirmed nor refuted the original hypothesis."', 'inconclusive', '["inconclusive", "ambiguous", "indeterminate", "uncertain"]', NULL, NULL, NULL, 'Not reaching a clear conclusion — neither yes nor no.', '"Inconclusive" specifically means a study or investigation did not produce a clear result. It is the precise academic term. "Ambiguous" means unclear in meaning. "Uncertain" is too general.', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{"Academic English"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('a9e5300b-3f60-41b0-a9b0-5de2f915db9a', 795, 'multiple_choice', 'C1', 'vocabulary', '"She ___ accepted the award on behalf of the entire research team."', 'graciously', '["graciously", "gracefully", "gratefully", "greatfully"]', NULL, NULL, NULL, 'With elegance and warmth — adverb form of "gracious".', '"Graciously" means in a pleasantly polite and generous way. "Gracefully" refers to elegant physical movement. "Gratefully" means with thanks. Accepting an award with kind words = graciously.', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('c0d0ff7b-8441-46ca-b75c-8cb5cb6caf08', 1739, 'multiple_choice', 'B2', 'sport', 'In yoga, what is the difference between a vinyasa and a hatha class?', 'vinyasa links breath to movement in a flowing sequence; hatha is slower and more static', '["vinyasa links breath to movement in a flowing sequence; hatha is slower and more static", "vinyasa is for beginners; hatha is advanced", "vinyasa uses props; hatha does not", "vinyasa is hot yoga; hatha is done outdoors"]', NULL, NULL, NULL, 'Vinyasa is Sanskrit for "flowing". Hatha is "force" — focused on held postures and alignment.', 'Vinyasa yoga links each movement to an inhale or exhale, creating a flowing, dynamic practice. Hatha yoga is generally slower, holding poses for longer and focusing on alignment and breath. Both are widely practised styles. Other common styles include Ashtanga (structured and physically demanding), Yin (long passive holds), and Bikram (practised in a heated room).', '2026-03-30 08:52:38.502672+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('80066804-9cc4-4ef0-bf30-4cde70efadb8', 2236, 'gap_fill', 'C1', 'phrasal_verbs', 'Sales have ___ since the new launch.', 'picked up', '[]', NULL, NULL, NULL, 'Improved or increased.', '"Pick up" means to improve or increase.', '2026-06-01 07:29:20.293249+00', NULL, NULL, 'en', '{"Phrasal verb"}', false, 'Present perfect of "pick ___".', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('297421df-faf8-48d2-a6b0-307b47362e0d', 1103, 'gap_fill', 'B1', 'business_vocabulary', 'A summary of a company''s financial position — what it owns and what it owes — is called a _______ sheet.', 'balance', NULL, NULL, NULL, NULL, 'What do you call it when assets and liabilities are weighed against each other?', 'A balance sheet is a financial statement showing what a company owns (assets) and what it owes (liabilities) at a specific point in time. Assets minus liabilities = equity.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Business vocabulary","Financial vocabulary",Collocation}', false, 'Think of an old-fashioned set of scales.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('a6fd4431-5cea-41b9-9d0e-79351411a7b9', 2237, 'gap_fill', 'C1', 'phrasal_verbs', 'They ___ the rumour before it spread.', 'shut down', '[]', NULL, NULL, NULL, 'Stopped something firmly and completely.', '"Shut down" means to stop something firmly and completely.', '2026-06-01 07:29:20.293249+00', NULL, NULL, 'en', '{"Phrasal verb"}', false, 'Past tense of "shut ___".', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('61b146d3-8e4f-4d2f-9801-223e030e4097', 601, 'sentence_building', 'B1', 'business_english', 'Necesitamos programar una reunión para la próxima semana.', 'we need to schedule a meeting for next week', '["we", "need", "to", "schedule", "a", "meeting", "for", "next", "week", "organise", "on", "last"]', NULL, NULL, NULL, NULL, '"Schedule/organise a meeting" are both standard business collocations. "For next week" is the correct preposition for future time reference.', '2026-02-12 15:08:31.507807+00', NULL, NULL, 'both', '{"Business vocabulary"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('48e75ef4-b1c1-45da-a777-4e5ecdd953a5', 1907, 'matching', 'B1', 'idioms', 'Match each idiom to its meaning.', 'match_all_pairs', '[{"left": {"type": "text", "label": "", "content": "burn the midnight oil"}, "right": {"type": "text", "label": "", "content": "work very late at night"}}, {"left": {"type": "text", "label": "", "content": "bite off more than you can chew"}, "right": {"type": "text", "label": "", "content": "take on more than you can handle"}}, {"left": {"type": "text", "label": "", "content": "have a lot on your plate"}, "right": {"type": "text", "label": "", "content": "be very busy"}}, {"left": {"type": "text", "label": "", "content": "cut corners"}, "right": {"type": "text", "label": "", "content": "do something badly to save time or money"}}]', NULL, NULL, NULL, NULL, NULL, '2026-04-08 18:25:27.713957+00', NULL, NULL, 'en', '{Idioms}', true, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('5303ba67-fe71-4ebb-8b71-836deea414d9', 1908, 'matching', 'B2', 'idioms', 'Match each idiom to its meaning.', 'match_all_pairs', '[{"left": {"type": "text", "label": "", "content": "sit on the fence"}, "right": {"type": "text", "label": "", "content": "avoid making a decision"}}, {"left": {"type": "text", "label": "", "content": "pull someone''s leg"}, "right": {"type": "text", "label": "", "content": "joke or tease someone"}}, {"left": {"type": "text", "label": "", "content": "spill the beans"}, "right": {"type": "text", "label": "", "content": "reveal a secret"}}, {"left": {"type": "text", "label": "", "content": "go the extra mile"}, "right": {"type": "text", "label": "", "content": "make more effort than expected"}}]', NULL, NULL, NULL, NULL, NULL, '2026-04-08 18:25:27.713957+00', NULL, NULL, 'en', '{Idioms}', true, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('4143a8f6-d94e-4d6f-b176-6c53cd048a94', 1909, 'matching', 'B1', 'idioms', 'Match each idiom to its meaning.', 'match_all_pairs', '[{"left": {"type": "text", "label": "", "content": "get cold feet"}, "right": {"type": "text", "label": "", "content": "become nervous about a plan"}}, {"left": {"type": "text", "label": "", "content": "beat around the bush"}, "right": {"type": "text", "label": "", "content": "avoid getting to the main point"}}, {"left": {"type": "text", "label": "", "content": "read between the lines"}, "right": {"type": "text", "label": "", "content": "understand the hidden meaning"}}, {"left": {"type": "text", "label": "", "content": "take something with a pinch of salt"}, "right": {"type": "text", "label": "", "content": "not believe something completely"}}]', NULL, NULL, NULL, NULL, NULL, '2026-04-08 18:25:27.713957+00', NULL, NULL, 'en', '{Idioms}', true, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('07367138-d70b-4a20-9ce8-6edf87fedc82', 120, 'multiple_choice', 'B2', 'reported_speech', 'She said that she ___ feeling well.', 'wasn''t', '["weren''t", "wasn''t", "doesn''t", "didn''t"]', NULL, NULL, NULL, 'Reported speech: "isn''t" gets backshifted into the past.', 'Backshift: present simple becomes past simple in reported speech.', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{"Reported speech"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('46466e63-a143-45ef-998b-25a4e3f5c889', 133, 'multiple_choice', 'B2', 'reported_questions', 'He asked me ___ I wanted to go to the cinema.', 'if', '["that", "if", "what", "which"]', NULL, NULL, NULL, 'Reported yes/no question — the link word is the giveaway.', 'If or whether for reported yes/no questions.', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{"Reported speech"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('6580bd53-0090-44df-ab0a-9666bf36d3ef', 165, 'multiple_choice', 'B2', 'reported_commands', 'She told me ___ quietly.', 'to speak', '["speak", "to speak", "speaking", "spoke"]', NULL, NULL, NULL, 'Reported command: told + person + to + infinitive.', 'Tell + object + to + infinitive for reported commands.', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{"Reported speech"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('8aab570e-cf89-4a25-bff5-f12ea6411f50', 701, 'odd_one_out', 'C1', 'formal_register', 'Which word is NOT formal register?', 'ain''t', '["nevertheless", "furthermore", "ain''t", "notwithstanding"]', NULL, NULL, NULL, NULL, '"Ain''t" is very informal/slang. The others are formal discourse markers. If you want to upset an English teacher, you can use "ain''t". Especially with another negative... ', '2026-02-20 19:09:17.848852+00', NULL, NULL, 'en', '{"Formal register"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('34841080-5e5f-4890-9ceb-3d57e0d9e493', 778, 'multiple_choice', 'C1', 'formal vocabulary', '"The proposal was met with ___ opposition from community groups who had not been consulted."', 'vociferous', '["vociferous", "loud", "strong", "heavy"]', NULL, NULL, NULL, 'Sharing a root with "voice" — loudly expressed opposition.', '"Vociferous" means loud and forceful in making one''s views known. While "loud" and "strong" are technically possible, "vociferous opposition" is the established formal collocation.', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{"Formal register"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('322f8bc7-daad-452f-a75a-354115779127', 781, 'multiple_choice', 'C1', 'formal vocabulary', '"The new data ___ previous assumptions about consumer behaviour."', 'upended', '["upended", "uplifted", "updated", "upgraded"]', NULL, NULL, NULL, 'To completely overturn — like flipping something over.', '"Upend" means to turn something on its head — to overturn established ideas completely. It is vivid and precise in academic and journalistic writing.', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{"Formal register"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('9525eeb8-07a4-47ff-8602-46da668e5b7e', 1740, 'multiple_choice', 'B2', 'sport', 'What does "DOMS" stand for, and when does it typically occur?', 'Delayed Onset Muscle Soreness — it appears 24–48 hours after intense exercise', '["Delayed Onset Muscle Soreness — it appears 24–48 hours after intense exercise", "Direct Output Muscle Stress — it occurs during exercise", "Deep Oxygen Muscle Strain — it occurs immediately after exercise", "Dynamic Output Movement Score — it is measured during a WOD"]', NULL, NULL, NULL, 'The technical term for the soreness that arrives a day or two after a hard workout.', '"Agujetas" or DOMS is the muscle soreness felt 24 to 48 hours after unfamiliar or intense exercise, especially eccentric movements like downhill running or the lowering phase of a squat. It is caused by microscopic muscle damage that triggers repair and growth. Active recovery, light movement, and hydration can help. DOMS is a sign of adaptation, not injury.', '2026-03-30 08:52:38.502672+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('b5b7ab83-525c-44a7-8188-c44a2e3215f3', 2238, 'gap_fill', 'C1', 'phrasal_verbs', 'The committee ___ several new proposals.', 'put forward', '[]', NULL, NULL, NULL, 'Suggested or presented for consideration.', '"Put forward" means to suggest or present something for consideration.', '2026-06-01 07:29:20.293249+00', NULL, NULL, 'en', '{"Phrasal verb"}', false, '"put ___" — particle "forward".', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('be4a4a4d-2b02-47c9-8023-0795454e0b37', 820, 'odd_one_out', 'C1', 'formal/legal vocabulary', 'Three of these are legal terms. Which is the odd one out?', 'curriculum', '["plaintiff", "defendant", "verdict", "curriculum"]', NULL, NULL, NULL, NULL, 'A plaintiff (the person who brings a case), a defendant (the person accused), and a verdict (the court''s decision) are all legal terms. A curriculum is an educational concept — entirely the wrong courtroom.', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{"Formal register"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('01ae60bb-1130-455c-9de9-dd9735e05602', 852, 'error_correction', 'C1', 'formal/legal vocabulary', 'The contract is legally bounding for both parties.', 'The contract is legally binding for both parties.', '[]', NULL, NULL, NULL, NULL, '"Legally binding" means that parties are legally required to honour the contract. "Bounding" relates to jumping or forming a boundary — not a legal term.', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{"Formal register"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('8c4758ac-b9cb-4025-a2b3-8ac5031f077a', 365, 'multiple_choice', 'A2', 'basic_questions', '___ does the class start?', 'What time', '["What", "How", "Which", "What time"]', NULL, NULL, NULL, 'Asking about a clock time.', 'What time for asking about specific times.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Question form"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('6251c9f9-c0c4-4559-83d3-7958de3512a7', 366, 'multiple_choice', 'A1', 'basic_questions', '___ is your favourite colour?', 'What', '["Who", "What", "Where", "How"]', NULL, NULL, NULL, 'Asking for a thing (colour).', 'What for asking about preferences.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Question form"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('82a30b16-5a79-4200-a380-b8390b14e4f1', 1225, 'multiple_choice', 'A1', 'business_phrasal_verbs', 'The meeting has been _____ until next week.', 'put off', '["put off", "put on", "put in", "put up"]', NULL, NULL, NULL, 'To postpone — push the date back.', 'Put off means to postpone or delay something. Compare: the meeting has been put off / rescheduled.', '2026-03-18 19:58:52.376507+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('77bf793f-bb41-40d8-b2a7-25eca3bc642f', 797, 'multiple_choice', 'C2', 'academic vocabulary', '"The sociological concept of ___ describes the tendency to view one''s own culture as superior."', 'ethnocentrism', '["ethnocentrism", "nationalism", "xenophobia", "parochialism"]', NULL, NULL, NULL, 'From "ethno-" (race/nation) + "centric" (centred on).', '"Ethnocentrism" is the specific academic term for judging other cultures by the standards of your own. "Xenophobia" is fear of foreigners. "Nationalism" is attachment to one''s nation. "Parochialism" is narrow-mindedness.', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{"Academic English"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('c9fea382-29de-4057-8bfb-48d38c3917cc', 1028, 'multiple_choice', 'A1', 'prepositions', 'The supermarket is right _______ the bank — they''re beside each other.', 'next to', '["next to", "at", "between", "in front of"]', NULL, NULL, NULL, 'Right beside — sharing a wall.', 'Next to means directly beside something. Compare: between = in the middle of two things; in front of = facing something; opposite = directly across from something.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Preposition of place"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('dc731af0-b7b5-4db2-ba6d-5e6bd7856801', 1137, 'gap_fill', 'C2', 'bathroom_vocabulary', 'A liquid applied to natural stone or porous tiles after installation to protect the surface from stains and moisture is called a _______.', 'sealant', NULL, NULL, NULL, '["sealer"]', 'A liquid coating that seals against water and stains.', 'A sealant penetrates the surface of porous materials such as natural stone, slate, or unglazed tiles, protecting them from water and staining. Regular reapplication is recommended, particularly in wet areas.', '2026-03-11 18:12:09.553883+00', NULL, NULL, 'en', '{}', false, 'Same root as "seal" — to close off.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('b2a3c455-c10f-4ac6-b3d7-acd614db2609', 1226, 'multiple_choice', 'A2', 'business_phrasal_verbs', 'Can you _____ the new employee on the office rules?', 'fill in', '["fill in", "fill up", "fill out", "fill over"]', NULL, NULL, NULL, 'To inform someone briefly about something they don''t know yet.', 'Fill someone in means to give them information they are missing. Compare: bring someone up to speed.', '2026-03-18 19:58:52.376507+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('5763dfc5-3d8a-4f76-91f3-ebc3f73100bf', 691, 'error_correction', 'B1', 'reported_speech', 'He told me that he will leave the company.', 'He told me that he would leave the company.', '[]', NULL, NULL, NULL, NULL, 'In reported speech, "will" changes to "would". Normally, technically, but native speakers sometimes use either if the situation remains the same: in this case he still ''will'' leave the company at the time of speaking. ', '2026-02-20 19:09:17.848852+00', NULL, NULL, 'en', '{"Reported speech"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('d175094c-3ee6-490d-8ee2-c6e912070a61', 1104, 'gap_fill', 'B2', 'business_vocabulary', 'The company''s strategy is built around cost _______ — making the same product at a lower cost than any competitor.', 'leadership', NULL, NULL, NULL, NULL, 'A common pairing with "cost" — being the *leader* in low-cost production.', 'Cost leadership is a competitive strategy based on being the lowest-cost producer in the market. The company can then undercut competitors on price while maintaining profitability.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Business vocabulary","Financial vocabulary",Collocation}', false, 'Often paired with ''thought'' or ''cost'' — being out in front.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('53a69356-407a-412d-b5f5-c4e4e9793bbb', 689, 'odd_one_out', 'C1', 'reporting_verbs', 'Which is NOT a reporting verb?', 'enumerate', '["claim", "deny", "enumerate", "insist"]', NULL, NULL, NULL, NULL, '"Enumerate" means ''to mention a number of things one by one", it is not a typical reporting verb.', '2026-02-20 19:09:17.848852+00', NULL, NULL, 'en', '{"Reported speech"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('7362d9d4-e940-44a1-898a-729d7e7bd27a', 70, 'gap_fill', 'B2', 'reported_questions', 'He wanted to know if I ___ (can / help) him.', 'could help', NULL, NULL, NULL, NULL, 'Can changes to could in reported questions', 'When reporting, can changes to could.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{"Reported speech"}', false, 'Can → could when reporting questions.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('e5ef099a-a90a-4fe8-8a9b-deb4368e3e91', 192, 'multiple_choice', 'B2', 'reported_thoughts', 'I thought you ___ coming to the party.', 'were', '["wasn''t", "were", "will", "would"]', NULL, NULL, NULL, 'Backshift: present "are" → past in reported thought.', 'Backshift in reported thoughts (present → past).', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{"Reported speech"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('53d997f5-9793-4e59-942d-4a4946b05aa7', 207, 'gap_fill', 'A1', 'present_simple', 'We ___ (go) to the beach every summer.', 'go', NULL, NULL, NULL, NULL, 'We/you/they don''t add -s.', 'Present simple for habits and routines.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Present tense"}', false, 'Only he/she/it adds -s.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('337b3ec5-4752-49c3-87c1-19e5406f1ddf', 367, 'multiple_choice', 'A2', 'basic_questions', '___ do you go to the gym?', 'How often', '["How many", "How often", "How long", "Who"]', NULL, NULL, NULL, 'Asking about frequency — how many times.', 'How often for frequency: How often do you...?', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Question form"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('8b1ee55f-94eb-414b-be26-2be010fb8aed', 368, 'multiple_choice', 'A2', 'basic_questions', '___ does it take to get to work?', 'How long', '["How often", "How many", "How much", "How long"]', NULL, NULL, NULL, 'Asking about duration — a length of time.', 'How long for duration: How long does it take?', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Question form"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('6015c19c-fd03-451c-918f-8af613edc0f6', 370, 'multiple_choice', 'A2', 'basic_questions', '___ people are in your family?', 'How many', '["How often", "How many", "How much", "How long"]', NULL, NULL, NULL, 'Asking about a number of countable things.', 'How many + plural countable noun.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Question form"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('24494d0d-205a-4e04-80b1-a15cea338ae7', 373, 'multiple_choice', 'A1', 'pronouns', 'That book is ___. Give it back!', 'mine', '["my", "me", "mine", "I"]', NULL, NULL, NULL, 'Possessive pronoun — stands alone (no noun after).', 'Mine = possessive pronoun (it belongs to me).', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{Pronoun}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('58f5e955-0a80-4d62-ba72-db9056baa1f3', 374, 'multiple_choice', 'A1', 'pronouns', 'Can you help ___? I don''t understand.', 'me', '["I", "my", "mine", "me"]', NULL, NULL, NULL, 'Object pronoun — what comes after the verb.', 'Me = object pronoun after verbs: help me, tell me.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{Pronoun}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('8a2fd453-aaec-4376-9000-fe58202a128d', 375, 'multiple_choice', 'A2', 'pronouns', 'These are ___ shoes, not yours.', 'my', '["I", "me", "my", "mine"]', NULL, NULL, NULL, 'Possessive adjective — comes before "shoes".', 'My + noun: my shoes, my house, my name.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{Pronoun}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('48342350-d997-4301-8b00-de22afa038a0', 376, 'multiple_choice', 'A1', 'pronouns', 'Maria is Italian. ___ is from Rome.', 'She', '["He", "She", "Her", "His"]', NULL, NULL, NULL, 'Subject pronoun — replacing "Maria".', 'She = subject pronoun for a female person.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{Pronoun}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('50f68c91-afb2-4b57-903f-4a140ab64009', 377, 'multiple_choice', 'A2', 'pronouns', 'Is this ___ car or theirs?', 'your', '["you", "your", "yours", "yourself"]', NULL, NULL, NULL, 'Possessive adjective — comes before "car".', 'Your + noun: your car. Yours without a noun.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{Pronoun}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('b5171798-5348-4ed2-83c2-56c97260be58', 378, 'multiple_choice', 'A1', 'pronouns', 'We live in Palma. ___ house is near the beach.', 'Our', '["We", "Us", "Our", "Ours"]', NULL, NULL, NULL, 'Possessive adjective for "we".', 'Our + noun: Our house, our school.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{Pronoun}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('02f52afd-b702-4994-972d-3dc0ffc5950f', 379, 'multiple_choice', 'A2', 'pronouns', 'The children did it by ___.', 'themselves', '["they", "their", "theirs", "themselves"]', NULL, NULL, NULL, 'Reflexive pronoun for "they" — they did it alone.', 'By themselves = without help (reflexive pronoun).', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{Pronoun}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('be5fbb61-764a-42e1-8dfa-f785adc501b2', 1910, 'matching', 'B1', 'grammar', 'Match the beginning of each sentence to its correct ending.', 'match_all_pairs', '[{"left": {"type": "text", "label": "", "content": "By the time she arrived,"}, "right": {"type": "text", "label": "", "content": "the meeting had already finished."}}, {"left": {"type": "text", "label": "", "content": "Although it was raining,"}, "right": {"type": "text", "label": "", "content": "we decided to go for a walk."}}, {"left": {"type": "text", "label": "", "content": "Unless you study regularly,"}, "right": {"type": "text", "label": "", "content": "you''ll find the exam very difficult."}}, {"left": {"type": "text", "label": "", "content": "As soon as the lesson ended,"}, "right": {"type": "text", "label": "", "content": "the students checked their phones."}}, {"left": {"type": "text", "label": "", "content": "Provided that you book early,"}, "right": {"type": "text", "label": "", "content": "you can get a much cheaper ticket."}}]', NULL, NULL, NULL, NULL, NULL, '2026-04-08 18:25:27.713957+00', NULL, NULL, 'en', '{Grammar,Sentences}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('8a3df239-0abd-4abb-819d-5e36018937fa', 2239, 'gap_fill', 'C1', 'phrasal_verbs', 'He always ___ when things get difficult.', 'backs down', '[]', NULL, NULL, NULL, 'Withdraws from a position or argument.', '"Back down" means to withdraw from a position or argument.', '2026-06-01 07:29:20.293249+00', NULL, NULL, 'en', '{"Phrasal verb"}', false, '"back ___" — particle "down".', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('a50e3fa8-fda9-48ae-9be2-727a1f67dce7', 501, 'multiple_choice', 'C1', 'advanced_phrasal_verbs', 'After examining the manuscript, the historian carefully ___ it in the archive, conscious of its fragility.', 'put back', '["put away", "put back", "put down", "put up"]', NULL, NULL, NULL, 'To return something to its original position.', 'Put off = postpone, delay to a later time.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Phrasal verb"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('2ade5bb3-576b-41bc-add3-42aa0220a79d', 2240, 'multiple_choice', 'A2', 'spanish', 'Me ___ a las siete todos los días.', 'levanto', '["levanto", "acuesto", "siento", "lavo"]', NULL, NULL, NULL, '"I get up" — a reflexive verb.', '"Levantarse" is reflexive: "me levanto" = "I get up".', '2026-06-01 07:29:20.293249+00', NULL, NULL, 'es', '{Vocabulary}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('119ee8aa-4e57-4cb3-93b5-e670f9067fa4', 894, 'multiple_choice', 'A2', 'spanish', 'What does "el ayuntamiento" mean in English?', 'Town hall', '["Town hall", "Hospital", "School", "Train station"]', NULL, NULL, NULL, 'The local government building of a town.', '"El ayuntamiento" is the town hall or city hall. "El hospital" = hospital, "el colegio" = school, "la estación de tren" = train station. It is often used to describe the local authority as well as just the building.', '2026-03-03 14:10:39.181019+00', NULL, NULL, 'both', '{Vocabulario}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('9d4ffc5a-e4fd-4f69-be1a-d9fd4b732635', 896, 'multiple_choice', 'A2', 'spanish', 'What does "tomar el sol" mean in English?', 'To sunbathe', '["To sunbathe", "To drink coffee", "To have lunch", "To go for a walk"]', NULL, NULL, NULL, 'Literally "to take the sun".', '"Tomar el sol" literally means to take the sun — it means to sunbathe. Other "tomar" expressions: "tomar un café" (to have a coffee), "tomar el autobús" (to take the bus).', '2026-03-03 14:10:39.181019+00', NULL, NULL, 'both', '{Vocabulario}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('aa4fc414-318f-4f3e-94e3-f37c1032a7fd', 898, 'multiple_choice', 'A2', 'spanish', 'How do you say "Turn left" when giving directions in Spanish?', 'Gira a la izquierda', '["Gira a la izquierda", "Gira a la derecha", "Sigue recto", "Para aquí"]', NULL, NULL, NULL, '"Gira" = turn (imperative), "a la izquierda" = to the left.', '"Gira a la izquierda" = turn left. "Gira a la derecha" = turn right, "sigue recto" = go straight on, "para aquí" = stop here.', '2026-03-03 14:10:39.181019+00', NULL, NULL, 'both', '{Vocabulario}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('8dbd53cd-4c78-4738-b364-42f6975cf564', 899, 'multiple_choice', 'A2', 'spanish', 'What does "cada día" mean in English?', 'Every day', '["Every day", "Some days", "All day", "The next day"]', NULL, NULL, NULL, '"Cada" = each, "día" = day.', '"Cada" means each/every, so "cada día" = every day. Compare: "todo el día" = all day, "al día siguiente" = the next day, "algunos días" = some days.', '2026-03-03 14:10:39.181019+00', NULL, NULL, 'both', '{Vocabulario}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('7dd1eacf-44f3-4924-aaa7-f9b4b0d36d65', 906, 'multiple_choice', 'A2', 'spanish', 'What does "¿Cuánto cuesta?" mean in English?', 'How much does it cost?', '["How much does it cost?", "How many are there?", "What time is it?", "How far is it?"]', NULL, NULL, NULL, '"Cuánto" = how much, "cuesta" = costs.', '"¿Cuánto cuesta?" = How much does it cost? Essential for shopping. "¿Cuántos hay?" = How many are there?, "¿Qué hora es?" = What time is it?', '2026-03-03 14:10:39.181019+00', NULL, NULL, 'both', '{Vocabulario}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('7159c2be-dccd-4cd2-8e16-ecf562003830', 109, 'multiple_choice', 'B1', 'zero_conditional', 'If you ___ water to 100°C, it boils.', 'heat', '["will heat", "heat", "would heat", "heated"]', NULL, NULL, NULL, 'Always-true scientific fact. Form: If + present, present.', 'Zero conditional (general truths): If + present, present.', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{Conditional}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('5c96c6d3-b82d-4421-9066-00e0aca63f94', 161, 'multiple_choice', 'B2', 'mixed_conditionals', 'If I ___ rich, I would have bought that house last year.', 'were', '["am", "was", "were", "had been"]', NULL, NULL, NULL, 'Mixed conditional: present condition (you''re not rich now) + past consequence (didn''t buy then).', 'Mixed conditional: present condition, past result. Was here is inelegant English, were is better. ', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{Conditional}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('d857d004-8c83-47fb-80f8-54c0381dd333', 184, 'multiple_choice', 'B2', 'unless_if_not', '___ you hurry, we''ll miss the train.', 'Unless', '["If", "Unless", "When", "Although"]', NULL, NULL, NULL, '= "if not" — if you DON''T hurry, we''ll miss the train.', 'Unless = if not.', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{Conditional}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('c1c1256f-4536-45a9-a4c9-2fc03ffd36d6', 208, 'gap_fill', 'A2', 'present_simple', 'The shop ___ (close) at 9 pm.', 'closes', NULL, NULL, NULL, NULL, 'The shop = it. Add -s.', 'Present simple for schedules and timetables.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Present tense"}', false, 'Like: it opens, it closes, it works.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('3af4d5ce-0f4c-4829-bb54-ae0c6ec5602e', 401, 'gap_fill', 'C1', 'mixed_conditionals', 'If I ___ (study) harder at school, I would have a better job now.', 'had studied', NULL, NULL, NULL, NULL, 'Mixed conditional: past condition (you didn''t study) → present consequence (no good job now).', 'Mixed conditional (past → present): If + past perfect, would + base verb. Past action affecting present situation.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{Conditional}', false, 'Form: had + past participle in the if-clause.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('a33f3b06-bcbe-48d8-b5ee-1307bb87d9b7', 606, 'sentence_building', 'C1', 'third_conditional', 'Si hubiéramos sabido antes, habríamos cambiado el plan.', 'if we had known earlier we would have changed the plan', '["if", "we", "had", "known", "earlier", "we", "would", "have", "changed", "the", "plan", "will", "kept", "early"]', NULL, NULL, NULL, NULL, 'Third conditional: if + past perfect, would have + past participle. Used for hypothetical past situations.', '2026-02-12 15:08:31.507807+00', NULL, NULL, 'en', '{Conditional}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('0aa28f70-bc20-4616-91a0-47128745059d', 403, 'gap_fill', 'C1', 'mixed_conditionals', 'I ___ (not be) in this mess if I hadn''t listened to your advice.', 'wouldn''t be', NULL, NULL, NULL, NULL, 'Past condition → present consequence. The "now" is implied — you''re in this mess right now.', 'Mixed conditional: would + base verb in the result clause when describing a present situation.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{Conditional}', false, 'Form: would/wouldn''t + base verb.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('bbd30fcc-ac6c-403d-aa11-b0406af7ff06', 502, 'multiple_choice', 'C1', 'advanced_phrasal_verbs', 'I can''t ___ with his constant complaining any longer.', 'put up', '["put on", "put off", "put up", "put away"]', NULL, NULL, NULL, 'To tolerate something annoying.', 'Put up with = tolerate, endure something annoying.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Phrasal verb"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('48a00f51-ec62-498c-98e9-2bf46dfc4837', 942, 'multiple_choice', 'A1', 'phrasal_verbs', 'Please _______ the form and sign at the bottom.', 'fill in', '["fill in", "fill up", "fill over", "fill past"]', NULL, NULL, NULL, 'To complete a form by writing in the blanks.', 'To fill in (or fill out) a form means to complete it. Fill in is more common in British English; fill out in American English.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Phrasal verb"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('8a29560a-e70c-4a6d-a02f-75e7e60d0da8', 939, 'multiple_choice', 'A1', 'phrasal_verbs', 'She _______ smoking two years ago and feels much healthier now.', 'gave up', '["gave up", "gave in", "gave out", "gave away"]', NULL, NULL, NULL, 'To stop a habit — like surrendering to it.', 'To give up means to stop doing something, especially a habit. Compare: give in = to surrender or admit defeat; give out = to distribute, or to stop working.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Phrasal verb"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('715cfdd3-b8e7-487d-84bb-3c4f928b3dbd', 2241, 'multiple_choice', 'A2', 'spanish', 'No me ___ de que era tan tarde.', 'di cuenta', '["di cuenta", "di vuelta", "fui", "puse"]', NULL, NULL, NULL, '"darse cuenta de" = to realise.', '"Darse cuenta de" means "to realise" something.', '2026-06-01 07:29:20.293249+00', NULL, NULL, 'es', '{Vocabulary}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('93d6090f-6350-4b48-8f6e-9bee45eb813b', 940, 'multiple_choice', 'A1', 'phrasal_verbs', 'Can you _______ the lights? It''s getting dark in here.', 'turn on', '["turn on", "turn up", "turn over", "turn out"]', NULL, NULL, NULL, 'To activate or switch on. Opposite of "turn off".', 'To turn on means to switch something on. Compare: turn up = to increase volume or heat; turn out = to produce a result, or to switch off a light.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Phrasal verb"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('fcc8437f-b7b4-4e6c-a4a1-ffa91d12d114', 1105, 'gap_fill', 'B2', 'business_vocabulary', 'In tough economic conditions, customer _______ is far cheaper than acquiring new ones.', 'retention', NULL, NULL, NULL, NULL, 'The opposite of losing customers — *keeping* them.', 'Customer retention means keeping existing customers and encouraging them to return. Acquiring a new customer typically costs five to seven times more than retaining an existing one.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Business vocabulary"}', false, NULL, 'noun');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('d1382c39-7305-41d6-935a-b4892f97043b', 941, 'multiple_choice', 'A1', 'phrasal_verbs', 'We _______ of petrol on the motorway and had to call for help.', 'ran out', '["ran out", "ran off", "ran away", "ran through"]', NULL, NULL, NULL, 'When you have no more of something — your supply has gone.', 'To run out of something means to have none left. The preposition of is essential — don''t omit it.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Phrasal verb"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('578b4121-b096-46fe-837c-9ac6cfd5281a', 692, 'error_correction', 'B1', 'first_conditional', 'If I had time, I will help you.', 'If I have time, I will help you.', '[]', NULL, NULL, NULL, NULL, 'In first conditional, the "if" clause uses present simple, not the past simple "had".', '2026-02-20 19:09:17.848852+00', NULL, NULL, 'en', '{Conditional}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('1651ffaa-b0da-4a3f-9679-ffe6ba059ff5', 673, 'error_correction', 'C1', 'third_conditional', 'Had I knew about the problem, I would have acted sooner.', 'Had I known about the problem, I would have acted sooner.', '[]', NULL, NULL, NULL, NULL, 'Inverted third conditional uses the past participle: "Had I known", not "Had I knew".', '2026-02-20 19:09:17.848852+00', NULL, NULL, 'en', '{Conditional}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('27642820-b8f1-421f-9ead-17d1c000839b', 681, 'error_correction', 'B2', 'second_conditional', 'If I have more time, I would learn another language.', 'If I had more time, I would learn another language.', '[]', NULL, NULL, NULL, NULL, 'In the second conditional, the "if" clause uses past simple, not  the infinitive " have".', '2026-02-20 19:09:17.848852+00', NULL, NULL, 'en', '{Conditional}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('96757144-3c45-44bb-ae85-e008530fb0f4', 705, 'error_correction', 'C2', 'mixed_conditionals', 'Were it not of his help, the project would have failed.', 'Were it not for his help, the project would have failed.', '[]', NULL, NULL, NULL, NULL, 'The correct structure is "Were it not for", not "Were it not of".', '2026-02-20 19:09:17.848852+00', NULL, NULL, 'en', '{Conditional}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('005d5a36-1319-45d3-ba3c-17b2f23861b4', 671, 'odd_one_out', 'B2', 'conditionals', 'Which is NOT a conditional form?', 'I am going to', '["If I had known", "I wish I could", "Unless you try", "I am going to"]', NULL, NULL, NULL, NULL, '"I am going to" expresses future plans, not a conditional structure.', '2026-02-20 19:09:17.848852+00', NULL, NULL, 'en', '{Conditional}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('69e56f9d-dfb0-4f0b-baf6-0968c59c0795', 943, 'multiple_choice', 'A2', 'phrasal_verbs', 'I need to _______ this word — I don''t know what it means.', 'look up', '["look up", "look for", "look after", "look out"]', NULL, NULL, NULL, 'To search for information (in a dictionary, online).', 'To look up a word means to search for its meaning — in a dictionary or online. Compare: look after = to take care of someone; look out = to be careful.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Phrasal verb"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('fb2c39ae-e955-49b5-844f-7cc2b4adff8c', 1106, 'gap_fill', 'B2', 'business_vocabulary', 'A _______ analysis is a detailed calculation of whether a project will earn more money than it costs.', 'cost-benefit', NULL, NULL, NULL, '["cost benefit"]', 'A compound word with a hyphen — weighing two things against each other.', 'A cost-benefit analysis calculates whether the financial benefits of a project outweigh its costs. It is a standard tool for evaluating investment decisions.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Business vocabulary","Financial vocabulary",Collocation}', false, 'If you''re weighing what you''d gain against what you''d lose.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('f5fabea9-0231-4158-962d-44101c159331', 944, 'multiple_choice', 'A2', 'phrasal_verbs', 'The meeting was _______ until next Thursday.', 'put off', '["put off", "put on", "put up", "put away"]', NULL, NULL, NULL, 'To postpone — push the date back.', 'To put off means to postpone something to a later date. Compare: put on = to add or start something; put away = to tidy something into its usual place.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Phrasal verb"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('cd5552c0-5d8f-4098-85a8-d32f5706a95e', 2242, 'multiple_choice', 'A2', 'spanish', 'Hace frío; voy a ___ el abrigo.', 'ponerme', '["ponerme", "quitarme", "lavarme", "sentarme"]', NULL, NULL, NULL, '"ponerse" = to put on (clothing).', '"Ponerse" means "to put on" clothing: "ponerme el abrigo".', '2026-06-01 07:29:20.293249+00', NULL, NULL, 'es', '{Vocabulary}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('7de86c65-cb28-4421-b611-3721a70e50f5', 131, 'multiple_choice', 'B2', 'passive_present_perfect', 'The work ___ yet.', 'hasn''t been finished', '["hasn''t finishing", "hasn''t been finished", "isn''t finishing", "wasn''t finished"]', NULL, NULL, NULL, 'The work didn''t finish itself. Passive present perfect.', 'Present perfect passive: has/have been + past participle.', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{"Passive voice"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('bd0466a0-af58-404c-83aa-b5ed3f202b62', 614, 'sentence_building', 'B2', 'second_conditional', NULL, 'if I had more time I would learn another language', '["if", "I", "had", "more", "time", "I", "would", "learn", "another", "language", "will", "other", "learning"]', NULL, NULL, NULL, NULL, 'Second conditional: if + past simple, would + infinitive. For unreal present/future situations.', '2026-02-12 14:34:46.611844+00', NULL, NULL, 'en', '{Conditional}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('eb91681d-0eb4-4c82-b438-39c60982d39e', 402, 'gap_fill', 'C1', 'mixed_conditionals', 'If she ___ (be) more confident, she would have applied for that job.', 'were', NULL, '["was"]', 'Was is inelegant here, native speakers judge each other on these things. Were always sounds better in hypotheticals. ', NULL, 'Mixed conditional: present condition (she''s not confident now) → past consequence (didn''t apply).', 'Mixed conditional (present → past): If + past simple, would have + past participle. Present characteristic affecting past action.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{Conditional}', false, 'Form: ___ (subjunctive) for hypothetical present condition.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('fb217e11-668d-4476-a4fc-48ae1047d7e8', 513, 'multiple_choice', 'C1', 'advanced_phrasal_verbs', 'I''ll ___ to you once I have more information.', 'get back', '["get on", "get through", "get back", "get by"]', NULL, NULL, NULL, 'To respond/reply later (especially to messages).', 'Get back to someone = contact them again later with information.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Phrasal verb"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('8378ad61-77a9-4ae7-a7c2-84f193f86fc4', 2243, 'multiple_choice', 'A2', 'spanish', 'Tenemos que ___ pronto para el tren.', 'salir', '["salir", "entrar", "volver", "quedar"]', NULL, NULL, NULL, '"to leave / set off".', '"Salir" means "to leave" or "to set off".', '2026-06-01 07:29:20.293249+00', NULL, NULL, 'es', '{Vocabulary}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('c269e693-65b1-4e4f-8114-3b8705b1efcb', 1911, 'matching', 'B2', 'grammar', 'Match the beginning of each sentence to its correct ending.', 'match_all_pairs', '[{"left": {"type": "text", "label": "", "content": "She would have passed the exam"}, "right": {"type": "text", "label": "", "content": "if she had studied harder."}}, {"left": {"type": "text", "label": "", "content": "He''s used to working"}, "right": {"type": "text", "label": "", "content": "long hours in the restaurant."}}, {"left": {"type": "text", "label": "", "content": "I''d rather you didn''t"}, "right": {"type": "text", "label": "", "content": "mention it to anyone else."}}, {"left": {"type": "text", "label": "", "content": "It''s about time you"}, "right": {"type": "text", "label": "", "content": "started looking for a new job."}}, {"left": {"type": "text", "label": "", "content": "There''s no point in"}, "right": {"type": "text", "label": "", "content": "worrying about things you can''t control."}}]', NULL, NULL, NULL, NULL, NULL, '2026-04-08 18:25:27.713957+00', NULL, NULL, 'en', '{Grammar,Sentences}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('6cddde3f-0012-4da6-ae28-e88e6fd044b2', 2244, 'multiple_choice', 'A2', 'spanish', 'Voy a ___ con mis amigos esta noche.', 'salir', '["salir", "entrar", "subir", "bajar"]', NULL, NULL, NULL, '"salir con" = to go out with.', '"Salir con" means "to go out with" someone.', '2026-06-01 07:29:20.293249+00', NULL, NULL, 'es', '{Vocabulary}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('d645901b-656b-46b3-9ffd-170ac2e4ea14', 901, 'multiple_choice', 'A2', 'spanish', 'What does "el semáforo" mean in English?', 'Traffic light', '["Traffic light", "Roundabout", "Crossroads", "Car park"]', NULL, NULL, NULL, 'From Greek "sēma" (sign) + "phorós" (carrier) — a sign carrier.', '"El semáforo" = traffic light. "La rotonda" = roundabout, "el cruce" = crossroads, "el aparcamiento" = car park.', '2026-03-03 14:10:39.181019+00', NULL, NULL, 'both', '{Vocabulario}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('9f7e7173-c7fb-441b-a0bd-b0d0c53e71f3', 27, 'gap_fill', 'B1', 'relative_clauses', 'The book ___ (which / who / that / why) I''m reading is really interesting.', 'which', NULL, NULL, NULL, NULL, 'Relative pronoun for things', 'Which or that can be used for things in relative clauses.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{"Relative clause"}', false, 'Books, ideas, objects — not people.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('fd7ebd78-93c9-460e-aa1d-280c79354222', 945, 'multiple_choice', 'A2', 'phrasal_verbs', 'He _______ his jacket because it was so hot in the office.', 'took off', '["took off", "put off", "got off", "came off"]', NULL, NULL, NULL, 'To remove (clothing, an item).', 'To take off clothing means to remove it. Take off also means to leave the ground (a plane), or to become suddenly successful.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Phrasal verb"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('2e654ba4-2a26-4e65-94e5-1ddc2555a5be', 946, 'multiple_choice', 'A2', 'phrasal_verbs', 'Can you _______ the music a bit? I''m trying to concentrate.', 'turn down', '["turn down", "turn off", "turn up", "turn over"]', NULL, NULL, NULL, 'To reduce the volume — opposite of "turn up".', 'To turn down the music means to reduce the volume. Compare: turn off = to stop completely; turn up = to increase the volume.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Phrasal verb"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('560b3803-e40d-4a37-90cc-8dd1f11ca7b6', 105, 'multiple_choice', 'B1', 'relative_clauses', 'That''s the woman ___ lives next door to us.', 'who', '["which", "what", "where", "who"]', NULL, NULL, NULL, 'Relative pronoun for people — not for things or places.', 'Who for people in relative clauses.', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{"Relative clause"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('4aeb9af7-723f-48dd-b9bc-83193369b8a0', 127, 'multiple_choice', 'B2', 'relative_clauses', 'That''s the hotel ___ we stayed last summer.', 'where', '["which", "where", "when", "who"]', NULL, NULL, NULL, 'Relative for places — the hotel ___ we stayed.', 'Where for places in relative clauses.', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{"Relative clause"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('dcdd0082-1218-4dd8-ab8a-08bfb34d00e2', 717, 'error_correction', 'B1', 'passive_voice', 'The meeting was cancel due to bad weather.', 'The meeting was cancelled due to bad weather.', '[]', NULL, NULL, NULL, NULL, 'In the passive voice, we need the past participle: "was cancelled".', '2026-02-20 19:09:17.848852+00', NULL, NULL, 'en', '{"Passive voice"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('f3e48bbb-7914-4364-bce3-e426095d5c25', 155, 'multiple_choice', 'B2', 'relative_clauses_whose', 'That''s the woman ___ son won the competition.', 'whose', '["who", "which", "whose", "that"]', NULL, NULL, NULL, 'Possessive relative — her son.', 'Whose for possession in relative clauses.', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{"Relative clause"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('c238f8a5-3b97-409e-813b-f945217986eb', 380, 'multiple_choice', 'A1', 'pronouns', 'Look at ___! She''s dancing!', 'her', '["she", "her", "hers", "herself"]', NULL, NULL, NULL, 'Object pronoun — what comes after a preposition.', 'Her = object pronoun: Look at her, tell her, call her.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{Pronoun}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('aff4ea8f-c0f7-48e3-94d8-2ee4182034f2', 381, 'multiple_choice', 'A1', 'plurals', 'I have two ___.', 'children', '["child", "childs", "children", "childrens"]', NULL, NULL, NULL, 'Irregular plural — child becomes...?', 'Child → children (irregular plural).', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{Plural}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('fc322493-02dd-46fc-964c-5503aa388659', 382, 'multiple_choice', 'A1', 'plurals', 'There are three ___ on the table.', 'boxes', '["box", "boxs", "boxes", "boxen"]', NULL, NULL, NULL, 'Words ending in -x add -es.', 'Nouns ending in -x: add -es. Box → boxes.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{Plural}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('6d976b3e-ce26-4fd0-ad7c-10d90f757ff0', 612, 'sentence_building', 'B1', 'passive_voice', NULL, 'the meeting was cancelled due to bad weather', '["the", "meeting", "was", "cancelled", "due", "to", "bad", "weather", "because", "of", "good", "held"]', NULL, NULL, NULL, NULL, 'Passive voice (was cancelled) + "due to" or "because of" to give the reason.', '2026-02-12 14:34:46.611844+00', NULL, NULL, 'en', '{"Passive voice"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('9d927433-c8f8-4737-9904-bbe816dcafcd', 657, 'sentence_building', 'B2', 'passive_voice', '', 'the report must be finished by Friday at the latest', '["the", "report", "must", "be", "finished", "by", "Friday", "at", "the", "latest", "is", "finishing", "has"]', NULL, NULL, NULL, NULL, 'Passive modal: must + be + past participle. Expresses obligation with passive voice.', '2026-02-17 09:58:54.170896+00', NULL, NULL, 'en', '{"Passive voice"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('14b4f106-4bf8-41ed-a15e-dfc459db4d46', 383, 'multiple_choice', 'A1', 'plurals', 'I brush my ___ twice a day.', 'teeth', '["tooth", "tooths", "teeth", "teeths"]', NULL, NULL, NULL, 'Irregular plural — tooth becomes...?', 'Tooth → teeth (irregular plural).', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{Plural}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('c738504f-3351-44e2-8d86-696bb531ced4', 543, 'multiple_choice', 'C2', 'idioms', 'She''s been sitting on the ___ about whether to accept the offer.', 'fence', '["gate", "fence", "bench", "wall"]', NULL, NULL, NULL, 'Refusing to take a side — an idiom about a garden boundary.', 'Sit on the fence = avoid making a decision or taking a side.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Fixed expression"}', true, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('54333d78-c6ab-46ee-8e6e-a09d13283cb2', 554, 'multiple_choice', 'C1', 'confusing_words', 'She showed great ___ in handling the crisis.', 'sensitivity', '["sensibility", "sensitivity", "sense", "sensation"]', NULL, NULL, NULL, 'Awareness of others'' feelings — emotional intelligence.', 'Sensitivity = awareness of others'' feelings. Sensibility = ability to appreciate art/feelings.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Confusable words"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('b60b5479-122c-4814-b989-bca4b23be04c', 563, 'multiple_choice', 'C1', 'relative_clauses', 'The report, ___ was published yesterday, confirms our findings.', 'which', '["what", "that", "which", "it"]', NULL, NULL, NULL, 'Non-defining relative (with commas) for things.', 'Non-defining relative clause: use which (not that) with commas.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Relative clause"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('bf5812a2-7d3a-4801-b132-045e90acfe53', 2245, 'multiple_choice', 'A2', 'spanish', '¿A qué hora te ___ por la noche?', 'acuestas', '["acuestas", "levantas", "despiertas", "sientas"]', NULL, NULL, NULL, '"acostarse" = to go to bed.', '"Acostarse" is reflexive: "te acuestas" = "you go to bed".', '2026-06-01 07:29:20.293249+00', NULL, NULL, 'es', '{Vocabulary}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('8ee8087d-e24f-48e0-ab61-5c8d305e811a', 2246, 'multiple_choice', 'A2', 'spanish', 'El avión va a ___ a las diez.', 'despegar', '["despegar", "aterrizar", "parar", "volver"]', NULL, NULL, NULL, '"to take off" — for a plane.', '"Despegar" means "to take off" — used for a plane.', '2026-06-01 07:29:20.293249+00', NULL, NULL, 'es', '{Vocabulary}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('b2dd7a7a-2350-421f-b634-6971bad88716', 2247, 'multiple_choice', 'A2', 'spanish', 'Tienes que ___ la verdad.', 'decir', '["decir", "callar", "mentir", "oír"]', NULL, NULL, NULL, '"to tell / say" the truth.', '"Decir la verdad" means "to tell the truth".', '2026-06-01 07:29:20.293249+00', NULL, NULL, 'es', '{Vocabulary}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('f2b25c47-337c-4aef-bac8-bd0521d1361d', 724, 'error_correction', 'C2', 'relative_clauses', 'The research paper, that was published last year, has been widely cited.', 'The research paper, which was published last year, has been widely cited.', '[]', NULL, NULL, NULL, NULL, 'Non-defining relative clauses (with commas) use "which", not "that".', '2026-02-20 19:09:17.848852+00', NULL, NULL, 'en', '{"Relative clause"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('7e3d0dc7-d47e-4489-a12b-1ab6559e6063', 947, 'multiple_choice', 'A2', 'phrasal_verbs', 'I _______ an old school friend on the street yesterday — what a surprise!', 'ran into', '["ran into", "ran after", "ran out of", "ran away from"]', NULL, NULL, NULL, 'To meet by chance — unexpectedly.', 'To run into someone means to meet them unexpectedly. Compare: run after = to chase; run out of = to have none left.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Phrasal verb"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('c7bcb27f-7ad9-4aee-bc80-e7ec3decd610', 948, 'multiple_choice', 'A2', 'phrasal_verbs', 'She _______ her new computer and installed the software.', 'set up', '["set up", "set out", "set off", "set in"]', NULL, NULL, NULL, 'To install or arrange — get something ready to use.', 'To set up an app or account means to install and configure it for first use. Set up also means to establish a business or organisation.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Phrasal verb"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('8a111f4a-7d91-4156-b381-9a8dafe965d3', 949, 'multiple_choice', 'B1', 'phrasal_verbs', 'The company _______ three new branches across Spain last year.', 'set up', '["set up", "set out", "set off", "set back"]', NULL, NULL, NULL, 'To establish or found (a business, organisation).', 'To set up a branch or office means to establish it. Compare: set out = to begin a journey or explain something; set off = to start a journey or trigger something.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Phrasal verb"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('5fb80f5f-3b72-457d-be90-29f61622e86b', 950, 'multiple_choice', 'B1', 'phrasal_verbs', 'I can''t _______ my new neighbours — they play loud music every night.', 'put up with', '["put up with", "put down with", "put off with", "keep up with"]', NULL, NULL, NULL, 'To tolerate something annoying.', 'To put up with something means to tolerate it, even though it is unpleasant. It is three words — the with is essential.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Phrasal verb"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('f8082df7-319c-46f8-bbbb-f6d1e077f4b5', 951, 'multiple_choice', 'B1', 'phrasal_verbs', 'She _______ some fascinating information while researching her project.', 'came across', '["came across", "came up with", "came around to", "came out with"]', NULL, NULL, NULL, 'To discover by chance — encounter unexpectedly.', 'To come across something means to find or encounter it by chance, without looking for it. Compare: come up with = to think of an idea or solution.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Phrasal verb"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('9d1e9e84-59fe-4e68-a08f-efed1e53c611', 2248, 'multiple_choice', 'A2', 'spanish', 'Vamos a ___ del autobús aquí.', 'bajar', '["bajar", "subir", "entrar", "salir"]', NULL, NULL, NULL, '"bajar de" = to get off.', '"Bajar de" means "to get off" a bus or train.', '2026-06-01 07:29:20.293249+00', NULL, NULL, 'es', '{Vocabulary}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('b5b75829-826f-4148-9e79-258b5e4be030', 1912, 'matching', 'B1', 'grammar', 'Match the beginning of each sentence to its correct ending.', 'match_all_pairs', '[{"left": {"type": "text", "label": "", "content": "I''m looking forward to"}, "right": {"type": "text", "label": "", "content": "seeing you at the weekend."}}, {"left": {"type": "text", "label": "", "content": "He managed to finish"}, "right": {"type": "text", "label": "", "content": "the report before the deadline."}}, {"left": {"type": "text", "label": "", "content": "We''re thinking about"}, "right": {"type": "text", "label": "", "content": "moving to a bigger flat."}}, {"left": {"type": "text", "label": "", "content": "She apologised for"}, "right": {"type": "text", "label": "", "content": "arriving late to the meeting."}}]', NULL, NULL, NULL, NULL, NULL, '2026-04-08 18:25:27.713957+00', NULL, NULL, 'en', '{Grammar,Sentences}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('1016dcc5-c087-4729-bcbb-9e216ed719de', 157, 'multiple_choice', 'B2', 'inversion_negative', 'Never ___ such a beautiful sunset.', 'have I seen', '["I have seen", "have I seen", "I saw", "did I saw"]', NULL, NULL, NULL, 'Inversion after a negative adverb at the start of a sentence.', 'Inversion after negative adverbs (question word order).', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{Inversion}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('920b2b09-469c-43c3-a44f-fca083edd6c9', 413, 'gap_fill', 'C1', 'inversion', 'Not only ___ she speak French, but she also speaks Mandarin.', 'does', NULL, NULL, NULL, NULL, 'Inversion after fronted "Not only" — needs an auxiliary.', 'Inversion after Not only: Not only + auxiliary + subject + verb.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{Inversion}', false, 'Same word order as a question: "Not only ___ she..."', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('c32ce406-0552-464f-8811-4cadd2cccda6', 573, 'multiple_choice', 'C1', 'advanced_grammar', 'He spoke ___ he were an expert, but he clearly wasn''t.', 'as if', '["what if", "as if", "only if", "even if"]', NULL, NULL, NULL, 'Comparison to a hypothetical situation.', 'As if + past subjunctive (were) for unreal present comparisons.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('06ff545a-7543-497a-8c8c-abdae5848c3b', 574, 'multiple_choice', 'C2', 'advanced_grammar', '___ the weather been better, we would have gone hiking.', 'Had', '["If", "Should", "Had", "Were"]', NULL, NULL, NULL, 'Inversion replacing "If the weather had been better".', 'Had + subject + past participle = If the weather had been better. Formal inversion.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('dab7f0ad-9e3f-4a27-bb06-d4456880eb16', 662, 'sentence_building', 'C1', 'inversion', '', 'not only did she pass the exam but she also got the highest mark', '["not", "only", "did", "she", "pass", "the", "exam", "but", "she", "also", "got", "the", "highest", "mark", "passed", "get", "to"]', NULL, NULL, NULL, NULL, 'Not only... but also: emphatic structure with inversion after Not only.', '2026-02-17 09:58:54.170896+00', NULL, NULL, 'en', '{Inversion}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('ed6b5ea8-d6c0-479b-b48b-55abc233b2ef', 721, 'error_correction', 'C1', 'inversion', 'Rarely have I saw such a beautiful sunset.', 'Rarely have I seen such a beautiful sunset.', '[]', NULL, NULL, NULL, NULL, 'After "rarely" at the start of a sentence, we need inversion: "have I seen" using the past participle not the past simple.', '2026-02-20 19:09:17.848852+00', NULL, NULL, 'en', '{Inversion}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('a9d45b3d-4d91-4c99-b6e5-36ffe713fbe3', 707, 'error_correction', 'C1', 'inversion', 'Not only did she passed the exam, but she got the highest mark.', 'Not only did she pass the exam, but she got the highest mark.', '[]', NULL, NULL, NULL, NULL, 'After "Not only" at the start of a sentence, we need inversion, and after the auxiliary did the infinitive: "did she pass".', '2026-02-20 19:09:17.848852+00', NULL, NULL, 'en', '{Inversion}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('61885334-0741-43d8-bb9f-d2c27883e5e4', 694, 'error_correction', 'C2', 'inversion', 'Scarcely had the meeting begun than the fire alarm went off.', 'Scarcely had the meeting begun when the fire alarm went off.', '[]', NULL, NULL, NULL, NULL, '"Scarcely...when" is the correct pattern, not "scarcely...than". Compare: "No sooner...than".', '2026-02-20 19:09:17.848852+00', NULL, NULL, 'en', '{Inversion}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('d0164eb3-d473-4489-971b-6c24f3a682d2', 2249, 'multiple_choice', 'A2', 'spanish', 'No te ___; todo va a salir bien.', 'preocupes', '["preocupes", "alegres", "rías", "duermas"]', NULL, NULL, NULL, '"preocuparse" = to worry.', '"Preocuparse" means "to worry": "no te preocupes" = "don''t worry".', '2026-06-01 07:29:20.293249+00', NULL, NULL, 'es', '{Vocabulary}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('889c04cf-844e-4c88-9463-1ae1c9d2073d', 952, 'multiple_choice', 'B2', 'phrasal_verbs', 'The outdoor concert was _______ due to the storm.', 'called off', '["called off", "called up", "called out", "called back"]', NULL, NULL, NULL, 'To cancel — like cancelling a search party.', 'To call off an event means to cancel it. Compare: call up = to telephone someone; call out = to shout, or to challenge someone.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Phrasal verb"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('770b8efc-e31f-4f4e-aa2a-dba24e77c12e', 1913, 'matching', 'B1', 'vocabulary', 'Match each word to its definition.', 'match_all_pairs', '[{"left": {"type": "text", "label": "", "content": "commute"}, "right": {"type": "text", "label": "", "content": "travel regularly between home and work"}}, {"left": {"type": "text", "label": "", "content": "resign"}, "right": {"type": "text", "label": "", "content": "formally leave a job"}}, {"left": {"type": "text", "label": "", "content": "freelance"}, "right": {"type": "text", "label": "", "content": "work independently for different clients"}}, {"left": {"type": "text", "label": "", "content": "redundant"}, "right": {"type": "text", "label": "", "content": "no longer needed in a job"}}, {"left": {"type": "text", "label": "", "content": "promote"}, "right": {"type": "text", "label": "", "content": "move someone to a higher position"}}]', NULL, NULL, NULL, NULL, NULL, '2026-04-08 18:25:27.713957+00', NULL, NULL, 'en', '{Vocabulary,Work}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('19624b42-7502-4840-93cc-86f1758df9fe', 1914, 'matching', 'B2', 'vocabulary', 'Match each word to its definition.', 'match_all_pairs', '[{"left": {"type": "text", "label": "", "content": "ambiguous"}, "right": {"type": "text", "label": "", "content": "having more than one possible meaning"}}, {"left": {"type": "text", "label": "", "content": "concise"}, "right": {"type": "text", "label": "", "content": "short and clear with no unnecessary words"}}, {"left": {"type": "text", "label": "", "content": "persuasive"}, "right": {"type": "text", "label": "", "content": "able to convince people to agree"}}, {"left": {"type": "text", "label": "", "content": "coherent"}, "right": {"type": "text", "label": "", "content": "logical and easy to understand"}}]', NULL, NULL, NULL, NULL, NULL, '2026-04-08 18:25:27.713957+00', NULL, NULL, 'en', '{Vocabulary}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('f631f4eb-e2d6-491d-8ab5-0794ddeabf80', 725, 'odd_one_out', 'C1', 'inversion', 'Which does NOT use inversion?', 'I always go', '["Never have I", "Seldom does she", "I always go", "Not only did he"]', NULL, NULL, NULL, NULL, '"I always go" uses normal word order. The others use inversion after negative adverbials.', '2026-02-20 19:09:17.848852+00', NULL, NULL, 'en', '{Inversion}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('1cff20da-e4a8-43e7-8391-b2b31a7cbd6f', 8, 'gap_fill', 'B2', 'modal_deduction_past', 'The lights are off. They ___ (must / go) out already.', 'must have gone', NULL, NULL, NULL, NULL, 'Must have + past participle for logical deductions about the past', 'Must have + past participle expresses a logical conclusion about something in the past.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{"Modal verb"}', false, 'Form: must have + past participle. The lights are off — they''re definitely not home.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('f044539c-edee-4f5c-b545-d358e9f25cf6', 103, 'multiple_choice', 'B1', 'modals_obligation', 'You ___ wear a seatbelt in the car. It''s the law.', 'must', '["may", "could", "must", "might"]', NULL, NULL, NULL, 'It''s the law — strong obligation, not just advice or possibility.', 'Must for strong obligation or rules/laws.', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{"Modal verb"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('328e53bf-99bc-46bf-baec-1b605f1c88c2', 123, 'multiple_choice', 'B1', 'modals_ability', 'When I was younger, I ___ run very fast.', 'could', '["can", "could", "was able", "managed"]', NULL, NULL, NULL, 'Past form of "can" for ability.', 'Could for general past ability.', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{"Modal verb"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('ecfec3e3-e53a-497d-84a4-3a95345f45eb', 129, 'multiple_choice', 'B2', 'modals_no_obligation', 'You ___ come to the party if you don''t want to.', 'don''t have to', '["mustn''t", "don''t have to", "can''t", "have to"]', NULL, NULL, NULL, 'It''s optional — not banned. (Watch out for "mustn''t" — that''s prohibition!)', 'Don''t have to means no obligation.', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{"Modal verb"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('d5b550e6-a04b-42d3-a9e8-5f4b196c11cd', 149, 'multiple_choice', 'B2', 'modals_deduction_past', 'They''re not here. They ___ forgotten about the meeting.', 'must have', '["must", "must have", "should", "should have"]', NULL, NULL, NULL, 'Past deduction — strong certainty about the past. Form: must have + past participle.', 'Must have + past participle for logical deductions about the past.', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{"Modal verb"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('1a205282-6429-4ea1-a3b0-8eb55af68171', 665, 'sentence_building', 'C1', 'inversion', 'De haberlo sabido, habria actuado de otra manera.', 'had I known I would have acted differently', '["had", "I", "known", "I", "would", "have", "acted", "differently", "did", "knowing", "been", "other"]', NULL, NULL, NULL, NULL, 'Inverted third conditional: Had + subject + past participle, would have + past participle.', '2026-02-17 09:58:54.170896+00', NULL, NULL, 'en', '{Inversion}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('7c921161-be71-4775-be8b-a92841ebc019', 666, 'sentence_building', 'C2', 'inversion', '', 'seldom have I encountered such a thoroughly convincing argument', '["seldom", "have", "I", "encountered", "such", "a", "thoroughly", "convincing", "argument", "hardly", "an", "has", "encounter"]', NULL, NULL, NULL, NULL, 'Negative adverb inversion: Seldom + auxiliary + subject. Very formal and emphatic.', '2026-02-17 09:58:54.170896+00', NULL, NULL, 'en', '{Inversion}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('73c9ec88-d384-4632-b6c0-f6eb34a4d212', 271, 'gap_fill', 'A1', 'can_and_cant', 'She ___ (can / swim) very well.', 'can swim', NULL, NULL, NULL, NULL, 'Can + base verb.', 'Can + base verb for ability. No -s for third person.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Modal verb"}', false, 'Can never changes form: I can, she can, they can.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('b5351ad1-b89e-4f2c-9e19-a1ce93022440', 272, 'gap_fill', 'A1', 'can_and_cant', 'I ___ (not can / drive).', 'can''t drive', NULL, NULL, NULL, NULL, 'Negative of can — short form.', 'Can''t / cannot + base verb for inability.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Modal verb"}', false, 'Can''t = cannot.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('390fbb0c-549d-48a5-87c5-671a650a2d29', 384, 'multiple_choice', 'A2', 'plurals', 'There are a lot of ___ in this city.', 'people', '["person", "persons", "people", "peoples"]', NULL, NULL, NULL, 'Irregular plural — person becomes...?', 'Person → people (the most common plural form).', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{Plural}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('6386a847-9b17-440d-9d1a-7594e6d7c094', 385, 'multiple_choice', 'A1', 'plurals', 'Two ___ of wine, please.', 'glasses', '["glass", "glasses", "glasss", "cups"]', NULL, NULL, NULL, 'Words ending in -ss add -es.', 'Nouns ending in -ss: add -es. Glass → glasses.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{Plural}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('2f540098-4aee-4d8b-aba1-f64a6370ff55', 386, 'multiple_choice', 'A2', 'countability', 'Can you give me some ___?', 'advice', '["the advices", "advice", "advices", "an advice"]', NULL, NULL, NULL, 'Always uncountable — no -s ever.', 'Advice is uncountable: some advice (never advices).', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Uncountable noun"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('c815ea6d-8da5-4e99-b34c-872ca34f5bbe', 387, 'multiple_choice', 'A2', 'countability', 'I need ___ information about the course.', 'some', '["a", "an", "some", "many"]', NULL, NULL, NULL, 'Information is uncountable.', 'Information is uncountable: some information.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Uncountable noun"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('980df10b-ff24-4a90-a9e4-8a9d8453c251', 388, 'multiple_choice', 'A2', 'countability', 'She has long ___.', 'hair', '["a hair", "the hairs", "hair", "hairs"]', NULL, NULL, NULL, 'Hair on your head is uncountable (no -s).', 'Hair (on your head) is uncountable in English.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Uncountable noun"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('a7ab8712-91ad-415f-88a0-b2143aa590ab', 956, 'gap_fill', 'B2', 'phrasal_verbs', 'He asked for a pay rise twice, but his manager ___ his request both times.', 'turned down', NULL, NULL, NULL, NULL, 'Phrasal verb meaning to reject (a request, an offer).', 'To turn someone down means to reject their request. Note that down comes after the object (him), not after the verb.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Phrasal verb"}', false, 'Two words. Starts with t___ d___.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('7f800de7-9be5-455c-9d02-2039cf555b70', 954, 'gap_fill', 'B1', 'phrasal_verbs', 'The new product really _______ in the market — sales tripled in a month.', 'took off', NULL, NULL, NULL, NULL, 'To suddenly become successful — like an aeroplane leaving the runway.', 'To take off means to become suddenly successful — sales, a career, or a trend. The same phrasal verb is used for planes leaving the ground.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Phrasal verb"}', false, 'Two words. Past tense. Starts with t___ o___.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('7b1cb899-8570-4d04-be68-18f62f82a572', 953, 'multiple_choice', 'B2', 'phrasal_verbs', 'After months of negotiation, the two companies finally _______ a deal.', 'came up with', '["came up with", "came across", "came around", "came out with"]', NULL, NULL, NULL, 'To invent or think of (a deal, an idea, a solution).', 'To come up with something means to think of or produce an idea, plan, or solution. It implies effort or creativity.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Phrasal verb"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('b02b855b-50b3-4357-afa9-5e3fc527487a', 2250, 'multiple_choice', 'A2', 'travel', 'I''d like to ___ a room for two nights.', 'book', '["book", "buy", "make", "take"]', NULL, NULL, NULL, 'Reserve it in advance.', 'To "book" a room means to reserve it in advance.', '2026-06-01 07:33:21.080816+00', NULL, NULL, 'en', '{Travel}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('d04cfbcc-7a51-4a6c-a555-2577fa52606b', 2251, 'multiple_choice', 'A2', 'travel', 'We''re flying ___ Madrid on Friday.', 'to', '["to", "at", "in", "for"]', NULL, NULL, NULL, 'Shows movement towards a destination.', 'We use "to" for movement towards a destination: "flying to Madrid".', '2026-06-01 07:33:21.080816+00', NULL, NULL, 'en', '{Travel}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('054b27fe-ec6e-40c5-9e53-f771da1f7eaa', 2252, 'multiple_choice', 'A2', 'travel', 'Don''t forget your ___ — you can''t fly without it.', 'passport', '["passport", "ticket", "suitcase", "map"]', NULL, NULL, NULL, 'The document that proves your identity abroad.', 'A "passport" is the document proving your identity when you travel abroad.', '2026-06-01 07:33:21.080816+00', NULL, NULL, 'en', '{Travel}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('5790afd2-aa1e-4f96-91f9-5bde44fa2f0c', 2253, 'multiple_choice', 'A2', 'travel', 'The hotel has a lovely swimming ___.', 'pool', '["pool", "bath", "sea", "lake"]', NULL, NULL, NULL, 'Where you swim at a hotel.', 'A "swimming pool" is where you swim at a hotel.', '2026-06-01 07:33:21.080816+00', NULL, NULL, 'en', '{Travel}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('0d286998-f06c-4121-a423-1b9747ac33ee', 1915, 'matching', 'B1', 'grammar', 'Match each modal verb to its meaning.', 'match_all_pairs', '[{"left": {"type": "text", "label": "", "content": "must"}, "right": {"type": "text", "label": "", "content": "it is necessary, or I am sure it is true"}}, {"left": {"type": "text", "label": "", "content": "might"}, "right": {"type": "text", "label": "", "content": "it is possible"}}, {"left": {"type": "text", "label": "", "content": "should"}, "right": {"type": "text", "label": "", "content": "it is the right thing to do"}}, {"left": {"type": "text", "label": "", "content": "can''t"}, "right": {"type": "text", "label": "", "content": "it is impossible, or I am sure it is not true"}}]', NULL, NULL, NULL, NULL, NULL, '2026-04-08 18:25:27.713957+00', NULL, NULL, 'en', '{Grammar,"Modal verb"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('ea513d84-2854-4cda-ae69-b04b310682ed', 389, 'multiple_choice', 'A2', 'countability', 'We bought some new ___.', 'furniture', '["furnitures", "the furnitures", "a furniture", "furniture"]', NULL, NULL, NULL, 'Furniture is uncountable.', 'Furniture is uncountable: some furniture, a piece of furniture.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Uncountable noun"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('8b9403fd-d43d-4a24-91dc-048a21b646d7', 2205, 'multiple_choice', 'A2', 'spanish', 'El ___ es mi día favorito de la semana.', 'sábado', '["sábado", "enero", "verano", "reloj"]', NULL, NULL, NULL, 'You need a day of the week.', '"Sábado" (Saturday) is a day of the week.', '2026-06-01 07:21:37.506938+00', NULL, NULL, 'es', '{Vocabulary}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('bb07f3bb-ab2d-4b42-b1ed-a1853a2c3b95', 2206, 'multiple_choice', 'A2', 'spanish', 'Quiero ___ una mesa para dos personas.', 'reservar', '["reservar", "comer", "abrir", "pagar"]', NULL, NULL, NULL, '"to book / reserve" a table.', '"Reservar" means "to book" or "to reserve".', '2026-06-01 07:21:37.506938+00', NULL, NULL, 'es', '{Vocabulary}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('9d505025-2851-4a6a-bbea-c273d5dc275a', 2207, 'multiple_choice', 'A2', 'spanish', 'Mi hermana ___ inglés y francés.', 'habla', '["habla", "come", "vive", "lee"]', NULL, NULL, NULL, '"speaks" languages.', '"Habla" is the form of "hablar" (to speak) for "she": "habla inglés".', '2026-06-01 07:21:37.506938+00', NULL, NULL, 'es', '{Vocabulary}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('e17943fa-f86e-4f5d-abf6-03ef82608ac9', 111, 'multiple_choice', 'B2', 'modals_deduction', 'She''s not answering her phone. She ___ be in a meeting.', 'must', '["can''t", "ought to", "must", "should"]', NULL, NULL, NULL, 'Logical certainty — you''re sure she''s in a meeting. Not advice, not impossibility.', 'Must for logical deductions (high certainty).', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{"Modal verb"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('0b6719be-66df-42a1-8197-21dd48077731', 152, 'multiple_choice', 'B1', 'can_could_permission', '___ I borrow your pen for a moment?', 'Can', '["Need", "Can", "Must", "Should"]', NULL, NULL, NULL, 'Asking for permission, informally — between friends.', 'Can/Could for asking permission.', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{"Modal verb"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('ec7f6681-b1f3-436c-8b00-7a91285c175d', 173, 'multiple_choice', 'B1', 'modal_can_ability', 'I ___ swim when I was five years old.', 'could', '["can", "could", "may", "might"]', NULL, NULL, NULL, 'Past form of "can" for ability.', 'Could for past ability.', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{"Modal verb"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('d2a080b7-d120-4e96-a617-b9b6942c61c5', 273, 'gap_fill', 'A1', 'can_and_cant', '___ you help me?', 'Can', NULL, NULL, NULL, '["could"]', 'Question with can — verb first.', 'Questions with can: Can + subject + base verb.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Modal verb"}', false, '___ + subject + base verb?', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('fee79111-9cb2-4942-92e0-42976dfa0177', 274, 'gap_fill', 'A2', 'can_and_cant', 'He ___ (can / speak) three languages.', 'can speak', NULL, NULL, NULL, NULL, 'Can + base verb.', 'Can for ability: he can speak (not he cans speak).', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Modal verb"}', false, 'Can stays the same for he/she/it (no -s!).', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('376eea6e-66a4-4c44-9fe4-d215dde2b767', 275, 'gap_fill', 'A1', 'can_and_cant', 'We ___ (not can / come) to the party.', 'can''t come', NULL, NULL, NULL, NULL, 'We + can''t + base verb.', 'Can''t + base verb for things that are not possible.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Modal verb"}', false, 'Can''t = cannot.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('ab13d50b-e0ba-418a-9f44-7adb10b4f2fa', 277, 'gap_fill', 'A1', 'can_and_cant', 'My grandmother ___ (not can / hear) very well.', 'can''t hear', NULL, NULL, NULL, NULL, 'She + can''t + base verb.', 'Can''t for inability. No auxiliary verb needed.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Modal verb"}', false, 'Can''t is the same for everyone.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('368759ea-62b3-40c8-8a15-34115864ddd5', 278, 'gap_fill', 'A2', 'can_and_cant', 'You ___ (can / park) here, it''s free.', 'can park', NULL, NULL, NULL, NULL, 'Can + base verb.', 'Can for permission: you are allowed to park here.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Modal verb"}', false, 'Can = it''s possible/allowed.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('b8ceade6-1b40-4967-9b69-ed258b35dd1d', 390, 'multiple_choice', 'A1', 'plurals', 'There are lots of ___ in the park.', 'women', '["woman", "womans", "women", "womens"]', NULL, NULL, NULL, 'Irregular plural — woman becomes...?', 'Woman → women (irregular plural).', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{Plural}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('43b94bb8-8831-40f9-941d-1cc94ef0d871', 391, 'multiple_choice', 'A2', 'like_and_would_like', 'I ___ pizza. It''s my favourite food.', 'like', '["liked", "would like", "am liking", "like"]', NULL, NULL, NULL, 'Habitual feeling — present simple.', 'Like = enjoy in general (permanent). Would like = want now.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Modal verb"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('865578e5-a12b-4c98-8867-d50fec1812ea', 699, 'error_correction', 'C1', 'modal_perfects', 'The project should have being completed by last month.', 'The project should have been completed by last month.', '[]', NULL, NULL, NULL, NULL, 'In passive modal perfect, we need the past participle: "been", not "being".', '2026-02-20 19:09:17.848852+00', NULL, NULL, 'en', '{"Modal verb"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('c9879bc8-9e7f-4c0c-8db6-b24a5bcb0da4', 1832, 'gap_fill', 'A2', 'spanish', 'El año pasado mi familia y yo _______ de vacaciones a Portugal. Fue un viaje increíble.', 'fuimos', NULL, NULL, NULL, NULL, NULL, 'Ir en pretérito indefinido, primera persona del plural: fuimos.', '2026-04-06 16:43:51.906934+00', NULL, NULL, 'es', '{Spanish}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('c18ed2e1-a2f8-409d-8a1c-7de58b81751c', 961, 'gap_fill', 'C1', 'phrasal_verbs', 'The CEO attempted to _______ the financial irregularities, but the auditors found everything.', 'cover up', NULL, NULL, NULL, NULL, 'To conceal — hide wrongdoing from view.', 'To cover up means to hide or conceal something — usually wrongdoing or a mistake. The noun form is a cover-up.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Phrasal verb"}', false, 'Two words. Starts with c___ u___.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('962f83c3-51e6-4c22-a835-a407ab2aa2cc', 1182, 'odd_one_out', 'A2', 'spanish', '¿Cuál de estas palabras NO describe el tiempo atmosférico?', 'hambriento', '["soleado", "nublado", "hambriento", "lluvioso"]', NULL, NULL, NULL, NULL, '"Hambriento" significa que tienes ganas de comer — describe un estado físico, no el tiempo atmosférico. Soleado, nublado y lluvioso describen condiciones meteorológicas.', '2026-03-16 08:29:27.085219+00', NULL, NULL, 'es', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('f7344206-0cec-4235-be7e-558d98320410', 653, 'sentence_building', 'B1', 'modal_verbs', '', 'you should have told me about the meeting earlier', '["you", "should", "have", "told", "me", "about", "the", "meeting", "earlier", "must", "tell", "lately"]', NULL, NULL, NULL, NULL, 'Should have + past participle: criticism or regret about the past.', '2026-02-17 09:58:54.170896+00', NULL, NULL, 'en', '{"Modal verb"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('6ad6a074-e7ac-48d4-a675-5a09ef107d7b', 613, 'sentence_building', 'C1', 'modal_perfects', NULL, 'we should have finished the report earlier', '["we", "should", "have", "finished", "the", "report", "earlier", "must", "complete", "later"]', NULL, NULL, NULL, NULL, '"Should have + past participle" expresses regret about a past action.', '2026-02-12 14:34:46.611844+00', NULL, NULL, 'en', '{"Modal verb"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('3459b1bd-c886-49ba-9737-975e627cb443', 1183, 'odd_one_out', 'A2', 'spanish', '¿Cuál de estas palabras NO es un pronombre personal?', 'mi', '["yo", "tú", "ella", "mi"]', NULL, NULL, NULL, NULL, '"Mi" es un determinante posesivo, no un pronombre personal. Yo, tú y ella son pronombres personales que se usan para referirse a personas.', '2026-03-16 08:29:27.085219+00', NULL, NULL, 'es', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('89938cc5-5dba-4714-9dc9-2a50ac49955f', 1184, 'odd_one_out', 'A2', 'spanish', '¿Cuál de estas palabras NO es un día de la semana?', 'finde', '["lunes", "miércoles", "finde", "viernes"]', NULL, NULL, NULL, NULL, '"Finde" es una palabra corta usado en vez de ''fin de semana'', no un día de la semana. Lunes, miércoles y viernes son todos días de la semana.', '2026-03-16 08:29:27.085219+00', NULL, NULL, 'es', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('43e4da7e-d7a4-4744-986b-f1142f21903b', 608, 'sentence_building', 'C1', 'modal_perfects', 'El proyecto debería haberse terminado el mes pasado.', 'the project should have been completed last month', '["the", "project", "should", "have", "been", "completed", "last", "month", "must", "finish", "next"]', NULL, NULL, NULL, NULL, 'Modal perfect passive: should have been + past participle. Expresses that something was expected but did not happen.', '2026-02-12 15:08:31.507807+00', NULL, NULL, 'en', '{"Modal verb"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('6032d802-444b-4afa-a0c9-fac3bf1868e6', 620, 'sentence_building', 'B1', 'modal_verbs', NULL, 'you should always check your emails before leaving the office', '["you", "should", "always", "check", "your", "emails", "before", "leaving", "the", "office", "never", "soon", "arrive"]', NULL, NULL, NULL, NULL, '"Should" for advice. "Before + gerund" (before leaving). Adverb "always" goes between modal and main verb.', '2026-02-12 14:34:46.611844+00', NULL, NULL, 'en', '{"Modal verb"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('f977eed4-3189-4200-a086-8cf5580f78cd', 2210, 'multiple_choice', 'A2', 'phrasal_verbs', 'What time do you ___ in the morning?', 'get up', '["get up", "get on", "get off", "get in"]', NULL, NULL, NULL, 'Leave your bed after sleeping.', '"Get up" means to leave your bed after sleeping.', '2026-06-01 07:29:20.293249+00', NULL, NULL, 'en', '{"Phrasal verb"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('151b731d-3fc1-4055-a86f-7a209288915b', 4, 'gap_fill', 'B1', 'modals_advice', 'You ___ (should / verb) a doctor about that cough. It sounds serious.', 'should see', NULL, NULL, NULL, '[{"answer": "should be seeing", "feedback": "This isn''t wrong, but ''should see'' is more natural for giving advice about a single action."}]', 'Use should + infinitive for giving advice', 'Should + infinitive is used to give advice or recommendations.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{"Modal verb"}', false, 'Form: should + infinitive (no "to" needed after should).', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('b0bee205-fa3e-4ebf-aa84-30d9ca6b5c5b', 709, 'error_correction', 'A1', 'modal_verbs', 'He can speaks English very well.', 'He can speak English very well.', '[]', NULL, NULL, NULL, NULL, 'After modal verbs (can, could, should), we use the base form without "s".', '2026-02-20 19:09:17.848852+00', NULL, NULL, 'en', '{"Modal verb"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('b0f87e75-90bf-4a33-86cf-376174743564', 2211, 'multiple_choice', 'A2', 'phrasal_verbs', 'Please ___ your shoes before you come in.', 'take off', '["take off", "put on", "take up", "turn off"]', NULL, NULL, NULL, 'Remove them.', '"Take off" means to remove clothing or shoes.', '2026-06-01 07:29:20.293249+00', NULL, NULL, 'en', '{"Phrasal verb"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('84fabf2a-f3ae-4b10-be41-839101a7163d', 2212, 'multiple_choice', 'A2', 'phrasal_verbs', 'I need to ___ early tomorrow for my flight.', 'wake up', '["wake up", "wake off", "get over", "look up"]', NULL, NULL, NULL, 'Stop sleeping.', '"Wake up" means to stop sleeping.', '2026-06-01 07:29:20.293249+00', NULL, NULL, 'en', '{"Phrasal verb"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('8cddec8e-d72e-485c-ac03-05d0b3a7c205', 2254, 'multiple_choice', 'A2', 'travel', 'What time does the train ___?', 'leave', '["leave", "go out", "start", "open"]', NULL, NULL, NULL, 'Depart from the station.', 'A train "leaves" (departs) the station at a set time.', '2026-06-01 07:33:21.080816+00', NULL, NULL, 'en', '{Travel}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('ad316e6b-c308-4d15-8cfc-50dfe1999011', 2255, 'multiple_choice', 'A2', 'travel', 'We stayed ___ a small hotel near the beach.', 'in', '["in", "on", "to", "by"]', NULL, NULL, NULL, 'Used for being inside a building.', 'We use "in" for being inside a building: "stayed in a small hotel".', '2026-06-01 07:33:21.080816+00', NULL, NULL, 'en', '{Travel}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('72626f90-24f5-4aa2-84bd-fdf7dfd245c8', 426, 'gap_fill', 'C1', 'modal_perfects', 'They ___ (might / get) lost. Let me call them.', 'might have got', NULL, '["might''ve got", "might''ve gotten"]', NULL, NULL, 'Past possibility — uncertain about what happened.', 'Might have + past participle for possibility about the past (not certain). Gotten more American than the English got, but both are ok. ', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Modal verb"}', false, 'Form: might have + past participle.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('21148bd5-f00b-4566-8585-0bc97cbb76fc', 430, 'gap_fill', 'C1', 'modal_perfects', 'She ___ (would / love) to see the show, but she was working.', 'would have loved', NULL, '["would''ve loved"]', NULL, NULL, 'Hypothetical past — she didn''t see it.', 'Would have + past participle for imagined/wished situations in the past.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Modal verb"}', false, 'Form: would have + past participle.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('032c0418-6fa2-4637-9f50-fc381d6089c3', 432, 'gap_fill', 'C1', 'modal_perfects', 'He looks exhausted. He ___ (must / work) all night.', 'must have been working', NULL, '["must''ve worked", "must''ve been working"]', NULL, NULL, 'Deduction about a past ongoing action.', 'Must have been + verb-ing for deductions about continuous past actions.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Modal verb"}', false, 'Form: must have been + verb-ing.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('e3932d6b-c1c9-47af-8507-92a3108559fe', 962, 'gap_fill', 'C1', 'phrasal_verbs', 'The experienced detective _______ the suspect''s false alibi immediately.', 'saw through', NULL, NULL, NULL, NULL, 'To perceive deception — see beyond the lies.', 'To see through something means to recognise that it is false or deceptive, despite an attempt to hide the truth.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Phrasal verb"}', false, 'Two words. Past tense. Starts with s___ t___.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('24bc44ae-7e66-486e-ba0f-714cee8ee833', 678, 'odd_one_out', 'C1', 'word_formation', 'Which is NOT a word with a negative prefix?', 'important', '["unlikely", "disappear", "important", "irregular"]', NULL, NULL, NULL, NULL, '"Important" has no negative prefix. Un-, dis-, and ir- are all negative prefixes.', '2026-02-20 19:09:17.848852+00', NULL, NULL, 'en', '{"Word formation"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('a1b2c3d4-0935-0935-0935-000000000935', 935, 'matching', 'C1', 'pronunciation', 'Listen and match each sound to the word and its meaning.', 'match_all_pairs', '[{"left": {"type": "audio", "label": "Sound 1", "content": "https://dyxmgicedabvmsbuvxny.supabase.co/storage/v1/object/public/audio/matching/Bow%20-%20weapon.mp3"}, "right": {"type": "text", "content": "bow — a weapon for shooting arrows"}}, {"left": {"type": "audio", "label": "Sound 2", "content": "https://dyxmgicedabvmsbuvxny.supabase.co/storage/v1/object/public/audio/matching/Row%20-%20verb.mp3"}, "right": {"type": "text", "content": "row — to propel a boat using oars"}}, {"left": {"type": "audio", "label": "Sound 3", "content": "https://dyxmgicedabvmsbuvxny.supabase.co/storage/v1/object/public/audio/matching/Tear%20-%20cry.mp3"}, "right": {"type": "text", "content": "tear — a drop of water from your eye"}}, {"left": {"type": "audio", "label": "Sound 4", "content": "https://dyxmgicedabvmsbuvxny.supabase.co/storage/v1/object/public/audio/matching/Wind%20-%20weather.mp3"}, "right": {"type": "text", "content": "wind — moving air; a weather condition"}}, {"left": {"type": "audio", "label": "Sound 5", "content": "https://dyxmgicedabvmsbuvxny.supabase.co/storage/v1/object/public/audio/matching/Live%20-%20verb.mp3"}, "right": {"type": "text", "content": "live — to exist; to be alive"}}]', NULL, NULL, NULL, NULL, 'Each of these five words has a second pronunciation with a completely different meaning. You''ll hear them next!', '2026-03-04 08:58:34.770181+00', 'heteronyms_1', 1, 'en', '{Pronunciation}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('94ecbccf-11fe-4779-88cd-63582bd47886', 424, 'gap_fill', 'C1', 'modal_perfects', 'He ___ (can''t / be) at the party. He was in hospital.', 'can''t have been', NULL, NULL, NULL, NULL, 'Logical impossibility about the past.', 'Can''t have + past participle for something you believe is impossible in the past. Using could instead of can here is also acceptable. ', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Modal verb"}', false, 'Form: can''t have + past participle.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('a1b2c3d4-0936-0936-0936-000000000936', 936, 'matching', 'C1', 'pronunciation', 'The same words — but now with their second pronunciation. Listen and match.', 'match_all_pairs', '[{"left": {"type": "audio", "label": "Sound 1", "content": "https://dyxmgicedabvmsbuvxny.supabase.co/storage/v1/object/public/audio/matching/Bow%20-%20verb.mp3"}, "right": {"type": "text", "content": "bow — to bend forward as a sign of respect"}}, {"left": {"type": "audio", "label": "Sound 2", "content": "https://dyxmgicedabvmsbuvxny.supabase.co/storage/v1/object/public/audio/matching/Row%20-%20argue.mp3"}, "right": {"type": "text", "content": "row — a noisy argument"}}, {"left": {"type": "audio", "label": "Sound 3", "content": "https://dyxmgicedabvmsbuvxny.supabase.co/storage/v1/object/public/audio/matching/Tear%20-%20rip.mp3"}, "right": {"type": "text", "content": "tear — to rip something apart"}}, {"left": {"type": "audio", "label": "Sound 4", "content": "https://dyxmgicedabvmsbuvxny.supabase.co/storage/v1/object/public/audio/matching/Wind%20-%20verb.mp3"}, "right": {"type": "text", "content": "wind — to coil or wrap something around an object"}}, {"left": {"type": "audio", "label": "Sound 5", "content": "https://dyxmgicedabvmsbuvxny.supabase.co/storage/v1/object/public/audio/matching/Live%20-%20adjective.mp3"}, "right": {"type": "text", "content": "live — happening now; in front of an audience"}}]', NULL, NULL, NULL, NULL, 'Same spelling, completely different sound and meaning. These are called heteronyms. bow /boʊ/ vs /baʊ/ · row /roʊ/ vs /raʊ/ · tear /tɪər/ vs /tɛr/ · wind /wɪnd/ vs /waɪnd/ · live /lɪv/ vs /laɪv/', '2026-03-04 08:58:34.770181+00', 'heteronyms_1', 2, 'en', '{Pronunciation}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('a1b2c3d4-0938-0938-0938-000000000938', 938, 'matching', 'C1', 'pronunciation', 'Listen and match each pronunciation to the sentence that uses it correctly.', 'match_all_pairs', '[{"left": {"type": "audio", "label": "Sound 1", "content": "https://dyxmgicedabvmsbuvxny.supabase.co/storage/v1/object/public/audio/matching/Bow%20-%20verb.mp3"}, "right": {"type": "text", "content": "The actors came out to bow at the end of the show."}}, {"left": {"type": "audio", "label": "Sound 2", "content": "https://dyxmgicedabvmsbuvxny.supabase.co/storage/v1/object/public/audio/matching/Row%20-%20verb.mp3"}, "right": {"type": "text", "content": "She learned to row a boat on the lake."}}, {"left": {"type": "audio", "label": "Sound 3", "content": "https://dyxmgicedabvmsbuvxny.supabase.co/storage/v1/object/public/audio/matching/Tear%20-%20rip.mp3"}, "right": {"type": "text", "content": "Be careful not to tear the paper when you open it."}}, {"left": {"type": "audio", "label": "Sound 4", "content": "https://dyxmgicedabvmsbuvxny.supabase.co/storage/v1/object/public/audio/matching/Wind%20-%20verb.mp3"}, "right": {"type": "text", "content": "Wind the cable around the reel before you store it."}}, {"left": {"type": "audio", "label": "Sound 5", "content": "https://dyxmgicedabvmsbuvxny.supabase.co/storage/v1/object/public/audio/matching/Live%20-%20adjective.mp3"}, "right": {"type": "text", "content": "The concert was broadcast live to millions of viewers."}}]', NULL, NULL, NULL, NULL, 'bow /baʊ/ (bend) · row /roʊ/ (boat) · tear /tɛr/ (rip) · wind /waɪnd/ (coil) · live /laɪv/ (adjective)', '2026-03-04 08:58:34.770181+00', 'heteronyms_1', 4, 'en', '{Pronunciation}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('dd1a2ce8-ff4e-468f-8deb-d402171c8d14', 2256, 'multiple_choice', 'A2', 'travel', 'Can I see the ___, please? I want to order food.', 'menu', '["menu", "bill", "receipt", "key"]', NULL, NULL, NULL, 'The list of dishes in a restaurant.', 'A "menu" is the list of dishes available in a restaurant.', '2026-06-01 07:33:21.080816+00', NULL, NULL, 'en', '{Travel}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('a03ce063-abba-41fe-a94e-0f4c846a588e', 1115, 'gap_fill', 'C2', 'business_vocabulary', 'The concept of corporate social _______ holds that a company has obligations not just to shareholders, but to employees, customers, and communities.', 'responsibility', NULL, NULL, NULL, NULL, 'Paired with "corporate" and "social" — often abbreviated as CSR.', 'Corporate social responsibility (CSR) is the idea that companies have obligations beyond profit — to employees, communities, the environment, and society as a whole.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Business vocabulary",Collocation}', false, 'What companies have when they''re answerable for their actions.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('816c0101-8d78-4561-9a04-caafd19b50dc', 1227, 'multiple_choice', 'A1', 'business_phrasal_verbs', 'We need to _____ a new supplier before the end of the month.', 'take on', '["take on", "take off", "take up", "take over"]', NULL, NULL, NULL, 'To engage (a supplier, an employee).', 'Take on means to hire someone or start using a new supplier or partner.', '2026-03-18 19:58:52.376507+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('3b42e4a7-906c-4bb4-b8f4-1e6494752a23', 2257, 'multiple_choice', 'A2', 'travel', 'Our flight was ___ by two hours.', 'delayed', '["delayed", "late", "slow", "stopped"]', NULL, NULL, NULL, 'Made to happen later than planned.', 'A flight that is "delayed" is made to happen later than planned.', '2026-06-01 07:33:21.080816+00', NULL, NULL, 'en', '{Travel}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('c42331ae-8ec2-447e-ac68-15b0722dc408', 2258, 'multiple_choice', 'A2', 'travel', 'I need to ___ in at the airport two hours early.', 'check', '["check", "book", "sign", "log"]', NULL, NULL, NULL, '"___ in" for a flight.', '"Check in" means to register for a flight at the airport.', '2026-06-01 07:33:21.080816+00', NULL, NULL, 'en', '{Travel}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('9c3a459e-b683-44fc-afe9-ae26ff096417', 392, 'multiple_choice', 'A2', 'like_and_would_like', 'I ___ a coffee, please.', 'would like', '["like", "would like", "am liking", "liked"]', NULL, NULL, NULL, 'Polite request for something now.', 'Would like = polite way to say want. For ordering/requesting.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Modal verb"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('a1b2c3d4-0937-0937-0937-000000000937', 937, 'matching', 'C1', 'pronunciation', 'Listen and match each sound to its definition. No word is shown this time.', 'match_all_pairs', '[{"left": {"type": "audio", "label": "Sound 1", "content": "https://dyxmgicedabvmsbuvxny.supabase.co/storage/v1/object/public/audio/matching/Bow%20-%20weapon.mp3"}, "right": {"type": "text", "content": "a curved piece of wood used to shoot arrows"}}, {"left": {"type": "audio", "label": "Sound 2", "content": "https://dyxmgicedabvmsbuvxny.supabase.co/storage/v1/object/public/audio/matching/Row%20-%20argue.mp3"}, "right": {"type": "text", "content": "a loud and angry dispute"}}, {"left": {"type": "audio", "label": "Sound 3", "content": "https://dyxmgicedabvmsbuvxny.supabase.co/storage/v1/object/public/audio/matching/Tear%20-%20cry.mp3"}, "right": {"type": "text", "content": "the salty liquid that falls from your eye when you cry"}}, {"left": {"type": "audio", "label": "Sound 4", "content": "https://dyxmgicedabvmsbuvxny.supabase.co/storage/v1/object/public/audio/matching/Wind%20-%20verb.mp3"}, "right": {"type": "text", "content": "to twist or wrap something carefully around an object"}}, {"left": {"type": "audio", "label": "Sound 5", "content": "https://dyxmgicedabvmsbuvxny.supabase.co/storage/v1/object/public/audio/matching/Live%20-%20verb.mp3"}, "right": {"type": "text", "content": "to have life; to exist and breathe"}}]', NULL, NULL, NULL, NULL, 'Mixed pronunciations — you need to identify both the sound AND the meaning. bow /boʊ/ · row /raʊ/ · tear /tɪər/ · wind /waɪnd/ · live /lɪv/', '2026-03-04 08:58:34.770181+00', 'heteronyms_1', 3, 'en', '{Pronunciation}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('a1b2c3d4-0931-0931-0931-000000000931', 931, 'matching', 'A2', 'pronunciation', 'Listen and match each sound to the correct word.', 'match_all_pairs', '[{"left": {"type": "audio", "label": "Sound 1", "content": "https://dyxmgicedabvmsbuvxny.supabase.co/storage/v1/object/public/audio/matching/ship.mp3"}, "right": {"type": "text", "content": "ship"}}, {"left": {"type": "audio", "label": "Sound 2", "content": "https://dyxmgicedabvmsbuvxny.supabase.co/storage/v1/object/public/audio/matching/bit.mp3"}, "right": {"type": "text", "content": "bit"}}, {"left": {"type": "audio", "label": "Sound 3", "content": "https://dyxmgicedabvmsbuvxny.supabase.co/storage/v1/object/public/audio/matching/sit.mp3"}, "right": {"type": "text", "content": "sit"}}, {"left": {"type": "audio", "label": "Sound 4", "content": "https://dyxmgicedabvmsbuvxny.supabase.co/storage/v1/object/public/audio/matching/Live%20-%20verb.mp3"}, "right": {"type": "text", "content": "live"}}, {"left": {"type": "audio", "label": "Sound 5", "content": "https://dyxmgicedabvmsbuvxny.supabase.co/storage/v1/object/public/audio/matching/fill.mp3"}, "right": {"type": "text", "content": "fill"}}]', NULL, NULL, NULL, NULL, 'All five words use the short /ɪ/ sound — like the i in "it". Listen for the clipped, quick vowel.', '2026-03-04 08:58:34.770181+00', 'short_long_i', 1, 'en', '{Pronunciation}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('a1b2c3d4-0932-0932-0932-000000000932', 932, 'matching', 'A2', 'pronunciation', 'Listen again — now match these sounds to the correct word.', 'match_all_pairs', '[{"left": {"type": "audio", "label": "Sound 1", "content": "https://dyxmgicedabvmsbuvxny.supabase.co/storage/v1/object/public/audio/matching/sheep.mp3"}, "right": {"type": "text", "content": "sheep"}}, {"left": {"type": "audio", "label": "Sound 2", "content": "https://dyxmgicedabvmsbuvxny.supabase.co/storage/v1/object/public/audio/matching/beat.mp3"}, "right": {"type": "text", "content": "beat"}}, {"left": {"type": "audio", "label": "Sound 3", "content": "https://dyxmgicedabvmsbuvxny.supabase.co/storage/v1/object/public/audio/matching/seat.mp3"}, "right": {"type": "text", "content": "seat"}}, {"left": {"type": "audio", "label": "Sound 4", "content": "https://dyxmgicedabvmsbuvxny.supabase.co/storage/v1/object/public/audio/matching/leave.mp3"}, "right": {"type": "text", "content": "leave"}}, {"left": {"type": "audio", "label": "Sound 5", "content": "https://dyxmgicedabvmsbuvxny.supabase.co/storage/v1/object/public/audio/matching/feel.mp3"}, "right": {"type": "text", "content": "feel"}}]', NULL, NULL, NULL, NULL, 'All five words use the long /iː/ sound — like the ee in "see". Notice how the vowel is stretched and sustained.', '2026-03-04 08:58:34.770181+00', 'short_long_i', 2, 'en', '{Pronunciation}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('a1b2c3d4-0933-0933-0933-000000000933', 933, 'matching', 'A2', 'pronunciation', 'Listen and match each sound to its definition. No word is shown this time.', 'match_all_pairs', '[{"left": {"type": "audio", "label": "Sound 1", "content": "https://dyxmgicedabvmsbuvxny.supabase.co/storage/v1/object/public/audio/matching/sheep.mp3"}, "right": {"type": "text", "content": "a farm animal with thick wool"}}, {"left": {"type": "audio", "label": "Sound 2", "content": "https://dyxmgicedabvmsbuvxny.supabase.co/storage/v1/object/public/audio/matching/bit.mp3"}, "right": {"type": "text", "content": "a small amount of something"}}, {"left": {"type": "audio", "label": "Sound 3", "content": "https://dyxmgicedabvmsbuvxny.supabase.co/storage/v1/object/public/audio/matching/seat.mp3"}, "right": {"type": "text", "content": "a place where you can sit"}}, {"left": {"type": "audio", "label": "Sound 4", "content": "https://dyxmgicedabvmsbuvxny.supabase.co/storage/v1/object/public/audio/matching/leave.mp3"}, "right": {"type": "text", "content": "to go away from a place"}}, {"left": {"type": "audio", "label": "Sound 5", "content": "https://dyxmgicedabvmsbuvxny.supabase.co/storage/v1/object/public/audio/matching/fill.mp3"}, "right": {"type": "text", "content": "to put something into a container until it is full"}}]', NULL, NULL, NULL, NULL, 'A mix of /ɪ/ and /iː/ words — you need to recognise the sound AND know the meaning. sheep /iː/ · bit /ɪ/ · seat /iː/ · leave /iː/ · fill /ɪ/', '2026-03-04 08:58:34.770181+00', 'short_long_i', 3, 'en', '{Pronunciation}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('4c5218bd-b544-4cd3-bfd4-f7391bde2a59', 106, 'multiple_choice', 'B2', 'passive_voice', 'The letter ___ yesterday morning.', 'was sent', '["sent", "is sent", "has been sent", "was sent"]', NULL, NULL, NULL, 'The letter didn''t send itself. Past simple, passive voice.', 'Past passive: was/were + past participle.', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{"Passive voice"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('e6924d6a-2368-46d2-ac34-a18ce4e96905', 2259, 'multiple_choice', 'A2', 'travel', 'She packed her ___ the night before the trip.', 'suitcase', '["suitcase", "passport", "ticket", "room"]', NULL, NULL, NULL, 'Where you put your clothes to travel.', 'A "suitcase" is where you pack your clothes to travel.', '2026-06-01 07:33:21.080816+00', NULL, NULL, 'en', '{Travel}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('95c31603-c07c-4347-8384-079411000f03', 621, 'sentence_building', 'A2', 'question_forms', '¿Puedes ayudarme?', 'can you help me', '["can", "you", "help", "me", "do", "are"]', NULL, NULL, NULL, NULL, 'We use ''can'' + subject + verb to make polite questions. ''Can you help me?'' is a common way to ask for help.', '2026-02-13 08:00:10.850224+00', NULL, NULL, 'en', '{"Question form"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('942122fc-42ed-4c70-82d3-9359efe4aeca', 202, 'gap_fill', 'A1', 'present_simple', 'I ___ (not like) coffee.', 'don''t like', NULL, NULL, NULL, NULL, 'Negative present simple with "I": don''t + verb.', 'Negative present simple: don''t + base verb.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Present tense"}', false, 'Don''t = do not.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('a1b2c3d4-0934-0934-0934-000000000934', 934, 'matching', 'A2', 'pronunciation', 'Listen and match each word to its minimal pair — the word that sounds almost the same but different.', 'match_all_pairs', '[{"left": {"type": "audio", "label": "Sound 1", "content": "https://dyxmgicedabvmsbuvxny.supabase.co/storage/v1/object/public/audio/matching/ship.mp3"}, "right": {"type": "text", "content": "sheep"}}, {"left": {"type": "audio", "label": "Sound 2", "content": "https://dyxmgicedabvmsbuvxny.supabase.co/storage/v1/object/public/audio/matching/bit.mp3"}, "right": {"type": "text", "content": "beat"}}, {"left": {"type": "audio", "label": "Sound 3", "content": "https://dyxmgicedabvmsbuvxny.supabase.co/storage/v1/object/public/audio/matching/sit.mp3"}, "right": {"type": "text", "content": "seat"}}, {"left": {"type": "audio", "label": "Sound 4", "content": "https://dyxmgicedabvmsbuvxny.supabase.co/storage/v1/object/public/audio/matching/Live%20-%20verb.mp3"}, "right": {"type": "text", "content": "leave"}}, {"left": {"type": "audio", "label": "Sound 5", "content": "https://dyxmgicedabvmsbuvxny.supabase.co/storage/v1/object/public/audio/matching/fill.mp3"}, "right": {"type": "text", "content": "feel"}}]', NULL, NULL, NULL, NULL, 'Minimal pairs: ship /ɪ/ ↔ sheep /iː/ · bit /ɪ/ ↔ beat /iː/ · sit /ɪ/ ↔ seat /iː/ · live /ɪ/ ↔ leave /iː/ · fill /ɪ/ ↔ feel /iː/', '2026-03-04 08:58:34.770181+00', 'short_long_i', 4, 'en', '{Pronunciation}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('7aca6b17-a11e-4d45-bed2-f361a3c2d5be', 729, 'matching', 'B1', 'pronunciation', 'Listen to each word and match it to the word on the left.', 'match_all_pairs', '[{"left": {"type": "audio", "label": "Word 1", "content": "https://dyxmgicedabvmsbuvxny.supabase.co/storage/v1/object/public/audio/matching/though.mp3"}, "right": {"type": "text", "content": "though"}}, {"left": {"type": "audio", "label": "Word 2", "content": "https://dyxmgicedabvmsbuvxny.supabase.co/storage/v1/object/public/audio/matching/through.mp3"}, "right": {"type": "text", "content": "through"}}, {"left": {"type": "audio", "label": "Word 3", "content": "https://dyxmgicedabvmsbuvxny.supabase.co/storage/v1/object/public/audio/matching/tough.mp3"}, "right": {"type": "text", "content": "tough"}}, {"left": {"type": "audio", "label": "Word 4", "content": "https://dyxmgicedabvmsbuvxny.supabase.co/storage/v1/object/public/audio/matching/trough.mp3"}, "right": {"type": "text", "content": "trough"}}, {"left": {"type": "audio", "label": "Word 5", "content": "https://dyxmgicedabvmsbuvxny.supabase.co/storage/v1/object/public/audio/matching/thought.mp3"}, "right": {"type": "text", "content": "thought"}}]', NULL, NULL, NULL, NULL, NULL, '2026-02-25 12:43:15.182597+00', 'ough_words', 1, 'en', '{Pronunciation}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('abcc34b6-09c9-4b27-a266-081a144ca908', 732, 'matching', 'B1', 'pronunciation', 'Listen to each word and match it to its spelling and meaning.', 'match_all_pairs', '[{"left": {"type": "audio", "label": "Word 1", "content": "https://dyxmgicedabvmsbuvxny.supabase.co/storage/v1/object/public/audio/matching/though.mp3"}, "right": {"type": "text", "content": "though — conjunction, like \"but\""}}, {"left": {"type": "audio", "label": "Word 2", "content": "https://dyxmgicedabvmsbuvxny.supabase.co/storage/v1/object/public/audio/matching/through.mp3"}, "right": {"type": "text", "content": "through — in one side and out of the other"}}, {"left": {"type": "audio", "label": "Word 3", "content": "https://dyxmgicedabvmsbuvxny.supabase.co/storage/v1/object/public/audio/matching/tough.mp3"}, "right": {"type": "text", "content": "tough — difficult or hard"}}, {"left": {"type": "audio", "label": "Word 4", "content": "https://dyxmgicedabvmsbuvxny.supabase.co/storage/v1/object/public/audio/matching/trough.mp3"}, "right": {"type": "text", "content": "trough — where animals eat and drink"}}, {"left": {"type": "audio", "label": "Word 5", "content": "https://dyxmgicedabvmsbuvxny.supabase.co/storage/v1/object/public/audio/matching/thought.mp3"}, "right": {"type": "text", "content": "thought — past tense of \"think\""}}]', NULL, NULL, NULL, NULL, NULL, '2026-02-25 13:09:12.002627+00', 'ough_words', 2, 'en', '{Pronunciation}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('a0071198-bfca-4a84-80da-ed09ed154f86', 1917, 'matching', 'C1', 'idioms', 'Match each idiom to its meaning.', 'match_all_pairs', '[{"left": {"type": "text", "label": "", "content": "play devil''s advocate"}, "right": {"type": "text", "label": "", "content": "argue a position you don''t personally hold"}}, {"left": {"type": "text", "label": "", "content": "bite the bullet"}, "right": {"type": "text", "label": "", "content": "endure a painful or difficult situation"}}, {"left": {"type": "text", "label": "", "content": "throw in the towel"}, "right": {"type": "text", "label": "", "content": "give up"}}, {"left": {"type": "text", "label": "", "content": "push the envelope"}, "right": {"type": "text", "label": "", "content": "go beyond conventional limits"}}]', NULL, NULL, NULL, NULL, NULL, '2026-04-08 18:25:27.713957+00', NULL, NULL, 'en', '{Idioms}', true, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('f9a27633-3206-4cce-b9b6-5bb63dc504d8', 1918, 'matching', 'C2', 'idioms', 'Match each idiom to its meaning.', 'match_all_pairs', '[{"left": {"type": "text", "label": "", "content": "hit the nail on the head"}, "right": {"type": "text", "label": "", "content": "say exactly the right thing"}}, {"left": {"type": "text", "label": "", "content": "a double-edged sword"}, "right": {"type": "text", "label": "", "content": "something with both advantages and disadvantages"}}, {"left": {"type": "text", "label": "", "content": "paint yourself into a corner"}, "right": {"type": "text", "label": "", "content": "create a situation with no easy way out"}}, {"left": {"type": "text", "label": "", "content": "move the goalposts"}, "right": {"type": "text", "label": "", "content": "change the rules or expectations unfairly"}}]', NULL, NULL, NULL, NULL, NULL, '2026-04-08 18:25:27.713957+00', NULL, NULL, 'en', '{Idioms}', true, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('5eef6e37-8099-4166-b8f2-f0a5b98823c1', 2260, 'gap_fill', 'B2', 'travel', 'By the time we reached the hotel, we ___ for twelve hours.', 'had been travelling', '[]', NULL, NULL, '[{"answer": "had been traveling", "feedback": "Also correct — \"traveling\" is the American spelling of \"travelling\"."}]', 'Past perfect continuous — an action ongoing up to a point in the past.', 'Past perfect continuous "had been travelling" describes an action ongoing up to a point in the past.', '2026-06-01 07:33:21.080816+00', NULL, NULL, 'en', '{Tense}', false, '"had been + -ing".', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('b0e31c5b-8012-40e5-aa2f-618b2f8a734b', 301, 'multiple_choice', 'A1', 'present_simple', 'My sister ___ in a bank.', 'works', '["work", "works", "working", "is work"]', NULL, NULL, NULL, 'My sister = she. Add -s.', 'Third person singular (she/he/it): add -s to the verb.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Present tense"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('31b9398c-cdcc-4422-812c-0fa2971ecced', 963, 'gap_fill', 'C1', 'phrasal_verbs', 'After initially agreeing to the merger, the smaller company decided to _______.', 'back out', NULL, NULL, NULL, '["pull out"]', 'To withdraw from an agreement — pull back at the last minute.', 'To back out of a commitment or agreement means to withdraw from it, especially after initially agreeing. Pull out has the same meaning.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Phrasal verb"}', false, 'Two words. Starts with b___ o___.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('ed9a4ba0-94f5-4f1a-9984-fe83bd839c1e', 733, 'matching', 'B2', 'pronunciation', 'Each word on the left RHYMES with a word on the right (they sound the same at the end). Listen and match them.', 'match_all_pairs', '[{"left": {"type": "audio", "label": "Word 1", "content": "https://dyxmgicedabvmsbuvxny.supabase.co/storage/v1/object/public/audio/matching/though.mp3"}, "right": {"type": "text", "content": "go"}}, {"left": {"type": "audio", "label": "Word 2", "content": "https://dyxmgicedabvmsbuvxny.supabase.co/storage/v1/object/public/audio/matching/through.mp3"}, "right": {"type": "text", "content": "blue"}}, {"left": {"type": "audio", "label": "Word 3", "content": "https://dyxmgicedabvmsbuvxny.supabase.co/storage/v1/object/public/audio/matching/tough.mp3"}, "right": {"type": "text", "content": "stuff"}}, {"left": {"type": "audio", "label": "Word 4", "content": "https://dyxmgicedabvmsbuvxny.supabase.co/storage/v1/object/public/audio/matching/trough.mp3"}, "right": {"type": "text", "content": "off"}}, {"left": {"type": "audio", "label": "Word 5", "content": "https://dyxmgicedabvmsbuvxny.supabase.co/storage/v1/object/public/audio/matching/thought.mp3"}, "right": {"type": "text", "content": "port"}}]', NULL, NULL, NULL, NULL, NULL, '2026-02-25 13:09:46.323315+00', 'ough_words', 4, 'en', '{Pronunciation}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('60d9879a-6445-44c3-8b8f-b0d90479072e', 730, 'matching', 'B1', 'pronunciation', 'Listen and match each word to its meaning.', 'match_all_pairs', '[{"left": {"type": "audio", "label": "Word 1", "content": "https://dyxmgicedabvmsbuvxny.supabase.co/storage/v1/object/public/audio/matching/though.mp3"}, "right": {"type": "text", "content": "conjunction: like \"but\""}}, {"left": {"type": "audio", "label": "Word 2", "content": "https://dyxmgicedabvmsbuvxny.supabase.co/storage/v1/object/public/audio/matching/through.mp3"}, "right": {"type": "text", "content": "adverb: in one side and out of the other"}}, {"left": {"type": "audio", "label": "Word 3", "content": "https://dyxmgicedabvmsbuvxny.supabase.co/storage/v1/object/public/audio/matching/tough.mp3"}, "right": {"type": "text", "content": "adjective: difficult or hard"}}, {"left": {"type": "audio", "label": "Word 4", "content": "https://dyxmgicedabvmsbuvxny.supabase.co/storage/v1/object/public/audio/matching/trough.mp3"}, "right": {"type": "text", "content": "noun: where animals eat"}}, {"left": {"type": "audio", "label": "Word 5", "content": "https://dyxmgicedabvmsbuvxny.supabase.co/storage/v1/object/public/audio/matching/thought.mp3"}, "right": {"type": "text", "content": "verb: past tense of \"think\""}}]', NULL, NULL, NULL, NULL, NULL, '2026-02-25 12:16:31.110712+00', 'ough_words', 3, 'en', '{Pronunciation}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('44652ec1-94eb-47cc-a9f6-13dfac4dce5d', 2261, 'gap_fill', 'B2', 'travel', 'If the flight ___ delayed, we''ll miss the connection.', 'is', '[]', NULL, NULL, NULL, 'First conditional: present simple in the "if" clause.', 'In a first conditional, the "if" clause uses the present simple: "If the flight is delayed".', '2026-06-01 07:33:21.080816+00', NULL, NULL, 'en', '{Conditional}', false, 'Two letters.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('673081a4-6aa6-464d-9ad9-a734653d9316', 2262, 'gap_fill', 'B2', 'travel', 'The tour guide recommended ___ the old town on foot.', 'exploring', '[]', NULL, NULL, NULL, '"recommend" is followed by a gerund here.', '"Recommend" is followed by the -ing form: "recommended exploring".', '2026-06-01 07:33:21.080816+00', NULL, NULL, 'en', '{Gerund}', false, '-ing form.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('6a9cb045-5785-474d-8ca9-54c5f38a15bf', 696, 'error_correction', 'C1', 'subjunctive', 'She demanded that he leaves immediately.', 'She demanded that he leave immediately.', '[]', NULL, NULL, NULL, NULL, 'After "demand/insist/suggest that", we use the subjunctive (infinitive): "he leave".', '2026-02-20 19:09:17.848852+00', NULL, NULL, 'en', '{Subjunctive}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('8c61b693-ed2d-41ca-9b6e-8b3d0972e3e3', 2263, 'gap_fill', 'B2', 'travel', 'All passengers ___ to show their boarding passes.', 'are required', '[]', NULL, NULL, NULL, 'Present simple passive.', 'Present simple passive: "are required" = subject + "are" + past participle.', '2026-06-01 07:33:21.080816+00', NULL, NULL, 'en', '{Passive}', false, '"are + past participle".', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('f3be9764-ccfd-455c-ad69-2c2386a6ea6b', 2264, 'gap_fill', 'B2', 'travel', 'We''d already eaten ___ the waiter brought the menu.', 'by the time', '[]', NULL, NULL, '[{"answer": "before", "feedback": "Also correct — \"before\" works naturally here too."}]', 'A time conjunction linking two past events.', '"By the time" (or "before") links the earlier action to the later one in the past.', '2026-06-01 07:33:21.080816+00', NULL, NULL, 'en', '{Tense}', false, 'Could be "by the time" or a single word.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('1ca8845b-d23e-4470-829f-0bd5746f6d7b', 676, 'odd_one_out', 'C2', 'subjunctive', 'Which is NOT a subjunctive structure?', 'She has been working', '["I suggest he leave", "If I were you", "It is vital that she attend", "She has been working"]', NULL, NULL, NULL, NULL, '"She has been working" is present perfect continuous, not subjunctive.', '2026-02-20 19:09:17.848852+00', NULL, NULL, 'en', '{Subjunctive}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('c10a361c-e21e-46c2-9f87-c8e203c53855', 59, 'gap_fill', 'B2', 'wish', 'I wish I ___ (can / speak) French fluently.', 'could speak', NULL, NULL, NULL, NULL, 'Wish + past simple for present wishes', 'Use past simple after ''wish'' when talking about present situations you want to be different.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{"Wish & regret"}', false, 'Even with "can", we use the past form when wishing about the present.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('869a7333-3673-4fd4-8706-0ccca10e5c50', 964, 'gap_fill', 'C1', 'phrasal_verbs', 'Despite being terrified, she managed to ___ the presentation perfectly.', 'pull off', NULL, NULL, NULL, NULL, 'To succeed at something difficult, often unexpectedly.', 'To talk someone into doing something means to persuade them to do it. The preposition into is essential — compare: talk someone out of = to persuade them not to do it.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Phrasal verb"}', false, 'Two words. Starts with p___ o___.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('c9476603-3c12-49e2-94f7-010031f1502b', 965, 'gap_fill', 'C2', 'phrasal_verbs', 'The company''s soaring reputation has been gradually _______ by a series of product failures.', 'worn away', NULL, NULL, NULL, '["eroded away", "eaten away", "chipped away"]', 'To gradually erode — like rocks worn by water over time.', 'To wear away means to gradually damage or reduce something through continuous pressure or use. Similar: erode away, eat away, chip away.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Phrasal verb"}', false, 'Two words. Past participle (after "has been"). Starts with w___ a___.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('e455d66a-aa23-4671-b1b1-6ad011344946', 2265, 'multiple_choice', 'B2', 'travel', 'The resort is ___ the most beautiful I''ve ever seen.', 'by far', '["by far", "very", "much more", "so"]', NULL, NULL, NULL, 'Emphasises a superlative strongly.', '"By far" strongly emphasises a superlative: "by far the most beautiful".', '2026-06-01 07:33:21.080816+00', NULL, NULL, 'en', '{Comparative}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('2dfdc30a-9edc-413c-ba12-b7a8b99dbc9f', 117, 'multiple_choice', 'B2', 'wish', 'I wish I ___ more time to study for the exam.', 'had', '["have", "had", "would have", "will have"]', NULL, NULL, NULL, 'Wishing about the present — backshift to past simple.', 'Wish + past simple for present wishes.', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{"Wish & regret"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('e9327070-4701-408e-bfbe-a8eedefb5c80', 394, 'multiple_choice', 'A1', 'to_be', 'I ___ 25 years old.', 'am', '["have", "am", "has", "is"]', NULL, NULL, NULL, 'I + verb "to be" in present.', 'In English we say: I am 25 (not I have 25).', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"To be"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('93f54376-761a-4100-9fcc-b4f8147d7d5f', 395, 'multiple_choice', 'A2', 'adverbs_of_frequency', 'She ___ goes to the gym. She goes every day.', 'always', '["never", "sometimes", "always", "rarely"]', NULL, NULL, NULL, 'Every day = 100% of the time.', 'Always = 100% of the time. She goes every day = always.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{Adverb}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('aa110f1a-c1f8-4f89-8669-29f8a9902a65', 510, 'multiple_choice', 'C1', 'advanced_phrasal_verbs', 'She managed to ___ her nerves before the presentation.', 'get over', '["get by", "get through", "get over", "get along"]', NULL, NULL, NULL, 'To recover from an emotional difficulty.', 'Get over = overcome, recover from something.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Phrasal verb"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('45387375-e12f-425c-9bcc-0784b65c580d', 757, 'multiple_choice', 'A2', 'travel', '"___ is the weather like in Spain in summer?"', 'What', '["How", "What", "Where", "Which"]', NULL, NULL, NULL, '"___ is X like?" — asking for a description.', '"What is the weather like?" is the correct fixed phrase for asking about weather. "How is the weather?" is also possible, but "What is it like?" is more natural.', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{Vocabulary}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('130caf91-cf1f-483e-9838-66be88cf57ae', 969, 'multiple_choice', 'A1', 'hotel_vocabulary', 'You need to _______ at reception when you arrive at the hotel.', 'check in', '["check in", "sign in", "log in", "book in"]', NULL, NULL, NULL, 'To register at reception when arriving — opposite of "check out".', 'To check in means to register your arrival at a hotel, airport, or event. The opposite is to check out — to leave and settle your bill.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Hotel vocabulary","Phrasal verb"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('6960f3cd-1150-4913-9fe9-9f15e8352e99', 970, 'multiple_choice', 'A1', 'hotel_vocabulary', 'A _______ room has two separate single beds.', 'twin', '["twin", "double", "shared", "standard"]', NULL, NULL, NULL, 'Two of the same — like twins.', 'A twin room has two separate single beds. A double room has one large bed for two people. This is a common source of confusion when booking.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Hotel vocabulary","Confusable words"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('e3a5ab52-d597-4710-b92d-744fb3094dda', 972, 'multiple_choice', 'A1', 'hotel_vocabulary', 'You can order food to your room using _______ service.', 'room', '["room", "hotel", "floor", "door"]', NULL, NULL, NULL, '___ service = food brought to your hotel ___.', 'Room service means ordering food or drinks to be delivered directly to your hotel room, usually at any hour.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Hotel vocabulary",Collocation}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('ba004cc2-5985-4885-b994-01a24914a342', 974, 'multiple_choice', 'A2', 'hotel_vocabulary', 'We made a _______ at the hotel three months before our holiday.', 'reservation', '["reservation", "plan", "contract", "decision"]', NULL, NULL, NULL, 'A booking made in advance.', 'A reservation is a formal arrangement to have something kept for you — a room, table, or seat. Book and reserve are common synonyms as verbs.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Hotel vocabulary"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('60f1b43a-a415-4b30-a71f-097295a83dc4', 1919, 'matching', 'C1', 'idioms', 'Match each idiom to its meaning.', 'match_all_pairs', '[{"left": {"type": "text", "label": "", "content": "an elephant in the room"}, "right": {"type": "text", "label": "", "content": "an obvious problem that nobody wants to discuss"}}, {"left": {"type": "text", "label": "", "content": "cut to the chase"}, "right": {"type": "text", "label": "", "content": "get to the point quickly"}}, {"left": {"type": "text", "label": "", "content": "the tip of the iceberg"}, "right": {"type": "text", "label": "", "content": "a small visible part of a much larger problem"}}, {"left": {"type": "text", "label": "", "content": "get the ball rolling"}, "right": {"type": "text", "label": "", "content": "make a start on something"}}]', NULL, NULL, NULL, NULL, NULL, '2026-04-08 18:25:27.713957+00', NULL, NULL, 'en', '{Idioms}', true, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('b460fad8-1089-4dc1-9563-a5991c4fe246', 2266, 'multiple_choice', 'B2', 'travel', 'We were ___ tired to go sightseeing after the flight.', 'too', '["too", "so", "very", "enough"]', NULL, NULL, NULL, '"___ tired to do something" = excessively.', '"Too + adjective + to" means excessively: "too tired to go sightseeing".', '2026-06-01 07:33:21.080816+00', NULL, NULL, 'en', '{Grammar}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('db22b010-56c9-4e3f-bdf0-0f0898bc217c', 1195, 'sentence_building', 'B1', 'routines', 'Tiendo a perder la noción del tiempo por las mañanas.', 'I tend to lose track of time in the morning.', '["I", "tend", "to", "lose", "track", "of", "time", "in", "the", "morning", "miss", "keep", "often"]', NULL, NULL, NULL, NULL, 'Tend to + infinitive describes a habitual behaviour. Lose track of time means to stop noticing how much time is passing.', '2026-03-16 09:04:17.945706+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('78d26378-998c-4890-be4e-8d5feb49b7d5', 151, 'multiple_choice', 'B2', 'cleft_sentences', '___ I really need is a holiday.', 'What', '["That", "What", "Which", "It"]', NULL, NULL, NULL, 'Cleft sentence — putting the focus on what comes at the end (a holiday).', 'What-cleft sentences for emphasis.', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{"Cleft sentence"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('160d61a8-e2ba-4663-b91f-65478515f2f2', 163, 'multiple_choice', 'B2', 'participle_clauses', '___ tired, I decided to go to bed early.', 'Feeling', '["Feel", "Felt", "Feeling", "To feel"]', NULL, NULL, NULL, '-ing form at the start of a sentence — gives the reason.', 'Participle clause showing reason.', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{"Participle clause"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('25f1a8df-388a-4344-9419-d554f3e625f1', 973, 'multiple_choice', 'A1', 'hotel_vocabulary', 'The receptionist gave us a _______ to get into our room.', 'key card', '["key card", "password", "code card", "chip"]', NULL, NULL, NULL, 'A modern hotel "key" — looks like a credit card.', 'A key card is the plastic card used to open hotel room doors electronically. It replaced the traditional metal key in most modern hotels.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Hotel vocabulary"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('90217b21-39db-465d-b853-98ccad25f8c8', 975, 'multiple_choice', 'A2', 'hotel_vocabulary', 'Breakfast is _______ with your room — you don''t need to pay for it separately.', 'included', '["included", "optional", "extra", "available"]', NULL, NULL, NULL, 'Part of the room price — no extra charge.', 'If something is included, it is part of the price — you do not pay extra. The opposite is that it is optional or available at an extra charge.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Hotel vocabulary"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('55221332-bc3c-4d2c-8dce-9e91bc3ee0aa', 971, 'multiple_choice', 'A1', 'hotel_vocabulary', 'Would you like your _______ to be sent to your room?', 'luggage', '["luggage", "package", "equipment", "belongings"]', NULL, NULL, NULL, 'All your travel bags together — uncountable noun.', 'Luggage (uncountable) refers to the bags and suitcases you travel with. It has no plural form — you cannot say luggages.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Hotel vocabulary","Uncountable noun"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('8279dd16-011c-42be-81f1-9dbd6bf53205', 205, 'gap_fill', 'A1', 'present_simple', 'He ___ (not eat) meat.', 'doesn''t eat', NULL, NULL, NULL, NULL, 'He/she/it negative — uses doesn''t.', 'Third person negative: doesn''t + base verb.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Present tense"}', false, 'Doesn''t = does not.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('61be1c7e-a544-419e-9ea4-dba96a1821da', 456, 'gap_fill', 'C1', 'participle_clauses', '___ (realise) his mistake, he immediately apologised.', 'Realising', NULL, NULL, NULL, NULL, '-ing form at start of sentence — gives the reason.', 'Present participle clause: -ing form replaces because/when + subject + verb.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Participle clause"}', false, '= "Because he realised..."', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('07ae1c0a-c85b-4ad9-8afe-b77d78ece825', 457, 'gap_fill', 'C1', 'participle_clauses', '___ (write) in the 19th century, the novel still feels relevant today.', 'Written', NULL, NULL, NULL, NULL, 'Past participle at start = passive participle clause.', 'Past participle clause (passive meaning): Written = Because it was written.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Participle clause"}', false, '= "Although it was written..."', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('c014016b-e707-4823-8984-f7be5d937416', 508, 'multiple_choice', 'C1', 'advanced_phrasal_verbs', 'We need to ___ a solution before the deadline.', 'come up with', '["come down to", "come up with", "come across", "come round to"]', NULL, NULL, NULL, 'To invent or think of (an idea, a solution).', 'Come up with = think of, produce an idea or solution.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Phrasal verb"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('455f5dca-e7b2-43b1-83f9-5a093aa24332', 561, 'multiple_choice', 'C1', 'cleft_sentences', '___ I really need is a good night''s sleep.', 'What', '["That", "What", "Which", "It"]', NULL, NULL, NULL, 'What-cleft for emphasis — putting focus at the end.', 'What-cleft for emphasis: What I need is... = The thing I need is...', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Cleft sentence"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('ac0855f3-92fa-4f10-a7e4-dfafde158f13', 796, 'multiple_choice', 'C2', 'linking language', '"The bill was passed ___ fierce opposition from several powerful lobby groups."', 'All three are correct', '["notwithstanding", "regardless of", "despite", "All three are correct"]', NULL, NULL, NULL, 'Check whether all the linkers fit both grammatically and in meaning.', '"Notwithstanding", "despite", and "regardless of" all express contrast (something happened in spite of something else). All three work here — useful synonyms for formal writing.', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{"Linking word"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('66dfe840-3a40-48a0-8fdb-6feedc7e70d2', 976, 'multiple_choice', 'A2', 'hotel_vocabulary', 'The sign on the door said ''No _______'' — the hotel was completely full.', 'vacancy', '["vacancy", "space", "availability", "entry"]', NULL, NULL, NULL, 'An empty room available to book — "no ___" means full.', 'A vacancy is an available room. No vacancy means the hotel is full. The same word is used in recruitment — a job vacancy means a position that needs to be filled.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Hotel vocabulary"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('e6d95cb9-4939-4af5-b891-7a231dff8de1', 977, 'multiple_choice', 'A2', 'hotel_vocabulary', 'The hotel offered _______ champagne on arrival — a free glass for every guest.', 'complimentary', '["complimentary", "traditional", "homemade", "special"]', NULL, NULL, NULL, 'Free of charge — given as a courtesy.', 'Complimentary means provided free of charge, as a gesture of hospitality. It is a more formal and professional word than free.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Hotel vocabulary"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('66e92e9d-60d5-4d40-ad47-95a1f5073a83', 1920, 'matching', 'C1', 'grammar', 'Match the beginning of each sentence to its correct ending.', 'match_all_pairs', '[{"left": {"type": "text", "label": "", "content": "Not only did she refuse to apologise,"}, "right": {"type": "text", "label": "", "content": "but she also blamed everyone else."}}, {"left": {"type": "text", "label": "", "content": "Rarely had he seen"}, "right": {"type": "text", "label": "", "content": "such a convincing performance."}}, {"left": {"type": "text", "label": "", "content": "Had I known about the problem earlier,"}, "right": {"type": "text", "label": "", "content": "I would have dealt with it immediately."}}, {"left": {"type": "text", "label": "", "content": "So complex was the situation"}, "right": {"type": "text", "label": "", "content": "that even the experts disagreed."}}, {"left": {"type": "text", "label": "", "content": "Only after the meeting ended"}, "right": {"type": "text", "label": "", "content": "did they realise the extent of the problem."}}]', NULL, NULL, NULL, NULL, NULL, '2026-04-08 18:25:27.713957+00', NULL, NULL, 'en', '{Grammar,Sentences,Inversion}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('ca30cf41-4c2f-435a-9afc-18008b9fc426', 1921, 'matching', 'C2', 'grammar', 'Match the beginning of each sentence to its correct ending.', 'match_all_pairs', '[{"left": {"type": "text", "label": "", "content": "The more he tried to explain,"}, "right": {"type": "text", "label": "", "content": "the more confused everyone became."}}, {"left": {"type": "text", "label": "", "content": "No sooner had the announcement been made"}, "right": {"type": "text", "label": "", "content": "than the share price collapsed."}}, {"left": {"type": "text", "label": "", "content": "Much as I admire her work,"}, "right": {"type": "text", "label": "", "content": "I can''t overlook this fundamental error."}}, {"left": {"type": "text", "label": "", "content": "It wasn''t until she retired"}, "right": {"type": "text", "label": "", "content": "that she finally received the recognition she deserved."}}]', NULL, NULL, NULL, NULL, NULL, '2026-04-08 18:25:27.713957+00', NULL, NULL, 'en', '{Grammar,Sentences}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('e597f062-6f6d-455c-a91b-d7df1eab9be9', 1922, 'matching', 'C1', 'grammar', 'Match the beginning of each sentence to its correct ending.', 'match_all_pairs', '[{"left": {"type": "text", "label": "", "content": "I''d appreciate it if you could"}, "right": {"type": "text", "label": "", "content": "let me know by the end of the week."}}, {"left": {"type": "text", "label": "", "content": "It goes without saying that"}, "right": {"type": "text", "label": "", "content": "confidentiality must be maintained at all times."}}, {"left": {"type": "text", "label": "", "content": "She couldn''t help but feel"}, "right": {"type": "text", "label": "", "content": "that something had gone terribly wrong."}}, {"left": {"type": "text", "label": "", "content": "The decision to expand"}, "right": {"type": "text", "label": "", "content": "proved to be more costly than anticipated."}}, {"left": {"type": "text", "label": "", "content": "Whatever you decide,"}, "right": {"type": "text", "label": "", "content": "make sure you can justify it."}}]', NULL, NULL, NULL, NULL, NULL, '2026-04-08 18:25:27.713957+00', NULL, NULL, 'en', '{Grammar,Sentences}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('da580e24-3ee4-484e-ae5d-15c0ce45dfa6', 75, 'gap_fill', 'B1', 'linking_words', 'I wanted to go out, ___ (but / so / because) it was raining.', 'but', NULL, NULL, NULL, NULL, 'Contrasting two ideas', 'But is used to show contrast between two ideas.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{"Linking word"}', false, '"I wanted X, BUT Y" — opposite outcomes.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('a92f9d51-230b-44e0-9031-a7d4c45bb3ba', 132, 'multiple_choice', 'B1', 'linking_words', 'I was tired, ___ I went to bed early.', 'so', '["but", "so", "because", "although"]', NULL, NULL, NULL, 'Tired → bed early. Cause and effect.', 'So shows result or consequence.', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{"Linking word"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('b08ae085-3245-424e-b8a4-bd4ff0bc1ce5', 142, 'multiple_choice', 'B2', 'so_such', 'It was ___ a difficult test that nobody passed.', 'such', '["so", "such", "very", "too"]', NULL, NULL, NULL, 'There''s an article ("a") and a noun ("test") — that needs the longer form.', 'Such + a/an + adjective + noun.', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{"Linking word"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('15ee328d-7db3-42da-b067-ef82dca760ac', 166, 'multiple_choice', 'B1', 'as_like', 'He works ___ a doctor in the local hospital.', 'as', '["like", "for", "such as", "as"]', NULL, NULL, NULL, 'In the role of — he actually IS a doctor.', 'As + profession/role.', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{"Linking word"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('84b2746c-d490-462b-87fc-9b6e622074bb', 172, 'multiple_choice', 'B2', 'emphatic_structures', 'It ___ John who told me the news.', 'was', '["is", "was", "has", "does"]', NULL, NULL, NULL, 'It-cleft for emphasis: "It ___ John who..." — pulls focus onto John.', 'It-cleft sentence for emphasis (It was... who).', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{"Cleft sentence"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('82c5d2c5-73d7-4b56-b7f7-845d30a3aca8', 396, 'multiple_choice', 'A2', 'adverbs_of_frequency', 'I ___ eat fish. I don''t like it.', 'never', '["always", "usually", "sometimes", "never"]', NULL, NULL, NULL, 'Don''t like it = 0% of the time.', 'Never = 0% of the time. I don''t like it = I never eat it.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{Adverb}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('ecde8e3d-cb69-458e-a24a-1b1bcc5e0b55', 399, 'multiple_choice', 'A1', 'basic_vocabulary', 'The opposite of "hot" is ___.', 'cold', '["warm", "cool", "cold", "big"]', NULL, NULL, NULL, 'The opposite temperature.', 'Hot ↔ cold. These are basic opposite adjectives.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{Vocabulary}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('d61fca9b-e94d-473c-82c4-22199c900349', 400, 'multiple_choice', 'A1', 'basic_vocabulary', 'The opposite of "cheap" is ___.', 'expensive', '["small", "expensive", "free", "old"]', NULL, NULL, NULL, 'High price = the opposite of cheap.', 'Cheap ↔ expensive. About the price of things.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{Vocabulary}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('82d2bb17-2885-4f63-b1b2-9e61de021f69', 562, 'multiple_choice', 'C1', 'cleft_sentences', 'It ___ John who suggested the idea.', 'was', '["is", "had", "was", "has"]', NULL, NULL, NULL, '"It ___ John who..." — past form of "to be".', 'It-cleft for emphasis on the person: It was John who...', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Cleft sentence"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('27b350ca-1775-48d8-8279-2d890b994aec', 1923, 'matching', 'C1', 'vocabulary', 'Match each word to its definition.', 'match_all_pairs', '[{"left": {"type": "text", "label": "", "content": "scrutinise"}, "right": {"type": "text", "label": "", "content": "examine very carefully"}}, {"left": {"type": "text", "label": "", "content": "mitigate"}, "right": {"type": "text", "label": "", "content": "reduce the severity of something"}}, {"left": {"type": "text", "label": "", "content": "precedent"}, "right": {"type": "text", "label": "", "content": "an earlier event used to justify a later decision"}}, {"left": {"type": "text", "label": "", "content": "discrepancy"}, "right": {"type": "text", "label": "", "content": "a difference between two things that should match"}}, {"left": {"type": "text", "label": "", "content": "convoluted"}, "right": {"type": "text", "label": "", "content": "unnecessarily complicated"}}]', NULL, NULL, NULL, NULL, NULL, '2026-04-08 18:25:27.713957+00', NULL, NULL, 'en', '{Vocabulary}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('4e0efa06-564c-49d6-b415-b6337d2f7fc0', 1924, 'matching', 'C2', 'vocabulary', 'Match each word to its definition.', 'match_all_pairs', '[{"left": {"type": "text", "label": "", "content": "equivocate"}, "right": {"type": "text", "label": "", "content": "use vague language to avoid committing to a position"}}, {"left": {"type": "text", "label": "", "content": "perfunctory"}, "right": {"type": "text", "label": "", "content": "done with minimal effort or care"}}, {"left": {"type": "text", "label": "", "content": "amalgamate"}, "right": {"type": "text", "label": "", "content": "combine or unite into one"}}, {"left": {"type": "text", "label": "", "content": "propitious"}, "right": {"type": "text", "label": "", "content": "giving a good chance of success"}}]', NULL, NULL, NULL, NULL, NULL, '2026-04-08 18:25:27.713957+00', NULL, NULL, 'en', '{Vocabulary}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('dfa0d297-b09d-4c45-b8b4-8206abb66c4c', 978, 'multiple_choice', 'A2', 'hotel_vocabulary', 'The pool and gym are just two of the hotel''s excellent _______.', 'facilities', '["facilities", "decorations", "attractions", "activities"]', NULL, NULL, NULL, 'Hotel amenities — pool, gym, spa, etc.', 'Facilities refers to the physical amenities and services a hotel offers — pool, gym, spa, business centre, etc. It is always plural in this context.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Hotel vocabulary"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('1aa3678c-87ac-4f88-a12f-5b460a13c419', 979, 'multiple_choice', 'B1', 'hotel_vocabulary', 'The hotel was _______ — they had accepted more bookings than they had rooms available.', 'overbooked', '["overbooked", "overcrowded", "overwhelmed", "overrun"]', NULL, NULL, NULL, 'When a hotel accepts more bookings than rooms available.', 'Overbooked means more reservations have been accepted than there are rooms available. Hotels sometimes offer compensation — an upgrade or alternative accommodation — in this situation.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Hotel vocabulary"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('c699cb89-7206-4777-8030-0dc687d98e4f', 714, 'error_correction', 'B2', 'linking_words', 'Despite of rain, we went for a walk.', 'Despite the rain, we went for a walk.', '[]', NULL, NULL, NULL, NULL, '"Despite" is never followed by "of". Use "In spite of" if you want the "of" form.', '2026-02-20 19:09:17.848852+00', NULL, NULL, 'en', '{"Linking word"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('948d438d-f556-4a7c-adda-73a7fa4fe628', 107, 'multiple_choice', 'B1', 'comparatives', 'This restaurant is ___ than the one we went to last week.', 'more expensive', '["the more expensive", "more expensive", "most expensive", "expensiver"]', NULL, NULL, NULL, 'Long adjective — needs "more". And we''re comparing only two restaurants, not picking a #1.', 'Comparative form for long adjectives: more + adjective.', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{Comparative}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('414ced3b-5c8f-4619-899f-64edd5b2b156', 134, 'multiple_choice', 'B1', 'comparatives_as_as', 'My sister is ___ tall as me.', 'as', '["so", "as", "more", "too"]', NULL, NULL, NULL, 'Equal comparison — ___ + adjective + ___.', 'As...as for equal comparisons.', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{Comparative}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('e27003ac-8dbf-4b63-941b-87069efd7dac', 670, 'sentence_building', 'C2', 'complex_sentences', 'A pesar de que le ofrecieron el puesto, lo rechazó sin pensárselo dos veces.', 'despite having been offered the position she turned it down without thinking twice', '["despite", "having", "been", "offered", "the", "position", "she", "turned", "it", "down", "without", "thinking", "twice", "offering", "thought", "a"]', NULL, NULL, NULL, NULL, 'Despite + having been + past participle (passive perfect gerund) + phrasal verb (turn down).
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('356dc805-2148-4abb-a249-03f65eaa1b86', 684, 'odd_one_out', 'B2', 'linking_words', 'Which is NOT a linking word showing contrast?', 'moreover', '["however", "moreover", "although", "nevertheless"]', NULL, NULL, NULL, NULL, '"Moreover" adds information (addition). The others show contrast.', '2026-02-20 19:09:17.848852+00', NULL, NULL, 'en', '{"Linking word"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('6d01513b-8c56-48df-b041-adbe220938fa', 146, 'multiple_choice', 'B2', 'despite_although', '___ the rain, we enjoyed our walk.', 'Despite', '["Although", "Despite", "However", "Because"]', NULL, NULL, NULL, '___ + noun. (The other option needs a full clause with subject and verb.)', 'Despite + noun.', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{"Linking word"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('4dd5f312-7deb-4669-9524-d0b677d9a522', 156, 'multiple_choice', 'B1', 'comparatives', 'This exercise is ___ difficult than the last one.', 'less', '["most", "less", "least", "lease"]', NULL, NULL, NULL, 'Comparing downward — the opposite of "more".', 'Less for comparatives (opposite of more).', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{Comparative}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('ac8f794f-aae4-43f8-9120-ee8e3c39d116', 170, 'multiple_choice', 'B2', 'double_comparatives', 'The ___ you practice, the ___ you''ll become.', 'more / better', '["most / better", "more / best", "more / better", "most / best"]', NULL, NULL, NULL, '"The ___ X, the ___ Y" — proportional change. The two blanks pair up.', 'The + comparative... the + comparative (for correlation).', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{Comparative}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('eb45416d-5631-4fc7-8559-48dfcb8ce365', 286, 'gap_fill', 'A2', 'comparatives', 'My house is ___ (big) than your house.', 'bigger', NULL, NULL, NULL, NULL, 'Short adjective + -er — but with a twist.', 'Short adjectives: add -er. Double the consonant after a short vowel: big → bigger.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{Comparative}', false, 'Big → bigger (the g doubles).', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('d56aa96a-9e22-46e5-9374-55f0ef7da072', 288, 'gap_fill', 'A2', 'comparatives', 'This restaurant is ___ (expensive) than that one.', 'more expensive', NULL, NULL, NULL, NULL, 'Long adjective — needs "more".', 'Long adjectives (3+ syllables): more + adjective.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{Comparative}', false, 'Expensive (3 syllables) → "more expensive".', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('fbdf46e2-4ec8-4c8c-ae97-f9381fa496c4', 289, 'gap_fill', 'A2', 'comparatives', 'She is ___ (good) at maths than me.', 'better', NULL, NULL, NULL, NULL, 'Comparative of "good".', 'Good is irregular: good → better → best.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{Comparative}', false, 'Good → better → best.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('865adacc-2de4-4302-bca6-640c080ec288', 290, 'gap_fill', 'A2', 'comparatives', 'Today is ___ (bad) than yesterday.', 'worse', NULL, NULL, NULL, NULL, 'Comparative of "bad".', 'Bad is irregular: bad → worse → worst.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{Comparative}', false, 'Bad → worse → worst.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('743f6953-0480-4e1b-bcb2-cde39c7586f1', 397, 'multiple_choice', 'A2', 'conjunctions', 'I want to go out ___ it''s raining.', 'but', '["then", "but", "because", "so"]', NULL, NULL, NULL, 'Contrast — wanted X, ___ Y prevented it.', 'But shows contrast: I want to go out (positive) but it''s raining (problem).', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Linking word"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('dc43a8e5-e731-4b88-9aa0-e83441b0bfa7', 398, 'multiple_choice', 'A2', 'conjunctions', 'She''s tired ___ she went to bed early.', 'so', '["than", "but", "because", "so"]', NULL, NULL, NULL, 'Cause and effect — tired ___ early bed.', 'So shows result: She''s tired → result: she went to bed early.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Linking word"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('7fcc806d-6a68-47fe-9f4d-f2f1fc0b15a6', 23, 'gap_fill', 'B1', 'superlatives', 'That was ___ (good) meal I''ve ever had!', 'the best', NULL, NULL, NULL, NULL, 'Superlative of ''good''', 'Best is the irregular superlative form of good.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{Superlative}', false, 'Good → better → best.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('320271a1-75f5-4025-b996-677ac41e197d', 116, 'multiple_choice', 'B1', 'gerunds_infinitives', 'I enjoy ___ to music in my free time.', 'listening', '["listen", "to listen", "listening", "listened"]', NULL, NULL, NULL, 'Verbs of liking (enjoy, love, hate) take -ing.', 'Enjoy is followed by gerund (-ing form).', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{"Gerund & infinitive"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('377e0576-e97c-4f80-b37e-f4a59120f786', 121, 'multiple_choice', 'B1', 'superlatives', 'That was ___ film I''ve ever seen!', 'the best', '["the better", "the best", "the good", "better"]', NULL, NULL, NULL, 'Good → better → best. Irregular!', 'Best is the irregular superlative of good.', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{Superlative}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('c8649b09-f96a-4362-a19f-af3328ced48c', 715, 'error_correction', 'A2', 'comparatives', 'She is tallest than her sister.', 'She is taller than her sister.', '[]', NULL, NULL, NULL, NULL, 'One-syllable adjectives use -er (taller), not "tallest". That''s the superlative form.', '2026-02-20 19:09:17.848852+00', NULL, NULL, 'en', '{Comparative}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('6fed53fe-3698-4807-b8cc-475a5abf3f02', 697, 'error_correction', 'B2', 'verb_patterns', 'She suggested me apply for the job.', 'She suggested I apply for the job.', '[]', NULL, NULL, NULL, NULL, '"Suggest" doesn''t take an object + infinitive. Use "suggest + (that) + subject + infinitive".', '2026-02-20 19:09:17.848852+00', NULL, NULL, 'en', '{"Gerund & infinitive"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('837b0e9f-78bd-4e70-b0d8-8e68bf2b8945', 136, 'multiple_choice', 'B2', 'gerunds_infinitives', 'I stopped ___ cigarettes five years ago.', 'smoking', '["smoke", "to smoke", "smoking", "smoked"]', NULL, NULL, NULL, 'Stopped doing it — gave it up. ("Stopped to smoke" would mean something else!)', 'Stop + gerund means to quit doing something.', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{"Gerund & infinitive"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('95b4b256-88b7-40da-b3ed-e6ea078e96ab', 186, 'multiple_choice', 'B2', 'verb_patterns_allow', 'My parents don''t allow me ___ out late.', 'to stay', '["stay", "to stay", "staying", "stayed"]', NULL, NULL, NULL, 'Allow + person + to + infinitive.', 'Allow + object + to + infinitive.', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{"Gerund & infinitive"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('944bd84d-9218-4542-a9c3-1b969aa64244', 704, 'error_correction', 'B2', 'gerunds_and_infinitives', 'I look forward to hear from you.', 'I look forward to hearing from you.', '[]', NULL, NULL, NULL, NULL, '"Look forward to" is followed by the gerund (-ing), not the base form.', '2026-02-20 19:09:17.848852+00', NULL, NULL, 'en', '{"Gerund & infinitive"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('a7ccfce0-fe46-40c5-a3a7-608e3e45fced', 626, 'sentence_building', 'A2', 'comparatives', 'Ella es más alta que su hermano.', 'she is taller than her brother', '["she", "is", "taller", "than", "her", "brother", "more", "the"]', NULL, NULL, NULL, NULL, 'Short adjectives use -er + than for comparisons. ''Taller than'' not ''more tall than''.', '2026-02-13 08:00:10.850224+00', NULL, NULL, 'both', '{Comparative}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('3e5cf8f5-aaf7-450a-b7f9-8e34ccd19458', 187, 'multiple_choice', 'B1', 'superlatives_place', 'This is ___ expensive restaurant in town.', 'the most', '["more", "most", "the more", "the most"]', NULL, NULL, NULL, 'Long adjective superlative — needs the longer form.', 'The + superlative.', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{Superlative}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('c323f6e8-31d7-44c5-8ae3-d590a1856f29', 200, 'multiple_choice', 'B2', 'verb_patterns_manage', 'I finally managed ___ the problem.', 'to solve', '["solve", "to solve", "solving", "solved"]', NULL, NULL, NULL, 'Managed + to + infinitive.', 'Manage + to + infinitive (succeed in doing something difficult).', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{"Gerund & infinitive"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('eff42f92-f50d-451f-8682-0fc861e3eabf', 287, 'gap_fill', 'A2', 'comparatives', 'English is ___ (easy) than Japanese!', 'easier', NULL, NULL, NULL, NULL, 'Adjective ending in -y changes spelling.', 'Adjectives ending in -y: change to -ier. Easy → easier.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{Comparative}', false, 'Easy → easier. Happy → happier.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('fd2df5d0-0e18-4c26-8a6c-12b72b9ffc3c', 291, 'gap_fill', 'A2', 'superlatives', 'This is the ___ (tall) building in the city.', 'tallest', NULL, NULL, NULL, NULL, 'Short adjective superlative.', 'Superlative: the + adjective-est for short adjectives.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{Superlative}', false, 'Tall → taller → tallest.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('58bdbcaa-a5ac-405c-b04d-2f77e7599117', 292, 'gap_fill', 'A2', 'superlatives', 'She is the ___ (intelligent) student in the class.', 'most intelligent', NULL, NULL, NULL, NULL, 'Long adjective — needs "most".', 'Superlative with long adjectives: the most + adjective.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{Superlative}', false, 'Intelligent (4 syllables) → "the most intelligent".', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('df636f39-ebb5-4b3d-9d6c-6a276b896672', 293, 'gap_fill', 'A2', 'superlatives', 'What is the ___ (good) restaurant in town?', 'best', NULL, NULL, NULL, NULL, 'Superlative of "good".', 'Good is irregular: good → better → best.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{Superlative}', false, 'Good → better → best.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('39568314-cd0a-4479-95b4-0ffb32ddac59', 404, 'gap_fill', 'C1', 'mixed_conditionals', 'If we ___ (leave) earlier, we wouldn''t be stuck in traffic now.', 'had left', NULL, '["''d left"]', NULL, NULL, 'Past condition (didn''t leave) → present consequence (stuck now).', 'Mixed conditional: If + past perfect for the unreal past condition.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{Conditional}', false, 'Form: had + past participle.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('d73a611e-2188-43af-ba2a-e0fd996b6999', 405, 'gap_fill', 'C2', 'mixed_conditionals', 'Were it not for her dedication, she ___ (never / achieve) such success.', 'would never have achieved', NULL, '["''d never have achieved"]', NULL, NULL, 'Formal "Were it not for X..." — past consequence.', 'Formal inversion: Were it not for = If it were not for. Quite formal register.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{Conditional}', false, 'Form: would (never) have + past participle.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('18b7b3f3-399b-466f-a84a-dd90a2d4b725', 454, 'gap_fill', 'C1', 'collocations', 'The incident ___ serious concerns about safety standards.', 'raised', NULL, NULL, NULL, NULL, '"___ concerns" — to bring up an issue.', 'Raise concerns = cause people to worry about something.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{Collocation}', false, '___ concerns, ___ questions, ___ doubts — same verb.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('fd3ef5eb-d2cf-4ba6-9a66-a15315592b8a', 2267, 'multiple_choice', 'B2', 'travel', 'I wish we ___ booked an earlier flight.', 'had', '["had", "have", "did", "would"]', NULL, NULL, NULL, 'Regret about the past uses the past perfect.', '"I wish + past perfect" expresses regret about the past: "I wish we had booked".', '2026-06-01 07:33:21.080816+00', NULL, NULL, 'en', '{Tense}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('35434388-935b-4ab1-aca6-9dc8a674ef58', 141, 'multiple_choice', 'B1', 'question_tags', 'You''re coming to the party, ___?', 'aren''t you', '["isn''t it", "aren''t you", "won''t you", "don''t you"]', NULL, NULL, NULL, 'Positive statement → negative tag. The verb in the tag matches the verb in the sentence.', 'Negative question tag after positive statement.', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{"Question form"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('f8e7d6ee-f37b-4fe8-9da0-f305eee2be9c', 197, 'multiple_choice', 'B1', 'much_many_questions', 'How ___ people are coming to dinner?', 'many', '["much", "many", "lot", "lots"]', NULL, NULL, NULL, 'People are countable: 1 person, 2 people.', 'How many with countable nouns.', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{"Question form"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('3765ce23-53f8-402f-bc22-47186e9d8dad', 251, 'gap_fill', 'A1', 'prepositions_of_time', 'I wake up ___ 7 o''clock.', 'at', NULL, NULL, NULL, NULL, 'Clock times take a particular preposition.', 'Use at with specific times: at 7 o''clock, at midnight.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Preposition of time"}', false, '___ 7, ___ 9 am, ___ midnight.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('f46adf44-e6d9-4c6f-bb90-ad4add58abdf', 252, 'gap_fill', 'A1', 'prepositions_of_time', 'My birthday is ___ March.', 'in', NULL, NULL, NULL, NULL, 'Months take a particular preposition.', 'Use in with months: in March, in June.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Preposition of time"}', false, '___ March, ___ July, ___ December.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('774e02f2-3fa9-4233-9570-c6c7e2ddcd7f', 625, 'sentence_building', 'A2', 'infinitives', 'Necesito comprar algo de comida.', 'I need to buy some food', '["I", "need", "to", "foods", "buy", "some", "food", "want", "the"]', NULL, NULL, NULL, NULL, '''Need to'' is followed by the infinitive verb. We use ''some'' with uncountable nouns in positive sentences.', '2026-02-13 08:00:10.850224+00', NULL, NULL, 'en', '{"Gerund & infinitive"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('6256d4e9-d994-4793-ad2a-9856b971674d', 361, 'multiple_choice', 'A1', 'basic_questions', '___ is your name?', 'What', '["Who", "What", "Where", "When"]', NULL, NULL, NULL, 'Asking for something specific (a name).', 'What for asking about things: What is your name?', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Question form"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('ee7a60a2-dbc7-4b78-9c7f-2909b2446f8f', 648, 'sentence_building', 'A2', 'past_simple', 'Ayer fui al supermercado con mi madre.', 'yesterday I went to the supermarket with my mother', '["yesterday", "I", "went", "to", "the", "supermarket", "with", "my", "mother", "go", "a", "father"]', '["I went to the supermarket with my mother yesterday."]', NULL, NULL, NULL, 'Past simple irregular: go -> went. "Al" = to the.', '2026-02-17 09:58:54.170896+00', NULL, NULL, 'en', '{"Past tense"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('7ad4a7ba-d748-4e68-ba1a-462aed46b8a2', 647, 'sentence_building', 'A2', 'past_continuous', '', 'he was watching TV when the phone rang', '["he", "was", "watching", "TV", "when", "the", "phone", "rang", "watched", "rings", "ringing", "is"]', '["the phone rang when he was watching TV. ", ["when he was watching TV the phone rang"]]', NULL, NULL, NULL, 'Past continuous interrupted by past simple: was + -ing when + past simple.', '2026-02-17 09:58:54.170896+00', NULL, NULL, 'en', '{"Past tense"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('0b842d55-99f7-4bd2-bfc4-d5647a46efe7', 656, 'sentence_building', 'B2', 'past_perfect', '', 'by the time we arrived the film had already started', '["by", "the", "time", "we", "arrived", "the", "film", "had", "already", "started", "has", "will", "starting"]', NULL, NULL, NULL, NULL, 'Past perfect: had + past participle. One past action completed before another.', '2026-02-17 09:58:54.170896+00', NULL, NULL, 'en', '{"Past tense"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('5ccf2951-5956-4e24-a106-150c04d0271c', 362, 'multiple_choice', 'A1', 'basic_questions', '___ are you from?', 'Where', '["What", "Who", "Where", "When"]', NULL, NULL, NULL, 'Asking for a place (origin).', 'Where for asking about places: Where are you from?', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Question form"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('3717367d-0274-4b14-8965-7acc9d4da875', 363, 'multiple_choice', 'A1', 'basic_questions', '___ old are you?', 'How', '["What", "How", "Where", "Who"]', NULL, NULL, NULL, 'Asking about age — a specific question word.', 'How old...? for asking about age.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Question form"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('57952f81-2e0b-4b0a-bab1-893df7137913', 406, 'gap_fill', 'C1', 'mixed_conditionals', 'If I ___ (know) you were coming, I would have prepared dinner.', 'had known', NULL, NULL, NULL, '["knew"]', 'Pure third conditional — both clauses past.', 'Third conditional: If + past perfect, would have + past participle. Natives might use "If I knew..." but it itsn''t technically correct.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{Conditional}', false, 'Form: had + past participle in if-clause.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('0ce2be98-dbc9-4865-bbf4-30cae777acd4', 407, 'gap_fill', 'C1', 'mixed_conditionals', 'She wouldn''t have got the promotion if she ___ (not work) so hard.', 'hadn''t worked', NULL, NULL, NULL, NULL, 'Third conditional — past consequence requires past condition.', 'Third conditional negative: hadn''t + past participle in the if-clause.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{Conditional}', false, 'Form: hadn''t + past participle.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('60b45b33-6df4-4365-af1d-58b00cb9bc05', 693, 'error_correction', 'A2', 'verb_patterns', 'I''m agree with you.', 'I agree with you.', '[]', NULL, NULL, NULL, NULL, '"Agree" is a verb, not an adjective — we don''t use "am" before it. It''s a typical mistake Spanish speakers make. ', '2026-02-20 19:09:17.848852+00', NULL, NULL, 'en', '{"Gerund & infinitive"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('e4141d9f-982f-474e-bf8d-66115df1b0f9', 2268, 'multiple_choice', 'B2', 'travel', 'The hotel, ___ overlooks the bay, was fully booked.', 'which', '["which", "who", "that", "where"]', NULL, NULL, NULL, 'Non-defining relative clause about a thing.', '"Which" introduces a non-defining relative clause about a thing.', '2026-06-01 07:33:21.080816+00', NULL, NULL, 'en', '{"Relative clause"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('dea1d3fb-91e8-469a-8580-f65cf4491396', 660, 'sentence_building', 'B2', 'used_to', 'No estoy acostumbrado a levantarme tan temprano.', 'I am not used to getting up so early', '["I", "am", "not", "used", "to", "getting", "up", "so", "early", "get", "usually", "very"]', NULL, NULL, NULL, NULL, 'Be used to + -ing: describes what you are or aren''t accustomed to.', '2026-02-17 09:58:54.170896+00', NULL, NULL, 'en', '{"Past tense"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('a5ae48e9-0c65-49b1-b09d-c0be05647d19', 627, 'sentence_building', 'A2', 'past_simple', 'Ayer fuimos al parque.', 'yesterday we went to the park', '["yesterday", "go", "we", "went", "to", "the", "park", "go", "a"]', NULL, NULL, NULL, NULL, '''Go'' becomes ''went'' in the past simple. Time expressions like ''yesterday'' often go at the start of the sentence.', '2026-02-13 08:00:10.850224+00', NULL, NULL, 'en', '{"Past tense"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('c3726d95-d797-48a0-937f-3e021acc1dbb', 1205, 'sentence_building', 'C1', 'routines', 'He adquirido el hábito de revisar mis objetivos cada lunes por la mañana.', 'I have got into the habit of reviewing my goals every Monday morning.', '["I", "have", "got", "into", "the", "habit", "of", "reviewing", "my", "goals", "every", "Monday", "morning", "review", "acquired", "weekly"]', NULL, NULL, NULL, NULL, 'Get into the habit of + gerund describes the establishment of a regular behaviour. The present perfect shows this is a recently acquired habit.', '2026-03-16 09:04:17.945706+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('b89245a0-6ce3-4f61-8173-07b0e857187a', 408, 'gap_fill', 'C2', 'mixed_conditionals', 'Had I ___ (realise) the consequences, I would never have agreed.', 'realised', NULL, NULL, NULL, NULL, 'Inversion conditional: "Had + subject + past participle" replaces "If I had...".', 'Formal inversion: Had I realised = If I had realised. Literary/formal style. Realized is the American spelling.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{Conditional}', false, 'Same as "If I had realised...".', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('09a6cb5e-1a88-4af4-b4ff-dc67a1631fc5', 409, 'gap_fill', 'C1', 'mixed_conditionals', 'If he ___ (not be) so stubborn, he wouldn''t have lost all his friends.', 'weren''t', NULL, '["wasn''t"]', 'Was is inelegant here, native speakers judge each other on these things. Were always sounds better in hypotheticals. ', NULL, 'Mixed: present condition (he''s stubborn now) → past consequence.', 'This can be either mixed conditional (present trait → past result) or third conditional.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{Conditional}', false, 'Form: ___ (subjunctive negative) for present condition.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('3fc06722-81b3-418c-86f2-d4cbb84103e4', 1, 'gap_fill', 'B1', 'present_perfect', 'I ___ (never / visit) Scotland, but I''d love to go someday.', 'have never visited', NULL, NULL, NULL, NULL, 'Use present perfect for life experiences up to now', 'Present perfect is used for experiences from the past up to the present moment.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{"Present tense"}', false, 'Form: have/has + past participle. ("Have you ever been there?")', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('1121ac1f-0840-402f-bd28-aeae61599372', 1766, 'multiple_choice', 'A1', 'travel', 'At the airport, where do you go to leave your large bags before a flight?', 'the check-in desk', '["the check-in desk", "the departure gate", "the baggage claim", "the customs area"]', NULL, NULL, NULL, 'The desk where you hand over your large bags to the airline before flying.', 'At the check-in desk you register for your flight, drop off large bags, and receive your boarding pass. The departure gate is where you board the plane. Baggage claim is where you collect your bags on arrival. Customs is where officials check what you are bringing into the country.', '2026-03-30 09:41:12.599621+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('620b1215-39a6-4ed2-9171-ef4a5cd4a62c', 2324, 'multiple_choice', 'A2', 'spanish', 'Para jugar al tenis necesitas una ___.', 'raqueta', '["raqueta", "pelota", "red", "bota"]', NULL, NULL, NULL, '"racket".', '"Raqueta" means "racket".', '2026-06-01 07:35:54.312658+00', NULL, NULL, 'es', '{Sport}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('4d25217f-4aeb-492b-bdbb-44ff21c28fd3', 1767, 'multiple_choice', 'A1', 'travel', 'What do you call the bed you sleep in on an overnight train?', 'a sleeper', '["a sleeper", "a bunk", "a cabin", "a couchette"]', NULL, NULL, NULL, 'A bed on a train designed for overnight journeys.', 'A sleeper (or sleeper berth) is a bed on an overnight train. A couchette is a cheaper, less private version — a fold-down seat that converts into a basic bed. A cabin on a train or ferry refers to a private room. Overnight train travel is growing in popularity as a sustainable alternative to flying.', '2026-03-30 09:41:12.599621+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('65533e8d-4bd7-4858-b3c3-c30309906e66', 1768, 'multiple_choice', 'A1', 'travel', 'What does it mean when a hotel is "fully booked"?', 'there are no rooms available', '["there are no rooms available", "the hotel is closed for refurbishment", "all rooms include breakfast", "the hotel only accepts online bookings"]', NULL, NULL, NULL, 'The hotel literally has all of its rooms reserved by other guests.', 'Fully booked means every room has been reserved and no more bookings can be accepted. Compare: sold out (used for tickets and products), no vacancy (the sign hotels display when full), available (rooms are free to book). Always book in advance during peak season to avoid disappointment.', '2026-03-30 09:41:12.599621+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('31be589c-4223-4bb4-8026-aa8190d0a62d', 1769, 'multiple_choice', 'A2', 'travel', 'What is a "layover" when travelling by plane?', 'a stop between flights where you wait at an airport', '["a stop between flights where you wait at an airport", "the fee for carrying extra luggage", "the time between booking and travelling", "a delay caused by bad weather"]', NULL, NULL, NULL, '"Lay-over" literally describes the time you wait while one flight rests before the next.', 'A layover (or stopover) is time spent waiting at an intermediate airport between two flights. Short layovers can be stressful; longer ones can be an opportunity to explore a city. A connecting flight is the second or subsequent flight in a journey with a layover. A direct flight has no change of plane; a non-stop flight has no stops at all.', '2026-03-30 09:41:12.599621+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('93de01dd-4163-4739-850a-411e71ffd684', 1770, 'multiple_choice', 'A2', 'travel', 'What do you call the document that shows all the details of your trip — flights, hotels, and activities?', 'an itinerary', '["an itinerary", "a visa", "a voucher", "a manifest"]', NULL, NULL, NULL, 'From the Latin "iter" meaning journey — your detailed travel schedule.', 'An itinerary is a detailed travel plan showing dates, times, transport, and accommodation. Travel agents and online booking platforms often generate itineraries automatically. A visa is official permission to enter a country. A voucher is a document exchanged for a service. A manifest is a list of passengers or cargo.', '2026-03-30 09:41:12.599621+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('c5d15bcc-6b4f-4461-beb3-7e9e31d03244', 1771, 'multiple_choice', 'A2', 'travel', 'What does it mean to "pack light"?', 'to travel with as little luggage as possible', '["to travel with as little luggage as possible", "to carry only hand luggage on short flights", "to use lightweight suitcases", "to pack mainly light-coloured clothing"]', NULL, NULL, NULL, 'Travelling with as few items as possible — the opposite of overpacking.', 'Pack light means to travel with minimal luggage, taking only what you need. It makes travel easier, avoids checked baggage fees, and allows more flexibility. Experienced travellers often recommend packing light as the single best travel habit to develop.', '2026-03-30 09:41:12.599621+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('df87bb72-9bee-4fcf-8e1d-38540417ab62', 1772, 'multiple_choice', 'A2', 'travel', 'What is "travel sickness"?', 'a feeling of nausea caused by movement during a journey', '["a feeling of nausea caused by movement during a journey", "an illness caught while travelling abroad", "tiredness after a long flight", "an allergic reaction to foreign food"]', NULL, NULL, NULL, 'The unpleasant feeling caused by movement — also called motion sickness.', 'Travel sickness (or motion sickness) is caused by a conflict between what your eyes see and what your inner ear senses during movement. It can happen on cars, boats, planes, and buses. Remedies include looking at the horizon, sitting in the front, and taking medication. Compare: jet lag (tiredness caused by crossing time zones).', '2026-03-30 09:41:12.599621+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('92b78370-1acb-42e5-b41a-678a8fba5d39', 1773, 'multiple_choice', 'A2', 'travel', 'What is "peak season" for a tourist destination?', 'the time of year when most tourists visit and prices are highest', '["the time of year when most tourists visit and prices are highest", "the best time of year for weather only", "the period when flights are cheapest", "the time when hotels offer the most discounts"]', NULL, NULL, NULL, 'The "peak" or highest point of tourist demand — when prices climb the highest.', 'Peak season is when a destination is most popular, usually due to school holidays, good weather, or local events. Prices for flights and accommodation are highest during peak season. Off-peak (low season) and shoulder season (between peak and low) offer lower prices and fewer crowds, though sometimes at the cost of weather or facilities.', '2026-03-30 09:41:12.599621+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('1bdbb386-bc17-448c-ac8e-80e3bd1ca261', 1775, 'multiple_choice', 'A2', 'travel', 'What does "all-inclusive" mean at a resort?', 'food, drinks, and most activities are included in one price', '["food, drinks, and most activities are included in one price", "the hotel includes airport transfers only", "breakfast and dinner are included", "the room price includes flights"]', NULL, NULL, NULL, 'Everything is "included" in one price — food, drinks, and entertainment.', 'An all-inclusive resort includes accommodation, meals, drinks, and often activities and entertainment in one fixed price. It makes budgeting easy but may limit the experience of local restaurants and culture. Compare: half board (breakfast and dinner included), bed and breakfast (B&B — only breakfast included), self-catering (no meals included).', '2026-03-30 09:41:12.599621+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('7d8d408f-caaa-4c81-9fac-1040de7b66bb', 1776, 'multiple_choice', 'B1', 'travel', 'What does it mean when a flight is described as "overbooked"?', 'more seats have been sold than are available on the plane', '["more seats have been sold than are available on the plane", "the flight is carrying more cargo than usual", "the airline has cancelled the flight", "the plane is flying above its normal altitude"]', NULL, NULL, NULL, 'When the airline has sold more tickets than they actually have seats for.', 'Overbooking happens when airlines sell more tickets than seats, betting that some passengers will not show up. When everyone does appear, passengers may be "bumped" — denied boarding in exchange for compensation such as vouchers, cash, or a later flight. Knowing your passenger rights in these situations is very useful when travelling.', '2026-03-30 09:41:12.599621+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('e5c63827-e302-46e9-8bbe-5e11b5f91d7a', 1780, 'multiple_choice', 'B2', 'travel', 'What does it mean when a tourist destination is described as "off the beaten track"?', 'it is away from the main tourist routes and not widely visited', '["it is away from the main tourist routes and not widely visited", "it is difficult to reach by public transport only", "it has poor tourist infrastructure", "it is only accessible on foot"]', NULL, NULL, NULL, 'An idiom — literally, away from the path everyone else has worn down with their feet.', 'Off the beaten track describes places that are not heavily touristed — away from the crowds, less well-known, and often more authentic. Many travellers actively seek out off-the-beaten-track destinations to avoid overtourism and experience a more genuine local culture. Compare: tourist trap (a place that exploits visitors), hidden gem (a little-known place of great quality).', '2026-03-30 09:41:12.599621+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('313fef5a-ab74-4f09-a0f3-06eeb4b2bb78', 2269, 'multiple_choice', 'B2', 'travel', 'Neither the pool nor the gym ___ open during our stay.', 'was', '["was", "were", "are", "being"]', NULL, NULL, NULL, 'With "neither…nor", the verb agrees with the nearer subject (gym).', 'With "neither … nor", the verb agrees with the nearer subject — singular "gym", so "was".', '2026-06-01 07:33:21.080816+00', NULL, NULL, 'en', '{Agreement}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('c4e3d8f6-6808-47c5-8698-489f590650e8', 2270, 'gap_fill', 'C1', 'travel', 'Rarely ___ I encountered such appalling customer service.', 'have', '[]', NULL, NULL, NULL, 'Inversion after "rarely" with the present perfect.', 'Inversion after "Rarely": the auxiliary "have" comes before the subject.', '2026-06-01 07:33:21.080816+00', NULL, NULL, 'en', '{Inversion}', false, 'One word.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('daf71ccd-742a-40de-a976-d5a324d50b3e', 1925, 'matching', 'C1', 'grammar', 'Match each sentence to the grammar feature it demonstrates.', 'match_all_pairs', '[{"left": {"type": "text", "label": "", "content": "He is believed to have left the country."}, "right": {"type": "text", "label": "", "content": "passive with perfect infinitive"}}, {"left": {"type": "text", "label": "", "content": "The report, having been checked, was sent."}, "right": {"type": "text", "label": "", "content": "perfect participle clause"}}, {"left": {"type": "text", "label": "", "content": "Whatever happens, stay calm."}, "right": {"type": "text", "label": "", "content": "concessive whatever-clause"}}, {"left": {"type": "text", "label": "", "content": "She''s bound to know the answer."}, "right": {"type": "text", "label": "", "content": "bound to + infinitive (expressing certainty)"}}]', NULL, NULL, NULL, NULL, NULL, '2026-04-08 18:25:27.713957+00', NULL, NULL, 'en', '{Grammar}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('b6643972-637b-48d4-9b5e-ae9ff6d81690', 1926, 'matching', 'C2', 'grammar', 'Match each sentence to the grammar feature it demonstrates.', 'match_all_pairs', '[{"left": {"type": "text", "label": "", "content": "He had barely sat down when the phone rang."}, "right": {"type": "text", "label": "", "content": "barely ... when (immediate sequence)"}}, {"left": {"type": "text", "label": "", "content": "She can''t have been serious."}, "right": {"type": "text", "label": "", "content": "can''t + perfect infinitive (past deduction)"}}, {"left": {"type": "text", "label": "", "content": "The sooner we address this, the better."}, "right": {"type": "text", "label": "", "content": "the + comparative ... the + comparative"}}, {"left": {"type": "text", "label": "", "content": "Suppose you were offered the job — what would you do?"}, "right": {"type": "text", "label": "", "content": "suppose + past simple (hypothetical)"}}]', NULL, NULL, NULL, NULL, NULL, '2026-04-08 18:25:27.713957+00', NULL, NULL, 'en', '{Grammar}', false, NULL, NULL);
