INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('77e937e2-9fe5-48d7-a793-5bfb23a36840', 1930, 'matching', 'A2', 'spanish', 'Match each Spanish expression to its English meaning.', 'match_all_pairs', '[{"left": {"type": "text", "label": "", "content": "tener ganas de"}, "right": {"type": "text", "label": "", "content": "to feel like doing something"}}, {"left": {"type": "text", "label": "", "content": "estar de acuerdo"}, "right": {"type": "text", "label": "", "content": "to agree"}}, {"left": {"type": "text", "label": "", "content": "dar igual"}, "right": {"type": "text", "label": "", "content": "not to matter"}}, {"left": {"type": "text", "label": "", "content": "echar de menos"}, "right": {"type": "text", "label": "", "content": "to miss someone or something"}}]', NULL, NULL, NULL, NULL, NULL, '2026-04-08 18:25:27.713957+00', NULL, NULL, 'es', '{Vocabulary,Expressions}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('623b8b88-3f8d-4afb-b53b-23076680ca75', 1931, 'matching', 'A2', 'spanish', 'Match each Spanish expression to its English meaning.', 'match_all_pairs', '[{"left": {"type": "text", "label": "", "content": "ponerse en contacto"}, "right": {"type": "text", "label": "", "content": "to get in touch"}}, {"left": {"type": "text", "label": "", "content": "tener en cuenta"}, "right": {"type": "text", "label": "", "content": "to bear in mind"}}, {"left": {"type": "text", "label": "", "content": "a partir de ahora"}, "right": {"type": "text", "label": "", "content": "from now on"}}, {"left": {"type": "text", "label": "", "content": "en serio"}, "right": {"type": "text", "label": "", "content": "seriously / really"}}]', NULL, NULL, NULL, NULL, NULL, '2026-04-08 18:25:27.713957+00', NULL, NULL, 'es', '{Vocabulary,Expressions}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('50476f73-dd0f-4893-a87d-0e44cc6e2a15', 455, 'gap_fill', 'C2', 'collocations', 'The project was carried ___ despite significant opposition.', 'out', NULL, NULL, NULL, NULL, 'Phrasal verb: "carry ___" = execute, complete.', 'Carry out = complete, execute. A project, a plan, research, an investigation.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{Collocation}', false, 'Carry ___ a project, carry ___ a plan, carry ___ research.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('37aec3c8-08b5-4f97-9b07-d0e5ebeb5ef5', 982, 'multiple_choice', 'B2', 'hotel_vocabulary', '_______ board means breakfast and dinner are both included in the room price.', 'Half', '["Half", "Full", "Part", "Board"]', NULL, NULL, NULL, '___ board = breakfast + dinner. (Full board = all three meals.)', 'Half board includes breakfast and dinner. Full board includes all three meals. Bed and breakfast (B&B) includes only breakfast. All-inclusive covers meals, drinks, and sometimes activities.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Hotel vocabulary",Collocation}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('d67c1e4b-41cb-4f5a-b2ef-e75589544fd7', 2271, 'gap_fill', 'C1', 'travel', 'The luggage ___ have been lost somewhere in transit.', 'must', '[]', NULL, NULL, NULL, 'A modal of strong deduction about the past.', '"Must have + past participle" expresses a strong deduction about the past.', '2026-06-01 07:33:21.080816+00', NULL, NULL, 'en', '{"Modal verb"}', false, 'Four letters.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('aac79566-7f61-406b-80ad-19b3ea246c27', 2272, 'gap_fill', 'C1', 'travel', 'Had we known about the strike, we ___ have rebooked.', 'would', '[]', NULL, NULL, NULL, 'The result clause of an inverted third conditional.', 'In an inverted third conditional, the result clause uses "would have": "we would have rebooked".', '2026-06-01 07:33:21.080816+00', NULL, NULL, 'en', '{Conditional}', false, 'Five letters.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('8436720b-974e-4f01-80dd-8b2109cdd961', 2273, 'gap_fill', 'C1', 'travel', 'The itinerary is subject ___ change without notice.', 'to', '[]', NULL, NULL, NULL, '"subject ___ something" = liable to it.', '"Subject to" means liable to or dependent on: "subject to change".', '2026-06-01 07:33:21.080816+00', NULL, NULL, 'en', '{Preposition}', false, 'Two letters.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('00620bf0-e15d-4ab4-8310-b2cbd6e33da7', 2274, 'gap_fill', 'C1', 'travel', 'Not until we landed ___ we realise the time difference.', 'did', '[]', NULL, NULL, NULL, 'Negative inversion needs an auxiliary before the subject.', 'Negative inversion needs an auxiliary before the subject: "Not until … did we realise".', '2026-06-01 07:33:21.080816+00', NULL, NULL, 'en', '{Inversion}', false, 'Three letters.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('77dfbf64-c41d-4d9e-8903-6f14677bf811', 2017, 'multiple_choice', 'A1', 'bathroom_vocabulary', 'The thing we sit on to use the bathroom is called a _______.', 'toilet', '["toilet", "shower", "bath", "sink"]', NULL, NULL, NULL, 'The fixture in the bathroom designed for human waste.', 'A toilet is used to remove waste from the body.', '2026-04-16 07:35:16.933644+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('540ebf2f-815f-49d3-ace3-5c8fbb4f2df6', 2018, 'multiple_choice', 'A1', 'bathroom_vocabulary', 'The thing in a bathroom where you stand up to wash yourself is called a _______.', 'shower', '["shower", "bath", "tray", "basin"]', NULL, NULL, NULL, 'Where you stand under running water to wash.', 'A shower is used to wash while standing up. A bath is used lying down.', '2026-04-16 07:35:16.933644+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('1aace3e0-07e8-4885-8c85-82edc1783482', 2019, 'multiple_choice', 'A1', 'bathroom_vocabulary', 'The thing in a bathroom where customers wash their hands is called a _______.', 'basin', '["basin", "bath", "bowl", "tray"]', NULL, NULL, NULL, 'A small bowl for washing hands, fixed to the wall.', 'A basin (also called a washbasin) is the sink in a bathroom used for washing hands.', '2026-04-16 07:35:16.933644+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('4099859b-f430-41f3-878b-5f4d8740ed68', 2020, 'multiple_choice', 'A1', 'bathroom_vocabulary', 'The part of a toilet that you sit on is called the toilet _______.', 'seat', '["seat", "lid", "top", "cover"]', NULL, NULL, NULL, 'The part of the toilet you actually sit on.', 'The toilet seat is the part you sit on. The lid covers the top when not in use.', '2026-04-16 07:35:16.933644+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('882142ac-2e3c-406d-81a7-6fbc83fbe2db', 2021, 'multiple_choice', 'A1', 'bathroom_vocabulary', 'The part at the top of a shower that water comes out of is called the shower _______.', 'head', '["head", "top", "arm", "cap"]', NULL, NULL, NULL, 'The "top" of a shower — where the water comes out.', 'The shower head sprays water. It can often be adjusted to change the flow.', '2026-04-16 07:35:16.933644+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('231f8089-2a2e-4504-a0e7-098be6307c0d', 2022, 'multiple_choice', 'A1', 'bathroom_vocabulary', 'The small object used to stop water draining out of a bath or basin is called a _______.', 'plug', '["plug", "cap", "stopper", "block"]', NULL, NULL, NULL, 'A small object used to block the drain so water doesn''t escape.', 'A plug sits in the drain hole so the bath or basin can fill with water.', '2026-04-16 07:35:16.933644+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('0295adbb-50a5-402e-96d4-43bf4399669e', 2023, 'multiple_choice', 'A1', 'bathroom_vocabulary', 'The button or handle used to clean the toilet with water is called the _______.', 'flush', '["flush", "push", "press", "spray"]', NULL, NULL, NULL, 'The button that releases water to clean the toilet.', 'You press the flush to send water through the toilet after using it.', '2026-04-16 07:35:16.933644+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('6489e5fc-b109-49e6-ac17-49dedb999791', 2024, 'multiple_choice', 'A1', 'bathroom_vocabulary', 'The flat thing fixed to the wall where customers can put their toiletries is called a _______.', 'shelf', '["shelf", "ledge", "platform", "board"]', NULL, NULL, NULL, 'A flat horizontal piece fixed to the wall to hold things.', 'A bathroom shelf holds things like soap, shampoo, and toothbrushes.', '2026-04-16 07:35:16.933644+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('ac04de03-4120-43d1-b438-d3f1dd877334', 2025, 'multiple_choice', 'A1', 'bathroom_vocabulary', 'The flat piece that covers and hides the side of a bath is called a bath _______.', 'panel', '["panel", "board", "side", "cover"]', NULL, NULL, NULL, 'A flat board that hides the side of a bath.', 'A bath panel gives the bath a neat, finished appearance by hiding the space underneath.', '2026-04-16 07:35:16.933644+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('c0e8c4ff-0393-4037-8291-42d3e09a1c06', 2275, 'gap_fill', 'C1', 'travel', 'The hotel prides ___ on its impeccable service.', 'itself', '[]', NULL, NULL, NULL, '"pride ___ on something" takes a reflexive pronoun.', '"Pride itself on" uses a reflexive pronoun referring back to "the hotel".', '2026-06-01 07:33:21.080816+00', NULL, NULL, 'en', '{Pronoun}', false, 'Starts with "it".', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('f0872793-04f2-4cef-8e35-f8922b6c5182', 2277, 'gap_fill', 'C1', 'travel', 'So remote ___ the village that no buses run there.', 'is', '[]', NULL, NULL, NULL, 'Inversion after "so + adjective" at the start.', 'Inversion after "So + adjective": "So remote is the village that …".', '2026-06-01 07:33:21.080816+00', NULL, NULL, 'en', '{Inversion}', false, 'Two letters.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('0dff1681-468c-4b28-930e-24877444f9b5', 1001, 'multiple_choice', 'A2', 'vocabulary', 'The teacher spoke quickly and I couldn''t _______ everything she said.', 'follow', '["follow", "listen", "hear", "catch"]', NULL, NULL, NULL, 'To understand or comprehend (a fast speaker, an instruction).', 'To follow means to understand the logic or sequence of something. Catch has a similar meaning in informal English — I didn''t catch what she said.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Confusable words"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('e7baaabf-4b05-43dc-9ec6-86eaa362a276', 1002, 'multiple_choice', 'A2', 'vocabulary', 'She was _______ when she found out she''d passed — she jumped up and screamed!', 'delighted', '["delighted", "disappointed", "confused", "shocked"]', NULL, NULL, NULL, 'Extremely happy — beyond just "pleased".', 'Delighted means very pleased. It is stronger than happy and is the natural choice when the good news is significant, like passing an exam.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{Collocation}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('8f8fd5d0-8d75-45be-9e03-621be6c52703', 1003, 'multiple_choice', 'A2', 'vocabulary', 'I _______ my umbrella on the bus and had to walk home in the rain.', 'left', '["left", "forgot", "lost", "dropped"]', NULL, NULL, NULL, 'To accidentally not bring something — past simple.', 'Left is used when you deliberately or accidentally put something somewhere and did not take it with you. Forgot implies you did not remember to bring it. Lose implies you do not know where it is.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Confusable words"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('67433f18-7647-4340-b9ab-45753b91f512', 2278, 'gap_fill', 'C1', 'travel', 'We had no ___ but to spend the night at the airport.', 'choice', '[]', NULL, NULL, '[{"answer": "option", "feedback": "Also correct — \"no option but to\" works just as well."}]', '"had no ___ but to do something" = no alternative.', '"Have no choice (or option) but to" means there is no alternative.', '2026-06-01 07:33:21.080816+00', NULL, NULL, 'en', '{Vocabulary}', false, 'Starts with "ch" (or "op" for the alternative).', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('94ca0413-7d8d-4762-b850-b28aedcd17d2', 2279, 'gap_fill', 'C1', 'travel', 'The travel agent assured us the tour ___ go ahead.', 'would', '[]', NULL, NULL, NULL, 'Reported speech — future-in-the-past.', 'Reported speech uses "would" for the future-in-the-past: "the tour would go ahead".', '2026-06-01 07:33:21.080816+00', NULL, NULL, 'en', '{"Reported speech"}', false, 'Five letters.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('ade672a1-0c94-47cc-a561-ac8bcd71c3fd', 2280, 'multiple_choice', 'A2', 'spanish', 'Quiero reservar una ___ para dos noches.', 'habitación', '["habitación", "maleta", "playa", "llave"]', NULL, NULL, NULL, '"room" at a hotel.', '"Habitación" means "room" — what you reserve at a hotel.', '2026-06-01 07:33:21.080816+00', NULL, NULL, 'es', '{Travel}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('d0e64ae9-d53b-49b2-91dd-6ab7a259e83e', 2026, 'multiple_choice', 'A1', 'bathroom_vocabulary', 'The thing fixed to a wall or door where customers can hang their towels or dressing gown is called a _______.', 'hook', '["hook", "ring", "peg", "clip"]', NULL, NULL, NULL, 'A curved piece of metal you hang things on — like a coat or a towel.', 'A hook on a bathroom wall or door is used to hang towels and dressing gowns.', '2026-04-16 07:35:16.933644+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('7b3c3504-c2bd-4c06-a6fd-48f1fe8dd6bd', 2027, 'multiple_choice', 'A2', 'bathroom_vocabulary', 'A tile with a flat, non-shiny surface is described as having a _______ finish.', 'matte', '["matte", "glossy", "satin", "polished"]', NULL, NULL, NULL, 'A flat, non-reflective finish — the opposite of glossy.', 'A matte finish absorbs light and does not shine. The opposite is a glossy finish.', '2026-04-16 07:35:16.933644+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('e7b79f2a-329b-464e-8c40-c7f9d09dcb1e', 2028, 'multiple_choice', 'A2', 'bathroom_vocabulary', 'A toilet that is fixed to the wall with nothing touching the floor is described as _______.', 'wall-hung', '["wall-hung", "freestanding", "raised", "floating"]', NULL, NULL, NULL, 'Mounted on the wall — literally hanging from it, off the floor.', 'A wall-hung toilet is attached directly to the wall, making it easier to clean the floor underneath.', '2026-04-16 07:35:16.933644+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('b379d290-34ad-4651-b371-84aa0b932296', 2029, 'multiple_choice', 'A2', 'bathroom_vocabulary', 'The popular shiny, silver-coloured finish on taps and bathroom fittings is called _______.', 'chrome', '["chrome", "steel", "silver", "nickel"]', NULL, NULL, NULL, 'The shiny silver metal coating — common on taps and bathroom fittings.', 'Chrome is the most common finish for taps and fittings. It is shiny and easy to clean.', '2026-04-16 07:35:16.933644+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('9631969b-5dc5-4893-9561-e4ec7fc311e4', 2030, 'multiple_choice', 'A2', 'bathroom_vocabulary', 'The glass panels around a shower that keep the water inside are called a shower _______.', 'enclosure', '["enclosure", "cabinet", "screen", "cover"]', NULL, NULL, NULL, 'Something that "encloses" or surrounds a space — keeping the water in.', 'A shower enclosure keeps water contained in the shower area. It usually has a door and side panels.', '2026-04-16 07:35:16.933644+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('b5286f94-3d34-4e67-82c0-384bc826e0dc', 2031, 'multiple_choice', 'A2', 'bathroom_vocabulary', 'A towel rail with a warm element inside that dries and warms towels is called a _______ towel rail.', 'heated', '["heated", "electric", "warm", "powered"]', NULL, NULL, NULL, 'Warmed by an internal heating element.', 'A heated towel rail keeps towels warm and dry. Some use hot water pipes, others use electricity.', '2026-04-16 07:35:16.933644+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('4fe16fbf-97fb-417b-83d9-38258b4e4248', 2032, 'multiple_choice', 'A2', 'bathroom_vocabulary', 'The products that a showroom currently has available for customers to buy are called its _______.', 'stock', '["stock", "supply", "range", "inventory"]', NULL, NULL, NULL, 'The products a shop currently has in supply, ready to sell.', 'Stock refers to all the items a shop has available to sell right now.', '2026-04-16 07:35:16.933644+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('0ed607d1-3416-43ff-92f8-8ed6479f8e09', 2033, 'multiple_choice', 'A2', 'bathroom_vocabulary', 'A small piece of tile that a customer can take home to check the colour and finish in their own bathroom is called a _______.', 'sample', '["sample", "copy", "piece", "trial"]', NULL, NULL, NULL, 'A small example of a product — like a test piece a customer can take home.', 'Customers often take samples home to see how a tile looks in their own lighting before buying.', '2026-04-16 07:35:16.933644+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('e479ee7d-bf4c-41cb-a502-d1f33b371793', 2034, 'multiple_choice', 'A2', 'bathroom_vocabulary', 'The box behind or above a toilet that holds the water used for flushing is called a _______.', 'cistern', '["cistern", "tank", "chamber", "container"]', NULL, NULL, NULL, 'From the Latin "cisterna" — a tank or container for storing water.', 'The cistern stores water that is released when you flush the toilet.', '2026-04-16 07:35:16.933644+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('11a17940-ce0a-487c-b5ff-aa3a3140da93', 2035, 'multiple_choice', 'A2', 'bathroom_vocabulary', 'When we send a customer''s order directly to their home, we call this a _______.', 'delivery', '["delivery", "service", "transfer", "dispatch"]', NULL, NULL, NULL, 'Transporting an item to its destination — to the customer''s home.', 'A delivery means taking the customer''s goods to their address.', '2026-04-16 07:35:16.933644+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('b5d994af-b169-4156-a832-2c791eaeae01', 2036, 'multiple_choice', 'A2', 'bathroom_vocabulary', 'When we reduce the price of a product for a customer, we give them a _______.', 'discount', '["discount", "reduction", "deal", "saving"]', NULL, NULL, NULL, 'A reduction in price — what "dis-counts" from the original total.', 'A discount is a lower price. It is often given to regular customers or during a sale.', '2026-04-16 07:35:16.933644+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('ed122e97-4cb3-420d-82ff-83a3d384eede', 2037, 'multiple_choice', 'B1', 'bathroom_vocabulary', 'A shower area with no door or tray, where you walk straight in from the bathroom floor, is called a _______ shower.', 'walk-in', '["walk-in", "wet room", "open", "barrier-free"]', NULL, NULL, NULL, 'Literally a shower you walk into — no door, no step, no tray.', 'A walk-in shower has no barrier to step over. Unlike a wet room, it still has a defined shower area.', '2026-04-16 07:35:16.933644+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('d3b6a83a-e179-4998-b767-7472c009072c', 2038, 'multiple_choice', 'B1', 'bathroom_vocabulary', 'A finish on tiles or fittings that is slightly shiny — between matte and glossy — is described as _______.', 'satin', '["satin", "silk", "semi-matte", "sheen"]', NULL, NULL, NULL, 'A finish named after the smooth fabric — slightly soft, slightly shiny.', 'A satin finish has a subtle, soft shine. It is less reflective than glossy but not as flat as matte.', '2026-04-16 07:35:16.933644+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('a11794ff-dae4-4139-b763-7a93ac2320b9', 2039, 'multiple_choice', 'B1', 'bathroom_vocabulary', 'A room or building where bathroom products are set up for customers to see and experience before buying is called a _______.', 'showroom', '["showroom", "display room", "shop floor", "exhibition"]', NULL, NULL, NULL, 'A room where products are "shown" to customers.', 'A showroom lets customers walk through full bathroom setups to help them make decisions.', '2026-04-16 07:35:16.933644+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('0b551cee-9ff6-4ed9-ad67-063307de9074', 2040, 'multiple_choice', 'B1', 'bathroom_vocabulary', 'Smaller items added to complete a bathroom, such as soap dishes, toilet roll holders, and towel rings, are known as bathroom _______.', 'accessories', '["accessories", "fittings", "additions", "extras"]', NULL, NULL, NULL, 'From the Latin "accedere" — to come towards. The smaller items that come with the main pieces.', 'Bathroom accessories are the smaller functional items that complete a bathroom design.', '2026-04-16 07:35:16.933644+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('47b81db1-9056-4d8e-bfab-557e6f5ed331', 2041, 'multiple_choice', 'B1', 'bathroom_vocabulary', 'A heating system with warm pipes or electric elements built beneath the floor tiles is called _______ heating.', 'underfloor', '["underfloor", "under-tile", "radiant", "floor-level"]', NULL, NULL, NULL, 'Heating that runs under the floor — literally below the tiles.', 'Underfloor heating is popular in bathrooms because it warms the tiles from below, making the floor comfortable to walk on.', '2026-04-16 07:35:16.933644+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('b4f631de-8367-4c9f-9bd7-81c90e53c9f2', 2042, 'gap_fill', 'B2', 'bathroom_vocabulary', 'When a customer confirms an order by paying part of the total price upfront, the amount they pay is called a _______.', 'deposit', NULL, NULL, NULL, NULL, 'A partial payment made in advance to secure an order.', 'A deposit secures the order. The remaining balance is usually paid on delivery or installation.', '2026-04-16 07:35:16.933644+00', NULL, NULL, 'en', '{}', false, 'Single word. Starts with d___.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('1d3f147a-bcb6-4126-b04c-7629b5b89438', 2043, 'gap_fill', 'B2', 'bathroom_vocabulary', 'Before recommending how many tiles to order, it is important to ask the customer for the _______ of their bathroom — its length, width, and height.', 'dimensions', NULL, NULL, NULL, NULL, 'The measurements of a space — length, width, and height.', 'Dimensions are the measurements of a space. Without them, it is impossible to calculate the correct quantity of materials.', '2026-04-16 07:35:16.933644+00', NULL, NULL, 'en', '{}', false, 'Single word. Starts with d___.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('6af40758-b91d-4457-9e15-0a9e0afc86b5', 2044, 'gap_fill', 'B2', 'bathroom_vocabulary', 'The process of fitting bathroom products professionally in a customer''s home is called _______.', 'installation', NULL, NULL, NULL, NULL, 'The process of professionally fitting and connecting equipment.', 'Installation refers to the work done by a plumber or fitter to put products in place correctly.', '2026-04-16 07:35:16.933644+00', NULL, NULL, 'en', '{}', false, 'Single word. Starts with i___.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('42a82a61-439a-4cfd-8220-5ec2e7e31a5f', 2045, 'gap_fill', 'B2', 'bathroom_vocabulary', 'When calculating how many tiles to order, it is good practice to add 10% extra to allow for cutting and _______.', 'wastage', NULL, NULL, NULL, NULL, 'The amount lost or thrown away in a process — broken or off-cut tiles.', 'Wastage accounts for tiles that are cut to fit edges, broken, or incorrectly fitted during installation.', '2026-04-16 07:35:16.933644+00', NULL, NULL, 'en', '{}', false, 'Single word. Starts with w___.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('c03f36df-637a-4668-adf1-7a2f3d1010a7', 2046, 'gap_fill', 'B2', 'bathroom_vocabulary', 'When a customer returns a product they are not satisfied with and we give them their money back, this is called a _______.', 'refund', NULL, NULL, NULL, NULL, 'Returning the money a customer paid — "re-funding" them.', 'A refund returns the customer''s payment in full. It is different from an exchange, where the product is replaced.', '2026-04-16 07:35:16.933644+00', NULL, NULL, 'en', '{}', false, 'Single word. Starts with r___.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('cb8716fe-9360-4adc-8bc0-33aefb41bffa', 2047, 'gap_fill', 'B2', 'bathroom_vocabulary', 'When a new tap or fitting will work correctly with a customer''s existing pipes and water system, we say it is _______ with their plumbing.', 'compatible', NULL, NULL, NULL, NULL, 'Able to work or fit together correctly with something else.', 'Compatible means two things work correctly together. Always check compatibility before recommending a product.', '2026-04-16 07:40:24.456408+00', NULL, NULL, 'en', '{}', false, 'Single word. Starts with c___.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('2aa6c3ba-6122-4565-b860-0913bfa82b32', 1933, 'matching', 'A2', 'spanish', 'Match each Spanish preposition to its English meaning.', 'match_all_pairs', '[{"left": {"type": "text", "label": "", "content": "desde"}, "right": {"type": "text", "label": "", "content": "from / since"}}, {"left": {"type": "text", "label": "", "content": "hasta"}, "right": {"type": "text", "label": "", "content": "until / up to"}}, {"left": {"type": "text", "label": "", "content": "hacia"}, "right": {"type": "text", "label": "", "content": "towards"}}, {"left": {"type": "text", "label": "", "content": "sin"}, "right": {"type": "text", "label": "", "content": "without"}}]', NULL, NULL, NULL, NULL, NULL, '2026-04-08 18:25:27.713957+00', NULL, NULL, 'es', '{Grammar,Preposition}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('7bb225f3-d4f3-4383-9f71-6b37668ff485', 698, 'odd_one_out', 'B1', 'prepositions', 'Which is NOT a preposition of time?', 'among', '["at", "on", "among", "in"]', NULL, NULL, NULL, NULL, '"Among" is a preposition of place. Amongst is a more formal version of among, it means the same thing. We use "at" (time), "on" (day), "in" (month/year).', '2026-02-20 19:09:17.848852+00', NULL, NULL, 'en', '{"Preposition of time"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('f90f0eef-536a-401d-8c18-845b699f26fb', 1944, 'odd_one_out', 'A2', 'grammar', 'Three of these are prepositions of place. Which is the odd one out?', 'during', '["under", "beside", "between", "during"]', NULL, NULL, NULL, NULL, '"During" is a preposition of time. "Under", "beside", and "between" all describe where something is.', '2026-04-08 18:26:42.653742+00', NULL, NULL, 'en', '{Grammar,"Preposition of place"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('1fece76a-b4f7-42eb-8bff-798bed150c41', 262, 'gap_fill', 'A1', 'prepositions_of_place', 'She lives ___ Barcelona.', 'in', NULL, NULL, NULL, NULL, 'Cities and countries take a particular preposition.', 'Use in with cities, countries, and continents.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Preposition of place"}', false, '___ Madrid, ___ Spain, ___ Europe.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('a53e7d5c-f2f4-4437-8adc-7d52de455923', 458, 'gap_fill', 'C1', 'participle_clauses', '___ (complete) the project, the team celebrated with dinner.', 'Having completed', NULL, NULL, NULL, NULL, 'Perfect participle — finished action before main clause.', 'Perfect participle: Having + past participle for a completed action before the main clause.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Participle clause"}', false, '= "After they had completed..."', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('8ff39636-b975-442b-acac-892ff7b5a755', 2276, 'gap_fill', 'C1', 'travel', 'The delays were ___ to severe weather over the Alps.', 'due', '[]', NULL, NULL, '[{"answer": "attributable", "feedback": "Also correct — \"attributable to\" is a more formal way of saying the same thing."}]', 'Caused by something.', '"Due to" (or "attributable to") means caused by something.', '2026-06-01 07:33:21.080816+00', NULL, NULL, 'en', '{Vocabulary}', false, 'Three letters ("due") or a longer formal alternative.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('9de7e149-8dae-46a7-9fa7-bf626a2d7488', 1545, 'gap_fill', 'B2', 'business_vocabulary', 'Following poor results, the board announced a major _____ — cutting costs, selling assets, and reducing headcount.', 'restructuring', NULL, NULL, NULL, '[{"answer": "restructure", "feedback": ""}]', 'A major reorganisation — the prefix *re-* is a big clue.', 'Restructuring refers to significant changes made to a company''s operations, finances, or organisation, usually in response to poor performance. It often involves redundancies and the sale of non-core assets.', '2026-03-26 08:02:12.742714+00', NULL, NULL, 'en', '{}', false, NULL, 'noun');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('2088af5c-3dcb-40eb-899c-8d6e807826cb', 840, 'error_correction', 'C1', 'grammar', 'She is the most talented of the two candidates.', 'She is the more talented of the two candidates.', '[]', NULL, NULL, NULL, NULL, 'When comparing exactly two people or things, use the comparative (-er / more). Use the superlative (-est / most) for three or more. She is the more talented of the two.', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('1be31c52-613c-4c1a-b4c0-79f2e5339f0f', 1741, 'gap_fill', 'B1', 'sport', 'She follows a strict _____ plan that balances cardio, strength training, and rest days.', 'training', NULL, NULL, NULL, '[{"answer": "health", "feedback": "✅ ''Health plan'' works in the wider sense. The model answer ''training plan'' specifically describes the structured cardio/strength/rest schedule."}]', 'The structured programme that organises workouts, intensity, and rest days.', 'A training plan (or training programme) is a structured schedule of exercise designed to help someone reach a specific goal — such as running a 5km, losing weight, or building strength. Training plans vary in length and intensity depending on the goal. Having a plan helps avoid overtraining and ensures balanced progress.', '2026-03-30 08:52:38.502672+00', NULL, NULL, 'en', '{}', false, 'Single word. Starts with t___.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('0b307547-ae24-4b1c-8e69-8367cf368f2d', 3, 'gap_fill', 'B2', 'present_perfect_continuous', 'How long ___ (you / work) on this project? It looks nearly finished.', 'have you been working', NULL, '["have u been working", "''ve u been working"]', 'Using ''u'' for ''you'' is understandable but try to write ''you'' in full.', NULL, 'Think about the duration of an ongoing activity', 'Present perfect continuous emphasizes the duration of an activity from the past until now.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{"Present tense"}', false, 'Form: have/has been + verb-ing.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('ec6f10b2-4bf3-4f21-bc13-b07f8ee96e6c', 2066, 'error_correction', 'B2', 'grammar', 'I wish I was taller when I was younger.', 'I wish I had been taller when I was younger.', '[]', NULL, NULL, NULL, NULL, 'For a wish about the past we use the past perfect: "I wish I had been", not "I wish I was".', '2026-06-01 07:05:45.329436+00', NULL, NULL, 'en', '{Tense}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('636a6f18-de33-4c6d-bf27-330ab31d082d', 2067, 'error_correction', 'B2', 'grammar', 'Neither of the options were acceptable to the team.', 'Neither of the options was acceptable to the team.', '[]', NULL, NULL, NULL, NULL, '"Neither of…" is treated as singular in formal English, so it takes "was", not "were".', '2026-06-01 07:05:45.329436+00', NULL, NULL, 'en', '{Agreement}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('f941fdc6-6b74-4304-a498-f00865711a9c', 2068, 'error_correction', 'B2', 'grammar', 'You shouldn''t have to told her the secret.', 'You shouldn''t have told her the secret.', '[]', NULL, NULL, NULL, NULL, '"Shouldn''t have" is followed directly by the past participle: "shouldn''t have told", with no extra "to".', '2026-06-01 07:05:45.329436+00', NULL, NULL, 'en', '{"Modal verb"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('56db24be-ab17-46c4-94d1-3973a5977402', 2069, 'error_correction', 'B2', 'grammar', 'She suggested to go to the new restaurant.', 'She suggested going to the new restaurant.', '[]', NULL, NULL, NULL, NULL, '"Suggest" is followed by the -ing form, not the infinitive: "suggested going".', '2026-06-01 07:05:45.329436+00', NULL, NULL, 'en', '{Gerund}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('bc0e797e-1664-41e0-8ba4-b6dae5bedde1', 2070, 'error_correction', 'C1', 'grammar', 'Scarcely had we left the house than it began to pour.', 'Scarcely had we left the house when it began to pour.', '[]', NULL, NULL, NULL, NULL, 'After "scarcely … " the correct partner is "when", not "than": "scarcely had we left … when".', '2026-06-01 07:05:45.329436+00', NULL, NULL, 'en', '{Inversion}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('859a57f8-d479-4844-8d72-34f253438685', 2072, 'error_correction', 'C1', 'grammar', 'Hardly had we sat down than the phone rang.', 'Hardly had we sat down when the phone rang.', '[]', NULL, NULL, NULL, NULL, 'After "hardly had …" the correct partner is "when", not "than".', '2026-06-01 07:05:45.329436+00', NULL, NULL, 'en', '{Inversion}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('8add974c-108a-4b67-8fb0-a6393cf2a9ad', 369, 'multiple_choice', 'A1', 'basic_questions', '___ is this? It''s my phone.', 'What', '["Who", "What", "Where", "How"]', NULL, NULL, NULL, 'Asking for a thing.', 'What for identifying objects: What is this?', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Question form"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('82790de7-05ad-4f31-84a7-ea3d565a4850', 483, 'gap_fill', 'C1', 'wish_and_regret', 'If only I ___ (listen) to my parents'' advice.', 'had listened', NULL, '["''d listened"]', NULL, NULL, 'Past regret — should have listened back then.', 'If only + past perfect for strong regret about a past action.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Wish & regret"}', false, 'Form: If only + past perfect.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('e125a7ca-a3bf-4dc9-bbd0-45c4a96a11a8', 2073, 'error_correction', 'C1', 'grammar', 'Were I to known the truth, I would have acted differently.', 'Were I to know the truth, I would have acted differently.', '[]', NULL, NULL, NULL, NULL, 'In "Were I to …" conditionals, the verb stays in the infinitive: "Were I to know", not "to known".', '2026-06-01 07:05:45.329436+00', NULL, NULL, 'en', '{Conditional}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('f5c5c8be-62d2-49f5-ae08-c3f01107182c', 2074, 'error_correction', 'C1', 'grammar', 'The data suggests that the trend are continuing.', 'The data suggests that the trend is continuing.', '[]', NULL, NULL, NULL, NULL, '"The trend" is singular, so it takes "is continuing", not "are continuing".', '2026-06-01 07:05:45.329436+00', NULL, NULL, 'en', '{Agreement}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('5fe9f183-3c5c-4754-a632-96f17d317e2f', 2075, 'error_correction', 'C1', 'grammar', 'She''d rather you didn''t mentioned this to anyone.', 'She''d rather you didn''t mention this to anyone.', '[]', NULL, NULL, NULL, NULL, 'After "didn''t" the verb returns to its base form: "didn''t mention", not "didn''t mentioned".', '2026-06-01 07:05:45.329436+00', NULL, NULL, 'en', '{Tense}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('ea8ddec5-c442-4dee-a870-19829618265f', 2076, 'error_correction', 'C1', 'grammar', 'Seldom have I seen such a dedication to the cause.', 'Seldom have I seen such dedication to the cause.', '[]', NULL, NULL, NULL, NULL, '"Dedication" is uncountable here, so it takes no article: "such dedication", not "such a dedication".', '2026-06-01 07:05:45.329436+00', NULL, NULL, 'en', '{Article}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('aa3f7269-d682-40f2-bae2-a19f23415cd6', 2077, 'error_correction', 'C1', 'grammar', 'It''s high time we leave for the airport.', 'It''s high time we left for the airport.', '[]', NULL, NULL, NULL, NULL, 'The idiom "It''s high time" is followed by the past tense: "It''s high time we left".', '2026-06-01 07:05:45.329436+00', NULL, NULL, 'en', '{Tense}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('99899749-c70a-480c-84a5-c0a781234be1', 2325, 'multiple_choice', 'A2', 'spanish', 'El ___ marcó un gol increíble.', 'jugador', '["jugador", "árbitro", "entrenador", "público"]', NULL, NULL, NULL, '"player".', '"Jugador" means "player".', '2026-06-01 07:35:54.312658+00', NULL, NULL, 'es', '{Sport}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('4dae8217-d0fc-4a91-a914-73ef5eea7e8e', 602, 'sentence_building', 'B1', 'polite_requests', '¿Podrías enviarme el informe antes del viernes?', 'could you send me the report before Friday', '["could", "you", "send", "me", "the", "report", "before", "Friday", "should", "after", "to"]', NULL, NULL, NULL, NULL, '"Could you" is used for polite requests. "Before" = antes de. Both "send me" and "send to me" are correct.', '2026-02-12 15:08:31.507807+00', NULL, NULL, 'both', '{"Making suggestions"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('01b2c34e-1003-4091-b7f6-b45dd1397915', 611, 'sentence_building', 'B1', 'present_perfect_continuous', NULL, 'she has been working here since January', '["she", "has", "been", "working", "here", "since", "January", "is", "from", "at"]', NULL, NULL, NULL, NULL, 'Present perfect continuous (has been working) + "since" for a specific point in time.', '2026-02-12 14:34:46.611844+00', NULL, NULL, 'en', '{"Present tense"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('53129746-68d3-4873-9d3f-545afd91aade', 1093, 'multiple_choice', 'A2', 'business_vocabulary', 'A _______ is an amount of extra money paid to an employee for doing very well.', 'bonus', '["bonus", "salary", "commission", "benefit"]', NULL, NULL, NULL, 'Extra, not regular. Paid for performance, not just for showing up.', 'A bonus is a one-off additional payment for good performance. Compare: commission = a percentage of sales earned by a salesperson; benefit = a non-cash perk such as a company car or health insurance.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Business vocabulary","HR vocabulary","Financial vocabulary","Confusable words"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('837322c3-1cd6-46c4-8f09-15cdaefa5a97', 2281, 'multiple_choice', 'A2', 'spanish', '¿Dónde está la ___ de autobuses?', 'estación', '["estación", "tienda", "cocina", "piscina"]', NULL, NULL, NULL, '"station".', '"Estación" means "station".', '2026-06-01 07:33:21.080816+00', NULL, NULL, 'es', '{Travel}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('c5176dbb-673b-490c-92c1-874d62127b82', 2282, 'multiple_choice', 'A2', 'spanish', 'Necesito comprar un ___ de ida y vuelta.', 'billete', '["billete", "mapa", "hotel", "coche"]', NULL, NULL, NULL, '"ticket" — return.', '"Billete" means "ticket"; "de ida y vuelta" means "return".', '2026-06-01 07:33:21.080816+00', NULL, NULL, 'es', '{Travel}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('40c3022f-0bfc-4740-9f88-d43cb983997d', 2283, 'multiple_choice', 'A2', 'spanish', 'El avión sale ___ las diez de la mañana.', 'a', '["a", "en", "de", "por"]', NULL, NULL, NULL, '"at" a clock time in Spanish.', 'Spanish uses "a" for clock times: "a las diez".', '2026-06-01 07:33:21.080816+00', NULL, NULL, 'es', '{Travel}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('2d977ad0-e42d-4d83-a0fa-2e0997f9f011', 2284, 'multiple_choice', 'A2', 'spanish', 'Vamos ___ la playa en coche.', 'a', '["a", "en", "de", "por"]', NULL, NULL, NULL, 'Movement towards a place.', '"A" shows movement towards a place: "vamos a la playa".', '2026-06-01 07:33:21.080816+00', NULL, NULL, 'es', '{Travel}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('68608ac5-7c08-4e4a-b551-4877dd2471ab', 2285, 'multiple_choice', 'A2', 'spanish', '¿Tiene una ___ de la ciudad?', 'mapa', '["mapa", "llave", "maleta", "cama"]', NULL, NULL, NULL, '"map".', '"Mapa" means "map" — note it is masculine ("un mapa") despite ending in -a.', '2026-06-01 07:33:21.080816+00', NULL, NULL, 'es', '{Travel}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('b3c1a683-6316-460e-8fa3-e45ba112cdfb', 2286, 'multiple_choice', 'A2', 'spanish', 'La ___ del hotel está en la primera planta.', 'recepción', '["recepción", "cocina", "piscina", "playa"]', NULL, NULL, NULL, '"reception".', '"Recepción" means "reception".', '2026-06-01 07:33:21.080816+00', NULL, NULL, 'es', '{Travel}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('b0a8fa0a-ce14-47ad-80dd-b6700aed3ef1', 2287, 'multiple_choice', 'A2', 'spanish', 'Perdí mi ___ y no puedo abrir la puerta.', 'llave', '["llave", "mapa", "billete", "maleta"]', NULL, NULL, NULL, '"key".', '"Llave" means "key".', '2026-06-01 07:33:21.080816+00', NULL, NULL, 'es', '{Travel}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('78362a5f-48ce-4552-a7e5-95a6037f1af8', 2288, 'multiple_choice', 'A2', 'spanish', 'El hotel está ___ del centro, a diez minutos.', 'cerca', '["cerca", "lejos", "dentro", "encima"]', NULL, NULL, NULL, '"near" — a ten-minute walk away.', '"Cerca de" means "near to": "cerca del centro".', '2026-06-01 07:33:21.080816+00', NULL, NULL, 'es', '{Travel}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('434fc45d-33d3-4c76-ab9e-410247f163a4', 1146, 'odd_one_out', 'A1', 'vocabulary', 'Which of these is NOT a colour of the rainbow?', 'pink', '["red", "green", "pink", "blue"]', NULL, NULL, NULL, NULL, 'Pink is not a colour of the rainbow. The colours are red, orange, yellow, green, blue, indigo, and violet.', '2026-03-16 08:29:27.085219+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('fcddf7f4-8812-4ecb-a557-e4401567c1ec', 1094, 'multiple_choice', 'A2', 'business_vocabulary', 'To _______ someone means to officially end their employment.', 'dismiss', '["dismiss", "resign", "retire", "suspend"]', NULL, NULL, NULL, 'The company does this *to* the employee — it''s not something they choose.', 'To dismiss someone means to end their employment, usually for misconduct or poor performance. Compare: resign = to leave voluntarily; retire = to stop working, usually at an older age; make redundant = to eliminate a role due to business reasons.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Business vocabulary","HR vocabulary","Confusable words"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('ce47455f-ae55-4d03-8db6-806142d9d17b', 5, 'gap_fill', 'B1', 'first_conditional', 'If the weather ___ (be) nice tomorrow, we''ll go to the beach.', 'is', NULL, NULL, NULL, '[{"answer": "is being", "feedback": "This isn''t wrong, but ''is'' is more natural in first conditional sentences."}]', 'First conditional uses present simple in the if-clause', 'First conditional: If + present simple, will + infinitive.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{Conditional}', false, 'Form: If + present simple, will + infinitive.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('077da184-5046-4e0f-a776-16b401836d8c', 6, 'gap_fill', 'B2', 'passive_voice', 'This building ___ (construct) in 1892 and it''s still standing today.', 'was constructed', NULL, NULL, NULL, NULL, 'Use passive voice in past simple', 'Passive voice past: was/were + past participle.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{"Passive voice"}', false, 'Form: was/were + past participle.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('d5dc78ac-8dfd-4fc3-8669-b104954ffde0', 7, 'gap_fill', 'B1', 'past_continuous', 'While I ___ (cook) dinner, the phone rang.', 'was cooking', NULL, NULL, NULL, NULL, 'An action in progress when something else happened', 'Past continuous for an action in progress interrupted by another action.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{"Past tense"}', false, 'Form: was/were + verb-ing. The phone rang interrupted it.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('be62cd4a-2eb2-45b1-99b6-10edc4825ae9', 9, 'gap_fill', 'B1', 'second_conditional', 'If I ___ (have) more time, I would learn to play the guitar.', 'had', NULL, NULL, NULL, NULL, 'Second conditional uses past simple in the if-clause', 'Second conditional: If + past simple, would + infinitive (for hypothetical situations).', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{Conditional}', false, 'Form: If + past simple, would + infinitive.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('ebfea555-1327-42e7-9347-6c2867713e81', 10, 'gap_fill', 'B2', 'second_conditional', 'If she ___ (be) here now, she would know what to do.', 'were', NULL, NULL, NULL, '[{"answer": "was", "feedback": "''Was'' is acceptable in modern English, but ''were'' is preferred as it clearly signals a hypothetical situation."}]', 'Use ''were'' for all persons in second conditional', 'In second conditional, ''were'' is traditionally preferred for all persons to show the situation is hypothetical.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{Conditional}', false, '"If I were you..." — hypothetical, even with "I" or "she".', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('76ca5a2e-6d28-4b1f-98cb-0220e2cb4a97', 11, 'gap_fill', 'B1', 'present_perfect', 'She ___ (just / finish) her homework and now she''s watching TV.', 'has just finished', NULL, NULL, NULL, NULL, 'Use present perfect for recently completed actions', 'Present perfect with ''just'' shows an action that finished very recently. The adverb goes before the main verb.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{"Present tense"}', false, '"Just" sits between has/have and the past participle.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('a35f2cea-a2e6-4ff4-8d40-5e6413911412', 12, 'gap_fill', 'B1', 'past_simple', 'I ___ (lose) my wallet last weekend and I still haven''t found it.', 'lost', NULL, NULL, NULL, NULL, 'A completed action at a specific past time', 'Past simple for completed actions at a specific time in the past.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{"Past tense"}', false, '"last weekend" anchors it in the past.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('03257bfb-cfc4-4a33-bbcf-01b870563ade', 13, 'gap_fill', 'B2', 'past_perfect', 'When I arrived at the cinema, the film ___ (already / start).', 'had already started', NULL, NULL, NULL, NULL, 'One past action happened before another', 'Past perfect shows which of two past actions happened first.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{"Past tense"}', false, 'Past perfect happens *before* past simple. The film started, then you arrived.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('6d187e8d-54c8-4783-81c0-797476d2956f', 1228, 'multiple_choice', 'A2', 'business_phrasal_verbs', 'Please _____ the contract before you sign it.', 'look over', '["look over", "look up", "look after", "look into"]', NULL, NULL, NULL, 'To review carefully — same as "go over".', 'Look over means to read or check something quickly to see if it is correct.', '2026-03-18 19:58:52.376507+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('be104a00-4344-44c0-982b-5092ba0312af', 1932, 'matching', 'A2', 'spanish', 'Match each Spanish sentence to the correct tense.', 'match_all_pairs', '[{"left": {"type": "text", "label": "", "content": "Voy al trabajo todos los días."}, "right": {"type": "text", "label": "", "content": "present (habitual action)"}}, {"left": {"type": "text", "label": "", "content": "Fui al médico ayer."}, "right": {"type": "text", "label": "", "content": "preterite (completed past)"}}, {"left": {"type": "text", "label": "", "content": "Cuando era pequeño, vivía en Madrid."}, "right": {"type": "text", "label": "", "content": "imperfect (past habit or description)"}}, {"left": {"type": "text", "label": "", "content": "Mañana iré al supermercado."}, "right": {"type": "text", "label": "", "content": "future"}}]', NULL, NULL, NULL, NULL, NULL, '2026-04-08 18:25:27.713957+00', NULL, NULL, 'es', '{Grammar,Tenses}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('ec635975-47a2-4d11-a7dc-1376e1e5b3e1', 1150, 'odd_one_out', 'A1', 'vocabulary', 'Which of these is NOT a form of transport?', 'ladder', '["bus", "train", "bicycle", "ladder"]', NULL, NULL, NULL, NULL, 'A ladder is a piece of equipment used for climbing, not a form of transport. The others — bus, train, and bicycle — are all used to travel from place to place.', '2026-03-16 08:29:27.085219+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('c2cf1f1f-a2f5-4b49-b76c-6a5314ce912f', 1101, 'multiple_choice', 'B2', 'business_vocabulary', 'A product that generates a large profit relative to its cost is said to have a high profit _______.', 'margin', '["margin", "rate", "percentage", "ratio"]', NULL, NULL, NULL, 'The *difference* between cost and price — not a rate or a ratio.', 'Profit margin is the percentage of revenue that becomes profit after costs. A high margin means the product is very profitable relative to its price.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Business vocabulary","Financial vocabulary",Collocation}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('388b9e98-f72f-47a4-939f-04489813e160', 1155, 'odd_one_out', 'B1', 'vocabulary', 'Which of these is NOT a planet in our solar system?', 'Pluto', '["Mercury", "Venus", "Pluto", "Mars"]', NULL, NULL, NULL, NULL, 'Pluto was reclassified as a dwarf planet by the International Astronomical Union in 2006. Mercury, Venus, and Mars are all recognised planets in our solar system.', '2026-03-16 08:29:27.085219+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('f48b3ae4-5ddf-4eb4-ba26-73b71cf66399', 1157, 'odd_one_out', 'B1', 'grammar', 'Which of these words does NOT introduce a contrast?', 'therefore', '["however", "although", "therefore", "whereas"]', NULL, NULL, NULL, NULL, '"Therefore" introduces a result or conclusion, not a contrast. However, although, and whereas are all used to show contrast between two ideas.', '2026-03-16 08:29:27.085219+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('225e9d37-342e-4747-bd0b-2e7c8c24e20d', 1158, 'odd_one_out', 'B2', 'vocabulary', 'Which of these words does NOT mean to think carefully about something?', 'demand', '["consider", "reflect", "ponder", "demand"]', NULL, NULL, NULL, NULL, '"Demand" means to ask for something forcefully. Consider, reflect, and ponder all mean to think carefully or deeply about something.', '2026-03-16 08:29:27.085219+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('aecb5cb6-f575-4e81-8502-997c303df5c5', 48, 'gap_fill', 'B1', 'adjectives_order', 'She bought a ___ (beautiful / red / Italian) dress.', 'beautiful red Italian', NULL, NULL, NULL, NULL, 'Opinion, size, age, shape, color, origin, material', 'Adjective order: opinion → color → origin.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{Adjective}', false, 'OSASCOMP: Opinion → Size → Age → Shape → Colour → Origin → Material → Purpose.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('70ea8ce3-51c0-4fd4-9a88-bae43925cb29', 1160, 'odd_one_out', 'B2', 'vocabulary', 'Which of these phrasal verbs does NOT mean to cancel something?', 'bring up', '["call off", "back out of", "fall through", "bring up"]', NULL, NULL, NULL, NULL, '"Bring up" means to mention or raise a topic in conversation. Call off, back out of, and fall through all relate to cancelling or not going ahead with something.', '2026-03-16 08:29:27.085219+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('5107c6bc-dbdd-4e1b-8360-734a872836d4', 1161, 'odd_one_out', 'B1', 'vocabulary', 'Which of these words is NOT connected to travel?', 'invoice', '["itinerary", "departure", "invoice", "destination"]', NULL, NULL, NULL, NULL, 'An invoice is a financial document, not connected to travel. Itinerary, departure, and destination are all words commonly used when talking about travel.', '2026-03-16 08:29:27.085219+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('b4081e41-5eb6-4a8f-ab2c-ac14f7662183', 1162, 'odd_one_out', 'B2', 'grammar', 'Which of these words is NOT used to introduce a relative clause?', 'although', '["who", "which", "whose", "although"]', NULL, NULL, NULL, NULL, '"Although" is a subordinating conjunction used to introduce contrast, not a relative pronoun. Who, which, and whose are all relative pronouns used to introduce relative clauses.', '2026-03-16 08:29:27.085219+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('b4af6227-3dfc-4ed8-b59f-e5fa884b9fca', 1149, 'odd_one_out', 'A2', 'idioms', 'Which of these expressions does NOT mean something is easy?', 'hit the sack', '["a piece of cake", "a walk in the park", "hit the sack", "plain sailing"]', NULL, NULL, NULL, NULL, '"Hit the sack" means to go to bed. The other expressions all describe something easy: "a piece of cake", "a walk in the park", and "plain sailing".', '2026-03-16 08:29:27.085219+00', NULL, NULL, 'en', '{}', true, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('fa5c91a4-f6ed-4d5c-b1e6-c6500cc2fd7b', 1163, 'odd_one_out', 'B2', 'vocabulary', 'Which of these is NOT a play by Shakespeare?', 'Oliver Twist
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('93cac49e-4433-4e29-b407-529882d9a7ee', 1148, 'odd_one_out', 'A1', 'vocabulary', 'Which of these is NOT a day of the week?', 'weekend', '["Monday", "Wednesday", "weekend", "Sunday"]', NULL, NULL, NULL, NULL, 'The weekend is a little group, not a day of the week. The seven individual days are Monday, Tuesday, Wednesday, Thursday, Friday, Saturday, and Sunday.', '2026-03-16 08:29:27.085219+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('664caedf-0e3b-4190-bb42-a2ff199422f3', 1151, 'odd_one_out', 'A1', 'vocabulary', 'Which of these is NOT part of the face?', 'neck', '["nose", "eye", "neck", "mouth"]', NULL, NULL, NULL, NULL, 'The neck is what joins the head to the body, not part of the face. The nose, eye, and mouth are all parts of the face.', '2026-03-16 08:29:27.085219+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('840cd94e-84c4-4a82-9439-49d1d33d34f4', 1156, 'odd_one_out', 'B1', 'vocabulary', 'Which of these words does NOT mean happy?', 'nervous', '["cheerful", "content", "elated", "nervous"]', NULL, NULL, NULL, NULL, '"Nervous" means worried or anxious — the opposite of happy. Cheerful, content, and elated all describe positive emotional states.', '2026-03-16 08:29:27.085219+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('039867ee-5806-4f35-965f-26025d2782cf', 1154, 'odd_one_out', 'A2', 'grammar', 'Which of these words does NOT show where something is?', 'despite', '["under", "behind", "despite", "next to"]', NULL, NULL, NULL, NULL, '"Despite" shows relationship, not location. Under, behind, and next to are all prepositions of place that tell you where something is.', '2026-03-16 08:29:27.085219+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('1d2503dc-83a3-47d3-aff7-511207ba22e1', 1164, 'odd_one_out', 'B1', 'vocabulary', 'Which of these adjectives does NOT describe a positive personality trait?', 'grumpy', '["generous", "patient", "grumpy", "reliable"]', NULL, NULL, NULL, NULL, '"Grumpy" describes someone who is always unhappy and vocal about it,  generally considered a negative trait. Generous, patient, and reliable are all positive personality characteristics.', '2026-03-16 08:29:27.085219+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('eb73ab87-1a6c-409f-beca-b94aebcc53c7', 1152, 'odd_one_out', 'A2', 'grammar', 'Which of these verb forms is NOT in the past simple?', 'run', '["walked", "played", "run", "stopped"]', NULL, NULL, NULL, NULL, '"Run" is the present and past participle (third column), not the past simple. Walked, played, and stopped are all past simple forms.', '2026-03-16 08:29:27.085219+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('815fd8c4-8460-4699-9c32-4edeec73d026', 512, 'multiple_choice', 'C2', 'advanced_phrasal_verbs', 'Don''t ___ the importance of regular exercise.', 'play down', '["play up", "play down", "play out", "play off"]', NULL, NULL, NULL, 'To minimise the importance of something — the opposite of "play up".', 'Play down = minimise the importance of something.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Phrasal verb"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('1c9de56a-5d18-4a83-a9c5-73be5fee7db4', 1165, 'odd_one_out', 'C1', 'vocabulary', 'Which of these is NOT a logical fallacy?', 'Occam''s razor', '["ad hominem", "straw man", "Occam''s razor", "false dichotomy"]', NULL, NULL, NULL, NULL, 'Occam''s razor is a philosophical principle stating that the simplest explanation is usually correct — not a logical fallacy. Ad hominem, straw man, and false dichotomy are all recognised logical fallacies.', '2026-03-16 08:29:27.085219+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('e6a27f68-f146-4b5c-ab3f-72913e049a69', 1166, 'odd_one_out', 'C1', 'vocabulary', 'Which of these words does NOT describe a gradual decline?', 'escalate', '["deteriorate", "erode", "wane", "escalate"]', NULL, NULL, NULL, NULL, '"Escalate" means to increase or intensify, the opposite of decline. Deteriorate, erode, and wane all describe a gradual weakening or reduction.', '2026-03-16 08:29:27.085219+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('a26dc4c3-e4d6-4b77-a9df-a7d0c94cb0aa', 1167, 'odd_one_out', 'C1', 'vocabulary', 'Which of these adjectives does NOT suggest ambiguity or uncertainty?', 'categorical', '["ambivalent", "equivocal", "tentative", "categorical"]', NULL, NULL, NULL, NULL, '"Categorical" means absolute and unconditional — leaving no room for doubt. Ambivalent, equivocal, and tentative all suggest uncertainty or a lack of clear commitment.', '2026-03-16 08:29:27.085219+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('c896f954-560c-4f10-a112-84cb850fccd1', 1229, 'multiple_choice', 'A1', 'business_phrasal_verbs', 'The deal _____ because the two sides couldn''t agree on the price.', 'fell through', '["fell through", "fell over", "fell out", "fell behind"]', NULL, NULL, NULL, 'To fail unexpectedly — like falling through a trapdoor.', 'Fall through means a plan or deal fails to happen. Compare: the merger fell through.', '2026-03-18 19:58:52.376507+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('906ba9d9-6cdc-4b11-95c8-5608c1a0d63b', 15, 'gap_fill', 'B1', 'future_going_to', 'Look at those dark clouds! It ___ (rain) soon.', 'is going to rain', NULL, '["is gonna rain"]', '''Gonna'' reflects spoken English, but technically we shouldn''t write like that.', NULL, 'A prediction based on present evidence', 'Going to is used for predictions based on current evidence.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{"Future form"}', false, 'You can see the evidence right now (the dark clouds).', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('7c69761d-179d-4321-a358-0eb0228882b1', 1170, 'odd_one_out', 'C2', 'vocabulary', 'Which of these words does NOT relate to contradiction or opposition?', 'axiom', '["paradox", "oxymoron", "dichotomy", "axiom"]', NULL, NULL, NULL, NULL, 'An axiom is a self-evident truth or established principle — not a contradiction. Paradox, oxymoron, and dichotomy all involve some form of contradiction or opposition.', '2026-03-16 08:29:27.085219+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('f576bfc9-6d3d-4c8b-9206-5c3d9005bb37', 1171, 'odd_one_out', 'C1', 'vocabulary', 'Which of these verbs does NOT mean to make something worse?', 'mitigate', '["exacerbate", "aggravate", "mitigate", "compound"]', NULL, NULL, NULL, NULL, '"Mitigate" means to reduce or lessen the severity of something. Exacerbate, aggravate, and compound all mean to make a situation worse.', '2026-03-16 08:29:27.085219+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('796b97b7-e5a2-421a-9c1f-6b774a2e807c', 1173, 'odd_one_out', 'C1', 'vocabulary', 'Which of these words does NOT describe someone who talks too much?', 'taciturn', '["garrulous", "loquacious", "taciturn", "verbose"]', NULL, NULL, NULL, NULL, '"Taciturn" describes someone who is habitually quiet and says very little. Garrulous, loquacious, and verbose all describe someone who talks a great deal.', '2026-03-16 08:29:27.085219+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('f8c73fa2-b423-46ad-838a-f7402dc64c7f', 1174, 'odd_one_out', 'C2', 'vocabulary', 'Which of these words does NOT describe a feeling of unease?', 'equanimity', '["disquiet", "trepidation", "malaise", "equanimity"]', NULL, NULL, NULL, NULL, '"Equanimity" means calm composure and acceptance, especially in difficult situations. Disquiet, trepidation, and malaise all describe feelings of unease, anxiety, or general discomfort.', '2026-03-16 08:29:27.085219+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('0ee2f70b-6e8b-4030-97a3-4fc4aaa16292', 1175, 'odd_one_out', 'A2', 'spanish', '¿Cuál de estas palabras NO es un insecto?', 'araña', '["hormiga", "mariposa", "araña", "abeja"]', NULL, NULL, NULL, NULL, 'La araña es un arácnido, no un insecto. Los insectos tienen seis patas y tres partes en el cuerpo. Las arañas tienen ocho patas y dos partes.', '2026-03-16 08:29:27.085219+00', NULL, NULL, 'es', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('b17515b9-2650-4b31-b6b0-0b7baf0486a7', 1176, 'odd_one_out', 'A2', 'spanish', '¿Cuál de estas palabras NO es una fruta?', 'zanahoria', '["manzana", "plátano", "zanahoria", "mango"]', NULL, NULL, NULL, NULL, 'La zanahoria es una verdura, no una fruta. Las frutas se desarrollan a partir de la flor de una planta y contienen semillas. La zanahoria es una raíz.', '2026-03-16 08:29:27.085219+00', NULL, NULL, 'es', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('db583fc1-c74d-423e-8e2c-fd687698cfc8', 1177, 'odd_one_out', 'A2', 'spanish', '¿Cuál de estas palabras NO es un verbo?', 'rápido', '["hablar", "correr", "rápido", "comer"]', NULL, NULL, NULL, NULL, '"Rápido" es un adjetivo, no un verbo. Hablar, correr y comer son todos verbos en infinitivo.', '2026-03-16 08:29:27.085219+00', NULL, NULL, 'es', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('ad654977-3a0e-45b8-83a3-73a6aa3a4433', 1178, 'odd_one_out', 'A2', 'spanish', '¿Cuál de estos NO es un color primario en pintura?', 'verde', '["rojo", "azul", "verde", "amarillo"]', NULL, NULL, NULL, NULL, 'El verde no es un color primario en pintura. Los colores primarios en el modelo tradicional de pintura son el rojo, el azul y el amarillo. El verde se forma mezclando azul y amarillo.', '2026-03-16 08:29:27.085219+00', NULL, NULL, 'es', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('840ae3ac-7574-4273-a2db-83f85e26d5d1', 1179, 'odd_one_out', 'A2', 'spanish', '¿Cuál de estas expresiones NO significa tener buena suerte?', 'tener mala pata', '["estar en racha", "caer de pie", "tener mala pata", "tocar la lotería"]', NULL, NULL, NULL, NULL, '"Tener mala pata" significa tener mala suerte, lo contrario de las demás expresiones. Estar en racha, caer de pie y tocar la lotería significan tener buena suerte o fortuna.', '2026-03-16 08:29:27.085219+00', NULL, NULL, 'es', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('aa13526d-b6b5-4445-b8a2-f1d503c427ae', 1180, 'odd_one_out', 'A2', 'spanish', '¿Cuál de estos NO es un animal doméstico?', 'tigre', '["perro", "gato", "conejo", "tigre"]', NULL, NULL, NULL, NULL, 'El tigre es un animal salvaje, no doméstico. El perro, el gato y el conejo son animales que viven habitualmente con personas en casa.', '2026-03-16 08:29:27.085219+00', NULL, NULL, 'es', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('06c28cef-8038-4368-b6a0-86f8f7c040f5', 1181, 'odd_one_out', 'A2', 'spanish', '¿Cuál de estas ciudades NO es la capital de un país hispanohablante?', 'Barcelona', '["Buenos Aires", "Lima", "Barcelona", "Bogotá"]', NULL, NULL, NULL, NULL, 'Barcelona no es la capital de ningún país hispanohablante — es la segunda ciudad más grande de España, cuya capital es Madrid. Buenos Aires, Lima y Bogotá son todas capitales nacionales.', '2026-03-16 08:29:27.085219+00', NULL, NULL, 'es', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('cf793052-5f8d-4cc9-af3e-0cdcd5bee8c9', 1168, 'odd_one_out', 'C2', 'vocabulary', 'Which of these words does NOT mean to criticise someone strongly?', 'extol', '["lambast", "castigate", "censure", "extol"]', NULL, NULL, NULL, NULL, '"Extol" means to praise someone enthusiastically. Lambast, castigate, and censure all mean to criticise or condemn someone strongly.', '2026-03-16 08:29:27.085219+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('d99f9a3e-956d-49fc-9fa3-47bb831a4bb6', 1172, 'odd_one_out', 'C2', 'vocabulary', 'Which of these authors did NOT win the Nobel Prize in Literature?', 'Stephen King', '["Gabriel García Márquez", "Toni Morrison", "Stephen King", "Albert Camus"]', NULL, NULL, NULL, NULL, 'Stephen King has not won the Nobel Prize in Literature. Gabriel García Márquez (1982), Toni Morrison (1993), and Albert Camus (1957) are all Nobel laureates.', '2026-03-16 08:29:27.085219+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('e0d551f1-4dfc-4343-8a2d-6d68236920ef', 1208, 'sentence_building', 'C1', 'routines', 'Establecer un horario de sueño constante tiene beneficios a largo plazo para la salud mental.', 'Establishing a consistent sleep schedule has long-term benefits for mental health.', '["establishing", "a", "consistent", "sleep", "schedule", "has", "long-term", "benefits", "for", "mental", "health", "establish", "regular", "improve", "physical"]', NULL, NULL, NULL, NULL, 'A gerund (Establishing) functions as the subject of this sentence. Long-term benefits are those that persist into the future.', '2026-03-16 09:04:17.945706+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('b7e7f4f2-ae0e-4151-a562-b22ae1b5cfa3', 548, 'multiple_choice', 'C1', 'confusing_words', 'The ___ of the new policy remains to be seen.', 'effect', '["affect", "effective", "effect", "affection"]', NULL, NULL, NULL, 'Noun form — the result. (Don''t confuse with the verb "affect".)', 'Effect (noun) = result, impact. Affect (verb) = influence.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Confusable words"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('90261efb-87aa-47f5-b9c3-677a4ed61a9f', 159, 'multiple_choice', 'B2', 'causative_make', 'My boss made me ___ late yesterday.', 'work', '["to work", "working", "worked", "work"]', NULL, NULL, NULL, 'Make + person + infinitive without "to" — forced action.', 'Make + object + infinitive without ''to''.', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{Causative}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('3fbec3b2-eb3c-4631-8eb7-55a80daa15e0', 566, 'multiple_choice', 'C1', 'advanced_grammar', 'Strange ___ it may seem, he actually enjoys public speaking.', 'as', '["so", "that", "if", "as"]', NULL, NULL, NULL, 'Concession structure: "Strange ___ it may seem".', 'Strange as it may seem = although it seems strange. Concessive clause.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('1ac1c8e5-8cfd-42ac-895f-4112b2fb18af', 1266, 'error_correction', 'A1', 'grammar', 'My sister have a cat.', 'My sister has a cat.', '[]', NULL, NULL, NULL, NULL, 'Third person singular (he/she/it) uses has, not have, in the present simple.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('9c452bf4-93d2-46a9-911d-d6788b970a85', 1268, 'error_correction', 'A1', 'grammar', 'There is twenty students in the class.', 'There are twenty students in the class.', '[]', NULL, NULL, NULL, NULL, 'Use there are with plural nouns. Twenty students is plural, so are is required.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('2437b54d-913a-43ca-9416-31ed07d94ac9', 980, 'multiple_choice', 'B1', 'hotel_vocabulary', 'We asked for _______ rooms — two rooms with a connecting door between them.', 'adjoining', '["adjoining", "adjacent", "attached", "additional"]', NULL, NULL, NULL, 'Two rooms with a connecting door between them.', 'Adjoining rooms share a connecting internal door. Adjacent rooms are next to each other but do not have a connecting door — an important distinction when booking for families.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Hotel vocabulary","Confusable words"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('f6a8e8fa-9ce4-43ca-977d-babf3865538f', 1270, 'error_correction', 'A1', 'grammar', 'I am boring in this lesson.', 'I am bored in this lesson.', '[]', NULL, NULL, NULL, NULL, 'Bored describes how a person feels. Boring describes what causes the feeling. The student is bored, not boring.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('ddb8b9d2-883f-4132-9db8-c6c84421c995', 981, 'multiple_choice', 'B1', 'hotel_vocabulary', 'The _______ will arrange restaurant bookings, theatre tickets and airport transfers for guests.', 'concierge', '["concierge", "maître d''", "manager", "valet"]', NULL, NULL, NULL, 'French-origin word for the staff member who helps guests with arrangements.', 'A concierge is a senior hotel staff member whose role is to assist guests with arrangements — bookings, transport, recommendations, and personal requests.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Hotel vocabulary"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('43348126-85c9-438b-a7e9-99b66513b9cb', 1271, 'error_correction', 'A2', 'routines', 'We go to the gym in Saturdays.', 'We go to the gym on Saturdays.', '[]', NULL, NULL, NULL, NULL, 'Use on with days of the week: on Monday, on Saturdays. In is used for months, seasons, and parts of the day.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('f5ef42ef-a1bd-4338-befb-6d85bae86d22', 1272, 'error_correction', 'A1', 'grammar', 'She have got two brothers.', 'She has got two brothers.', '[]', NULL, NULL, NULL, NULL, 'Third person singular (she) requires has got, not have got.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('0d1270aa-eb3f-4db0-9fde-1ec73440cbb5', 1274, 'error_correction', 'A1', 'grammar', 'He don''t understand the question.', 'He doesn''t understand the question.', '[]', NULL, NULL, NULL, NULL, 'In the third person singular (he/she/it), the negative form is doesn''t, not don''t.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('d8d042d9-7b01-48c6-87dc-919a9f49cf86', 1275, 'error_correction', 'B1', 'routines', 'I am used to get up early for my job.', 'I am used to getting up early for my job.', '[]', NULL, NULL, NULL, NULL, 'Be used to expresses familiarity and is followed by a gerund (-ing). The to here is a preposition, not part of an infinitive marker.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('4e092893-b549-41a5-85c1-4d570547c1ed', 1277, 'error_correction', 'B1', 'routines', 'I have been following this routine since three months.', 'I have been following this routine for three months.', '[]', NULL, NULL, NULL, NULL, 'Use for with a period of time (for three months) and since with a specific point in time (since January).', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('c7579a0e-88b6-4af7-b0b5-ad4f486bad3c', 1280, 'error_correction', 'B2', 'grammar', 'The news are very concerning today.', 'The news is very concerning today.', '[]', NULL, NULL, NULL, NULL, 'News is an uncountable noun and always takes a singular verb, even though it ends in -s.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('919a83f9-1622-4023-b27b-55d97d7fa16c', 1273, 'error_correction', 'A2', 'routines', 'He rarely eats breakfast he just goes at work.', 'He rarely eats breakfast he just goes to work.', '[]', NULL, NULL, NULL, NULL, 'The correct expression is go to work. At work means you are already there; to work indicates movement towards it.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('cd46e1a5-fbbb-4b40-8b71-49c3386225b8', 1265, 'error_correction', 'A1', 'routines', 'I usually going to bed at ten o''clock.', 'I usually go to bed at ten o''clock.', '[]', NULL, NULL, NULL, NULL, 'Present simple for routines, wit hwords like usually and never etc. ', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('c94019d4-8597-4bd3-9a05-785c97ae5529', 1269, 'error_correction', 'A2', 'routines', 'I always have lunch on the same time.', 'I always have lunch at the same time.', '[]', NULL, NULL, NULL, NULL, 'We use at with the same time, we can say ''on time'' meaning when we are supoosed to.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('1063a24b-f09c-4e22-b535-1f872a78c4b1', 1267, 'error_correction', 'A2', 'routines', 'She wake up early every day for work.', 'She wakes up early every day for work.', '[]', NULL, NULL, NULL, NULL, 'The present simple, not the present continuous, is used for regular habits and routines. Remember the third person S!', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('6e9e407a-fe25-4e97-922b-3d8a3a6c51a5', 1276, 'error_correction', 'B2', 'grammar', 'He suggested taking one different route.', 'He suggested taking a different route.', '[]', NULL, NULL, NULL, NULL, 'It''s more natural to use ''a'' than ''one'' in most contexts for native speakers.
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('b4ea8a90-2711-49db-a32d-8bb3a600a210', 1279, 'error_correction', 'B1', 'routines', 'I wish I would fall asleep more easily at night.', 'I wish I could fall asleep more easily at night.', '[]', NULL, NULL, NULL, NULL, 'After I wish, use the past simple for a present wish. In thois case of the verb ''can''. Would in wish clauses is only used to express a desire about someone else''s behaviour.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('138c9da4-240d-43c5-bba0-cd287e2b6553', 1281, 'error_correction', 'B1', 'routines', 'It is worth plan your week in advance.', 'It is worth planning your week in advance.', '[]', NULL, NULL, NULL, NULL, 'Worth is followed by a gerund (-ing), never the infinitive. Other examples: worth trying, worth considering, worth remembering.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('5097ef53-542d-445c-a9f9-f6c307645491', 1282, 'error_correction', 'B2', 'grammar', 'He is the taller player on the team.', 'He is the tallest player on the team.', '[]', NULL, NULL, NULL, NULL, 'One-syllable adjectives form the superlative with the -est, not with most. The here indicates a superlative form, not a comparative.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('c5ab2cc7-69bf-4d21-8cfd-68183748ba89', 1278, 'error_correction', 'B2', 'grammar', 'Despite the bad whether, we enjoyed the trip.', 'Despite the bad weather, we enjoyed the trip.', '[]', NULL, NULL, NULL, NULL, 'Weather and whether sound the same, but at this level we need to know which is which. ', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('1c2ac69f-4735-46f0-a33a-1b2905db0b22', 16, 'gap_fill', 'B2', 'future_continuous', 'This time tomorrow, I ___ (fly) to New York.', 'will be flying', NULL, NULL, NULL, NULL, 'An action in progress at a specific future time', 'Future continuous for actions in progress at a specific time in the future.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{"Future form"}', false, 'Form: will be + verb-ing.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('dcebfc63-a0f7-4451-9a10-4cc7b91b46b4', 571, 'multiple_choice', 'C2', 'advanced_grammar', 'Not only ___ the film win Best Picture, but it also swept every other category.', 'did', '["was", "has", "did", "had"]', NULL, NULL, NULL, 'Inversion after fronted "Not only" — needs an auxiliary.', 'Not only + auxiliary + subject + verb: inversion for emphasis.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('5824a6d3-2e95-4503-9581-dbd0d77575ae', 983, 'multiple_choice', 'B2', 'hotel_vocabulary', 'The hotel offers a _______ rate for employees of large companies — a significant discount on standard prices.', 'corporate', '["corporate", "business", "commercial", "preferred"]', NULL, NULL, NULL, '___ rate = a special price for business clients.', 'A corporate rate is a discounted room price negotiated for employees of a specific company. Hotels offer these to attract regular business travellers.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Hotel vocabulary","Business vocabulary"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('15caf229-2a35-4b61-82b3-c563bead638d', 576, 'multiple_choice', 'C1', 'advanced_grammar', 'Barely ___ she sat down when the phone rang.', 'had', '["was", "did", "has", "had"]', NULL, NULL, NULL, 'Past perfect inversion — like "no sooner had X than Y".', 'Barely had + subject + past participle + when: inversion showing two quick events.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('5156a5a2-8c73-4126-a00c-d75a366f0ac2', 582, 'multiple_choice', 'C1', 'nuance', 'The proposal was ___ rejected by the committee.', 'unanimously', '["anonymously", "spontaneously", "simultaneously", "unanimously"]', NULL, NULL, NULL, 'With everyone agreeing — no dissent.', 'Unanimously = with complete agreement from everyone.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Confusable words"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('f58dc6ad-5b0c-41f9-aaa5-849ba885b66a', 2289, 'multiple_choice', 'A2', 'spanish', '¿Puedo ___ con tarjeta de crédito?', 'pagar', '["pagar", "comer", "dormir", "salir"]', NULL, NULL, NULL, '"to pay".', '"Pagar" means "to pay": "pagar con tarjeta" = "pay by card".', '2026-06-01 07:33:21.080816+00', NULL, NULL, 'es', '{Travel}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('9d049c0c-7947-40e6-880f-29a306251e0a', 1285, 'error_correction', 'C1', 'routines', 'She has accustomed herself to wake up without an alarm.', 'She has accustomed herself to waking up without an alarm.', '[]', NULL, NULL, NULL, NULL, 'Accustom oneself to is followed by a gerund. The to is a preposition here, as in be used to, look forward to, and object to.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('3d0148c4-dc35-47cd-aab3-838ba4bebde7', 1286, 'error_correction', 'C2', 'grammar', 'He took great pride of his punctuality.', 'He took great pride in his punctuality.', '[]', NULL, NULL, NULL, NULL, 'The correct collocation is take pride in. Compare: pride in one''s work, take pride in doing something well.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('b2fd085e-dcbe-477b-987b-8aea8f6d44a2', 1287, 'error_correction', 'C1', 'routines', 'Not having a routine can result to feeling disoriented.', 'Not having a routine can result in feeling disoriented.', '[]', NULL, NULL, NULL, NULL, 'Result in is the correct collocation. Result to does not exist. Compare: result in confusion, result in failure.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('a6231c15-6b81-4362-8a6f-21fc2e8f13a1', 1290, 'error_correction', 'C2', 'grammar', 'The report had a profound affect on government policy.', 'The report had a profound effect on government policy.', '[]', NULL, NULL, NULL, NULL, 'Effect is the noun meaning result or impact. Affect is typically a verb. The correct collocation is have an effect on.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('fea2de56-fa18-4a61-bf73-0273548f974f', 1292, 'error_correction', 'C2', 'grammar', 'She is widely known of her expertise in the field.', 'She is widely known for her expertise in the field.', '[]', NULL, NULL, NULL, NULL, 'Known for is the correct collocation. Compare: famous for, celebrated for, recognised for. Known of means you have heard of someone but don''t know them well.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('b630060f-5001-40f5-804d-a8614dbe2452', 1293, 'error_correction', 'C1', 'routines', 'The key to maintain good habits is starting small and being consistent.', 'The key to maintaining good habits is starting small and being consistent.', '[]', NULL, NULL, NULL, NULL, 'When to functions as a preposition (not an infinitive marker), it is followed by a gerund. Compare: be used to, look forward to, the secret to.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('2a4cbe5d-d118-4fb5-bfc7-85d9cc297173', 1294, 'error_correction', 'C2', 'grammar', 'He spoke to the audience with great eloquency.', 'He spoke to the audience with great eloquence.', '[]', NULL, NULL, NULL, NULL, 'The correct noun form is eloquence. The suffix -ency is not used here — compare: eloquence, resilience, patience.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('e526e381-f3e7-495d-b0cb-7d99350458b0', 1283, 'error_correction', 'B1', 'routines', 'I keep forgetting to taking my vitamins every morning.', 'I keep forgetting to take my vitamins every morning.', '[]', NULL, NULL, NULL, NULL, 'Forget + to + infinitive. Forget to do something means to fail to remember to do it. Forget doing something refers to not remembering a past event — a completely different meaning.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('3dd78060-f577-4ea0-ab4a-29cafe26db8a', 1284, 'error_correction', 'B2', 'grammar', 'If I known the answer, I would tell you.', 'If I knew the answer, I would tell you.', '[]', NULL, NULL, NULL, NULL, 'In second conditional sentences, the if clause uses the past simple, not the past participle. ', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('b52d5ac4-8a2b-4f11-8bc6-5a3430b54f9f', 1288, 'error_correction', 'C2', 'grammar', 'She refrained for commenting on the allegations.', 'She refrained from commenting on the allegations.', '[]', NULL, NULL, NULL, NULL, 'Refrain from is the correct collocation, followed by a gerund. Compare: abstain from, desist from, shy away from.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('dae1a16d-992a-4676-b181-710dc775b743', 1289, 'error_correction', 'C1', 'routines', 'The extent at which daily habits shape our behaviour is often overlooked.', 'The extent to which daily habits shape our behaviour is often overlooked.', '[]', NULL, NULL, NULL, NULL, 'The correct phrase is the extent to which. This is a fixed relative clause structure — to which, not at which.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('b8bd6f3b-ec57-4b41-bb58-8bbb8db9d581', 1291, 'error_correction', 'C1', 'routines', 'Blocking off time in your diary for rest is rarely a waste of it.', 'Blocking out time in your diary for rest is rarely a waste of it.', '[]', NULL, NULL, NULL, NULL, 'Block out time is the correct phrasal verb, meaning to deliberately reserve a period in your schedule. Block time  off is not a standard expression.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('2cc058e5-fab3-430f-ada5-8db0c62ec69b', 1295, 'error_correction', 'A2', 'spanish', 'Me gusta levantarme pronto para las mañanas.', 'Me gusta levantarme pronto por las mañanas.', '[]', NULL, NULL, NULL, NULL, 'La expresión correcta es "por las mañanas". Por se usa con partes del día: por la mañana, por la tarde, por la noche.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'es', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('946b56d1-ec0a-4020-8ad3-64f86df55664', 17, 'gap_fill', 'B1', 'modals_ability', 'When I was younger, I ___ (can / run) really fast.', 'could run', NULL, NULL, NULL, NULL, 'Past ability uses ''could''', 'Could + infinitive expresses past ability.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{"Modal verb"}', false, 'The past form of "can".', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('8d76327e-711d-4c84-b5b8-81a9961b2643', 2294, 'multiple_choice', 'A2', 'sport', 'You need a good ___ to play tennis.', 'racket', '["racket", "bat", "stick", "glove"]', NULL, NULL, NULL, 'The equipment for hitting a tennis ball.', 'A "racket" is the equipment used to hit the ball in tennis.', '2026-06-01 07:35:54.312658+00', NULL, NULL, 'en', '{Sport}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('ed849172-939d-4dc5-870c-101b1fd51c47', 2295, 'multiple_choice', 'A2', 'sport', 'The football match is at the ___.', 'stadium', '["stadium", "court", "pool", "track"]', NULL, NULL, NULL, 'A large place where big matches are played.', 'A "stadium" is the large venue where big matches are played.', '2026-06-01 07:35:54.312658+00', NULL, NULL, 'en', '{Sport}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('5d7542ae-6c08-4515-987d-54ca6134341f', 2296, 'multiple_choice', 'A2', 'sport', 'He scored a brilliant ___ in the last minute.', 'goal', '["goal", "point", "set", "race"]', NULL, NULL, NULL, 'What you score in football.', 'You score a "goal" in football.', '2026-06-01 07:35:54.312658+00', NULL, NULL, 'en', '{Sport}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('c86bf2e7-6440-4cad-b739-0f48ea1336f0', 2297, 'multiple_choice', 'A2', 'sport', 'The runners are warming ___ before the race.', 'up', '["up", "on", "in", "off"]', NULL, NULL, NULL, '"warm ___" = prepare your body for exercise.', '"Warm up" means to prepare your body before exercise.', '2026-06-01 07:35:54.312658+00', NULL, NULL, 'en', '{Sport}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('92c91258-168a-4ed7-8ab9-5be309b7a20a', 2298, 'multiple_choice', 'A2', 'sport', 'She''s the fastest ___ on the team.', 'runner', '["runner", "running", "run", "runs"]', NULL, NULL, NULL, 'The person who runs.', '"Runner" is the person who runs (the noun, not the verb form).', '2026-06-01 07:35:54.312658+00', NULL, NULL, 'en', '{Sport}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('d746827c-5a53-4cd7-8821-3e3b8987c0b2', 2299, 'multiple_choice', 'A2', 'sport', 'We watched the ___ between the two best players.', 'match', '["match", "play", "show", "practice"]', NULL, NULL, NULL, 'A contest between two sides.', 'A "match" is a contest between two players or teams.', '2026-06-01 07:35:54.312658+00', NULL, NULL, 'en', '{Sport}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('e054be9b-95d1-41ff-8e11-508ff374f83d', 2300, 'gap_fill', 'B2', 'sport', 'He''s been ___ for the marathon since January.', 'training', '[]', NULL, NULL, NULL, 'Present perfect continuous — the -ing form after "been".', 'Present perfect continuous: "has been training" for an action continuing up to now.', '2026-06-01 07:35:54.312658+00', NULL, NULL, 'en', '{Tense}', false, '-ing form.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('3b2245df-7569-4bda-984a-4be4b0f4e9c2', 2309, 'multiple_choice', 'B2', 'sport', 'Few sports are ___ exhausting as boxing.', 'as', '["as", "so", "more", "than"]', NULL, NULL, NULL, '"___ … as" — a comparison of equality.', 'Comparison of equality: "as + adjective + as": "as exhausting as boxing".', '2026-06-01 07:35:54.312658+00', NULL, NULL, 'en', '{Comparative}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('fd563bbb-35a7-4057-b76b-daa3ffb2ae8d', 2310, 'gap_fill', 'C1', 'sport', 'Never before ___ the team achieved such a result.', 'had', '[]', NULL, NULL, NULL, 'Inversion after "never before" with the past perfect.', 'Inversion after "Never before": the auxiliary "had" comes before the subject.', '2026-06-01 07:35:54.312658+00', NULL, NULL, 'en', '{Inversion}', false, 'Three letters.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('bfeed9a4-8be4-4274-ad67-e866a3748807', 2311, 'gap_fill', 'C1', 'sport', 'The athlete attributed her success ___ years of discipline.', 'to', '[]', NULL, NULL, NULL, '"attribute something ___ a cause".', 'The pattern is "attribute something to a cause".', '2026-06-01 07:35:54.312658+00', NULL, NULL, 'en', '{Preposition}', false, 'Two letters.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('006a041a-188b-4854-8102-5c8fe4789dd8', 2312, 'gap_fill', 'C1', 'sport', 'So determined ___ the rookie that nothing could stop him.', 'was', '[]', NULL, NULL, NULL, 'Inversion after "so + adjective" at the start.', 'Inversion after "So + adjective": "So determined was the rookie that …".', '2026-06-01 07:35:54.312658+00', NULL, NULL, 'en', '{Inversion}', false, 'Three letters.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('81e70a95-d188-4241-9075-12d8f39c6fb4', 2313, 'gap_fill', 'C1', 'sport', 'The referee''s decision was met ___ furious protest.', 'with', '[]', NULL, NULL, NULL, '"be met ___ a reaction" = encounter it.', '"Be met with" a reaction means to encounter or receive it.', '2026-06-01 07:35:54.312658+00', NULL, NULL, 'en', '{Preposition}', false, 'Four letters.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('c7226fae-5b36-4ea4-bc49-f2e942be4a58', 1296, 'error_correction', 'A2', 'spanish', 'Ella es muy simpático con todo el mundo.', 'Ella es muy simpática con todo el mundo.', '[]', NULL, NULL, NULL, NULL, 'Los adjetivos en español deben concordar en género con el sustantivo. Ella es femenino, así que el adjetivo debe ser simpática, no simpático.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'es', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('0472d717-82cc-49b9-a66e-b9a30e51e275', 1298, 'error_correction', 'A2', 'spanish', 'Me gustan mucho el café por las mañanas.', 'Me gusta mucho el café por las mañanas.', '[]', NULL, NULL, NULL, NULL, 'Con el verbo gustar, el verbo concuerda con lo que gusta. El café es singular, así que el verbo debe ser gusta, no gustan.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'es', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('9773949c-01e4-4b11-a2f7-6f23f23a7adf', 1297, 'error_correction', 'A2', 'spanish', 'Siempre desayuno a las ocho de lo mañana.', 'Siempre desayuno a las ocho de la mañana.', '[]', NULL, NULL, NULL, NULL, 'La expresión correcta es "de la mañana". El artículo la es necesario: de la mañana, de la tarde, de la noche.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'es', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('513cf21c-cc1d-4b98-893e-69ef8101b23a', 1299, 'error_correction', 'A2', 'spanish', 'Normalmente voy al gimnasio las lunes.', 'Normalmente voy al gimnasio los lunes.', '[]', NULL, NULL, NULL, NULL, 'Para indicar un día de la semana de forma habitual, se usa el artículo los sin preposición: los lunes, los viernes. ', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'es', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('d4aa8201-5fd6-4f53-abc8-cb015d84c4cd', 1300, 'error_correction', 'A2', 'spanish', 'Soy muy cansado hoy porque no dormí bien.', 'Estoy muy cansado hoy porque no dormí bien.', '[]', NULL, NULL, NULL, NULL, 'Estar se usa para estados temporales como el cansancio. Ser se usa para características permanentes. El cansancio es temporal, así que estoy cansado es correcto.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'es', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('2c995fd3-e763-4df9-a355-ed00f0765e3b', 1301, 'error_correction', 'A2', 'spanish', 'Me cepillo los dientes antes de ir a duermo.', 'Me cepillo los dientes antes de ir a dormir.', '[]', NULL, NULL, NULL, NULL, 'Ir a + infinitivo es la estructura correcta. Antes de ir a dormir significa before going to sleep. Sin la preposición a, la frase es incorrecta.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'es', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('d83ad210-5bad-4f84-85a8-bc7a46fe4285', 1303, 'error_correction', 'A2', 'spanish', 'Intento acostar temprano los días entre semana.', 'Intento acostarme temprano los días entre semana.', '[]', NULL, NULL, NULL, NULL, 'Acostarse es un verbo reflexivo. Cuando se usa como infinitivo, el pronombre reflexivo debe concordar con el sujeto: me (yo), te (tú), se (él/ella).', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'es', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('ec652c12-cca9-4766-bf08-9428f49bad79', 1302, 'error_correction', 'A2', 'spanish', 'Mi hermana tiene veintycinco años.', 'Mi hermana tiene veinticinco años.', '[]', NULL, NULL, NULL, NULL, 'Los números del 21 al 29 se escriben en una sola palabra en español usando i: veintiuno, veintidós, veintitrés... veinticinco. No se separan. Desde 30 en adelante lo normal es escribirlos en varias palabras: treinta y uno, cincuenta y siete.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'es', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('2fdb1a60-2ed1-408e-a172-50cd61913478', 1304, 'error_correction', 'A2', 'spanish', 'Ayer fuimos al restaurante y comemos pizza y pasta.', 'Ayer fuimos al restaurante y comimos pizza y pasta.', '[]', NULL, NULL, NULL, NULL, 'Ayer indica pasado, así que el verbo debe estar en pretérito indefinido (comimos), no en presente (comemos). Todos los verbos en la oración deben concordar en tiempo.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'es', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('379519a5-e739-4d7a-af95-4be9d55fd780', 1209, 'sentence_building', 'C2', 'routines', 'Sin darnos cuenta, desarrollamos rituales que nos anclan a una sensación de normalidad.', 'Without realising it, we develop rituals that anchor us to a sense of normality.', '["without", "realising", "it", "we", "develop", "rituals", "that", "anchor", "us", "to", "a", "sense", "of", "normality", "routine", "stability", "knowing"]', NULL, NULL, NULL, NULL, 'Without realising it is a participial phrase describing an unconscious process. Note British spelling: realising, not realizing.', '2026-03-16 09:04:17.945706+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('adcd5955-2924-4913-8a77-19e7eaa35d3d', 2314, 'gap_fill', 'C1', 'sport', 'Had the goalkeeper reacted sooner, the goal ___ have been saved.', 'would', '[]', NULL, NULL, '[{"answer": "might", "feedback": "Also correct — \"might have been saved\" expresses a less certain outcome."}]', 'The result clause of an inverted third conditional.', 'In an inverted third conditional, the result clause uses "would have" (or "might have" for less certainty).', '2026-06-01 07:35:54.312658+00', NULL, NULL, 'en', '{Conditional}', false, '"would" or "might".', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('74d4c9bf-ef27-48a5-a6e3-cf4da997b57f', 2315, 'gap_fill', 'C1', 'sport', 'It was his sheer persistence that ___ him apart from the rest.', 'set', '[]', NULL, NULL, NULL, '"set somebody apart" = make them stand out (past tense here).', '"Set somebody apart" means to make them stand out from others.', '2026-06-01 07:35:54.312658+00', NULL, NULL, 'en', '{"Phrasal verb"}', false, 'Three letters.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('dfc65630-81f0-42da-8805-5c713fb4de23', 2316, 'gap_fill', 'C1', 'sport', 'The new signing has yet ___ prove himself.', 'to', '[]', NULL, NULL, NULL, '"have yet ___ do something" = still hasn''t done it.', '"Have yet to do something" means still not having done it.', '2026-06-01 07:35:54.312658+00', NULL, NULL, 'en', '{Grammar}', false, 'Two letters.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('34d185bc-8681-4153-88dc-808ec901a7ad', 2317, 'gap_fill', 'C1', 'sport', 'Rarely does a player ___ such composure under pressure.', 'show', '[]', NULL, NULL, NULL, 'Bare infinitive after the inverted "rarely does".', 'After the inverted "Rarely does", the main verb is the bare infinitive "show".', '2026-06-01 07:35:54.312658+00', NULL, NULL, 'en', '{Inversion}', false, 'Four letters.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('95aa6e6b-7bdb-46d8-ba6b-f96e13a0bf19', 997, 'multiple_choice', 'A1', 'vocabulary', 'Can you _______ me your pen for a minute? I''ll give it back straight away.', 'lend', '["lend", "borrow", "rent", "take"]', NULL, NULL, NULL, 'To give something temporarily, expecting it back.', 'Lend means to give something temporarily — you lend to someone. Borrow means to receive something temporarily — you borrow from someone. These are commonly confused.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Confusable words"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('525dda97-3db2-410c-9e56-0383f4f160cd', 1934, 'matching', 'A2', 'spanish', 'Match each Spanish word to its English meaning.', 'match_all_pairs', '[{"left": {"type": "text", "label": "", "content": "el alojamiento"}, "right": {"type": "text", "label": "", "content": "accommodation"}}, {"left": {"type": "text", "label": "", "content": "la estancia"}, "right": {"type": "text", "label": "", "content": "the stay"}}, {"left": {"type": "text", "label": "", "content": "el huésped"}, "right": {"type": "text", "label": "", "content": "the guest"}}, {"left": {"type": "text", "label": "", "content": "la habitación"}, "right": {"type": "text", "label": "", "content": "the room"}}]', NULL, NULL, NULL, NULL, NULL, '2026-04-08 18:25:27.713957+00', NULL, NULL, 'es', '{Vocabulary,"Hotel vocabulary"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('bd40f091-aad1-4e4e-979f-5e219836b5e9', 2318, 'gap_fill', 'C1', 'sport', 'The defeat was all the more painful ___ it was avoidable.', 'because', '[]', NULL, NULL, '[{"answer": "since", "feedback": "Also correct — \"since\" works as a reason linker."}, {"answer": "as", "feedback": "Also correct — \"as\" can introduce the reason here too."}]', 'A linking word that introduces the reason.', '"Because", "since" or "as" all introduce the reason for the defeat being painful.', '2026-06-01 07:35:54.312658+00', NULL, NULL, 'en', '{Grammar}', false, '"because", "since" or "as".', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('8dc575c9-9a4b-4c80-abc9-ee6a1cc47191', 1305, 'sentence_auction', 'A1', 'routines', 'Daily routines', 'auction', '[{"correct": true, "sentence": "I wake up at seven o''clock every morning.", "explanation": "Correct. Present simple is used for regular daily habits."}, {"correct": false, "sentence": "She is going to the gym every Monday.", "explanation": "Incorrect. The present continuous is not used for regular habits. It should be: she goes to the gym every Monday."}, {"correct": true, "sentence": "We have dinner at nine o''clock every evening.", "explanation": "Correct. Have dinner in the present simple is the right form for a daily routine."}, {"correct": false, "sentence": "He don''t drink coffee in the morning.", "explanation": "Incorrect. Third person singular requires doesn''t, not don''t."}]', NULL, NULL, NULL, NULL, NULL, '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('afb7cac0-af75-40c9-a92f-45a5435429a4', 1306, 'sentence_auction', 'A1', 'grammar', 'Present simple', 'auction', '[{"correct": true, "sentence": "There are twenty students in my class.", "explanation": "Correct. There are is used with plural nouns."}, {"correct": false, "sentence": "She have got a new job.", "explanation": "Incorrect. Third person singular requires has got, not have got."}, {"correct": true, "sentence": "I like swimming in the sea.", "explanation": "Correct. Like + gerund (-ing) is a standard structure."}, {"correct": false, "sentence": "The children is playing in the garden.", "explanation": "Incorrect. Children is plural and requires are, not is."}]', NULL, NULL, NULL, NULL, NULL, '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('b2753753-2966-409a-b7bb-9b379769f6fb', 1307, 'sentence_auction', 'A2', 'routines', 'Frequency adverbs', 'auction', '[{"correct": true, "sentence": "I usually go for a walk after lunch.", "explanation": "Correct. Usually goes before the main verb."}, {"correct": false, "sentence": "She always is late for work on Mondays.", "explanation": "Incorrect. Frequency adverbs go after the verb to be, not before it. It should be: she is always late."}, {"correct": true, "sentence": "They go to bed early on weekdays.", "explanation": "Correct. On weekdays is the right preposition expression for regular days."}, {"correct": false, "sentence": "I am brushing my teeth twice a day.", "explanation": "Incorrect. Regular habits use the present simple, not the present continuous."}]', NULL, NULL, NULL, NULL, NULL, '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('26e0780e-c8f1-47b5-8018-aedb0d009c25', 1935, 'matching', 'A2', 'spanish', 'Match each Spanish word to its English meaning.', 'match_all_pairs', '[{"left": {"type": "text", "label": "", "content": "disponible"}, "right": {"type": "text", "label": "", "content": "available"}}, {"left": {"type": "text", "label": "", "content": "incluido"}, "right": {"type": "text", "label": "", "content": "included"}}, {"left": {"type": "text", "label": "", "content": "gratuito"}, "right": {"type": "text", "label": "", "content": "free of charge"}}, {"left": {"type": "text", "label": "", "content": "obligatorio"}, "right": {"type": "text", "label": "", "content": "compulsory / required"}}]', NULL, NULL, NULL, NULL, NULL, '2026-04-08 18:25:27.713957+00', NULL, NULL, 'es', '{Vocabulary}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('aab672cd-313f-4a57-af30-4ac7c80d8eba', 1936, 'matching', 'A2', 'spanish', 'Match each Spanish word to its English meaning.', 'match_all_pairs', '[{"left": {"type": "text", "label": "", "content": "el desayuno"}, "right": {"type": "text", "label": "", "content": "breakfast"}}, {"left": {"type": "text", "label": "", "content": "la comida"}, "right": {"type": "text", "label": "", "content": "lunch / food"}}, {"left": {"type": "text", "label": "", "content": "la cena"}, "right": {"type": "text", "label": "", "content": "dinner"}}, {"left": {"type": "text", "label": "", "content": "la merienda"}, "right": {"type": "text", "label": "", "content": "afternoon snack"}}]', NULL, NULL, NULL, NULL, NULL, '2026-04-08 18:25:27.713957+00', NULL, NULL, 'es', '{Vocabulary,Food}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('981bfd38-277c-4dcb-86b4-e98e1d7160d8', 393, 'multiple_choice', 'A1', 'to_be', 'They ___ at school today.', 'are', '["is", "am", "are", "be"]', NULL, NULL, NULL, 'They + verb "to be" in present.', 'To be: I am, you/we/they are, he/she/it is.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"To be"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('50a227cd-f521-4b73-b2e9-f7eba8ba53f9', 998, 'multiple_choice', 'A1', 'vocabulary', 'I need to _______ a reservation at the restaurant for Friday night.', 'make', '["make", "do", "have", "take"]', NULL, NULL, NULL, 'Common collocation: "___ a reservation".', 'Make a reservation is a fixed collocation. You make a reservation, a booking, an appointment, and a decision. You do not do these things.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{Collocation}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('d5cb0d70-8fda-4319-848c-1ec6d63b2f4b', 999, 'multiple_choice', 'A1', 'vocabulary', 'My teacher gave me some useful _______ on how to improve my writing.', 'advice', '["advice", "advices", "advise", "advising"]', NULL, NULL, NULL, 'Uncountable noun — never with -s.', 'Advice is an uncountable noun — it has no plural form. You cannot say advices. One piece of advice; some advice; a lot of advice.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Uncountable noun"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('c9205651-6e26-47f2-8a08-4e33e8eb5288', 1000, 'multiple_choice', 'A1', 'vocabulary', 'All of our _______ was lost at the airport — including our passports.', 'luggage', '["luggage", "luggages", "bags", "baggages"]', NULL, NULL, NULL, 'Uncountable noun — like furniture, no plural.', 'Luggage is uncountable — no plural form. The same applies to baggage. You say a piece of luggage, not a luggage or luggages.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Uncountable noun"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('d640a9c9-7209-4046-af1a-99d5b0320417', 638, 'sentence_building', 'A2', 'past_simple', '', 'I was born in Spain', '["I", "was", "born", "in", "Spain", "am", "the"]', NULL, NULL, NULL, NULL, '''Was born'' is a fixed expression for talking about your birth. ''I was born in'' + place.', '2026-02-13 08:00:10.850224+00', NULL, NULL, 'en', '{"Past tense"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('5c41ac84-3654-4f6e-a91b-91538bd5eb6b', 169, 'multiple_choice', 'B1', 'suggestions_lets', 'Let''s ___ to the cinema tonight.', 'go', '["going", "went", "go", "to go"]', NULL, NULL, NULL, 'Let''s + infinitive without "to".', 'Let''s + infinitive without ''to''.', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{"Making suggestions"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('59bf5a17-f5c7-4832-9f65-b1acd26604fd', 575, 'multiple_choice', 'C1', 'advanced_grammar', 'She insisted that he ___ present at the meeting.', 'be', '["is", "being", "was", "be"]', NULL, NULL, NULL, 'Subjunctive — base form of "to be" after "insist that".', 'Subjunctive after insist: base form of verb (no -s, no past tense).', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('ad54ac01-5a79-4e12-8f5d-5592aac36ac2', 1838, 'gap_fill', 'A2', 'spanish', 'Pagué casi trescientos euros _______ los billetes de avión de ida y vuelta.', 'por', NULL, NULL, NULL, NULL, NULL, '"Por" expresa precio o intercambio: pagué X euros por Y cosa.', '2026-04-06 16:43:51.906934+00', NULL, NULL, 'es', '{Spanish}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('83a66d89-3c24-401d-8a7b-46f459db7f73', 1308, 'sentence_auction', 'A2', 'grammar', 'Common grammar', 'auction', '[{"correct": true, "sentence": "The news was very surprising yesterday.", "explanation": "Correct. News is uncountable and takes a singular verb."}, {"correct": true, "sentence": "I met a lot of interesting people at the party.", "explanation": "Correct. People is already plural — no -s needed."}, {"correct": false, "sentence": "She is more taller than her brother.", "explanation": "Incorrect. Never use more with a comparative adjective ending in -er. It should be: she is taller."}, {"correct": true, "sentence": "He told me about his new job last week.", "explanation": "Correct. Told is the past simple of tell, used correctly here."}]', NULL, NULL, NULL, NULL, NULL, '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('f0e2eaac-f851-4b50-8b87-b7e68b233d70', 1309, 'sentence_auction', 'A1', 'routines', 'Home routines', 'auction', '[{"correct": true, "sentence": "My mother cooks dinner every evening.", "explanation": "Correct. Third person singular adds -s: cooks, not cook."}, {"correct": true, "sentence": "I always drink a glass of water when I wake up.", "explanation": "Correct. When I wake up is a correct time clause using the present simple."}, {"correct": false, "sentence": "He go to work by the bus every day.", "explanation": "Incorrect. Two errors: go should be goes (third person), and by the bus should be by bus — no article after by with transport."}, {"correct": false, "sentence": "We don''t never eat fast food during the week.", "explanation": "Incorrect. Double negatives are not used in standard English. Use either don''t or never, not both."}]', NULL, NULL, NULL, NULL, NULL, '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('6cdc8f5b-275b-43bf-9bc7-efd3e33f5cbf', 1310, 'sentence_auction', 'A2', 'grammar', 'Articles and nouns', 'auction', '[{"correct": true, "sentence": "I need some advice about my new job.", "explanation": "Correct. Advice is uncountable and cannot be made plural."}, {"correct": false, "sentence": "She gave me an useful tip about the exercise.", "explanation": "Incorrect. Use a, not an, before words starting with a consonant sound. Useful starts with a /j/ sound, so it takes a."}, {"correct": true, "sentence": "There is a lot of traffic on the road this morning.", "explanation": "Correct. Traffic is uncountable and uses a lot of correctly."}, {"correct": false, "sentence": "Can you give me an information about the schedule?", "explanation": "Incorrect. Information is uncountable. You cannot say an information — use some information or a piece of information."}]', NULL, NULL, NULL, NULL, NULL, '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('44e11fa1-3977-4814-9bd5-b92ef0842580', 1311, 'sentence_auction', 'B1', 'routines', 'Habits and routines', 'auction', '[{"correct": true, "sentence": "She has been following the same morning routine for years.", "explanation": "Correct. The present perfect continuous describes an ongoing habit that started in the past."}, {"correct": false, "sentence": "I am used to wake up early since I started this job.", "explanation": "Incorrect. Be used to is followed by a gerund (-ing), not the infinitive. It should be: used to waking up."}, {"correct": true, "sentence": "Getting enough sleep has made a huge difference to my energy levels.", "explanation": "Correct. A gerund (Getting) as subject is grammatically correct, and the collocation is make a difference to."}, {"correct": false, "sentence": "It''s worth to establish a consistent bedtime.", "explanation": "Incorrect. Worth is followed by a gerund, not the infinitive. It should be: worth establishing."}, {"correct": true, "sentence": "Most people find it hard to change their daily habits.", "explanation": "Correct. Find it + adjective + to-infinitive is a standard structure."}]', NULL, NULL, NULL, NULL, NULL, '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('06cab03b-d1d4-40b5-bb76-b1146653522d', 650, 'sentence_building', 'A2', 'going_to_future', 'Qué vas a hacer este fin de semana?', 'what are you going to do this weekend', '["what", "are", "you", "going", "to", "do", "this", "weekend", "did", "last", "is"]', NULL, NULL, NULL, NULL, 'Going to future question: What + are + subject + going to + verb?', '2026-02-17 09:58:54.170896+00', NULL, NULL, 'both', '{"Future form"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('1f391c23-e7a8-4e7a-b740-52b535a77826', 615, 'sentence_building', 'B1', 'future_plans', NULL, 'they are planning to launch a new product next month', '["they", "are", "planning", "to", "launch", "a", "new", "product", "next", "month", "old", "sell", "last"]', NULL, NULL, NULL, NULL, 'Present continuous for future arrangements. "Launch a product" is a standard business collocation.', '2026-02-12 14:34:46.611844+00', NULL, NULL, 'en', '{"Future form"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('374a0a4c-955f-4bce-a241-f09d34d98cbf', 617, 'sentence_building', 'C1', 'future_perfect', NULL, 'the contract will have been signed by the end of the week', '["the", "contract", "will", "have", "been", "signed", "by", "the", "end", "of", "the", "week", "until", "signing", "after"]', NULL, NULL, NULL, NULL, 'Future perfect passive: will have been + past participle. "By the end of" marks the deadline.', '2026-02-12 14:34:46.611844+00', NULL, NULL, 'en', '{"Future form"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('8b0d1e39-4a5e-427c-a44e-dea3c4548fd1', 1312, 'sentence_auction', 'B2', 'grammar', 'Verb patterns', 'auction', '[{"correct": true, "sentence": "He suggested going to a different restaurant.", "explanation": "Correct. Suggest is followed by a gerund (-ing)."}, {"correct": false, "sentence": "She denied to take the money.", "explanation": "Incorrect. Deny is followed by a gerund (-ing), not the infinitive. It should be: denied taking the money."}, {"correct": true, "sentence": "They managed to finish the project on time.", "explanation": "Correct. Manage is followed by the infinitive (to finish)."}, {"correct": true, "sentence": "I regret to inform you that your application was unsuccessful.", "explanation": "Correct. Regret + to-infinitive is used in formal contexts to introduce bad news."}, {"correct": false, "sentence": "He avoided to make eye contact during the interview.", "explanation": "Incorrect. Avoid is followed by a gerund (-ing). It should be: avoided making eye contact."}]', NULL, NULL, NULL, NULL, NULL, '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('6813f0e7-16cb-4f43-8313-e7019b48fcc9', 1313, 'sentence_auction', 'B1', 'routines', 'Sleep and wellbeing', 'auction', '[{"correct": true, "sentence": "I tend to feel more focused after a good night''s sleep.", "explanation": "Correct. Tend to + infinitive describes a general tendency or habit."}, {"correct": false, "sentence": "Despite to have a regular bedtime, she often feels tired.", "explanation": "Incorrect. Despite is a preposition followed by a noun or gerund (-ing). It should be: despite having."}, {"correct": true, "sentence": "I wish I could fall asleep more easily at night.", "explanation": "Correct. Wish + could is used to express a desire about the present."}, {"correct": true, "sentence": "It has been shown that sleep deprivation affects both mood and performance.", "explanation": "Correct. The present perfect passive (has been shown) is appropriate for established research findings."}]', NULL, NULL, NULL, NULL, NULL, '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('f04ee0c6-f599-4b36-883c-9e5b26650a39', 1314, 'sentence_auction', 'B2', 'grammar', 'Conditionals and wishes', 'auction', '[{"correct": true, "sentence": "If I had more free time, I would exercise more regularly.", "explanation": "Correct second conditional: past simple in the if clause, would + infinitive in the result clause."}, {"correct": false, "sentence": "If I would have known earlier, I would have prepared better.", "explanation": "Incorrect. In third conditional sentences, the if clause uses had + past participle, not would have. It should be: if I had known."}, {"correct": true, "sentence": "I wish I had taken better care of my health when I was younger.", "explanation": "Correct. Wish + past perfect is used to express regret about a past event."}, {"correct": false, "sentence": "Unless you will rest properly, your performance will suffer.", "explanation": "Incorrect. Unless introduces a conditional clause and uses the present simple, not will. It should be: unless you rest."}]', NULL, NULL, NULL, NULL, NULL, '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('c8914ebc-1b08-477d-91e6-3f8703549a95', 1315, 'sentence_auction', 'B1', 'routines', 'Present perfect and habits', 'auction', '[{"correct": true, "sentence": "I have gradually cut down on the amount of coffee I drink.", "explanation": "Correct. The present perfect shows a recent change, and cut down on is the correct collocation."}, {"correct": false, "sentence": "She has been doing yoga since two years.", "explanation": "Incorrect. Use for with a period of time: for two years. Since is used with a specific point in time."}, {"correct": true, "sentence": "Lately I have been trying to go to bed before midnight.", "explanation": "Correct. Lately refers to a recent ongoing period, so the present perfect continuous is required."}, {"correct": true, "sentence": "He has recently started to follow a healthier routine.", "explanation": "Correct. Recently with the present perfect is natural and standard."}, {"correct": true, "sentence": "She used to take the bus but now she cycles to work.", "explanation": "Correct. Used to describes a past habit that no longer happens."}]', NULL, NULL, NULL, NULL, NULL, '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('81944569-3813-4fb3-a1e1-14dbd4437d48', 1316, 'sentence_auction', 'C1', 'routines', 'Routine and discipline', 'auction', '[{"correct": true, "sentence": "Establishing a consistent sleep schedule has long-term benefits for mental health.", "explanation": "Correct. A gerund (Establishing) as subject is grammatically correct and natural."}, {"correct": true, "sentence": "She has made mindfulness a non-negotiable part of her daily routine.", "explanation": "Correct. Make + object + noun phrase (SVOC) correctly expresses transformation."}, {"correct": false, "sentence": "Such is the extent of his self-discipline that he rarely deviates of his schedule.", "explanation": "Incorrect. The correct collocation is deviate from, not deviate of. Compare: depart from, differ from."}, {"correct": true, "sentence": "The key to maintaining a healthy routine lies in making gradual adjustments.", "explanation": "Correct. The key to + gerund is the standard structure. Lies in is the correct collocation."}]', NULL, NULL, NULL, NULL, NULL, '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('e9d1a76a-ba53-411e-9739-edb7001cf2b4', 1317, 'sentence_auction', 'C2', 'grammar', 'Advanced grammar', 'auction', '[{"correct": true, "sentence": "Were it not for her meticulous planning, the project would have failed.", "explanation": "Correct. Were it not for is a formal inversion structure used in place of if it were not for."}, {"correct": true, "sentence": "Hardly had she sat down when the phone rang.", "explanation": "Correct. Hardly had + subject + past participle is a standard inversion structure with when."}, {"correct": false, "sentence": "Not only he failed the exam, but he also missed the deadline.", "explanation": "Incorrect. After negative adverbials like not only, subject-verb inversion is required: Not only did he fail the exam."}, {"correct": true, "sentence": "The extent to which habits shape identity is often underestimated.", "explanation": "Correct. The extent to which is a sophisticated structure introducing a degree or measure."}, {"correct": true, "sentence": "Seldom does she deviate from her morning routine, regardless of circumstance.", "explanation": "Correct. Seldom triggers inversion (does she), which is correct formal usage."}]', NULL, NULL, NULL, NULL, NULL, '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('9fd599cf-3074-409f-b4c2-dbe56f46bee3', 1318, 'sentence_auction', 'C1', 'routines', 'Wellbeing and habits', 'auction', '[{"correct": true, "sentence": "Research suggests that structured routines are linked to higher levels of wellbeing.", "explanation": "Correct. Research as a general concept takes a singular verb, and linked to describes correlation correctly."}, {"correct": true, "sentence": "Procrastination is often a symptom of deeper anxiety rather than laziness.", "explanation": "Correct. Rather than is used to contrast two ideas, suggesting the first is more accurate."}, {"correct": true, "sentence": "Without realising it, we often develop rituals that anchor us to a sense of normality.", "explanation": "Correct. Without realising it is a participial phrase. Note British spelling: realising."}, {"correct": false, "sentence": "Daily exercise has a proven affect on both mood and concentration.", "explanation": "Incorrect. Effect is the noun meaning result or impact. Affect is typically a verb. The collocation is have an effect on."}]', NULL, NULL, NULL, NULL, NULL, '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('d3daeddb-37b8-41e5-8c4c-8a2f6d40ad98', 2320, 'multiple_choice', 'A2', 'spanish', 'Me gusta ___ al fútbol con mis amigos.', 'jugar', '["jugar", "hacer", "ir", "correr"]', NULL, NULL, NULL, '"to play" a sport with a ball.', '"Jugar a" is used for playing a sport with a ball: "jugar al fútbol".', '2026-06-01 07:35:54.312658+00', NULL, NULL, 'es', '{Sport}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('7488dc08-60e5-46fd-a385-d4cef0a63a40', 1319, 'sentence_auction', 'C2', 'grammar', 'Precision and register', 'auction', '[{"correct": true, "sentence": "He is widely regarded as one of the most innovative thinkers of his generation.", "explanation": "Correct. Regarded as is the correct collocation in formal English."}, {"correct": false, "sentence": "The findings are consistent to previous research in this area.", "explanation": "Incorrect. The correct collocation is consistent with, not consistent to."}, {"correct": true, "sentence": "Her tenacity in the face of adversity is truly commendable.", "explanation": "Correct. In the face of is a fixed prepositional phrase meaning despite. Tenacity and commendable are used at the appropriate register."}, {"correct": true, "sentence": "The committee reached a consensus on the proposed changes.", "explanation": "Correct. Reach a consensus is the standard collocation. On introduces what the consensus is about."}, {"correct": false, "sentence": "She is renowned of her ability to remain calm under pressure.", "explanation": "Incorrect. Renowned for is the correct collocation. Compare: famous for, known for, celebrated for."}]', NULL, NULL, NULL, NULL, NULL, '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('be64af7c-6737-4b5a-9c47-4c9b0ea2deac', 1320, 'sentence_auction', 'C1', 'routines', 'Habits and psychology', 'auction', '[{"correct": true, "sentence": "Habits formed early in childhood are often remarkably resistant to change.", "explanation": "Correct. Formed is a past participle acting as a reduced relative clause. Resistant to is the correct collocation."}, {"correct": true, "sentence": "She has been making a conscious effort to wind down before bed.", "explanation": "Correct. The present perfect continuous describes an ongoing intentional effort. Wind down means to relax gradually."}, {"correct": true, "sentence": "Getting into a good routine is particularly important for those who tend to procrastinate.", "explanation": "Correct. Get into the habit/routine of is a natural expression. Tend to describes a habitual characteristic."}, {"correct": false, "sentence": "The more you practice a habit, the most automatic it becomes.", "explanation": "Incorrect. In the the more... the more structure, both parts use comparative forms. It should be: the more automatic it becomes."}]', NULL, NULL, NULL, NULL, NULL, '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('f48e8094-4930-4a21-b6d4-48e8cca20e8c', 1321, 'sentence_auction', 'A2', 'spanish', 'Rutinas diarias', 'auction', '[{"correct": true, "sentence": "Me levanto a las siete de la mañana todos los días.", "explanation": "Correcto. El presente de indicativo se usa para expresar hábitos y rutinas."}, {"correct": false, "sentence": "Estoy desayunando siempre antes de ir al trabajo.", "explanation": "Incorrecto. El presente continuo no se usa para hábitos regulares en español. Lo correcto es: siempre desayuno antes de ir al trabajo."}, {"correct": true, "sentence": "Normalmente me ducho por la mañana y me visto rápidamente.", "explanation": "Correcto. Por la mañana es la expresión correcta para indicar el momento del día."}, {"correct": true, "sentence": "Ella siempre llega tarde al trabajo porque no le gusta madrugar.", "explanation": "Correcto. El adverbio siempre va antes del verbo principal en español."}]', NULL, NULL, NULL, NULL, NULL, '2026-03-17 09:30:11.660865+00', NULL, NULL, 'es', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('45608e64-3f36-4bfa-94c3-9cc3faa9b9fe', 1322, 'sentence_auction', 'A2', 'spanish', 'Descripciones', 'auction', '[{"correct": true, "sentence": "Mi hermano es muy trabajador y siempre llega puntual a sus citas.", "explanation": "Correcto. Trabajador y puntual son adjetivos masculinos que concuerdan con mi hermano."}, {"correct": true, "sentence": "Esta mañana estoy muy cansada porque dormí mal.", "explanation": "Correcto. Estar se usa para estados temporales como el cansancio."}, {"correct": false, "sentence": "Soy muy nervioso hoy porque tengo una entrevista de trabajo.", "explanation": "Incorrecto. El nerviosismo de hoy es temporal, así que se usa estoy nervioso, no soy nervioso."}, {"correct": true, "sentence": "Me gustan mucho las películas de terror pero mis amigos no las soportan.", "explanation": "Correcto. El verbo gustar concuerda con las películas (plural), y no las soportan es correcto."}]', NULL, NULL, NULL, NULL, NULL, '2026-03-17 09:30:11.660865+00', NULL, NULL, 'es', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('a81eb46c-1412-4645-ac31-0b29d3d92d86', 1323, 'sentence_auction', 'A2', 'spanish', 'Tiempo libre y ocio', 'auction', '[{"correct": true, "sentence": "Los fines de semana me gusta salir a caminar por el parque.", "explanation": "Correcto. Me gusta + infinitivo es la estructura estándar para expresar gustos."}, {"correct": true, "sentence": "¿A qué hora quedamos mañana para tomar algo?", "explanation": "Correcto. Quedar con alguien es la expresión española para to meet up."}, {"correct": false, "sentence": "Ayer fuimos al cine y nos divertamos mucho.", "explanation": "Incorrecto. El pretérito indefinido de divertirse es nos divertimos, no nos divertamos."}, {"correct": true, "sentence": "Normalmente paso los domingos con mi familia en casa.", "explanation": "Correcto. Pasar el tiempo con alguien es la expresión correcta."}]', NULL, NULL, NULL, NULL, NULL, '2026-03-17 09:30:11.660865+00', NULL, NULL, 'es', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('88cdf5d4-3a7a-4410-a3d0-780e6c890015', 1324, 'sentence_auction', 'A2', 'spanish', 'El trabajo y los estudios', 'auction', '[{"correct": true, "sentence": "Llevo tres años trabajando en la misma empresa.", "explanation": "Correcto. Llevar + gerundio es la estructura española para expresar una acción que empezó en el pasado y continúa."}, {"correct": false, "sentence": "Estudio español desde dos años.", "explanation": "Incorrecto. Con llevar o hace + que, se usa la estructura correcta. También se puede decir: llevo dos años estudiando español."}, {"correct": true, "sentence": "Trabajo de lunes a viernes y los sábados descanso.", "explanation": "Correcto. De lunes a viernes es la expresión estándar para indicar días laborables."}, {"correct": true, "sentence": "Ayer tuve una reunión muy importante con mis clientes.", "explanation": "Correcto. Tuve es el pretérito indefinido de tener, usado correctamente para hablar del pasado."}]', NULL, NULL, NULL, NULL, NULL, '2026-03-17 09:30:11.660865+00', NULL, NULL, 'es', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('2e972298-600d-44f8-80ff-d9d6ea3b8185', 1004, 'multiple_choice', 'A2', 'vocabulary', 'My boss is very _______ — she always says thank you and treats everyone with respect.', 'polite', '["polite", "punctual", "ambitious", "creative"]', NULL, NULL, NULL, 'Showing good manners — saying please and thank you.', 'Polite describes someone who is respectful and considerate in manner and speech. Compare: punctual = always on time; ambitious = strongly motivated to succeed.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{Collocation}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('c7e715c7-c195-4d7d-a04d-1efd514716d6', 1005, 'multiple_choice', 'A2', 'vocabulary', 'The documentary was really _______ — I learned so much I didn''t know before.', 'informative', '["informative", "entertaining", "enjoyable", "exciting"]', NULL, NULL, NULL, 'Containing useful new information.', 'Informative means providing useful knowledge or facts. Compare: entertaining = enjoyable to watch or read; educational = teaching something, but with a stronger sense of formal learning.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{Collocation}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('90316c47-e964-489a-b785-a38370b284a4', 1006, 'multiple_choice', 'A2', 'vocabulary', 'He was very _______ — he arrived ten minutes early for every single meeting.', 'punctual', '["punctual", "polite", "organised", "professional"]', NULL, NULL, NULL, 'Always arriving on time — never late.', 'Punctual means consistently on time. It is a valued professional quality, especially in cultures where time-keeping is taken seriously.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{Collocation}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('23d6b23f-8243-4824-94a5-aca23d20ccb5', 1230, 'multiple_choice', 'A2', 'business_phrasal_verbs', 'We need to _____ costs if we want to stay profitable this quarter.', 'cut down on', '["cut down on", "cut out", "cut off", "cut up"]', NULL, NULL, NULL, 'To reduce (costs, consumption).', 'Cut down on means to reduce the amount or level of something. Compare: cut back on spending.', '2026-03-18 19:58:52.376507+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('9a91008a-7fbd-40ae-9c85-dd8c7c40f841', 1007, 'multiple_choice', 'B1', 'vocabulary', 'She''s very _______ — if she says she''ll do something, she always does it.', 'reliable', '["reliable", "flexible", "ambitious", "determined"]', NULL, NULL, NULL, 'Can be depended on — always does what they say.', 'Reliable describes someone who can be trusted to do what they say. Compare: flexible = willing to adapt; determined = strongly committed to achieving something.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{Collocation}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('37cf0df0-67d6-4491-b433-f3a930e35171', 1008, 'multiple_choice', 'B1', 'vocabulary', 'The audit was extremely _______ — the team checked every single transaction.', 'thorough', '["thorough", "brief", "efficient", "routine"]', NULL, NULL, NULL, 'Complete and detailed — leaves nothing out.', 'Thorough means extremely careful and complete. A thorough audit leaves nothing unchecked. Compare: efficient = achieving results without wasting time or resources.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Business vocabulary",Collocation}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('939a2c72-4e3b-42a2-82a0-1826846935e3', 1325, 'sentence_auction', 'A2', 'spanish', 'Hábitos y salud', 'auction', '[{"correct": true, "sentence": "Intento comer sano y hacer ejercicio al menos tres veces a la semana.", "explanation": "Correcto. Intentar + infinitivo y al menos son expresiones estándar."}, {"correct": false, "sentence": "Me acuesto muy tarde los noches del fin de semana.", "explanation": "Incorrecto. Noches es femenino plural, así que el artículo debe ser las noches, no los noches."}, {"correct": true, "sentence": "Bebo mucha agua durante el día porque sé que es importante para la salud.", "explanation": "Correcto. Durante el día es la expresión correcta para throughout the day."}, {"correct": true, "sentence": "Antes de acostarme siempre leo un poco para relajarme.", "explanation": "Correcto. Antes de + infinitivo es la estructura correcta. Los verbos reflexivos están bien conjugados."}]', NULL, NULL, NULL, NULL, NULL, '2026-03-17 09:30:11.660865+00', NULL, NULL, 'es', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('c8d8dde5-d57b-4694-8cac-fae29cd2ac96', 1326, 'matching', 'A1', 'routines', 'Match each action to the time of day when it usually happens.', '["match_all_pairs"]', '[{"left": {"type": "text", "label": "", "content": "wake up"}, "right": {"type": "text", "label": "", "content": "in the morning"}}, {"left": {"type": "text", "label": "", "content": "have lunch"}, "right": {"type": "text", "label": "", "content": "at midday"}}, {"left": {"type": "text", "label": "", "content": "watch TV"}, "right": {"type": "text", "label": "", "content": "in the evening"}}, {"left": {"type": "text", "label": "", "content": "go to bed"}, "right": {"type": "text", "label": "", "content": "at night"}}]', NULL, NULL, NULL, NULL, NULL, '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('aecde125-d14d-45cc-88b7-8523e45e6788', 1327, 'matching', 'A2', 'vocabulary', 'Match each verb to its opposite.', '["match_all_pairs"]', '[{"left": {"type": "text", "label": "", "content": "wake up"}, "right": {"type": "text", "label": "", "content": "fall asleep"}}, {"left": {"type": "text", "label": "", "content": "arrive"}, "right": {"type": "text", "label": "", "content": "leave"}}, {"left": {"type": "text", "label": "", "content": "start"}, "right": {"type": "text", "label": "", "content": "finish"}}, {"left": {"type": "text", "label": "", "content": "remember"}, "right": {"type": "text", "label": "", "content": "forget"}}]', NULL, NULL, NULL, NULL, NULL, '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('1d229d26-e388-4369-bb8c-c4272939d2d6', 1328, 'matching', 'A1', 'vocabulary', 'Match each adjective to its meaning.', '["match_all_pairs"]', '[{"left": {"type": "text", "label": "", "content": "tired"}, "right": {"type": "text", "label": "", "content": "needing rest or sleep"}}, {"left": {"type": "text", "label": "", "content": "hungry"}, "right": {"type": "text", "label": "", "content": "wanting food"}}, {"left": {"type": "text", "label": "", "content": "bored"}, "right": {"type": "text", "label": "", "content": "not interested or entertained"}}, {"left": {"type": "text", "label": "", "content": "busy"}, "right": {"type": "text", "label": "", "content": "having a lot to do"}}]', NULL, NULL, NULL, NULL, NULL, '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('c858d933-05f3-4410-9ea9-efaa23c8a2fc', 1329, 'matching', 'A2', 'routines', 'Match each expression to its meaning.', '["match_all_pairs"]', '[{"left": {"type": "text", "label": "", "content": "on weekdays"}, "right": {"type": "text", "label": "", "content": "Monday to Friday"}}, {"left": {"type": "text", "label": "", "content": "at the weekend"}, "right": {"type": "text", "label": "", "content": "Saturday and Sunday"}}, {"left": {"type": "text", "label": "", "content": "once a week"}, "right": {"type": "text", "label": "", "content": "one time every seven days"}}, {"left": {"type": "text", "label": "", "content": "every other day"}, "right": {"type": "text", "label": "", "content": "on alternate days"}}]', NULL, NULL, NULL, NULL, NULL, '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('ebc361fa-446b-4376-b26e-ca61ae10757a', 1330, 'matching', 'A2', 'vocabulary', 'Match each verb with the noun it most commonly goes with.', '["match_all_pairs"]', '[{"left": {"type": "text", "label": "", "content": "make"}, "right": {"type": "text", "label": "", "content": "a mistake"}}, {"left": {"type": "text", "label": "", "content": "do"}, "right": {"type": "text", "label": "", "content": "the housework"}}, {"left": {"type": "text", "label": "", "content": "have"}, "right": {"type": "text", "label": "", "content": "a shower"}}, {"left": {"type": "text", "label": "", "content": "take"}, "right": {"type": "text", "label": "", "content": "a photo"}}]', NULL, NULL, NULL, NULL, NULL, '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('983227c4-0e68-4f88-9014-cc8a264f16de', 1210, 'sentence_building', 'C1', 'routines', 'La procrastinación suele ser un síntoma de una ansiedad más profunda que de pereza.', 'Procrastination is often a symptom of deeper anxiety rather than laziness.', '["procrastination", "is", "often", "a", "symptom", "of", "deeper", "anxiety", "rather", "than", "laziness", "usually", "instead", "sign", "profound"]', NULL, NULL, NULL, NULL, 'Rather than contrasts two ideas, suggesting the first is more accurate or likely. A symptom of implies a deeper underlying cause.', '2026-03-16 09:04:17.945706+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('57456f01-2dd2-4377-82af-c1c0a14a265c', 1009, 'multiple_choice', 'B2', 'vocabulary', 'The new office has a very _______ atmosphere — everyone is on first-name terms and wears casual clothes.', 'informal', '["informal", "formal", "tense", "competitive"]', NULL, NULL, NULL, 'Casual, relaxed — opposite of "formal".', 'Informal describes a relaxed environment without strict rules or formality. Common signs: first names, casual clothes, open-plan offices. The opposite is formal.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Business vocabulary",Collocation}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('3f19e204-2b25-4beb-839c-3930ba22571c', 1218, 'sentence_building', 'A2', 'spanish', 'He never eats breakfast at home.', 'él nunca desayuna en casa.', '["él", "nunca", "desayuna", "en", "casa", "come", "siempre", "trabajo", "fuera"]', NULL, NULL, NULL, NULL, 'Nunca means never. En casa means at home — no article is needed in this fixed expression.', '2026-03-16 09:04:17.945706+00', NULL, NULL, 'es', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('5d5b2c1a-c554-439f-b26f-02ec788cdb6a', 55, 'gap_fill', 'B1', 'adverbs_frequency', 'I ___ (_ _ _ _ _ _) drink coffee in the morning.', 'always', NULL, NULL, NULL, NULL, 'Adverbs of frequency come before the main verb', 'Adverbs of frequency are placed before the main verb.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{Adverb}', false, 'A frequency adverb meaning 100% of the time.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('84fd2792-de82-4c97-a666-dd0df921bbef', 56, 'gap_fill', 'B1', 'adverbs_frequency', 'She is ___ (_ _ _ _ _) late for class.', 'never', NULL, NULL, NULL, NULL, 'Adverbs of frequency come after ''be''', 'With the verb ''be'', adverbs of frequency come after it.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{Adverb}', false, 'A frequency adverb meaning 0% of the time.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('68afbc41-8927-4f9a-beee-b749b84082b8', 1010, 'multiple_choice', 'B2', 'vocabulary', 'There was a _______ between the figures in the report and the actual bank statements.', 'discrepancy', '["discrepancy", "mistake", "problem", "difference"]', NULL, NULL, NULL, 'A surprising mismatch between two things that should match.', 'A discrepancy is a difference between two figures or accounts that should match. In finance, a discrepancy between records and actual balances is a serious concern.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Business vocabulary"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('91ee463e-bdf2-4f29-a406-633219239a67', 1011, 'multiple_choice', 'B2', 'vocabulary', 'Her speech was _______ — every single person in the room was completely engaged.', 'compelling', '["compelling", "informative", "prepared", "professional"]', NULL, NULL, NULL, 'So engaging it captures everyone''s attention.', 'Compelling means so interesting or persuasive that it holds your complete attention. A compelling argument is one that is very difficult to disagree with.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Business vocabulary",Collocation}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('1c023959-a056-462d-bee4-7493aa4dfbfd', 1012, 'gap_fill', 'B1', 'vocabulary', 'The project was finished three weeks _______ of schedule — the team was delighted.', 'ahead', NULL, NULL, NULL, NULL, 'Phrase: "___ of schedule" = before the deadline.', 'Ahead of schedule means finishing or progressing earlier than planned. The opposite is behind schedule. Both are essential phrases in project management.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Business vocabulary","Fixed expression"}', false, 'Opposite of "behind schedule".', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('f04c8c79-1659-412c-be67-31e7f54e34ce', 1013, 'gap_fill', 'B1', 'vocabulary', 'I have a real _______ for languages — I find it easy to pick up new words and grammar.', 'flair', NULL, NULL, NULL, '["gift", "talent", "knack"]', 'A natural talent or aptitude.', 'A flair for something means a natural talent or instinct for it. Similar: a gift for, a talent for, a knack for — though flair carries a slightly more stylish connotation.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{Collocation,"Dependent preposition"}', false, 'Often used with "for" — a ___ for X.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('eb42490b-e970-40f7-8233-c15d2aa38b06', 1332, 'matching', 'A2', 'grammar', 'Match each frequency adverb to its approximate meaning.', '["match_all_pairs"]', '[{"left": {"type": "text", "label": "", "content": "always"}, "right": {"type": "text", "label": "", "content": "100% of the time"}}, {"left": {"type": "text", "label": "", "content": "usually"}, "right": {"type": "text", "label": "", "content": "most of the time"}}, {"left": {"type": "text", "label": "", "content": "sometimes"}, "right": {"type": "text", "label": "", "content": "on some occasions"}}, {"left": {"type": "text", "label": "", "content": "rarely"}, "right": {"type": "text", "label": "", "content": "not very often"}}]', NULL, NULL, NULL, NULL, NULL, '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('ba0937a9-dd5b-435c-ac2f-0fadea7e644c', 1333, 'matching', 'A2', 'vocabulary', 'Match each feeling to its cause.', '["match_all_pairs"]', '[{"left": {"type": "text", "label": "", "content": "exhausted"}, "right": {"type": "text", "label": "", "content": "you haven''t slept enough"}}, {"left": {"type": "text", "label": "", "content": "stressed"}, "right": {"type": "text", "label": "", "content": "you have too much to do"}}, {"left": {"type": "text", "label": "", "content": "relieved"}, "right": {"type": "text", "label": "", "content": "something worrying has ended well"}}, {"left": {"type": "text", "label": "", "content": "motivated"}, "right": {"type": "text", "label": "", "content": "you feel ready and eager to do something"}}]', NULL, NULL, NULL, NULL, NULL, '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('58c4fa06-940d-45c5-b628-d5d919ad51d2', 1334, 'matching', 'A1', 'routines', 'Match each room to what you typically do there.', '["match_all_pairs"]', '[{"left": {"type": "text", "label": "", "content": "kitchen"}, "right": {"type": "text", "label": "", "content": "cook and eat"}}, {"left": {"type": "text", "label": "", "content": "bedroom"}, "right": {"type": "text", "label": "", "content": "sleep and rest"}}, {"left": {"type": "text", "label": "", "content": "bathroom"}, "right": {"type": "text", "label": "", "content": "wash and brush teeth"}}, {"left": {"type": "text", "label": "", "content": "living room"}, "right": {"type": "text", "label": "", "content": "relax and watch TV"}}]', NULL, NULL, NULL, NULL, NULL, '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('e296e1ec-86b5-4a67-8480-f5b735a4c356', 1331, 'matching', 'A1', 'vocabulary', 'Match each preposition of time to a typical example.', '["match_all_pairs"]', '[{"left": {"type": "text", "label": "", "content": "at"}, "right": {"type": "text", "label": "", "content": "7 o''clock"}}, {"left": {"type": "text", "label": "", "content": "on"}, "right": {"type": "text", "label": "", "content": "Monday morning"}}, {"left": {"type": "text", "label": "", "content": "in"}, "right": {"type": "text", "label": "", "content": "the afternoon"}}, {"left": {"type": "text", "label": "", "content": "for"}, "right": {"type": "text", "label": "", "content": "two hours"}}]', NULL, NULL, NULL, NULL, NULL, '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('60711216-f997-4c99-8cac-c32aae1bdba6', 1937, 'odd_one_out', 'A2', 'idioms', 'Which of these is NOT an idiom?', 'make a phone call', '["break a leg", "bite the bullet", "hit the road", "make a phone call"]', NULL, NULL, NULL, NULL, '"Make a phone call" means exactly what it says. "Break a leg" = good luck, "bite the bullet" = endure something difficult, "hit the road" = start a journey.', '2026-04-08 18:26:42.653742+00', NULL, NULL, 'en', '{Idioms}', true, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('d2272c6d-d013-49e1-97c5-2bdd69837db7', 1938, 'odd_one_out', 'A2', 'idioms', 'Which of these is NOT an idiom?', 'take a taxi', '["it''s raining cats and dogs", "once in a blue moon", "a piece of cake", "take a taxi"]', NULL, NULL, NULL, NULL, '"Take a taxi" means exactly what it says. "Raining cats and dogs" = raining heavily, "once in a blue moon" = very rarely, "a piece of cake" = something very easy.', '2026-04-08 18:26:42.653742+00', NULL, NULL, 'en', '{Idioms}', true, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('955ba1f1-dd44-4d3b-8962-e5d5505f48b7', 1939, 'odd_one_out', 'A2', 'vocabulary', 'Three of these are mammals. Which is the odd one out?', 'shark', '["dolphin", "whale", "bat", "shark"]', NULL, NULL, NULL, NULL, 'Dolphins, whales, and bats are all mammals — they breathe air, are warm-blooded, and feed their young with milk. A shark is a fish. The dolphin and whale answers surprise many people!', '2026-04-08 18:26:42.653742+00', NULL, NULL, 'en', '{Nature,Vocabulary}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('69e668f6-ad58-4678-bc58-f88a5c18c313', 1940, 'odd_one_out', 'A2', 'vocabulary', 'Which of these cities is NOT the capital of its country?', 'Sydney', '["London", "Sydney", "Berlin", "Madrid"]', NULL, NULL, NULL, NULL, 'Sydney is Australia''s largest city, but the capital is Canberra — purpose-built as a compromise between Sydney and Melbourne. London, Berlin, and Madrid are all national capitals.', '2026-04-08 18:26:42.653742+00', NULL, NULL, 'en', '{"General Knowledge"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('e8ab3e8a-582b-4beb-af9b-21ea41529725', 1941, 'odd_one_out', 'A2', 'vocabulary', 'Three of these are typical Monday morning activities. Which is the odd one out?', 'feel motivated', '["make coffee", "check emails", "feel motivated", "check the time repeatedly"]', NULL, NULL, NULL, NULL, 'Making coffee, checking emails, and watching the clock are all perfectly normal Monday morning activities. Feeling motivated is the odd one out — statistically speaking, at least.', '2026-04-08 18:26:42.653742+00', NULL, NULL, 'en', '{Humour}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('331abdd0-7510-4ca8-83ef-d6c419be97ac', 279, 'gap_fill', 'A1', 'there_is_there_are', '___ a supermarket near my house.', 'There is', NULL, NULL, NULL, NULL, 'One supermarket — singular.', 'There is + singular noun.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"There is/are"}', false, '___ + a + singular noun.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('ac76f4ff-f5d4-45a2-8150-6d8f9fe08e45', 2321, 'multiple_choice', 'A2', 'spanish', 'Voy ___ gimnasio tres veces por semana.', 'al', '["al", "a la", "en", "de"]', NULL, NULL, NULL, '"to the gym" — remember a + el = al.', '"A + el" contracts to "al": "voy al gimnasio".', '2026-06-01 07:35:54.312658+00', NULL, NULL, 'es', '{Sport}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('39e2b1dd-ef3a-40ea-9189-aeb63576c41d', 1942, 'odd_one_out', 'A2', 'vocabulary', 'Three of these are things you can eat. Which is the odd one out?', 'a ruler', '["a date", "a mussel", "a prawn", "a ruler"]', NULL, NULL, NULL, NULL, 'A date is a sweet fruit, a mussel is a shellfish, a prawn is a seafood — all edible. A ruler is a measuring tool. Though it might feel like you''ve eaten one after a long maths lesson.', '2026-04-08 18:26:42.653742+00', NULL, NULL, 'en', '{Humour,Vocabulary}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('99e8b296-44eb-4feb-8a5a-e05afd68ff55', 1335, 'matching', 'A2', 'vocabulary', 'Match each word to its definition.', '["match_all_pairs"]', '[{"left": {"type": "text", "label": "", "content": "habit"}, "right": {"type": "text", "label": "", "content": "something you do regularly without thinking"}}, {"left": {"type": "text", "label": "", "content": "routine"}, "right": {"type": "text", "label": "", "content": "a fixed way of doing things at the same time each day"}}, {"left": {"type": "text", "label": "", "content": "schedule"}, "right": {"type": "text", "label": "", "content": "a plan showing what you will do and when"}}, {"left": {"type": "text", "label": "", "content": "deadline"}, "right": {"type": "text", "label": "", "content": "the latest time by which something must be done"}}]', NULL, NULL, NULL, NULL, NULL, '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('0b3ceb8a-0630-4f0a-8322-bc7c4f40687c', 1943, 'odd_one_out', 'A2', 'grammar', 'Three of these are irregular past tenses. Which is the odd one out?', 'watched', '["went", "ate", "swam", "watched"]', NULL, NULL, NULL, NULL, '"Watched" is regular — it simply adds -ed. "Went" (go), "ate" (eat), and "swam" (swim) are all irregular past tenses.', '2026-04-08 18:26:42.653742+00', NULL, NULL, 'en', '{Grammar,Tenses}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('800e0609-84f0-4b58-a4d3-765de90ce60f', 1337, 'matching', 'B2', 'grammar', 'Match each linking word to its function.', '["match_all_pairs"]', '[{"left": {"type": "text", "label": "", "content": "however"}, "right": {"type": "text", "label": "", "content": "introduces a contrast"}}, {"left": {"type": "text", "label": "", "content": "therefore"}, "right": {"type": "text", "label": "", "content": "introduces a result or conclusion"}}, {"left": {"type": "text", "label": "", "content": "furthermore"}, "right": {"type": "text", "label": "", "content": "adds a stronger or more important point"}}, {"left": {"type": "text", "label": "", "content": "nevertheless"}, "right": {"type": "text", "label": "", "content": "shows something is true despite what was just said"}}]', NULL, NULL, NULL, NULL, NULL, '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('b204dd0e-5d2e-48a6-a6ae-720119124aec', 2322, 'multiple_choice', 'A2', 'spanish', 'Ella ___ natación todos los días.', 'hace', '["hace", "juega", "va", "pone"]', NULL, NULL, NULL, 'Spanish uses "hacer" with natación.', 'Spanish uses "hacer" with "natación": "hace natación" = "does swimming".', '2026-06-01 07:35:54.312658+00', NULL, NULL, 'es', '{Sport}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('761d8bbe-2ee3-4666-8581-651c7c059533', 1338, 'matching', 'B1', 'routines', 'Match each expression to its meaning.', '["match_all_pairs"]', '[{"left": {"type": "text", "label": "", "content": "get into the habit of"}, "right": {"type": "text", "label": "", "content": "start doing something regularly"}}, {"left": {"type": "text", "label": "", "content": "fall into a routine"}, "right": {"type": "text", "label": "", "content": "naturally start following a regular pattern"}}, {"left": {"type": "text", "label": "", "content": "stick to a schedule"}, "right": {"type": "text", "label": "", "content": "follow a plan without deviating from it"}}, {"left": {"type": "text", "label": "", "content": "break a habit"}, "right": {"type": "text", "label": "", "content": "stop doing something you do regularly"}}]', NULL, NULL, NULL, NULL, NULL, '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('45b3f78b-ec27-41f4-becc-9aa3629d5294', 1945, 'odd_one_out', 'A2', 'vocabulary', 'Three of these are types of accommodation. Which is the odd one out?', 'invoice', '["hotel", "hostel", "chalet", "invoice"]', NULL, NULL, NULL, NULL, 'A hotel, hostel, and chalet are all places to stay. An invoice is a document requesting payment.', '2026-04-08 18:26:42.653742+00', NULL, NULL, 'en', '{Vocabulary,Travel}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('71881be8-5712-45e5-a201-e50f5ec7b0c1', 1946, 'odd_one_out', 'A2', 'vocabulary', 'Three of these words describe appearance. Which is the odd one out?', 'nervous', '["slim", "tall", "curly", "nervous"]', NULL, NULL, NULL, NULL, '"Nervous" describes how someone feels, not how they look. "Slim", "tall", and "curly" all describe physical appearance.', '2026-04-08 18:26:42.653742+00', NULL, NULL, 'en', '{Vocabulary}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('4787aff6-d8d3-48ca-a15b-c209811fa5f6', 1341, 'matching', 'B2', 'routines', 'Match each gerund phrase to what it describes.', '["match_all_pairs"]', '[{"left": {"type": "text", "label": "", "content": "pulling an all-nighter"}, "right": {"type": "text", "label": "", "content": "staying awake all night to work or study"}}, {"left": {"type": "text", "label": "", "content": "hitting snooze"}, "right": {"type": "text", "label": "", "content": "delaying waking up by dismissing an alarm"}}, {"left": {"type": "text", "label": "", "content": "meal prepping"}, "right": {"type": "text", "label": "", "content": "preparing food in advance for the week"}}, {"left": {"type": "text", "label": "", "content": "power napping"}, "right": {"type": "text", "label": "", "content": "sleeping briefly during the day to restore energy"}}]', NULL, NULL, NULL, NULL, NULL, '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('b40c1812-f588-4965-b730-8ac87bb2670e', 1211, 'sentence_building', 'C2', 'routines', 'Las investigaciones sugieren que las rutinas estructuradas están relacionadas con mayores niveles de bienestar.', 'Research suggests that structured routines are linked to higher levels of wellbeing.', '["research", "suggests", "that", "structured", "routines", "are", "linked", "to", "higher", "levels", "of", "wellbeing", "shows", "regular", "connected", "happiness"]', NULL, NULL, NULL, NULL, 'Linked to describes a correlation without implying direct causation. Research as a general concept takes a singular verb.', '2026-03-16 09:04:17.945706+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('f7f600ab-5e75-4f17-9499-8a6fddb74a3b', 1212, 'sentence_building', 'C1', 'routines', 'Reservar tiempo en tu agenda para el descanso y el ocio rara vez es una pérdida.', 'Blocking out time in your diary for rest and leisure is rarely a waste.', '["blocking", "out", "time", "in", "your", "diary", "for", "rest", "and", "leisure", "is", "rarely", "a", "waste", "schedule", "never", "valuable"]', NULL, NULL, NULL, NULL, 'Block out time means to deliberately reserve a period in your schedule. The gerund Blocking acts as the subject of the sentence.', '2026-03-16 09:04:17.945706+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('e4fda588-cd9d-466c-859c-db0448f0acba', 1947, 'odd_one_out', 'B1', 'idioms', 'Which of these is NOT an idiom?', 'make an appointment', '["spill the beans", "cut corners", "read the room", "make an appointment"]', NULL, NULL, NULL, NULL, '"Make an appointment" is literal. "Spill the beans" = reveal a secret, "cut corners" = do something badly to save effort, "read the room" = sense the mood of a group.', '2026-04-08 18:26:42.653742+00', NULL, NULL, 'en', '{Idioms}', true, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('1f073235-4850-480d-8d24-d5bf9f4119d9', 1948, 'odd_one_out', 'B2', 'idioms', 'Which of these is NOT an idiom?', 'take the minutes', '["pull someone''s leg", "burn your bridges", "hit the nail on the head", "take the minutes"]', NULL, NULL, NULL, NULL, '"Take the minutes" literally means to record what is said in a meeting. The others are all idioms: "pull someone''s leg" = joke, "burn your bridges" = permanently damage a relationship, "hit the nail on the head" = say exactly the right thing.', '2026-04-08 18:26:42.653742+00', NULL, NULL, 'en', '{Idioms}', true, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('66174640-2c8b-421e-8769-f189348f8295', 1629, 'gap_fill', 'C1', 'travel', 'Tourism has _______ a double-edged sword for many developing economies, bringing income but also social disruption.', 'proved to be', NULL, NULL, NULL, '[{"answer": "been", "feedback": "✅ ''Has been'' works fine. The model answer ''proved to be'' adds a sense of having been demonstrated through experience."}]', 'Showed itself to be — turned out to be.', '"Proved to be" introduces the result of something after experience or evidence. "Tourism has proved to be a double-edged sword" = experience has shown it to be both beneficial and harmful.', '2026-03-27 08:23:03.995534+00', NULL, NULL, 'en', '{}', false, 'Form: ___ + adjective phrase.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('6cfc68c4-fb42-4ccc-b0bd-7e195fc60565', 1949, 'odd_one_out', 'B1', 'vocabulary', 'Which of these countries is NOT in the European Union?', 'Norway', '["Germany", "Norway", "France", "Spain"]', NULL, NULL, NULL, NULL, 'Norway is not an EU member. It belongs to the EEA but has never joined. Germany, France, and Spain are all EU members.', '2026-04-08 18:26:42.653742+00', NULL, NULL, 'en', '{"General Knowledge"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('34cadb7e-6273-4fe1-a0c2-6796e9a1d4ce', 1950, 'odd_one_out', 'B2', 'vocabulary', 'Which of these statements is TRUE?', 'Lightning can strike the same place twice', '["The Great Wall of China is visible from space", "We only use 10% of our brain", "Goldfish have a 3-second memory", "Lightning can strike the same place twice"]', NULL, NULL, NULL, NULL, 'Lightning regularly strikes the same place twice. The others are popular myths: the Great Wall is not visible from space, we use virtually all of our brain, and goldfish actually have a memory of several months.', '2026-04-08 18:26:42.653742+00', NULL, NULL, 'en', '{"General Knowledge"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('b208dabe-7013-43b6-b8cb-c801443d36dc', 1344, 'matching', 'B1', 'routines', 'Match each health habit to its benefit.', '["match_all_pairs"]', '[{"left": {"type": "text", "label": "", "content": "drinking enough water"}, "right": {"type": "text", "label": "", "content": "improves concentration and energy"}}, {"left": {"type": "text", "label": "", "content": "getting regular exercise"}, "right": {"type": "text", "label": "", "content": "reduces stress and improves mood"}}, {"left": {"type": "text", "label": "", "content": "keeping a consistent bedtime"}, "right": {"type": "text", "label": "", "content": "improves sleep quality over time"}}, {"left": {"type": "text", "label": "", "content": "eating breakfast"}, "right": {"type": "text", "label": "", "content": "provides energy for the morning"}}]', NULL, NULL, NULL, NULL, NULL, '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('9d77bdff-2d28-4a2d-8899-934593f602fc', 1951, 'odd_one_out', 'B1', 'vocabulary', 'Three of these are genuine English words. Which one did we make up?', 'snorfalicious', '["flabbergasted", "discombobulate", "bumfuzzle", "snorfalicious"]', NULL, NULL, NULL, NULL, '"Snorfalicious" is fictional. "Flabbergasted" = astonished, "discombobulate" = confuse or unsettle, "bumfuzzle" (US dialect) = confuse or fluster. English really contains all three.', '2026-04-08 18:26:42.653742+00', NULL, NULL, 'en', '{Humour,Vocabulary}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('625b6c7e-78b7-490c-80ea-feba2f5f912b', 1346, 'matching', 'C1', 'vocabulary', 'Match each formal word to its informal equivalent.', '["match_all_pairs"]', '[{"left": {"type": "text", "label": "", "content": "endeavour"}, "right": {"type": "text", "label": "", "content": "try"}}, {"left": {"type": "text", "label": "", "content": "commence"}, "right": {"type": "text", "label": "", "content": "start"}}, {"left": {"type": "text", "label": "", "content": "terminate"}, "right": {"type": "text", "label": "", "content": "end"}}, {"left": {"type": "text", "label": "", "content": "ascertain"}, "right": {"type": "text", "label": "", "content": "find out"}}]', NULL, NULL, NULL, NULL, NULL, '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
