INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('b84ada49-90c4-498d-9a39-656ef2584735', 1348, 'matching', 'C1', 'routines', 'Match each concept to its meaning in the context of habit formation.', '["match_all_pairs"]', '[{"left": {"type": "text", "label": "", "content": "cue"}, "right": {"type": "text", "label": "", "content": "a trigger that initiates a habitual behaviour"}}, {"left": {"type": "text", "label": "", "content": "reward"}, "right": {"type": "text", "label": "", "content": "the positive outcome that reinforces a habit"}}, {"left": {"type": "text", "label": "", "content": "keystone habit"}, "right": {"type": "text", "label": "", "content": "a habit that triggers the development of other good habits"}}, {"left": {"type": "text", "label": "", "content": "relapse"}, "right": {"type": "text", "label": "", "content": "returning to old habits after a period of change"}}]', NULL, NULL, NULL, NULL, NULL, '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('caa93f73-4d24-4dcc-b5d6-e2c7fae325f0', 1349, 'matching', 'C2', 'grammar', 'Match each clause structure to an example.', '["match_all_pairs"]', '[{"left": {"type": "text", "label": "", "content": "concessive clause"}, "right": {"type": "text", "label": "", "content": "Although she was tired, she finished the report."}}, {"left": {"type": "text", "label": "", "content": "result clause"}, "right": {"type": "text", "label": "", "content": "She worked so hard that she finished early."}}, {"left": {"type": "text", "label": "", "content": "purpose clause"}, "right": {"type": "text", "label": "", "content": "She set an alarm so that she wouldn''t be late."}}, {"left": {"type": "text", "label": "", "content": "conditional clause"}, "right": {"type": "text", "label": "", "content": "Had she planned better, she would have succeeded."}}]', NULL, NULL, NULL, NULL, NULL, '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('3bbb9df9-ee60-435e-9a5f-143447257986', 1952, 'odd_one_out', 'B2', 'vocabulary', 'Three of these are real collective nouns for groups of animals. Which one did we invent?', 'a delegation of penguins', '["a murder of crows", "a parliament of owls", "a conspiracy of lemurs", "a delegation of penguins"]', NULL, NULL, NULL, NULL, 'A murder of crows, a parliament of owls, and a conspiracy of lemurs are all genuine. A group of penguins is a colony or waddle. "A delegation" was our invention — though they do walk like diplomats.', '2026-04-08 18:26:42.653742+00', NULL, NULL, 'en', '{Humour,Vocabulary}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('37024bfb-22c0-401f-ad35-e9fd1bf1c16e', 2323, 'multiple_choice', 'A2', 'spanish', 'Nuestro equipo ___ el partido ayer.', 'ganó', '["ganó", "perdió", "jugó", "corrió"]', NULL, NULL, NULL, '"won" the match.', '"Ganó" is the preterite of "ganar" (to win): "won the match".', '2026-06-01 07:35:54.312658+00', NULL, NULL, 'es', '{Sport}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('d6725d5a-fac4-4d42-8ea7-0b894a9c1231', 1954, 'odd_one_out', 'B2', 'vocabulary', 'Three of these are synonyms for "begin". Which is the odd one out?', 'abandon', '["commence", "initiate", "launch", "abandon"]', NULL, NULL, NULL, NULL, '"Abandon" means to give up on something — the opposite of beginning. "Commence", "initiate", and "launch" all mean to start.', '2026-04-08 18:26:42.653742+00', NULL, NULL, 'en', '{Vocabulary}', false, NULL, NULL);
