INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('12202ff5-bdb1-42a0-bdea-3f3acebf8e3f', 1363, 'matching', 'A2', 'spanish', 'Match each Spanish verb to its English meaning.', '["match_all_pairs"]', '[{"left": {"type": "text", "label": "", "content": "desayunar"}, "right": {"type": "text", "label": "", "content": "to have breakfast"}}, {"left": {"type": "text", "label": "", "content": "almorzar"}, "right": {"type": "text", "label": "", "content": "to have lunch"}}, {"left": {"type": "text", "label": "", "content": "merendar"}, "right": {"type": "text", "label": "", "content": "to have an afternoon snack"}}, {"left": {"type": "text", "label": "", "content": "cenar"}, "right": {"type": "text", "label": "", "content": "to have dinner"}}]', NULL, NULL, NULL, NULL, NULL, '2026-03-17 09:30:11.660865+00', NULL, NULL, 'es', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('6f1a6a00-3d52-4645-8ecf-f49b7c6c6ede', 1014, 'gap_fill', 'B2', 'vocabulary', 'His first attempt at the business failed, but his second one was a _______ success.', 'resounding', NULL, NULL, NULL, '["huge", "massive", "tremendous", "great"]', 'A complete, undeniable success — unmistakable.', 'A resounding success means a very great and unmistakeable success. Resounding is a strong intensifier — more emphatic than huge or great.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{Collocation}', false, 'Like a sound that fills a room.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('6ffba1a8-4b06-4e73-9398-1ee9b7bdddb6', 1015, 'gap_fill', 'B2', 'vocabulary', 'She was _______ with praise after her presentation — her manager called it the best he''d seen in years.', 'showered', NULL, NULL, NULL, NULL, 'To give in great quantity — like rain.', 'To be showered with praise means to receive a great deal of it all at once. The image is of praise falling like water — sudden and abundant.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{Collocation}', false, '___ with praise, ___ with gifts.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('07527c6f-efa0-423c-8a85-c8c6b7393e09', 1016, 'gap_fill', 'B2', 'vocabulary', 'The company has _______ its profits by 40% this year through cost-cutting and new markets.', 'boosted', NULL, NULL, NULL, '["increased", "grown", "raised"]', 'Increased significantly — like a rocket boost.', 'To boost profits means to increase them, often significantly and deliberately. Boost implies both the action taken and a strong positive result.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Business vocabulary",Collocation}', false, 'Often used with profits, sales, confidence.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('844d2664-5c20-4acb-8a59-415f15c47527', 1017, 'gap_fill', 'C1', 'vocabulary', 'The findings of the new study are largely _______ with earlier research on the same topic.', 'consistent', NULL, NULL, NULL, NULL, 'In agreement with — matching previous research.', 'Consistent with means in agreement or harmony with. If new findings are consistent with earlier research, the two support each other.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Dependent preposition"}', false, 'Often used with "with": ___ ___ X.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('a1675d85-f8b0-45c6-92a3-165925258cc8', 2327, 'multiple_choice', 'A2', 'spanish', 'El partido se juega en el ___.', 'estadio', '["estadio", "piscina", "cocina", "mercado"]', NULL, NULL, NULL, '"stadium".', '"Estadio" means "stadium".', '2026-06-01 07:35:54.312658+00', NULL, NULL, 'es', '{Sport}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('7b0631da-6c2f-42a0-bf1d-5971a4f0c465', 1018, 'gap_fill', 'C1', 'vocabulary', 'Her argument was completely _______ — every point supported the next, with no logical gaps.', 'coherent', NULL, NULL, NULL, '["watertight", "airtight", "logical"]', 'Logically connected — every point flows.', 'Coherent means logically structured and easy to follow — every part connects clearly to the next. Compare: watertight = having no flaws or gaps, especially in an argument or contract.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Business vocabulary"}', false, 'Sharing a root with "cohere" — to stick together.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('7fe099e2-0907-49f3-8576-12ab7bc9ad00', 1019, 'gap_fill', 'C1', 'vocabulary', 'The proposal was _______ on the grounds that it was too expensive and too risky.', 'rejected', NULL, NULL, NULL, '["dismissed", "turned down"]', 'Formally turned down — refused to accept.', 'To reject a proposal means to refuse or dismiss it officially. Rejected on the grounds that means refused for a specific stated reason.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Business vocabulary"}', false, 'Often paired with "on the grounds of" + reason.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('a20a9499-2bf8-4ae3-b9f5-1e3f9b6c42cc', 1020, 'gap_fill', 'C1', 'vocabulary', 'The data was carefully _______ before any conclusions were drawn.', 'scrutinised', NULL, NULL, NULL, '["scrutinized", "analysed", "examined", "reviewed"]', 'Examined very carefully and critically.', 'To scrutinise means to examine very carefully and critically. It implies more intensity than simply review or check — often used in formal, legal, or financial contexts.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Business vocabulary"}', false, 'From Latin "scrutinium" — close inspection.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('39d89cde-6a36-4bef-9fa6-ede89f527d0f', 1956, 'odd_one_out', 'B2', 'vocabulary', 'Three of these words suggest a lack of clarity. Which is the odd one out?', 'transparent', '["ambiguous", "vague", "obscure", "transparent"]', NULL, NULL, NULL, NULL, '"Transparent" means clear and easy to understand. "Ambiguous", "vague", and "obscure" all describe something difficult to interpret.', '2026-04-08 18:26:42.653742+00', NULL, NULL, 'en', '{Vocabulary}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('4948c3cf-9713-4963-99b6-cae9bd63a1c3', 688, 'error_correction', 'A2', 'adjectives', 'I am interesting in learning English.', 'I am interested in learning English.', '[]', NULL, NULL, NULL, NULL, 'We use "interested" (how you feel) not "interesting" (what something is like).', '2026-02-20 19:09:17.848852+00', NULL, NULL, 'en', '{Adjective}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('41d9ad78-09af-4f67-a87c-5c76e9b1840d', 1630, 'gap_fill', 'C1', 'travel', 'Despite the _______ of budget airlines, long-haul travel remains financially out of reach for many.', 'proliferation', NULL, NULL, NULL, '[{"answer": "accessibility", "feedback": "✅ ''Accessibility'' works — the sentence reads as ''cheap short-haul flights don''t make long-haul affordable''. The model answer ''proliferation'' emphasises the spread/growth of budget airlines specifically."}]', 'A rapid increase in number — multiplying.', 'Proliferation means rapid increase in number or spread. "The proliferation of budget airlines" = the fact that budget airlines have multiplied and spread widely.', '2026-03-27 08:23:03.995534+00', NULL, NULL, 'en', '{}', false, 'Sharing a root with "prolific".', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('8f07d5a4-df18-4ae0-b35f-cfeab493d047', 1366, 'multiple_choice', 'A1', 'prepositions', 'She wakes up _____ seven o''clock every morning.', 'at', '["at", "in", "on", "by"]', NULL, NULL, NULL, 'Clock times take this preposition.', 'Use at with clock times: at seven o''clock, at midnight, at noon.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('b2af8f7c-ad98-45b0-9288-daf0a2027df1', 247, 'multiple_choice', 'A2', 'articles', 'I usually have ___ breakfast at 8 am.', '(no article)', '["a", "the", "big", "(no article)"]', NULL, NULL, NULL, 'Meals don''t take an article — we say "have breakfast", not "have a breakfast".', 'We don''t use an article before meal names (breakfast, lunch, dinner) when talking about the meal in general: "have breakfast", "eat lunch", "cook dinner".', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{Article}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('b3d68b06-2ff8-44e6-8358-f40987e5d108', 1367, 'multiple_choice', 'A1', 'prepositions', 'We always go to the beach _____ summer.', 'in', '["at", "in", "on", "during"]', NULL, NULL, NULL, 'Seasons take this preposition.', 'Use in with seasons: in summer, in winter, in spring.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('5322b9e5-f532-4e95-bd9b-f327f0391626', 1364, 'matching', 'A2', 'spanish', 'Match each Spanish time expression to its English equivalent.', '["match_all_pairs"]', '[{"left": {"type": "text", "label": "", "content": "entre semana"}, "right": {"type": "text", "label": "", "content": "on weekdays"}}, {"left": {"type": "text", "label": "", "content": "el fin de semana"}, "right": {"type": "text", "label": "", "content": "at the weekend"}}, {"left": {"type": "text", "label": "", "content": "cada dos días"}, "right": {"type": "text", "label": "", "content": "every other day"}}, {"left": {"type": "text", "label": "", "content": "a diario"}, "right": {"type": "text", "label": "", "content": "every day / on a daily basis"}}]', NULL, NULL, NULL, NULL, NULL, '2026-03-17 09:30:11.660865+00', NULL, NULL, 'es', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('80f9ab87-e406-4669-927b-eac4c50984c2', 1365, 'matching', 'A2', 'spanish', 'Match each Spanish adverb to its English meaning.', '["match_all_pairs"]', '[{"left": {"type": "text", "label": "", "content": "normalmente"}, "right": {"type": "text", "label": "", "content": "normally / usually"}}, {"left": {"type": "text", "label": "", "content": "a menudo"}, "right": {"type": "text", "label": "", "content": "often"}}, {"left": {"type": "text", "label": "", "content": "de vez en cuando"}, "right": {"type": "text", "label": "", "content": "from time to time"}}, {"left": {"type": "text", "label": "", "content": "casi nunca"}, "right": {"type": "text", "label": "", "content": "hardly ever"}}]', NULL, NULL, NULL, NULL, NULL, '2026-03-17 09:30:11.660865+00', NULL, NULL, 'es', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('fb0b9ef0-ca7a-4708-9862-5d0fbb37203b', 2328, 'multiple_choice', 'A2', 'spanish', 'El ___ pita cuando hay una falta.', 'árbitro', '["árbitro", "jugador", "portero", "público"]', NULL, NULL, NULL, '"referee".', '"Árbitro" means "referee".', '2026-06-01 07:35:54.312658+00', NULL, NULL, 'es', '{Sport}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('80d1388f-f27d-4391-8825-944db2f0e7cd', 2329, 'multiple_choice', 'A2', 'spanish', 'Después de correr, estoy muy ___.', 'cansado', '["cansado", "contento", "triste", "enfadado"]', NULL, NULL, NULL, '"tired".', '"Cansado" means "tired" — how you feel after running.', '2026-06-01 07:35:54.312658+00', NULL, NULL, 'es', '{Sport}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('c2082b9e-ecac-4803-97c8-ce3701285116', 1957, 'odd_one_out', 'C1', 'idioms', 'Which of these is NOT an idiom?', 'follow protocol', '["turn a blind eye", "face the music", "pull strings", "follow protocol"]', NULL, NULL, NULL, NULL, '"Follow protocol" means exactly what it says. "Turn a blind eye" = deliberately ignore something, "face the music" = accept consequences, "pull strings" = use personal influence.', '2026-04-08 18:26:42.653742+00', NULL, NULL, 'en', '{Idioms}', true, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('d5155326-99a7-44f9-8cd2-8f0a9fce541d', 1958, 'odd_one_out', 'C2', 'idioms', 'Which of these is NOT an idiom?', 'draw up a contract', '["sit on the fence", "paint the town red", "burn the midnight oil", "draw up a contract"]', NULL, NULL, NULL, NULL, '"Draw up a contract" is a literal legal expression. "Sit on the fence" = avoid taking sides, "paint the town red" = go out and celebrate, "burn the midnight oil" = work very late.', '2026-04-08 18:26:42.653742+00', NULL, NULL, 'en', '{Idioms}', true, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('e867659a-c7e1-4b9b-9e84-201401520b00', 1959, 'odd_one_out', 'C1', 'vocabulary', 'Which of these is NOT a paradox?', 'Occam''s razor', '["This statement is false", "The Ship of Theseus", "Schrödinger''s cat", "Occam''s razor"]', NULL, NULL, NULL, NULL, '"Occam''s razor" is a philosophical principle (prefer the simplest explanation), not a paradox. The liar''s paradox, Ship of Theseus, and Schrödinger''s cat all involve genuine contradictions or unresolvable questions.', '2026-04-08 18:26:42.653742+00', NULL, NULL, 'en', '{"General Knowledge",Philosophy}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('64494c34-4c62-45af-b46a-ccaea48f870b', 1368, 'multiple_choice', 'A2', 'prepositions', 'I usually go to the gym _____ Mondays.', 'on', '["at", "in", "on", "by"]', NULL, NULL, NULL, 'Days of the week take this preposition.', 'Use on with specific days of the week: on Monday, on Fridays, on weekends.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('fe998f6d-ab96-42bd-9c14-6881fd4362e2', 1369, 'multiple_choice', 'A1', 'prepositions', 'Your phone is _____ the bedside chest.', 'on', '["at", "in", "on", "under"]', NULL, NULL, NULL, 'On a horizontal surface.', 'On is used for surfaces. The phone is placed on the bedside chest.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('149215e3-93b0-42cd-925e-26e1b0180ac7', 1370, 'multiple_choice', 'A2', 'prepositions', 'I''ll see you _____ Monday morning.', 'on', '["at", "in", "on", "by"]', NULL, NULL, NULL, 'Day + time of day takes the same preposition as days alone.', 'Use on with specific days or parts of specific days: on Monday morning, on Friday afternoon.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('39906039-3561-4a28-aa61-da6ad619e3cc', 2065, 'error_correction', 'B2', 'grammar', 'The report needs to be finish by Friday.', 'The report needs to be finished by Friday.', '[]', NULL, NULL, NULL, NULL, 'A passive infinitive needs the past participle: "to be finished", not "to be finish".', '2026-06-01 07:05:45.329436+00', NULL, NULL, 'en', '{Passive}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('b40712ad-2d57-4c3b-9112-e221433caade', 1558, 'multiple_choice', 'A1', 'prepositions', 'I always check my phone _____ getting out of bed.', 'before', '["before", "when", "during", "since"]', NULL, NULL, NULL, 'Earlier in time than something else.', 'Before means earlier in time than something else. After means later. During means while something is happening.', '2026-03-26 08:02:12.742714+00', NULL, NULL, 'en', '{"Preposition of time"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('6290d5f2-0f05-4cf3-91e0-2c844fd11928', 1371, 'multiple_choice', 'A2', 'prepositions', 'She lives _____ a small flat _____ the city centre.', 'in / in', '["in / in", "at / in", "on / at", "in / at"]', NULL, NULL, NULL, 'Inside an enclosed space (a flat) and inside an area (the city centre).', 'Live in is used for towns, cities, countries, and enclosed spaces like flats. City centre also uses in.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('b209b0c1-59e0-4bd1-a480-81f4fb881d40', 2091, 'sentence_building', 'A2', 'grammar', NULL, 'They were playing football in the park.', '["they", "were", "playing", "football", "in", "the", "park", "was", "played", "at"]', NULL, NULL, NULL, NULL, 'Past continuous: "were" + the -ing form "playing" describes an action in progress in the past.', '2026-06-01 07:13:28.516357+00', NULL, NULL, 'en', '{Tense}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('8aeac0cc-ca01-457e-98fe-c9de88072531', 728, 'matching', 'B2', 'vocabulary', 'Match each word to its definition.', 'match_all_pairs', '[{"left": {"type": "text", "content": "concise"}, "right": {"type": "text", "content": "Short and clear, using few words"}}, {"left": {"type": "text", "content": "ambiguous"}, "right": {"type": "text", "content": "Having more than one possible meaning"}}, {"left": {"type": "text", "content": "redundant"}, "right": {"type": "text", "content": "No longer needed or useful"}}, {"left": {"type": "text", "content": "coherent"}, "right": {"type": "text", "content": "Logical and easy to understand"}}, {"left": {"type": "text", "content": "eloquent"}, "right": {"type": "text", "content": "Fluent and persuasive in speaking"}}]', NULL, NULL, NULL, NULL, NULL, '2026-02-25 12:43:15.182597+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('2535de10-7b03-4e7e-8cea-d57696f981a3', 731, 'matching', 'A1', 'vocabulary', 'Match the picture to the correct word.', 'match_all_pairs', '[{"left": {"type": "image", "content": "https://dyxmgicedabvmsbuvxny.supabase.co/storage/v1/object/public/audio/matching/apple.png"}, "right": {"type": "text", "content": "apple"}}, {"left": {"type": "image", "content": "https://dyxmgicedabvmsbuvxny.supabase.co/storage/v1/object/public/audio/matching/chair.png"}, "right": {"type": "text", "content": "chair"}}, {"left": {"type": "image", "content": "https://dyxmgicedabvmsbuvxny.supabase.co/storage/v1/object/public/audio/matching/window.png"}, "right": {"type": "text", "content": "window"}}]', NULL, NULL, NULL, NULL, NULL, '2026-02-25 12:43:15.182597+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('f7443986-ffd1-47ea-b16a-d966ed6c4c9c', 2092, 'sentence_building', 'A2', 'grammar', NULL, 'Have you ever been to Italy?', '["have", "you", "ever", "been", "to", "italy", "has", "gone", "visited", "seen"]', NULL, NULL, NULL, NULL, 'Present perfect question with "ever": "Have you ever been…?" asks about life experience.', '2026-06-01 07:13:28.516357+00', NULL, NULL, 'en', '{Tense}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('e552b392-c019-40e8-bec1-845b68d514b7', 2093, 'sentence_building', 'A2', 'grammar', NULL, 'I can''t find my keys anywhere.', '["I", "can''t", "find", "my", "keys", "anywhere", "cannot", "finding", "somewhere"]', NULL, NULL, NULL, NULL, 'Modal negative: "can''t" + base verb "find" for present inability.', '2026-06-01 07:13:28.516357+00', NULL, NULL, 'en', '{"Modal verb"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('a39712fd-4628-4262-b875-c558c125eda8', 2094, 'sentence_building', 'A2', 'grammar', NULL, 'We didn''t have time for breakfast.', '["we", "didn''t", "have", "time", "for", "breakfast", "don''t", "had", "to"]', NULL, NULL, NULL, NULL, 'Past simple negative: "didn''t" + base verb "have".', '2026-06-01 07:13:28.516357+00', NULL, NULL, 'en', '{"Auxiliary verb"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('1fdb573b-52a9-4c6d-8ccb-12c956d9ad6d', 2095, 'sentence_building', 'A2', 'grammar', NULL, 'Does he live near the station?', '["does", "he", "live", "near", "the", "station", "do", "lives", "next"]', NULL, NULL, NULL, NULL, 'Present simple question: "Does" + subject + base verb "live".', '2026-06-01 07:13:28.516357+00', NULL, NULL, 'en', '{"Auxiliary verb"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('2606fa14-3d62-4bb9-9487-97b03218fecf', 2096, 'sentence_building', 'A2', 'grammar', NULL, 'There aren''t any tickets left.', '["there", "aren''t", "any", "tickets", "left", "isn''t", "some", "leaving"]', NULL, NULL, NULL, NULL, '"There aren''t any" is the plural negative used with countable nouns like "tickets".', '2026-06-01 07:13:28.516357+00', NULL, NULL, 'en', '{Agreement}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('d39fa1ab-59e4-4dff-b009-42c7721580a9', 2097, 'sentence_building', 'A2', 'grammar', NULL, 'My sister is older than me.', '["my", "sister", "is", "older", "than", "me", "more", "old", "then"]', NULL, NULL, NULL, NULL, 'Comparative of a short adjective: "older than", with the object pronoun "me".', '2026-06-01 07:13:28.516357+00', NULL, NULL, 'en', '{Comparative}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('912c1d3d-9394-485b-9b88-f5f3f16d45d5', 2098, 'sentence_building', 'A2', 'grammar', NULL, 'You should see a doctor soon.', '["you", "should", "see", "a", "doctor", "soon", "must", "to", "seeing"]', NULL, NULL, NULL, NULL, 'Modal of advice: "should" + base verb "see".', '2026-06-01 07:13:28.516357+00', NULL, NULL, 'en', '{"Modal verb"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('c8934039-ecca-46d1-9a6d-fd8140f03f60', 2099, 'sentence_building', 'A2', 'grammar', NULL, 'I''ve known her since school.', '["I''ve", "known", "her", "since", "school", "know", "for", "knew"]', NULL, NULL, NULL, NULL, 'Present perfect + "since": "I''ve known her since school" links a past start to now.', '2026-06-01 07:13:28.516357+00', NULL, NULL, 'en', '{Tense}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('8d805de4-d2cc-4c0d-9ba8-2f11b0aaa5f0', 2101, 'sentence_building', 'B2', 'grammar', NULL, 'She told me she had already finished the report.', '["she", "told", "me", "had", "already", "finished", "the", "report", "said", "has", "finish"]', NULL, NULL, NULL, NULL, 'Reported speech: the original past simple shifts back to the past perfect "had already finished".', '2026-06-01 07:13:28.516357+00', NULL, NULL, 'en', '{"Reported speech"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('404b46d6-24d2-41b0-ab46-9087d15215fb', 18, 'gap_fill', 'B1', 'modals_permission', '___ (I / can / borrow) your pen for a moment?', 'can I borrow', NULL, NULL, NULL, NULL, 'Asking for permission', 'Can, could, or may are used to ask for permission.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{"Modal verb"}', false, 'Question word order: modal + subject + verb.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('ab3d2aa7-c662-4845-ba17-897e945c1d66', 1372, 'multiple_choice', 'A1', 'prepositions', 'I go to work _____ bus every day.', 'by', '["by", "in", "on", "with"]', NULL, NULL, NULL, '___ bus, ___ train, ___ car — means of transport.', 'Use by with forms of transport when talking about how you travel: by bus, by train, by car.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('1aa3147e-0385-487e-94a7-77b9615111f5', 1373, 'multiple_choice', 'A2', 'prepositions', 'The post office is _____ the station and the pub.', 'between', '["between", "among", "beside", "through"]', NULL, NULL, NULL, 'Two things on either side — a station here, a pub there.', 'Between is used when something is in the middle of two specific things. Among is used with groups of three or more.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('195c3746-e39c-41cd-9f2e-e7626dccdea1', 1374, 'multiple_choice', 'A2', 'prepositions', 'We met _____ the cafe _____ the corner.', 'at / on', '["at / on", "in / at", "on / in", "at / in"]', NULL, NULL, NULL, '___ a specific place + ___ the corner — different prepositions.', 'Meet at a place (at the cafe). On the corner is a fixed expression for location.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('9187593a-95e4-4e0c-9ab8-e81a3c7f07e9', 1375, 'multiple_choice', 'A1', 'prepositions', 'I study English _____ the evenings.', 'in', '["at", "in", "on", "by"]', NULL, NULL, NULL, '___ the morning, ___ the afternoon, ___ the evening.', 'Use in with parts of the day: in the morning, in the afternoon, in the evening. Exception: at night.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('4c0d4cf8-b17c-450d-9910-41c5a560d67e', 2071, 'error_correction', 'C1', 'grammar', 'The committee recommended that he submits the form immediately.', 'The committee recommended that he submit the form immediately.', '[]', NULL, NULL, NULL, NULL, 'After "recommend that", the subjunctive uses the base form: "that he submit", not "submits".', '2026-06-01 07:05:45.329436+00', NULL, NULL, 'en', '{Subjunctive}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('5855ee31-5e05-4857-a40c-31c73d7ff28a', 2290, 'multiple_choice', 'A2', 'sport', 'He ___ football every Saturday with his friends.', 'plays', '["plays", "does", "makes", "goes"]', NULL, NULL, NULL, 'The verb we use with team ball games.', 'We use "play" with team and ball games: "play football".', '2026-06-01 07:35:54.312658+00', NULL, NULL, 'en', '{Sport}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('6e0f9663-c4f6-419d-8f7e-c73b11f6cb62', 1732, 'multiple_choice', 'A2', 'sport', 'In a spinning class, what does the instructor mean when they say "increase your resistance"?', 'make pedalling harder', '["make pedalling harder", "pedal faster", "stand up on the bike", "slow down and recover"]', NULL, NULL, NULL, 'On a spinning bike, the resistance dial controls how hard the wheel is to turn.', 'Resistance on a spinning bike simulates the effort of cycling uphill — the higher the resistance, the harder it is to pedal. Instructors use cues like "add resistance", "turn it up", or "climb" to simulate hill sections. Indoor cycling classes are also called spin classes or cycling classes.', '2026-03-30 08:52:38.502672+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('af5c5ad1-6321-40b9-9f6b-6acb6d9b73c4', 2291, 'multiple_choice', 'A2', 'sport', 'She ___ swimming three times a week.', 'goes', '["goes", "plays", "does", "makes"]', NULL, NULL, NULL, 'The verb for "___ swimming / ___ running".', 'We use "go" with activities ending in -ing: "go swimming".', '2026-06-01 07:35:54.312658+00', NULL, NULL, 'en', '{Sport}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('f2950c8b-b04e-432f-b678-fce7b7651835', 1736, 'multiple_choice', 'B1', 'sport', 'What does it mean to "hit the wall" in marathon running?', 'to reach a point of exhaustion', '["to reach a point of exhaustion", "to run into an obstacle on the course", "to stop running and walk", "to finish the race strongly"]', NULL, NULL, NULL, 'An idiom for sudden, dramatic exhaustion — usually around mile 20 of a marathon.', 'Hitting the wall — also called bonking — typically happens around kilometre 30 to 35 in a marathon, when glycogen stores are depleted and the body struggles to continue. Runners describe it as a sudden, overwhelming fatigue. Proper pacing and nutrition strategies, including energy gels, are designed to delay or prevent the wall.', '2026-03-30 08:52:38.502672+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('3524f2cc-b65f-4913-8b6c-a62fc8fc080b', 1720, 'gap_fill', 'C1', 'business_phrasal_verbs', 'The acquisition allowed the larger firm to _____ its smaller rival and eliminate the competition.', 'swallow up', NULL, NULL, NULL, '[{"answer": "acquire", "feedback": "Acquire works in meaning, but the sentence is testing the phrasal verb swallow up, which implies the smaller company loses its identity entirely — stronger than simply acquiring it."}]', 'To absorb or take over completely — like a big fish eating a small one.', 'Swallow up means to absorb or take over something completely, leaving it with no independent existence. It implies the target loses its identity entirely. Compare: take over (more neutral — to assume control), absorb (formal equivalent), gobble up (informal, implies speed and aggression). Often used in journalism about mergers and acquisitions.', '2026-03-30 08:25:59.401228+00', NULL, NULL, 'en', '{}', false, 'Two words. Starts with s___ u___.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('3782b5c4-3ed8-4acb-a7cb-7780818a3d5d', 1721, 'gap_fill', 'C2', 'business_phrasal_verbs', 'After the product recall, it took the company years to _____ consumer confidence.', 'win back', NULL, NULL, NULL, NULL, 'To regain something that was lost — like trust or customers.', 'Win back means to regain something that was lost — trust, customers, market share, or reputation. It implies effort and a strategic approach. Compare: rebuild (to reconstruct gradually), restore (to return something to its former state), recover (to get back to a previous level). Win back is particularly common in brand and customer relations contexts.', '2026-03-30 08:25:59.401228+00', NULL, NULL, 'en', '{}', false, 'Two words. Starts with w___ b___.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('84e33da3-318c-476d-986a-b042cf22d644', 1722, 'gap_fill', 'C2', 'business_phrasal_verbs', 'The aggressive competitor has been _____ the company''s market share for the past three years.', 'eating into', NULL, NULL, NULL, NULL, 'Gradually reducing something valuable — like termites in a wooden beam.', 'Eat into something means to gradually reduce or erode it — most commonly market share, profits, reserves, or savings. The image is of something being consumed from the outside in. Compare: erode (formal equivalent), chip away at (similar — gradual reduction), undermine (to weaken the foundations of something). Eat into is informal but widely used in financial journalism.', '2026-03-30 08:25:59.401228+00', NULL, NULL, 'en', '{}', false, 'Two words: -ing form + i___.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('33b0fbc7-5097-4171-98aa-ba1c32439343', 2292, 'multiple_choice', 'A2', 'sport', 'They ___ yoga to relax in the evenings.', 'do', '["do", "play", "go", "make"]', NULL, NULL, NULL, 'The verb for activities without a ball, like yoga or judo.', 'We use "do" for activities without a ball, like yoga or judo: "do yoga".', '2026-06-01 07:35:54.312658+00', NULL, NULL, 'en', '{Sport}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('05a4fb3d-9efb-41eb-a968-c003c56599c8', 1723, 'gap_fill', 'C2', 'business_phrasal_verbs', 'The two sides eventually _____ their differences and signed the agreement.', 'set aside', NULL, NULL, NULL, NULL, 'To put differences or feelings in a separate place — to put them aside.', 'Set aside differences or disagreements means to temporarily or permanently stop allowing them to be an obstacle, in order to achieve a shared goal. Compare: put aside (very similar), bury the hatchet (to end a conflict — more informal and idiomatic), resolve (to deal with and eliminate). Set aside is also used to mean to reserve money or time for a specific purpose.', '2026-03-30 08:25:59.401228+00', NULL, NULL, 'en', '{}', false, 'Two words. Starts with s___ a___.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('ec260284-f66f-4a44-80fa-a94332e19cd9', 2293, 'multiple_choice', 'A2', 'sport', 'Our team ___ the match 2–0.', 'won', '["won", "gained", "earned", "beat"]', NULL, NULL, NULL, 'Was successful in the game.', 'To "win" a match means to be successful in it. We win a match or a game, but we beat an opponent.', '2026-06-01 07:35:54.312658+00', NULL, NULL, 'en', '{Sport}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('583705a5-14fb-4cef-9ce1-5462f54856ee', 2102, 'sentence_building', 'B2', 'grammar', NULL, 'The bridge is being repaired at the moment.', '["the", "bridge", "is", "being", "repaired", "at", "moment", "was", "repair", "in"]', NULL, NULL, NULL, NULL, 'Present continuous passive: "is being repaired" describes an action happening to the subject now.', '2026-06-01 07:13:28.516357+00', NULL, NULL, 'en', '{Passive}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('171cb02f-57d1-48b3-a8d9-dd12260c295a', 2103, 'sentence_building', 'B2', 'grammar', NULL, 'I''d rather you didn''t smoke in here.', '["I''d", "rather", "you", "didn''t", "smoke", "in", "here", "don''t", "smoking", "prefer"]', NULL, NULL, NULL, NULL, '"I''d rather + past tense" expresses a preference about someone else''s behaviour: "I''d rather you didn''t smoke".', '2026-06-01 07:13:28.516357+00', NULL, NULL, 'en', '{Tense}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('67c7aece-5fd5-4a36-a1ad-281cc58420d6', 1385, 'gap_fill', 'B2', 'prepositions', 'She suffers _____ insomnia and rarely sleeps more than five hours.', 'from', NULL, NULL, NULL, NULL, 'Always: "suffer ___ + illness".', 'Suffer from is the correct collocation for medical or ongoing conditions. Compare: recover from, benefit from.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}', false, 'Same as in "die ___" (a disease).', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('59578c8d-893e-4478-9a39-d83ae80cb01b', 2104, 'sentence_building', 'B2', 'grammar', NULL, 'He must have left his phone at home.', '["he", "must", "have", "left", "his", "phone", "at", "home", "has", "leave", "in"]', NULL, NULL, NULL, NULL, 'Modal deduction about the past: "must have left" shows a confident guess.', '2026-06-01 07:13:28.516357+00', NULL, NULL, 'en', '{"Modal verb"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('661d73e5-3cac-4db9-b5a7-9f2ec989715b', 1960, 'odd_one_out', 'C2', 'vocabulary', 'Which of these thinkers is NOT associated with existentialism?', 'Plato', '["Sartre", "Camus", "Nietzsche", "Plato"]', NULL, NULL, NULL, NULL, 'Plato is an ancient Greek philosopher associated with idealism and the theory of Forms. Sartre and Camus are central existentialists. Nietzsche''s ideas were a major precursor to the movement.', '2026-04-08 18:26:42.653742+00', NULL, NULL, 'en', '{"General Knowledge",Philosophy}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('ced81b20-b519-48ba-9289-0a121b1d0953', 716, 'error_correction', 'A2', 'there_is_there_are', 'There is lots of people in the park.', 'There are lots of people in the park.', '[]', NULL, NULL, NULL, NULL, '"People" is plural, so we need "are", not "is".', '2026-02-20 19:09:17.848852+00', NULL, NULL, 'en', '{"There is/are"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('1cdecbc3-b203-4b3d-b288-21c5901a15db', 1961, 'odd_one_out', 'C1', 'vocabulary', 'Three of these are genuine words with recognised meanings. Which one did we invent?', 'blorfulous', '["petrichor", "sonder", "hiraeth", "blorfulous"]', NULL, NULL, NULL, NULL, '"Blorfulous" is fictional. "Petrichor" = the smell of rain on dry earth, "sonder" = the realisation that every stranger has a rich inner life, "hiraeth" = a Welsh word for deep longing for home.', '2026-04-08 18:26:42.653742+00', NULL, NULL, 'en', '{Humour,Vocabulary}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('299a42f5-edec-4ad7-9920-027a9496e455', 1962, 'odd_one_out', 'C2', 'vocabulary', 'Three of these are genuine words in the Oxford English Dictionary. Which one is not?', 'snorkelicious', '["flibbertigibbet", "callipygian", "lollygag", "snorkelicious"]', NULL, NULL, NULL, NULL, '"Snorkelicious" is made up. "Flibbertigibbet" = a frivolous chatterer, "callipygian" = having well-shaped buttocks (yes, really), "lollygag" = to dawdle. The English language contains multitudes.', '2026-04-08 18:26:42.653742+00', NULL, NULL, 'en', '{Humour,Vocabulary}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('deda3674-3649-4a16-8ea6-b06077d2be1a', 718, 'error_correction', 'A2', 'time_expressions', 'I went to the cinema this night.', 'I went to the cinema last night.', '[]', NULL, NULL, NULL, NULL, 'We say "last night" in the past, or "tonight" if it is the same day.', '2026-02-20 19:09:17.848852+00', NULL, NULL, 'en', '{"Time expression"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('4b61ac37-07fd-4768-8142-a48128783d16', 1725, 'gap_fill', 'C2', 'business_phrasal_verbs', 'The consultants were brought in to _____ inefficiencies and recommend a new operating model.', 'root out', NULL, NULL, NULL, NULL, 'To find and remove something completely — like pulling a weed up by its roots.', 'Root out means to find and eliminate something unwanted — inefficiencies, corruption, waste, or bad practices. The image is of pulling something out by its roots so it cannot grow back. Compare: weed out (very similar — to identify and remove), stamp out (to eliminate completely), address (more neutral). Root out implies both discovery and elimination.', '2026-03-30 08:25:59.401228+00', NULL, NULL, 'en', '{}', false, 'Two words. Starts with r___ o___.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('7f21df04-48b9-46c2-a024-5b31ad03ad5a', 1241, 'gap_fill', 'B2', 'business_phrasal_verbs', 'After months of negotiation, the two companies finally _____ a deal.', 'hammered out', NULL, NULL, NULL, NULL, 'To negotiate with great effort — like working with a hammer.', 'Hammer out means to reach an agreement after long and difficult negotiations. Compare: iron out, thrash out.', '2026-03-18 19:58:52.376507+00', NULL, NULL, 'en', '{}', false, 'Often paired with "deal", "agreement", "compromise".', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('a3efbf29-67c9-4e64-a449-c8a54a47da8c', 1252, 'gap_fill', 'C2', 'business_phrasal_verbs', 'The CEO was forced to _____ after the scandal became public.', 'step down', NULL, NULL, NULL, NULL, 'To resign from a leadership role — step out of position.', 'Step down means to resign from a senior position, usually under pressure or voluntarily. Compare: stand down, resign.', '2026-03-18 19:58:52.376507+00', NULL, NULL, 'en', '{}', false, 'Often used after a scandal or pressure.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('43bca0cc-c986-4707-8f47-ce6eb3c41eb8', 1380, 'gap_fill', 'B1', 'prepositions', 'He cut down _____ caffeine after his doctor''s advice.', 'on', NULL, NULL, NULL, NULL, 'Phrasal: "cut down ___" = reduce.', 'Cut down on means to reduce the amount of something. The preposition on is part of the phrasal verb and cannot be omitted.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}', false, 'Same preposition as in "cut back ___".', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('8e0d0d1b-0b30-43d6-b0b9-b540e39396a7', 1381, 'gap_fill', 'B2', 'prepositions', 'The key _____ maintaining a good routine lies in being consistent.', 'to', NULL, NULL, NULL, NULL, 'Phrase: "the key ___ + -ing" — what unlocks something.', 'The key to (doing) something is a fixed expression. The to is a preposition followed by a gerund (maintaining).', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}', false, 'Same as in "the secret ___ X".', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('adf5e2c5-0bc8-4de4-8293-21fb20110d28', 2105, 'sentence_building', 'B2', 'grammar', NULL, 'By next year, they will have moved to Canada.', '["by", "next", "year", "they", "will", "have", "moved", "to", "canada", "would", "move", "in"]', NULL, NULL, NULL, NULL, 'Future perfect: "will have moved" describes something completed before a future point.', '2026-06-01 07:13:28.516357+00', NULL, NULL, 'en', '{Tense}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('f7ae36c4-00ac-4ac8-a0c8-97ba39cb1e9a', 835, 'error_correction', 'A2', 'grammar', 'They didn''t went to the concert.', 'They didn''t go to the concert.', '[]', NULL, NULL, NULL, NULL, 'After "didn''t" (did not), we use the infinitive. "They didn''t go" — not "didn''t went".', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('4c14c66d-7021-4298-8df6-8c2bf5a2e4dd', 2108, 'sentence_building', 'B2', 'grammar', NULL, 'The more I practise, the better I get.', '["the", "more", "I", "practise", "better", "get", "most", "good", "practising"]', NULL, NULL, NULL, NULL, 'The comparative correlative: "The more …, the better …" links two changing quantities.', '2026-06-01 07:13:28.516357+00', NULL, NULL, 'en', '{Comparative}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('6a27c3b2-0b60-48ad-8fee-59a0f5cbe034', 1384, 'gap_fill', 'B1', 'prepositions', 'I''m looking forward _____ having a proper break next week.', 'to', NULL, NULL, NULL, NULL, 'Phrasal: "look forward ___ + -ing".', 'Look forward to is a fixed phrasal verb. The to is a preposition followed by a gerund (-ing), not the infinitive.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}', false, 'The "to" here is a preposition, not infinitive — followed by -ing.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('0d692de7-774a-4647-815d-9c4e5de80654', 1383, 'gap_fill', 'B2', 'prepositions', 'It''s hard to concentrate _____ work when you''re sleep-deprived.', 'on', NULL, NULL, NULL, '[{"answer": "at", "feedback": "✅ ''Concentrate at work'' is also fine — it means focus while at the workplace. The model answer ''concentrate on'' is the fixed collocation for focusing on a task."}]', 'Always: "concentrate ___ + something".', 'Concentrate on is the correct collocation. Compare: focus on, work on, reflect on.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}', false, 'Same preposition as in "focus ___".', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('ab2d207e-8ee0-4fb2-af25-6c493abab0ba', 643, 'sentence_building', 'A1', 'there_is_there_are', '', 'there is a dog in the garden', '["there", "any", "a", "cats", "in", "the", "garden", "is", "dog"]', '["in the garden there is a dog."]', 'There is a dog in the garden is more natural ', NULL, NULL, 'There is + singular noun + place. Use "is" for singular.', '2026-02-17 09:58:54.170896+00', NULL, NULL, 'en', '{"There is/are"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('4828bcb1-c82b-4a69-907b-751e67807207', 631, 'sentence_building', 'A2', 'adjectives', '', 'the weather is very cold today', '["the", "weather", "is", "very", "cold", "today", "were", "it"]', NULL, NULL, NULL, NULL, 'We use ''the weather is'' + adjective to describe current weather. ''Very'' goes before the adjective to make it stronger.', '2026-02-13 08:00:10.850224+00', NULL, NULL, 'en', '{Adjective}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('acd654a6-20a1-41a1-8e70-05346c20a5a1', 1963, 'odd_one_out', 'C1', 'vocabulary', 'Three of these verbs mean to confirm or support something. Which is the odd one out?', 'undermine', '["corroborate", "substantiate", "vindicate", "undermine"]', NULL, NULL, NULL, NULL, '"Undermine" means to weaken something gradually. "Corroborate", "substantiate", and "vindicate" all involve confirming or proving something.', '2026-04-08 18:26:42.653742+00', NULL, NULL, 'en', '{Vocabulary}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('7c1647b3-d870-4991-b209-6cd55376a39d', 1401, 'multiple_choice', 'A2', 'vocabulary', 'Which word means to do something regularly without thinking about it?', 'automatically', '["automatically", "carefully", "quickly", "rarely"]', NULL, NULL, NULL, 'Without conscious effort — like a habit.', 'Automatically means without conscious thought or effort. It is the adverb form of automatic.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('03624e79-820e-47e2-8362-6cd652b24ef0', 1402, 'multiple_choice', 'A2', 'vocabulary', 'If you feel _____, you need to eat something.', 'hungry', '["hungry", "sleepy", "thirsty", "tired"]', NULL, NULL, NULL, 'Wanting to eat — your stomach is empty.', 'Hungry means wanting or needing food. Thirsty is the equivalent feeling for wanting water.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('df89cf1b-a9dd-4370-8a35-3cc827a385af', 1742, 'gap_fill', 'B1', 'sport', 'After six weeks of crossfit, she noticed a significant improvement in her _____ — she could complete exercises she couldn''t even attempt before.', 'fitness', NULL, NULL, NULL, NULL, 'The general state of being physically conditioned and able.', 'Fitness refers to the overall physical condition of the body, including strength, cardiovascular endurance, flexibility, and coordination. In everyday English, fitness is uncountable. Related expressions: get fit (to improve fitness), fitness goal, fitness level, fitness class. CrossFit is popular because it works multiple components of fitness simultaneously.', '2026-03-30 08:52:38.502672+00', NULL, NULL, 'en', '{}', false, 'Single word. Starts with f___.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('e8e8e9de-5cec-4b8a-badc-6be3b785f009', 1743, 'gap_fill', 'B1', 'sport', 'He decided to _____ his running to three times a week and add two swimming sessions for variety.', 'cut down', NULL, NULL, NULL, '[{"answer": "increase", "feedback": "This works too — ''increase'' is grammatically fine here. The model answer ''cut down'' means to reduce, which fits if he was running more often; but ''increase'' fits equally well if he was running less."}, {"answer": "increases", "feedback": "This works too — ''increase'' is grammatically fine here (just without the ''s''). The model answer ''cut down'' means to reduce; ''increase'' fits if he was running less often before."}]', 'To reduce — to do less of something.', 'Cut down (on) means to reduce the amount or frequency of something. In a fitness context, cutting down on one activity to make room for another is a common way to vary training and prevent overuse injuries. Compare: cut back (similar but broader), reduce, scale back.', '2026-03-30 08:52:38.502672+00', NULL, NULL, 'en', '{}', false, 'Two words. Starts with c___ d___.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('d05b2469-2f56-47c8-9f2a-8e699addc345', 1833, 'gap_fill', 'A2', 'spanish', 'Cuando entré en la habitación del hotel, me di cuenta de que la cama no _______ hecha.', 'estaba', NULL, NULL, NULL, NULL, NULL, 'Usamos "estar" para describir el estado de las cosas. Imperfecto porque describe el estado en ese momento.', '2026-04-06 16:43:51.906934+00', NULL, NULL, 'es', '{Spanish}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('3697e2e2-f7f8-455d-a66e-378b94cf762c', 836, 'error_correction', 'A2', 'grammar', 'I buyed a new phone last week.', 'I bought a new phone last week.', '[]', NULL, NULL, NULL, NULL, '"Buy" is an irregular verb. Its past simple form is "bought". Unfortunately, you have to study irregular verbs, but there are patterns you can learn!', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('ac9a7258-ebce-4842-9baf-fa52a51d9a59', 1964, 'odd_one_out', 'C2', 'vocabulary', 'Three of these words describe something complex or hard to follow. Which is the odd one out?', 'lucid', '["labyrinthine", "byzantine", "convoluted", "lucid"]', NULL, NULL, NULL, NULL, '"Lucid" means clear and easy to understand. "Labyrinthine", "byzantine", and "convoluted" all describe something intricate or difficult to navigate.', '2026-04-08 18:26:42.653742+00', NULL, NULL, 'en', '{Vocabulary}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('a1b2c3d4-0913-0913-0913-000000000913', 913, 'matching', 'A2', 'vocabulary', 'Match each adjective to its opposite.', 'match_all_pairs', '[{"left": {"type": "text", "content": "cheap"}, "right": {"type": "text", "content": "expensive"}}, {"left": {"type": "text", "content": "easy"}, "right": {"type": "text", "content": "difficult"}}, {"left": {"type": "text", "content": "noisy"}, "right": {"type": "text", "content": "quiet"}}, {"left": {"type": "text", "content": "fast"}, "right": {"type": "text", "content": "slow"}}, {"left": {"type": "text", "content": "hot"}, "right": {"type": "text", "content": "cold"}}]', NULL, NULL, NULL, NULL, NULL, '2026-03-03 15:58:50.696706+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('a1b2c3d4-0914-0914-0914-000000000914', 914, 'matching', 'A2', 'vocabulary', 'Match each travel word to its meaning.', 'match_all_pairs', '[{"left": {"type": "text", "content": "depart"}, "right": {"type": "text", "content": "to leave a place"}}, {"left": {"type": "text", "content": "arrive"}, "right": {"type": "text", "content": "to reach a place"}}, {"left": {"type": "text", "content": "book"}, "right": {"type": "text", "content": "to reserve something in advance"}}, {"left": {"type": "text", "content": "cancel"}, "right": {"type": "text", "content": "to decide something will not happen"}}, {"left": {"type": "text", "content": "check in"}, "right": {"type": "text", "content": "to register on arrival at a hotel or airport"}}]', NULL, NULL, NULL, NULL, NULL, '2026-03-03 15:58:50.696706+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('665f8abb-654b-491c-8ded-c401e1552a74', 2100, 'sentence_building', 'B2', 'grammar', 'Si hubiera salido antes, no habría perdido el tren.', 'If I had left earlier, I wouldn''t have missed the train.', '["if", "I", "had", "left", "earlier", "wouldn''t", "have", "missed", "the", "train", "would", "leave", "miss"]', NULL, NULL, NULL, NULL, 'Third conditional: "If I had left … I wouldn''t have missed" — an unreal past situation.', '2026-06-01 07:13:28.516357+00', NULL, NULL, 'en', '{Conditional}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('21d19f15-1577-4d33-b0ab-7431578f0ef7', 2112, 'sentence_building', 'C1', 'grammar', 'Lo que necesito es dormir bien una noche.', 'What I need is a good night''s sleep.', '["what", "I", "need", "is", "a", "good", "night''s", "sleep", "that", "are", "nights"]', NULL, NULL, NULL, NULL, 'Pseudo-cleft for emphasis: "What I need is …" front-loads the important information.', '2026-06-01 07:13:28.516357+00', NULL, NULL, 'en', '{Cleft}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('8425e5ca-e46a-4ded-8bc7-5106e0c19988', 2113, 'sentence_building', 'C1', 'grammar', 'Fue el ruido lo que me mantuvo despierto toda la noche.', 'It was the noise that kept me awake all night.', '["it", "was", "the", "noise", "that", "kept", "me", "awake", "all", "night", "which", "keep", "whole"]', NULL, NULL, NULL, NULL, 'Cleft sentence: "It was the noise that …" highlights one element of the sentence.', '2026-06-01 07:13:28.516357+00', NULL, NULL, 'en', '{Cleft}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('abbf578f-31bc-4334-808e-49ef52298ff1', 2114, 'sentence_building', 'C1', 'grammar', 'No la perdonó hasta que ella se disculpó.', 'Not until she apologised did he forgive her.', '["not", "until", "she", "apologised", "did", "he", "forgive", "her", "when", "does", "forgave"]', NULL, NULL, NULL, NULL, 'Negative inversion: "Not until … did he forgive her" delays and emphasises the main clause.', '2026-06-01 07:13:28.516357+00', NULL, NULL, 'en', '{Inversion}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('789f2736-c70c-4f4c-9dc2-c3e17921e593', 1834, 'gap_fill', 'A2', 'spanish', 'Nunca he _______ flamenco, pero me gustaría aprender algún día.', 'bailado', NULL, NULL, NULL, NULL, NULL, 'Participio pasado de "bailar" para el pretérito perfecto compuesto: he bailado.', '2026-04-06 16:43:51.906934+00', NULL, NULL, 'es', '{Spanish}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('059e5767-8c09-4686-9b76-1336cea5de51', 1835, 'gap_fill', 'A2', 'spanish', 'La guía turística nos _______ que el castillo tiene más de quinientos años de historia.', 'explicó', NULL, NULL, NULL, NULL, NULL, '"Explicar" en pretérito indefinido, tercera persona singular: explicó.', '2026-04-06 16:43:51.906934+00', NULL, NULL, 'es', '{Spanish}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('a1b2c3d4-0915-0915-0915-000000000915', 915, 'matching', 'A2', 'vocabulary', 'Match each word to the correct category.', 'match_all_pairs', '[{"left": {"type": "text", "content": "apple"}, "right": {"type": "text", "content": "fruit"}}, {"left": {"type": "text", "content": "carrot"}, "right": {"type": "text", "content": "vegetable"}}, {"left": {"type": "text", "content": "salmon"}, "right": {"type": "text", "content": "fish"}}, {"left": {"type": "text", "content": "chicken"}, "right": {"type": "text", "content": "meat"}}, {"left": {"type": "text", "content": "cheddar"}, "right": {"type": "text", "content": "cheese"}}]', NULL, NULL, NULL, NULL, NULL, '2026-03-03 15:58:50.696706+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('59517f15-d2d0-48ad-a2f0-9736ad8278a6', 633, 'sentence_building', 'A2', 'there_is_there_are', '', 'there are two cats in the garden', '["there", "are", "two", "cats", "in", "the", "garden", "is", "a"]', NULL, NULL, '["in the garden there are two cats ."]', NULL, 'We use ''there are'' for plural nouns and ''there is'' for singular. Two cats = plural, so ''there are''.', '2026-02-13 08:00:10.850224+00', NULL, NULL, 'en', '{"There is/are"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('a3773e49-58e7-4bc1-bfca-01231777ce5b', 539, 'multiple_choice', 'C1', 'idioms', 'We''re all in the same ___ when it comes to rising costs.', 'boat', '["ship", "boat", "car", "bus"]', NULL, NULL, NULL, 'In the same situation — an idiom involving water transport.', 'In the same boat = in the same difficult situation.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Fixed expression"}', true, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('b04a2327-a54f-40f5-8cf5-d892c74b52dd', 2115, 'sentence_building', 'C1', 'grammar', 'Insisto en que se le diga inmediatamente.', 'I insist that he be told immediately.', '["I", "insist", "that", "he", "be", "told", "immediately", "is", "tell", "insisted"]', NULL, NULL, NULL, NULL, 'Subjunctive after "insist that": the base form "be told", with no tense change.', '2026-06-01 07:13:28.516357+00', NULL, NULL, 'en', '{Subjunctive}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('8851ff0c-d874-4189-85b1-dbe366ff3ee5', 1836, 'gap_fill', 'A2', 'spanish', '¿Me _______ decir cómo se llega a la catedral desde aquí?', 'podría', NULL, NULL, NULL, NULL, NULL, '"Poder" en condicional simple para hacer una petición educada: ¿me podría + infinitivo?', '2026-04-06 16:43:51.906934+00', NULL, NULL, 'es', '{Spanish}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('34edf13c-9871-465f-b791-fa29348c368d', 801, 'odd_one_out', 'A1', 'grammar', 'Three of these are verbs (action words). Which is the odd one out?', 'fast', '["run", "jump", "fast", "swim"]', NULL, NULL, NULL, NULL, 'Run, jump, and swim are all verbs — things you do. "Fast" is an adjective (or adverb) meaning quick. You can run fast, but "fast" itself is not a verb.', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('27baeea2-7b3a-49e1-9938-f980dc4fc269', 296, 'gap_fill', 'A1', 'have_got', 'I ___ (h... got) a dog.', 'have got', NULL, NULL, 'British English uses have/has got, where Americans use have/has.', NULL, 'I + ___ — informal way of saying "I have".', 'Have got = have (possession). I/you/we/they have got.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Have got"}', false, 'Same as "I have a dog" — just informal.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('c04696b4-7c1c-4eba-993f-1e9826ea5a20', 798, 'odd_one_out', 'A1', 'home', 'Three of these are rooms in a house. Which is the odd one out?', 'garden', '["kitchen", "bedroom", "garden", "bathroom"]', NULL, NULL, NULL, NULL, 'The kitchen, bedroom, and bathroom are all indoor rooms. A garden is outside — which is lovely in summer, but it''s not a room!', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{Vocabulary}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('1116bab8-2aa7-417f-9ac4-eb2eebb88444', 799, 'odd_one_out', 'A1', 'weather', 'Three of these describe the weather. Which is the odd one out?', 'hungry', '["sunny", "rainy", "cloudy", "hungry"]', NULL, NULL, NULL, NULL, 'Sunny, rainy, and cloudy all describe the weather. Hungry describes how you feel when you need food — nothing to do with the forecast!', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{Vocabulary}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('d7fb2955-c046-4607-9600-5d34aac96d8b', 1965, 'odd_one_out', 'C1', 'grammar', 'Three of these sentences use inversion. Which is the odd one out?', 'I have never been more surprised', '["Never have I seen such dedication", "Seldom does she miss a deadline", "Had I known, I would have helped", "I have never been more surprised"]', NULL, NULL, NULL, NULL, '"I have never been more surprised" uses normal word order. The others all use inversion after a negative adverbial or in a conditional without "if".', '2026-04-08 18:26:42.653742+00', NULL, NULL, 'en', '{Grammar,Inversion}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('9be3f513-ab80-45a5-b184-f0a2fe90d715', 802, 'odd_one_out', 'A1', 'animals', 'Three of these are animals you would find on a farm. Which is the odd one out?', 'shark', '["cow", "pig", "shark", "chicken"]', NULL, NULL, NULL, NULL, 'Cows, pigs, and chickens are all common farm animals. A shark lives in the ocean — and if it were on your farm, you would have much bigger problems than collecting eggs.', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{Vocabulary}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('a021d1b9-eeb1-4c3f-b85b-371409cb7375', 1837, 'gap_fill', 'A2', 'spanish', 'Llevamos dos horas _______ el vuelo más barato — hay demasiadas opciones.', 'buscando', NULL, NULL, NULL, NULL, NULL, '"Llevar + gerundio" expresa una acción en progreso con duración desde hace un tiempo.', '2026-04-06 16:43:51.906934+00', NULL, NULL, 'es', '{Spanish}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('7b389454-d087-4b28-b987-e4774101317e', 2116, 'sentence_building', 'C1', 'grammar', 'Solo después de la reunión me di cuenta de mi error.', 'Only after the meeting did I realise my mistake.', '["only", "after", "the", "meeting", "did", "I", "realise", "my", "mistake", "when", "do", "realised"]', NULL, NULL, NULL, NULL, 'Restrictive inversion: after "Only after …" the auxiliary comes before the subject — "did I realise".', '2026-06-01 07:13:28.516357+00', NULL, NULL, 'en', '{Inversion}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('e96d119b-73df-4b2b-8d7a-af932f8ff0fd', 2117, 'sentence_building', 'C1', 'grammar', 'Si no fuera por tu ayuda, habría fracasado.', 'Were it not for your help, I would have failed.', '["were", "it", "not", "for", "your", "help", "I", "would", "have", "failed", "was", "if", "fail"]', NULL, NULL, NULL, NULL, 'Inverted conditional: "Were it not for …" is a formal way of saying "If it weren''t for…".', '2026-06-01 07:13:28.516357+00', NULL, NULL, 'en', '{Conditional}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('bde1e57d-f3a6-4477-9226-489f93adeb98', 2118, 'sentence_building', 'C1', 'grammar', 'Su argumento fue tan convincente que nadie se opuso.', 'So convincing was her argument that nobody objected.', '["so", "convincing", "was", "her", "argument", "that", "nobody", "objected", "such", "were", "object"]', NULL, NULL, NULL, NULL, 'Inversion after "So + adjective": "So convincing was her argument that …".', '2026-06-01 07:13:28.516357+00', NULL, NULL, 'en', '{Inversion}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('11cddc7b-2866-49f9-834f-44fb16f7de39', 2119, 'sentence_building', 'C1', 'grammar', 'No tenían ni idea de lo que se avecinaba.', 'Little did they know what was coming.', '["little", "did", "they", "know", "what", "was", "coming", "do", "knew", "that", "come"]', NULL, NULL, NULL, NULL, 'Negative inversion for dramatic effect: "Little did they know …".', '2026-06-01 07:13:28.516357+00', NULL, NULL, 'en', '{Inversion}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('06f8c23f-09da-479a-ab9a-f6fdb81b983e', 800, 'odd_one_out', 'A1', 'body', 'Three of these are parts of the body. Which is the odd one out?', 'shine', '["shine", "ankle", "knee", "hip"]', NULL, NULL, NULL, NULL, 'Knee, hip, and ankle are all joints of the leg. Shine is the odd one out. The ''shin'' is the front of the leg below the knee and above the ankle, but shine is a verb. ', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{Vocabulary}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('697f5b7f-538d-42f2-9419-9e7475763be8', 1966, 'odd_one_out', 'C2', 'grammar', 'Three of these are examples of litotes. Which is the odd one out?', 'absolutely terrible', '["not bad", "not uncommon", "not without its flaws", "absolutely terrible"]', NULL, NULL, NULL, NULL, '"Absolutely terrible" is a direct emphatic statement. "Not bad", "not uncommon", and "not without its flaws" are all litotes — understatement through negating the opposite.', '2026-04-08 18:26:42.653742+00', NULL, NULL, 'en', '{Grammar,Rhetoric}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('c9ba9d54-5982-45dd-8688-632bcf1a6172', 1967, 'odd_one_out', 'A2', 'spanish', '¿Cuál de estas expresiones NO es un modismo?', 'tomar un taxi', '["estar en las nubes", "tomar el pelo", "meter la pata", "tomar un taxi"]', NULL, NULL, NULL, NULL, '"Tomar un taxi" es completamente literal. "Estar en las nubes" = estar distraído, "tomar el pelo" = burlarse de alguien, "meter la pata" = cometer un error.', '2026-04-08 18:26:42.653742+00', NULL, NULL, 'es', '{Idioms}', true, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('de65af2f-b71f-4ed6-8177-459213636e37', 1968, 'odd_one_out', 'A2', 'spanish', '¿Cuál de estas expresiones NO es un modismo?', 'comer una manzana', '["ponerse las pilas", "costar un ojo de la cara", "no hay mal que por bien no venga", "comer una manzana"]', NULL, NULL, NULL, NULL, '"Comer una manzana" es completamente literal. "Ponerse las pilas" = esforzarse más, "costar un ojo de la cara" = ser muy caro, "no hay mal que por bien no venga" = every cloud has a silver lining.', '2026-04-08 18:26:42.653742+00', NULL, NULL, 'es', '{Idioms}', true, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('cc35ec93-8201-4c82-8394-052ace157c14', 1969, 'odd_one_out', 'A2', 'spanish', '¿Cuál de estas ciudades NO es la capital de su país?', 'Sydney', '["Madrid", "Lisboa", "Sydney", "Berlín"]', NULL, NULL, NULL, NULL, 'La capital de Australia es Canberra, no Sydney. Madrid, Lisboa y Berlín sí son capitales nacionales.', '2026-04-08 18:26:42.653742+00', NULL, NULL, 'es', '{"General Knowledge"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('18c78997-d5aa-4de7-8fd7-f2ed9c6ff283', 1970, 'odd_one_out', 'A2', 'spanish', '¿Cuál de estos animales NO es un mamífero?', 'tiburón', '["delfín", "murciélago", "ballena", "tiburón"]', NULL, NULL, NULL, NULL, 'El tiburón es un pez. Los delfines, las ballenas y los murciélagos son todos mamíferos: respiran aire, son de sangre caliente y alimentan a sus crías con leche.', '2026-04-08 18:26:42.653742+00', NULL, NULL, 'es', '{Nature}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('2d15d540-0e99-40d2-b706-35049b65ba1f', 1469, 'multiple_choice', 'B2', 'phrasal_verbs', 'She''s been _____ a very difficult time since she lost her job.', 'going through', '["going through", "going over", "going along", "going off"]', NULL, NULL, NULL, 'To experience (a difficult time, a process).', 'Go through means to experience a difficult or unpleasant period or situation.', '2026-03-18 20:30:31.624632+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('dac5a8f5-3334-41f9-8146-039b6f2e40d2', 468, 'gap_fill', 'C1', 'advanced_vocabulary', 'She has a ___ knowledge of international law.', 'thorough', NULL, NULL, NULL, NULL, 'Complete, deep knowledge — leaves nothing out.', 'Thorough/comprehensive = very complete and detailed.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{}', false, 'Goes through every detail.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('3b500666-d6d2-4f88-810b-4c0e3803bd29', 1429, 'gap_fill', 'A2', 'spanish', 'Cada mañana me _____ a las siete, me ducho y desayuno antes de salir de casa.', 'levanto', NULL, NULL, NULL, NULL, NULL, 'Levantarse es un verbo reflexivo. En primera persona singular (yo), la forma es me levanto.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'es', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('db4b7dd6-9657-450b-8bf2-39da1ba3fc36', 1021, 'gap_fill', 'C1', 'vocabulary', 'She has a _______ understanding of the political complexities involved in the negotiation.', 'nuanced', NULL, NULL, NULL, '[{"answer": "sophisticated", "feedback": ""}, {"answer": "thorough", "feedback": ""}, {"answer": "deep", "feedback": ""}, {"answer": "complete", "feedback": "✅ ''Complete understanding'' works fine — it means full grasp. The model answer ''nuanced'' specifically emphasises sensitivity to subtle layers and shades of meaning."}]', 'Subtle, sophisticated — appreciating fine details.', 'A nuanced understanding is one that recognises complexity, subtlety, and different shades of meaning — rather than seeing things in simple black and white.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Business vocabulary"}', false, 'From "nuance" — a small distinction.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('a1b2c3d4-0911-0911-0911-000000000911', 911, 'matching', 'A2', 'vocabulary', 'Match each verb with the correct collocation.', 'match_all_pairs', '[{"left": {"type": "text", "content": "make"}, "right": {"type": "text", "content": "a decision"}}, {"left": {"type": "text", "content": "do"}, "right": {"type": "text", "content": "homework"}}, {"left": {"type": "text", "content": "have"}, "right": {"type": "text", "content": "a shower"}}, {"left": {"type": "text", "content": "take"}, "right": {"type": "text", "content": "a photo"}}, {"left": {"type": "text", "content": "go"}, "right": {"type": "text", "content": "shopping"}}]', NULL, NULL, NULL, NULL, NULL, '2026-03-03 15:58:50.696706+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('d7c4fa3d-106b-4ea0-8329-139353946d40', 2090, 'sentence_building', 'A2', 'grammar', NULL, 'She doesn''t work on Sundays.', '["she", "doesn''t", "work", "on", "sundays", "don''t", "works", "at", "weekends"]', NULL, NULL, NULL, NULL, 'Present simple negative for "she": the auxiliary "doesn''t" + base verb "work".', '2026-06-01 07:13:28.516357+00', NULL, NULL, 'en', '{"Auxiliary verb"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('53836d01-ffc9-408f-81f1-0a15afe72950', 1426, 'multiple_choice', 'A2', 'spanish', '¿Cuál es el significado de "madrugar"?', 'levantarse muy temprano', '["levantarse muy temprano", "quedarse dormido", "acostarse tarde", "descansar"]', NULL, NULL, NULL, NULL, 'Madrugar significa levantarse muy temprano por la mañana. Una persona que madruga se llama madrugador/a.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'es', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('07756731-2b03-435d-b743-3339ed761c76', 1427, 'multiple_choice', 'A2', 'spanish', '¿Qué significa "tener sueño"?', 'tener ganas de dormir', '["tener ganas de dormir", "tener un sueño bonito", "dormir bien", "estar descansado"]', NULL, NULL, NULL, NULL, 'Tener sueño significa sentir la necesidad de dormir. Es diferente de "tener un sueño", que significa to have a dream.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'es', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('f167cb6c-991b-433c-9672-e12f88a656fd', 1428, 'multiple_choice', 'A2', 'spanish', '¿Cuál de estas palabras describe a alguien que trabaja mucho?', 'trabajador', '["trabajador", "perezoso", "tranquilo", "aburrido"]', NULL, NULL, NULL, NULL, 'Trabajador/a describe a alguien que trabaja mucho y con esfuerzo. Su opuesto es perezoso/a (lazy).', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'es', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('bf303c0a-e234-4089-8b98-8a56814723a4', 1431, 'multiple_choice', 'A2', 'spanish', '¿Cómo se dice "alarm clock" en español?', 'el despertador', '["el despertador", "el reloj de pared", "el temporizador", "el cronómetro"]', NULL, NULL, NULL, NULL, 'El despertador es el reloj que te despierta por la mañana. El verbo relacionado es despertar/despertarse (to wake up).', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'es', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('e9c030dc-7fb9-481b-82a5-24a9bdf8a6ec', 2319, 'gap_fill', 'C1', 'sport', 'No sooner had the final whistle ___ than the fans erupted.', 'sounded', '[]', NULL, NULL, '[{"answer": "blown", "feedback": "Also accepted — though \"sounded\" reads more naturally with an intransitive whistle."}]', 'Past participle after "had" in this inversion.', 'After "had", we need the past participle: "had … sounded" (or "blown").', '2026-06-01 07:35:54.312658+00', NULL, NULL, 'en', '{Inversion}', false, '"blown" or "sounded".', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('42a0e6cd-b665-4a9f-97dc-ff8179b57656', 1433, 'multiple_choice', 'A2', 'spanish', '¿Qué significa "trasnochar"?', 'quedarse despierto hasta muy tarde', '["quedarse despierto hasta muy tarde", "dormir demasiado", "levantarse muy temprano", "tomar una siesta"]', NULL, NULL, NULL, NULL, 'Trasnochar significa quedarse despierto hasta muy tarde o durante toda la noche. Su opuesto es madrugar.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'es', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('02cef32c-8112-40ad-ac4c-c36c60630713', 1435, 'multiple_choice', 'A2', 'spanish', '¿Cuál es el verbo correcto? "Llevo tres años _____ en esta empresa."', 'trabajando', '["trabajando", "trabaje", "trabajo", "trabajar"]', NULL, NULL, NULL, NULL, 'Con llevar + tiempo, se usa el gerundio: llevo tres años trabajando. Esta estructura equivale a "I have been working here for three years."', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'es', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('076e0bd7-923b-4eeb-9d97-df65bb64e918', 1971, 'odd_one_out', 'A2', 'spanish', '¿Cuál de estas cosas es difícil hacer un lunes por la mañana?', 'sentirte motivado', '["tomar café", "revisar el correo", "sentirte motivado", "mirar el reloj"]', NULL, NULL, NULL, NULL, 'Tomar café, revisar el correo y mirar el reloj cada cinco minutos son actividades perfectamente normales un lunes. Sentirte motivado es el verdadero reto.', '2026-04-08 18:26:42.653742+00', NULL, NULL, 'es', '{Humour}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('b51448ca-cbf6-4cb5-acaf-cdf42794942e', 1972, 'odd_one_out', 'A2', 'spanish', 'Tres de estas palabras en español son cognados del inglés. ¿Cuál NO lo es?', 'perro', '["hotel", "hospital", "música", "perro"]', NULL, NULL, NULL, NULL, '"Perro" (dog) no se parece en nada a su equivalente inglés. "Hotel", "hospital" y "música" son cognados reconocibles en ambos idiomas.', '2026-04-08 18:26:42.653742+00', NULL, NULL, 'es', '{Vocabulary}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('f7b60baf-d962-44bc-b704-2a67ea70a467', 1022, 'gap_fill', 'C2', 'vocabulary', 'The two theories are mutually _______ — accepting one means rejecting the other entirely.', 'exclusive', NULL, NULL, NULL, NULL, 'Cannot both be true — accepting one rejects the other.', 'Mutually exclusive means two things that cannot both be true or accepted at the same time. If you accept one, you must reject the other.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Business vocabulary",Collocation}', false, 'Common phrase: "mutually ___".', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('a1b2c3d4-0912-0912-0912-000000000912', 912, 'matching', 'A2', 'vocabulary', 'Match each job to the correct workplace.', 'match_all_pairs', '[{"left": {"type": "text", "content": "doctor"}, "right": {"type": "text", "content": "hospital"}}, {"left": {"type": "text", "content": "chef"}, "right": {"type": "text", "content": "restaurant"}}, {"left": {"type": "text", "content": "teacher"}, "right": {"type": "text", "content": "school"}}, {"left": {"type": "text", "content": "mechanic"}, "right": {"type": "text", "content": "garage"}}, {"left": {"type": "text", "content": "pilot"}, "right": {"type": "text", "content": "airport"}}]', NULL, NULL, NULL, NULL, NULL, '2026-03-03 15:58:50.696706+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('844aafb8-7ce5-42db-a892-8a830abf6971', 804, 'odd_one_out', 'A2', 'time', 'Three of these are months of the year. Which is the odd one out?', 'Friday', '["January", "Friday", "March", "October"]', NULL, NULL, NULL, NULL, 'January, March, and October are months of the year. Friday is a day of the week. Both useful for making plans — but not the same category!', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{"Time expression"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('b8a14ad0-2d53-42a4-bdb0-b05f52826f5d', 803, 'odd_one_out', 'A1', 'food', 'Three of these are drinks. Which is the odd one out?', 'bread', '["water", "juice", "coffee", "bread"]', NULL, NULL, NULL, NULL, 'Water, juice, and coffee are all things you drink. Bread is a food — you eat it, not drink it (unless you are very, very hungry).', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{Vocabulary}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('1b4c52da-5c97-4b5d-a320-d43a680afc3c', 805, 'odd_one_out', 'A2', 'money', 'Three of these are ways to pay in a shop. Which is the odd one out?', 'receipt', '["cash", "credit card", "contactless", "receipt"]', NULL, NULL, NULL, NULL, 'Cash, credit card, and contactless are all payment methods. A receipt is what you receive after you pay — it''s proof of purchase, not a way to pay.', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{Vocabulary}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('1f6bcaac-8c9e-4caf-8c0f-8f4d17d25499', 806, 'odd_one_out', 'A2', 'feelings', 'Three of these describe how someone feels. Which is the odd one out?', 'tall', '["nervous", "excited", "angry", "tall"]', NULL, NULL, NULL, NULL, 'Nervous, excited, and angry are all emotions — how a person feels. Tall describes physical height, not a feeling. (Though some tall people feel very confident about it!)', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{Vocabulary}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('d30fd080-dea5-4dfd-8a1a-598bd81fc094', 808, 'odd_one_out', 'B1', 'vocabulary', 'Three of these are synonyms for "tired". Which is the odd one out?', 'energetic', '["exhausted", "drained", "weary", "energetic"]', NULL, NULL, NULL, NULL, 'Exhausted, drained, and weary all mean very tired. "Energetic" means full of energy — the complete opposite. Don''t mix them up in your CV!', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('d226bba4-6719-4ec5-b6f6-4d4979d91db0', 809, 'odd_one_out', 'B1', 'vocabulary', 'Three of these describe a confident person. Which is the odd one out?', 'timid', '["assertive", "self-assured", "bold", "timid"]', NULL, NULL, NULL, NULL, 'Assertive, self-assured, and bold all describe someone with confidence. Timid means shy and lacking confidence — the opposite quality.', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('08bb3a22-00ca-45d8-b299-fffe01d13988', 807, 'odd_one_out', 'A2', 'travel', 'Three of these are types of transport. Which is the odd one out?', 'motorway', '["train", "bus", "ferry", "motorway"]', NULL, NULL, NULL, NULL, 'Trains, buses, and ferries are all vehicles — things you travel in. A motorway is a type of road — it is where you travel, not what you travel in.', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{Vocabulary}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('880fc37f-50d0-4c12-8eac-8e6f6d86fba8', 813, 'odd_one_out', 'B2', 'environment', 'Three of these words are connected with the environment. Which is the odd one out?', 'dividend', '["deforestation", "pollution", "flooding", "dividend"]', NULL, NULL, NULL, NULL, 'Deforestation, pollution, and flooding are all environmental issues. A dividend is a payment made to shareholders from a company''s profits — firmly in finance, not ecology.', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{Vocabulary}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('271a17e2-b426-4f01-abe4-a267ee875a15', 680, 'odd_one_out', 'A2', 'house_and_home', 'Which one is NOT a room in a house?', 'garden', '["kitchen", "bedroom", "garden", "bathroom"]', NULL, NULL, NULL, NULL, '"Garden" is outside the house, not a room inside it.', '2026-02-20 19:09:17.848852+00', NULL, NULL, 'en', '{Vocabulary}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('d30abec0-e291-4814-8fdc-93f3460395bb', 2130, 'multiple_choice', 'A2', 'prepositions', 'We usually meet ___ Monday mornings.', 'on', '["on", "in", "at", "by"]', NULL, NULL, NULL, 'For days and dates, English uses one particular little word.', 'We use "on" with days and dates: "on Monday mornings".', '2026-06-01 07:16:29.304337+00', NULL, NULL, 'en', '{"Preposition of time"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('fc663d73-3b07-4add-a79c-9c271a2b8f07', 2131, 'multiple_choice', 'A2', 'prepositions', 'The shop opens ___ 9 o''clock.', 'at', '["at", "on", "in", "to"]', NULL, NULL, NULL, 'For an exact clock time, think of a single point on the day.', 'We use "at" with exact clock times: "at 9 o''clock".', '2026-06-01 07:16:29.304337+00', NULL, NULL, 'en', '{"Preposition of time"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('fa1d6a75-c604-4e3c-bd49-4d9476dfa174', 1973, 'odd_one_out', 'A2', 'spanish', 'Tres de estas frases usan el verbo correcto. ¿Cuál tiene un error?', 'Está médico', '["Estoy cansado", "Está en Madrid", "Está contento", "Está médico"]', NULL, NULL, NULL, NULL, 'La frase correcta es "Es médico". Las profesiones se expresan con "ser". Las otras usan "estar" correctamente: estado temporal, ubicación y estado emocional.', '2026-04-08 18:26:42.653742+00', NULL, NULL, 'es', '{Grammar}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('be9558db-e5e1-4b98-9a98-8b883378e2d7', 1974, 'odd_one_out', 'A2', 'spanish', 'Tres de estas palabras son sinónimos de "pequeño". ¿Cuál es la excepción?', 'enorme', '["diminuto", "minúsculo", "ínfimo", "enorme"]', NULL, NULL, NULL, NULL, '"Enorme" significa muy grande — lo contrario. "Diminuto", "minúsculo" e "ínfimo" son todos sinónimos de pequeño.', '2026-04-08 18:26:42.653742+00', NULL, NULL, 'es', '{Vocabulary}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('08eb3f3d-e8d2-4fb0-bf6d-afa84549b6c9', 1975, 'odd_one_out', 'A2', 'spanish', 'Tres de estas palabras son "falsos amigos". ¿Cuál NO lo es?', 'hotel', '["embarazada", "sensible", "actual", "hotel"]', NULL, NULL, NULL, NULL, '"Hotel" significa lo mismo en ambos idiomas. "Embarazada" = pregnant, "sensible" = sensitive, "actual" = current. ¡Cuidado con los falsos amigos!', '2026-04-08 18:26:42.653742+00', NULL, NULL, 'es', '{Vocabulary}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('d6aa1e96-1a0f-4eff-a888-1990e1d251de', 19, 'gap_fill', 'B2', 'modals_obligation', 'You ___ (not have to / come) to the meeting if you''re too busy.', 'don''t have to come', NULL, '["don''t need to come", "needn''t come"]', NULL, NULL, 'No obligation or necessity', 'Don''t have to means there is no obligation.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{"Modal verb"}', false, '"Don''t have to" = no obligation. Different from "must not"!', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('48a7a006-8481-4c32-b8a8-df1543dd60fb', 20, 'gap_fill', 'B2', 'modals_prohibition', 'You ___ (must not / _ _ _ _) here. It''s a bus stop.', 'must not park', NULL, NULL, NULL, NULL, 'Strong prohibition', 'Must not expresses prohibition.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{"Modal verb"}', false, 'Stronger than "shouldn''t" — there''s a rule against it.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('b2355ece-7965-4828-8750-bd4bc2353ed6', 1976, 'odd_one_out', 'A2', 'spanish', 'Tres de estas palabras pertenecen a la misma familia de palabras. ¿Cuál es la excepción?', 'traje', '["trabajo", "trabajar", "trabajador", "traje"]', NULL, NULL, NULL, NULL, '"Trabajo", "trabajar" y "trabajador" comparten la raíz "trabaj-". "Traje" (suit/outfit) viene del verbo "traer" — no tiene ninguna relación.', '2026-04-08 18:26:42.653742+00', NULL, NULL, 'es', '{Vocabulary,"Word formation"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('9f4d9577-0f45-45ce-b717-9dc334081981', 2132, 'multiple_choice', 'A2', 'prepositions', 'My birthday is ___ July.', 'in', '["in", "on", "at", "by"]', NULL, NULL, NULL, 'For months and years, we use the same word as for big containers of time.', 'We use "in" with months, seasons and years: "in July".', '2026-06-01 07:16:29.304337+00', NULL, NULL, 'en', '{"Preposition of time"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('7170b6e0-34a8-4cc4-9324-20441ecef58a', 2133, 'multiple_choice', 'A2', 'prepositions', 'The cat is hiding ___ the table.', 'under', '["under", "on", "at", "of"]', NULL, NULL, NULL, 'The cat is below it, not on top.', '"Under" means below something: the cat is beneath the table.', '2026-06-01 07:16:29.304337+00', NULL, NULL, 'en', '{"Preposition of place"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('5a89ad85-e499-49fc-9904-ba370b0db05b', 21, 'gap_fill', 'B1', 'comparatives', 'This exercise is ___ (difficult) than the last one.', 'more difficult', NULL, NULL, NULL, NULL, 'Comparative form for long adjectives', 'For adjectives with two or more syllables, use more + adjective.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{Comparative}', false, 'Long adjective (2+ syllables) → "more" + adjective.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('a1b2c3d4-0919-0919-0919-000000000919', 919, 'matching', 'B2', 'grammar', 'Match each linking word to its function.', 'match_all_pairs', '[{"left": {"type": "text", "content": "although"}, "right": {"type": "text", "content": "to show contrast"}}, {"left": {"type": "text", "content": "therefore"}, "right": {"type": "text", "content": "to show result"}}, {"left": {"type": "text", "content": "provided that"}, "right": {"type": "text", "content": "to show condition"}}, {"left": {"type": "text", "content": "in addition"}, "right": {"type": "text", "content": "to add information"}}, {"left": {"type": "text", "content": "in other words"}, "right": {"type": "text", "content": "to clarify or restate"}}]', NULL, NULL, NULL, NULL, NULL, '2026-03-03 19:46:49.927263+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('68964c26-8151-4626-9f11-00000d6b5c2b', 22, 'gap_fill', 'B1', 'comparatives', 'My brother is ___ (tall) than me.', 'taller', NULL, NULL, NULL, NULL, 'Comparative form for short adjectives', 'For short adjectives, add -er to form the comparative.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{Comparative}', false, 'Short adjective (1 syllable) → adjective + "-er".', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('a1b2c3d4-0921-0921-0921-000000000921', 921, 'matching', 'C1', 'vocabulary', 'Match each word to its definition.', 'match_all_pairs', '[{"left": {"type": "text", "content": "exacerbate"}, "right": {"type": "text", "content": "to make a problem worse"}}, {"left": {"type": "text", "content": "mitigate"}, "right": {"type": "text", "content": "to reduce the severity of something"}}, {"left": {"type": "text", "content": "undermine"}, "right": {"type": "text", "content": "to weaken or damage gradually"}}, {"left": {"type": "text", "content": "corroborate"}, "right": {"type": "text", "content": "to confirm or support with evidence"}}, {"left": {"type": "text", "content": "circumvent"}, "right": {"type": "text", "content": "to find a way around a rule or obstacle"}}]', NULL, NULL, NULL, NULL, NULL, '2026-03-03 19:46:49.927263+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('a799d339-d3df-4900-902f-678524bcb91a', 2134, 'multiple_choice', 'A2', 'prepositions', 'She lives ___ Spain.', 'in', '["in", "on", "at", "to"]', NULL, NULL, NULL, 'For countries and cities, think of being inside a large area.', 'We use "in" with countries and cities: "in Spain".', '2026-06-01 07:16:29.304337+00', NULL, NULL, 'en', '{"Preposition of place"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('a1b2c3d4-0922-0922-0922-000000000922', 922, 'matching', 'C1', 'vocabulary', 'Match each formal verb to its neutral equivalent.', 'match_all_pairs', '[{"left": {"type": "text", "content": "commence"}, "right": {"type": "text", "content": "begin"}}, {"left": {"type": "text", "content": "endeavour"}, "right": {"type": "text", "content": "try"}}, {"left": {"type": "text", "content": "terminate"}, "right": {"type": "text", "content": "end"}}, {"left": {"type": "text", "content": "ascertain"}, "right": {"type": "text", "content": "find out"}}, {"left": {"type": "text", "content": "remunerate"}, "right": {"type": "text", "content": "pay"}}]', NULL, NULL, NULL, NULL, NULL, '2026-03-03 19:46:49.927263+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('37c0cab5-cc87-4a80-8785-3e22f1790f65', 2135, 'multiple_choice', 'A2', 'prepositions', 'Put the milk ___ the fridge.', 'in', '["in", "on", "at", "by"]', NULL, NULL, NULL, 'Inside an enclosed space.', '"In" is used for an enclosed space like the inside of a fridge.', '2026-06-01 07:16:29.304337+00', NULL, NULL, 'en', '{"Preposition of place"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('36f3ce4a-7aed-4664-9630-1f041658c309', 24, 'gap_fill', 'B2', 'superlatives', 'She''s ___ (intelligent) person in our class.', 'the most intelligent', NULL, NULL, NULL, NULL, 'Superlative form for long adjectives', 'For long adjectives, use the most + adjective.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{Superlative}', false, 'Long adjective (3+ syllables) → "the most" + adjective.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('ed55b121-f4fa-4bbb-a316-c64f9550d966', 25, 'gap_fill', 'B1', 'used_to', 'I ___ (use to / verb) tennis every weekend, but now I prefer swimming.', 'used to play', NULL, NULL, NULL, NULL, 'Past habit that is no longer true', 'Used to + infinitive describes past habits or states that are no longer true.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{"Past tense"}', false, 'Form: used to + infinitive.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('cef75ed9-8a09-49c0-9826-ef8a0aaf22c1', 26, 'gap_fill', 'B2', 'be_used_to', 'Don''t worry about the noise. I ___ (be used to / live) in the city centre.', 'am used to living', NULL, NULL, NULL, NULL, 'Be used to + -ing means accustomed to', 'Be used to + -ing means you are accustomed to something.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{"Past tense"}', false, 'Different from "used to" (past habit). This is about present feelings — accustomed to.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('c0b7b387-3be5-44fb-8207-d3aed45ed99e', 28, 'gap_fill', 'B2', 'relative_clauses', 'That''s the man ___ (who / that) wife works with my sister.', 'whose', NULL, NULL, NULL, NULL, 'Possessive relative pronoun', 'Whose is used to show possession in relative clauses.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{"Relative clause"}', false, 'Not "who''s" — this shows possession.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('82efd48f-cd8d-4c78-bd98-df00b342cecf', 29, 'gap_fill', 'B1', 'questions', '___ (how _ _ _ _ ) have you been learning English?', 'how long', NULL, NULL, NULL, NULL, 'Question word for duration', 'How long asks about the duration of time.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{"Question form"}', false, 'The answer would be a length of time (5 years, 2 weeks).', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('6519b842-ba8a-4a65-9e40-7b8d73163376', 30, 'gap_fill', 'B1', 'questions', '___ (what _ _ _ _ ) does the train leave?', 'what time', NULL, NULL, NULL, NULL, 'Question phrase for asking about time', 'What time is used to ask about specific times.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{"Question form"}', false, 'The answer would be a clock time, like "8pm".', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('c0dd33ea-cd68-44bb-a6b3-cb742feea2e4', 540, 'multiple_choice', 'C2', 'idioms', 'He let the cat out of the ___ about the surprise party.', 'bag', '["house", "box", "bag", "hat"]', NULL, NULL, NULL, 'To reveal a secret — an idiom about cats and containers.', 'Let the cat out of the bag = reveal a secret accidentally.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Fixed expression"}', true, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('26707361-68a0-4e13-9331-2a8e1fb0c41a', 546, 'multiple_choice', 'C1', 'confusing_words', 'The new law will ___ everyone equally.', 'affect', '["inflict", "infect", "effect", "affect"]', NULL, NULL, NULL, 'Verb form — to have an impact on. (Don''t confuse with the noun "effect".)', 'Affect (verb) = influence. Effect (noun) = result. Common confusion.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Confusable words"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('1da8949c-ab8d-429a-816c-4f5334aef738', 547, 'multiple_choice', 'C1', 'confusing_words', 'I would strongly ___ against making any hasty decisions.', 'advise', '["device", "advise", "devise", "advice"]', NULL, NULL, NULL, 'Verb form (with -s). The noun is "advice" (with -c).', 'Advise (verb) = give advice. Advice (noun) = the recommendation itself.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Confusable words"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('a1b2c3d4-0923-0923-0923-000000000923', 923, 'matching', 'C1', 'vocabulary', 'Match each word to its definition.', 'match_all_pairs', '[{"left": {"type": "text", "content": "pragmatic"}, "right": {"type": "text", "content": "focused on practical results rather than theory"}}, {"left": {"type": "text", "content": "ambivalent"}, "right": {"type": "text", "content": "having mixed or contradictory feelings"}}, {"left": {"type": "text", "content": "tenuous"}, "right": {"type": "text", "content": "weak or unconvincing"}}, {"left": {"type": "text", "content": "nuanced"}, "right": {"type": "text", "content": "having subtle distinctions"}}, {"left": {"type": "text", "content": "pervasive"}, "right": {"type": "text", "content": "spreading widely through something"}}]', NULL, NULL, NULL, NULL, NULL, '2026-03-03 19:46:49.927263+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('a1b2c3d4-0924-0924-0924-000000000924', 924, 'matching', 'C2', 'vocabulary', 'Match each word to its definition.', 'match_all_pairs', '[{"left": {"type": "text", "content": "obfuscate"}, "right": {"type": "text", "content": "to make something unclear or confusing"}}, {"left": {"type": "text", "content": "vacillate"}, "right": {"type": "text", "content": "to waver between different opinions"}}, {"left": {"type": "text", "content": "inveterate"}, "right": {"type": "text", "content": "having a habit too firmly established to change"}}, {"left": {"type": "text", "content": "perfidious"}, "right": {"type": "text", "content": "deceitful and untrustworthy"}}, {"left": {"type": "text", "content": "pellucid"}, "right": {"type": "text", "content": "transparently clear and easy to understand"}}]', NULL, NULL, NULL, NULL, NULL, '2026-03-03 19:46:49.927263+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('a1b2c3d4-0925-0925-0925-000000000925', 925, 'matching', 'C2', 'vocabulary', 'Match each expression to its meaning.', 'match_all_pairs', '[{"left": {"type": "text", "content": "a foregone conclusion"}, "right": {"type": "text", "content": "a result that seems certain before it happens"}}, {"left": {"type": "text", "content": "to split hairs"}, "right": {"type": "text", "content": "to focus on trivial distinctions"}}, {"left": {"type": "text", "content": "to beg the question"}, "right": {"type": "text", "content": "to assume the truth of what you are trying to prove"}}, {"left": {"type": "text", "content": "a double-edged sword"}, "right": {"type": "text", "content": "something with both advantages and disadvantages"}}, {"left": {"type": "text", "content": "to take something at face value"}, "right": {"type": "text", "content": "to accept something without questioning it further"}}]', NULL, NULL, NULL, NULL, NULL, '2026-03-03 19:46:49.927263+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('e588dfe5-460b-4119-ab93-0b1aef975411', 735, 'sentence_auction', 'B1', 'grammar', 'Theme: Present Perfect vs Past Simple', 'auction', '[{"correct": false, "sentence": "I have seen that film last week.", "explanation": "Wrong — use Past Simple with a finished time reference. It should be: \"I saw that film last week.\""}, {"correct": true, "sentence": "She has never been to New York.", "explanation": "Correct! Present Perfect used with \"never\" to describe a life experience — no specific time given."}, {"correct": false, "sentence": "We have finished the report yesterday.", "explanation": "Wrong — \"yesterday\" is a finished time reference, so Past Simple is needed: \"We finished the report yesterday.\""}, {"correct": true, "sentence": "Have you ever tried sushi?", "explanation": "Correct! Present Perfect with \"ever\" asking about a life experience."}, {"correct": false, "sentence": "He worked here since 2019.", "explanation": "Wrong — \"since\" requires Present Perfect: \"He has worked here since 2019.\""}, {"correct": true, "sentence": "They left the office an hour ago.", "explanation": "Correct! Past Simple with \"ago\" — a finished, specific time reference."}]', NULL, NULL, NULL, NULL, NULL, '2026-02-25 20:33:02.6411+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('f0e53da4-2b8d-44e1-a216-b87e11c87f03', 812, 'odd_one_out', 'B2', 'register', 'Three of these are words typical of formal or academic writing. Which is the odd one out?', 'gonna', '["hereby", "notwithstanding", "furthermore", "gonna"]', NULL, NULL, NULL, NULL, '"Hereby", "notwithstanding", and "furthermore" are all formal connectors and phrases. "Gonna" is very informal spoken English — it would raise a few eyebrows in a legal document.', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{"Academic English"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('82263a7e-fd49-4c1e-b07e-7b5f55ab1a1b', 810, 'odd_one_out', 'B2', 'business', 'Three of these are types of employment contract. Which is the odd one out?', 'invoice', '["permanent", "temporary", "freelance", "invoice"]', NULL, NULL, NULL, NULL, 'Permanent, temporary, and freelance are all types of work arrangement. An invoice is a document requesting payment — important in business, but it is not a type of contract.', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{"Business vocabulary"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('94b94b72-6fba-4dd4-961e-de69da9faeb1', 2136, 'multiple_choice', 'A2', 'prepositions', 'I''ll see you ___ the weekend.', 'at', '["at", "on", "in", "for"]', NULL, NULL, NULL, 'British English uses this word with "the weekend".', 'British English uses "at the weekend"; American English prefers "on the weekend".', '2026-06-01 07:16:29.304337+00', NULL, NULL, 'en', '{"Preposition of time"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('b3ca0641-e44e-43eb-8fc4-9c0b0bd1a694', 2138, 'multiple_choice', 'A2', 'prepositions', 'We travelled ___ train to Madrid.', 'by', '["by", "on", "with", "in"]', NULL, NULL, NULL, 'For methods of transport, we use this word: ___ train, ___ car, ___ plane.', 'We use "by" for means of transport: "by train", "by car", "by plane".', '2026-06-01 07:16:29.304337+00', NULL, NULL, 'en', '{Preposition}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('b613c51b-9057-4d7e-b78a-e7d606e84060', 2139, 'multiple_choice', 'A2', 'prepositions', 'He''s waiting ___ the bus stop.', 'at', '["at", "in", "on", "to"]', NULL, NULL, NULL, 'A specific point or spot.', 'We use "at" for a specific point or place: "at the bus stop".', '2026-06-01 07:16:29.304337+00', NULL, NULL, 'en', '{"Preposition of place"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('7f2fccb9-f3c5-4289-b737-1cd38d565733', 736, 'sentence_auction', 'B2', 'grammar', 'Theme: Prepositions', 'auction', '[{"correct": false, "sentence": "She is very good in mathematics.", "explanation": "Wrong — the correct preposition is \"at\": \"She is very good at mathematics.\""}, {"correct": true, "sentence": "He depends on his parents for money.", "explanation": "Correct! \"Depend on\" is the right collocation."}, {"correct": false, "sentence": "I am not interested about your opinion.", "explanation": "Wrong — it should be \"interested in\": \"I am not interested in your opinion.\""}, {"correct": true, "sentence": "We need to concentrate on the main issues.", "explanation": "Correct! \"Concentrate on\" is the right collocation."}, {"correct": false, "sentence": "She is married with a doctor.", "explanation": "Wrong — it should be \"married to\": \"She is married to a doctor.\""}]', NULL, NULL, NULL, NULL, NULL, '2026-02-25 20:33:15.162556+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('60f205f4-6b60-4d89-be60-f70d5f74a5c9', 2140, 'gap_fill', 'B2', 'prepositions', 'She''s very good ___ solving problems.', 'at', '[]', NULL, NULL, NULL, 'Which preposition follows "good" when we talk about a skill?', '"Good at" is a fixed pairing for talking about a skill or ability.', '2026-06-01 07:16:29.304337+00', NULL, NULL, 'en', '{Preposition}', false, 'Two letters.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('099d6261-6c66-4c4a-8dc1-d801b551911f', 1213, 'sentence_building', 'C2', 'routines', 'Los hábitos formados en la infancia temprana suelen ser extraordinariamente resistentes al cambio.', 'Habits formed early in childhood are often remarkably resistant to change.', '["habits", "formed", "early", "in", "childhood", "are", "often", "remarkably", "resistant", "to", "change", "made", "very", "difficult", "overcome", "adulthood"]', NULL, NULL, NULL, NULL, 'Formed is a past participle acting as a reduced relative clause (= habits that are formed). Resistant to is the correct collocation.', '2026-03-16 09:04:17.945706+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('44ab9fed-2126-48b9-9c75-88b23176782c', 815, 'odd_one_out', 'B2', 'phrasal verbs', 'Three of these phrasal verbs mean to "postpone". Which is the odd one out?', 'call off', '["put off", "push back", "hold off", "call off"]', NULL, NULL, NULL, NULL, '"Put off", "push back", and "hold off" can all mean to delay something. "Call off" means to cancel entirely — a stronger and different action. Don''t postpone — cancel!', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{"Phrasal verb"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('54cf7faa-974f-40b5-9d4f-637da94cb83a', 814, 'odd_one_out', 'B2', 'academic writing', 'Three of these are reporting verbs. Which is the odd one out?', 'wonder', '["claim", "state", "argue", "wonder"]', NULL, NULL, NULL, NULL, '"Claim", "state", and "argue" are all reporting verbs used to introduce someone else''s words or ideas. "Wonder" expresses a personal thought or question — it does not report what someone said.', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{"Academic English"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('e9453fac-dadb-4c53-a5a2-0d8ec7f40b2c', 816, 'odd_one_out', 'B2', 'vocabulary', 'Three of these words describe something uncertain or unclear. Which is the odd one out?', 'categorical', '["vague", "ambiguous", "obscure", "categorical"]', NULL, NULL, NULL, NULL, '"Vague", "ambiguous", and "obscure" all mean unclear or difficult to understand. "Categorical" means clear, definite, and absolute — the complete opposite.', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('ccabca27-b3bf-42e3-8bb4-e9b449f026a0', 838, 'error_correction', 'B2', 'grammar', 'She is used to work late on Fridays.', 'She is used to working late on Fridays.', '[]', NULL, NULL, NULL, NULL, '"Be used to" is always followed by the -ing form: "She is used to working late." Compare with "used to + infinitive" for past habits: "She used to work there." Very different meanings from small differences in grammar.', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('aed19c47-2760-4be0-9885-66e949c813d4', 737, 'sentence_auction', 'C1', 'grammar', 'Theme: Articles (a / an / the / zero article)', 'auction', '[{"correct": false, "sentence": "The life is full of surprises.", "explanation": "Wrong — no article needed with abstract nouns used in a general sense: \"Life is full of surprises.\""}, {"correct": true, "sentence": "She plays the piano beautifully.", "explanation": "Correct! We use \"the\" with musical instruments."}, {"correct": false, "sentence": "He was sent to the prison for fraud.", "explanation": "Wrong — \"prison\" used institutionally takes zero article: \"He was sent to prison for fraud.\""}, {"correct": true, "sentence": "I had a most enjoyable evening.", "explanation": "Correct! \"A\" can be used before superlatives in exclamatory expressions."}, {"correct": false, "sentence": "The unemployment is rising in many countries.", "explanation": "Wrong — abstract nouns used generally take zero article: \"Unemployment is rising in many countries.\""}, {"correct": true, "sentence": "He arrived home late and went straight to bed.", "explanation": "Correct! \"Home\" and \"bed\" in these expressions take zero article."}]', NULL, NULL, NULL, NULL, NULL, '2026-02-25 20:33:34.312863+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('782dab47-3a4d-4a8d-8928-7f7dc5031ff8', 819, 'odd_one_out', 'C1', 'academic language', 'Three of these are associated with logic and formal reasoning. Which is the odd one out?', 'rhetoric', '["premise", "syllogism", "inference", "rhetoric"]', NULL, NULL, NULL, NULL, 'A premise, syllogism, and inference are all elements of logical argument. Rhetoric is the art of persuasive language — it may use logic, but its primary focus is effect, not strict reasoning.', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{"Academic English"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('eece4035-eff7-493e-8981-ab10c441e6bf', 821, 'odd_one_out', 'C1', 'vocabulary', 'Three of these describe a person who avoids clear commitment. Which is the odd one out?', 'decisive', '["evasive", "noncommittal", "equivocal", "decisive"]', NULL, NULL, NULL, NULL, '"Evasive", "noncommittal", and "equivocal" all describe someone who avoids giving clear answers or making clear choices. "Decisive" means someone who makes clear, confident decisions — the total opposite.', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('666f33b1-0d25-47d5-9e30-e19d4bd39629', 1977, 'sentence_building', 'A1', 'travel', 'Necesito un taxi al aeropuerto.', 'I need a taxi to the airport.', '["I", "need", "a", "taxi", "to", "the", "airport", "want", "bus", "from", "hotel"]', NULL, NULL, NULL, NULL, 'Use "to the airport" for direction of travel. "I need + noun" is a simple, direct way to express necessity.', '2026-04-13 09:19:30.039983+00', NULL, NULL, 'en', '{Travel}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('aba57a01-04aa-43ca-8fa8-35f8f515118a', 825, 'odd_one_out', 'C1', 'vocabulary', 'Three of these words suggest something is not quite right or dishonest. Which is the odd one out?', 'categorical', '["dubious", "suspect", "questionable", "categorical"]', NULL, NULL, NULL, NULL, '"Dubious", "suspect", and "questionable" all cast doubt on something''s honesty or validity. "Categorical" means absolute and clear — no doubt at all.', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('6a95762d-f81f-4f83-84f0-a4975b766cba', 822, 'odd_one_out', 'C2', 'linguistics', 'Three of these are related to linguistics. Which is the odd one out?', 'theorem', '["morpheme", "phoneme", "lexeme", "theorem"]', NULL, NULL, NULL, NULL, 'A morpheme (smallest unit of meaning), phoneme (unit of sound), and lexeme (unit of vocabulary) are all linguistic terms. A theorem is a proven mathematical or logical statement — different field entirely.', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{"Academic English"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('c1632c14-7596-41b8-8020-d346618e5bdb', 823, 'odd_one_out', 'C2', 'language/rhetoric', 'Three of these are rhetorical devices. Which is the odd one out?', 'ellipsis', '["hyperbole", "anaphora", "euphemism", "ellipsis"]', NULL, NULL, NULL, NULL, 'Hyperbole (exaggeration), anaphora (repetition at the start of clauses), and euphemism (polite substitution for something unpleasant) are rhetorical/stylistic devices. Ellipsis is primarily a grammatical and punctuation term — the omission of words or the three dots (...).', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{"Academic English"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('7196a9f6-a967-480b-85f1-eb2b985b375b', 1145, 'odd_one_out', 'A1', 'vocabulary', 'Which of these is NOT an insect?', 'spider', '["ant", "butterfly", "spider", "bee"]', NULL, NULL, NULL, NULL, 'A spider is an arachnid, not an insect. Insects have six legs and three body parts. Spiders have eight legs and two body parts.', '2026-03-16 08:29:27.085219+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('42210fc1-abb4-4610-b1b2-739993511b72', 1214, 'sentence_building', 'C1', 'routines', 'Ha convertido la atención plena en una parte innegociable de su rutina diaria.', 'She has made mindfulness a non-negotiable part of her daily routine.', '["she", "has", "made", "mindfulness", "a", "non-negotiable", "part", "of", "her", "daily", "routine", "essential", "practice", "fixed", "important", "meditation"]', NULL, NULL, NULL, NULL, 'Make + object + noun phrase (SVOC) expresses transformation: she has turned mindfulness into a fixed part of her routine.', '2026-03-16 09:04:17.945706+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('e028634c-56ee-4e11-a4dd-250023f3bc93', 1215, 'sentence_building', 'A2', 'spanish', 'I normally have breakfast at eight in the morning.', 'Normalmente desayuno a las ocho de la mañana.', '["normalmente", "desayuno", "a", "las", "ocho", "de", "la", "mañana", "como", "siete", "tarde"]', NULL, NULL, NULL, NULL, 'Desayunar means to have breakfast. A las ocho means at eight o''clock. De la mañana means in the morning.', '2026-03-16 09:04:17.945706+00', NULL, NULL, 'es', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('53323794-0904-45c8-8a7b-c9a124ea9d32', 1216, 'sentence_building', 'A2', 'spanish', 'She always brushes her teeth before going to bed.', 'Ella siempre se cepilla los dientes antes de acostarse.', '["ella", "siempre", "se", "cepilla", "los", "dientes", "antes", "de", "acostarse", "después", "lavarse", "dormir"]', NULL, NULL, NULL, NULL, 'Cepillarse los dientes is a reflexive verb phrase. Antes de + infinitive means before doing something.', '2026-03-16 09:04:17.945706+00', NULL, NULL, 'es', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('30cd8854-87ba-4350-91cb-5dce239ec102', 1217, 'sentence_building', 'A2', 'spanish', 'We go for a walk every Sunday morning.', 'Damos un paseo todos los domingos por la mañana.', '["damos", "un", "paseo", "todos", "los", "domingos", "por", "la", "mañana", "caminamos", "sábados", "tarde"]', NULL, NULL, NULL, NULL, 'Dar un paseo is the fixed expression for to go for a walk. Por la mañana means in the morning.', '2026-03-16 09:04:17.945706+00', NULL, NULL, 'es', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('1fa32306-0ec6-4dd7-8012-468e3a675b43', 830, 'error_correction', 'A1', 'grammar', 'He have a new car.', 'He has a new car.', '[]', NULL, NULL, NULL, NULL, 'With he, she, or it, we use "has", not "have". He has a new car. ', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('d7c80cac-f607-4913-91b3-ef1feddbd3ff', 1470, 'multiple_choice', 'B2', 'phrasal_verbs', 'We need to _____ some money each month for the holiday.', 'set aside', '["set aside", "set up", "set off", "set out"]', NULL, NULL, NULL, 'To reserve (money, time) for a specific purpose.', 'Set aside means to reserve time, money, or resources for a specific purpose.', '2026-03-18 20:30:31.624632+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('bdd11698-96cc-49a8-b25f-9c9b28244fa1', 827, 'odd_one_out', 'C2', 'academic vocabulary', 'Three of these are economic concepts. Which is the odd one out?', 'jurisprudence', '["stagflation", "quantitative easing", "deflation", "jurisprudence"]', NULL, NULL, NULL, NULL, 'Stagflation (stagnation + inflation), quantitative easing (central bank asset purchasing), and deflation (falling prices) are all economic concepts. Jurisprudence is the theory and philosophy of law — different field.', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{"Academic English"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('f7ea256f-ec0c-4035-ba6d-605d5ab00bc9', 1147, 'odd_one_out', 'A2', 'vocabulary', 'Which of these is NOT a fruit?', 'parsnip', '["apple", "banana", "parsnip", "mango"]', NULL, NULL, NULL, NULL, 'Fruits develop from the flower of a plant and contain seeds. Parsnips are roots.', '2026-03-16 08:29:27.085219+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('4e4f7eec-2b8d-4206-9133-5616fa549e1e', 1219, 'sentence_building', 'A2', 'spanish', 'I usually read for a while before falling asleep.', 'Normalmente leo un rato antes de quedarme dormido.', '["normalmente", "leo", "un", "rato", "antes", "de", "quedarme", "dormido", "después", "dormir", "siempre"]', NULL, NULL, NULL, NULL, 'Quedarse dormido means to fall asleep. Antes de + infinitive means before doing something. Un rato means a while.', '2026-03-16 09:04:17.945706+00', NULL, NULL, 'es', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('a30bd0bb-1e3a-4f0e-81f5-0388f69134dd', 1220, 'sentence_building', 'A2', 'spanish', 'My mother makes coffee every morning without fail.', 'Mi madre hace café todas las mañanas sin falta.', '["mi", "madre", "hace", "café", "todas", "las", "mañanas", "sin", "falta", "padre", "toma", "noches"]', NULL, NULL, NULL, NULL, 'Sin falta means without fail or without exception. Todas las mañanas means every morning.', '2026-03-16 09:04:17.945706+00', NULL, NULL, 'es', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('a116c346-3eea-4264-ac8b-e825b7051eb2', 1221, 'sentence_building', 'A2', 'spanish', 'They usually have dinner at nine o''clock.', 'Normalmente cenan a las nueve.', '["normalmente", "cenan", "a", "las", "nueve", "comen", "siete", "tarde", "siempre"]', NULL, NULL, NULL, NULL, 'Cenar means to have dinner. The third person plural form is cenan. A las nueve means at nine o''clock.', '2026-03-16 09:04:17.945706+00', NULL, NULL, 'es', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('51853a7f-8416-480a-bb2b-bc1cb16bb8a4', 1222, 'sentence_building', 'A2', 'spanish', 'I try to go to the gym three times a week.', 'Intento ir al gimnasio tres veces a la semana.', '["intento", "ir", "al", "gimnasio", "tres", "veces", "a", "la", "semana", "voy", "dos", "mes"]', NULL, NULL, NULL, NULL, 'Intentar + infinitive means to try to do something. Al is a contraction of a + el. Tres veces a la semana means three times a week.', '2026-03-16 09:04:17.945706+00', NULL, NULL, 'es', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('6f5c8d4d-361b-4db4-825c-c60a015dd747', 1223, 'sentence_building', 'A2', 'spanish', 'She gets up early even on weekends.', 'Ella se levanta temprano incluso los fines de semana.', '["ella", "se", "levanta", "temprano", "incluso", "los", "fines", "de", "semana", "tarde", "siempre", "días"]', NULL, NULL, NULL, NULL, 'Levantarse is the reflexive verb meaning to get up. Incluso means even. Los fines de semana means at weekends.', '2026-03-16 09:04:17.945706+00', NULL, NULL, 'es', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('7db1304f-e099-4a82-a91c-0ac6c3ea984c', 2141, 'gap_fill', 'B2', 'prepositions', 'They accused him ___ stealing the money.', 'of', '[]', NULL, NULL, NULL, 'The fixed pattern is "accuse somebody ___ something".', 'The fixed pattern is "accuse somebody of (doing) something".', '2026-06-01 07:16:29.304337+00', NULL, NULL, 'en', '{Preposition}', false, 'Two letters.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('4eb66a4a-0fc7-4519-82d8-d7c9fc14806b', 1224, 'sentence_building', 'A2', 'spanish', 'I check my phone first thing every morning.', 'Miro el móvil nada más levantarme cada mañana.', '["miro", "el", "móvil", "nada", "más", "levantarme", "cada", "mañana", "veo", "despertarme", "tarde", "siempre"]', NULL, NULL, NULL, NULL, 'Nada más + infinitive means as soon as or right after. Móvil is the Spanish word for mobile phone.', '2026-03-16 09:04:17.945706+00', NULL, NULL, 'es', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('58f203b2-e7dc-40fb-aeb2-91d40af8e155', 644, 'sentence_building', 'A1', 'family', 'Tengo un hermano y una hermana.', 'I have a brother and a sister', '["I", "have", "a", "brother", "and", "a", "sister", "the", "has"]', NULL, NULL, NULL, NULL, 'Tener = to have. Use "a" before singular family members.', '2026-02-17 09:58:54.170896+00', NULL, NULL, 'en', '{Vocabulary}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('c6a62f3e-3e7d-41e5-aca0-fe205323c1cc', 667, 'sentence_building', 'C2', 'formal_register', '', 'were it not for the generous support of our sponsors this event would never have taken place', '["were", "it", "not", "for", "the", "generous", "support", "of", "our", "sponsors", "this", "event", "would", "never", "have", "taken", "place", "did", "took", "been"]', NULL, NULL, NULL, NULL, 'Were it not for: formal inverted conditional meaning "If it were not for".', '2026-02-17 09:58:54.170896+00', NULL, NULL, 'en', '{"Formal register"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('a1907ffa-9f00-4748-9393-a8632361748d', 634, 'sentence_building', 'A2', 'question_forms', '', 'what time does the shop open', '["what", "time", "does", "the", "shop", "open", "is", "do"]', NULL, NULL, NULL, NULL, 'For questions about time with he/she/it subjects, use: What time + does + subject + verb.', '2026-02-13 08:00:10.850224+00', NULL, NULL, 'en', '{"Question form"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('843f42e2-c8ce-4229-ab61-5e1db6b4f8de', 641, 'sentence_building', 'A1', 'present_simple', '', 'I go to work every day', '["I", "go", "to", "work", "every", "day", "night", "goes"]', '["every day I go to work."]', 'If you put the time phrase at the end it is more natural.', NULL, NULL, 'Simple present routine: subject + verb + place + time expression.', '2026-02-17 09:58:54.170896+00', NULL, NULL, 'en', '{"Present tense"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('3f9b060e-49f5-41a0-9923-a4df59887572', 832, 'error_correction', 'A1', 'grammar', 'She goed to school by bus yesterday.', 'She went to school by bus yesterday.', '["She goes to school by bus."]', NULL, NULL, NULL, NULL, '"Go" is an irregular verb. Past simple = "went", not "goed".', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('3d6c9111-51b1-41f4-b685-a3e82ddb0d48', 1978, 'sentence_building', 'A1', 'travel', '¿Dónde está el mostrador de facturación?', 'Where is the check-in desk?', '["where", "is", "the", "check-in", "desk", "are", "gate", "counter", "boarding"]', NULL, NULL, NULL, NULL, '"Where is + the + noun?" asks about the location of something specific. The check-in desk is where you register before your flight.', '2026-04-13 09:19:30.039983+00', NULL, NULL, 'en', '{Travel}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('a32a64a2-91dd-4e69-a701-a0d47fe63f35', 1979, 'sentence_building', 'A2', 'travel', 'Mi maleta es demasiado pesada.', 'My bag is too heavy.', '["my", "bag", "is", "too", "heavy", "suitcase", "very", "big", "light"]', NULL, NULL, NULL, NULL, '"Too + adjective" means more than is allowed or acceptable. "Very heavy" is just a description; "too heavy" signals a problem.', '2026-04-13 09:19:30.039983+00', NULL, NULL, 'en', '{Travel}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('90aa0d46-0228-4eca-885a-a9aecc7deb57', 1980, 'sentence_building', 'A1', 'travel', 'Tengo un asiento de ventanilla.', 'I have a window seat.', '["I", "have", "a", "window", "seat", "got", "aisle", "ticket", "place"]', NULL, NULL, NULL, NULL, 'A window seat is beside the window. The opposite is an aisle seat, next to the corridor.', '2026-04-13 09:19:30.039983+00', NULL, NULL, 'en', '{Travel}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('cc508ab3-8552-44df-9d67-ac057b52fb4b', 739, 'multiple_choice', 'A1', 'food', 'Which of these is a fruit?', 'mango', '["carrot", "onion", "mango", "potato"]', NULL, NULL, NULL, 'A tropical sweet fruit with orange-yellow flesh.', 'A mango is a fruit — sweet and delicious. The others are vegetables.', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{Vocabulary}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('3acc6fa5-61dc-4911-b14b-441c82727cb5', 210, 'gap_fill', 'A1', 'present_simple', 'She ___ (watch) TV every evening.', 'watches', NULL, NULL, NULL, NULL, 'Verbs ending in -ch take -es in 3rd person.', 'Verbs ending in -ch: add -es for third person.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Present tense"}', false, 'Watch → watches. (Same pattern: catch → catches.)', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('29c29c3a-0067-4f02-86be-485eaab0ea6a', 618, 'sentence_building', 'B1', 'present_perfect', NULL, 'I have never been to Scotland but I would love to go', '["I", "have", "never", "been", "to", "Scotland", "but", "I", "would", "love", "to", "go", "always", "hate", "from"]', NULL, NULL, NULL, NULL, 'Present perfect for life experience (have never been) + "would love to" for desire. "Been to" = visited.', '2026-02-12 14:34:46.611844+00', NULL, NULL, 'en', '{"Present tense"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('05465e73-3ebf-4edc-bc76-7d338ed55588', 1231, 'multiple_choice', 'A1', 'business_phrasal_verbs', 'She _____ the sales report to her manager every Friday.', 'sends off', '["sends off", "sends over", "sends up", "sends out"]', NULL, NULL, NULL, 'To dispatch — same verb as "send off a letter".', 'Send off means to send something to someone, often formally. Send out is also possible but send off implies dispatching something specific.', '2026-03-18 19:58:52.376507+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('e2383405-4c2e-4d30-956b-d43bc27753ca', 1153, 'odd_one_out', 'A2', 'vocabulary', 'Which of these is NOT a sport?', 'chess', '["football", "swimming", "chess", "tennis"]', NULL, NULL, NULL, NULL, 'Chess is a board game, not usually considered a sport — though this is debated! (I think it is a sport...) Football, swimming, and tennis all involve physical activity and are universally recognised as sports.', '2026-03-16 08:29:27.085219+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('451c47e3-eea2-48ca-a1f3-06d37979b29c', 604, 'sentence_building', 'B2', 'polite_requests', 'Me gustaría solicitar un día libre la semana que viene.', 'I would like to request a day off next week', '["I", "would", "like", "to", "request", "a", "day", "off", "next", "week", "want", "free", "this"]', NULL, NULL, NULL, NULL, '"Would like to request" is the polite formal structure. "A day off" = un día libre. "Free" is a false friend — we say "day off", not "free day".', '2026-02-12 15:08:31.507807+00', NULL, NULL, 'en', '{"Making suggestions"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('4c856d2d-e211-469a-9e3e-4e7eadb157fb', 2142, 'gap_fill', 'B2', 'prepositions', 'I''m not interested ___ politics at all.', 'in', '[]', NULL, NULL, NULL, '"interested ___ a subject" takes a fixed preposition.', '"Interested in" is a fixed adjective + preposition pairing.', '2026-06-01 07:16:29.304337+00', NULL, NULL, 'en', '{Preposition}', false, 'Two letters.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('1a995a8c-d33a-4f51-8f99-9081f9cd9cf0', 642, 'sentence_building', 'A1', 'present_simple', '', 'she likes drinking coffee in the morning', '["she", "likes", "drinking", "coffee", "in", "the", "morning", "liking", "at"]', '["in the morning she likes drinking coffee."]', 'If you put the time phrase at the end it is more natural.', NULL, NULL, 'Present simple with gerund: She likes + -ing form.', '2026-02-17 09:58:54.170896+00', NULL, NULL, 'en', '{"Present tense"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('6e8832f3-53f2-417a-b552-a3c0337eb89b', 635, 'sentence_building', 'A2', 'present_simple', '', 'my sister lives in a small town', '["my", "sister", "lives", "in", "a", "small", "town", "is", "the"]', NULL, NULL, NULL, NULL, 'In present simple, ''she lives'' takes -s. Adjectives go before the noun: ''a small town'' not ''a town small''.', '2026-02-13 08:00:10.850224+00', NULL, NULL, 'en', '{"Present tense"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('aba73cd8-605b-4046-bb73-1d15c3793afc', 629, 'sentence_building', 'A2', 'present_simple', 'Siempre desayuno a las ocho.', 'I always have breakfast at eight', '["I", "always", "have", "breakfast", "at", "eight", "eat", "the"]', NULL, NULL, '["I have breakfast at eight ."]', NULL, 'Adverbs of frequency (always, usually, never) go before the main verb. ''I always have breakfast'' not ''I have always breakfast''.', '2026-02-13 08:00:10.850224+00', NULL, NULL, 'en', '{"Present tense"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('80e10461-daf9-446f-95bd-e1065f08257b', 639, 'sentence_building', 'A2', 'present_continuous', '', 'she is wearing a red dress', '["she", "is", "wearing", "a", "red", "dress", "wear", "the"]', NULL, NULL, NULL, NULL, 'Use present continuous (is + -ing) to describe what someone is doing or wearing now. ''She is wearing'' not ''she wears'' for right now.', '2026-02-13 08:00:10.850224+00', NULL, NULL, 'en', '{"Present tense"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('fb8fe35d-9914-4f83-8701-6d831b46bab2', 632, 'sentence_building', 'A2', 'present_continuous', '', 'we are going to the beach', '["we", "are", "going", "to", "the", "beach", "will", "a"]', NULL, NULL, NULL, NULL, '''We are going to'' describes a plan or movement. ''Are going'' is the present continuous of ''go''.', '2026-02-13 08:00:10.850224+00', NULL, NULL, 'en', '{"Present tense"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('10c093a9-6204-4477-97ae-486fc4478a39', 652, 'sentence_building', 'B1', 'present_perfect', '', 'I have lived here since I was a child', '["I", "have", "lived", "here", "since", "I", "was", "a", "child", "for", "living", "am"]', NULL, NULL, NULL, NULL, 'Present perfect with "since" + point in time. Describes duration from past to now.', '2026-02-17 09:58:54.170896+00', NULL, NULL, 'en', '{"Present tense"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('c6d7b013-7ddd-4633-a3ff-c6c2b2e04a8a', 645, 'sentence_building', 'A1', 'present_simple', 'Ella no come carne.', 'She does not eat meat', '["she", "does", "not", "eat", "meat", "don''t", "do", "eats", "fish"]', NULL, NULL, NULL, NULL, 'Negative present simple: subject + does not + base verb.', '2026-02-17 09:58:54.170896+00', NULL, NULL, 'en', '{"Present tense"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('38e6f39a-3d48-4c4a-aa5e-667289f91d90', 2143, 'gap_fill', 'B2', 'prepositions', 'We need to focus ___ the main issue.', 'on', '[]', NULL, NULL, NULL, '"focus ___ something" — direct your attention towards it.', '"Focus on" means to direct your attention towards something.', '2026-06-01 07:16:29.304337+00', NULL, NULL, 'en', '{Preposition}', false, 'Two letters.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('06881467-f7b6-4ef8-becf-d0fc74ff2d5a', 624, 'sentence_building', 'A2', 'present_simple', 'No me gusta el café.', 'I do not like coffee', '["I", "do", "not", "like", "coffee", "am", "the"]', NULL, NULL, NULL, NULL, 'To make a negative sentence in present simple, we use: subject + do/does + not + verb. ''I do not like coffee.''', '2026-02-13 08:00:10.850224+00', NULL, NULL, 'both', '{"Present tense"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('b21fb022-74be-4477-a968-b37f467b3b56', 637, 'sentence_building', 'A2', 'present_simple', '', 'he usually walks to work', '["he", "usually", "walks", "to", "work", "is", "goes"]', NULL, NULL, '["he walks to work ."]', NULL, 'Adverbs of frequency go before the main verb. ''He usually walks'' — ''walks'' because he/she/it takes -s.', '2026-02-13 08:00:10.850224+00', NULL, NULL, 'en', '{"Present tense"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('ad6b0e51-2191-45c1-89c2-845d72163fef', 609, 'sentence_building', 'B1', 'present_continuous', 'Mis compañeros están preparando una presentación para el cliente.', 'my colleagues are preparing a presentation for the client', '["my", "colleagues", "are", "preparing", "a", "presentation", "for", "the", "client", "friends", "making", "from"]', NULL, NULL, NULL, NULL, 'Present continuous for current activities. "Preparing a presentation" and "for the client" are standard collocations.', '2026-02-12 15:08:31.507807+00', NULL, NULL, 'en', '{"Present tense"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('1d18d496-3f6b-4ca3-aeaa-3bbdca3660c3', 1983, 'sentence_building', 'A2', 'travel', '¿Puedo tener la tarjeta de embarque, por favor?', 'Can I have a boarding pass, please?', '["can", "I", "have", "a", "boarding", "pass", "please", "ticket", "card", "get"]', NULL, NULL, NULL, NULL, '"Can I have...?" is a polite, direct way to ask for something. A boarding pass is the document you need to board the plane.', '2026-04-13 09:19:30.039983+00', NULL, NULL, 'en', '{Travel}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('800e5b4d-5bd8-4fe1-90f1-69d237ec3e72', 1984, 'sentence_building', 'A1', 'travel', 'Mi pasaporte está en mi bolso.', 'My passport is in my bag.', '["my", "passport", "is", "in", "my", "bag", "on", "wallet", "suitcase", "the"]', NULL, NULL, NULL, NULL, 'Use "in" for things inside a container. Your passport is the official document you need to travel abroad.', '2026-04-13 09:19:30.039983+00', NULL, NULL, 'en', '{Travel}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('b275af32-aba8-42bf-86e2-e4c99329c989', 1985, 'sentence_building', 'A1', 'travel', 'El hotel está cerca de la playa.', 'The hotel is near the beach.', '["the", "hotel", "is", "near", "the", "beach", "next", "to", "airport", "close"]', NULL, NULL, NULL, NULL, '"Near + noun" means close to something. You can also say "close to the beach" or "next to the beach."', '2026-04-13 09:19:30.039983+00', NULL, NULL, 'en', '{Travel}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('b0221bcf-3774-406d-a38c-1eb25a078516', 1986, 'sentence_building', 'A2', 'travel', 'Llegamos al aeropuerto a las siete.', 'We get to the airport at seven.', '["we", "get", "to", "the", "airport", "at", "seven", "arrive", "leave", "eight"]', NULL, NULL, NULL, NULL, '"Get to" is an informal way to say "arrive at." Use it with specific places like airports and train stations.', '2026-04-13 09:19:30.039983+00', NULL, NULL, 'en', '{Travel}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('1bda82b9-a6cd-4602-981c-c4e813c25f77', 675, 'odd_one_out', 'B1', 'adjectives', 'Which word does NOT describe personality?', 'enormous', '["generous", "reliable", "enormous", "cheerful"]', NULL, NULL, NULL, NULL, '"Enormous" describes size, not personality.', '2026-02-20 19:09:17.848852+00', NULL, NULL, 'en', '{Adjective}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('ee3df3b4-97ae-46d2-bf00-64eab8945260', 722, 'odd_one_out', 'B1', 'irregular_verbs', 'Which is NOT an irregular verb?', 'play', '["go", "eat", "play", "swim"]', NULL, NULL, NULL, NULL, '"Play" is regular (play → played → played). The others are irregular.', '2026-02-20 19:09:17.848852+00', NULL, NULL, 'en', '{"Irregular verb"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('89a72a2f-e49b-49d0-8e1e-cb87372fc41c', 700, 'odd_one_out', 'A1', 'days_and_months', 'Which one is NOT a day of the week?', 'tomorrow', '["Monday", "tomorrow", "Friday", "Sunday"]', NULL, NULL, NULL, NULL, '"Tomorrow" is not a day of the week.', '2026-02-20 19:09:17.848852+00', NULL, NULL, 'en', '{"Time expression"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('fc6040c4-5d44-442e-a1e6-21aba606b9e6', 726, 'odd_one_out', 'A2', 'family', 'Which one is NOT a family member?', 'neighbour', '["uncle", "cousin", "neighbour", "grandmother"]', NULL, NULL, NULL, NULL, '"Neighbour" is someone who lives nearby, not a family member.', '2026-02-20 19:09:17.848852+00', NULL, NULL, 'en', '{Vocabulary}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('a2bcf68e-527d-4017-9118-6788aa4394bb', 706, 'odd_one_out', 'A1', 'food', 'Which one is NOT food?', 'snails', '["bread", "cheese", "snails", "rice"]', NULL, NULL, NULL, NULL, 'A "snail" is a mollusc, not food. Some people disagree, I know...', '2026-02-20 19:09:17.848852+00', NULL, NULL, 'en', '{Vocabulary}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('91083ef4-0fba-4711-803b-1fd90af6d227', 702, 'odd_one_out', 'A2', 'jobs', 'Which one is NOT a job?', 'teach', '["builder", "doctor", "teach", "nurse"]', NULL, NULL, NULL, NULL, '"Teach" is a verb, not a job. Teacher is arguably a job, it depends on your teacher... ', '2026-02-20 19:09:17.848852+00', NULL, NULL, 'en', '{Vocabulary}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('bd040507-4420-43c2-b022-a1b65fc4f812', 710, 'odd_one_out', 'A1', 'numbers', 'Which one is NOT a number?', 'many', '["many", "twelve", "seven", "three"]', NULL, NULL, NULL, NULL, '"Many" is a quantifier, not a number.', '2026-02-20 19:09:17.848852+00', NULL, NULL, 'en', '{Vocabulary}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('c49050be-42a2-49fd-8a07-fd7ad273b31d', 713, 'odd_one_out', 'A2', 'weather', 'Which one is NOT weather?', 'soft', '["sunny", "rainy", "soft", "cloudy"]', NULL, NULL, NULL, NULL, '"Soft" describes many things, not the weather generally. We can say ''soft wind'' or ''soft rain'' though. ', '2026-02-20 19:09:17.848852+00', NULL, NULL, 'en', '{Vocabulary}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('47e97981-6a12-4b87-8626-49772f477d9f', 687, 'odd_one_out', 'A2', 'transport', 'Which one is NOT a means of transport?', 'sheep', '["bus", "train", "sheep", "bicycle"]', NULL, NULL, NULL, NULL, 'A "sheep" is an animal, not transport. They do not like it if you try to ride them 😉. ', '2026-02-20 19:09:17.848852+00', NULL, NULL, 'en', '{Vocabulary}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('922a6b47-00cb-4d81-a89a-e23f67b93afe', 703, 'odd_one_out', 'A1', 'animals', 'Which one is NOT an animal?', 'mushroom', '["cat", "dog", "horse", "mushroom"]', NULL, NULL, NULL, NULL, 'A "mushroom" is an fungi not an animal. Nor a vegetable. ', '2026-02-20 19:09:17.848852+00', NULL, NULL, 'en', '{Vocabulary}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('dffc2de6-41c4-4e69-ac9d-a4bcf05ed647', 719, 'odd_one_out', 'A1', 'colours', 'Which one is NOT a colour?', 'clear', '["red", "blue", "green", "clear"]', NULL, NULL, NULL, NULL, '"Clear" is an adjective describing transparency, or the absence of colour,  it is not a colour.', '2026-02-20 19:09:17.848852+00', NULL, NULL, 'en', '{Vocabulary}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('c3e5135f-7c4e-4d41-86cb-504ccd2c5f50', 712, 'odd_one_out', 'C2', 'euphemisms', 'Which is NOT a euphemism?', 'blunt', '["passed away", "let go", "blunt", "economical with the truth"]', NULL, NULL, NULL, NULL, '"Blunt" is direct, the opposite of euphemistic. The others soften difficult truths.', '2026-02-20 19:09:17.848852+00', NULL, NULL, 'en', '{"Academic English"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('38ba09f0-abf6-47d3-a3c3-ea5308108936', 686, 'odd_one_out', 'C2', 'literary_devices', 'Which literary device is NOT about comparison?', 'alliteration', '["simile", "metaphor", "alliteration", "analogy"]', NULL, NULL, NULL, NULL, '"Alliteration" is repetition of initial sounds. The others compare things.', '2026-02-20 19:09:17.848852+00', NULL, NULL, 'en', '{"Academic English"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('591e6f0f-cf44-40ac-9dab-548caf501104', 616, 'sentence_building', 'B1', 'reported_speech', NULL, 'he told me that he was leaving the company', '["he", "told", "me", "that", "he", "was", "leaving", "the", "company", "said", "are", "join"]', NULL, NULL, NULL, NULL, 'Reported speech: told + person + that + past tense. "Told me" requires an object; "said" does not.', '2026-02-12 14:34:46.611844+00', NULL, NULL, 'en', '{"Reported speech"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('a533c76f-730e-4448-a931-5c772debd560', 1744, 'gap_fill', 'B2', 'sport', 'Padel requires quick reflexes and excellent _____ between partners, especially near the net.', 'coordination', NULL, NULL, NULL, NULL, 'The smooth, well-timed working together — between people or body parts.', 'Coordination in sport refers to the ability to control body movements smoothly and efficiently, especially in relation to a partner or opponent. In padel doubles, coordination between partners is essential for covering the court, deciding who takes the ball, and communicating during rallies. Related: hand-eye coordination, footwork, communication.', '2026-03-30 08:52:38.502672+00', NULL, NULL, 'en', '{}', false, 'Single word. Starts with c___.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('c2dd6712-e82b-4d88-a1d3-8a249e977763', 1542, 'gap_fill', 'B1', 'business_vocabulary', 'All parties with an interest in the company''s success — including employees, investors, and customers — are known as _____.', 'stakeholders', NULL, NULL, NULL, NULL, 'Broader than shareholders — they hold a *stake*, not shares.', 'Stakeholders are anyone who is affected by or has an interest in a company''s decisions. This is broader than shareholders, who only own equity. The term is central to modern business ethics.', '2026-03-26 08:02:12.742714+00', NULL, NULL, 'en', '{}', false, 'Anyone who would care if the company succeeded or failed.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('454c3fa6-f900-48b8-84a7-a8eba5189241', 1543, 'gap_fill', 'B1', 'business_vocabulary', 'The company launched an aggressive _____ campaign to win customers away from its main competitor.', 'marketing', NULL, NULL, NULL, NULL, 'What department would plan a campaign to win customers?', 'A marketing campaign is a coordinated set of activities designed to promote a product or service and attract customers. It can include advertising, social media, events, and promotions.', '2026-03-26 08:02:12.742714+00', NULL, NULL, 'en', '{}', false, 'The 4 Ps: product, price, place, and promotion.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('1019733e-5391-4321-a482-829e5ae77801', 1548, 'gap_fill', 'C1', 'business_vocabulary', 'The board approved the _____ of its underperforming retail division to focus on its core logistics business.', 'divestiture', NULL, NULL, NULL, NULL, 'The opposite of an investment — selling off, not buying in.', 'Divestiture (or divestment) is the process of selling off a subsidiary, business unit, or asset. Companies divest to raise capital, reduce complexity, or refocus on core activities.', '2026-03-26 08:02:12.742714+00', NULL, NULL, 'en', '{}', false, 'Strip the prefix away and you have "vest" — to give or transfer.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('7c28ae09-cc73-4948-9e21-23139a8b5c3a', 1745, 'gap_fill', 'B2', 'sport', 'After months of weight training, she had visibly increased her muscle _____ and reduced her body fat percentage.', 'mass', NULL, NULL, NULL, NULL, 'The amount or bulk of something — in fitness, the volume of muscle tissue.', 'Muscle mass refers to the total amount of muscle tissue in the body. Increasing muscle mass through resistance training raises the basal metabolic rate (the number of calories burned at rest), which is one reason weight training is recommended alongside cardio for fat loss. Related terms: lean muscle mass, body composition, hypertrophy (muscle growth).', '2026-03-30 08:52:38.502672+00', NULL, NULL, 'en', '{}', false, 'Single word. Starts with m___.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('a2d99a4e-1eb3-4735-99bb-839cb4e4b755', 2144, 'gap_fill', 'B2', 'prepositions', 'He apologised ___ being late.', 'for', '[]', NULL, NULL, NULL, '"apologise ___ something you did".', 'The pattern is "apologise for (doing) something".', '2026-06-01 07:16:29.304337+00', NULL, NULL, 'en', '{Preposition}', false, 'Three letters.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('dd93cbea-9a88-4890-a8a9-9614e88a3262', 2145, 'multiple_choice', 'B2', 'prepositions', 'The decision depends ___ the budget.', 'on', '["on", "of", "from", "to"]', NULL, NULL, NULL, '"depend ___ something" — a fixed pairing.', '"Depend on" is the fixed pairing — never "depend of" or "depend to".', '2026-06-01 07:16:29.304337+00', NULL, NULL, 'en', '{Preposition}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('9dbcbfad-3cf5-4eb4-9676-149a2097781e', 2146, 'multiple_choice', 'B2', 'prepositions', 'She succeeded ___ passing the exam.', 'in', '["in", "at", "on", "with"]', NULL, NULL, NULL, '"succeed ___ doing something".', 'The pattern is "succeed in (doing) something".', '2026-06-01 07:16:29.304337+00', NULL, NULL, 'en', '{Preposition}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('696cefba-f86b-42be-a6b6-2a6905d7ece5', 695, 'error_correction', 'A1', 'singular_plural', 'I have two sister and a brother.', 'I have two sisters and a brother.', '[]', NULL, NULL, NULL, NULL, 'We need the plural form: "two sisters".', '2026-02-20 19:09:17.848852+00', NULL, NULL, 'en', '{Plural}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('44f4ab6e-60b5-4038-b6b7-f9c469583b7c', 727, 'matching', 'A1', 'vocabulary', 'Match the English words to their Spanish translations.', 'match_all_pairs', '[{"left": {"type": "text", "content": "new"}, "right": {"type": "text", "content": "nuevo"}}, {"left": {"type": "text", "content": "old"}, "right": {"type": "text", "content": "viejo"}}, {"left": {"type": "text", "content": "big"}, "right": {"type": "text", "content": "grande"}}, {"left": {"type": "text", "content": "small"}, "right": {"type": "text", "content": "pequeño"}}, {"left": {"type": "text", "content": "beautiful"}, "right": {"type": "text", "content": "bonito"}}]', NULL, NULL, NULL, NULL, NULL, '2026-02-25 12:16:31.110712+00', NULL, NULL, 'both', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('bcfacec7-7a50-4e33-ba93-e50b29690332', 1746, 'gap_fill', 'C1', 'sport', 'The swimmer''s _____ technique — her ability to turn efficiently at the wall — was the key difference in a race decided by hundredths of a second.', 'tumble turn', NULL, NULL, NULL, '[{"answer": "turning", "feedback": "Good thinking — turning is close, but the specific technique is called a tumble turn (or flip turn)."}]', 'The somersault swimmers do at the end of a length to push off the wall.', 'A tumble turn (or flip turn) is the technique competitive swimmers use to turn at the end of a length without stopping — rolling forward, pushing off the wall with both feet, and continuing in the opposite direction. It is significantly faster than an open turn and is essential at competitive level. Mastering the tumble turn is one of the first goals for swimmers moving from recreational to competitive swimming.', '2026-03-30 08:52:38.502672+00', NULL, NULL, 'en', '{}', false, 'Two words. Starts with t___ t___.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('c274c257-c5ea-4c43-a3a8-b39d4b57cc7a', 1724, 'gap_fill', 'C2', 'business_vocabulary', 'The regulator stepped in to _____ the merger before it could further distort competition in the market.', 'block', NULL, NULL, NULL, NULL, 'Simple everyday verb — what you do to someone''s path.', 'Block here works as a single verb, but in business contexts the relevant phrasal alternatives are: block off (to prevent access), shut down (to stop completely), put a stop to, and most formally — prohibit or prevent. Regulators blocking mergers is a very common theme in business English, and the vocabulary around it (block, prohibit, refer, scrutinise, approve, clear) is worth knowing.', '2026-03-30 08:25:59.401228+00', NULL, NULL, 'en', '{}', false, 'What a goalkeeper does to a shot.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('c8c5c2b9-cbcc-4037-943e-13f22c3255f8', 1747, 'gap_fill', 'C1', 'sport', 'Running coaches often warn against _____ — training too hard without adequate rest, which leads to fatigue, poor performance, and injury.', 'overtraining', NULL, NULL, NULL, NULL, 'Going beyond what the body can recover from — too much training, not enough rest.', 'Overtraining syndrome occurs when the volume or intensity of training exceeds the body''s ability to recover. Symptoms include persistent fatigue, declining performance, irritability, and increased susceptibility to illness. The antidote is periodisation — structuring training into cycles of hard work and planned recovery. Rest is not weakness; it is when adaptation occurs.', '2026-03-30 08:52:38.502672+00', NULL, NULL, 'en', '{}', false, 'Single word. Starts with o___.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('d2291160-3751-4dca-a45b-58dfa72f7c08', 1748, 'gap_fill', 'C1', 'sport', 'She focused on _____ training — short, maximum-effort intervals followed by brief rest periods — to improve her speed and cardiovascular capacity.', 'high-intensity interval', NULL, NULL, NULL, '[{"answer": "hiit", "feedback": "HIIT is the acronym — the full term is high-intensity interval, which describes the training method itself."}]', 'Short bursts at maximum effort alternated with rest. Often abbreviated HIIT.', 'High-intensity interval training (HIIT) alternates between short bursts of maximum effort and recovery periods. It is time-efficient, burns a high number of calories, and improves both aerobic and anaerobic fitness. CrossFit incorporates many HIIT principles. Research suggests that 20 minutes of HIIT can be as effective as longer moderate-intensity sessions for cardiovascular health.', '2026-03-30 08:52:38.502672+00', NULL, NULL, 'en', '{}', false, 'Three words (hyphenated). Starts with h___-i___ i___.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('5ebbe87d-ea16-4a69-aa07-2daec478f4c5', 858, 'sentence_auction', 'A1', 'grammar', 'Theme: He, She, It — does or doesn''t?', 'auction', '[{"correct": true, "sentence": "She doesn''t like spicy food.", "explanation": "Correct! We use doesn''t with he/she/it in negative present simple."}, {"correct": false, "sentence": "He go to work by bus every day.", "explanation": "Wrong — he/she/it needs an -s: ''He goes to work by bus every day.''"}, {"correct": false, "sentence": "My brother play football on Sundays.", "explanation": "Wrong — third person singular needs -s: ''My brother plays football on Sundays.''"}, {"correct": true, "sentence": "The cat sleeps on the sofa.", "explanation": "Correct! The cat = third person singular, so sleeps is right."}, {"correct": true, "sentence": "Does your sister speak English?", "explanation": "Correct! Does + infinitive (no -s) for questions with he/she/it."}, {"correct": false, "sentence": "He doesn''t speaks French.", "explanation": "Wrong — after doesn''t, use the infinitive: ''He doesn''t speak French.''"}]', NULL, NULL, NULL, NULL, NULL, '2026-02-26 08:26:39.264638+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('30ab2d2d-4e69-442f-b1ee-838f48877a4a', 655, 'sentence_building', 'B1', 'second_conditional', 'Si tuviera mas tiempo, aprendería a tocar la guitarra.', 'if I had more time I would learn to play the guitar', '["if", "I", "had", "more", "time", "I", "would", "learn", "to", "play", "the", "guitar", "will", "have", "played"]', '["I would learn to play the guitar if I had more time.", "I would learn to play the guitar if I had more time ."]', NULL, NULL, NULL, 'Second conditional: If + past simple, would + infinitive. Used for unreal or unlikely situations.', '2026-02-17 09:58:54.170896+00', NULL, NULL, 'en', '{Conditional}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('e3094ad4-822f-4822-9501-24979fc8d271', 651, 'sentence_building', 'B1', 'first_conditional', '', 'if it rains tomorrow we will stay at home', '["if", "it", "rains", "tomorrow", "we", "will", "stay", "at", "home", "would", "stayed", "rained"]', NULL, NULL, NULL, NULL, 'First conditional: If + present simple, will + infinitive. Used for real future possibilities. Either clause can go first in the sentence.', '2026-02-17 09:58:54.170896+00', NULL, NULL, 'en', '{Conditional}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('90ec15b8-4fb4-4b8a-a598-de29a4bab397', 668, 'sentence_building', 'C2', 'inversion', 'Bajo ningun concepto deberia haberse tomado esa decision sin consultarnos.', 'under no circumstances should that decision have been made without consulting us', '["under", "no", "circumstances", "should", "that", "decision", "have", "been", "made", "without", "consulting", "us", "hardly", "making", "the", "consult"]', NULL, NULL, NULL, NULL, 'Under no circumstances + inverted auxiliary: emphatic prohibition. Passive perfect infinitive.', '2026-02-17 09:58:54.170896+00', NULL, NULL, 'en', '{Inversion}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('be380d41-47f0-4c14-9d0e-c9bbb2e569ae', 619, 'sentence_building', 'C1', 'inversion', NULL, 'not only did she pass the exam but she also got the highest mark', '["not", "only", "did", "she", "pass", "the", "exam", "but", "she", "also", "got", "the", "highest", "mark", "failed", "lowest", "however"]', NULL, NULL, NULL, NULL, 'Inversion with "not only...but also": not only + auxiliary + subject + verb. Emphasises both achievements.', '2026-02-12 14:34:46.611844+00', NULL, NULL, 'en', '{Inversion}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('771d75bc-dbce-4a9d-b1be-4c6696751112', 603, 'sentence_building', 'B2', 'present_perfect', 'La empresa ha decidido ampliar su equipo de ventas.', 'the company has decided to expand its sales team', '["the", "company", "has", "decided", "to", "expand", "its", "sales", "team", "their", "reduce", "group"]', NULL, NULL, NULL, NULL, '"Its" (not "their") is correct for a singular company. "Expand" = ampliar. "Sales team" is the standard business term.', '2026-02-12 15:08:31.507807+00', NULL, NULL, 'en', '{"Present tense"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('4124c038-9608-42a3-aa48-3189dc4f2660', 2147, 'multiple_choice', 'B2', 'prepositions', 'I must congratulate you ___ your promotion.', 'on', '["on", "for", "about", "with"]', NULL, NULL, NULL, '"congratulate somebody ___ an achievement".', 'We "congratulate somebody on" an achievement.', '2026-06-01 07:16:29.304337+00', NULL, NULL, 'en', '{Preposition}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('628c3414-9075-458a-b695-1394a32c9540', 859, 'sentence_auction', 'A1', 'grammar', 'Theme: Present Continuous — what is happening right now?', 'auction', '[{"correct": true, "sentence": "They are watching a film at the moment.", "explanation": "Correct! Are + watching — perfect present continuous."}, {"correct": false, "sentence": "She is study for her exam right now.", "explanation": "Wrong — you need the -ing form: ''She is studying for her exam.''"}, {"correct": false, "sentence": "I am not understand this question.", "explanation": "Wrong — ''understand'' is a state verb. We don''t use it in continuous: ''I don''t understand this question.''"}, {"correct": true, "sentence": "He is wearing a red jacket today.", "explanation": "Correct! Is + wearing — describing something happening now."}, {"correct": true, "sentence": "Are you listening to me?", "explanation": "Correct! Are + listening — perfect question form."}, {"correct": false, "sentence": "We is having a great time!", "explanation": "Wrong — with ''we'', use are: ''We are having a great time!''"}]', NULL, NULL, NULL, NULL, NULL, '2026-02-26 08:26:39.264638+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('16d9a762-88dd-491e-9209-af843f953172', 860, 'sentence_auction', 'A2', 'grammar', 'Theme: Question word order — do the words go in the right order?', 'auction', '[{"correct": true, "sentence": "Where does she live?", "explanation": "Correct! Question word + does + subject + infinitive — perfect."}, {"correct": false, "sentence": "What time you wake up?", "explanation": "Wrong — you need the auxiliary: ''What time do you wake up?''"}, {"correct": true, "sentence": "How old is your brother?", "explanation": "Correct! With the verb ''to be'', we invert: How old + is + subject."}, {"correct": false, "sentence": "Why he is angry?", "explanation": "Wrong — invert the subject and auxiliary: ''Why is he angry?''"}, {"correct": true, "sentence": "Who is your favourite teacher?", "explanation": "Correct! When ''who'' is the subject, no auxiliary needed."}, {"correct": true, "sentence": "What does ''curious'' mean?", "explanation": "Correct! Does + subject + infinitive — the word order is right."}]', NULL, NULL, NULL, NULL, NULL, '2026-02-26 08:26:39.264638+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('c1f8311a-0688-44c3-8ec3-26a0d8bd4813', 861, 'sentence_auction', 'A1', 'grammar', 'Theme: There is / There are — singular or plural?', 'auction', '[{"correct": true, "sentence": "There are three windows in this room.", "explanation": "Correct! Three windows = plural, so we use ''there are''."}, {"correct": false, "sentence": "There is a lot of people in the street.", "explanation": "Wrong — ''people'' is plural: ''There are a lot of people in the street.''"}, {"correct": true, "sentence": "Is there any milk in the fridge?", "explanation": "Correct! ''Milk'' is uncountable — ''is there'' is right."}, {"correct": false, "sentence": "There are a good restaurant near here.", "explanation": "Wrong — one restaurant = singular: ''There is a good restaurant near here.''"}, {"correct": true, "sentence": "There isn''t any bread left.", "explanation": "Correct! ''Bread'' is uncountable — ''there isn''t'' is perfect."}]', NULL, NULL, NULL, NULL, NULL, '2026-02-26 08:26:39.264638+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('81df3985-f19b-43fa-9f28-e49ed8488b96', 862, 'sentence_auction', 'A1', 'grammar', 'Theme: Can and can''t — ability and possibility', 'auction', '[{"correct": false, "sentence": "She can to swim very well.", "explanation": "Wrong — modal verbs never use ''to'': ''She can swim very well.''"}, {"correct": true, "sentence": "Can you help me, please?", "explanation": "Correct! Can + subject + infinitive — perfect question form."}, {"correct": true, "sentence": "He can''t drive a car.", "explanation": "Correct! Can''t + infinitive — no -s, no ''to''."}, {"correct": true, "sentence": "I can speak three languages.", "explanation": "Correct! Can + infinitive — simple and clean."}, {"correct": false, "sentence": "Can she to play the guitar?", "explanation": "Wrong — no ''to'' after can: ''Can she play the guitar?''"}, {"correct": false, "sentence": "He can''t drives a car.", "explanation": "Wrong — after can/can''t, always use the infinitive: ''He can''t drive.''"}]', NULL, NULL, NULL, NULL, NULL, '2026-02-26 08:26:39.264638+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('21c64191-3530-403c-a621-b75f92e6da35', 863, 'sentence_auction', 'A2', 'grammar', 'Theme: Articles — a, an, or the?', 'auction', '[{"correct": true, "sentence": "She is an engineer.", "explanation": "Correct! ''Engineer'' starts with a vowel sound — so we use ''an''."}, {"correct": true, "sentence": "He is the best student in the class.", "explanation": "Correct! ''The best'' — superlatives always use ''the''."}, {"correct": true, "sentence": "I want to be a doctor.", "explanation": "Correct! Jobs use ''a/an'' — ''a doctor'' is right."}, {"correct": false, "sentence": "She is a honest person.", "explanation": "Wrong — ''honest'' starts with a vowel sound (the h is silent): ''She is an honest person.''"}, {"correct": true, "sentence": "He plays the guitar every evening.", "explanation": "Correct! Musical instruments use ''the'': the guitar, the piano."}, {"correct": false, "sentence": "She plays a piano.", "explanation": "Wrong — musical instruments take ''the'': ''She plays the piano.''"}]', NULL, NULL, NULL, NULL, NULL, '2026-02-26 08:26:39.264638+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('aa134200-7ec9-4b51-9797-bd9c645220cd', 864, 'sentence_auction', 'A1', 'grammar', 'Theme: At, on, in — prepositions of time', 'auction', '[{"correct": true, "sentence": "I was born in 1995.", "explanation": "Correct! We use ''in'' with years, months and seasons."}, {"correct": true, "sentence": "The meeting is on Monday at 9 o''clock.", "explanation": "Correct! ''On'' for days, ''at'' for specific times — both right."}, {"correct": false, "sentence": "The party is in Saturday.", "explanation": "Wrong — use ''on'' with days of the week: ''The party is on Saturday.''"}, {"correct": true, "sentence": "I go to bed at midnight.", "explanation": "Correct! We use ''at'' with clock times and midnight/midday."}, {"correct": false, "sentence": "She was born on July.", "explanation": "Wrong — use ''in'' with months: ''She was born in July.''"}, {"correct": true, "sentence": "He arrived at the airport in the morning.", "explanation": "Correct! ''At'' the airport (place), ''in the morning'' (part of day) — both right."}]', NULL, NULL, NULL, NULL, NULL, '2026-02-26 08:26:39.264638+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('f9a67517-358b-4415-97aa-89f2bc204a26', 865, 'sentence_auction', 'A2', 'grammar', 'Theme: Object pronouns — me, him, her, us, them', 'auction', '[{"correct": true, "sentence": "She gave him a book.", "explanation": "Correct! ''Him'' is the object pronoun for ''he''."}, {"correct": false, "sentence": "Can you help I?", "explanation": "Wrong — ''I'' is a subject pronoun. After a verb, use the object: ''Can you help me?''"}, {"correct": true, "sentence": "I love her very much.", "explanation": "Correct! ''Her'' is the object pronoun for ''she''."}, {"correct": false, "sentence": "He called we yesterday.", "explanation": "Wrong — ''we'' is a subject pronoun. Use the object: ''He called us yesterday.''"}, {"correct": true, "sentence": "They invited her to the party.", "explanation": "Correct! ''Her'' is right — she received the invitation."}, {"correct": true, "sentence": "Give it to me, please.", "explanation": "Correct! Both ''it'' and ''me'' are object pronouns used correctly here."}]', NULL, NULL, NULL, NULL, NULL, '2026-02-26 08:26:39.264638+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('6d52fc6c-c187-4cf9-b76d-0147c8280856', 2148, 'multiple_choice', 'B2', 'prepositions', 'They are responsible ___ the whole team.', 'for', '["for", "of", "to", "about"]', NULL, NULL, NULL, '"responsible ___ something/someone".', '"Responsible for" is the fixed pairing.', '2026-06-01 07:16:29.304337+00', NULL, NULL, 'en', '{Preposition}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('e24e6aeb-5417-4a12-8b15-0e3ddd6d1bb5', 866, 'sentence_auction', 'A1', 'grammar', 'Theme: Have got / Has got — possession', 'auction', '[{"correct": true, "sentence": "She has got two brothers.", "explanation": "Correct! She = third person singular, so ''has got'' is right."}, {"correct": false, "sentence": "She have got two brothers.", "explanation": "Wrong — with he/she/it, use ''has got'': ''She has got two brothers.''"}, {"correct": true, "sentence": "Have you got a pen?", "explanation": "Correct! ''Have you got'' — the right question form."}, {"correct": false, "sentence": "They has got a dog.", "explanation": "Wrong — ''they'' uses ''have got'': ''They have got a dog.''"}, {"correct": true, "sentence": "Has she got any sisters?", "explanation": "Correct! Has + subject + got — perfect question form for third person."}]', NULL, NULL, NULL, NULL, NULL, '2026-02-26 08:26:39.264638+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('f4dd393b-ff1e-474f-9dc0-56a7f4d3d2a7', 867, 'sentence_auction', 'A2', 'grammar', 'Theme: Adjectives — where do they go?', 'auction', '[{"correct": true, "sentence": "It''s a beautiful old building.", "explanation": "Correct! Adjectives go before the noun in English."}, {"correct": false, "sentence": "She has a hair long and brown.", "explanation": "Wrong — adjectives go BEFORE the noun in English: ''She has long, brown hair.''"}, {"correct": true, "sentence": "The weather is cold today.", "explanation": "Correct! Adjectives can also go after ''be'': is/are/was + adjective."}, {"correct": true, "sentence": "He is a very tall man.", "explanation": "Correct! Very + adjective + noun — the order is right."}, {"correct": false, "sentence": "That was an idea interesting.", "explanation": "Wrong — the adjective goes before the noun: ''That was an interesting idea.''"}, {"correct": true, "sentence": "She wore a lovely red dress.", "explanation": "Correct! Opinion adjective (lovely) comes before colour (red) — perfect order."}]', NULL, NULL, NULL, NULL, NULL, '2026-02-26 08:26:39.264638+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('01105ef8-1375-4cc4-ac67-5cf5e21ccfec', 868, 'sentence_auction', 'B1', 'grammar', 'Theme: Conditionals — first and second', 'auction', '[{"correct": true, "sentence": "If it rains tomorrow, we will stay at home.", "explanation": "Correct! First conditional: if + present simple, will + infinitive."}, {"correct": false, "sentence": "If I would have more money, I would travel more.", "explanation": "Wrong — never use ''would'' in the if-clause: ''If I had more money, I would travel more.''"}, {"correct": true, "sentence": "If I knew the answer, I would tell you.", "explanation": "Correct! Second conditional: if + past simple, would + infinitive."}, {"correct": true, "sentence": "We''ll miss the train if we don''t hurry.", "explanation": "Correct! First conditional — the if-clause is in present simple, main clause uses will."}, {"correct": false, "sentence": "She would be happier if she exercises more.", "explanation": "Wrong — second conditional needs past simple in the if-clause: ''if she exercised more.''"}]', NULL, NULL, NULL, NULL, NULL, '2026-02-26 08:26:39.264638+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('78b65257-6984-4ac4-a4d6-2762cf3434e9', 869, 'sentence_auction', 'B1', 'grammar', 'Theme: Passive voice — is the form correct?', 'auction', '[{"correct": true, "sentence": "This bridge was built in 1890.", "explanation": "Correct! Was + past participle — passive simple past."}, {"correct": false, "sentence": "The report was wrote by the manager.", "explanation": "Wrong — ''wrote'' is simple past, not past participle. Use ''written'': ''The report was written by the manager.''"}, {"correct": true, "sentence": "The meeting has been postponed until Friday.", "explanation": "Correct! Has been + past participle — present perfect passive."}, {"correct": false, "sentence": "English is spoke in many countries.", "explanation": "Wrong — the past participle of ''speak'' is ''spoken'': ''English is spoken in many countries.''"}, {"correct": true, "sentence": "The windows are cleaned every week.", "explanation": "Correct! Are + past participle — present simple passive for repeated actions."}, {"correct": false, "sentence": "The cake was ate by the children.", "explanation": "Wrong — the past participle of ''eat'' is ''eaten'': ''The cake was eaten by the children.''"}]', NULL, NULL, NULL, NULL, NULL, '2026-02-26 08:26:39.264638+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('7d114739-1fb9-4926-935c-f49201be425d', 870, 'sentence_auction', 'B2', 'grammar', 'Theme: Reported speech — what changes when we report?', 'auction', '[{"correct": true, "sentence": "She said that she was tired.", "explanation": "Correct! ''Is'' shifts back to ''was'' in reported speech — perfect."}, {"correct": false, "sentence": "He told me he will come tomorrow.", "explanation": "Wrong — ''will'' shifts back to ''would'' in reported speech: ''He told me he would come.''"}, {"correct": true, "sentence": "She asked me where I lived.", "explanation": "Correct! Reported questions use normal word order — no inversion after the question word."}, {"correct": false, "sentence": "She asked me where did I live.", "explanation": "Wrong — no inversion in reported questions: ''She asked me where I lived.''"}, {"correct": true, "sentence": "They said they hadn''t seen the film.", "explanation": "Correct! ''Haven''t'' shifts back to ''hadn''t'' — the backshift is right."}, {"correct": false, "sentence": "He told to me the news.", "explanation": "Wrong — ''tell'' doesn''t use ''to'' before the indirect object: ''He told me the news.''"}]', NULL, NULL, NULL, NULL, NULL, '2026-02-26 08:26:39.264638+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('bcde4ce1-76b0-4f63-a82a-31b461498561', 871, 'sentence_auction', 'B1', 'grammar', 'Theme: Modal verbs — should, must, have to, might', 'auction', '[{"correct": true, "sentence": "She must be tired — she worked all night.", "explanation": "Correct! ''Must'' for a logical deduction — we''re almost certain."}, {"correct": false, "sentence": "You should to see a doctor about that cough.", "explanation": "Wrong — modal verbs never use ''to'': ''You should see a doctor.''"}, {"correct": true, "sentence": "You mustn''t park here — it''s illegal.", "explanation": "Correct! ''Mustn''t'' = prohibition. It is not allowed."}, {"correct": false, "sentence": "He don''t have to come if he doesn''t want to.", "explanation": "Wrong — ''have to'' conjugates like a normal verb: ''He doesn''t have to come.''"}, {"correct": true, "sentence": "I might go to the gym later.", "explanation": "Correct! ''Might'' + infinitive — expressing possibility. No ''to'' needed."}, {"correct": true, "sentence": "You don''t have to wear a tie — it''s not obligatory.", "explanation": "Correct! Don''t have to = no obligation. (Different from mustn''t, which is prohibition.)"}]', NULL, NULL, NULL, NULL, NULL, '2026-02-26 08:26:39.264638+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('5e734748-52ca-4f45-8c2a-36be6b0548d7', 872, 'sentence_auction', 'B1', 'grammar', 'Theme: Gerund or infinitive — which verb form follows?', 'auction', '[{"correct": true, "sentence": "I want to learn a new language.", "explanation": "Correct! ''Want'' is always followed by the infinitive: want to do."}, {"correct": false, "sentence": "She enjoys to swim in the sea.", "explanation": "Wrong — ''enjoy'' is always followed by the gerund: ''She enjoys swimming.''"}, {"correct": true, "sentence": "He decided to change jobs.", "explanation": "Correct! ''Decide'' takes the infinitive: decided to change."}, {"correct": false, "sentence": "They finished to paint the house.", "explanation": "Wrong — ''finish'' is always followed by the gerund: ''They finished painting the house.''"}, {"correct": true, "sentence": "I look forward to seeing you soon.", "explanation": "Correct! ''Look forward to'' is followed by the gerund — the ''to'' here is a preposition, not part of an infinitive."}, {"correct": true, "sentence": "She suggested going to the cinema.", "explanation": "Correct! ''Suggest'' takes the gerund: suggested going."}]', NULL, NULL, NULL, NULL, NULL, '2026-02-26 08:26:39.264638+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('a64deb62-a6f9-445f-8859-46cdd239ba21', 607, 'sentence_building', 'B2', 'present_perfect_continuous', 'Llevo trabajando aquí desde que terminé la universidad.', 'I have been working here since I finished university', '["I", "have", "been", "working", "here", "since", "I", "finished", "university", "from", "completing", "school"]', NULL, NULL, NULL, NULL, 'Present perfect continuous (have been working) + "since" + past simple. "Since" marks when the action started.', '2026-02-12 15:08:31.507807+00', NULL, NULL, 'en', '{"Present tense"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('314039ae-ffab-4c4b-8ca6-b34fdc6f5079', 873, 'sentence_auction', 'B2', 'grammar', 'Theme: Relative clauses — who, which, whose, where', 'auction', '[{"correct": true, "sentence": "The woman who lives next door is a doctor.", "explanation": "Correct! ''Who'' for people — and it''s the subject of the clause."}, {"correct": false, "sentence": "The man which I met was very kind.", "explanation": "Wrong — use ''who'' or ''that'' for people, not ''which'': ''The man who I met was very kind.''"}, {"correct": true, "sentence": "He''s the person whose car was stolen.", "explanation": "Correct! ''Whose'' shows possession — it belongs to him."}, {"correct": true, "sentence": "That''s the shop where I buy my coffee.", "explanation": "Correct! ''Where'' for places — perfect."}, {"correct": false, "sentence": "She''s the teacher who her students love.", "explanation": "Wrong — ''her'' is redundant here. Either: ''the teacher who(m) students love'' or ''the teacher her students love'' (no who)."}, {"correct": true, "sentence": "This is the book that changed my life.", "explanation": "Correct! ''That'' can replace ''which'' for things in defining relative clauses."}]', NULL, NULL, NULL, NULL, NULL, '2026-02-26 08:26:39.264638+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('9c5cc719-3813-4d47-b81a-a1dd74391fe1', 874, 'sentence_auction', 'B1', 'grammar', 'Theme: Countable and uncountable nouns', 'auction', '[{"correct": true, "sentence": "I need some advice about my career.", "explanation": "Correct! ''Advice'' is uncountable — no plural, no ''a''."}, {"correct": false, "sentence": "Can I have some informations, please?", "explanation": "Wrong — ''information'' is uncountable in English. No plural: ''Can I have some information?''"}, {"correct": true, "sentence": "There isn''t much traffic today.", "explanation": "Correct! ''Traffic'' is uncountable — we use ''much'', not ''many''."}, {"correct": false, "sentence": "She gave me a very useful advice.", "explanation": "Wrong — ''advice'' is uncountable. You can say ''some advice'' or ''a piece of advice''."}, {"correct": true, "sentence": "We need to buy some furniture for the new flat.", "explanation": "Correct! ''Furniture'' is uncountable — no plural form, no ''a''."}, {"correct": true, "sentence": "I don''t have much time right now.", "explanation": "Correct! ''Time'' (in general) is uncountable — ''much time'' is right."}]', NULL, NULL, NULL, NULL, NULL, '2026-02-26 08:26:39.264638+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('c08adb5d-99db-43f8-9eea-424612c8f8d7', 875, 'sentence_auction', 'B1', 'grammar', 'Theme: Future forms — will, going to, present continuous', 'auction', '[{"correct": true, "sentence": "Look at those clouds — it''s going to rain.", "explanation": "Correct! Evidence in the present = going to. We can see it coming."}, {"correct": false, "sentence": "I will call you when I will arrive.", "explanation": "Wrong — after time conjunctions (when, after, before, until), use present simple: ''I will call you when I arrive.''"}, {"correct": true, "sentence": "She''s meeting her manager tomorrow at 2pm.", "explanation": "Correct! Present continuous for fixed future arrangements — the meeting is in the diary."}, {"correct": true, "sentence": "I''ll open the window — it''s very hot in here.", "explanation": "Correct! Will for spontaneous decisions made at the moment of speaking."}, {"correct": false, "sentence": "They will to arrive at 6 o''clock.", "explanation": "Wrong — ''will'' is already a modal verb. No ''to'': ''They will arrive at 6.''"}]', NULL, NULL, NULL, NULL, NULL, '2026-02-26 08:26:39.264638+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('5e50a40b-c1d7-4fbf-9d5f-c2b028470591', 876, 'sentence_auction', 'B1', 'grammar', 'Theme: Comparatives and superlatives', 'auction', '[{"correct": true, "sentence": "This is the most difficult exam I''ve ever taken.", "explanation": "Correct! Most + adjective for superlatives with longer words."}, {"correct": false, "sentence": "She is more taller than her sister.", "explanation": "Wrong — never use ''more'' with a comparative adjective that already has -er: ''She is taller than her sister.''"}, {"correct": true, "sentence": "He drives more carefully than his brother.", "explanation": "Correct! ''Carefully'' is an adverb — it uses ''more'', not -er."}, {"correct": true, "sentence": "The more you practise, the better you become.", "explanation": "Correct! The + comparative, the + comparative — a great structure for cause and effect."}, {"correct": false, "sentence": "That was the most best film I''ve seen.", "explanation": "Wrong — ''best'' is already a superlative. Drop ''most'': ''That was the best film I''ve seen.''"}, {"correct": false, "sentence": "She works more harder than anyone else in the office.", "explanation": "Wrong — ''harder'' is already a comparative. No need for ''more'': ''She works harder than anyone else.''"}]', NULL, NULL, NULL, NULL, NULL, '2026-02-26 08:26:39.264638+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('72b8b521-5b28-4e47-a9d6-27b530c2732c', 877, 'sentence_auction', 'B1', 'grammar', 'Theme: Past simple vs past continuous — what was happening?', 'auction', '[{"correct": true, "sentence": "I was cooking dinner when the phone rang.", "explanation": "Correct! Longer background action (was cooking) interrupted by shorter event (rang)."}, {"correct": false, "sentence": "While I drove to work, I heard the news.", "explanation": "Wrong — driving is the longer background action: ''While I was driving to work, I heard the news.''"}, {"correct": true, "sentence": "They were watching TV when the power went off.", "explanation": "Correct! Were watching = background. Went off = the interrupting event."}, {"correct": false, "sentence": "He fall asleep while he was watching the film.", "explanation": "Wrong — past simple of ''fall'' is ''fell'': ''He fell asleep while he was watching the film.''"}, {"correct": true, "sentence": "What were you doing when I called?", "explanation": "Correct! Asking about the background action in progress — were you doing is right."}]', NULL, NULL, NULL, NULL, NULL, '2026-02-26 08:26:39.264638+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('13b08976-403a-419c-9fad-7df957d96442', 878, 'sentence_auction', 'C1', 'grammar', 'Theme: Inversion — formal and emphatic structures', 'auction', '[{"correct": true, "sentence": "Hardly had she sat down when the phone rang.", "explanation": "Correct! Hardly + had + subject — inversion required with negative adverbials."}, {"correct": false, "sentence": "Never I have seen such a beautiful sunset.", "explanation": "Wrong — inversion is required: ''Never have I seen such a beautiful sunset.''"}, {"correct": true, "sentence": "Under no circumstances should you open that door.", "explanation": "Correct! Negative adverbial at the front triggers inversion: should + subject."}, {"correct": false, "sentence": "Not only he was late, but he also forgot to call.", "explanation": "Wrong — ''not only'' at the front requires inversion in the first clause: ''Not only was he late, but...''"}, {"correct": true, "sentence": "No sooner had I left the house than it started raining.", "explanation": "Correct! No sooner + had + subject — classic inversion with ''no sooner...than''."}, {"correct": true, "sentence": "Rarely have I enjoyed a meal so much.", "explanation": "Correct! Rarely + have + subject — formal inversion used for emphasis."}]', NULL, NULL, NULL, NULL, NULL, '2026-02-26 08:26:39.264638+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('c6d9f734-ede8-438b-b88b-394eba3d58e1', 1232, 'multiple_choice', 'A2', 'business_phrasal_verbs', 'The new manager wants to _____ some changes in the department.', 'bring in', '["bring in", "bring up", "bring out", "bring over"]', NULL, NULL, NULL, 'To introduce (changes, new policies, fresh ideas).', 'Bring in means to introduce new ideas, rules, or people to an organisation.', '2026-03-18 19:58:52.376507+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('ebe44609-df7b-4096-bbf5-38d60f4bfd33', 829, 'error_correction', 'A1', 'grammar', 'We was at the beach yesterday.', 'We were at the beach yesterday.', '[]', NULL, NULL, NULL, NULL, '"We" is first person plural, the past tense of "to be" is "were", not "was". We were at the beach. I was. You/we/they were.  He/she/it was.', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('44cb79bc-c022-4259-b74f-9906067ea952', 2149, 'multiple_choice', 'B2', 'prepositions', 'This book is similar ___ the one I read.', 'to', '["to", "with", "as", "than"]', NULL, NULL, NULL, '"similar ___ something" — note it is not "with".', '"Similar to" is the fixed pairing — note it is not "similar with".', '2026-06-01 07:16:29.304337+00', NULL, NULL, 'en', '{Preposition}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('2cdce2e1-fe1f-4c29-bf8e-43eab1943581', 879, 'sentence_auction', 'C1', 'grammar', 'Theme: Perfect modals — must have, should have, can''t have', 'auction', '[{"correct": true, "sentence": "She must have forgotten about the meeting.", "explanation": "Correct! Must have + past participle — a logical deduction about the past."}, {"correct": true, "sentence": "He should have told us about the problem sooner.", "explanation": "Correct! Should have + past participle — a criticism or regret about the past."}, {"correct": true, "sentence": "They can''t have known about the changes in advance.", "explanation": "Correct! Can''t have + past participle — expressing near certainty that something didn''t happen."}, {"correct": false, "sentence": "He must had left before we arrived.", "explanation": "Wrong — it''s ''must have'', not ''must had'': ''He must have left before we arrived.''"}, {"correct": false, "sentence": "You should of called me!", "explanation": "Wrong — this is a very common written error. It''s always ''should have'', not ''should of'': ''You should have called me!''"}, {"correct": true, "sentence": "She might have missed the train.", "explanation": "Correct! Might have + past participle — speculating about a past possibility."}]', NULL, NULL, NULL, NULL, NULL, '2026-02-26 08:26:39.264638+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('b4575afa-5a60-4c87-bed1-f892b96594f1', 880, 'sentence_auction', 'C1', 'grammar', 'Theme: Participle clauses — -ing and -ed at the start', 'auction', '[{"correct": true, "sentence": "Exhausted by the long journey, she went straight to bed.", "explanation": "Correct! Past participle clause — she was exhausted, so she went to bed."}, {"correct": true, "sentence": "Having finished the report, she sent it to her manager.", "explanation": "Correct! Having + past participle for an action completed before the main verb."}, {"correct": false, "sentence": "Opened the door, he walked into the room.", "explanation": "Wrong — the subject is doing the opening, so use the present participle: ''Opening the door, he walked into the room.''"}, {"correct": true, "sentence": "Written in 1945, the novel is still widely read today.", "explanation": "Correct! Past participle clause — the novel was written, so the passive participle is right."}, {"correct": false, "sentence": "Arriving late, his colleagues were unimpressed.", "explanation": "Wrong — dangling participle! It was he who arrived late, not his colleagues. Try: ''Arriving late, he found his colleagues were unimpressed.''"}]', NULL, NULL, NULL, NULL, NULL, '2026-02-26 08:26:39.264638+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('6f7904de-1298-4f6c-a3e2-c855bddfeab9', 881, 'sentence_auction', 'C1', 'grammar', 'Theme: Cleft sentences — It was... / What I need is...', 'auction', '[{"correct": true, "sentence": "It was in 2005 that she first visited Japan.", "explanation": "Correct! It was + focus element + that — a classic cleft structure for emphasis."}, {"correct": true, "sentence": "What I need is more time to prepare.", "explanation": "Correct! What-cleft — ''what I need'' is the subject, ''more time'' is the complement."}, {"correct": true, "sentence": "What surprised me most was his reaction.", "explanation": "Correct! What-cleft used to focus on the subject — clean and emphatic."}, {"correct": false, "sentence": "What I told him was the true.", "explanation": "Wrong — ''true'' is an adjective; the noun is ''truth'': ''What I told him was the truth.''"}, {"correct": true, "sentence": "It was her idea that was suggested first.", "explanation": "Correct! It was + noun phrase + relative clause — putting the focus on her idea."}]', NULL, NULL, NULL, NULL, NULL, '2026-02-26 08:26:39.264638+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('1e23a1c2-f96a-49d1-8e85-217d16a64b9b', 882, 'sentence_auction', 'C1', 'grammar', 'Theme: Wish, if only, as if — unreal and hypothetical', 'auction', '[{"correct": true, "sentence": "I wish I knew the answer.", "explanation": "Correct! Wish + past simple for a present wish — I don''t know the answer now."}, {"correct": true, "sentence": "I wish I had studied harder at school.", "explanation": "Correct! Wish + past perfect for a past regret — I can''t change it now."}, {"correct": false, "sentence": "If only I would have more time!", "explanation": "Wrong — never use ''would'' after ''wish'' or ''if only'': ''If only I had more time!''"}, {"correct": true, "sentence": "If only she would listen to me!", "explanation": "Correct! Wish/if only + would + infinitive is used to express irritation about someone else''s behaviour."}, {"correct": true, "sentence": "They acted as though nothing had happened.", "explanation": "Correct! As though + past perfect — describing how they behaved after an event."}, {"correct": true, "sentence": "He speaks to her as if she was a small child.", "explanation": "Correct! Both ''was'' and ''were'' are accepted after ''as if'' in modern English."}]', NULL, NULL, NULL, NULL, NULL, '2026-02-26 08:26:39.264638+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('9337fdb2-f1d5-4578-8e65-33d40f70a14c', 883, 'sentence_auction', 'C1', 'grammar', 'Theme: Dependent prepositions — the right preposition after adjectives and verbs', 'auction', '[{"correct": true, "sentence": "She has a real talent for languages.", "explanation": "Correct! ''Talent for'' is the right collocation."}, {"correct": false, "sentence": "He is very keen of classical music.", "explanation": "Wrong — it''s ''keen on'': ''He is very keen on classical music.''"}, {"correct": true, "sentence": "I''m not familiar with this software.", "explanation": "Correct! ''Familiar with'' — the right dependent preposition."}, {"correct": true, "sentence": "She takes pride in her work.", "explanation": "Correct! ''Take pride in'' — a fixed collocation."}, {"correct": false, "sentence": "He is responsible of the marketing team.", "explanation": "Wrong — it''s ''responsible for'': ''He is responsible for the marketing team.''"}, {"correct": true, "sentence": "They are committed to improving customer service.", "explanation": "Correct! ''Committed to'' + gerund — ''to'' here is a preposition, not part of an infinitive."}]', NULL, NULL, NULL, NULL, NULL, '2026-02-26 08:26:39.264638+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('1e4e1c8e-fd82-4f58-9130-2e6d0cd6b306', 845, 'error_correction', 'B2', 'grammar', 'He is the kind of person who enjoy talking to new people.', 'He is the kind of person who enjoys talking to new people.', '[]', NULL, NULL, NULL, NULL, 'The relative pronoun "who" refers back to "person" (singular), so the verb must agree: "a person who enjoys". The relative clause takes its number from the noun, not "who".', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('4b62db4f-940e-46d5-a0e5-7bfaac256de5', 833, 'error_correction', 'A2', 'grammar', 'I have 25 years old.', 'I am 25 years old.', '["I''m 25 years old."]', NULL, NULL, NULL, NULL, 'In English, we use "to be" to talk about age: "I am 25 years old." Spanish speakers often say "I have 25 years" — a direct translation that sounds weird in English!', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('039428a4-f420-4852-9b21-72b06737f3ba', 841, 'error_correction', 'B1', 'grammar', 'I wish I would more free time.', 'I wish I had more free time.', '[]', NULL, NULL, NULL, NULL, '"I wish + past simple" expresses a wish about the present: "I wish I had more time." Using "would" after "wish" is a very common mistake — but "I wish I had" is the correct form. But, we often say "I wish you/he/she/etc would..."', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('353d65e3-2287-4b94-b08d-f1dc940082a9', 884, 'sentence_auction', 'C1', 'grammar', 'Theme: Formal writing — professional English', 'auction', '[{"correct": true, "sentence": "The proposal was discussed at length by the board.", "explanation": "Correct! Formal passive — appropriate for professional writing."}, {"correct": false, "sentence": "We would like to apologise for any inconveniences caused.", "explanation": "Wrong — ''inconvenience'' is uncountable in this context: ''...for any inconvenience caused.''"}, {"correct": true, "sentence": "Please do not hesitate to contact us.", "explanation": "Correct! Standard formal phrase — and note, it''s ''contact us'', not ''contact with us''."}, {"correct": false, "sentence": "We are writing with regards to your recent complaint.", "explanation": "Wrong — the formal phrase is ''with regard to'' (no s): ''We are writing with regard to your complaint.''"}, {"correct": true, "sentence": "Further information is available on request.", "explanation": "Correct! Clean, formal construction — passive without an unnecessary agent."}, {"correct": false, "sentence": "Please don''t hesitate to contact with us.", "explanation": "Wrong — ''contact'' is a transitive verb. No preposition needed: ''Please don''t hesitate to contact us.''"}]', NULL, NULL, NULL, NULL, NULL, '2026-02-26 08:26:39.264638+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('45b08b84-9c3f-4064-9f91-76e5a87992a2', 828, 'error_correction', 'A1', 'grammar', 'She don''t like the cold.', 'She doesn''t like the cold.', '[]', NULL, NULL, NULL, NULL, 'With he, she, or it in the present simple, we use "doesn''t" (does not), not "don''t" (do not). She doesn''t like cold.', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('ab728d23-3512-42ab-a0dc-243f6f37c4a2', 885, 'sentence_auction', 'C2', 'grammar', 'Theme: Discourse markers — connecting ideas accurately', 'auction', '[{"correct": true, "sentence": "Nevertheless, the results were disappointing.", "explanation": "Correct! ''Nevertheless'' = despite this — used to introduce a contrasting point."}, {"correct": false, "sentence": "Despite of the rain, we enjoyed the trip.", "explanation": "Wrong — it''s ''despite'' + noun (no ''of'') or ''in spite of'' + noun: ''Despite the rain, we enjoyed the trip.''"}, {"correct": true, "sentence": "Furthermore, the study reveals a significant correlation.", "explanation": "Correct! ''Furthermore'' adds another point — formal and appropriate here."}, {"correct": false, "sentence": "In spite the challenges, the team succeeded.", "explanation": "Wrong — it''s ''in spite of'', not ''in spite'': ''In spite of the challenges, the team succeeded.''"}, {"correct": true, "sentence": "Consequently, the project was delayed by three weeks.", "explanation": "Correct! ''Consequently'' = as a result — used to signal a cause-effect relationship."}, {"correct": true, "sentence": "However, we must acknowledge the limitations.", "explanation": "Correct! ''However'' introduces a contrasting point — and ''must'' + infinitive is right."}]', NULL, NULL, NULL, NULL, NULL, '2026-02-26 08:26:39.264638+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('d13b46c6-9cfa-4677-a0fa-2a3d19230889', 886, 'sentence_auction', 'C1', 'grammar', 'Theme: Third and mixed conditionals — past regrets and present consequences', 'auction', '[{"correct": true, "sentence": "If she had studied harder, she would have passed the exam.", "explanation": "Correct! Third conditional — past unreal condition, past unreal result."}, {"correct": true, "sentence": "If he hadn''t moved abroad, he would be living here now.", "explanation": "Correct! Mixed conditional — past condition with a present result."}, {"correct": false, "sentence": "If I would have known, I would have helped.", "explanation": "Wrong — never use ''would'' in the if-clause: ''If I had known, I would have helped.''"}, {"correct": true, "sentence": "She would be a doctor now if she had chosen medicine.", "explanation": "Correct! Mixed conditional — the past choice has a present-day consequence."}, {"correct": false, "sentence": "If it hadn''t rained, we would had a great picnic.", "explanation": "Wrong — the result clause needs ''would have'': ''...we would have had a great picnic.''"}]', NULL, NULL, NULL, NULL, NULL, '2026-02-26 08:26:39.264638+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('95ec8712-aeb9-4c37-b7d6-e7b297653279', 887, 'sentence_auction', 'C1', 'grammar', 'Theme: Collocations — the right verb with the right noun', 'auction', '[{"correct": true, "sentence": "She made a great effort to finish on time.", "explanation": "Correct! ''Make an effort'' is the right collocation."}, {"correct": false, "sentence": "He did a serious mistake during the presentation.", "explanation": "Wrong — we ''make'' a mistake, not ''do'' one: ''He made a serious mistake.''"}, {"correct": true, "sentence": "The company made a significant profit last year.", "explanation": "Correct! ''Make a profit'' is the standard collocation."}, {"correct": true, "sentence": "She made great progress in her studies.", "explanation": "Correct! ''Make progress'' — another fixed collocation."}, {"correct": false, "sentence": "She did progress in her studies.", "explanation": "Wrong — we ''make'' progress, not ''do'' it: ''She made great progress in her studies.''"}, {"correct": true, "sentence": "He took full responsibility for the error.", "explanation": "Correct! ''Take responsibility'' is the right collocation — accept it, own it."}]', NULL, NULL, NULL, NULL, NULL, '2026-02-26 08:26:39.264638+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('04d2f57f-2fa0-4be8-84a7-b7bd899ca8ec', 831, 'error_correction', 'A2', 'vocabulary', 'I am very boring at this party.', 'I am very bored at this party.', '[]', NULL, NULL, NULL, NULL, '"Boring" describes something that causes boredom (the party is boring). "Bored" describes how you feel (I am bored). If you say "I am boring", people might agree — but that is not what you want!', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('092b9fd9-cd38-44fe-b0c4-52ac2b777b87', 834, 'error_correction', 'A2', 'grammar', 'He plays tennis very good.', 'He plays tennis very well.', '[]', NULL, NULL, NULL, NULL, '"Good" is an adjective (a good player). "Well" is the adverb (he plays well). Use adverbs to describe how you do something. (I do these exercises very well ''fandandgo''!)', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('892c6372-b5f0-4073-ab67-59a79c376a06', 837, 'error_correction', 'A2', 'vocabulary', 'Can you say me the time, please?', 'Can you tell me the time, please?', '[]', NULL, NULL, NULL, NULL, 'In English, we "tell someone something" but "say something". "Can you tell me the time?" — not "say me". A small but very common mistake!', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('ca9c5ad4-5a97-4ba0-89eb-c68fd0ff231c', 842, 'error_correction', 'B1', 'grammar', 'The contract must be finish by the end of the month.', 'The contract must be finished by the end of the month.', '[]', NULL, NULL, NULL, NULL, 'In passive constructions with modal verbs, we need "be + past participle, the third column": must be finished, should be completed, will be delivered.', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('9795b842-8997-4122-8baf-67ed04fcfc7b', 843, 'error_correction', 'B2', 'grammar', 'He admitted to steal the money.', 'He admitted to stealing the money.', '[]', NULL, NULL, NULL, NULL, 'Certain verbs are followed by a gerund (-ing), not an infinitive. "Admit to doing something" is the correct pattern: He admitted to stealing the money. Maybe don''t admit to doing it until they show you proof 😉.', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('f27e32f8-6641-4d4c-a2f6-202b5c037ca3', 844, 'error_correction', 'B1', 'grammar', 'She has been working here since three years.', 'She has been working here for three years.', '[]', NULL, NULL, NULL, NULL, 'Use "for" with a duration (for three years, for a long time). Use "since" with a specific point in time (since 2020, since Monday). Three years is a duration, not a point in time.', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('1ce4f287-a567-4e92-8083-e8f6fedc1233', 669, 'sentence_building', 'C2', 'inversion', 'Solo cuando perdemos algo nos damos cuenta de su verdadero valor.', 'only when we lose something do we realise its true value', '["only", "when", "we", "lose", "something", "do", "we", "realise", "its", "true", "value", "does", "lost", "it", "really"]', '["we only realise its true value when we lose something"]', 'With this word order there is no need for the auxiliary verb ''do''', NULL, NULL, 'Only when + clause + inverted main clause. Emphatic structure.
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('57a3b995-1a93-4bc7-b416-f5f12877cf05', 846, 'error_correction', 'B2', 'grammar', 'The manager suggested that we would start the meeting earlier.', 'The manager suggested that we should start the meeting earlier.', '[]', NULL, NULL, NULL, NULL, '"Suggest + that + should" is the formal pattern in British English: "suggested that we should start..." Using "would" here is incorrect. Note: the subjunctive (suggest we start) is also acceptable.', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('d94804b0-80be-40bf-8ca8-1d8a77fc6eb8', 850, 'error_correction', 'C2', 'grammar', 'The bill has laid before parliament for three weeks.', 'The bill has lain before parliament for three weeks.', '[]', NULL, NULL, NULL, NULL, 'The verb "lie" (to be in a horizontal position / to exist somewhere) is intransitive. Past participle: lain. "Lay" is transitive (to place something). "The bill has lain before parliament" = it has been there. It suggests inactivity, in this case on the part of parliament.', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('f1514f60-ee44-4a12-861a-7f7475e4a01d', 851, 'error_correction', 'C1', 'vocabulary', 'The CEO inferred in her speech that redundancies were likely.', 'The CEO implied in her speech that redundancies were likely.', '[]', NULL, NULL, NULL, NULL, 'Speakers "imply" (hint at something without stating it). Listeners "infer" (draw a conclusion). The CEO was speaking, so she implied — the audience inferred. A very common mix-up, even among native speakers!', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('c312f99a-2035-4f9e-a3c8-30ec54d2c2b4', 640, 'sentence_building', 'A2', 'question_forms', '', 'do you want to come with us', '["do", "you", "want", "to", "come", "with", "us", "are", "going"]', NULL, NULL, NULL, NULL, 'For present simple questions we use ''do'' + subject + verb. ''Want to'' is followed by the infinitive: ''want to come''.', '2026-02-13 08:00:10.850224+00', NULL, NULL, 'en', '{"Question form"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('2969d7a3-ec60-4e90-9c95-117c5b984981', 853, 'error_correction', 'C1', 'vocabulary', 'He made a complement about her presentation skills.', 'He made a compliment about her presentation skills.', '[]', NULL, NULL, NULL, NULL, 'A "compliment" (noun) is a positive remark about someone. A "complement" (noun) is something that completes or enhances something else. Remember: E is for ''extra'' it adds something: good wine complements the meal.', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('4bdc985c-2468-4109-9a2b-15071dc6d438', 854, 'error_correction', 'C1', 'vocabulary', 'She is adverse to taking any financial risks.', 'She is averse to taking any financial risks.', '[]', NULL, NULL, NULL, NULL, '"Averse to" means reluctant or unwilling. "Adverse" means harmful or unfavourable (adverse conditions, adverse effects). "Risk-averse" is a common business term — not "risk-adverse".', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('578f1a5c-1c54-41ca-90cc-f6e7d448902d', 855, 'error_correction', 'C1', 'vocabulary', 'The principle cause of the project failure was poor communication.', 'The principal cause of the project failure was poor communication.', '[]', NULL, NULL, NULL, NULL, '"Principal" as an adjective means "main" or "most important". "Principle" is a noun meaning a rule or belief. "The principal cause" = the main cause. "A core principle" = a fundamental belief.', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('a629ca4f-35de-481e-823c-6f8f119edac6', 856, 'error_correction', 'C1', 'vocabulary', 'The new regulation will effect thousands of small businesses.', 'The new regulation will affect thousands of small businesses.', '[]', NULL, NULL, NULL, NULL, '"Affect" is the verb (to have an impact on), usually. "Effect" is usually the noun (the result or impact). "The regulation will affect businesses" — and its "effect" may be significant. A notoriously tricky pair, native speakers make lots of mistakes!', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('5ed68428-ec20-4cff-b29c-710afdd75785', 857, 'error_correction', 'C2', 'grammar', 'The report alluded several serious failures in the inspection process.', 'The report identified several serious failures in the inspection process.', '[]', NULL, NULL, NULL, NULL, '"Allude" must be followed by "to": "alluded to several failures." Without "to", the sentence is ungrammatical. If "to" is missing and cannot be added, the verb should change — "identified" works cleanly here, though there are other options too.', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('c354be3f-958a-4ff2-8f4d-85fcb07f9c23', 1185, 'sentence_building', 'A1', 'routines', 'Me despierto a las siete todos los días.', 'I wake up at seven o''clock every day.', '["I", "wake", "up", "at", "seven", "o''clock", "every", "day", "wakes", "morning", "goes"]', NULL, NULL, NULL, NULL, 'Wake up is a phrasal verb meaning to stop sleeping. Use the present simple for regular daily routines.', '2026-03-16 09:04:17.945706+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('c032d188-2dfc-4256-b6d8-c3e02d9797f1', 1186, 'sentence_building', 'A1', 'routines', 'Ella siempre desayuna antes de trabajar.', 'She always has breakfast before work.', '["she", "always", "has", "breakfast", "before", "work", "have", "after", "never", "eat"]', NULL, NULL, NULL, NULL, 'Frequency adverbs like always go before the main verb, not after it.', '2026-03-16 09:04:17.945706+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('7f763dc4-d4be-47b9-9f65-8cc25026de92', 628, 'sentence_building', 'A2', 'question_forms', '¿Cuánto cuesta esto?', 'how much does this cost', '["how", "much", "does", "this", "cost", "is", "do"]', '["how much is this"]', 'A different way of translating, less formal.', NULL, NULL, 'We use ''how much'' + does + subject + verb to ask about prices. ''How much does this cost?''', '2026-02-13 08:00:10.850224+00', NULL, NULL, 'both', '{"Question form"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('5beab43c-be83-47dc-9574-e3e9690bb1b2', 849, 'error_correction', 'C1', 'grammar', 'She was reluctant to accepting the offer without legal advice.', 'She was reluctant to accept the offer without legal advice.', '[]', NULL, NULL, NULL, NULL, '"Reluctant to + infinitive" is the correct structure: "reluctant to accept". "Reluctant in" does not exist as a pattern in English.', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('6670f943-7958-48d6-9820-1f69852b1dbb', 847, 'error_correction', 'B1', 'past_tenses
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('4b1f57d0-b01d-4460-a745-85361c161bc5', 1023, 'gap_fill', 'C2', 'vocabulary', 'The new CEO has worked hard to _______ the company''s public image following last year''s scandal.', 'rehabilitate', NULL, NULL, NULL, '["restore", "rebuild", "repair"]', 'To restore (a reputation) — bring it back to good standing.', 'To rehabilitate an image means to restore it after damage — to make it credible and respected again. Rebuild and restore are close synonyms.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Business vocabulary"}', false, 'Re- (again) + habit (state) = bring back to a good state.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('4ade00a8-ae1d-4a2f-90a4-c88efce1a34b', 1187, 'sentence_building', 'A2', 'routines', 'Normalmente vamos al gimnasio los lunes.', 'We usually go to the gym on Mondays.', '["we", "usually", "go", "to", "the", "gym", "on", "Mondays", "going", "at", "sometimes"]', NULL, NULL, NULL, NULL, 'Use the present simple for regular habits and routines. Usually goes before the main verb.', '2026-03-16 09:04:17.945706+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('71dcf71c-b30a-4f7c-ad9f-1c3286af12f2', 1749, 'gap_fill', 'C1', 'sport', 'After an intense yoga session, her muscles felt sore but she also felt a deep sense of _____ — calm, clear, and completely present.', 'mindfulness', NULL, NULL, NULL, NULL, 'The mental state of full presence and awareness — the goal of meditative practice.', 'Mindfulness means being fully aware of the present moment — your thoughts, feelings, and physical sensations — without judgement. It is central to yoga and meditation practice. Compare: awareness (noticing what is happening), presence (being mentally here rather than distracted), relaxation (physical release of tension). Mindfulness is now widely used in psychology, education, and business.', '2026-03-30 08:52:38.502672+00', NULL, NULL, 'en', '{}', false, 'Single word. Starts with m___.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('0073a9be-7266-4efd-b949-118d6af7cc7f', 1024, 'gap_fill', 'C2', 'vocabulary', 'The report identified a number of serious _______ in the organisation''s financial reporting.', 'shortcomings', NULL, NULL, NULL, '["irregularities", "deficiencies", "weaknesses"]', 'Flaws or weaknesses — areas where something falls short.', 'Shortcomings are weaknesses or failures to meet a required standard. In formal reports, shortcomings is more precise than problems or mistakes.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Business vocabulary"}', false, 'Compound noun: short + comings.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('a37968bd-004b-4aa7-8e53-0ebef9d2b015', 1750, 'gap_fill', 'C1', 'sport', 'The coach built the periodisation plan around the concept of _____ overload — gradually increasing training stress to force the body to adapt.', 'progressive', NULL, NULL, NULL, NULL, 'Gradually increasing — moving forward in steps.', 'Progressive overload is the principle that the body adapts to a given training stimulus, so training must be progressively increased in volume, intensity, or complexity to continue producing gains. It underpins all effective strength and endurance training programmes, from beginner running plans to elite weightlifting. Without progressive overload, performance plateaus.', '2026-03-30 08:52:38.502672+00', NULL, NULL, 'en', '{}', false, 'Single word. Starts with p___.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('28bd7821-4f70-4f91-bdca-2a5d73bcfac8', 1025, 'gap_fill', 'C2', 'vocabulary', 'His initial reluctance to accept the terms of the deal was eventually _______ by a revised offer.', 'overcome', NULL, NULL, NULL, '["addressed", "resolved"]', 'To defeat or surmount (an obstacle, reluctance).', 'To overcome reluctance means to succeed despite it — the obstacle is conquered rather than avoided. Compare: address = to deal with something directly; resolve = to find a solution.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Business vocabulary"}', false, 'Form: be ___ by + something.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('33add3bd-2cb4-4c05-ae96-a1be83b6a6f1', 1026, 'gap_fill', 'C2', 'vocabulary', 'The legislation was criticised for being _______ — it failed to address the root causes of the problem.', 'superficial', NULL, NULL, NULL, '["inadequate", "piecemeal", "insufficient"]', 'Only on the surface — not deep enough to address root causes.', 'Superficial means dealing only with the surface of a problem — lacking depth or substance. Legislation can be criticised as superficial if it fails to tackle root causes.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Business vocabulary"}', false, 'Super- (above) + facial = above the face.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('eae7ed9f-9950-402b-8905-6afe1b0f842c', 1027, 'multiple_choice', 'A1', 'prepositions', 'I usually wake up _______ seven o''clock in the morning.', 'at', '["at", "in", "on", "by"]', NULL, NULL, NULL, 'Clock times take this preposition.', 'Use at with specific times: at seven o''clock, at noon, at midnight, at 3pm. Use in with parts of the day: in the morning, in the evening. Use on with days and dates.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Preposition of time"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('1bc161ba-7a1d-451b-a350-1853faac8a08', 1029, 'multiple_choice', 'A1', 'prepositions', 'My birthday is _______ the 14th of March.', 'on', '["on", "at", "in", "by"]', NULL, NULL, NULL, 'Specific dates take this preposition.', 'Use on with specific dates and named days: on the 14th of March, on Monday, on Christmas Day. Use in with months, years, and seasons: in March, in 2024, in summer.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Preposition of time"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('c59f08b7-bd96-4f4c-861f-b8950dc9eb86', 630, 'sentence_building', 'A2', 'question_forms', '¿Puedo tener un vaso de agua?', 'can I have a glass of water', '["can", "I", "have", "cup", "a", "glass", "of", "water", "do", "the"]', NULL, NULL, NULL, NULL, '''Can I have...?'' is a polite way to ask for something. We say ''a glass of water'' not ''a glass with water''.', '2026-02-13 08:00:10.850224+00', NULL, NULL, 'both', '{"Question form"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('16ab6170-cd4a-447e-af7a-b76a47c61e52', 623, 'sentence_building', 'A2', 'question_forms', '¿Dónde está la estación de tren?', 'where is the train station', '["where", "trains", "is", "the", "train", "station", "are", "do"]', NULL, NULL, NULL, NULL, 'For questions with ''where'', the word order is: Where + is/are + subject. ''Where is the train station?''', '2026-02-13 08:00:10.850224+00', NULL, NULL, 'both', '{"Question form"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('832673cc-4bb4-44a9-9d33-b2a3b0f0f17c', 1188, 'sentence_building', 'A1', 'routines', 'Él nunca toma café por la tarde.', 'He never drinks coffee in the evening.', '["he", "never", "drinks", "coffee", "in", "the", "evening", "morning", "always", "drink"]', NULL, NULL, NULL, NULL, 'Never is a negative frequency adverb — no additional negative verb form is needed.', '2026-03-16 09:04:17.945706+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('725be44b-ef9a-459a-8038-5f188d06243d', 1189, 'sentence_building', 'A2', 'routines', 'Me cepillo los dientes dos veces al día.', 'I brush my teeth twice a day.', '["I", "brush", "my", "teeth", "twice", "a", "day", "once", "clean", "daily"]', NULL, NULL, NULL, NULL, 'Twice a day means two times per day. Use the present simple for personal routines.', '2026-03-16 09:04:17.945706+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('7446e6b7-83f1-463f-9b02-2177b8eec4a6', 1107, 'gap_fill', 'C1', 'business_vocabulary', 'The regulator found the company guilty of _______ — fixing prices in secret with a competitor.', 'collusion', NULL, NULL, NULL, NULL, 'Secret cooperation between rivals — the word shares a root with "collude".', 'Collusion means secret cooperation between companies to fix prices or manipulate markets — illegal in most jurisdictions and a serious breach of competition law.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Business vocabulary","Financial vocabulary"}', false, 'When two companies that should compete are secretly working together.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('f06b5a11-dde8-4734-8b3a-d412da328c69', 1112, 'gap_fill', 'C2', 'business_vocabulary', 'A company that holds a dominant market position and abuses it to prevent competition may be accused of being a _______.', 'monopoly', NULL, NULL, NULL, NULL, 'The board game is named after this — one player controls everything.', 'A monopoly exists when one company dominates a market so completely that competition is effectively eliminated. Regulators can investigate and break up monopolies.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Business vocabulary","Financial vocabulary"}', false, 'Mono- means "one". Think Standard Oil before 1911.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('8efbee93-88f2-4560-b57d-e563d2d5db0a', 1113, 'gap_fill', 'C2', 'business_vocabulary', 'The aggressive acquisition strategy resulted in significant _______, making the business complex and difficult to manage.', 'overexpansion', NULL, NULL, NULL, '["overdiversification"]', 'The prefix and suffix do most of the work — going *too far* with growth.', 'Overexpansion means growing too quickly or into too many areas — resulting in a business that is complex, inefficient, and difficult to manage profitably.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Business vocabulary"}', false, NULL, 'noun');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('8f5dd7ee-a97b-48d9-9589-3fff5d8a8ce1', 1114, 'gap_fill', 'C2', 'business_vocabulary', 'The board commissioned an independent _______ review to assess whether each business unit was delivering sufficient shareholder value.', 'strategic', NULL, NULL, NULL, '["portfolio"]', 'The kind of review that looks at the big picture, not the daily operations.', 'A strategic review (or portfolio review) assesses each part of a business to decide which units to invest in, maintain, or sell off. It is typically commissioned by the board.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Business vocabulary",Collocation}', false, NULL, 'adjective');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('85e05c38-6b22-4d4e-a1ea-51c91010cc7d', 1030, 'multiple_choice', 'A1', 'prepositions', 'She lives _______ a small flat in the centre of the city.', 'in', '["in", "at", "on", "inside"]', NULL, NULL, NULL, 'Inside an enclosed space (a flat, a box).', 'Use in with enclosed spaces — rooms, buildings, cities, countries: in a flat, in London, in Spain. Use at for specific locations or points: at the door, at the station.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Preposition of place"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('9c466ebd-1f03-445c-bbfc-22c689465b7c', 1031, 'multiple_choice', 'A1', 'prepositions', 'The keys are _______ the table in the kitchen.', 'on', '["on", "in", "at", "above"]', NULL, NULL, NULL, 'On a horizontal surface.', 'Use on for surfaces — things resting on top of something: on the table, on the floor, on the wall. Use in for things inside a container or enclosed space.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Preposition of place"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('b186bc25-fa90-4d8c-b703-9edaf57c0563', 1032, 'multiple_choice', 'A2', 'prepositions', 'We drove _______ the tunnel to get to the other side of the mountain.', 'through', '["through", "across", "over", "past"]', NULL, NULL, NULL, 'Entering one end and exiting the other.', 'Through means entering one side and exiting the other — used for enclosed spaces like tunnels, forests, and buildings. Compare: across = moving from one side to the other of an open surface.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Preposition of movement"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('845db5a9-0b44-41be-9756-88033d086225', 1033, 'multiple_choice', 'A2', 'prepositions', 'She''s been working at this company _______ 2018.', 'since', '["since", "for", "from", "during"]', NULL, NULL, NULL, '"2018" is a starting point, not a duration.', 'Since refers to a specific point in time when something started and is still continuing: since 2018. For refers to a duration: for six years. Both are used with the present perfect.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Preposition of time","Confusable words"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('62742ac6-c568-4f14-a40c-1c87b48a36f8', 1034, 'multiple_choice', 'A2', 'prepositions', 'He walked _______ the bridge and stopped to look at the river below.', 'across', '["across", "through", "around", "under"]', NULL, NULL, NULL, 'From one side to the other — over the bridge.', 'Across means from one side to the other of an open surface — a bridge, a road, a room. Compare: through = passing inside something enclosed; along = following the length of something.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Preposition of movement"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('a0c0134e-fe49-4d5a-b5f8-80b3e60f4cfa', 1035, 'multiple_choice', 'A2', 'prepositions', 'The train leaves _______ ten minutes — you need to hurry!', 'in', '["in", "at", "after", "by"]', NULL, NULL, NULL, '"After X minutes from now" → ___.', 'In ten minutes means after a period of ten minutes has passed — it refers to a future moment. Compare: at ten minutes past = a specific clock time.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Preposition of time"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('f28cf70c-43c1-4ca2-b010-0483068fdaa9', 1036, 'multiple_choice', 'A2', 'prepositions', 'My flat is _______ the third floor.', 'on', '["on", "at", "in", "by"]', NULL, NULL, NULL, 'For floors of buildings — same preposition as for "the menu".', 'Use on with floors of a building: on the third floor, on the ground floor. In British English, the ground floor is the bottom floor; the first floor is above it.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Preposition of place"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('c062d7e1-3f22-44d6-815d-9daa007d0824', 1037, 'multiple_choice', 'B1', 'prepositions', 'I''m really interested _______ learning how to cook Thai food.', 'in', '["in", "for", "with", "at"]', NULL, NULL, NULL, 'Always: "interested ___ + something".', 'Interested in is a fixed collocation — the preposition is always in. Compare: keen on, enthusiastic about, passionate about — each adjective has its own fixed preposition.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Dependent preposition"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('d6b89237-32c6-4948-ba45-1f04a866cddf', 1038, 'multiple_choice', 'B1', 'prepositions', 'She''s very good _______ dealing with difficult clients — she always stays calm.', 'at', '["at", "in", "for", "with"]', NULL, NULL, NULL, 'Always: "good ___ + something".', 'Good at is a fixed collocation — the preposition is always at. Compare: skilled in, experienced in, capable of — different adjectives require different prepositions.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Dependent preposition"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('0768b195-d1d9-45a6-aa13-80064ffc61e2', 1039, 'multiple_choice', 'B1', 'prepositions', 'He apologised _______ being late and explained what had happened.', 'for', '["for", "on", "of", "to"]', NULL, NULL, NULL, 'Always: "apologise ___ + something".', 'Apologise for is the correct collocation — the preposition is always for. You apologise for an action: for being late, for the delay, for the mistake.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Dependent preposition"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('82da67e5-759d-4cbb-be37-f930f1968176', 1040, 'multiple_choice', 'B2', 'prepositions', 'The report was criticised _______ a lack of evidence and poor methodology.', 'for', '["for", "by", "about", "with"]', NULL, NULL, NULL, 'Always: "criticised ___ + something".', 'Criticised for means the reason for criticism is introduced with for. Compare: criticised by = identifies who is doing the criticising.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Dependent preposition"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('47158ccd-0ade-4e2e-b689-e6b867fc7d95', 1041, 'multiple_choice', 'B2', 'prepositions', 'The decision to expand was made _______ consultation with the board.', 'in', '["in", "for", "to", "by"]', NULL, NULL, NULL, 'Phrase: "___ consultation with".', 'In consultation with is a fixed phrase meaning after discussing with. The decision was made in consultation with the board = the board was involved in the process.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Fixed expression","Business vocabulary"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('7b7fe222-88b3-45f4-a5c5-751b4429c6d7', 305, 'multiple_choice', 'A2', 'present_simple', 'How often ___ your sister exercise?', 'does', '["do", "does", "are", "is"]', NULL, NULL, NULL, 'Question with "your sister" — needs the 3rd-person auxiliary.', 'Frequency questions with you: How often do you...?', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Present tense"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('2164033a-50a1-499b-95d9-ef24efc02e05', 302, 'multiple_choice', 'A1', 'present_simple', '___ they live in Valencia?', 'Do', '["Does", "Do", "Are", "Is"]', NULL, NULL, NULL, 'Question with "they" — needs an auxiliary.', 'Questions with they/we/I/you: Do + subject + base verb.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Present tense"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('abf9c510-bbb8-4f97-91c8-1668f7b44288', 211, 'gap_fill', 'A2', 'present_simple', 'What time ___ the film start?', 'does', NULL, NULL, NULL, NULL, 'Question form for he/she/it.', 'Questions about schedules: does + subject + base verb.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Present tense"}', false, '___ + subject + verb?', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('13cb3f67-5e68-4ffc-ad4f-17ab8ef8539e', 303, 'multiple_choice', 'A1', 'present_simple', 'I ___ coffee every morning.', 'drink', '["drinks", "am drink", "drink", "drinking"]', NULL, NULL, NULL, 'I/you/we/they don''t add -s.', 'With I/you/we/they: use the base verb without -s.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Present tense"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('2fb85f67-1f8f-492e-ae3e-8bb0a98dfb2b', 304, 'multiple_choice', 'A1', 'present_simple', 'She ___ to work by bus.', 'goes', '["go", "goes", "going", "is go"]', NULL, NULL, NULL, 'She + verb in 3rd person — add -s.', 'Third person: go → goes (add -es after -o).', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Present tense"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('76f4dd83-6b61-4293-b7c9-5c24ae303f29', 306, 'multiple_choice', 'A1', 'present_simple', 'He ___ like fish.', 'doesn''t', '["don''t", "doesn''t", "isn''t", "aren''t"]', NULL, NULL, NULL, 'He + negative — uses an auxiliary.', 'Third person negative: doesn''t + base verb.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Present tense"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('7300ab1a-fa78-4a27-951f-24a43b5c9e0f', 307, 'multiple_choice', 'A1', 'present_simple', 'We ___ dinner at 8 pm.', 'have', '["has", "have", "having", "are have"]', NULL, NULL, NULL, 'We don''t add -s. Same as "I have".', 'With we: use have (not has).', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Present tense"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('a0a43e8e-8054-4707-9218-7d1124a693ca', 1042, 'gap_fill', 'B1', 'prepositions', 'She''s very keen _______ joining the project — she asked me about it again this morning.', 'on', NULL, NULL, NULL, NULL, 'Always: "keen ___ + -ing".', 'Keen on is a fixed collocation. Other similar expressions: interested in, enthusiastic about, passionate about. Each adjective takes a specific preposition.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Dependent preposition"}', false, 'Same preposition as in "set ___ doing" something.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('e3b6b5f8-dde1-4adb-a383-16a4e55796b0', 1043, 'gap_fill', 'B1', 'prepositions', 'I''m not very good _______ remembering names, but I never forget a face.', 'at', NULL, NULL, NULL, NULL, 'Always: "good ___ + -ing".', 'Good at is fixed. The preposition at is used with skills and abilities: good at maths, bad at cooking, terrible at remembering names.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Dependent preposition"}', false, 'Same as in "interested ___" — pairs with abilities.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('119cc318-be1b-42df-9348-10375087420f', 1044, 'gap_fill', 'B2', 'prepositions', 'The new policy came _______ force on the first of January.', 'into', NULL, NULL, NULL, NULL, 'Phrase: "come ___ force" = take effect.', 'Come into force is a fixed legal and formal phrase meaning to officially start taking effect. A law or policy comes into force on a specific date.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Fixed expression","Business vocabulary"}', false, 'Movement preposition.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('08ef2fca-7500-4151-b07d-663f60d8f92b', 1233, 'multiple_choice', 'A1', 'business_phrasal_verbs', 'I need to _____ the report before the deadline tomorrow.', 'hand in', '["hand in", "hand out", "hand over", "hand back"]', NULL, NULL, NULL, 'To submit (homework, a report) — give to someone in authority.', 'Hand in means to give a piece of work to someone in authority, such as a manager or teacher.', '2026-03-18 19:58:52.376507+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('1add9515-9e10-4286-9145-be0de10c2650', 674, 'error_correction', 'B1', 'present_perfect', 'She has been working here since five years.', 'She has been working here for five years.', '[]', NULL, NULL, NULL, NULL, 'Use "for" with a duration (five years). Use "since" with a point in time (since 2020).', '2026-02-20 19:09:17.848852+00', NULL, NULL, 'en', '{"Present tense"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('2ef0557b-c715-4d40-93cb-95c928e61b1f', 323, 'multiple_choice', 'A2', 'present_continuous', 'We ___ dinner with friends tonight.', 'are having', '["have", "having", "are having", "has"]', NULL, NULL, NULL, '"Tonight" — already arranged plan.', 'Present continuous for future arrangements.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Present tense"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('8ac6d39e-429d-4507-ad51-d0db647bf52a', 324, 'multiple_choice', 'A1', 'present_continuous', '___ it raining outside?', 'Is', '["Does", "Do", "Is", "Are"]', NULL, NULL, NULL, 'Question with "it" — short verb first.', 'Questions: Is/Are + subject + verb-ing?', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Present tense"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('ed8ed719-4fb1-4cc1-8929-7a6f89df6cea', 1989, 'sentence_building', 'B1', 'travel', 'Me gustaría mejorar mi asiento.', 'I would like to upgrade my seat.', '["I", "would", "like", "to", "upgrade", "my", "seat", "want", "change", "move", "get", "class"]', NULL, NULL, NULL, NULL, '"Would like to + infinitive" is a polite way to make a request. "Upgrade" means to move to a better seat or class.', '2026-04-13 09:19:30.039983+00', NULL, NULL, 'en', '{Travel}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('6225a313-235b-41ed-a9f6-ec44a5720171', 1990, 'sentence_building', 'B1', 'travel', 'Mi equipaje se perdió durante el vuelo.', 'My luggage got lost during the flight.', '["my", "luggage", "got", "lost", "during", "the", "flight", "bag", "was", "trip", "baggage", "on"]', NULL, NULL, NULL, NULL, '"Got lost" is an informal passive meaning it became lost. "Luggage" and "baggage" are both uncountable nouns meaning the same thing.', '2026-04-13 09:19:30.039983+00', NULL, NULL, 'en', '{Travel}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('1c11cad2-360d-43b0-a120-273587589e45', 62, 'gap_fill', 'B1', 'present_perfect_for_since', 'I''ve known her ___ (for / since) ten years.', 'for', NULL, NULL, NULL, NULL, 'For is used with a period of time', 'For is used with a period or duration of time.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{"Present tense"}', false, 'For ten years, for two weeks, for ages — a duration.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('9f7bdbd2-73c6-4d1f-a6b7-d19389cdab40', 101, 'multiple_choice', 'B1', 'present_perfect', 'I ___ to Paris three times this year.', 'have been', '["was", "go", "went", "have been"]', NULL, NULL, NULL, 'Three times THIS YEAR — the year isn''t over yet, so we''re still in the same time period.', 'Present perfect with unfinished time period (''this year'').', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{"Present tense"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('0debcb3d-b6e1-4182-814d-75a5a1cd362f', 108, 'multiple_choice', 'B1', 'present_perfect_for_since', 'They''ve been married ___ ten years.', 'for', '["while", "for", "during", "since"]', NULL, NULL, NULL, 'Ten years is a duration, not a starting point.', 'For with duration (ten years); since with point in time.', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{"Present tense"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('dceae340-7ffd-4442-b83c-903095ae8d08', 130, 'multiple_choice', 'B1', 'present_continuous_future', 'I ___ my grandparents this weekend.', 'am visiting', '["visit", "am visiting", "will visit", "visited"]', NULL, NULL, NULL, 'An arranged future plan — already in the diary.', 'Present continuous for fixed future arrangements.', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{"Present tense"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('d3e3f97a-718f-45f9-a521-abc0876fac72', 139, 'multiple_choice', 'B1', 'present_simple_habits', 'She ___ to the gym three times a week.', 'goes', '["go", "goes", "is going", "went"]', NULL, NULL, NULL, 'Habitual action with "she" — don''t forget the -s.', 'Present simple for regular habits.', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{"Present tense"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('1f9519a7-7d1b-4725-a2dc-1ea1e17ef3bb', 145, 'multiple_choice', 'B1', 'present_perfect_just', 'I ___ finished my homework.', 'have just', '["justly", "have just", "am just", "was just"]', NULL, NULL, NULL, '"Just" sits between have/has and the past participle.', 'Present perfect with just for recently completed actions.', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{"Present tense"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('f6c5dd82-4b65-4696-a414-c5d54c2ec82f', 183, 'multiple_choice', 'B1', 'present_perfect_yet', 'Have you finished your homework ___?', 'yet', '["already", "yet", "just", "still"]', NULL, NULL, NULL, 'Asking about completion in present perfect — sits at the end of the question.', 'Yet in questions (expecting completion). If you used already here it would indicate surprise at how quickly it was completed.', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{"Present tense"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('e4f685bd-a066-45f2-baeb-3ad91780e773', 189, 'multiple_choice', 'B1', 'present_simple_routines', 'What time ___ to bed on weekdays?', 'do you go', '["are you going", "do you go", "go you", "you go"]', NULL, NULL, NULL, 'Present simple question: do/does + subject + verb.', 'Present simple questions for routines.', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{"Present tense"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('0313df94-795a-495a-b034-ee87503a7ddd', 204, 'gap_fill', 'A1', 'present_simple', '___ you speak English?', 'Do', NULL, '["Can...speak", "Can speak"]', NULL, NULL, 'Question with "you" — needs an auxiliary verb.', 'Questions in present simple: Do + subject + base verb.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Present tense"}', false, 'Do/does + subject + verb.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('f586b85e-28a3-477e-8c5c-d5df5ecd8348', 221, 'gap_fill', 'A2', 'present_continuous', 'We ___ (not go) out tonight.', 'aren''t going', NULL, NULL, NULL, NULL, 'We → aren''t + verb-ing.', 'Negative present continuous for changed plans.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Present tense"}', false, 'Aren''t = are not.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('f99cec28-4271-48aa-a70e-02664384f24b', 222, 'gap_fill', 'A1', 'present_continuous', 'The children ___ (swim) in the pool.', 'are swimming', NULL, NULL, NULL, NULL, 'The children = they → are + verb-ing.', 'Double the final consonant: swim → swimming.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Present tense"}', false, 'Swim → swimming (the m doubles).', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('3cabf6b8-b0f9-40fb-aeb5-961d50e64a99', 223, 'gap_fill', 'A2', 'present_continuous', 'I ___ (learn) Spanish this year.', 'am learning', NULL, NULL, NULL, NULL, '"This year" — ongoing action right now.', 'Present continuous for ongoing situations around now.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Present tense"}', false, 'Form: am/is/are + verb-ing.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('e1cc002d-c26c-4692-abff-f5128cae8f99', 325, 'multiple_choice', 'A2', 'present_continuous', 'Why ___ she crying?', 'is', '["does", "do", "is", "are"]', NULL, NULL, NULL, 'Question with "she" — short verb.', 'Why + is + she + verb-ing for present continuous questions.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Present tense"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('8d15b2b5-abc3-462c-8c18-bc3073fd06a3', 1045, 'gap_fill', 'B2', 'prepositions', 'He resigned _______ protest after the board rejected his proposal for the third time.', 'in', NULL, NULL, NULL, NULL, 'Phrase: "___ protest" = as a form of protest.', 'Resign in protest is a fixed phrase — the preposition is in. In protest means as a formal expression of disagreement or objection.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Fixed expression"}', false, 'Same as in "___ silence", "___ secret".', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('ed0904e8-5850-46d2-99fa-d5af1e4eeb72', 1046, 'gap_fill', 'B2', 'prepositions', 'The deal was agreed _______ principle, but the details still need to be finalised.', 'in', NULL, NULL, NULL, NULL, 'Phrase: "agreed ___ principle" = agreed in general.', 'Agreed in principle means the main idea has been accepted, but the specific details still need to be worked out and confirmed.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Fixed expression","Business vocabulary"}', false, 'Same as in "___ theory".', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('64f4893a-eb57-4f46-b776-6bc63faf9cdd', 1991, 'sentence_building', 'B2', 'travel', 'Tengo que cambiar dinero antes de salir.', 'I need to exchange some money before leaving.', '["I", "need", "to", "exchange", "some", "money", "before", "leaving", "change", "cash", "going", "any"]', NULL, NULL, NULL, NULL, '"Exchange money" is the standard phrase for converting currency. "Before + -ing" is used when both actions have the same subject.', '2026-04-13 09:19:30.039983+00', NULL, NULL, 'en', '{Travel}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('a430a1e6-da76-49e5-a328-6027281cc4a1', 1993, 'sentence_building', 'B1', 'travel', 'Se olvidó de imprimir la tarjeta de embarque.', 'She forgot to print her boarding pass.', '["she", "forgot", "to", "print", "her", "boarding", "pass", "remember", "his", "ticket", "download", "card"]', NULL, NULL, NULL, NULL, '"Forget + to + infinitive" means to not remember to do something. Compare: "forget + -ing" refers to a past memory.', '2026-04-13 09:19:30.039983+00', NULL, NULL, 'en', '{Travel}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('2b15a209-2b0c-4854-a268-1164d6ae773a', 1994, 'sentence_building', 'B2', 'travel', 'Les pidieron que mostraran los pasaportes otra vez.', 'They were asked to show their passports again.', '["they", "were", "asked", "to", "show", "their", "passports", "again", "told", "present", "once", "documents"]', NULL, NULL, NULL, NULL, '"Were asked to + infinitive" is a passive structure. It is more neutral than "were told to," which sounds like a stronger order.', '2026-04-13 09:19:30.039983+00', NULL, NULL, 'en', '{Travel}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('10806ccc-0a47-4136-b026-3e8e4c4343c2', 1995, 'sentence_building', 'B2', 'travel', 'Siempre viajo con poco equipaje cuando voy al extranjero.', 'I always travel light when I go abroad.', '["I", "always", "travel", "light", "when", "I", "go", "abroad", "pack", "lightly", "overseas", "with"]', NULL, NULL, NULL, NULL, '"Travel light" is a fixed phrase meaning to travel with minimal luggage. "Abroad" means to or in a foreign country — no preposition needed after "go."', '2026-04-13 09:19:30.039983+00', NULL, NULL, 'en', '{Travel}', true, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('bdd5d41f-10d1-42c9-9cd6-46ad0448de49', 1998, 'sentence_building', 'C1', 'travel', 'Conseguimos facturar en el último momento.', 'We managed to check in at the last minute.', '["we", "managed", "to", "check", "in", "at", "the", "last", "minute", "moment", "were", "able", "just"]', NULL, NULL, NULL, NULL, '"Managed to + infinitive" suggests difficulty but success. "At the last minute" means just before the deadline.', '2026-04-13 09:19:30.039983+00', NULL, NULL, 'en', '{Travel}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('8dfec030-a5c6-4191-809a-12e8418e6eaa', 1999, 'sentence_building', 'C1', 'travel', 'Le apartaron para un control de seguridad adicional.', 'He was pulled aside for additional security screening.', '["he", "was", "pulled", "aside", "for", "additional", "security", "screening", "extra", "stopped", "taken", "check"]', NULL, NULL, NULL, NULL, '"Be pulled aside" means to be separated from others for individual attention. "Screening" is the process of checking passengers for prohibited items.', '2026-04-13 09:19:30.039983+00', NULL, NULL, 'en', '{Travel}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('e5661bd5-4cb4-4b4e-933a-940b92571714', 2000, 'sentence_building', 'C1', 'travel', 'La aerolínea se negó a compensarnos por el retraso.', 'The airline refused to compensate us for the delay.', '["the", "airline", "refused", "to", "compensate", "us", "for", "the", "delay", "pay", "denied", "reimburse", "cancellation"]', NULL, NULL, NULL, NULL, '"Refuse + to + infinitive" means to say no to doing something. "Compensate for" = to pay or make up for a loss or inconvenience.', '2026-04-13 09:19:30.039983+00', NULL, NULL, 'en', '{Travel}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('2daa3c9f-41d7-4aa8-a3a7-f9f71a132ba6', 682, 'error_correction', 'A1', 'present_simple', 'She go to school every day.', 'She goes to school every day.', '[]', NULL, NULL, NULL, NULL, 'Third person singular (she/he/it) needs "goes" in the present simple.', '2026-02-20 19:09:17.848852+00', NULL, NULL, 'en', '{"Present tense"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('1043b62f-accf-44a5-b2c2-dc4a5dabb428', 672, 'error_correction', 'A1', 'present_continuous', 'They is playing football.', 'They are playing football.', '[]', NULL, NULL, NULL, NULL, '"They" takes "are", not "is".', '2026-02-20 19:09:17.848852+00', NULL, NULL, 'en', '{"Present tense"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('5529b445-ab6a-4554-9208-a07c94fe26c1', 690, 'error_correction', 'A1', 'present_simple', 'We lives in a big house.', 'We live in a big house.', '[]', NULL, NULL, NULL, NULL, '"We" takes the base form "live", not "lives".', '2026-02-20 19:09:17.848852+00', NULL, NULL, 'en', '{"Present tense"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('53416d30-6598-41d2-b7bf-35cfc82b754e', 2001, 'sentence_building', 'C2', 'travel', 'Viajar con poco equipaje es más fácil de decir que de hacer.', 'Travelling light is easier said than done.', '["travelling", "light", "is", "easier", "said", "than", "done", "travel", "easy", "being", "more", "hard"]', NULL, NULL, NULL, NULL, '"Easier said than done" is a fixed idiom meaning something sounds simple but is difficult in practice.', '2026-04-13 09:19:30.039983+00', NULL, NULL, 'en', '{Travel}', true, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('01cabd7b-3352-4806-93e9-f3b8181011fd', 1992, 'sentence_building', 'B1', 'travel', 'Tuvimos que esperar tres horas para embarcar.', 'We had to wait three hours to board', '["we", "had", "to", "wait", "three", "hours", "to", "board", "for", "boarding", "waited", "four"]', NULL, NULL, NULL, NULL, '"Had to + infinitive" expresses past necessity. "To board" is the infinitive — the verb meaning to get on the plane.', '2026-04-13 09:19:30.039983+00', NULL, NULL, 'en', '{Travel}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('1e3dbc4f-8dec-45fc-bec2-6bf8948d7753', 677, 'odd_one_out', 'B1', 'past_participles', 'Which is NOT a past participle?', 'spoke', '["written", "spoke", "played", "broken"]', NULL, NULL, NULL, NULL, '"Spoke" is the past simple. The past participle is "spoken".', '2026-02-20 19:09:17.848852+00', NULL, NULL, 'en', '{"Past tense"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('b52cf27d-7547-42c4-b639-f716e94f7f7a', 214, 'gap_fill', 'A2', 'present_simple', 'How often ___ you exercise?', 'do', NULL, NULL, NULL, NULL, 'Question with "you" — needs an auxiliary.', 'Frequency questions: How often + do + subject + verb.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Present tense"}', false, '___ + you + verb?', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('acdb8a3d-408d-492b-9acc-8cc9e7de625e', 1997, 'sentence_building', 'C1', 'travel', 'El vuelo estaba sobrevendido y la dejaron fuera.', 'The flight was overbooked so they bumped her off.', '["the", "flight", "was", "overbooked", "so", "they", "bumped", "her", "off", "cancelled", "removed", "denied", "him"]', NULL, NULL, '[{"answer": "The flight was overbooked so they bumped him off", "feedback": ""}, {"answer": "The flight was overbooked so they bumped her", "feedback": ""}, {"answer": "The flight was overbooked so they bumped him", "feedback": ""}]', NULL, '"Bump someone off a flight" means to remove a passenger because the flight was overbooked. "Overbooked" = more tickets sold than seats available.', '2026-04-13 09:19:30.039983+00', NULL, NULL, 'en', '{Travel}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('f3dc7038-a6eb-4298-b34c-fb240fce6a06', 226, 'gap_fill', 'A2', 'past_simple', 'I ___ (go) to London last year.', 'went', NULL, NULL, NULL, NULL, '"Last year" — past simple.', 'Go is irregular: go → went → gone.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Past tense"}', false, 'Go → went. (Irregular!)', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('a91212c9-39cc-4e49-a553-94cd30c4eb3e', 229, 'gap_fill', 'A2', 'past_simple', '___ you enjoy the concert last week?', 'Did', NULL, NULL, NULL, NULL, 'Past question — auxiliary first.', 'Past simple questions: Did + subject + base verb.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Past tense"}', false, '___ + subject + base verb?', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('bc4378a6-2760-417b-b6ba-2ebd3d5c1faa', 326, 'multiple_choice', 'A2', 'past_simple', 'I ___ to the cinema last night.', 'went', '["go", "went", "going", "gone"]', NULL, NULL, NULL, '"Last night" — past simple. Go is irregular.', 'Go is irregular: go → went. Use past form for past events.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Past tense"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('60f563e1-6b72-4668-875e-c20fc6ec9713', 1047, 'gap_fill', 'C1', 'prepositions', 'The two parties reached an agreement _______ the basis of mutual compromise.', 'on', NULL, NULL, NULL, NULL, 'Phrase: "___ the basis of" = based on.', 'On the basis of is a fixed formal phrase meaning using something as the foundation or reason for a decision or agreement.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Fixed expression","Business vocabulary"}', false, 'Same as in "___ the assumption that...".', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('1e44fc4e-70ae-41e6-ae41-147a59ecd012', 1048, 'gap_fill', 'C1', 'prepositions', 'Her success is testament _______ years of dedicated preparation.', 'to', NULL, NULL, NULL, NULL, 'Phrase: "testament ___ + something" = evidence of.', 'Testament to is a fixed phrase meaning clear evidence or proof of something: Her success is testament to years of hard work.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Fixed expression"}', false, 'Same as in "tribute ___" or "monument ___".', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('111805ce-2657-4ae4-9ee1-557764e4ddab', 1049, 'gap_fill', 'C1', 'prepositions', 'The government was accused _______ acting in bad faith during the negotiations.', 'of', NULL, NULL, NULL, NULL, 'Always: "accused ___ + -ing".', 'Accused of is fixed — the preposition is always of. You accuse someone of a specific act: accused of fraud, accused of acting in bad faith.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Dependent preposition"}', false, 'Same preposition as in "guilty ___".', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('f68ab317-9aac-4b17-9762-03167695acd8', 1050, 'gap_fill', 'C1', 'prepositions', 'The merger fell _______ at the final hurdle due to regulatory concerns.', 'through', NULL, NULL, NULL, NULL, 'Phrasal: "fall ___" = collapse, fail.', 'Fall through means to fail or collapse — particularly a deal, plan, or negotiation. The at the final hurdle phrase means it failed at the very last stage.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Phrasal verb","Fixed expression"}', false, 'As if dropping through the floor.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('739cc1b5-c441-43ee-bfc2-f7f0d6c974b8', 2002, 'sentence_building', 'C1', 'travel', 'Le dijeron que su visado había caducado.', 'She was told her visa had expired.', '["she", "was", "told", "her", "visa", "had", "expired", "informed", "passport", "cancelled", "ran", "out"]', NULL, NULL, NULL, NULL, '"Was told + clause" is a passive reporting structure. "Had expired" is past perfect — the visa had already expired before she found out.', '2026-04-13 09:19:30.039983+00', NULL, NULL, 'en', '{Travel}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('9db424c2-c75f-4386-b91e-5d61db331d7e', 605, 'sentence_building', 'B1', 'past_simple', 'El director aprobó el presupuesto ayer por la tarde.', 'the director approved the budget yesterday afternoon', '["the", "director", "approved", "the", "budget", "yesterday", "afternoon", "rejected", "morning", "manage"]', NULL, NULL, NULL, NULL, '"Approved" = aprobó (past simple for completed past action). "Yesterday afternoon" = ayer por la tarde.', '2026-02-12 15:08:31.507807+00', NULL, NULL, 'both', '{"Past tense"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('b31aa93e-333a-4a9e-afd6-267efa347391', 2, 'gap_fill', 'B1', 'past_simple', 'We ___ (meet) at university in 2015 and we''ve been friends ever since.', 'met', NULL, NULL, NULL, NULL, 'This happened at a specific time in the past', 'Past simple is used for completed actions at a specific time in the past.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{"Past tense"}', false, 'The time marker "in 2015" anchors it firmly in the past.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('8fa5f8f1-67b2-48ea-84a8-c593c9e9c9af', 102, 'multiple_choice', 'B1', 'past_simple', 'She ___ her job two months ago.', 'left', '["has left", "left", "leaves", "is leaving"]', NULL, NULL, NULL, '"Two months ago" anchors it firmly in a finished past time.', 'Past simple for completed action at specific time (''two months ago'').', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{"Past tense"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('5a41f461-7b6d-40ad-b74e-de540909c975', 114, 'multiple_choice', 'B2', 'past_perfect', 'When I got to the station, the train ___.', 'had already left', '["already left", "has already left", "had already left", "was already leaving"]', NULL, NULL, NULL, 'One past action happened *before* another. The train left first; you arrived later.', 'Past perfect shows which of two past actions happened first.', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{"Past tense"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('1df5395e-8799-4fd9-8c58-ac7e545f906d', 162, 'multiple_choice', 'B1', 'past_continuous', 'What ___ at 8 o''clock last night?', 'were you doing', '["did you do", "were you doing", "have you done", "do you do"]', NULL, NULL, NULL, 'Action in progress at a specific past time + question word order.', 'Past continuous for actions in progress at specific past time.', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{"Past tense"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('7ce5a51f-b014-4e46-8c88-41b85248696d', 227, 'gap_fill', 'A2', 'past_simple', 'She ___ (not see) the film yesterday.', 'didn''t see', NULL, NULL, NULL, NULL, 'Past negative — didn''t + base verb.', 'Past simple negative: didn''t + base verb (not the past form).', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Past tense"}', false, 'Didn''t = did not. The verb stays in its base form.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('80202748-af2b-49fb-a9b9-38f484d48bdc', 230, 'gap_fill', 'A2', 'past_simple', 'He ___ (buy) a new car last month.', 'bought', NULL, NULL, NULL, NULL, '"Last month" — past simple.', 'Buy is irregular: buy → bought → bought.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Past tense"}', false, 'Buy → bought. Irregular.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('76f224d8-24d7-4dd7-988f-bad379419658', 231, 'gap_fill', 'A2', 'past_simple', 'They ___ (arrive) at the hotel at midnight.', 'arrived', NULL, NULL, NULL, NULL, 'Past simple of "arrive" — regular verb.', 'Regular past simple: add -ed. Verbs ending in -e: just add -d.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Past tense"}', false, 'Verb + -d (or -ed) for regular past simple.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('d164a468-cd27-4979-8a70-9465c5f8711c', 233, 'gap_fill', 'A2', 'past_simple', 'She ___ (meet) her husband in 2015.', 'met', NULL, NULL, NULL, NULL, '"In 2015" — past simple.', 'Meet is irregular: meet → met → met.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Past tense"}', false, 'Meet → met. Irregular.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('0a57db4c-c3fd-498b-bbd9-183a20c3f877', 234, 'gap_fill', 'A2', 'past_simple', 'The restaurant ___ (open) last Friday.', 'opened', NULL, NULL, NULL, NULL, '"Last Friday" — past simple, regular verb.', 'Regular past simple: add -ed to the base verb.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Past tense"}', false, 'Verb + -ed.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('f6cb27cb-bc71-47ca-b35e-9456d90187af', 327, 'multiple_choice', 'A2', 'past_simple', 'She ___ her keys yesterday.', 'lost', '["lose", "lost", "losed", "losing"]', NULL, NULL, NULL, '"Yesterday" — past simple. Lose is irregular.', 'Lose is irregular: lose → lost → lost.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Past tense"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('3f973436-f9e2-486d-a785-bf8ad8303339', 328, 'multiple_choice', 'A2', 'past_simple', '___ you enjoy the party?', 'Did', '["Do", "Did", "Was", "Were"]', NULL, NULL, NULL, 'Past question — needs an auxiliary.', 'Past simple questions: Did + subject + base verb.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Past tense"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('f2e273d4-ba12-42aa-acdb-706a4aecc7ba', 329, 'multiple_choice', 'A2', 'past_simple', 'We ___ TV last evening.', 'watched', '["watch", "watched", "watching", "watches"]', NULL, NULL, NULL, '"Last evening" — past simple. Watch is regular.', 'Regular past simple: add -ed to the base verb.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Past tense"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('a450a45b-a5aa-42b1-b290-b9afaab82194', 330, 'multiple_choice', 'A2', 'past_simple', 'He ___ speak to me at the party.', 'didn''t', '["don''t", "doesn''t", "didn''t", "wasn''t"]', NULL, NULL, NULL, 'Past negative — needs an auxiliary.', 'Past simple negative: didn''t + base verb.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Past tense"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('4d2fe1ea-41d2-4362-af9a-01199d96100f', 331, 'multiple_choice', 'A2', 'past_simple', 'They ___ married in 2018.', 'got', '["get", "got", "getting", "gets"]', NULL, NULL, NULL, 'Past simple — "got married" is the standard phrase.', 'Get is irregular: get → got. Past events with specific dates.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Past tense"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('b2fa88fc-b9f3-453b-8f7e-6399b7a77cbb', 769, 'multiple_choice', 'B2', 'be_used_to', '"She ___ working overtime — she does it every week without complaining."', 'is used to', '["is used to", "used to", "was used to", "gets used to"]', NULL, NULL, NULL, 'She''s accustomed to it — does it regularly.', '"Be used to + -ing" means something is familiar and no longer difficult. "Used to + infinitive" describes past habits. She is used to working overtime = it''s normal for her.', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{"Past tense"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('3eccf293-2f22-46f3-a6ac-74e8c1b7f8a4', 1051, 'gap_fill', 'C1', 'prepositions', 'He was _______ the verge of resigning when the company offered him a promotion.', 'on', NULL, NULL, NULL, NULL, 'Phrase: "___ the verge of" = about to.', 'On the verge of means on the point of — very close to doing something, usually significant: on the verge of resigning, on the verge of bankruptcy.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Fixed expression"}', false, 'Same as in "___ the brink of".', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('0f7cce3f-9f9b-49fc-ae6e-40a0813ba115', 1052, 'gap_fill', 'C2', 'prepositions', 'The new law applies _______ retrospect — it affects decisions made before it was passed.', 'in', NULL, NULL, NULL, NULL, 'Phrase: "___ retrospect" = looking back.', 'In retrospect is a fixed phrase meaning when looking back at past events with the knowledge you have now. Retroactively and retrospectively are related adverbs.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Fixed expression"}', false, 'Latin: retro (back) + specere (look).', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('696a5692-1596-412f-bb6b-0dd194a438fc', 2003, 'sentence_building', 'C1', 'travel', 'Al final perdieron el transbordo en Ámsterdam.', 'They ended up missing their connection in Amsterdam.', '["they", "ended", "up", "missing", "their", "connection", "in", "Amsterdam", "flight", "caught", "losing", "transfer"]', NULL, NULL, NULL, NULL, '"End up + -ing" describes an unplanned or undesirable result. "Miss a connection" means to arrive too late to board the next flight.', '2026-04-13 09:19:30.039983+00', NULL, NULL, 'en', '{Travel}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('36aa0fbf-d098-4c30-9c39-f2c2b5341cd1', 685, 'error_correction', 'B1', 'be_used_to', 'I am used to get up early.', 'I am used to getting up early.', '[]', NULL, NULL, NULL, NULL, '"Be used to" + verb -ing form when talking about habits you''re accustomed to/typically do.', '2026-02-20 19:09:17.848852+00', NULL, NULL, 'en', '{"Past tense"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('3087888b-2146-40fd-aafc-471399de5c6e', 2004, 'sentence_building', 'C1', 'travel', 'La aerolínea nos alojó en un hotel.', 'The airline put us up in a hotel.', '["the", "airline", "put", "us", "up", "in", "a", "hotel", "gave", "placed", "booked", "accommodation"]', NULL, NULL, NULL, NULL, '"Put someone up" means to provide temporary accommodation. It is commonly used when a company arranges a place to stay for stranded passengers.', '2026-04-13 09:19:30.039983+00', NULL, NULL, 'en', '{Travel}', true, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('bb98c10f-9f41-472f-a2ad-e43bc5d9c9e6', 2005, 'sentence_building', 'C2', 'travel', 'Consiguió pasar por la aduana sin ningún problema.', 'He talked his way through customs without any issues.', '["he", "talked", "his", "way", "through", "customs", "without", "any", "issues", "got", "past", "problems", "charm"]', NULL, NULL, NULL, NULL, '"Talk your way through" means to use persuasion or words to get through a difficult situation. "Customs" is where officers check what you are bringing into a country.', '2026-04-13 09:19:30.039983+00', NULL, NULL, 'en', '{Travel}', true, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('e9c12728-d3f2-419a-90c9-e76411d94c37', 14, 'gap_fill', 'B1', 'future_will', 'Don''t worry, I ___ (help) you with your bags.', 'will help', NULL, NULL, NULL, NULL, 'Spontaneous decision made at the moment of speaking', 'Will is used for spontaneous decisions and offers.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{"Future form"}', false, 'Will + infinitive — decision made now, not earlier.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('9755771b-01a8-4844-a2f9-1d57f0f8fb02', 104, 'multiple_choice', 'B1', 'future_continuous', 'Don''t call me at 7pm. I ___ dinner then.', 'will be having', '["will have", "will be having", "have", "am having"]', NULL, NULL, NULL, 'An action in progress at 7pm tomorrow — not just a single event.', 'Future continuous for action in progress at specific future time.', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{"Future form"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('cc9392cd-0144-484d-8b7d-ad1474faf06c', 1053, 'gap_fill', 'C2', 'prepositions', 'The committee concluded that the organisation had acted in accordance _______ all relevant guidelines.', 'with', NULL, NULL, NULL, NULL, 'Phrase: "in accordance ___ + rules".', 'In accordance with is a fixed formal phrase meaning in compliance with, or following the rules of. Common in legal and official language.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Fixed expression","Business vocabulary"}', false, 'Always paired with "with".', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('aae376ec-cc16-4f87-b124-067efd09743f', 1054, 'gap_fill', 'C2', 'prepositions', 'She spoke on behalf _______ all the employees when she raised the concerns.', 'of', NULL, NULL, NULL, NULL, 'Phrase: "on behalf ___ + group".', 'On behalf of is a fixed phrase meaning representing or acting for someone else: She spoke on behalf of all the employees.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Fixed expression"}', false, 'Always paired with "of".', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('5395a807-a009-4c7e-ae2d-35a2a923c499', 110, 'multiple_choice', 'B1', 'used_to', 'When I was a child, I ___ hate vegetables, but now I love them.', 'used to', '["was used to", "am used to", "use to", "used to"]', NULL, NULL, NULL, 'A habit you no longer have. Watch out for the look-alike "be used to".', 'Used to for past habits that are no longer true.', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{"Past tense"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('1c215f00-ac5f-43af-982e-7f2409b090bf', 154, 'multiple_choice', 'B1', 'future_simple_prediction', 'I think it ___ be sunny tomorrow.', 'will', '["is", "will", "is going to", "can"]', NULL, NULL, NULL, 'Personal prediction about the future ("I think...").', 'Will for predictions based on opinion (with ''think''). Contrast with going to for predictions based on evidence.', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{"Future form"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('9783e477-0b8b-4cee-a237-15b025097bd7', 168, 'multiple_choice', 'B2', 'future_perfect', 'By this time next year, I ___ my degree.', 'will have finished', '["will finish", "will have finished", "am finishing", "finish"]', NULL, NULL, NULL, 'Action completed BEFORE a future point. Form: will have + past participle.', 'Future perfect for actions completed by a future time.', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{"Future form"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('96dfc6ff-bd2a-401b-afe8-0d137d988deb', 177, 'multiple_choice', 'B1', 'going_to_intention', 'I ___ study medicine at university.', 'am going to', '["will", "am going to", "go to", "want"]', NULL, NULL, NULL, 'A planned future intention — already decided.', 'Going to for intentions and plans. Native speakers might use will in the same way, but in language teaching they push us to use going to for existing plans. ', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{"Future form"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('4e5575f7-076d-4fb8-8e43-0e95d78e77ef', 228, 'gap_fill', 'A2', 'past_simple', 'We ___ (have) a great time at the party last night.', 'had', NULL, NULL, NULL, NULL, '"Last night" — past simple.', 'Have is irregular: have → had → had.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Past tense"}', false, 'Have → had. Irregular.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('f2860a5d-f012-4cb3-bbca-5fb0934ed54d', 334, 'multiple_choice', 'A2', 'past_simple', 'She ___ the exam easily.', 'passed', '["pass", "passed", "passing", "past"]', NULL, NULL, NULL, 'Past simple of "pass" — regular.', 'Regular past simple: add -ed.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Past tense"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('9eee24a6-1f8d-4705-8ef9-a15e0be391a2', 335, 'multiple_choice', 'A2', 'past_simple', 'I ___ born in 1990.', 'was', '["am", "was", "were", "is"]', NULL, NULL, NULL, 'Past simple of "be" with "I".', 'Was born: I/he/she was born. We/they were born.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Past tense"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('4e29b0bb-49ee-45f9-ba22-dcf2692388e5', 336, 'multiple_choice', 'A2', 'past_simple', 'The film ___ at 8 o''clock.', 'started', '["start", "started", "starting", "starts"]', NULL, NULL, NULL, 'Past simple of "start" — regular.', 'Regular past simple for completed past actions.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Past tense"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('bf212e7f-3819-4d65-ae08-db1e863b3b71', 337, 'multiple_choice', 'A2', 'past_simple', 'We ___ a great holiday in Greece.', 'had', '["have", "has", "had", "having"]', NULL, NULL, NULL, 'Past simple of "have".', 'Have is irregular: have → had.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Past tense"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('38b05bc7-6b10-4372-be18-2433733d1f4b', 2006, 'sentence_building', 'C1', 'travel', 'Los retrasos nos dejaron varados en el aeropuerto toda la noche.', 'The delays left us stranded at the airport overnight.', '["the", "delays", "left", "us", "stranded", "at", "the", "airport", "overnight", "stuck", "night", "cancelled", "trapped"]', NULL, NULL, NULL, NULL, '"Leave + object + adjective" describes the result of a situation. "Stranded" = unable to leave a place. "Overnight" means for the whole night.', '2026-04-13 09:19:30.039983+00', NULL, NULL, 'en', '{Travel}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('7b238e0a-3f73-4392-8e73-b1b0af069640', 2007, 'sentence_building', 'A2', 'travel', 'I would like a room with a sea view.', 'Quisiera una habitación con vistas al mar.', '["quisiera", "una", "habitación", "con", "vistas", "al", "mar", "quiero", "vista", "ciudad", "piscina", "la"]', NULL, NULL, NULL, NULL, '"Quisiera" (conditional of querer) is more polite than "quiero." "Vistas al mar" = sea view. "Al" is a contraction of "a + el."', '2026-04-13 09:19:30.039983+00', NULL, NULL, 'es', '{Travel}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('b887b0e1-a9d3-49b5-bff5-898079218dad', 1055, 'gap_fill', 'C2', 'prepositions', 'The latest figures stand in stark contrast _______ the optimistic forecasts made last year.', 'to', NULL, NULL, NULL, NULL, 'Phrase: "in stark contrast ___ + something".', 'In stark contrast to is a fixed phrase meaning showing a very clear and strong difference. The preposition after contrast is always to or with.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Fixed expression"}', false, 'Same as "in opposition ___".', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('99cf345e-7417-4115-834d-49f6ab43df76', 1056, 'gap_fill', 'C2', 'prepositions', 'The proposal is in line _______ the company''s long-term sustainability goals.', 'with', NULL, NULL, NULL, NULL, 'Phrase: "in line ___ + something" = consistent with.', 'In line with is a fixed phrase meaning consistent with, or following the same direction as. Common in business and policy language.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Fixed expression","Business vocabulary"}', false, 'Always paired with "with".', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('e7cd320d-9192-4b5e-9f7b-236e36e24d53', 1057, 'multiple_choice', 'A1', 'business_phrasal_verbs', 'Can we _______ the meeting until Thursday? I have a conflict on Tuesday.', 'put off', '["put off", "put on", "put up", "put away"]', NULL, NULL, NULL, 'To postpone — push the date back.', 'To put off means to postpone — to move something to a later date. Compare: put on = to add or start something; put up = to tolerate or display.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Business phrasal verb"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('5a2a87cd-4022-484a-b3d7-d21177771c00', 1058, 'multiple_choice', 'A1', 'business_phrasal_verbs', 'We need to _______ new staff before the busy season starts.', 'take on', '["take on", "take off", "take up", "take over"]', NULL, NULL, NULL, 'To hire (new staff) — also: to accept (a new task).', 'To take on staff means to hire or employ new people. Take on can also mean to accept a responsibility or challenge.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Business phrasal verb","HR vocabulary"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('0546f1fb-09fc-4f05-8909-2b63ce0dec30', 113, 'multiple_choice', 'B1', 'articles', 'I play ___ piano in my free time.', 'the', '["a", "an", "the", "-"]', NULL, NULL, NULL, 'Musical instruments take a definite article. (But sports take none!)', 'Musical instruments take ''the''.', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{Article}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('456e70e4-0826-497c-b84a-0748a54952f3', 41, 'gap_fill', 'B1', 'articles', 'I need ___ (a / an / the) new phone. Mine is broken.', 'a', NULL, NULL, NULL, NULL, 'Indefinite article for unspecified things', 'A/an is used when mentioning something for the first time or when it''s not specific.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{Article}', false, 'First mention of something → use a/an.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('84ac64a4-264b-4f57-bdd2-c6b5a5d4e5e9', 42, 'gap_fill', 'B1', 'articles', 'Could you pass me ___ (a / an / the) salt, please?', 'the', NULL, NULL, NULL, NULL, 'Definite article when both know which one', 'The is used when both speaker and listener know which specific thing is being referred to.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{Article}', false, 'Both speakers know which one — there''s only one salt on the table.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('4ff4e7ad-b770-4379-a2c8-a777789ce45a', 45, 'gap_fill', 'B1', 'quantifiers', 'How ___ (many / much) people are coming to the party?', 'many', NULL, NULL, NULL, NULL, 'Many is used with countable nouns', 'Many is used with countable nouns.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{Quantifier}', false, 'People, books, cars — things you can count: 1, 2, 3.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('17b29d2a-b85f-416d-9576-3a59f0254c02', 115, 'multiple_choice', 'B1', 'quantifiers', 'There aren''t ___ people at the party yet.', 'many', '["much", "many", "a lot", "lots"]', NULL, NULL, NULL, 'People are countable: 1 person, 2 people. So not "much".', 'Many with countable nouns in negative sentences.', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{Quantifier}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('f8f731fb-4c3d-4657-b58a-f7ab533c35c2', 147, 'multiple_choice', 'B1', 'articles_geographical', 'Have you ever been to ___ United States?', 'the', '["a", "an", "the", "-"]', NULL, NULL, NULL, 'Countries with plural names take a definite article (the Netherlands, the Philippines, the UK).', 'The with country names containing plural nouns (States, Emirates, etc.).', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{Article}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('7a0daf4c-909c-4f4a-a91d-0b9d3bdf0bed', 164, 'multiple_choice', 'B1', 'quantifiers_some_any', 'We don''t have ___ milk. Can you buy some?', 'any', '["some", "any", "a", "one"]', NULL, NULL, NULL, 'Negative sentence + indefinite quantity.', 'Any in negative sentences and questions.', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{Quantifier}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('091d411a-6295-4eca-9c40-78c2304814aa', 241, 'gap_fill', 'A1', 'articles', 'She is ___ teacher.', 'a', NULL, NULL, NULL, NULL, 'First mention of a job — needs an indefinite article.', 'Use a before singular countable nouns starting with a consonant sound.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{Article}', false, 'Use "a" before a consonant sound: a teacher, a doctor.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('15ef2972-928c-4189-ac04-1ebdbda2f36c', 242, 'gap_fill', 'A1', 'articles', 'He is ___ engineer.', 'an', NULL, NULL, NULL, NULL, 'Engineer starts with a vowel sound.', 'Use an before words starting with a vowel sound: an engineer.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{Article}', false, 'Use "an" before vowel sounds: an engineer, an apple.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('f85e3e64-9875-495d-9c30-52a184238f36', 243, 'gap_fill', 'A2', 'articles', 'I want to visit ___ Eiffel Tower.', 'the', NULL, NULL, NULL, NULL, 'There''s only one Eiffel Tower — definite article.', 'Use the for famous landmarks and unique things.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{Article}', false, 'Use "the" for unique things.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('2e063dbd-85c6-4845-b456-5e8f334ac20f', 244, 'gap_fill', 'A1', 'articles', 'Can I have ___ glass of water?', 'a', NULL, NULL, NULL, NULL, 'First mention, countable noun.', 'Use a when asking for one of something.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{Article}', false, 'A glass = one glass.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('b7d12078-5a5e-4f64-a21b-910d409c5ed7', 245, 'gap_fill', 'A2', 'articles', '___ Amazon is the longest river in South America.', 'The', NULL, NULL, NULL, NULL, 'Rivers take a definite article.', 'Use the with rivers, oceans, and mountain ranges.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{Article}', false, 'The Amazon, the Nile, the Thames.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('33ab48ed-783f-43a5-875a-05e840645175', 246, 'gap_fill', 'A1', 'articles', 'There is ___ apple on the table.', 'an', NULL, NULL, NULL, NULL, 'Apple starts with a vowel sound.', 'Use an before words starting with a vowel sound.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{Article}', false, 'An apple, an orange, an idea.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('5d86e507-ad3c-43fa-b505-3faa337f7712', 248, 'gap_fill', 'A2', 'articles', 'She plays ___ guitar very well.', 'the', NULL, NULL, NULL, NULL, 'Musical instruments take a definite article.', 'Use the with musical instruments: play the guitar, play the piano.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{Article}', false, 'Play the guitar, play the piano, play the violin.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('689ad8b3-caa6-49f7-83d1-4b6ac5780654', 2150, 'gap_fill', 'C1', 'prepositions', 'The merger was carried out ___ accordance with the law.', 'in', '[]', NULL, NULL, NULL, '"___ accordance with" = following or complying with.', '"In accordance with" means following or complying with something.', '2026-06-01 07:16:29.304337+00', NULL, NULL, 'en', '{Preposition}', false, 'Two letters.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('23750d54-ea09-4904-9639-c2edde8a2034', 1060, 'multiple_choice', 'A1', 'business_phrasal_verbs', 'The CEO has decided to _______ early — he''ll leave the company next year.', 'step down', '["step down", "step back", "step out", "step up"]', NULL, NULL, NULL, 'To resign from a leadership position — step out of the role.', 'To step down means to resign from a senior position, usually voluntarily. The opposite — moving to a more senior role — is to step up.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Business phrasal verb","HR vocabulary"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('ca09327f-2ab7-4323-b2b6-b7b8ab4c2683', 1061, 'multiple_choice', 'A1', 'business_phrasal_verbs', 'We need to _______ the main points from today''s meeting and send them to the team.', 'write up', '["write up", "write out", "write down", "write off"]', NULL, NULL, NULL, 'To prepare in written form (notes, a report).', 'To write up means to produce a formal written record of something. Compare: write down = to make a quick note; write off = to dismiss something as a loss.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Business phrasal verb"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('ca953330-8f27-4482-9ae8-a3e5a31cedbd', 1062, 'multiple_choice', 'A2', 'business_phrasal_verbs', 'The new product launch really _______ — sales exceeded all our targets.', 'took off', '["took off", "took on", "took over", "took up"]', NULL, NULL, NULL, 'To suddenly become successful — like an aeroplane.', 'To take off means to become suddenly successful or popular. It also means to remove clothing, or for a plane to leave the ground.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Business phrasal verb"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('0ca683a7-196d-47f7-928b-56217c4b083f', 1234, 'multiple_choice', 'A2', 'business_phrasal_verbs', 'The project is _____ schedule — we need to work faster.', 'behind', '["behind", "under", "below", "off"]', NULL, NULL, NULL, '___ schedule — running late.', 'Behind schedule means later than planned. Compare: ahead of schedule (earlier than planned), on schedule (on time).', '2026-03-18 19:58:52.376507+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('13fabdc7-a4cd-4613-9a2a-38f13ecffd44', 1190, 'sentence_building', 'A1', 'routines', 'Cenan a las ocho.', 'They eat dinner at eight o''clock.', '["they", "eat", "dinner", "at", "eight", "o''clock", "have", "lunch", "seven", "eating"]', NULL, NULL, NULL, NULL, 'Use the present simple for a fixed daily routine. Eat dinner and have dinner are both correct.', '2026-03-16 09:04:17.945706+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('e3a25aa1-69ff-4362-8e4d-334e9a4a3ad9', 1191, 'sentence_building', 'A2', 'routines', 'A menudo leo antes de dormir.', 'I often read before going to sleep.', '["I", "often", "read", "before", "going", "to", "sleep", "after", "write", "fall"]', NULL, NULL, NULL, NULL, 'Before is a preposition here, so it is followed by a gerund: before going.', '2026-03-16 09:04:17.945706+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('df903c2b-8e60-4ba6-8b4c-0915538268e6', 1192, 'sentence_building', 'A1', 'routines', 'Mi madre cocina la cena todas las tardes.', 'My mother cooks dinner every evening.', '["my", "mother", "cooks", "dinner", "every", "evening", "cook", "lunch", "morning", "his"]', NULL, NULL, NULL, NULL, 'Third person singular (he/she/it) adds -s to the verb in the present simple: cooks, not cook.', '2026-03-16 09:04:17.945706+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('149485b9-e79c-40b0-bb34-22418822618e', 1193, 'sentence_building', 'A2', 'routines', '¿Siempre coges el mismo camino al trabajo?', 'Do you always take the same route to work?', '["do", "you", "always", "take", "the", "same", "route", "to", "work", "go", "usual", "different"]', NULL, NULL, NULL, NULL, 'Form present simple questions with Do/Does + subject + infinitive. Always goes after the subject.', '2026-03-16 09:04:17.945706+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('8cc4581b-5c4f-4a22-b2b9-b7eee51a6598', 1194, 'sentence_building', 'A2', 'routines', 'Ella sale a caminar después de comer.', 'She goes for a walk after lunch.', '["she", "goes", "for", "a", "walk", "after", "lunch", "go", "before", "run", "dinner"]', NULL, NULL, NULL, NULL, 'Go for a walk is a fixed expression. Third person singular: goes, not go.', '2026-03-16 09:04:17.945706+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('ad8608a1-033c-46ee-922f-51dd4f7c9dc0', 659, 'sentence_building', 'B2', 'wish_clauses', 'Ojalá me lo hubieras dicho antes.', 'I wish you had told me sooner', '["I", "wish", "you", "had", "told", "me", "sooner", "would", "have", "tell", "after", "later"]', NULL, NULL, NULL, NULL, 'I wish + past perfect: expressing regret about something that happened (or didn''t happen) in the past.', '2026-02-17 09:58:54.170896+00', NULL, NULL, 'en', '{"Wish & regret"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('5e5ac85b-5662-4975-931a-d0fde7164cb9', 1196, 'sentence_building', 'B1', 'routines', 'Lleva años siguiendo la misma rutina.', 'She has been following the same routine for years.', '["she", "has", "been", "following", "the", "same", "routine", "for", "years", "follow", "since", "doing", "daily"]', NULL, NULL, NULL, NULL, 'The present perfect continuous (has been following) describes a habit that started in the past and continues now. Use for, not since, with a period of time.', '2026-03-16 09:04:17.945706+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('b09fcafc-f49a-477a-8695-dcd9d12544ed', 1197, 'sentence_building', 'B2', 'routines', 'Estoy intentando adquirir el hábito de hacer ejercicio con regularidad.', 'I am trying to get into the habit of exercising regularly.', '["I", "am", "trying", "to", "get", "into", "the", "habit", "of", "exercising", "regularly", "exercise", "become", "build"]', NULL, NULL, NULL, NULL, 'Get into the habit of + gerund is a useful phrase for describing a new routine being established.', '2026-03-16 09:04:17.945706+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('6e10fde0-0cde-49c5-82c5-0db33958f056', 1198, 'sentence_building', 'B1', 'routines', 'A la mayoría de la gente le resulta difícil cambiar sus hábitos diarios.', 'Most people find it hard to change their daily habits.', '["most", "people", "find", "it", "hard", "to", "change", "their", "daily", "habits", "habit", "difficult", "routine", "very"]', NULL, NULL, NULL, NULL, 'Find it + adjective + to do something is a common structure: find it hard to, find it easy to, find it difficult to.', '2026-03-16 09:04:17.945706+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('e4735508-1259-415e-8877-d1d1119ba1c2', 148, 'multiple_choice', 'B1', 'both_neither_either', '___ of my parents speak English.', 'Both', '["One", "Both", "Either", "All"]', NULL, NULL, NULL, 'The two of them together — both speak English.', 'Both means the two together.', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{Quantifier}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('75e965d3-ffa1-4260-8a5c-c62496b0f4e8', 167, 'multiple_choice', 'B1', 'reflexive_pronouns', 'Did you enjoy ___ at the party?', 'yourself', '["you", "yourself", "yours", "your"]', NULL, NULL, NULL, 'Same person doing and receiving — "you" → ___.', 'Reflexive pronoun for ''enjoy yourself''.', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{Pronoun}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('bc3fa13d-7c7f-471a-9ed1-60b81c2c3294', 185, 'multiple_choice', 'B1', 'other_another', 'This shirt is too small. Can I try ___ one?', 'another', '["other", "another", "these other", "others"]', NULL, NULL, NULL, 'One more (different) of the same kind. (Not "other" — that needs "the".)', 'Another = one more (indefinite).', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{Quantifier}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('ffab7b80-b058-4740-8f99-a8cd0bab7d2d', 371, 'multiple_choice', 'A1', 'pronouns', 'This is my brother. ___ name is Carlos.', 'His', '["Its", "Her", "His", "He"]', NULL, NULL, NULL, 'Possessive — belonging to him (the brother).', 'His = belonging to a male person (my brother).', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{Pronoun}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('71b4936e-ff7c-4ce7-a2ae-4103bca5a01b', 372, 'multiple_choice', 'A1', 'pronouns', 'I love my cats. ___ are very friendly.', 'They', '["He", "She", "It", "They"]', NULL, NULL, NULL, 'Subject pronoun — replacing "the cats".', 'We don''t usually use it for animals.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{Pronoun}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('ffaf23e2-0c19-4d64-99dd-1b38031c198c', 532, 'multiple_choice', 'C1', 'idioms', 'She''s feeling under the ___ today so she stayed home.', 'weather', '["rain", "weather", "cloud", "storm"]', NULL, NULL, NULL, 'Feeling unwell — an idiom involving the sky.', 'Under the weather = feeling ill or unwell.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Fixed expression"}', true, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('fc950e85-73c2-4213-ab44-04d17a04f076', 646, 'sentence_building', 'A2', 'going_to_future', '', 'we are going to visit our grandparents next weekend', '["we", "are", "going", "to", "visit", "our", "grandparents", "next", "weekend", "visited", "last", "mine"]', '["next weekend we are going to visit our grandparents.", "we are going to our grandparents next weekend"]', 'If you put the time phrase at the end it is more natural. The ''visit'' isn''t necessary in this sentence, but it is normally used there.', NULL, NULL, 'Going to future: subject + be + going to + verb for planned actions.', '2026-02-17 09:58:54.170896+00', NULL, NULL, 'en', '{"Future form"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('db5fc6f5-3cba-44cd-a034-731df4ce231f', 2011, 'sentence_building', 'A2', 'travel', 'I need an extra pillow, please.', 'Necesito una almohada más, por favor.', '["necesito", "una", "almohada", "más", "por", "favor", "otra", "toalla", "manta", "quiero"]', NULL, NULL, NULL, NULL, '"Una almohada más" = one more pillow. "Más" after a noun means additional. "Toalla" = towel; "manta" = blanket.', '2026-04-13 09:19:30.039983+00', NULL, NULL, 'es', '{Travel}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('07e0f54e-f8ef-49b8-9fc0-5f1601e62463', 2013, 'sentence_building', 'A2', 'travel', 'I would like to book a taxi for the airport.', 'Quisiera reservar un taxi para el aeropuerto.', '["quisiera", "reservar", "un", "taxi", "para", "el", "aeropuerto", "quiero", "pedir", "la", "estación", "autocar"]', NULL, NULL, NULL, NULL, '"Quisiera + infinitive" = I would like to. "Reservar" = to book. "Aeropuerto" = airport; "estación" = station; "autocar" = coach.', '2026-04-13 09:19:30.039983+00', NULL, NULL, 'es', '{Travel}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('437af865-5d70-4c44-b5f4-15de29e4468d', 2010, 'sentence_building', 'A2', 'travel', 'Is there a swimming pool in the hotel?', 'Hay piscina en el hotel?', '["hay", "piscina", "en", "el", "hotel", "una", "tiene", "gimnasio", "spa", "restaurante"]', NULL, NULL, NULL, NULL, '"Hay" = there is/there are. No article is needed after "hay" in general questions. "Piscina" = pool; "gimnasio" = gym.', '2026-04-13 09:19:30.039983+00', NULL, NULL, 'es', '{Travel}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('3a1959c2-dd18-4851-81fc-870f80b6ebd4', 2014, 'sentence_building', 'A2', 'travel', 'Where is the nearest bus stop?', 'Dónde está la parada de autobús más cercana?', '["dónde", "está", "la", "parada", "de", "autobús", "más", "cercana", "próxima", "metro", "cerca", "el"]', NULL, NULL, NULL, NULL, '"La parada de autobús" = bus stop. "Más cercana" = the nearest (feminine, agreeing with parada). "Próxima" also means nearest or next.', '2026-04-13 09:19:30.039983+00', NULL, NULL, 'es', '{Travel}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('8264c8de-acee-42fa-b5d5-b1ef849e8434', 2015, 'sentence_building', 'A2', 'travel', 'Can you recommend a good restaurant near here?', 'Puede recomendarme un buen restaurante cerca de aquí?', '["puede", "recomendarme", "un", "buen", "restaurante", "cerca", "de", "aquí", "recomendar", "me", "bar", "bueno"]', NULL, NULL, NULL, NULL, '"Puede + infinitive" = can you? (formal, usted form). "Recomendarme" = recommend to me — the pronoun is attached to the infinitive. "Cerca de aquí" = near here.', '2026-04-13 09:19:30.039983+00', NULL, NULL, 'es', '{Travel}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('787cbb6b-0eca-4887-8655-5d05b514729b', 2012, 'sentence_building', 'A2', 'travel', 'The air conditioning is not working.', 'El aire acondicionado no funciona.', '["el", "aire", "acondicionado", "no", "funciona", "la", "calefacción", "wifi", "está", "roto"]', NULL, NULL, '[{"answer": "La aire acondicionado no funciona", "feedback": "Almost! Aire is masculine in Spanish, so it needs el — el aire acondicionado."}]', NULL, '"El aire acondicionado" = air conditioning. "No funciona" = it does not work. "La calefacción" = the heating.', '2026-04-13 09:19:30.039983+00', NULL, NULL, 'es', '{Travel}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('bb351f04-e98a-48b9-bb03-4fb04f79b418', 2016, 'sentence_building', 'A2', 'travel', 'The room has not been cleaned today.', 'No han limpiado la habitación hoy.', '["no", "han", "limpiado", "la", "habitación", "hoy", "hicieron", "limpia", "arreglado", "el"]', NULL, NULL, '[{"answer": "La habitación no han limpiado hoy.", "feedback": "También correcto — frontar el objeto (\"la habitación\") es natural en español."}]', NULL, '"Han limpiado" = they have cleaned (present perfect). This is more natural in Spanish than the passive form. "Hoy" = today; "arreglado" = tidied.', '2026-04-13 09:19:30.039983+00', NULL, NULL, 'es', '{Travel}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('1a2942b9-7215-433d-8f7b-8b1952dfd731', 31, 'gap_fill', 'B2', 'reported_speech', 'She said that she ___ (be) tired and wanted to go home.', 'was', NULL, NULL, NULL, NULL, 'Backshift the verb tense in reported speech', 'When reporting past statements, present simple becomes past simple.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{"Reported speech"}', false, 'Reported speech: present → past. "She said she was tired."', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('8428878b-3f06-458a-af23-22c916a6351e', 32, 'gap_fill', 'B2', 'reported_speech', 'He told me that he ___ (will / help) me tomorrow.', 'would help', NULL, '["will help", "''ll help"]', NULL, NULL, 'Will changes to would in reported speech', 'When reporting, will changes to would technically, but natives might use both if the condition remains the same.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{"Reported speech"}', false, 'Will → would when reporting what someone said.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('0d174ce5-447f-4d77-b49b-e56a08c397c8', 33, 'gap_fill', 'B1', 'gerunds_infinitives', 'I enjoy ___ (read) in my free time.', 'reading', NULL, NULL, NULL, NULL, 'Enjoy is followed by -ing', 'Enjoy is followed by a gerund (-ing form).', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{"Gerund & infinitive"}', false, 'Verbs of liking/disliking (enjoy, hate, love) take -ing.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('a8fbaf00-152e-4844-bf4e-23685cdd668e', 34, 'gap_fill', 'B1', 'gerunds_infinitives', 'I decided ___ (study) medicine at university.', 'to study', NULL, NULL, NULL, NULL, 'Decide is followed by to + infinitive', 'Decide is followed by the infinitive.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{"Gerund & infinitive"}', false, 'Form: decided + to + infinitive.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('7d3180d2-b7fb-487b-b493-bf18f2314e4f', 35, 'gap_fill', 'B2', 'gerunds_infinitives', 'She stopped ___ (smoke) five years ago.', 'smoking', NULL, NULL, NULL, NULL, 'Stop + -ing means to quit doing something', 'Stop + gerund means to quit an activity.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{"Gerund & infinitive"}', false, 'Compare: "stopped to smoke" = stopped *in order to* smoke. Different meaning!', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('aa21c418-81af-48a8-9655-397d47faf5f1', 36, 'gap_fill', 'B1', 'prepositions_time', 'The meeting is ___ (at / on / in) Monday morning.', 'on', NULL, NULL, NULL, NULL, 'Use ''on'' for days and dates', 'On is used for days of the week and specific dates.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{"Preposition of time"}', false, 'Days: on Monday, on Friday, on 25th December.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('cda9cdd9-bffe-46a9-a69a-eb5d32263258', 37, 'gap_fill', 'B1', 'prepositions_time', 'I usually go to the gym ___ (at / on / in) the evening.', 'in', NULL, NULL, NULL, NULL, 'Use ''in'' for parts of the day', 'In is used for parts of the day (morning, afternoon, evening).', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{"Preposition of time"}', false, 'In the morning, in the afternoon, in the evening — but AT night.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('7869b196-24c1-4d22-95c8-c3ff49ca0fca', 38, 'gap_fill', 'B1', 'prepositions_place', 'The café is ___ (under / at / on / in) the corner of the street.', 'on', NULL, NULL, NULL, NULL, 'Both ''on'' and ''at'' can be used for corners', 'Both on and at can be used when referring to corners.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{"Preposition of place"}', false, 'For corners, "on" is more common in everyday speech.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('301baacd-b52e-4fad-a4b5-5909edce6291', 39, 'gap_fill', 'B2', 'prepositions_dependent', 'I''m not very good ___ (at / in / on) mathematics.', 'at', NULL, NULL, NULL, NULL, 'Good at + subject/activity', 'Good is followed by at when talking about skills or subjects.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{"Dependent preposition"}', false, 'Good at maths, bad at sports, brilliant at chess.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('1fdd20db-c846-4067-ba64-1cd07824408c', 40, 'gap_fill', 'B2', 'prepositions_dependent', 'She''s interested ___ (at / in / on) learning Japanese.', 'in', NULL, NULL, NULL, NULL, 'Interested in + activity', 'Interested is followed by in.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{"Dependent preposition"}', false, 'Interested in + noun or -ing form.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('ca5c8ec9-42aa-4084-a753-aa5c0b633fca', 2151, 'gap_fill', 'C1', 'prepositions', 'The new policy gave rise ___ widespread protest.', 'to', '[]', NULL, NULL, NULL, '"give rise ___ something" = cause it.', '"Give rise to" means to cause or produce something.', '2026-06-01 07:16:29.304337+00', NULL, NULL, 'en', '{Preposition}', false, 'Two letters.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('ba8d09be-3718-4b69-9d7e-020e37af1242', 1751, 'gap_fill', 'C2', 'sport', 'Elite open-water swimmers must develop exceptional _____ — the ability to navigate accurately without fixed reference points such as lane ropes.', 'sighting', NULL, NULL, NULL, NULL, 'Looking up to check direction — the act of taking a visual reference point.', 'Sighting is the technique open-water swimmers use to check their direction by briefly lifting the head to look forward during the stroke. Unlike pool swimming, there are no lane lines, so sighting every six to ten strokes is essential to avoid swimming off course — which adds distance and wastes energy. Poor sighting is one of the most common mistakes in triathlon swimming.', '2026-03-30 08:52:38.502672+00', NULL, NULL, 'en', '{}', false, 'Single word. Starts with s___.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('481442b9-2f2a-4814-a729-79090da5220c', 1752, 'gap_fill', 'C2', 'sport', 'The padel player''s ability to _____ the ball off the back wall gave her a significant tactical advantage over opponents unfamiliar with the skill.', 'play', NULL, NULL, NULL, NULL, 'The basic verb for striking the ball — used in most racket sports.', 'Playing the ball off the back wall is one of the defining skills of padel — and what makes it fundamentally different from tennis. After the ball bounces off the back or side glass, a skilled player can redirect it with precision. Learning to read the rebound angle and use the walls offensively rather than defensively is what separates intermediate from advanced padel players.', '2026-03-30 08:52:38.502672+00', NULL, NULL, 'en', '{}', false, 'Single word. Starts with p___.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('bd6b0172-d2bc-43fd-ba0a-34dfb04fc66e', 1753, 'gap_fill', 'C2', 'sport', 'CrossFit''s programming philosophy is built around _____ — the idea that no single physical quality should be trained in isolation, but that fitness must be broad, general, and inclusive.', 'constant variation', NULL, NULL, NULL, NULL, 'A core CrossFit principle: continually changing the workout so the body never settles into one routine.', 'Constant variation — or constantly varied functional movement — is a core CrossFit principle. By regularly changing the exercises, rep schemes, and energy systems used, CrossFit aims to prepare athletes for any physical challenge. Critics argue this makes it difficult to develop mastery in specific skills; proponents argue it develops genuine all-round fitness. The debate reflects a broader tension between specialisation and generalisation in training.', '2026-03-30 08:52:38.502672+00', NULL, NULL, 'en', '{}', false, 'Two words. Starts with c___ v___.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('863935d8-2070-4a91-a9e0-e0a86e8d77e7', 1754, 'gap_fill', 'C2', 'sport', 'The weightlifter''s coach emphasised the importance of _____ position — keeping the spine neutral and the core braced to protect the lower back during heavy lifts.', 'bracing', NULL, NULL, NULL, NULL, 'Tensing the core to support the spine under load — like preparing yourself for impact.', 'Bracing refers to the technique of contracting the core muscles — including the deep stabilisers of the spine — to create intra-abdominal pressure and protect the back during heavy lifting. It is distinct from simply sucking the stomach in. Proper bracing technique is one of the first things taught in weightlifting and powerlifting coaching. Failure to brace correctly under heavy load is a significant cause of lower back injury.', '2026-03-30 08:52:38.502672+00', NULL, NULL, 'en', '{}', false, 'Single word. Starts with b___.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('0a619fe4-e27e-4690-b0c4-7421aba5f1df', 1755, 'gap_fill', 'C2', 'sport', 'In elite running, the concept of _____ economy — the oxygen cost of running at a given pace — is considered a better predictor of performance than VO2 max alone.', 'running', NULL, NULL, NULL, NULL, 'The sport this concept is from — a measure of how efficient your stride is.', 'Running economy refers to how efficiently a runner uses oxygen at a given speed. Two runners with the same VO2 max (maximum oxygen uptake) can perform very differently if one has better running economy — meaning they use less energy per stride. Factors include biomechanics, cadence, footstrike pattern, and muscle elasticity. Elite runners typically have both high VO2 max and excellent running economy.', '2026-03-30 08:52:38.502672+00', NULL, NULL, 'en', '{}', false, 'Single word. Starts with r___.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('bcc449fb-ae6c-4682-9080-d494b8c8762e', 1782, 'gap_fill', 'B1', 'travel', 'After collecting our bags, we went through _____ to declare the goods we had bought abroad.', 'customs', NULL, NULL, NULL, NULL, 'The official area at a border where authorities check what you''re bringing into a country.', 'Customs is the area at a border or airport where officials check what travellers are bringing into the country and collect any duties owed. There are typically two channels: the green channel (nothing to declare) and the red channel (goods to declare). Failing to declare goods correctly can result in fines or confiscation.', '2026-03-30 09:41:12.599621+00', NULL, NULL, 'en', '{}', false, 'Single word. Starts with c___.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('2596fe41-b320-49c7-a35c-8b7056ad350d', 1783, 'gap_fill', 'B1', 'travel', 'We decided to _____ a car at the airport so we could explore the countryside at our own pace.', 'hire', NULL, NULL, NULL, NULL, 'To pay to use something for a short period — like a car, a bike, or a tuxedo.', 'Hire a car (British English) or rent a car (American English) means to pay to use a vehicle for a period of time. When hiring a car abroad, you typically need a valid driving licence, a credit card for the deposit, and sometimes an international driving permit. Always check whether insurance is included in the price.', '2026-03-30 09:41:12.599621+00', NULL, NULL, 'en', '{}', false, 'Single word. Starts with h___.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('382ce843-b135-4962-92ff-911a952057c1', 1784, 'gap_fill', 'B2', 'travel', 'The hotel was in a prime _____ — right in the centre of the city, within walking distance of all the major attractions.', 'location', NULL, NULL, NULL, NULL, 'The place where a building stands — the most important factor in real estate.', 'Location is one of the most important factors when choosing accommodation. A central location means less time travelling between your hotel and the sights. Estate agents and travel writers use prime location, central location, and convenient location as key selling points. Compare: remote (far from amenities), off the beaten track (away from tourist areas).', '2026-03-30 09:41:12.599621+00', NULL, NULL, 'en', '{}', false, 'Single word. Starts with l___.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('d0daf09d-355c-4833-bb66-235ea9b3c345', 1785, 'gap_fill', 'B2', 'travel', 'The tour guide warned us to keep our belongings close in the market — pickpocketing was _____ in busy tourist areas.', 'rife', NULL, NULL, NULL, NULL, 'Widespread and common, usually in a negative sense — like crime in a neighbourhood.', 'Rife means widespread and very common — usually used for something negative. Pickpocketing is rife is a more vivid and sophisticated way of saying it happens a lot. Compare: common, widespread, prevalent (more neutral), endemic (so common it is a permanent feature of a place or society). Travel safety vocabulary is highly useful for real-life situations.', '2026-03-30 09:41:12.599621+00', NULL, NULL, 'en', '{}', false, 'Single word. Starts with r___.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('92c1db11-316a-4a31-a0dd-3fd7bfdc09c4', 1786, 'gap_fill', 'C1', 'travel', 'The rise of short-term rental platforms has _____ the traditional hotel industry, forcing many establishments to reconsider their pricing and service models.', 'disrupted', NULL, NULL, NULL, NULL, 'To interrupt or break up the normal way something works — what new technology often does to old industries.', 'Disrupt means to radically change or destabilise an established industry or system. Platforms like Airbnb are frequently described as having disrupted the hotel industry. In business English, disruption is often used approvingly — a disruptive company is one that has changed the rules. Compare: upend, transform, revolutionise, unsettle.', '2026-03-30 09:41:12.599621+00', NULL, NULL, 'en', '{}', false, 'Single word. Starts with d___.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('5600f283-3df8-4103-b810-13bb3c673083', 1063, 'multiple_choice', 'A2', 'business_phrasal_verbs', 'Could you _______ the sales figures for last month? I need them for the report.', 'look up', '["look up", "look into", "look after", "look over"]', NULL, NULL, NULL, 'To find specific information (in a report, online).', 'To look up means to search for specific information — in a database, reference book, or online. Compare: look into = to investigate a problem more deeply.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Business phrasal verb"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('730c3742-c153-4edd-acb6-b9e4f0da1b10', 1787, 'gap_fill', 'C1', 'travel', 'The government introduced a tourist _____ to manage visitor numbers and generate revenue for conservation.', 'levy', NULL, NULL, NULL, NULL, 'An official charge or tax — like a tariff or duty.', 'A levy is a tax or charge imposed by a government or authority. Tourist levies (also called visitor taxes or tourist taxes) are increasingly used by popular destinations including Barcelona, Venice, and Amsterdam to manage overtourism and fund infrastructure. Compare: surcharge (an extra charge added to a bill), tariff (a tax on imports or exports), fee (a charge for a service).', '2026-03-30 09:41:12.599621+00', NULL, NULL, 'en', '{}', false, 'Single word. Starts with l___.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('5e9be369-2db7-468c-aeba-df92b92ad689', 1788, 'gap_fill', 'C1', 'travel', 'The airline''s refusal to issue refunds during the pandemic drew widespread _____ from consumer groups and regulators alike.', 'condemnation', NULL, NULL, NULL, NULL, 'Strong public criticism — being formally rebuked by an authority.', 'Condemnation means strong public disapproval or criticism. It is a formal word used in journalism and official contexts. Compare: criticism (more neutral), backlash (a strong negative reaction from the public), censure (formal official disapproval). Draw condemnation and face condemnation are common collocations.', '2026-03-30 09:41:12.599621+00', NULL, NULL, 'en', '{}', false, 'Single word. Starts with c___.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('d02e3d24-db8e-4956-9bbe-ba835b9985ea', 1789, 'gap_fill', 'C1', 'travel', 'Long-haul travel has become increasingly accessible, yet its carbon _____ remains a significant ethical concern for environmentally conscious travellers.', 'footprint', NULL, NULL, NULL, NULL, 'An idiom — the mark or impact something leaves behind, especially environmentally.', 'Carbon footprint refers to the total amount of greenhouse gases produced by an activity, individual, or organisation. Flying has one of the highest carbon footprints of any personal activity. Related vocabulary: carbon offset (paying to compensate for emissions), sustainable travel, flight shame (the social pressure to avoid flying for environmental reasons — from Swedish flygskam).', '2026-03-30 09:41:12.599621+00', NULL, NULL, 'en', '{}', false, 'Single word. Starts with f___.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('231efae1-d2fe-4fd9-8eef-acc69e1779c3', 1790, 'gap_fill', 'C1', 'travel', 'The ancient city had been so heavily _____ by tourism that locals could barely afford to live there any more.', 'gentrified', NULL, NULL, NULL, NULL, 'When wealthier people move into a poorer area, raising prices and pushing out original residents.', 'Gentrify means to renovate and improve an area in a way that raises property prices and displaces lower-income residents. In the context of tourism, heavy visitor numbers drive up rents and change the character of neighbourhoods — a process sometimes called touristification. Venice and Barcelona are frequently cited examples. Compare: displace, price out, commercialise.', '2026-03-30 09:41:12.599621+00', NULL, NULL, 'en', '{}', false, 'Single word. Starts with g___.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('7a5c7f25-7864-405c-a30d-c117b90a0d95', 1792, 'gap_fill', 'C2', 'travel', 'The journalist''s piece on voluntourism questioned whether short-term volunteer trips _____ more harm than good by disrupting local economies and fostering dependency.', 'cause', NULL, NULL, NULL, '[{"answer": "do", "feedback": "Do more harm than good is a perfectly valid fixed phrase here — cause is the model answer but do works equally well."}]', 'The basic verb meaning "produce as a result" — to bring something about.', 'Voluntourism combines volunteering with tourism — paying to travel abroad to do charitable work. Critics argue it is more beneficial to donors than recipients, disrupts local labour markets, and can foster dependency. The debate illustrates a broader tension in ethical travel between good intentions and actual impact. Related: ethical tourism, responsible travel, sustainable development.', '2026-03-30 09:41:12.599621+00', NULL, NULL, 'en', '{}', false, 'Single word. Starts with c___.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('69215323-05cf-4a19-9b9b-c029218f143a', 1793, 'gap_fill', 'C2', 'travel', 'The airport''s new terminal was designed with _____ in mind — wide corridors, tactile paving, and accessible facilities throughout.', 'inclusivity', NULL, NULL, NULL, NULL, 'The principle of designing for everyone — accessibility regardless of ability.', 'Inclusivity means designing spaces and systems so that everyone — regardless of ability, age, or background — can participate fully. In travel and hospitality, inclusivity covers accessibility for disabled travellers, multilingual signage, sensory-friendly spaces, and gender-neutral facilities. Compare: accessibility (focused specifically on physical access), universal design (designing for the widest possible range of users from the outset).', '2026-03-30 09:41:12.599621+00', NULL, NULL, 'en', '{}', false, 'Single word. Starts with i___.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('8223b3e8-aa8b-4d5d-8e44-43d707e4717a', 1794, 'gap_fill', 'C2', 'travel', 'The region''s economy was almost entirely _____ on tourism, making it extremely vulnerable to global events such as pandemics or geopolitical instability.', 'predicated', NULL, NULL, NULL, NULL, 'Built or based upon something — like an argument resting on a foundation.', 'Predicated on means based on or dependent on a particular assumption or condition. An economy predicated on tourism is one where tourism is the fundamental basis of economic activity. The word is formal and common in academic and journalistic writing. Compare: dependent on (simpler equivalent), contingent on (subject to the condition that), reliant on.', '2026-03-30 09:41:12.599621+00', NULL, NULL, 'en', '{}', false, 'Single word. Starts with p___.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('9741aa93-6015-4634-849b-fa57ecd9cad9', 1795, 'gap_fill', 'C2', 'travel', 'The pandemic exposed the _____ of global tourism, as a single health crisis brought the entire industry to a complete standstill.', 'fragility', NULL, NULL, NULL, NULL, 'The quality of being easily broken — vulnerability.', 'Fragility refers to the quality of being easily damaged or disrupted. The fragility of global tourism was exposed by COVID-19, which showed how dependent the industry is on freedom of movement, consumer confidence, and international cooperation. Compare: vulnerability (susceptibility to harm), precariousness (insecurity), resilience (the ability to recover — the opposite quality).', '2026-03-30 09:41:12.599621+00', NULL, NULL, 'en', '{}', false, 'Single word. Starts with f___.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('46c461f5-4723-4af7-a1fe-fbbd198113eb', 1806, 'gap_fill', 'C2', 'business_phrasal_verbs', 'After years of expansion, the board decided to _____ several underperforming divisions and return to the company''s core business.', 'hive off', NULL, NULL, NULL, NULL, 'An idiom: to separate part of a business — like bees splitting off from the main hive.', 'Hive off means to separate a part of a business and make it independent, or to sell it off. It is commonly used in restructuring and demerger contexts. Compare: spin off (to create an independent company from a division), sell off (to dispose of an asset), carve out (to separate a business unit, often before a sale or IPO).', '2026-03-31 08:54:00.126346+00', NULL, NULL, 'en', '{}', false, 'Two words. Starts with h___ o___.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('83d75c10-d6ca-47de-b0f4-ad657403d030', 1449, 'gap_fill', 'A2', 'spanish', 'Entre semana siempre _____ antes de las once de la noche.', 'me acuesto', NULL, NULL, NULL, NULL, NULL, 'Acostarse es reflexivo y también cambia la raíz (o→ue): me acuesto, te acuestas, se acuesta.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'es', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('1c8c98c0-f185-44c0-916d-ac8df8994327', 1981, 'sentence_building', 'A2', 'travel', 'El vuelo sale a las diez.', 'The flight leaves at ten', '["the", "flight", "leaves", "at", "ten", "o''clock", "departs", "arrives", "plane", "nine"]', NULL, NULL, NULL, NULL, '"Leaves" and "departs" mean the same, but "leaves" is more natural in everyday speech. Both "at ten" and "at ten o''clock" are correct.', '2026-04-13 09:19:30.039983+00', NULL, NULL, 'en', '{Travel}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('1d65ab7d-82fa-4f60-bb35-7c0a451c4a5c', 1064, 'multiple_choice', 'A2', 'business_phrasal_verbs', 'The smaller company was _______ by a large international corporation last year.', 'taken over', '["taken over", "taken on", "taken off", "taken up"]', NULL, NULL, NULL, 'To acquire control of (a company, a department).', 'A takeover happens when one company buys a controlling interest in another. To take over means to assume control of something.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Business phrasal verb","Business vocabulary"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('fa217eb8-8abb-41cd-a142-ec4939e028eb', 1386, 'gap_fill', 'C1', 'prepositions', 'His success is attributed _____ years of disciplined practice.', 'to', NULL, NULL, NULL, NULL, '"Attributed ___ X" = caused by.', 'Attribute to is the correct collocation. Compare: put down to, ascribe to. All mean to identify the cause of something.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}', false, 'Form: be attributed ___.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('30670cf4-26fb-41c4-b5cb-8f35e1599823', 1387, 'gap_fill', 'C2', 'prepositions', 'She is renowned _____ her ability to remain calm under pressure.', 'for', NULL, NULL, NULL, NULL, '"Renowned ___ X" = famous for X.', 'Renowned for is the correct collocation. Compare: famous for, celebrated for, known for.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}', false, 'Same as in "famous ___".', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('381c08e9-cbd5-4599-82f8-ac48131051fa', 1388, 'gap_fill', 'C1', 'prepositions', 'The extent _____ which habits shape identity is rarely considered.', 'to', NULL, NULL, NULL, NULL, 'Phrase: "the extent ___ which..." = how much.', 'The extent to which is a fixed relative clause structure. It introduces a degree or measure and cannot be replaced by at which or in which.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}', false, 'Same as "the degree ___ which".', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('5b870957-5adf-4996-8a75-728ddfd87389', 1389, 'gap_fill', 'C2', 'prepositions', 'She refrained _____ commenting on the matter until the report was published.', 'from', NULL, NULL, NULL, NULL, 'Always: "refrain ___ + -ing" = avoid doing.', 'Refrain from is the correct collocation, followed by a gerund. Compare: abstain from, desist from, shy away from.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}', false, 'Same preposition as in "abstain ___".', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('acddb5f4-4e0c-4f30-8303-3ead3e43120e', 1390, 'gap_fill', 'C1', 'prepositions', 'He took great pride _____ the consistency of his morning routine.', 'in', NULL, NULL, NULL, NULL, 'Phrase: "take pride ___ + something".', 'Take pride in is the correct collocation. Compare: pride yourself on, derive satisfaction from.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}', false, 'Same as in "delight ___" or "joy ___".', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('0a52a663-4353-4458-ac80-32e4cecb119a', 1391, 'gap_fill', 'C2', 'prepositions', 'The habit is deeply ingrained _____ her daily behaviour.', 'in', NULL, NULL, NULL, NULL, 'Always: "ingrained ___ + something".', 'Ingrained in is the correct collocation. Ingrained means deeply embedded or established.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}', false, 'Like deeply rooted in soil.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('e1cac905-f465-48a6-90ff-8f37602c84dd', 1413, 'gap_fill', 'B2', 'vocabulary', 'The _____ of her routine was remarkable — she barely deviated from it even during holidays.', 'consistency', NULL, NULL, NULL, NULL, 'Doing the same thing reliably over time.', 'Consistency means the quality of always behaving or performing in the same way. It is closely related to reliability and predictability.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}', false, 'Noun form of "consistent".', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('f26c90e0-2fd8-4074-ad89-832d91968bc8', 1415, 'gap_fill', 'B2', 'vocabulary', 'The study found that people with structured morning routines reported higher levels of _____ throughout the day.', 'wellbeing', NULL, NULL, NULL, NULL, 'Overall health — physical, mental, emotional.', 'Wellbeing refers to a person''s general health, happiness, and comfort. It is commonly used in psychology and health contexts.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}', false, 'Compound noun: well + being.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('ce3c400e-733e-497a-962a-ac82f7ac88f2', 1416, 'gap_fill', 'C1', 'vocabulary', 'The speaker''s _____ delivery made the presentation difficult to follow — she moved between topics without warning.', 'erratic', NULL, NULL, NULL, NULL, 'Unpredictable, irregular — moving without a pattern.', 'Erratic means unpredictable and inconsistent. It is the opposite of steady or methodical.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}', false, 'From Latin "errare" — to wander.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('6414ab4a-4245-4da8-b461-7975ae51ec5c', 1421, 'gap_fill', 'C1', 'vocabulary', 'Research has shown that sleep deprivation has a markedly _____ effect on decision-making and emotional regulation.', 'harmful', NULL, NULL, NULL, '[{"answer": "deleterious", "feedback": "✅ Excellent — ''deleterious'' is a more formal C2-level synonym. Both work here."}, {"answer": "negative", "feedback": "✅ ''Negative'' works well — slightly less specific than ''harmful''."}, {"answer": "damaging", "feedback": "✅ ''Damaging'' fits perfectly — same meaning as ''harmful''."}, {"answer": "detrimental", "feedback": "✅ ''Detrimental'' works — a more formal way to say ''harmful''."}, {"answer": "adverse", "feedback": "✅ ''Adverse'' works — formal word for unfavourable or harmful."}]', 'Causing damage — the opposite of helpful.', '"Harmful" means causing damage or negative effects. The sentence means sleep deprivation has a clearly bad effect on decision-making and emotional regulation.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}', false, 'Common adjective. 7 letters.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('a71f013c-df03-4b70-b293-547de712e02e', 1414, 'gap_fill', 'B1', 'vocabulary', 'She decided to _____ her screen time after realising it was affecting her sleep.', 'cut down on', NULL, NULL, NULL, NULL, 'A phrasal verb meaning to do less of something habitual.', 'Cut down on means to reduce the amount or frequency of something. It is a phrasal verb commonly used for habits.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}', false, 'Three-word phrasal verb. Same as "cut back on".', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('ffdd5653-784b-4ab3-bc5d-9240a0fc0d9a', 2152, 'gap_fill', 'C1', 'prepositions', 'She was oblivious ___ the danger she was in.', 'to', '[]', NULL, NULL, NULL, '"oblivious ___" = completely unaware of.', '"Oblivious to" means completely unaware of something.', '2026-06-01 07:16:29.304337+00', NULL, NULL, 'en', '{Preposition}', false, 'Two letters.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('abeebd8a-a516-41de-b5d3-923ba4481e42', 1996, 'sentence_building', 'B2', 'travel', 'No había suficiente tiempo para hacer el transbordo.', 'There wasn''t enough time to make the connection.', '["there", "wasn''t", "enough", "time", "to", "make", "the", "connection", "short", "catch", "missed", "transfer"]', NULL, NULL, NULL, NULL, '"There wasn''t enough time to..." is a natural way to describe missing something due to a time constraint. "Make the connection" means to successfully board the connecting flight.', '2026-04-13 09:19:30.039983+00', NULL, NULL, 'en', '{Travel}', true, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('1443bb00-6dc4-49f9-849d-64d1f7e72186', 2153, 'gap_fill', 'C1', 'prepositions', 'They were intent ___ finishing before dark.', 'on', '[]', NULL, NULL, NULL, '"intent ___ doing something" = determined to.', '"Intent on (doing) something" means firmly determined to do it.', '2026-06-01 07:16:29.304337+00', NULL, NULL, 'en', '{Preposition}', false, 'Two letters.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('0b1fa811-eec7-4667-bf67-a5b37b75aef2', 2154, 'gap_fill', 'C1', 'prepositions', 'The findings are at odds ___ previous research.', 'with', '[]', NULL, NULL, NULL, '"at odds ___" = in conflict with.', '"At odds with" means in conflict or disagreement with.', '2026-06-01 07:16:29.304337+00', NULL, NULL, 'en', '{Preposition}', false, 'Four letters.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('b4cbbfa3-d8de-46dc-beb2-83bbed864b85', 2155, 'gap_fill', 'C1', 'prepositions', 'He prides himself ___ his punctuality.', 'on', '[]', NULL, NULL, NULL, '"pride yourself ___ something".', 'The reflexive pattern is "pride yourself on (doing) something".', '2026-06-01 07:16:29.304337+00', NULL, NULL, 'en', '{Preposition}', false, 'Two letters.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('aa17b3ca-2e09-4a2e-9a74-fe2c70d7f7e8', 2156, 'gap_fill', 'C1', 'prepositions', 'The proposal met ___ fierce opposition.', 'with', '[]', NULL, NULL, NULL, '"meet ___ a reaction" = encounter it.', '"Meet with" a reaction means to encounter or receive it.', '2026-06-01 07:16:29.304337+00', NULL, NULL, 'en', '{Preposition}', false, 'Four letters.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('2c6473cd-6eab-4468-b843-cbe716e984d7', 2157, 'gap_fill', 'C1', 'prepositions', 'She has a real flair ___ languages.', 'for', '[]', NULL, NULL, NULL, '"a flair ___ something" = a natural talent.', '"A flair for something" means a natural talent or ability.', '2026-06-01 07:16:29.304337+00', NULL, NULL, 'en', '{Preposition}', false, 'Three letters.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('054babcb-3ef7-4bc0-b52c-574fb75a078f', 2158, 'gap_fill', 'C1', 'prepositions', 'We must abide ___ the committee''s decision.', 'by', '[]', NULL, NULL, NULL, '"abide ___ a rule" = accept and follow it.', '"Abide by" a rule or decision means to accept and follow it.', '2026-06-01 07:16:29.304337+00', NULL, NULL, 'en', '{Preposition}', false, 'Two letters.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('4bc85541-92bf-4af0-825e-24e70945c5e0', 2159, 'gap_fill', 'C1', 'prepositions', 'The report casts doubt ___ the official version.', 'on', '[]', NULL, NULL, NULL, '"cast doubt ___ something" = make it seem less certain.', '"Cast doubt on something" means to make it seem less certain or reliable.', '2026-06-01 07:16:29.304337+00', NULL, NULL, 'en', '{Preposition}', false, 'Two letters.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('e38ef627-375d-4adf-8e1a-ccfe63b48ee5', 1422, 'gap_fill', 'C1', 'vocabulary', 'She was able to maintain her _____ under pressure, finishing the project ahead of schedule despite the setbacks.', 'composure', NULL, NULL, NULL, NULL, 'Calm self-control under pressure.', 'Composure means the state of being calm and in control of your feelings. Compare: equanimity, poise, self-possession.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}', false, 'Sharing a root with "compose" — to put together.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('fbf89265-ba5c-456f-a11b-909b1ca948c0', 1424, 'gap_fill', 'C1', 'vocabulary', 'The report identified sleep deprivation as a major _____ to productivity in modern workplaces.', 'impediment', NULL, NULL, NULL, NULL, 'An obstacle to progress.', 'Impediment means something that prevents or slows progress. Synonyms include obstacle, barrier, hindrance.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}', false, 'From Latin "impedire" — to entangle the feet.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('f30aa32c-8912-40f0-8bc6-aa281879df68', 1430, 'gap_fill', 'A2', 'spanish', 'Intento acostarme antes de las once _____ semana para no llegar cansado al trabajo.', 'entre', NULL, NULL, NULL, NULL, NULL, 'Entre semana es la expresión española para on weekdays (de lunes a viernes). Es una expresión fija.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'es', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('740cf589-0e7d-4ad0-8311-9ccb3eafbd29', 1432, 'gap_fill', 'A2', 'spanish', 'Los fines de semana me gusta _____ una siesta después de comer.', 'echar', NULL, NULL, NULL, NULL, NULL, 'Echar una siesta es la expresión española para to take a nap. Siesta es una palabra que existe también en inglés.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'es', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('5e671b31-46fc-43cf-8322-8a66c401787f', 1434, 'gap_fill', 'A2', 'spanish', 'Siempre me cepillo los dientes _____ de acostarme.', 'antes', NULL, NULL, NULL, NULL, NULL, 'Antes de + infinitivo significa before doing something. La estructura es la misma que en inglés: before going to bed / antes de acostarse.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'es', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('1beae735-a255-45ec-9d47-661cacef9a82', 1436, 'gap_fill', 'A2', 'spanish', 'Cuando llegué a la fiesta, todo el mundo _____ bailando.', 'estaba', NULL, NULL, NULL, NULL, NULL, 'El imperfecto continuo (estaba + gerundio) se usa para describir una acción que estaba en progreso en un momento concreto del pasado.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'es', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('d2ddc666-83fa-45d9-8b72-909d85aa89df', 1437, 'gap_fill', 'A2', 'spanish', 'Ayer _____ al supermercado después del trabajo.', 'fui', NULL, NULL, NULL, NULL, NULL, 'Fui es el pretérito indefinido de ir. Se usa para acciones completadas en el pasado.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'es', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('c9208292-52b5-496f-a5c0-7ef2fa444a20', 1438, 'gap_fill', 'A2', 'spanish', 'Mi hermana es más alta _____ yo.', 'que', NULL, NULL, NULL, NULL, NULL, 'En los comparativos en español se usa que (no de) para comparar dos cosas: más alto que, más rápido que.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'es', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('3cc389ec-6795-4681-b4ef-74ee592062aa', 1439, 'gap_fill', 'A2', 'spanish', 'Me encanta esta ciudad _____ hay muchísimas cosas que hacer.', 'porque', NULL, NULL, NULL, NULL, NULL, 'Porque significa because y se escribe en una sola palabra. No confundir con por qué (why — en preguntas).', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'es', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('75f54af8-24a9-4ee3-a8a4-15e32b9dcf5e', 1440, 'gap_fill', 'A2', 'spanish', 'Habla muy bien el español _____ nunca ha vivido en un país hispanohablante.', 'aunque', NULL, NULL, NULL, NULL, NULL, 'Aunque significa although o even though. Introduce una concesión — algo sorprendente dado lo que se ha dicho antes.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'es', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('be54ceed-1e63-409b-a3a7-34cb69437390', 1441, 'gap_fill', 'A2', 'spanish', 'Llevo tres años _____ español.', 'estudiando', NULL, NULL, NULL, NULL, NULL, 'Con llevar + tiempo, se usa el gerundio para indicar una acción que empezó en el pasado y continúa: llevo tres años estudiando.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'es', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('3f008920-e57a-489d-a6dd-f1ac81533f44', 1442, 'gap_fill', 'A2', 'spanish', 'Quedamos en el bar a las ocho, pero él _____ tarde.', 'llegó', NULL, NULL, NULL, NULL, NULL, 'Llegó es el pretérito indefinido de llegar en tercera persona singular. Se usa para una acción completada en el pasado.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'es', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('78751307-cdbf-4813-af7c-27a9bad8d5b5', 1443, 'gap_fill', 'A2', 'spanish', 'La película era muy larga; _____, nos gustó mucho.', 'sin embargo', NULL, NULL, NULL, NULL, NULL, 'Sin embargo significa however o nevertheless. Introduce un contraste con lo dicho anteriormente.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'es', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('d45e91f1-88bc-4981-b953-9c8f4239add2', 1444, 'gap_fill', 'A2', 'spanish', 'Necesito practicar más _____ mejorar mi español.', 'para', NULL, NULL, NULL, NULL, NULL, 'Para + infinitivo expresa finalidad (in order to): para mejorar = in order to improve.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'es', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('bf4800dc-cef2-4cb8-8a38-3fbacd60df02', 1445, 'gap_fill', 'A2', 'spanish', 'Llegaron tarde _____ el tráfico.', 'por', NULL, NULL, NULL, NULL, NULL, 'Por se usa para expresar causa o razón: llegaron tarde por el tráfico (they arrived late because of the traffic).', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'es', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('369bff08-fe0b-47db-b7b1-343d85df01ad', 1362, 'matching', 'A2', 'spanish', 'Match the Spanish expression to its English meaning.', '["match_all_pairs"]', '[{"left": {"type": "text", "label": "", "content": "quedarse dormido"}, "right": {"type": "text", "label": "", "content": "to fall asleep"}}, {"left": {"type": "text", "label": "", "content": "dar una cabezada"}, "right": {"type": "text", "label": "", "content": "to take a nap"}}, {"left": {"type": "text", "label": "", "content": "pegar ojo"}, "right": {"type": "text", "label": "", "content": "to sleep (often in negative: no pegar ojo)"}}, {"left": {"type": "text", "label": "", "content": "levantarse con el pie izquierdo"}, "right": {"type": "text", "label": "", "content": "to get out of the wrong side of bed"}}]', NULL, NULL, NULL, NULL, NULL, '2026-03-17 09:30:11.660865+00', NULL, NULL, 'es', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('1adc56b9-a8ab-4ba1-88d9-e1ab1aac3a30', 654, 'sentence_building', 'B1', 'present_perfect_continuous', 'Llevo tres años estudiando inglés.', 'I have been studying English for three years', '["I", "have", "been", "studying", "English", "for", "three", "years", "since", "studied", "am", "to"]', NULL, NULL, NULL, NULL, 'Present perfect continuous with "for" + duration. Llevar + verb + ing = have been + verb + ing.', '2026-02-17 09:58:54.170896+00', NULL, NULL, 'both', '{"Present tense"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('62102f8b-6513-48ae-80a6-b7742cfb6dbe', 1342, 'matching', 'B1', 'grammar', 'Match each verb form to its use.', '["match_all_pairs"]', '[{"left": {"type": "text", "label": "", "content": "present simple"}, "right": {"type": "text", "label": "", "content": "regular habits and facts"}}, {"left": {"type": "text", "label": "", "content": "present perfect continuous"}, "right": {"type": "text", "label": "", "content": "an action that started in the past and is still ongoing"}}, {"left": {"type": "text", "label": "", "content": "used to + infinitive"}, "right": {"type": "text", "label": "", "content": "a past habit that no longer happens"}}, {"left": {"type": "text", "label": "", "content": "was/were + verb + ing"}, "right": {"type": "text", "label": "", "content": "an action in progress in the past"}}]', NULL, NULL, NULL, NULL, NULL, '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('7b1262d9-1fa9-403e-98e7-43153515f6a5', 2008, 'sentence_building', 'A2', 'travel', 'What time is breakfast served?', 'A qué hora se sirve el desayuno?', '["a", "qué", "hora", "se", "sirve", "el", "desayuno", "sirven", "la", "cena", "empieza", "almuerzo"]', NULL, NULL, NULL, NULL, '"Se sirve" is the passive reflexive, used to say when something is served. "A qué hora" = at what time. "El desayuno" = breakfast; "el almuerzo" = lunch; "la cena" = dinner.', '2026-04-13 09:19:30.039983+00', NULL, NULL, 'es', '{Travel}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('33e5eca5-98c0-47f1-a2d0-96cf56b4c615', 1066, 'multiple_choice', 'A2', 'business_phrasal_verbs', 'The manager asked everyone to _______ their ideas before the next meeting.', 'think over', '["think over", "think up", "think about", "think through"]', NULL, NULL, NULL, 'To consider for some time before deciding.', 'To think over means to consider something carefully before deciding. Compare: think up = to invent or come up with an idea.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Business phrasal verb"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('0ad6c863-55e5-4124-ab96-19e3b48131e6', 1067, 'multiple_choice', 'B1', 'business_phrasal_verbs', 'The finance team will _______ the numbers and let us know if the project is viable.', 'run through', '["run through", "run up", "run across", "run down"]', NULL, NULL, NULL, 'To go through a list or process quickly.', 'To run through the numbers means to go over them quickly and systematically. Compare: run up = to accumulate costs or debt; run down = to gradually reduce, or to speak badly of someone.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Business phrasal verb","Financial vocabulary"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('0003cd08-9211-4b28-a5e3-b8a674422d5e', 1068, 'multiple_choice', 'B1', 'business_phrasal_verbs', 'It took six months to _______ a contract that worked for both companies.', 'draw up', '["draw up", "draw on", "draw out", "draw back"]', NULL, NULL, NULL, 'To prepare a formal document (contract, plan).', 'To draw up a contract or plan means to prepare a formal written version of it.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Business phrasal verb","Business vocabulary"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('0d228670-dab7-457b-bf0f-b9e437792aa1', 1069, 'multiple_choice', 'B1', 'business_phrasal_verbs', 'After unexpected delays, the project went significantly _______ budget.', 'over', '["over", "above", "past", "beyond"]', NULL, NULL, NULL, 'To exceed the budget — went ___ budget.', 'To go over budget means to spend more than planned. This is a fixed expression — above, past, and beyond don''t work here.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Business phrasal verb","Fixed expression","Financial vocabulary"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('3438f673-48a0-4b7f-96b6-1bf84c0e7189', 1065, 'multiple_choice', 'A2', 'business_phrasal_verbs', 'Please _______ the contract carefully before you sign it.', 'go over', '["go over", "go back", "go on", "go ahead"]', NULL, NULL, NULL, 'To review carefully — check every detail.', 'To go over (or go through) a document means to examine it carefully, checking each part. Both are correct here.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Business phrasal verb"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('4e0926b6-8647-4282-99d0-e39a258c5943', 1531, 'multiple_choice', 'A2', 'business_vocabulary', 'The amount of money a business makes after paying all its costs is called _____.', 'profit', '["profit", "turnover", "revenue", "investment"]', NULL, NULL, NULL, 'The money that *stays* with the company after paying everyone and everything.', 'Profit is what remains after all costs and expenses have been deducted from revenue. A company that spends more than it earns makes a loss.', '2026-03-26 08:02:12.742714+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('772183fb-bf33-437d-a155-3893f4cd63a3', 1532, 'multiple_choice', 'A2', 'business_vocabulary', 'A sales _____ is a percentage of the sale price paid to the person who made the sale.', 'commission', '["commission", "bonus", "salary", "tip"]', NULL, NULL, NULL, 'A percentage of the sale — so the more you sell, the more you earn.', 'Commission is a payment based on a percentage of the sales a person generates. It is common in sales roles and incentivises staff to sell more.', '2026-03-26 08:02:12.742714+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('54bb844a-a72b-409e-89e4-9933e8d331eb', 1533, 'multiple_choice', 'A2', 'business_vocabulary', 'A _____ is a goal or level of performance that a company or individual aims to reach.', 'target', '["target", "policy", "procedure", "strategy"]', NULL, NULL, NULL, 'An *objective* — something to aim at.', 'A target is a specific goal set for an individual or team — for example, a sales target or a production target. Reaching your targets is often linked to bonuses or performance reviews.', '2026-03-26 08:02:12.742714+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('653ff007-0573-4d06-9513-4aedb527985d', 1534, 'multiple_choice', 'A2', 'business_vocabulary', 'When a company spends more money than it earns, it makes a _____.', 'loss', '["loss", "debt", "deficit", "shortfall"]', NULL, NULL, NULL, 'The opposite of profit. One word.', 'A loss occurs when costs exceed revenue. A company making consistent losses may eventually become insolvent. Compare: profit (when revenue exceeds costs).', '2026-03-26 08:02:12.742714+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('bf680403-7b11-4c02-b92f-fb9407fc5771', 1446, 'gap_fill', 'A2', 'spanish', 'Todas las mañanas me _____ antes de desayunar.', 'ducho', NULL, NULL, NULL, NULL, NULL, 'Ducharse es un verbo reflexivo. Primera persona singular del presente: me ducho.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'es', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('cd9526ef-f8ee-44ae-a17c-3687ab3a1989', 1070, 'multiple_choice', 'B2', 'business_phrasal_verbs', 'After months of planning, the directors finally _______ a workable restructuring plan.', 'came up with', '["came up with", "came across", "came around", "came out with"]', NULL, NULL, NULL, 'To invent or think of (a plan, an idea).', 'To come up with something means to produce or think of an idea, plan, or solution. It implies creativity or effort.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Business phrasal verb"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('8706fac5-61f2-48fb-b5e2-b15a41f71744', 1071, 'multiple_choice', 'B2', 'business_phrasal_verbs', 'The aggressive expansion plan _______ the company''s cash reserves very quickly.', 'ate into', '["ate into", "ate up", "ate away", "ate all"]', NULL, NULL, NULL, 'To gradually reduce (savings, time, resources).', 'To eat into something means to gradually reduce or deplete it — typically money, time, or resources. Very common in financial contexts.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Business phrasal verb","Financial vocabulary"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('e5a8b66a-7fb4-4a01-9e9f-36bee91cb546', 1072, 'gap_fill', 'B1', 'business_phrasal_verbs', 'The new director has been asked to _______ the company''s unprofitable southern division and restore it to profitability.', 'turn around', NULL, NULL, NULL, NULL, 'To rescue a failing business — make it profitable again.', 'To turn around a struggling business means to make it successful again after a period of poor performance.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Business phrasal verb","Business vocabulary"}', false, 'Often paired with "company", "business", "fortunes".', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('78ef6fd4-e657-4462-9d05-5a170d280bc9', 1073, 'gap_fill', 'B1', 'business_phrasal_verbs', 'We need to _______ our operating costs if we want to stay competitive.', 'cut down on', NULL, NULL, NULL, '["cut back on", "reduce", "bring down"]', 'To reduce (costs, consumption).', 'To cut down on (or cut back on) costs means to reduce spending. Both are equally correct here.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Business phrasal verb","Financial vocabulary"}', false, 'Like trimming back a tree.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('8be4800b-b9f6-4a3f-a7c6-b586e59a7594', 1074, 'gap_fill', 'B2', 'business_phrasal_verbs', 'The legal team is _______ the terms of the contract very carefully before anything is signed.', 'going over', NULL, NULL, NULL, '["going through"]', 'Currently reviewing carefully.', 'To go over (or go through) a contract means to review it carefully, checking all the terms and conditions.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Business phrasal verb"}', false, 'Form: be + verb-ing for ongoing action.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('84f88bbf-409c-439f-9d50-4cd0c22c7b87', 1075, 'gap_fill', 'B2', 'business_phrasal_verbs', 'After the failed product launch, it took the brand two years to _______ its reputation.', 'build up', NULL, NULL, NULL, '["rebuild", "restore", "recover"]', 'To construct gradually — like building a wall, brick by brick.', 'To build up a reputation means to develop it gradually over time. After damage, rebuild and restore are also common alternatives.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Business phrasal verb"}', false, 'Often paired with reputation, trust, a business.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('f1dbe941-058b-4f5c-aeaf-4ae22123d56e', 1076, 'gap_fill', 'B2', 'business_phrasal_verbs', 'The CEO _______ her experience in emerging markets when pitching to the investors.', 'drew on', NULL, NULL, NULL, '["drew upon"]', 'To make use of (experience, knowledge, resources).', 'To draw on something means to use it as a resource — experience, skills, knowledge, or connections.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Business phrasal verb"}', false, 'Like drawing water from a well.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('d8f5965b-66b5-4471-a701-67d27b2d9336', 1077, 'gap_fill', 'C1', 'business_phrasal_verbs', 'The audit revealed that the management team had been _______ significant financial irregularities for years.', 'covering up', NULL, NULL, NULL, NULL, 'To conceal — hide wrongdoing from view.', 'To cover up means to deliberately conceal wrongdoing or mistakes. The noun is a cover-up.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Business phrasal verb"}', false, 'Form: be + verb-ing for ongoing action.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('c5637bb9-1b5c-4e4c-b633-0993fefea11a', 1078, 'gap_fill', 'C1', 'business_phrasal_verbs', 'After intense pressure from shareholders, the company agreed to _______ its controversial data-sharing practices.', 'phase out', NULL, NULL, NULL, '["do away with"]', 'To gradually discontinue — over phases or stages.', 'To phase out a practice or product means to withdraw it gradually and systematically, rather than stopping all at once.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Business phrasal verb"}', false, 'Opposite of "phase in".', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('b7d20097-3dba-4095-a89f-8ebe97b5c67d', 1079, 'gap_fill', 'C1', 'business_phrasal_verbs', 'She managed to _______ the hostile board members and get them to support the new strategy.', 'win over', NULL, NULL, NULL, '["bring around", "talk round", "bring round"]', 'To persuade — convert to your side.', 'To win someone over means to persuade them to change their position or gain their support, often after initial resistance.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Business phrasal verb"}', false, 'Like winning a battle for hearts and minds.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('24f1db93-a953-4053-9d21-817beddea32d', 1080, 'gap_fill', 'C1', 'business_phrasal_verbs', 'The legal dispute between the two firms has been _______ for nearly three years with no resolution in sight.', 'dragging on', NULL, NULL, NULL, NULL, 'To continue for too long — boringly extending.', 'If something drags on, it continues for much longer than expected or desired. Commonly used for disputes, negotiations, and meetings.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Business phrasal verb"}', false, 'Form: be + verb-ing.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('e8ea1ccf-6b18-4f6f-b279-2deb434e445d', 1235, 'multiple_choice', 'B1', 'business_phrasal_verbs', 'The board decided to _____ the merger after concerns were raised by shareholders.', 'call off', '["call off", "call up", "call out", "call back"]', NULL, NULL, NULL, 'To cancel — same as "call off a search".', 'Call off means to cancel something that was planned. Compare: the strike was called off after negotiations succeeded.', '2026-03-18 19:58:52.376507+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('ce98c64b-a01a-4281-b8a5-f45912aa5633', 1544, 'gap_fill', 'B2', 'business_vocabulary', 'The legal _____ of a company defines the maximum amount its shareholders can lose if it goes under.', 'liability', NULL, NULL, NULL, NULL, 'What shareholders *owe* if the company fails — limited in most modern companies.', 'Liability refers to a company''s legal financial obligations. Limited liability means shareholders can only lose what they invested. This is one of the key advantages of forming a limited company.', '2026-03-26 08:02:12.742714+00', NULL, NULL, 'en', '{}', false, 'The opposite of an asset on a balance sheet.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('9f6ae401-3e16-4f7c-92ac-f1db2902622e', 1537, 'multiple_choice', 'B1', 'business_vocabulary', 'The percentage of total market sales held by one company is called its market _____.', 'share', '["share", "position", "reach", "dominance"]', NULL, NULL, NULL, 'You have a *piece* of the market — what''s the word for a piece of something?', 'Market share measures how much of the total market a company controls. A company with 30% market share sells 30% of all products in that category. It is a key indicator of competitive strength.', '2026-03-26 08:02:12.742714+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('393bdac6-fbef-43b3-878d-050f1f15e0ef', 1538, 'multiple_choice', 'B1', 'business_vocabulary', 'When a company lets employees go because of financial difficulties rather than poor performance, it is called _____.', 'redundancy', '["redundancy", "dismissal", "resignation", "suspension"]', NULL, NULL, NULL, 'Not because they did anything wrong — the *role* is no longer needed.', 'Redundancy occurs when a job role is no longer needed, often due to restructuring or financial pressures. It differs from dismissal, which is for performance or conduct reasons.', '2026-03-26 08:02:12.742714+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('82973cab-609a-4bf4-a617-f6fe8507422e', 1447, 'gap_fill', 'A2', 'spanish', 'Normalmente _____ a las ocho de la mañana.', 'desayuno', NULL, NULL, NULL, NULL, NULL, 'Desayunar significa to have breakfast. Primera persona singular del presente: desayuno.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'es', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('38a0d6fc-8fe5-407b-8d7e-a72f31c6a35b', 2009, 'sentence_building', 'A2', 'travel', 'Can I have a late checkout, please?', 'Puedo hacer el check-out más tarde, por favor?', '["puedo", "hacer", "el", "check-out", "más", "tarde", "por", "favor", "salida", "tardío", "temprano", "puedes"]', NULL, NULL, NULL, NULL, '"Puedo + infinitive" = can I? (first person of poder). "Más tarde" = later. "Check-out" is widely used in Spanish-speaking hotels.', '2026-04-13 09:19:30.039983+00', NULL, NULL, 'es', '{Travel}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('33fa4021-27fb-47b6-9957-fcca93cc4d1f', 64, 'gap_fill', 'B1', 'too_enough', 'I''m not tall ___ (_ _ _ _ _ _) to reach the top shelf.', 'enough', NULL, NULL, NULL, NULL, 'Enough comes after adjectives', 'Enough comes after adjectives and means sufficient.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{"Too & enough"}', false, 'Form: adjective + enough. (Compare: "enough money" — enough comes BEFORE nouns.)', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('9a5caa2b-5125-4d80-a294-95dbb2a632dd', 44, 'gap_fill', 'B1', 'quantifiers', 'There isn''t ___ (many / much) milk left. We need to buy some.', 'much', NULL, NULL, NULL, NULL, 'Much is used with uncountable nouns', 'Much is used with uncountable nouns in negative sentences and questions.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{Quantifier}', false, 'Milk, water, bread, money — things you can''t count individually.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('13efa99e-c3ad-4284-8851-2d001743e11f', 46, 'gap_fill', 'B2', 'quantifiers', 'There are ___ (a few / a little) problems we need to discuss.', 'a few', NULL, NULL, NULL, NULL, 'A few is used with countable nouns', 'A few is used with countable nouns to mean ''some''.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{Quantifier}', false, 'Problems can be counted: 2 problems, 5 problems.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('b678ad5b-2aed-4d25-98af-2e4c9c08ea22', 47, 'gap_fill', 'B2', 'quantifiers', 'We have ___ (a few / a little) time before the meeting starts.', 'a little', NULL, NULL, NULL, NULL, 'A little is used with uncountable nouns', 'A little is used with uncountable nouns to mean ''some''.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{Quantifier}', false, 'Time can''t be counted as individual units.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('cfc8c7c1-3e11-47e2-a7e3-2a7e615ac256', 49, 'gap_fill', 'B2', 'third_conditional', 'If I ___ (know) about the party, I would have come.', 'had known', NULL, NULL, NULL, NULL, 'Third conditional: If + past perfect, would have + past participle', 'Third conditional is used for hypothetical past situations.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{Conditional}', false, 'Imagining a different past — but it''s already too late.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('0bfc6191-f3f2-41a5-b98a-5404b24e6fa4', 50, 'gap_fill', 'B2', 'third_conditional', 'She ___ (pass) the exam if she had studied harder.', 'would have passed', NULL, NULL, NULL, NULL, 'Would have + past participle in the result clause', 'Third conditional result clause: would have + past participle.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{Conditional}', false, 'Form: would have + past participle. (She didn''t pass — but she could have.)', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('348c5757-568e-40a1-9565-194b6a6a2815', 51, 'gap_fill', 'B1', 'phrasal_verbs', 'Can you ___ (look _ _ _ _ _ ) my cats while I''m on holiday please?', 'look after', NULL, NULL, NULL, NULL, 'Look after means to take care of', 'Look after means to take care of someone or something.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{"Phrasal verb"}', false, 'A two-word verb: "look" + a preposition meaning "after" the cats.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('fc6c17f4-1c58-422f-bdcc-a1fe08c63289', 52, 'gap_fill', 'B1', 'phrasal_verbs', 'I need to ___ (find _ _ _ ) what time the train leaves.', 'find out', NULL, NULL, NULL, NULL, 'Find out means to discover information', 'Find out means to discover or learn information.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{"Phrasal verb"}', false, 'A two-word verb: "find" + a preposition. You don''t know it yet, but you will.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('87a926c3-95ae-4193-801e-7d32eae0e839', 53, 'gap_fill', 'B2', 'phrasal_verbs', 'The meeting has been ___ (put _ _ _) until next week.', 'put off', NULL, NULL, NULL, NULL, 'Put off means to postpone', 'Put off means to postpone or delay something.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{"Phrasal verb"}', false, 'The meeting isn''t cancelled — just rescheduled.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('9bf53a6e-cdc7-4595-b08f-b8058b52b707', 54, 'gap_fill', 'B2', 'phrasal_verbs', 'It took me ages to ___ (work _ _ _) the answer to that problem.', 'work out', NULL, NULL, NULL, NULL, 'Work out means to solve or calculate', 'Work out means to solve a problem or calculate something.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{"Phrasal verb"}', false, 'A two-word verb: "work" + a preposition meaning to figure out.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('985da192-f802-4851-99a7-6af12fef3a31', 57, 'gap_fill', 'B2', 'passive_voice_present', 'Spanish ___ (speak) in many countries around the world.', 'is spoken', NULL, NULL, NULL, NULL, 'Passive present: is/are + past participle', 'Passive voice present: is/are + past participle.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{"Passive voice"}', false, 'Form: is/are + past participle.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('3d3e50af-a83e-403d-8adb-5577dc44c546', 58, 'gap_fill', 'B2', 'passive_voice_future', 'The new hospital ___ (open) next month.', 'will be opened', NULL, NULL, NULL, NULL, 'Passive future: will be + past participle', 'Passive voice future: will be + past participle.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{"Passive voice"}', false, 'Form: will be + past participle.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('7c2b6989-3fd8-4d26-9e1a-a8b469756d84', 60, 'gap_fill', 'B2', 'wish', 'I wish I ___ (study) harder when I was at school.', 'had studied', NULL, NULL, NULL, NULL, 'Wish + past perfect for past regrets', 'Use past perfect after ''wish'' for regrets about the past.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{"Wish & regret"}', false, 'Form: had + past participle. Looking back with regret.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('e570296b-785b-404e-9b72-3296c2b59693', 61, 'gap_fill', 'B1', 'present_perfect_for_since', 'They''ve lived in this house ___ (for / since) 2010.', 'since', NULL, NULL, NULL, NULL, 'Since is used with a point in time', 'Since is used with a specific point in time when something started.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{"Present tense"}', false, 'Since 2010, since Monday, since I was born — a starting point.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('3131cbea-e02e-4422-9329-ea6a8c433789', 63, 'gap_fill', 'B1', 'too_enough', 'This coffee is ___ (_ _ _) hot to drink right now.', 'too', NULL, NULL, NULL, NULL, 'Too means more than necessary', 'Too means more than is wanted or needed.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{"Too & enough"}', false, '"Too hot" = uncomfortably hot. A negative excess.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('68b5b756-7464-4c60-9565-8e518dfad8c3', 65, 'gap_fill', 'B2', 'so_such', 'It was ___ (so / such) a boring film that I fell asleep.', 'such', NULL, NULL, NULL, NULL, 'Such + a/an + adjective + noun', 'Such is used with a/an + adjective + noun.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{"Linking word"}', false, 'Such a + adjective + noun. (So + adjective only.)', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('8cb3ff61-b292-40da-8375-a2787e3020ee', 66, 'gap_fill', 'B2', 'so_such', 'The test was ___ (so / such) difficult that nobody passed.', 'so', NULL, NULL, NULL, NULL, 'So + adjective/adverb', 'So is used directly with adjectives or adverbs.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{"Linking word"}', false, 'So + adjective alone. (Such needs a noun.)', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('48b71834-cc0f-42f6-92e2-58d88a5bd975', 67, 'gap_fill', 'B1', 'making_suggestions', 'Why don''t we ___ (_ _) to the cinema tonight?', 'go', NULL, NULL, NULL, NULL, 'Why don''t we + infinitive without ''to''', 'Why don''t we is followed by the infinitive without ''to'' when making suggestions.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{"Making suggestions"}', false, '"Why don''t we go..." — invitation form.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('79662f1b-cd2a-421f-9e71-eb9581f59411', 1448, 'gap_fill', 'A2', 'spanish', 'Mi padre _____ muy temprano porque empieza a trabajar a las seis.', 'se levanta', NULL, NULL, NULL, NULL, NULL, 'Levantarse es un verbo reflexivo. Tercera persona singular del presente: se levanta.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'es', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('949def93-9def-4163-aa26-4fff15179126', 1450, 'gap_fill', 'A2', 'spanish', 'Mi hermana _____ veinte minutos en arreglarse cada mañana.', 'tarda', NULL, NULL, NULL, NULL, NULL, 'Tardar significa to take (time). Tercera persona singular: tarda. Por ejemplo: tarde veinte minutos = I take twenty minutes.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'es', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('afa303e5-35ab-4647-ac84-8a2c8a9d9df6', 1451, 'gap_fill', 'A2', 'spanish', 'Después de comer, mi abuelo siempre _____ una siesta corta.', 'echa', NULL, NULL, NULL, NULL, NULL, 'Echar una siesta es una expresión fija que significa to take a nap. Tercera persona singular de echar: echa.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'es', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('7e2801c5-5790-4ea8-92c7-03bfab7f44bb', 1452, 'gap_fill', 'A2', 'spanish', 'Antes de acostarme, _____ mis cosas para el día siguiente.', 'preparo', NULL, NULL, NULL, NULL, NULL, 'Preparar es un verbo regular -ar. Primera persona singular del presente: preparo.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'es', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('5136d02d-70cf-426e-8561-fb870be5c131', 1906, 'matching', 'A2', 'vocabulary', 'Match each word to its meaning.', 'match_all_pairs', '[{"left": {"type": "text", "label": "", "content": "sneeze"}, "right": {"type": "text", "label": "", "content": "air is forced out through your nose suddenly"}}, {"left": {"type": "text", "label": "", "content": "cough"}, "right": {"type": "text", "label": "", "content": "air is forced out through your throat"}}, {"left": {"type": "text", "label": "", "content": "yawn"}, "right": {"type": "text", "label": "", "content": "you open your mouth wide, usually when tired or bored"}}, {"left": {"type": "text", "label": "", "content": "hiccough/hiccup"}, "right": {"type": "text", "label": "", "content": "you make a sudden repeated sound you cannot control"}}]', NULL, NULL, NULL, NULL, NULL, '2026-04-08 18:25:27.713957+00', NULL, NULL, 'en', '{Vocabulary,Body}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('d6d2e188-5067-4363-b8d7-8286f9f0e292', 1587, 'error_correction', 'B1', 'business_vocabulary', 'The manager was responsible of training all new members of staff.', 'The manager was responsible for training all new members of staff.', '[]', NULL, NULL, NULL, 'Check the preposition — which one goes with "responsible"?', 'Responsible for is the correct collocation. Compare: in charge of, accountable for. Responsible of does not exist in English.', '2026-03-26 08:02:12.742714+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('05cbd854-c1ea-465a-a943-5766fa311bce', 1588, 'error_correction', 'B1', 'business_vocabulary', 'The company has invested on new technology to improve efficiency.', 'The company has invested in new technology to improve efficiency.', '[]', NULL, NULL, NULL, 'You don''t *invest on* something — check the preposition.', 'Invest in is the correct collocation. You invest in an asset, technology, or person. Invest on does not exist in standard business English.', '2026-03-26 08:02:12.742714+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('e9ea9127-5988-41b0-ad32-2a45a286273e', 1591, 'error_correction', 'C1', 'business_vocabulary', 'The director was accused for misusing company funds.', 'The director was accused of misusing company funds.', '[]', NULL, NULL, NULL, '"Accuse" doesn''t take the preposition you might expect from "blame".', 'Accuse someone of something is the correct structure. Compare: charge someone with, suspect someone of, blame someone for.', '2026-03-26 08:02:12.742714+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('de19e699-5b6c-4782-b5e4-8c8c670615a8', 1592, 'error_correction', 'C1', 'business_vocabulary', 'She resigned in spite for receiving an excellent performance review.', 'She resigned in spite of receiving an excellent performance review.', '[]', NULL, NULL, NULL, 'The three-word version of "despite" — check the ending.', 'In spite of is the three-word equivalent of despite. In spite for is not a standard construction.', '2026-03-26 08:02:12.742714+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('33f02c4c-fe15-4e5f-9768-00ea3c31bf1f', 1586, 'error_correction', 'A2', 'business_vocabulary', 'We need to make a decision until the end of the week.', 'We need to make a decision by the end of the week.', '[]', NULL, NULL, NULL, '"Until" means *up to and during*. Think about the deadline word instead.', 'By means no later than a specific point in time. Until means up to and continuing to that point. You reach a deadline by a time, not until one.', '2026-03-26 08:02:12.742714+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('3d250083-fd0c-4f03-b906-546c07311493', 68, 'gap_fill', 'B1', 'making_suggestions', 'Let''s ___ (_ _ _) that new restaurant for lunch.', 'try', NULL, NULL, NULL, NULL, 'Let''s + infinitive without ''to''', 'Let''s is followed by the infinitive without ''to''.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{"Making suggestions"}', false, '"Let''s try..." — including yourself in the suggestion.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('375ad178-322f-4877-9f42-af4eb31a8a0e', 1590, 'error_correction', 'B2', 'business_vocabulary', 'The new policy had a strong impact in customer satisfaction scores.', 'The new policy had a strong impact on customer satisfaction scores.', '[]', NULL, NULL, NULL, NULL, 'Have an impact on is the correct collocation. Impact is always followed by on when used as a noun in this way. Compare: have an effect on, have an influence on.', '2026-03-26 08:02:12.742714+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('454cf606-7cca-448e-9b3d-19cc0666cb2b', 1593, 'error_correction', 'C2', 'business_vocabulary', 'The company''s performance stands in stark contrast with its competitors.', 'The company''s performance stands in stark contrast to its competitors.', '[]', NULL, NULL, NULL, NULL, 'In stark contrast to is the correct fixed phrase. Contrast is always followed by to (or with in some informal usage), but in stark contrast requires to.', '2026-03-26 08:02:12.742714+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('7ad3453a-b240-43f1-b6b2-895c3b7b1425', 69, 'gap_fill', 'B2', 'reported_questions', 'She asked me where I ___ (live).', 'lived', NULL, '["live"]', NULL, NULL, 'No question word order in reported questions', 'In reported questions, use statement word order (not question order). Native speakers might keep the verb in the present.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{"Reported speech"}', false, 'Backshift the tense: live → lived. No question mark, no inversion.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('fd29a711-cf01-4384-a5dc-2d9e310d8425', 71, 'gap_fill', 'B1', 'countable_uncountable', 'Can I have ___ (a / an / some) water, please?', 'some', NULL, '["a", "", "-"]', NULL, NULL, 'Water is uncountable', 'Some is used with uncountable nouns in requests and offers.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{"Uncountable noun"}', false, 'You can''t say "a water" — water is uncountable.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('9b807dbc-e147-4385-8a94-614ae0e10d5a', 1596, 'error_correction', 'A2', 'spanish', 'Ayer me quedé en casa porque estuve muy cansado.', 'Ayer me quedé en casa porque estaba muy cansado.', '[]', NULL, NULL, NULL, NULL, 'Estar cansado es un estado, no una acción completada. El imperfecto (estaba) describe estados y situaciones en el pasado. El indefinido (estuve) se usa para acciones con principio y fin definidos.', '2026-03-26 08:02:12.742714+00', NULL, NULL, 'es', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('769465a5-7786-4b6c-a921-70414584c8d9', 73, 'gap_fill', 'B2', 'have_something_done', 'I need to ___ (have / my car / service).', 'have my car serviced', NULL, '["have the car serviced", "get the car serviced"]', NULL, NULL, 'Have + object + past participle', 'Have/get something done means to arrange for someone else to do something for you.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{Causative}', false, 'Someone else does it for you. Form: have + object + past participle.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('58b610db-ef42-4070-bc89-a9b92c37f5fd', 1453, 'gap_fill', 'A2', 'spanish', 'Mi hermana _____ sin despertador todas las mañanas a la misma hora.', 'se despierta', NULL, NULL, NULL, NULL, NULL, 'Despertarse es reflexivo y cambia la raíz (e→ie): me despierto, te despiertas, se despierta.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'es', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('f31a7553-260c-4354-8727-c12835c3f022', 74, 'gap_fill', 'B2', 'have_something_done', 'She''s ___ (have / her hair / cut) tomorrow.', 'having her hair cut', NULL, '["having a hair cut", "getting a hair cut"]', NULL, NULL, 'Have + object + past participle', 'Have/get something done structure.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{Causative}', false, 'The hairdresser cuts her hair — she''s having it done. Form: be + having + object + past participle.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('57ef7350-f7d5-4f46-b772-0a32c236f73f', 76, 'gap_fill', 'B1', 'linking_words', 'I was tired, ___ (but / so / because) I went to bed early.', 'so', NULL, NULL, NULL, NULL, 'Showing result or consequence', 'So is used to show a result or consequence.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{"Linking word"}', false, '"Tired, SO bed" — cause and effect.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('b0326847-6163-4bf4-a7b5-ff25a86c5905', 1599, 'error_correction', 'A2', 'spanish', 'Estoy acostumbrado de madrugar desde que era pequeño.', 'Estoy acostumbrado a madrugar desde que era pequeño.', '[]', NULL, NULL, NULL, NULL, 'Estar acostumbrado siempre va seguido de la preposición a, no de. Acostumbrado a + infinitivo es la estructura correcta.', '2026-03-26 08:02:12.742714+00', NULL, NULL, 'es', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('ac58297a-a5c2-4325-a9f3-6780de434aad', 1603, 'error_correction', 'A2', 'spanish', 'Llevo dos años estudiar español.', 'Llevo dos años estudiando español.', '[]', NULL, NULL, NULL, NULL, 'Con llevar + tiempo, se usa el gerundio, no el infinitivo: llevo dos años estudiando. Esta estructura equivale a "I have been studying Spanish for two years."', '2026-03-26 08:02:12.742714+00', NULL, NULL, 'es', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('67c46f87-77f7-4198-bfa6-59fd90f3d0eb', 1604, 'error_correction', 'A2', 'spanish', 'Después de la reunión, todos estaban de acuerdo por que era necesario cambiar la estrategia.', 'Después de la reunión, todos estaban de acuerdo en que era necesario cambiar la estrategia.', '[]', NULL, NULL, NULL, NULL, 'Estar de acuerdo en que es la expresión correcta. La preposición en es obligatoria antes de que en esta estructura. Sin ella, la frase es gramaticalmente incompleta. ', '2026-03-26 08:02:12.742714+00', NULL, NULL, 'es', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('dbd2c775-f9c8-4d3a-92f5-447a99576569', 1589, 'error_correction', 'B2', 'business_vocabulary', 'The project is slightly behind, but we should be able to catch up before the end of the month.', 'The project is slightly behind, but we should be able to catch up by the end of the month.', '[]', NULL, NULL, NULL, NULL, 'By the end of the month means no later than that point. Before is also possible here, but by is the standard expression for deadlines and target completion times.', '2026-03-26 08:02:12.742714+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('1ab69d0e-2efe-4e83-bcc1-7a7adb7dc50d', 1597, 'error_correction', 'A2', 'spanish', 'No me gusta nada las reuniones que empiezan muy temprano.', 'No me gustan nada las reuniones que empiezan muy temprano.', '[]', NULL, NULL, NULL, NULL, 'Con gustar, el verbo concuerda con lo que gusta, no con la persona. Las reuniones es plural, por lo que el verbo debe ser gustan, no gusta.', '2026-03-26 08:02:12.742714+00', NULL, NULL, 'es', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('7312735a-2577-4265-be8c-5f5ebed73045', 1598, 'error_correction', 'A2', 'spanish', 'Los nuevos empleados son muy trabajadoras y siempre llegan puntuales.', 'Los nuevos empleados son muy trabajadores y siempre llegan puntuales.', '[]', NULL, NULL, NULL, NULL, 'Los empleados es masculino plural, por lo que el adjetivo debe ser trabajadores, no trabajadoras. Los adjetivos deben concordar en género y número con el sustantivo.', '2026-03-26 08:02:12.742714+00', NULL, NULL, 'es', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('e5ace40d-230c-4e89-b216-9163b2d17a46', 1600, 'error_correction', 'A2', 'spanish', 'El año pasado viajamos a México y nos gustamos muchísimo.', 'El año pasado viajamos a México y nos gustó muchísimo.', '[]', NULL, NULL, NULL, NULL, 'Gustarse no existe en español. La construcción correcta es nos gustó (it pleased us / we loved it). Gustar funciona como "to please" — el sujeto es lo que gusta, no la persona.', '2026-03-26 08:02:12.742714+00', NULL, NULL, 'es', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('0f81a0de-025f-4619-bb3d-edb540881e28', 1605, 'error_correction', 'A2', 'spanish', 'Siempre me lavo las manos antes de sentarme para comer.', 'Siempre me lavo las manos antes de sentarme a comer.', '[]', NULL, NULL, NULL, NULL, 'Sentarse a + infinitivo es la estructura correcta. La preposición a es obligatoria entre sentarse y el infinitivo que expresa la acción que sigue. Compare: ponerse a trabajar, quedarse a cenar.', '2026-03-26 08:02:12.742714+00', NULL, NULL, 'es', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('9bdfcb8d-ccb7-4372-9c0b-38869c69fe0e', 1454, 'gap_fill', 'A2', 'spanish', 'En casa, _____ sobre las nueve de la noche, lo cual es bastante normal en España.', 'cenamos', NULL, NULL, NULL, NULL, NULL, 'Cenar significa to have dinner. Primera persona plural del presente: cenamos.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'es', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('cc6653cf-bad0-40d6-852c-5e23f936113b', 1455, 'gap_fill', 'A2', 'spanish', 'Por la mañana prefiero _____ un café antes de salir de casa.', 'tomar', NULL, NULL, NULL, NULL, NULL, 'Después de preferir + infinitivo, el infinitivo no cambia. Tomar un café significa to have a coffee en español.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'es', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('3d85a895-cfbc-4130-bab4-bebcc986e730', 1081, 'gap_fill', 'C1', 'business_phrasal_verbs', 'Demand for the product has _______ significantly since the negative press coverage.', 'tailed off', NULL, NULL, NULL, '["dropped off", "fallen off", "died down"]', 'To gradually decrease — fade away.', 'To tail off means to gradually decrease or decline. Compare: fall off, drop off. Note: died down suggests noise or excitement fading, not quantity declining.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Business phrasal verb","Financial vocabulary"}', false, 'Like an animal''s tail tapering to a point.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('297b9fe3-16fe-468f-abb9-2a8130a0fe6a', 1471, 'gap_fill', 'B2', 'phrasal_verbs', 'It''s hard to _____ with all the changes in technology — something new appears every week.', 'keep up', NULL, NULL, NULL, NULL, 'To maintain pace — not fall behind.', 'Keep up (with) means to maintain the same pace or level as something or someone that is advancing or changing.', '2026-03-18 20:30:31.624632+00', NULL, NULL, 'en', '{}', false, 'Often "keep up ___ change/news".', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('0d8b6de3-23b4-43f8-a8df-722a40f5833a', 1594, 'error_correction', 'A1', 'vocabulary', 'Despite working hard all year, he failed to meeting his annual targets.', 'Despite working hard all year, he failed to meet his annual targets.', '[]', NULL, NULL, NULL, NULL, 'Meeting in this context would be the noun or continuous form, but we need the verb in its infinitive: failed to + infinitive. Also: managed to + infinitive has the same pattern.', '2026-03-26 08:02:12.742714+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('b8b2be27-7789-4a45-8622-a62b91c4f9d0', 1595, 'error_correction', 'A2', 'grammar', 'The board knew about the risks, but it continued to moving forward anyway.', 'The board knew about the risks, but it continued to move forward anyway.', '[]', NULL, NULL, NULL, NULL, 'Continue can be followed by either a gerund or an infinitive, but continue moving and continue to move have slightly different meanings. Continued to moving is never ok.  In formal written English, continue to + infinitive is more standard. ', '2026-03-26 08:02:12.742714+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('d51b2c90-a90e-4f12-bd4f-e2d1b003787e', 1601, 'error_correction', 'A2', 'spanish', 'Normalmente voy al gimnasio las lunes.', 'Normalmente voy al gimnasio los lunes.', '[]', NULL, NULL, NULL, NULL, 'Para expresar hábitos en días de la semana, se usa el artículo los/las sin preposición: los lunes, los viernes. Los días de la semana son masculinos. ', '2026-03-26 08:02:12.742714+00', NULL, NULL, 'es', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('7288203b-b4fa-4031-b13e-4ebc55c5a9e2', 1602, 'error_correction', 'A2', 'spanish', 'Mi abuela tiene setenta i ocho años y todavía trabaja a tiempo parcial.', 'Mi abuela tiene setenta y ocho años y todavía trabaja a tiempo parcial.', '[]', NULL, NULL, NULL, NULL, 'Los números compuestos a partir del 31 sí se escriben separados: setenta y ocho, cuarenta y cinco. Solo los números del 16 al 29 se escriben en una sola palabra usando i.', '2026-03-26 08:02:12.742714+00', NULL, NULL, 'es', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('0353e02c-9f08-4dac-bd2c-9c298e10f907', 1502, 'gap_fill', 'B1', 'hotel_vocabulary', 'The guest called reception to report that the air conditioning in their room was not working. Reception sent a _____ engineer to fix it.', 'maintenance', NULL, NULL, NULL, NULL, 'The team that repairs and maintains hotel equipment.', 'The maintenance team is responsible for repairs and the upkeep of all equipment in the hotel — from air conditioning and plumbing to lifts and electrical systems.', '2026-03-23 08:55:51.646247+00', NULL, NULL, 'en', '{}', false, 'Sharing a root with "maintain".', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('a1989f34-3c46-4701-b149-9c2be98bc0e6', 1503, 'gap_fill', 'B1', 'hotel_vocabulary', 'At the end of their stay, the guests went to reception to _____ their bill.', 'settle', NULL, NULL, NULL, NULL, 'To pay the bill — to resolve what''s owed.', 'Settle the bill means to pay the full outstanding amount owed. It is the standard expression used in hotel contexts. Compare: pay the bill, clear the balance.', '2026-03-23 08:55:51.646247+00', NULL, NULL, 'en', '{}', false, 'Same verb as "settle a debt" or "settle an argument".', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('f8ee0072-dba9-4cc4-bda1-d2a7db542809', 1504, 'gap_fill', 'B2', 'hotel_vocabulary', 'When a guest books a superior room but a standard room is sold to them instead due to an error, it is called a _____.', 'downgrade', NULL, NULL, NULL, NULL, 'To move to a lower category — opposite of upgrade.', 'A downgrade is the opposite of an upgrade — the guest receives a lower category room than they booked. It should be accompanied by an apology and usually a discount or compensation.', '2026-03-23 08:55:51.646247+00', NULL, NULL, 'en', '{}', false, 'Compound noun: down + grade.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('c31bda62-1c39-4920-a474-64882034dd7b', 1505, 'gap_fill', 'B2', 'hotel_vocabulary', 'The hotel trained its reception team to _____ guests by suggesting room upgrades and restaurant bookings at check-in.', 'upsell', NULL, NULL, NULL, NULL, 'To sell a more expensive option to an existing customer.', 'Upselling means encouraging a guest to spend more by offering a better room, additional services, or enhancements. It increases revenue while potentially improving the guest''s experience.', '2026-03-23 08:55:51.646247+00', NULL, NULL, 'en', '{}', false, 'Compound verb: up + sell.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('455bb350-ad7e-449c-8b5e-55d70697a166', 1506, 'gap_fill', 'C1', 'hotel_vocabulary', 'The hotel''s _____ manager was on duty overnight and handled all complaints and emergencies in the absence of senior management.', 'duty', NULL, NULL, NULL, NULL, '___ manager — the manager currently working.', 'The duty manager is the senior member of staff responsible for running the hotel during a specific shift, particularly evenings and nights. They have authority to make decisions on complaints, room moves, and emergencies.', '2026-03-23 08:55:51.646247+00', NULL, NULL, 'en', '{}', false, 'Same as "officer on ___" in police context.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('ad74c151-7021-4310-9b25-5a4f28f9c952', 1516, 'gap_fill', 'A2', 'spanish', 'Al llegar al hotel, fui a recepción para hacer el _____.', 'check-in', NULL, NULL, NULL, NULL, NULL, 'El check-in es el proceso de registrarse en el hotel a la llegada. En español también se dice "registro" o "entrada", pero check-in es el término más usado en los hoteles.', '2026-03-23 08:55:51.646247+00', NULL, NULL, 'es', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('ca3d8b27-5428-41bb-a3f3-c6cdc2a85a51', 1517, 'gap_fill', 'A2', 'spanish', 'Pedí una habitación _____ porque viajaba solo y no necesitaba dos camas.', 'individual', NULL, NULL, NULL, NULL, NULL, 'Una habitación individual (o sencilla) tiene una sola cama para una persona. Una habitación doble tiene una cama grande para dos personas. Una habitación twin tiene dos camas individuales.', '2026-03-23 08:55:51.646247+00', NULL, NULL, 'es', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('ab38504c-1f59-4d4f-9590-9d4a3b6ead1d', 1518, 'gap_fill', 'A2', 'spanish', 'El desayuno estaba _____ en el precio de la habitación, así que no tuvimos que pagar nada extra.', 'incluido', NULL, NULL, NULL, NULL, NULL, 'Incluido significa que algo forma parte del precio total y no hay que pagar por ello de forma adicional. Es una de las palabras más útiles al hablar de reservas de hotel.', '2026-03-23 08:55:51.646247+00', NULL, NULL, 'es', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('1ec7fdbe-896d-4f2d-8f3c-0819a02a826b', 1519, 'gap_fill', 'A2', 'spanish', 'La habitación tenía unas vistas preciosas — se podía ver el _____ desde la ventana.', 'mar', NULL, NULL, NULL, NULL, NULL, 'Las vistas al mar son muy valoradas en los hoteles de costa. También se pueden pedir vistas a la piscina, a la montaña o al jardín al hacer la reserva.', '2026-03-23 08:55:51.646247+00', NULL, NULL, 'es', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('17abb0d5-27b6-4e77-8701-3b91338ec231', 1520, 'gap_fill', 'A2', 'spanish', 'Llamé a recepción para pedir más _____ porque en la habitación solo había una almohada.', 'almohadas', NULL, NULL, NULL, NULL, NULL, 'Almohada significa pillow en inglés. Es una de las peticiones más comunes en los hoteles. También puede pedir más toallas (towels) o mantas (blankets).', '2026-03-23 08:55:51.646247+00', NULL, NULL, 'es', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('b4678938-f56a-442a-a5de-ac1c5766a890', 1521, 'gap_fill', 'A2', 'spanish', 'El hotel tenía una _____ exterior muy grande con tumbonas y hamacas.', 'piscina', NULL, NULL, NULL, NULL, NULL, 'Piscina significa swimming pool. Es una instalación muy común en los hoteles de playa y de montaña en España. Una piscina exterior está al aire libre; una interior está cubierta.', '2026-03-23 08:55:51.646247+00', NULL, NULL, 'es', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('04494196-d91c-46ea-a295-2e783ed4a2bd', 1522, 'gap_fill', 'A2', 'spanish', 'A la hora de pagar, pregunté si podía pagar con _____ en lugar de en efectivo.', 'tarjeta', NULL, NULL, NULL, NULL, NULL, 'Tarjeta de crédito o débito es la forma más habitual de pagar en hoteles. En efectivo significa in cash. Muchos hoteles piden la tarjeta al hacer el check-in como garantía.', '2026-03-23 08:55:51.646247+00', NULL, NULL, 'es', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('37af3d1f-3b1d-4cbf-9904-036893c87004', 1523, 'gap_fill', 'A2', 'spanish', 'La habitación estaba en el tercer _____, así que cogimos el ascensor.', 'piso', NULL, NULL, NULL, NULL, NULL, 'Piso significa floor in a building. La planta baja es el ground floor. El primer piso es one floor up. El ascensor es the lift (British English) or elevator (American English).', '2026-03-23 08:55:51.646247+00', NULL, NULL, 'es', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('4ecb2077-0a35-4832-88fe-021891856d69', 1524, 'gap_fill', 'A2', 'spanish', 'Hice la _____ por internet con tres meses de antelación para conseguir un buen precio.', 'reserva', NULL, NULL, NULL, NULL, NULL, 'Reserva means reservation or booking. Hacer una reserva means to make a booking. Con antelación means in advance. Es recomendable reservar con antelación en temporada alta.', '2026-03-23 08:55:51.646247+00', NULL, NULL, 'es', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('20991685-e59d-4f45-aab2-ab142318bb9f', 1525, 'gap_fill', 'A2', 'spanish', 'Al salir del hotel, dejamos las maletas en la _____ de equipaje mientras esperábamos el taxi.', 'consigna', NULL, NULL, NULL, NULL, NULL, 'La consigna de equipaje (or the left luggage area) is where guests can store their bags after checking out. En inglés se dice luggage storage. Es muy útil cuando el vuelo de regreso es por la tarde.', '2026-03-23 08:55:51.646247+00', NULL, NULL, 'es', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('f7e6e1de-5afa-4811-9584-4e6574092fb2', 1501, 'gap_fill', 'B1', 'hotel_vocabulary', 'The receptionist offered to _____ the guest''s bags to their room while they waited in the lounge.', 'carry up', NULL, NULL, NULL, '["take up", "take"]', 'To take something up to a higher floor.', 'Carry up (or take up) means to transport a guest''s luggage from reception to their room. Porters or bellboys typically do this in larger hotels.', '2026-03-23 08:55:51.646247+00', NULL, NULL, 'en', '{}', false, '___ + the bags + up.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('e74e9dc1-5263-4b7a-864e-0b02b16797e3', 1555, 'gap_fill', 'C2', 'business_vocabulary', 'The group''s sprawling structure — dozens of unrelated businesses under one umbrella — was typical of an old-fashioned _____.', 'conglomerate', NULL, NULL, NULL, NULL, 'A large group of unrelated businesses — geology also uses this word for a rock made of different stones.', 'A conglomerate is a large corporation made up of many different, often unrelated, businesses. Once fashionable, conglomerates have fallen out of favour as investors prefer focused, specialist companies.', '2026-03-26 08:02:12.742714+00', NULL, NULL, 'en', '{}', false, 'Examples include Berkshire Hathaway and General Electric.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('8ea9562f-b0c2-491c-9a5b-e4999c9b39d5', 1855, 'gap_fill', 'A2', 'spanish', 'El trayecto en tren de Madrid a Sevilla _______ unas dos horas y media en el AVE.', 'dura', NULL, NULL, NULL, NULL, NULL, 'Usamos el presente para hablar de hechos o datos generales que siguen siendo válidos.', '2026-04-06 16:43:51.906934+00', NULL, NULL, 'es', '{Spanish}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('a1327350-4548-427a-84f9-e7eb32406911', 1856, 'gap_fill', 'A2', 'spanish', 'Siempre me _______ en el mismo sitio cuando voy a esa ciudad — el personal es muy amable.', 'alojo', NULL, NULL, NULL, NULL, NULL, '"Alojarse" = to stay (at a hotel/accommodation). Primera persona singular presente: me alojo.', '2026-04-06 16:43:51.906934+00', NULL, NULL, 'es', '{Spanish}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('6ab48fb9-ba06-45dc-ab82-75a25e6c38da', 1242, 'gap_fill', 'B1', 'business_phrasal_verbs', 'The project has been _____ because of a lack of funding.', 'put on the shelf', NULL, NULL, NULL, NULL, 'To postpone indefinitely — set aside literally.', 'Put on the shelf (or shelve) means to postpone or abandon a project indefinitely. It implies the idea has been set aside for later — or permanently.', '2026-03-18 19:58:52.376507+00', NULL, NULL, 'en', '{}', false, 'Like a book you''ll read someday.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('c602f188-2136-4494-8570-1ce85606fa82', 1243, 'gap_fill', 'B2', 'business_phrasal_verbs', 'We need to _____ the deadline — there''s no way we can finish by Friday.', 'push back', NULL, NULL, NULL, '["put back"]', 'To delay (a deadline, a meeting) — physically push it later.', 'Push back means to move a deadline to a later date. Compare: bring forward (move to an earlier date).', '2026-03-18 19:58:52.376507+00', NULL, NULL, 'en', '{}', false, 'Opposite of "bring forward".', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('c0f96dad-0d77-42b2-8770-acb1be7822eb', 1541, 'gap_fill', 'B1', 'business_vocabulary', 'Managing _____ flow carefully is essential — a profitable company can still fail if it runs out of cash.', 'cash', NULL, NULL, NULL, NULL, 'Money flowing in and out of a business — one word, often paired with "flow".', 'Cash flow refers to the movement of money in and out of a business. Positive cash flow means more money is coming in than going out. Even profitable businesses can collapse if cash flow is poorly managed.', '2026-03-26 08:02:12.742714+00', NULL, NULL, 'en', '{}', false, 'Notes and coins, basically.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('0633aa13-1cfe-48a3-bcb9-c4e5e8a9d123', 77, 'gap_fill', 'B2', 'linking_words', '___ (Although / Despite) it was cold, we went to the beach.', 'although', NULL, NULL, NULL, NULL, 'Although is followed by a clause', 'Although is followed by a subject and verb.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{"Linking word"}', false, 'Although + subject + verb. "Although it was cold..."', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('a743beb2-0710-4ed6-ac7a-60d015315cd9', 78, 'gap_fill', 'B2', 'linking_words', '___ (Although / Despite) the rain, we went to the beach.', 'despite', NULL, NULL, NULL, NULL, 'Despite is followed by a noun', 'Despite is followed by a noun or -ing form.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{"Linking word"}', false, 'Despite + noun (or -ing). "Despite the rain..." — no subject and verb.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('d836d08d-d827-4bdb-94e5-ec82c6a897cc', 79, 'gap_fill', 'B1', 'zero_conditional', 'If you ___ (_ _ _ _) ice, it melts.', 'heat', NULL, NULL, NULL, NULL, 'Zero conditional: If + present, present', 'Zero conditional is used for general truths and scientific facts.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{Conditional}', false, 'A general truth — present simple in both clauses.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('3bc5b128-b313-4b89-91a0-a862fa639245', 80, 'gap_fill', 'B1', 'zero_conditional', 'Water ___ (_ _ _ _ _) if you heat it to 100 degrees Celsius.', 'boils', NULL, NULL, NULL, NULL, 'Zero conditional uses present simple in both clauses', 'Zero conditional: If + present simple, present simple for general truths.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{Conditional}', false, 'Always true — like a scientific fact. Form: If + present, present.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('1bd98e99-b3cf-40fe-8ac1-4e6d70f6062e', 81, 'gap_fill', 'B2', 'mixed_conditional', 'If I ___ (be) better at maths, I would have studied engineering.', 'were', NULL, '["was"]', 'Were is more elegant and sounds more educated here. Native speakers judge each other for this use of was. ', NULL, 'Mixed conditional: present condition, past result', 'Mixed conditional combines elements of second and third conditional.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{Conditional}', false, 'Mixed condition: "If I were [now], I would have [past]" — present situation, past consequence.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('00385849-a740-46aa-8df9-be59237d395f', 82, 'gap_fill', 'B2', 'inversion', 'Never ___ (I / see) such a beautiful sunset.', 'have I seen', NULL, NULL, NULL, NULL, 'Inversion after negative adverbs', 'After negative adverbs like ''never'', we use question word order.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{Inversion}', false, 'Like a question: "Never have I seen..." instead of "I have never seen...".', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('29ba72dd-3875-4e8f-af82-d11027c05ff6', 83, 'gap_fill', 'B1', 'reflexive_pronouns', 'Be careful! Don''t hurt ___ (you).', 'yourself', NULL, NULL, NULL, NULL, 'Reflexive pronoun', 'Use reflexive pronouns when the subject and object are the same.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{Pronoun}', false, 'Same person doing and receiving the action: "you" → "yourself".', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('69512d4c-08f9-4943-b79e-8e46cbb68830', 84, 'gap_fill', 'B1', 'reflexive_pronouns', 'She taught ___ (her) to play the piano.', 'herself', NULL, NULL, NULL, NULL, 'Reflexive pronoun', 'Reflexive pronouns show that someone does something to/for themselves.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{Pronoun}', false, 'Same person doing and receiving the action: "her" → "herself".', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('d9268d95-1aff-4725-ae0a-8f41dba46d71', 85, 'gap_fill', 'B2', 'would_rather', 'I''d rather ___ (stay) at home tonight than go out.', 'stay', NULL, NULL, NULL, NULL, 'Would rather + infinitive without ''to''', 'Would rather is followed by the infinitive without ''to''.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{"Modal verb"}', false, 'Form: would rather + infinitive (no "to").', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('0176ccf6-f287-497a-8c57-0e03c2e1a342', 86, 'gap_fill', 'B2', 'would_rather', 'She''d rather you _____ 🚭 in the house.', 'didn''t smoke', NULL, NULL, NULL, NULL, 'Would rather + subject + past simple', 'After would rather + subject, use the past simple — even though the meaning is present. She''d rather you didn''t smoke = she wants you not to smoke.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{"Modal verb"}', false, 'When the subjects differ: would rather + someone + past simple.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('7c37832a-0f20-452b-8774-19c145d5bd69', 87, 'gap_fill', 'B1', 'both_neither_either', '___ (Both / Neither / Either) of my brothers live abroad.', 'both', NULL, NULL, NULL, NULL, 'Both means the two together.', 'Both means the two together, neither is the negative here. ', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{Quantifier}', false, 'Both = the two of them together.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('f03a3726-4999-468a-9225-4262a3bf7f96', 88, 'gap_fill', 'B1', 'both_neither_either', '___ (Both / Neither / Either) restaurant looks good. You choose.', 'either', NULL, NULL, NULL, NULL, 'Either means one or the other (it doesn''t matter which)', 'Either means one or the other, when it doesn''t matter which. Neither is the negative form. Good luck eating in those restaurants... ', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{Quantifier}', false, 'Either = one OR the other (you choose).', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('2f983c80-60e6-4717-beca-e916c030063a', 89, 'gap_fill', 'B2', 'causative_make_let', 'My parents don''t let me ___ (_ _ _ _) out late.', 'stay', NULL, NULL, NULL, NULL, 'Let + object + infinitive without ''to''', 'Let + object + infinitive (without ''to'') means to allow someone to do something.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{Causative}', false, 'Let + person + infinitive without "to". (Different from "make"!)', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('179c0a59-9c62-4268-b202-679add5c0cd9', 90, 'gap_fill', 'B2', 'causative_make_let', 'The teacher made us ___ (_ _) the exercise again.', 'do', NULL, NULL, NULL, NULL, 'Make + object + infinitive without ''to''', 'Make + object + infinitive (without ''to'') means to force someone to do something.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{Causative}', false, 'Make + person + infinitive without "to" — forced action.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('8804dafc-b158-4ec9-a422-53d040823e4c', 91, 'gap_fill', 'B1', 'must_vs_have_to', 'I ___ (must / have to) get up early tomorrow for my flight.', 'must', NULL, NULL, NULL, NULL, 'Both express obligation', 'Both must and have to express obligation, though must is more formal or personal. Native speakers often use both interchangeably.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{"Modal verb"}', false, '"Must" feels personal — internal pressure. (Compare: "have to" feels external.)', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('5393dc89-5bb1-4158-813e-65285e901e0b', 92, 'gap_fill', 'B1', 'must_vs_have_to', 'You ___ (must not / don''t have to) bring anything to the party. Everything is ready!', 'don''t have to', NULL, '["needn''t"]', NULL, NULL, 'No obligation', 'Don''t have to means there is no obligation (it''s not necessary).', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{"Modal verb"}', false, '"Don''t have to" = it''s not necessary. (Different from "must not"!)', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('7976039d-12b0-45c2-bbe9-2387ed9a0395', 93, 'gap_fill', 'B2', 'participle_clauses', '___ (Feel) tired, I decided to go to bed early.', 'feeling', NULL, '["As I felt", "Because I felt", "as I felt", "because I felt"]', NULL, NULL, 'Participle clause showing reason', 'Participle clauses can show the reason for an action.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{"Participle clause"}', false, '-ing form at the start of a sentence — it gives the reason.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('c4f98fe6-af0e-4032-a8b2-9e545a051814', 94, 'gap_fill', 'B2', 'participle_clauses', 'The man ___ (talk) to my boss is the new manager.', 'talking', NULL, NULL, NULL, NULL, 'Present participle as adjective', 'Present participles can be used like adjectives to describe nouns.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{"Participle clause"}', false, '-ing form describing the man (which one? the talking one).', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('59ce3fa3-2620-40fe-a017-564ca263c02c', 95, 'gap_fill', 'B1', 'as_like', 'He works ___ (as / like) a teacher.', 'as', NULL, NULL, NULL, NULL, 'As + profession/role', 'As is used before a profession or role.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{"Linking word"}', false, '"As" = in the role of (he IS a teacher).', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('18d09553-f76a-4119-b6fb-06fb985dd8ba', 1546, 'gap_fill', 'C1', 'business_vocabulary', 'The company used significant financial _____ — borrowing heavily to fund the acquisition and amplify potential returns.', 'leverage', NULL, NULL, NULL, NULL, 'Using borrowed money to magnify returns — a physics term used metaphorically.', 'Leverage (or gearing) refers to the use of borrowed capital to increase potential returns. High leverage amplifies both gains and losses and increases financial risk.', '2026-03-26 08:02:12.742714+00', NULL, NULL, 'en', '{}', false, 'What a long lever gives you, applied to finance.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('ac4363ee-bc91-4442-ac2f-9734b6d45089', 1547, 'gap_fill', 'C1', 'business_vocabulary', 'The fund manager used currency _____ to protect the portfolio against exchange rate fluctuations.', 'hedging', NULL, NULL, NULL, NULL, 'Protecting against a loss — also what you do in a garden.', 'Hedging is a risk management strategy that uses financial instruments to offset potential losses. A currency hedge protects against adverse movements in exchange rates.', '2026-03-26 08:02:12.742714+00', NULL, NULL, 'en', '{}', false, 'Don''t put all your eggs in one basket.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('48a22533-3241-4c31-8c57-9bc22e9c8e2f', 1379, 'gap_fill', 'B2', 'prepositions', 'She tends to arrive _____ time, regardless of the circumstances.', 'on', NULL, NULL, NULL, NULL, 'Phrase: "___ time" = punctually.', 'On time means punctual (at the right time). In time means early enough. Arrive on time is the standard collocation.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}', false, 'Different from "in time" (with time to spare).', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('97c7d2a7-6676-470b-aa19-e373593acf53', 1549, 'gap_fill', 'C1', 'business_vocabulary', 'Directors have a _____ duty to act in the best interests of shareholders rather than themselves.', 'fiduciary', NULL, NULL, NULL, NULL, 'A Latin-rooted legal adjective — the kind of duty a trustee has.', 'A fiduciary duty is a legal obligation to act in another party''s best interest. Directors owe this duty to shareholders. Breaching a fiduciary duty can result in personal legal liability.', '2026-03-26 08:02:12.742714+00', NULL, NULL, 'en', '{}', false, 'Shares a root with "fidelity" and "faith".', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('4ad37a07-19a2-49cb-b64d-d86d11772f9f', 1550, 'gap_fill', 'C1', 'business_vocabulary', 'The company''s strong brand and loyal customer base gave it a significant _____ moat — protection against competitive threats.', 'economic', NULL, NULL, NULL, NULL, 'Warren Buffett popularised this term — the adjective that describes the "moat" around a successful business.', 'An economic moat is a competitive advantage that protects a company''s market position and profitability over the long term. The term was popularised by investor Warren Buffett.', '2026-03-26 08:02:12.742714+00', NULL, NULL, 'en', '{}', false, NULL, 'adjective');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('a291d90b-888e-46bf-90e1-43ea7c1c0f9a', 1551, 'gap_fill', 'C2', 'business_vocabulary', 'The finance team worked overnight to prepare the _____ schedule, showing how the loan would be repaid over ten years.', 'amortisation', NULL, NULL, NULL, NULL, 'Paying off a debt gradually — shares a Latin root with "mortgage".', 'Amortisation is the process of gradually writing off the cost of an intangible asset or repaying a loan over time through regular payments. Each payment covers both interest and principal.', '2026-03-26 08:02:12.742714+00', NULL, NULL, 'en', '{}', false, 'The "A" in EBITDA.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('5414b3de-45e5-4d46-88c6-ffd5d96f9350', 1552, 'gap_fill', 'C2', 'business_vocabulary', 'The investigation revealed that the two firms had operated as a _____, secretly coordinating prices to eliminate competition.', 'cartel', NULL, NULL, NULL, NULL, 'A group of producers colluding — famously associated with OPEC in oil.', 'A cartel is a formal or informal agreement between competing businesses to fix prices, limit production, or divide markets. Cartels are illegal in most jurisdictions and subject to heavy fines.', '2026-03-26 08:02:12.742714+00', NULL, NULL, 'en', '{}', false, 'Drug lords and oil producers both have these.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('2f929203-18b1-414a-9781-14589ba6da23', 1553, 'gap_fill', 'C2', 'business_vocabulary', 'The digital revolution represented a genuine _____ shift for the publishing industry — the old business model became obsolete almost overnight.', 'paradigm', NULL, NULL, NULL, NULL, 'A complete change in the underlying model — from Thomas Kuhn''s philosophy of science.', 'A paradigm shift is a fundamental change in the underlying assumptions of a field or industry. The term comes from philosopher Thomas Kuhn. In business it describes a transformation so radical that the old rules no longer apply.', '2026-03-26 08:02:12.742714+00', NULL, NULL, 'en', '{}', false, 'Often misused, but here meaning a fundamental worldview or framework.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('20d47d86-ef60-478e-80e0-e5cddbe18327', 1554, 'gap_fill', 'C2', 'business_vocabulary', 'The merger was expected to generate significant _____ — the combined business would be worth more than the two companies separately.', 'synergies', NULL, NULL, NULL, NULL, '1 + 1 = 3. The combined effect is greater than the sum of parts.', 'Synergies refer to the additional value created when two companies combine — typically through cost savings, revenue growth, or operational efficiencies. Synergies are often used to justify mergers and acquisitions.', '2026-03-26 08:02:12.742714+00', NULL, NULL, 'en', '{}', false, 'Buzzword corporate-speak for "we''ll save money by combining".', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('86b4b261-c6df-43d3-9d0e-1efd940b59bc', 1245, 'gap_fill', 'C1', 'business_phrasal_verbs', 'The acquisition _____ at the last minute due to regulatory concerns.', 'fell through', NULL, NULL, NULL, NULL, 'To fail unexpectedly — common in business contexts.', 'Fall through means a deal or plan fails to happen. It is particularly common in business contexts involving mergers and acquisitions.', '2026-03-18 19:58:52.376507+00', NULL, NULL, 'en', '{}', false, 'Like falling through a trapdoor.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('bc606e85-3a26-415a-ad1a-e3e5e7d4104d', 1246, 'gap_fill', 'C2', 'business_phrasal_verbs', 'The consultants were brought in to _____ the inefficiencies in the supply chain.', 'iron out', NULL, NULL, NULL, NULL, 'To resolve (problems, wrinkles in a plan).', 'Iron out means to resolve problems or difficulties, especially small but persistent ones. Compare: smooth out, work out.', '2026-03-18 19:58:52.376507+00', NULL, NULL, 'en', '{}', false, 'Like ironing out wrinkles in cloth.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('8a10cda3-b0a5-413a-9fe0-934b52af0c34', 1247, 'gap_fill', 'C1', 'business_phrasal_verbs', 'The board voted to _____ the proposal, citing insufficient evidence of commercial viability.', 'throw out', NULL, NULL, NULL, NULL, 'To reject (a proposal, a case) — formal sense.', 'Throw out means to reject a proposal or idea formally. Compare: dismiss, turn down, vote down.', '2026-03-18 19:58:52.376507+00', NULL, NULL, 'en', '{}', false, 'Like throwing rubbish in the bin.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('a43725a9-f942-4b3b-9711-3a7aada0557b', 1248, 'gap_fill', 'C2', 'business_phrasal_verbs', 'After the restructuring, several middle management positions were _____ entirely.', 'phased out', NULL, NULL, NULL, NULL, 'To gradually discontinue — over phases or stages.', 'Phase out means to gradually eliminate something over time. Compare: wind down, discontinue.', '2026-03-18 19:58:52.376507+00', NULL, NULL, 'en', '{}', false, 'Opposite of "phased in".', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('96d61db5-a4b5-49b2-90f2-6a90eafda183', 1249, 'gap_fill', 'C1', 'business_phrasal_verbs', 'The two rival firms decided to _____ and form a joint venture.', 'team up', NULL, NULL, NULL, NULL, 'To form a team — work together with another party.', 'Team up means to join together with another person or organisation for a shared purpose. Compare: partner with, collaborate with.', '2026-03-18 19:58:52.376507+00', NULL, NULL, 'en', '{}', false, 'Often "___ up with X to do Y".', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('2019871e-d936-447f-a5b3-4ace5a18058f', 96, 'gap_fill', 'B1', 'as_like', 'She sings ___ (as / like) an angel.', 'like', NULL, NULL, NULL, NULL, 'Like + noun for comparisons', 'Like is used for comparisons and means similar to.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{"Linking word"}', false, '"Like" = similar to (she''s not actually an angel).', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('f608db54-310f-4b4b-b519-1604db620150', 1253, 'gap_fill', 'C1', 'business_phrasal_verbs', 'The new initiative was _____ as a pilot scheme in three regions before a national rollout.', 'rolled out', NULL, NULL, NULL, NULL, 'To launch (gradually, in stages).', 'Roll out means to launch or introduce a product, scheme, or initiative in stages. The noun rollout is common in business contexts.', '2026-03-18 19:58:52.376507+00', NULL, NULL, 'en', '{}', false, 'Often "___ a pilot scheme" before national launch.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('c3157909-b8be-46d3-8d25-5b39462a217c', 1254, 'gap_fill', 'C2', 'business_phrasal_verbs', 'The board is _____ its options before committing to a course of action.', 'weighing up', NULL, NULL, NULL, NULL, 'To consider carefully — weigh the pros and cons.', 'Weigh up means to carefully consider the advantages and disadvantages of different options before deciding. Compare: evaluate, assess, deliberate over.', '2026-03-18 19:58:52.376507+00', NULL, NULL, 'en', '{}', false, 'Like a literal balance.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('ee7c582c-a877-4735-b845-c46111764226', 1839, 'gap_fill', 'A2', 'spanish', 'Cuando llegamos al restaurante, todas las _______ estaban ocupadas y tuvimos que esperar.', 'mesas', NULL, NULL, NULL, NULL, NULL, '"Mesa" (table) es el sustantivo femenino que se usa para las mesas de un restaurante.', '2026-04-06 16:43:51.906934+00', NULL, NULL, 'es', '{Spanish}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('ec89affb-1769-49aa-b13c-a5c569bd2917', 1377, 'gap_fill', 'B2', 'prepositions', 'The new policy will have a significant impact _____ daily routines.', 'on', NULL, NULL, NULL, NULL, '"Impact ___ daily routines" — common after "impact".', 'The collocation is have an impact on. Compare: have an effect on, have an influence on.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}', false, 'Same as "an effect ___ X".', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('7b7a2a27-7afa-4bbf-8b63-78b415af5d0f', 1378, 'gap_fill', 'B1', 'prepositions', 'I''m not used _____ getting up before six o''clock.', 'to', NULL, NULL, NULL, NULL, 'Always: "be used ___ + -ing" = accustomed.', 'Be used to is a fixed expression meaning to be accustomed to. The to here is a preposition followed by a gerund.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}', false, 'Don''t confuse with "used to" (past habit).', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('96baeb73-5791-4877-ae02-e0a5599b667d', 1392, 'gap_fill', 'C1', 'prepositions', 'Research suggests that regular exercise is conducive _____ improved sleep.', 'to', NULL, NULL, NULL, NULL, '"Conducive ___ improved sleep" — leads to good outcome.', 'Conducive to is the correct collocation, meaning tending to produce a particular result. Compare: beneficial to, detrimental to.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}', false, 'From Latin "ducere" (to lead) — leading to.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('de07cad2-39db-4ddc-b52e-6f228b37d2ec', 1393, 'gap_fill', 'C2', 'prepositions', 'She is consistent _____ applying the same standards to herself as to others.', 'in', NULL, NULL, NULL, NULL, '"Consistent ___ doing X" = consistently does X.', 'Consistent in (doing something) means doing something regularly and without variation. Compare: consistent with (meaning in agreement with).', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}', false, 'Same as in "thorough ___" or "faithful ___".', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('129c3e1d-a854-42f1-b222-0355b60f2dcf', 1394, 'gap_fill', 'C1', 'prepositions', 'Resilience is a quality that can be cultivated _____ deliberate practice.', 'through', NULL, NULL, NULL, NULL, '"Cultivated ___ practice" — developed by means of.', 'Through means by means of when describing a method or process. Compare: through hard work, through repetition, through experience.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}', false, 'Same as "achieved ___" or "developed ___".', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('e4c85f58-ec0e-491d-9e55-cc703f825144', 1395, 'gap_fill', 'C2', 'prepositions', 'Her output is by no means _____ proportion to the effort she puts in.', 'in', NULL, NULL, NULL, NULL, 'Phrase: "___ proportion to".', 'In proportion to is the correct prepositional phrase meaning corresponding to or relative to. By no means in proportion to means the result does not match the effort.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}', false, 'Always paired with "to".', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('39f6fde8-5740-4763-ba5d-09c3a52e518d', 1406, 'gap_fill', 'B1', 'vocabulary', 'She has a very _____ approach to her work — she does the same tasks in the same order every day.', 'methodical', NULL, NULL, NULL, NULL, 'Following a precise system — same order every time.', 'Methodical means done in a careful, systematic way. It describes someone who follows a clear, consistent method.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}', false, 'Sharing a root with "method".', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('f81ba816-2d4c-427b-93d5-8a75e60c8129', 1407, 'gap_fill', 'B2', 'vocabulary', 'I find it difficult to _____ between rest and productivity — I feel guilty when I''m not doing something.', 'strike a balance', NULL, NULL, NULL, NULL, 'Idiom: ___ a balance = find equilibrium.', 'Strike a balance means to find a satisfactory middle point between two things. It is a common collocation.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}', false, 'Common idiom for compromise between two things.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('10e3601f-2776-4886-b4d0-ee063df3d5cc', 1408, 'gap_fill', 'B1', 'vocabulary', 'He tends to _____ important tasks until the last minute, even though he knows it causes stress.', 'procrastinate', NULL, NULL, NULL, NULL, 'To delay important tasks until the last minute.', 'Procrastinate means to delay doing something, especially something important. The noun form is procrastination.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}', false, 'Latin: pro- (forward) + cras (tomorrow) — for tomorrow.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('c1e7fe06-6270-4abe-b56a-02f7252dc7f7', 1409, 'gap_fill', 'B2', 'vocabulary', 'After years of working from home, she has found it difficult to maintain clear _____ between work and personal life.', 'boundaries', NULL, NULL, NULL, NULL, 'The limits between two domains (work and personal).', 'Boundaries in this context means the limits that separate two areas of life. Maintain boundaries is the standard collocation.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}', false, 'Like borders between countries.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('31a55eca-bfa3-4827-9319-88ca340faade', 1411, 'gap_fill', 'B2', 'vocabulary', 'Regular exercise is known to _____ the effects of stress on the body and mind.', 'mitigate', NULL, NULL, NULL, NULL, 'To reduce the severity of something negative.', 'Mitigate means to reduce the severity or impact of something. It is a formal verb used in academic and professional English.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}', false, 'From Latin "mitigare" — to soften.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('07ace117-8908-402d-b9f6-8e5e3d93cfff', 1412, 'gap_fill', 'B1', 'vocabulary', 'It''s important to _____ realistic goals when trying to build a new habit — starting too ambitiously often leads to failure.', 'set', NULL, NULL, NULL, NULL, 'Common verb pairing — ___ goals, ___ targets.', 'Set goals / set targets is the standard collocation. Set means to establish or fix something.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}', false, 'Same verb in "___ a record" or "___ an example".', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('642c3bea-3292-4ec8-88e7-952326b1b355', 1417, 'gap_fill', 'C2', 'vocabulary', 'His _____ in completing tasks — always finishing what he starts — is one of his greatest professional assets.', 'tenacity', NULL, NULL, NULL, NULL, 'Determined persistence — refusing to let go.', 'Tenacity means persistent determination. It implies the refusal to give up despite difficulties.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}', false, 'Sharing a root with "tenacious" — holding on tightly.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('1f3e6af3-5dce-4880-b3ef-ff4e35606f08', 1418, 'gap_fill', 'C1', 'vocabulary', 'She approached the challenge with remarkable _____, never showing signs of panic or frustration.', 'equanimity', NULL, NULL, NULL, NULL, 'Calm balance under pressure — neither up nor down.', 'Equanimity means mental calmness, especially in difficult situations. It implies composure and balance.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}', false, 'Latin: equa (equal) + animus (mind) — even mind.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('75d2e0e5-9aa5-4588-a7ae-907df58e67cf', 1419, 'gap_fill', 'C2', 'vocabulary', 'The _____ of good habits is not about willpower — it is about designing an environment that makes good choices easier.', 'cultivation', NULL, NULL, NULL, NULL, 'The development of habits — like cultivating a garden.', 'Cultivation means the development or improvement of something over time. It is used metaphorically here, as in cultivating habits.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}', false, 'Latin "cultivare" — to till.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('81543106-7bc2-4b10-b36c-7e7a4692d3f4', 1420, 'gap_fill', 'C1', 'vocabulary', 'Many high achievers are _____ about protecting their morning routine from interruptions.', 'fastidious', NULL, NULL, NULL, NULL, 'Meticulously protective — very particular.', 'Fastidious means very attentive to detail and careful about maintaining standards. It can also imply being difficult to please.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}', false, 'From Latin "fastidium" — disgust at carelessness.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('0df28f30-d24d-40cd-a146-bb6e9b701c10', 1423, 'gap_fill', 'C2', 'vocabulary', 'The _____ nature of his schedule — never the same two days in a row — made it difficult to establish lasting habits.', 'mercurial', NULL, NULL, NULL, NULL, 'Changeable, unpredictable — like the metal mercury.', 'Mercurial means subject to sudden unpredictable changes. It derives from Mercury, the Roman god of speed, associated with rapid movement.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}', false, 'Named after the Roman god Mercury — quick and changeable.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('59f2ecb0-5ad3-4c70-adb9-425c57574213', 1425, 'gap_fill', 'C2', 'vocabulary', 'There is a growing body of evidence to suggest that micro-habits — tiny _____ changes — are more effective than dramatic lifestyle overhauls.', 'incremental', NULL, NULL, NULL, NULL, 'Small, gradual — by tiny additions.', 'Incremental means increasing or developing gradually in small steps. Compare: gradual, progressive, cumulative.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}', false, 'Sharing a root with "increment".', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('338b08ab-b652-43aa-8c64-bda810d0aa9b', 1461, 'gap_fill', 'B1', 'phrasal_verbs', 'She worked hard to _____ for the time she had missed during her illness.', 'make up', NULL, NULL, NULL, NULL, 'To compensate for lost time or missing something.', 'Make up for means to compensate for something — to do something that reduces the negative effect of an earlier action or situation.', '2026-03-18 20:30:31.624632+00', NULL, NULL, 'en', '{}', false, 'Common collocation: "make up ___ lost time".', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('9279ffa2-1f78-4361-be52-581c13916e7e', 1462, 'gap_fill', 'B1', 'phrasal_verbs', 'Previously he _____ from expressing his opinions in meetings due to his shyness.', 'held back', NULL, NULL, NULL, NULL, 'To restrain — stop yourself from doing/saying.', 'Hold back can mean to prevent someone from progressing or expressing themselves. It can also mean to deliberately withhold something.', '2026-03-18 20:30:31.624632+00', NULL, NULL, 'en', '{}', false, 'Common with "from + -ing".', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('e50fc8db-a86c-4ca3-bb3c-69bdfd52866b', 1463, 'gap_fill', 'B1', 'phrasal_verbs', 'I spent all weekend trying to _____ with the work I missed while I was ill.', 'catch up', NULL, NULL, NULL, NULL, 'To get current — close the gap with where you should be.', 'Catch up (with) means to reach the same level or position as someone else, or to deal with work that has accumulated.', '2026-03-18 20:30:31.624632+00', NULL, NULL, 'en', '{}', false, 'Often "catch up ___ work" — same prep as "behind".', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('65f4c201-6d35-42af-946a-40ed98f933ad', 1464, 'gap_fill', 'B1', 'phrasal_verbs', 'His confidence has really _____ since he started the new job.', 'built up', NULL, NULL, NULL, NULL, 'To increase gradually — like building a wall.', 'Build up means to gradually increase or develop. It can describe confidence, pressure, tension, or a reputation.', '2026-03-18 20:30:31.624632+00', NULL, NULL, 'en', '{}', false, 'Common with confidence, savings, reputation.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('70d47335-7465-40f4-8f49-928b3642a086', 1465, 'gap_fill', 'B1', 'phrasal_verbs', 'I don''t think it will work — we need to _____ this plan more carefully.', 'think through', NULL, NULL, NULL, NULL, 'To consider carefully, end to end.', 'Think through means to consider all aspects of something carefully before deciding. Compare: think over, work out, plan out.', '2026-03-18 20:30:31.624632+00', NULL, NULL, 'en', '{}', false, 'Like walking through every step.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('e33e5886-b158-422f-a6cc-edc4bc6c9d7b', 1472, 'gap_fill', 'B2', 'phrasal_verbs', 'The company is slowly _____ its older product lines in favour of digital services.', 'phasing out', NULL, NULL, NULL, NULL, 'Gradually discontinuing — over phases.', 'Phase out means to gradually discontinue or eliminate something over a period of time. Compare: wind down, discontinue, do away with.', '2026-03-18 20:30:31.624632+00', NULL, NULL, 'en', '{}', false, 'Form: be + verb-ing. Opposite of "phasing in".', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('fe68da6f-8dfc-41f3-8411-9ac2244406a4', 1474, 'gap_fill', 'B2', 'phrasal_verbs', 'The situation _____ exactly as she had predicted — nobody listened and the project failed.', 'played out', NULL, NULL, NULL, NULL, 'To unfold over time — events happening.', 'Play out means to develop or unfold, especially in a way that was anticipated. It describes how a situation or event progresses over time.', '2026-03-18 20:30:31.624632+00', NULL, NULL, 'en', '{}', false, 'Like watching a play in a theatre.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('4a474b40-9654-4b4c-a433-9b1dc7ad05f8', 1475, 'gap_fill', 'B2', 'phrasal_verbs', 'The new manager asked the team to _____ a detailed proposal by Friday.', 'draw up', NULL, NULL, NULL, NULL, 'To prepare a formal document.', 'Draw up means to prepare a formal document, plan, or list. Compare: put together, draft, produce.', '2026-03-18 20:30:31.624632+00', NULL, NULL, 'en', '{}', false, 'Common with "contract", "plan", "agreement".', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('193bebf6-cb22-4d20-93a0-b9d317bb5aa8', 1476, 'gap_fill', 'C1', 'phrasal_verbs', 'The committee spent two hours trying to _____ the list of candidates to a final shortlist of three.', 'narrow down', NULL, NULL, NULL, NULL, 'To reduce the number of options.', 'Narrow down means to reduce a large number of options or possibilities to a smaller, more manageable set.', '2026-03-18 20:30:31.624632+00', NULL, NULL, 'en', '{}', false, 'Like narrowing a wide funnel to a single choice.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('30ddc3e9-9836-4140-a5b2-7486cbf0fa51', 1477, 'gap_fill', 'C1', 'phrasal_verbs', 'Despite enormous pressure to resign, the minister _____ and refused to leave office.', 'held out', NULL, NULL, NULL, NULL, 'To resist pressure — refused to give in.', 'Hold out means to resist pressure or continue to endure a difficult situation without giving in. Compare: stand firm, hang on.', '2026-03-18 20:30:31.624632+00', NULL, NULL, 'en', '{}', false, 'Like holding out against a siege.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('9d8c39f6-827a-4d3b-9920-5384b07e14f7', 1478, 'gap_fill', 'C1', 'phrasal_verbs', 'The company has been looking to _____ into new markets in South-East Asia.', 'branch out', NULL, NULL, NULL, NULL, 'To expand into new areas — like a tree''s branches.', 'Branch out means to expand into new areas of activity, especially in business. Compare: diversify, move into, expand.', '2026-03-18 20:30:31.624632+00', NULL, NULL, 'en', '{}', false, 'Often paired with "new markets", "new fields".', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('5098bdf7-750b-4f77-8443-e273a28a24a1', 1481, 'gap_fill', 'C2', 'phrasal_verbs', 'The report accused the government of trying to _____ the deeper structural problems with a series of short-term fixes.', 'paper over', NULL, NULL, NULL, NULL, 'To hide a problem superficially — like papering over cracks.', 'Paper over means to conceal or disguise a problem without actually solving it. Compare: gloss over, brush under the carpet.', '2026-03-18 20:30:31.624632+00', NULL, NULL, 'en', '{}', false, 'Idiom: "paper over the cracks".', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('27df9556-4ca5-44c7-9ae3-1c764cf878ef', 1482, 'gap_fill', 'C2', 'phrasal_verbs', 'The chairman tried to _____ the embarrassing findings in his annual report, but journalists noticed immediately.', 'gloss over', NULL, NULL, NULL, NULL, 'To skim past something embarrassing without addressing it.', 'Gloss over means to treat something briefly or superficially in order to avoid drawing attention to it. Compare: paper over, brush aside.', '2026-03-18 20:30:31.624632+00', NULL, NULL, 'en', '{}', false, 'Like glossing a surface — smoothing it over.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('e1899ff4-8ce7-4a32-9314-7c85bf5c9f53', 1484, 'gap_fill', 'C2', 'phrasal_verbs', 'She has a remarkable ability to _____ the most important information from lengthy and complex reports.', 'draw out', NULL, NULL, NULL, NULL, 'To extract — pull useful information from something.', 'Draw out means to extract the most essential or important elements from a large body of material. Compare: extract, distil (from), boil down to.', '2026-03-18 20:30:31.624632+00', NULL, NULL, 'en', '{}', false, 'Like drawing water from a well — but for ideas.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('06155271-238f-4c53-95fb-e492944318d4', 97, 'gap_fill', 'B2', 'emphatic_do', 'I ___ (_ _) understand what you mean, but I disagree. Completely.', 'do', NULL, NULL, NULL, NULL, 'Do for emphasis', 'Do/does/did can be used for emphasis in affirmative sentences.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{"Cleft sentence"}', false, '"I do understand" — adding force to what follows.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('a1b2c3d4-0916-0916-0916-000000000916', 916, 'matching', 'B1', 'vocabulary', 'Match each phrasal verb to its meaning.', 'match_all_pairs', '[{"left": {"type": "text", "content": "put off"}, "right": {"type": "text", "content": "to postpone"}}, {"left": {"type": "text", "content": "take on"}, "right": {"type": "text", "content": "to accept responsibility for"}}, {"left": {"type": "text", "content": "bring up"}, "right": {"type": "text", "content": "to mention a topic"}}, {"left": {"type": "text", "content": "look into"}, "right": {"type": "text", "content": "to investigate"}}, {"left": {"type": "text", "content": "carry out"}, "right": {"type": "text", "content": "to perform or complete a task"}}]', NULL, NULL, NULL, NULL, 'put off = postpone (delay to a later time) · take on = accept responsibility for · bring up = mention a topic in conversation · look into = investigate · carry out = perform or complete a task. These are all common phrasal verbs in professional and everyday English.', '2026-03-03 19:46:49.927263+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('a1b2c3d4-0917-0917-0917-000000000917', 917, 'matching', 'B1', 'vocabulary', 'Match each word to its definition.', 'match_all_pairs', '[{"left": {"type": "text", "content": "persuade"}, "right": {"type": "text", "content": "to convince someone to do something"}}, {"left": {"type": "text", "content": "negotiate"}, "right": {"type": "text", "content": "to discuss in order to reach an agreement"}}, {"left": {"type": "text", "content": "recommend"}, "right": {"type": "text", "content": "to suggest something as a good choice"}}, {"left": {"type": "text", "content": "complain"}, "right": {"type": "text", "content": "to express dissatisfaction"}}, {"left": {"type": "text", "content": "confirm"}, "right": {"type": "text", "content": "to state that something is definitely true or agreed"}}]', NULL, NULL, NULL, NULL, 'persuade = convince someone to do something · negotiate = discuss to reach an agreement · recommend = suggest as a good choice · complain = express dissatisfaction · confirm = state that something is definitely true or agreed. These verbs often appear in business and everyday communication contexts.', '2026-03-03 19:46:49.927263+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('a1b2c3d4-0918-0918-0918-000000000918', 918, 'matching', 'B2', 'vocabulary', 'Match each adjective to its meaning.', 'match_all_pairs', '[{"left": {"type": "text", "content": "reluctant"}, "right": {"type": "text", "content": "unwilling to do something"}}, {"left": {"type": "text", "content": "assertive"}, "right": {"type": "text", "content": "confident in stating your views"}}, {"left": {"type": "text", "content": "impartial"}, "right": {"type": "text", "content": "not favouring one side over another"}}, {"left": {"type": "text", "content": "tentative"}, "right": {"type": "text", "content": "not certain or definite"}}, {"left": {"type": "text", "content": "forthcoming"}, "right": {"type": "text", "content": "willing to give information"}}]', NULL, NULL, NULL, NULL, 'reluctant = unwilling (often followed by "to + infinitive": reluctant to speak) · assertive = confident in stating your views, not aggressive · impartial = neutral, not favouring one side · tentative = uncertain or cautious (a tentative suggestion) · forthcoming = willing to give information. These adjectives are common in professional and academic English.', '2026-03-03 19:46:49.927263+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('a1b2c3d4-0920-0920-0920-000000000920', 920, 'matching', 'B2', 'vocabulary', 'Match each idiom to its meaning.', 'match_all_pairs', '[{"left": {"type": "text", "content": "hit the nail on the head"}, "right": {"type": "text", "content": "to describe something exactly right"}}, {"left": {"type": "text", "content": "sit on the fence"}, "right": {"type": "text", "content": "to avoid taking sides"}}, {"left": {"type": "text", "content": "get the ball rolling"}, "right": {"type": "text", "content": "to start a process"}}, {"left": {"type": "text", "content": "bite the bullet"}, "right": {"type": "text", "content": "to endure a difficult situation"}}, {"left": {"type": "text", "content": "burn bridges"}, "right": {"type": "text", "content": "to permanently damage a relationship"}}]', NULL, NULL, NULL, NULL, 'hit the nail on the head = describe something exactly right · sit on the fence = avoid committing to a position · get the ball rolling = start a process or activity · bite the bullet = accept something difficult and deal with it · burn bridges = permanently damage a relationship so you cannot return. All five are common in meetings, negotiations, and everyday speech.', '2026-03-03 19:46:49.927263+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('a1b2c3d4-0928-0928-0928-000000000928', 928, 'matching', 'A2', 'spanish', 'Match each sentence to the correct use of ser or estar.', 'match_all_pairs', '[{"left": {"type": "text", "content": "Soy profesora."}, "right": {"type": "text", "content": "ser — permanent identity / profession"}}, {"left": {"type": "text", "content": "Estoy cansada."}, "right": {"type": "text", "content": "estar — temporary state"}}, {"left": {"type": "text", "content": "La reunión es a las diez."}, "right": {"type": "text", "content": "ser — time / scheduled events"}}, {"left": {"type": "text", "content": "El café está frío."}, "right": {"type": "text", "content": "estar — current condition"}}, {"left": {"type": "text", "content": "Somos de Madrid."}, "right": {"type": "text", "content": "ser — origin"}}]', NULL, NULL, NULL, NULL, 'Ser is used for permanent or defining characteristics: profession (soy profesora), origin (somos de Madrid), and scheduled events (la reunión es a las diez). Estar is used for temporary states: how you feel (estoy cansada) and current conditions (el café está frío). This ser/estar distinction is one of the most important grammar points in Spanish.', '2026-03-03 19:54:35.474351+00', NULL, NULL, 'es', '{Vocabulario}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('5bcf6f2c-0e8d-48ff-b8dd-5984a5b3de9d', 1336, 'matching', 'B1', 'vocabulary', 'Match each phrasal verb to its meaning.', '["match_all_pairs"]', '[{"left": {"type": "text", "label": "", "content": "cut down on"}, "right": {"type": "text", "label": "", "content": "reduce the amount of something"}}, {"left": {"type": "text", "label": "", "content": "give up"}, "right": {"type": "text", "label": "", "content": "stop doing something permanently"}}, {"left": {"type": "text", "label": "", "content": "keep up with"}, "right": {"type": "text", "label": "", "content": "maintain the same pace or level as someone"}}, {"left": {"type": "text", "label": "", "content": "wind down"}, "right": {"type": "text", "label": "", "content": "relax gradually after a period of activity"}}]', NULL, NULL, NULL, NULL, 'cut down on = reduce the amount of something (cut down on sugar) · give up = stop doing something permanently (give up smoking) · keep up with = maintain the same pace as someone or something · wind down = relax gradually after effort or stress. These four are especially common when talking about health, habits, and routines.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('b22b2488-cb2d-482f-99c0-6af11f27e0f4', 98, 'gap_fill', 'B2', 'cleft_sentences', '___ (_ _ _ _) I need is a good night''s sleep.', 'what', NULL, NULL, NULL, NULL, 'What-cleft sentence for emphasis', 'What-cleft sentences (What + clause + is/was) add emphasis.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{"Cleft sentence"}', false, '"What I need..." — a way to put the focus at the end.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('98f3dd68-9c00-4a47-8cf0-e3cbfd382d14', 1339, 'matching', 'B2', 'vocabulary', 'Match each verb to the noun it collocates with.', '["match_all_pairs"]', '[{"left": {"type": "text", "label": "", "content": "make"}, "right": {"type": "text", "label": "", "content": "progress"}}, {"left": {"type": "text", "label": "", "content": "reach"}, "right": {"type": "text", "label": "", "content": "a decision"}}, {"left": {"type": "text", "label": "", "content": "take"}, "right": {"type": "text", "label": "", "content": "advantage of"}}, {"left": {"type": "text", "label": "", "content": "strike"}, "right": {"type": "text", "label": "", "content": "a balance"}}]', NULL, NULL, NULL, NULL, 'make progress (not "do progress") · reach a decision (also "make a decision" — both work) · take advantage of an opportunity · strike a balance between two things. Collocations like these must be learned as fixed pairs — the wrong verb is a very common mistake even at advanced level.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('706b7687-53cb-4f67-a3be-01e6c6f3e772', 1340, 'matching', 'B1', 'vocabulary', 'Match each adjective to its synonym.', '["match_all_pairs"]', '[{"left": {"type": "text", "label": "", "content": "exhausted"}, "right": {"type": "text", "label": "", "content": "worn out"}}, {"left": {"type": "text", "label": "", "content": "anxious"}, "right": {"type": "text", "label": "", "content": "on edge"}}, {"left": {"type": "text", "label": "", "content": "determined"}, "right": {"type": "text", "label": "", "content": "resolute"}}, {"left": {"type": "text", "label": "", "content": "consistent"}, "right": {"type": "text", "label": "", "content": "steady"}}]', NULL, NULL, NULL, NULL, 'exhausted = worn out (both mean extremely tired) · anxious = on edge (nervous and tense) · determined = resolute (firmly decided and unwilling to give up) · consistent = steady (reliable and unchanging over time). Learning synonyms helps you vary your language and understand different registers — "resolute" is more formal than "determined".', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('bbd3d4f7-477c-4983-a2cf-c4fa1a705444', 1343, 'matching', 'B2', 'vocabulary', 'Match each word to its definition.', '["match_all_pairs"]', '[{"left": {"type": "text", "label": "", "content": "procrastinate"}, "right": {"type": "text", "label": "", "content": "to delay doing something you should do"}}, {"left": {"type": "text", "label": "", "content": "prioritise"}, "right": {"type": "text", "label": "", "content": "to decide what is most important and deal with it first"}}, {"left": {"type": "text", "label": "", "content": "delegate"}, "right": {"type": "text", "label": "", "content": "to give a task to someone else to do"}}, {"left": {"type": "text", "label": "", "content": "multitask"}, "right": {"type": "text", "label": "", "content": "to do several things at the same time"}}]', NULL, NULL, NULL, NULL, 'procrastinate = delay doing something you know you should do, often by doing less important things first · prioritise = decide what matters most and deal with it first · delegate = give a task to someone else to complete · multitask = do several things simultaneously. These four verbs are essential vocabulary for talking about work, study, and time management.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('6fde1c25-f723-44ff-9f3e-8ca4dcb2d3ce', 1345, 'matching', 'B2', 'vocabulary', 'Match each idiom to its meaning.', '["match_all_pairs"]', '[{"left": {"type": "text", "label": "", "content": "burn the candle at both ends"}, "right": {"type": "text", "label": "", "content": "exhaust yourself by doing too much"}}, {"left": {"type": "text", "label": "", "content": "be in a rut"}, "right": {"type": "text", "label": "", "content": "be stuck in a dull, unchanging routine"}}, {"left": {"type": "text", "label": "", "content": "hit the ground running"}, "right": {"type": "text", "label": "", "content": "start something energetically and with no delay"}}, {"left": {"type": "text", "label": "", "content": "turn over a new leaf"}, "right": {"type": "text", "label": "", "content": "change your behaviour and start fresh"}}]', NULL, NULL, NULL, NULL, 'burn the candle at both ends = exhaust yourself by working or socialising too hard and sleeping too little · be in a rut = feel stuck in a dull, unchanging routine with no progress · hit the ground running = start something immediately and energetically, without needing time to prepare · turn over a new leaf = decide to change your behaviour and make a fresh start. All four relate to habits and lifestyle — very useful for discussing wellbeing.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('2564c26c-05a7-4bfd-8242-ad1f97a50f25', 679, 'odd_one_out', 'B2', 'collocations', 'Which does NOT collocate with "take"?', 'a coffee', '["a break", "a coffee", "advantage", "a chance"]', NULL, NULL, NULL, NULL, 'We do not usually say "take a coffee", or any other drink, unless the meaning is to transposrt the drink, rather than to actually drink it.', '2026-02-20 19:09:17.848852+00', NULL, NULL, 'en', '{Collocation}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('e53bb309-370c-4b9c-868c-ea1990c28548', 410, 'gap_fill', 'C1', 'mixed_conditionals', 'They ___ (still / live) in London if they hadn''t found jobs abroad.', 'would still be living', NULL, '["''d still be living", "''d still live"]', NULL, NULL, 'Past condition → ongoing present consequence (still living).', 'Mixed conditional: would + be living (continuous) for an ongoing present result.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{Conditional}', false, 'Form: would (still) be + verb-ing.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('192952b7-114c-4170-ae48-e315c428a76f', 411, 'gap_fill', 'C2', 'mixed_conditionals', 'Should you ___ (require) any further assistance, do not hesitate to contact us.', 'require', NULL, NULL, NULL, NULL, 'Inversion conditional: "Should + subject + base verb" replaces "If you should...".', 'Formal inversion: Should you require = If you should require. Very formal correspondence.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{Conditional}', false, 'Formal style. Same as "If you require any further assistance...".', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('07d2d978-a528-4cac-8e9b-f05cca3f3419', 412, 'gap_fill', 'C1', 'mixed_conditionals', 'If it ___ (not be) for the traffic, we would have arrived on time.', 'hadn''t been', NULL, NULL, NULL, NULL, 'Idiom "If it ___ for X" = if X hadn''t happened/existed.', 'If it hadn''t been for = without. Describes a factor that changed the outcome.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{Conditional}', false, 'Form: hadn''t been (past perfect of "be").', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('2ef1201d-f9be-4ff6-9f65-3455a2b4008d', 414, 'gap_fill', 'C1', 'inversion', 'Rarely ___ I seen such a beautiful sunset.', 'have', NULL, NULL, NULL, NULL, 'Inversion after fronted negative adverb.', 'Inversion after Rarely: Rarely + auxiliary + subject + past participle.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{Inversion}', false, 'Form: Rarely ___ + subject + past participle.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('9b6d6ac1-cc94-4f74-98bb-220031f8ac87', 1982, 'sentence_building', 'A2', 'travel', 'Quiero facturar una maleta.', 'I want to check in a suitcase', '["I", "want", "to", "check", "in", "a", "suitcase", "one", "bag", "two", "have"]', NULL, NULL, '[{"answer": "I want to check a suitcase", "feedback": ""}, {"answer": "I want to check in a bag", "feedback": ""}, {"answer": "I want to check a bag in", "feedback": ""}, {"answer": "I want to check a bag", "feedback": ""}, {"answer": "I want to check in one suitcase", "feedback": "\"A suitcase\" is more natural than \"one\" here — a common mistake for Spanish speakers."}, {"answer": "I want to check one suitcase", "feedback": "\"A suitcase\" is more natural than \"one\" here — a common mistake for Spanish speakers."}, {"answer": "I want to check one suitcase in", "feedback": "\"A suitcase\" is more natural than \"one\" here — a common mistake for Spanish speakers."}, {"answer": "I want to check in one bag", "feedback": "\"A bag\" is more natural than \"one\" here — a common mistake for Spanish speakers."}, {"answer": "I want to check one bag", "feedback": "\"A bag\" is more natural than \"one\" here — a common mistake for Spanish speakers."}, {"answer": "I want to check one bag in", "feedback": "\"A bag\" is more natural than \"one\" here — a common mistake for Spanish speakers."}]', NULL, '"Check in" as a verb means to register your luggage at the airport. "One suitcase" = una maleta.', '2026-04-13 09:19:30.039983+00', NULL, NULL, 'en', '{Travel}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('1e025b16-90a1-4d54-91de-8a9c81e6cd18', 112, 'multiple_choice', 'B1', 'going_to_vs_will', 'Look at those clouds! It ___ rain.', 'is going to', '["will", "is going to", "rains", "is raining"]', NULL, NULL, NULL, 'There''s evidence right now (the clouds). Predictions based on what you can see.', 'Going to for predictions based on present evidence. if you are looking at the clouds, it''s "going to", if you''re predicting without evidence, use "will".', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{"Future form"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('4a71930d-d550-430d-a8eb-558d124bfe64', 122, 'multiple_choice', 'B2', 'third_conditional', 'If I ___ you were coming, I would have prepared dinner.', 'had known', '["know", "known", "had known", "would know"]', NULL, NULL, NULL, 'Imagining a different past. The if-clause needs past perfect.', 'Third conditional: If + past perfect, would have + past participle.', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{Conditional}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('27da9be5-d179-4f79-8d6a-88abb6ecf007', 125, 'multiple_choice', 'B1', 'too_enough', 'This coffee is ___ hot. I can''t drink it yet.', 'too', '["so", "enough", "very", "too"]', NULL, NULL, NULL, 'Excessively hot — uncomfortably so.', 'Too means more than necessary or wanted.', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{"Too & enough"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('9b054453-7186-4ed8-ae74-c7261b2dbd16', 128, 'multiple_choice', 'B1', 'first_conditional', 'If it ___ tomorrow, we''ll cancel the picnic.', 'rains', '["will rain", "rains", "is raining", "rained"]', NULL, NULL, NULL, 'First conditional uses present simple in the if-clause (even though it refers to the future).', 'First conditional: If + present simple, will + infinitive.', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{Conditional}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('6460ffa0-4ca9-4c4c-82e7-66071870d521', 135, 'multiple_choice', 'B1', 'modals_advice', 'You look tired. You ___ go to bed earlier.', 'should', '["can", " don''t have to", "ought", "should"]', NULL, NULL, NULL, 'Giving advice based on what you observe (she looks tired).', 'Should for giving advice.', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{"Modal verb"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('c1187cf5-6cba-4b6b-97d2-ac5e5dc287ea', 138, 'multiple_choice', 'B2', 'second_conditional', 'If I ___ you, I would accept the job offer.', 'were', '["am", "are", "were", "will be"]', NULL, NULL, NULL, 'Hypothetical — and second conditional has a special form for "I" and "she".', 'Were for all persons in second conditional (preferred form).', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{Conditional}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('63454b0a-7201-4235-a284-114f994889b4', 140, 'multiple_choice', 'B2', 'have_something_done', 'I need to ___ my hair ___.', 'have / cut', '["have / to cut", "make / cut", "cut / have", "have / cut"]', NULL, NULL, NULL, 'Someone else does it for you. Form: have + object + past participle.', 'Have + object + past participle (causative structure).', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{Causative}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('e218ccea-1c09-4fd6-b938-902ec13adcef', 143, 'multiple_choice', 'B1', 'adverbs_manner', 'She speaks English very ___.', 'well', '["good", "well", "nice", "better"]', NULL, NULL, NULL, 'The adverb form of "good" — describes *how* she speaks.', 'Well is the adverb form of good.', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{Adverb}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('91231573-94a3-441c-970d-b21ca104d84c', 144, 'multiple_choice', 'B2', 'wish_regret', 'I wish I ___ harder when I was at school.', 'had studied', '["study", "studying", "had studied", "would study"]', NULL, NULL, NULL, 'Regret about the past — use past perfect after wish.', 'Wish + past perfect for past regrets.', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{"Wish & regret"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('dfbbfa36-71fd-4c9c-a42f-1872688d960d', 150, 'multiple_choice', 'B1', 'possessive_pronouns', 'This book is ___. I bought it yesterday.', 'mine', '["my", "mine", "me", "I"]', NULL, NULL, NULL, 'It stands alone — "the book is ___". Not "my book".', 'Possessive pronouns stand alone without a noun.', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{Pronoun}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('002bee35-cf92-41bb-915f-50bfe663d67a', 415, 'gap_fill', 'C1', 'inversion', 'Never before ___ the company faced such a crisis.', 'had', NULL, NULL, NULL, NULL, 'Inversion + past tense.', 'Inversion after Never before: Never before + had + subject + past participle.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{Inversion}', false, 'Form: Never before ___ + subject + past participle.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('11556980-6811-4ab9-a353-888d54d27001', 416, 'gap_fill', 'C2', 'inversion', 'Under no circumstances ___ you to leave the building.', 'are', NULL, NULL, NULL, NULL, 'Inversion + passive structure: "you are to leave".', 'Inversion after Under no circumstances: Under no circumstances + auxiliary + subject.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{Inversion}', false, 'Form: ___ + you + to + base verb.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('cc0b81ec-077a-44e8-9aa4-bd77e5382e5e', 417, 'gap_fill', 'C1', 'inversion', 'No sooner ___ we arrived than it started to rain.', 'had', NULL, NULL, NULL, NULL, '"No sooner ___ X than Y" — past perfect in the first clause.', 'No sooner + had + subject + past participle + than. Describes two quick past events.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{Inversion}', false, 'Pair structure: No sooner ___ than...', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('10fc99e5-6f0f-449f-92c4-630e7f4e01d4', 418, 'gap_fill', 'C1', 'inversion', 'Hardly ___ she finished speaking when the phone rang.', 'had', NULL, NULL, NULL, NULL, '"Hardly ___ X when Y" — similar to "no sooner...than".', 'Hardly + had + subject + past participle + when. Similar to no sooner...than.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{Inversion}', false, 'Past perfect: ___ + subject + past participle.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('7313c298-e261-4b77-b422-166fb54ce200', 419, 'gap_fill', 'C2', 'inversion', 'Not until the results were published ___ the extent of the problem become clear.', 'did', NULL, NULL, NULL, NULL, 'Inversion after fronted "Not until" + clause.', 'Not until + clause, + auxiliary + subject + verb. Emphatic structure.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{Inversion}', false, 'Form: Not until X ___ + subject + base verb.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('d464d6e8-e1a6-441f-be29-c5291b167f77', 420, 'gap_fill', 'C1', 'inversion', 'Only after reading the report ___ I understand the situation.', 'did', NULL, NULL, NULL, NULL, 'Inversion after fronted "Only after".', 'Only after + noun/gerund, + auxiliary + subject + verb.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{Inversion}', false, 'Auxiliary first — like a question.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('003cd481-c9d3-49d2-b247-02834a709f26', 421, 'gap_fill', 'C1', 'inversion', 'Seldom ___ we had the opportunity to work with such talented people.', 'have', NULL, NULL, NULL, NULL, 'Inversion after negative adverb "seldom".', 'Seldom + auxiliary + subject + verb. For emphasis on rarity.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{Inversion}', false, 'Form: Seldom ___ + subject + past participle.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('348c8061-7c2d-4c1b-8167-05f322b37870', 422, 'gap_fill', 'C2', 'inversion', 'So impressive ___ the performance that the audience gave a standing ovation.', 'was', NULL, NULL, NULL, NULL, 'Inversion after fronted "So + adjective".', 'So + adjective + auxiliary + subject + that clause. For dramatic emphasis.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{Inversion}', false, 'Form: "to be" inverted: ___ the performance.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('27bfe2a0-4caa-405c-bb9f-653df0a41c8e', 1840, 'gap_fill', 'A2', 'spanish', 'Me _______ fatal que la gente llegue tarde sin avisar — es muy desconsiderado.', 'parece', NULL, NULL, NULL, NULL, NULL, '"Parecer" funciona como "gustar": me parece + adjetivo para expresar una opinión o reacción.', '2026-04-06 16:43:51.906934+00', NULL, NULL, 'es', '{Spanish}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('f6536e1e-6448-4b57-bbd6-afdf47b55a2f', 153, 'multiple_choice', 'B2', 'would_rather', 'I''d rather ___ at home tonight.', 'stay', '["staying", "to stay", "stayed", "stay"]', NULL, NULL, NULL, 'Form: would rather + infinitive without "to".', 'Would rather + infinitive without ''to''.', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{"Modal verb"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('43c63d6b-a9fe-42f9-95d6-2f8b347fac44', 160, 'multiple_choice', 'B1', 'frequency_adverbs', 'I ___ eat breakfast. I''m never hungry in the morning.', 'hardly ever', '["always", "usually", "sometimes", "hardly ever"]', NULL, NULL, NULL, 'Almost never. Stronger than "rarely".', 'Hardly ever means almost never.', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{Adverb}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('12e65558-37e8-4e20-b9c5-963481e8efd3', 171, 'multiple_choice', 'B1', 'time_expressions', 'I haven''t seen her ___ last week.', 'since', '["for", "since", "ago", "from"]', NULL, NULL, NULL, '"Last week" is a specific point in time, not a duration.', 'Since with a point in time.', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{"Time expression"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('0a8e6017-1494-4cf7-989c-3acb2dd6b586', 1841, 'gap_fill', 'A2', 'spanish', '¿Cuánto tiempo _______ en llegar al aeropuerto desde el hotel en taxi?', 'tarda', NULL, NULL, NULL, NULL, NULL, '"Tardar en + infinitivo" expresa el tiempo que necesita algo. ¿Cuánto tiempo tarda? = How long does it take?', '2026-04-06 16:43:51.906934+00', NULL, NULL, 'es', '{Spanish}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('838ee4c7-0a7f-433b-a2c8-0420e8aaaeb5', 1842, 'gap_fill', 'A2', 'spanish', 'El camarero nos _______ la carta y nos dejó unos minutos para decidir.', 'trajo', NULL, NULL, NULL, NULL, NULL, '"Traer" en pretérito indefinido, tercera persona singular: trajo (verbo irregular).', '2026-04-06 16:43:51.906934+00', NULL, NULL, 'es', '{Spanish}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('4cd38ef1-9770-41f5-881c-7a3ffca3e5f2', 1843, 'gap_fill', 'A2', 'spanish', 'Hemos _______ en este hotel antes — la última vez fue hace dos años.', 'estado', NULL, NULL, NULL, NULL, NULL, 'Participio de "estar" → estado. Haber + estado = pretérito perfecto compuesto.', '2026-04-06 16:43:51.906934+00', NULL, NULL, 'es', '{Spanish}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('495c0a7b-f2aa-458c-9c12-841209d39bd0', 1844, 'gap_fill', 'A2', 'spanish', 'A _______ de los problemas con el vuelo, conseguimos llegar a tiempo.', 'pesar', NULL, NULL, NULL, NULL, NULL, '"A pesar de" = despite/in spite of. Expresa contraste con una dificultad o obstáculo.', '2026-04-06 16:43:51.906934+00', NULL, NULL, 'es', '{Spanish}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('ad0324f2-21ac-43f8-b66a-0e0c2602042a', 1845, 'gap_fill', 'A2', 'spanish', 'Esta mañana he _______ las llaves de casa y he llegado tarde al trabajo.', 'perdido', NULL, NULL, NULL, NULL, NULL, 'Participio de "perder" → perdido. Forma parte del pretérito perfecto compuesto: he perdido.', '2026-04-06 16:43:51.906934+00', NULL, NULL, 'es', '{Spanish}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('3cbddd3e-37da-4bdf-a0f8-e1f76975e2ee', 1846, 'gap_fill', 'A2', 'spanish', 'El vuelo _______ dos horas de retraso a causa del mal tiempo en el aeropuerto de origen.', 'tuvo', NULL, NULL, NULL, NULL, NULL, '"Tener" en pretérito indefinido, tercera persona singular: tuvo.', '2026-04-06 16:43:51.906934+00', NULL, NULL, 'es', '{Spanish}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('ecc26eb1-60e3-4177-a03b-d7ced305f838', 1507, 'gap_fill', 'C1', 'hotel_vocabulary', 'The general manager reviewed the weekly _____ report — a key metric combining occupancy rate and average room rate to measure revenue performance.', 'RevPAR', NULL, NULL, NULL, NULL, 'Hotel acronym for Revenue Per Available Room.', 'RevPAR (Revenue Per Available Room) is one of the most important KPIs in hotel management. It is calculated by multiplying occupancy rate by average daily rate (ADR).', '2026-03-23 08:55:51.646247+00', NULL, NULL, 'en', '{}', false, 'Combines occupancy rate and average rate — key hotel metric.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('9f6ebcbe-eeb1-45f4-a61d-fe1426072784', 1508, 'gap_fill', 'C1', 'hotel_vocabulary', 'The hotel introduced a _____ programme to reward returning guests with free nights, room upgrades, and priority check-in.', 'loyalty', NULL, NULL, NULL, NULL, '___ programme — rewards returning guests.', 'A loyalty programme (or rewards programme) incentivises repeat stays by offering points or benefits. Major hotel chains use these to build long-term relationships with high-value guests.', '2026-03-23 08:55:51.646247+00', NULL, NULL, 'en', '{}', false, 'Common in hospitality and airlines.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('3b88d39b-fd4f-4f2e-b878-8ef7bf110d9e', 1509, 'gap_fill', 'C1', 'hotel_vocabulary', 'The front desk team was trained to handle _____ with empathy — listening carefully, apologising sincerely, and offering a practical solution.', 'complaints', NULL, NULL, NULL, NULL, 'Customer dissatisfaction — formal expressions thereof.', 'Complaint handling is a critical skill in hospitality. The standard approach is to listen, acknowledge, apologise, act, and follow up — sometimes referred to as the LEARN or HEARD model.', '2026-03-23 08:55:51.646247+00', NULL, NULL, 'en', '{}', false, 'Often paired with "handle" or "address".', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('40306614-1b43-4cbe-8118-745184b6922f', 1510, 'gap_fill', 'C1', 'hotel_vocabulary', 'A 10% _____ charge was automatically added to all food and beverage bills to cover the cost of staff gratuities.', 'service', NULL, NULL, NULL, NULL, '___ charge — automatic addition to bill for staff gratuities.', 'A service charge is a mandatory or discretionary percentage added to a bill in lieu of a tip. In the UK it is often 12.5%. Guests should be informed whether it is optional or compulsory.', '2026-03-23 08:55:51.646247+00', NULL, NULL, 'en', '{}', false, 'Same word as in "after-___" or "self-___".', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('7029ab35-e15c-42e7-b407-ba45de12c7d0', 1511, 'gap_fill', 'C2', 'hotel_vocabulary', 'The group''s head office issued detailed _____ standards covering everything from uniform presentation to the exact wording of telephone greetings.', 'brand', NULL, NULL, NULL, NULL, '___ standards — the rules ensuring consistency across a hotel chain.', 'Brand standards are the detailed guidelines issued by a hotel group to ensure consistency across all properties. They cover everything from physical appearance to service language and complaint resolution procedures.', '2026-03-23 08:55:51.646247+00', NULL, NULL, 'en', '{}', false, 'Same word as in "branding".', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('cfbbd681-c1b6-4174-b6f8-1ed73539bff2', 1987, 'sentence_building', 'B1', 'travel', '¿Podría decirme dónde está la puerta de embarque?', 'Could you tell me where the gate is?', '["could", "you", "tell", "me", "where", "the", "gate", "is", "can", "show", "door", "terminal"]', NULL, NULL, '[{"answer": "Can you tell me where the gate is?", "feedback": "Also correct — \"can\" works fine for a polite request. \"Could\" is slightly more formal."}]', NULL, '"Could you tell me where...?" is a polite indirect question. Note the word order after "where": subject + verb, not "where is the gate?".', '2026-04-13 09:19:30.039983+00', NULL, NULL, 'en', '{Travel}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('61db4a8e-debd-4545-8b10-68381bccb61a', 1513, 'gap_fill', 'C2', 'hotel_vocabulary', 'The revenue team used _____ segmentation to identify which guest categories — leisure, corporate, or group — were most profitable during each quarter.', 'market', NULL, NULL, NULL, NULL, '___ segmentation — dividing customers into groups by characteristics.', 'Market segmentation divides guests into categories based on purpose of travel, booking channel, or spend level. It allows hotels to target marketing and pricing strategies more effectively.', '2026-03-23 08:55:51.646247+00', NULL, NULL, 'en', '{}', false, 'Same word as in "target ___" or "___ research".', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('cef75e77-bf09-4cc7-823c-fd3e804af6b9', 1514, 'gap_fill', 'C2', 'hotel_vocabulary', 'Following a negative review on a major booking platform, the general manager posted a carefully worded _____ that acknowledged the issue and outlined the steps taken to resolve it.', 'response', NULL, NULL, NULL, NULL, 'A reply or reaction — formally written.', 'A public response to a negative online review is an important part of reputation management. A well-written response shows professionalism, addresses the concern directly, and signals to future guests that the hotel takes feedback seriously.', '2026-03-23 08:55:51.646247+00', NULL, NULL, 'en', '{}', false, 'Sharing a root with "respond".', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('51401bd4-de8c-4811-b579-3079993bd9d4', 1515, 'gap_fill', 'C2', 'hotel_vocabulary', 'The hotel''s _____ agreement with a tour operator guaranteed a block of 30 rooms per night throughout the summer season.', 'allotment', NULL, NULL, NULL, NULL, 'A reserved block of rooms set aside for specific clients.', 'An allotment agreement reserves a set number of rooms for a specific partner — such as a tour operator or airline — on a contracted basis. Unsold rooms are typically released back to the hotel by a set date.', '2026-03-23 08:55:51.646247+00', NULL, NULL, 'en', '{}', false, 'Sharing a root with "allot" — to assign.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('01219496-9f6d-4457-a491-745bd1d8e108', 1571, 'gap_fill', 'B1', 'prepositions', 'She thanked everyone _____ their patience during the difficult transition period.', 'for', NULL, NULL, NULL, NULL, 'Always: "thanked ___ + something".', 'Thank someone for something is the correct structure. Compare: apologise to someone for something, blame someone for something.', '2026-03-26 08:02:12.742714+00', NULL, NULL, 'en', '{"Dependent preposition"}', false, 'Same as in "grateful ___".', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('5bd61984-0b13-443d-801f-ab415af23eb1', 1573, 'gap_fill', 'B1', 'prepositions', 'She was promoted _____ the basis of her outstanding performance over the past year.', 'on', NULL, NULL, NULL, NULL, 'Phrase: "___ the basis of" = based on.', 'On the basis of means because of, or using something as a justification or criterion. Compare: on the grounds of, in light of, owing to.', '2026-03-26 08:02:12.742714+00', NULL, NULL, 'en', '{"Fixed expression"}', false, 'Same as in "___ the grounds of".', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('1542b31b-e8f5-4f39-808e-a5d8aa904c26', 1574, 'gap_fill', 'B2', 'prepositions', 'The salary increase was agreed _____ exchange for longer working hours.', 'in', NULL, NULL, NULL, NULL, 'Phrase: "___ exchange for" = traded for.', 'In exchange for means as a trade or swap — giving one thing in return for another. Compare: in return for, as compensation for.', '2026-03-26 08:02:12.742714+00', NULL, NULL, 'en', '{"Fixed expression"}', false, 'Same as in "___ return for".', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('7fb83dd9-805a-49e7-b9c8-d67b4daf95c7', 1575, 'gap_fill', 'B2', 'prepositions', 'The new strategy was developed _____ terms of both cost efficiency and long-term sustainability.', 'in', NULL, NULL, NULL, NULL, 'Phrase: "___ terms of" = with regard to.', 'In terms of is a fixed prepositional phrase used to specify the aspect or dimension being considered. Compare: with respect to, as regards, from the perspective of.', '2026-03-26 08:02:12.742714+00', NULL, NULL, 'en', '{"Fixed expression"}', false, 'Useful linker for analysis.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('5c7b2a69-7947-4643-babb-5f4019be4230', 1576, 'gap_fill', 'C1', 'prepositions', 'The decision was taken _____ the absence of any clear guidance from the board.', 'in', NULL, NULL, NULL, NULL, 'Phrase: "___ the absence of" = without.', 'In the absence of means when something is not present or available. It is a formal prepositional phrase common in business and legal writing.', '2026-03-26 08:02:12.742714+00', NULL, NULL, 'en', '{"Fixed expression","Formal register"}', false, 'Formal alternative to "without".', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('eb44d03b-4012-45df-bfee-749717f7d948', 1577, 'gap_fill', 'C1', 'prepositions', 'The policy was introduced _____ a view to reducing staff turnover in the long term.', 'with', NULL, NULL, NULL, NULL, 'Phrase: "___ a view to + -ing" = aimed at.', 'With a view to doing something means with the intention or aim of achieving something. It is a formal expression used in business and official documents.', '2026-03-26 08:02:12.742714+00', NULL, NULL, 'en', '{"Fixed expression","Formal register"}', false, 'Always paired with "to" + -ing form.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('cf2884ae-e430-423c-a962-c5161b2f0790', 1578, 'gap_fill', 'C1', 'prepositions', 'She achieved the result _____ virtue of her exceptional preparation rather than any particular talent.', 'by', NULL, NULL, NULL, NULL, 'Phrase: "___ virtue of" = because of.', 'By virtue of means because of or as a result of. It is a formal phrase typically used to explain why someone is entitled to something or how something was achieved.', '2026-03-26 08:02:12.742714+00', NULL, NULL, 'en', '{"Fixed expression","Formal register"}', false, 'Formal alternative to "because of".', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('85eed8ba-4b07-4799-9ee7-06ace6a15ad4', 1579, 'gap_fill', 'C1', 'prepositions', 'The expansion was approved _____ light of the strong quarterly results and positive market forecasts.', 'in', NULL, NULL, NULL, NULL, 'Phrase: "___ light of" = considering.', 'In light of means taking something into consideration; because of new information or circumstances. Compare: in view of, given, considering.', '2026-03-26 08:02:12.742714+00', NULL, NULL, 'en', '{"Fixed expression","Formal register"}', false, 'Same as in "___ view of".', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('dc90b7f6-d6f1-4a3b-9798-c52669e5cb08', 1580, 'gap_fill', 'C1', 'prepositions', 'Growth was achieved _____ the expense of employee wellbeing — a trade-off the board later regretted.', 'at', NULL, NULL, NULL, NULL, 'Phrase: "___ the expense of" = at the cost of.', 'At the expense of means causing harm or loss to something else in order to achieve a goal. Compare: to the detriment of, at the cost of.', '2026-03-26 08:02:12.742714+00', NULL, NULL, 'en', '{"Fixed expression"}', false, 'Same as in "___ the cost of".', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('4c559eec-6bea-475a-9c54-3d7cdabd3179', 1581, 'gap_fill', 'C2', 'prepositions', 'The redundancies were made _____ the grounds of operational necessity, though many employees disputed this.', 'on', NULL, NULL, NULL, NULL, 'Phrase: "___ the grounds of" = on the basis of.', 'On the grounds of means using something as a justification or legal basis. Compare: on the basis of, for reasons of. Common in legal and formal HR contexts.', '2026-03-26 08:02:12.742714+00', NULL, NULL, 'en', '{"Fixed expression","Formal register"}', false, 'Same as in "___ the basis of".', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('471b65cf-0b8b-435a-89fb-8b7acf0d4db6', 1582, 'gap_fill', 'C2', 'prepositions', 'The committee approved the proposal _____ the wake of the damaging audit report, hoping it would restore confidence.', 'in', NULL, NULL, NULL, NULL, 'Phrase: "___ the wake of" = following (an event).', 'In the wake of means as a consequence of, or following on from something — typically something significant or disruptive. Compare: following, in the aftermath of.', '2026-03-26 08:02:12.742714+00', NULL, NULL, 'en', '{"Fixed expression","Formal register"}', false, 'Like a ship leaving a wake behind.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('f1ad904e-25a5-4009-86c1-8df4c4cc94f2', 1236, 'multiple_choice', 'B2', 'business_phrasal_verbs', 'We''ve had to _____ several staff members due to the drop in demand.', 'lay off', '["lay off", "lay out", "lay down", "lay up"]', NULL, NULL, NULL, 'To dismiss workers (often due to economic reasons).', 'Lay off means to dismiss employees because of a lack of work, not because of poor performance. Compare: make redundant.', '2026-03-18 19:58:52.376507+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('71e93f54-245f-4812-8244-b3817db3985f', 1847, 'gap_fill', 'A2', 'spanish', 'El guía nos _______ que era imposible visitar el palacio sin reserva previa.', 'dijo', NULL, NULL, NULL, NULL, NULL, '"Decir" en pretérito indefinido, tercera persona singular: dijo (verbo irregular).', '2026-04-06 16:43:51.906934+00', NULL, NULL, 'es', '{Spanish}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('64d809e9-a751-4907-965b-850ecf5a484c', 1848, 'gap_fill', 'A2', 'spanish', 'Me _______ muchísimo conocer a gente nueva cuando viajo a otros países.', 'encanta', NULL, NULL, NULL, NULL, NULL, '"Encantar" funciona como "gustar": me encanta + infinitivo para expresar mucho entusiasmo.', '2026-04-06 16:43:51.906934+00', NULL, NULL, 'es', '{Spanish}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('94369241-81d4-48db-b0be-6ada6b16fb52', 1583, 'gap_fill', 'C2', 'prepositions', 'Staff were offered additional leave _____ lieu of overtime pay.', 'in', NULL, NULL, NULL, NULL, 'Phrase: "___ lieu of" = instead of.', 'In lieu of means instead of. It is a formal expression commonly used in employment and legal contexts. Compare: instead of, as a substitute for, as a replacement for.', '2026-03-26 08:02:12.742714+00', NULL, NULL, 'en', '{"Fixed expression","Formal register"}', false, 'French "lieu" = place. In place of.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('bcb6dec9-6a36-4f65-8cf9-55926d40e70d', 1584, 'gap_fill', 'C2', 'prepositions', 'The proposal failed _____ the committee''s initial enthusiasm.', 'notwithstanding', NULL, NULL, NULL, NULL, 'Formal preposition meaning "despite".', 'Notwithstanding means despite or in spite of. It is a formal preposition common in legal and official writing. It can appear before or after the noun it modifies.', '2026-03-26 08:02:12.742714+00', NULL, NULL, 'en', '{"Formal register"}', false, 'Compound: not + withstand + -ing.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('0ce732ec-19ef-4b62-89cd-1f62d077fcac', 1585, 'gap_fill', 'C2', 'prepositions', 'The contract was terminated _____ means of a formal written notice delivered to both parties.', 'by', NULL, NULL, NULL, NULL, 'Phrase: "___ means of" = through the use of.', 'By means of means using a particular method or instrument to achieve something. It is a formal phrase common in legal and business writing. Compare: through, via, using.', '2026-03-26 08:02:12.742714+00', NULL, NULL, 'en', '{"Fixed expression","Formal register"}', false, 'Same as in "___ way of".', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('5463b471-9c8b-471a-a92a-957976252fe3', 1681, 'gap_fill', 'B1', 'phrasal_verbs', 'I couldn''t _____ what she was trying to say — her explanation was very confusing.', 'figure out', NULL, NULL, NULL, NULL, 'To work something out by thinking — to understand after some effort.', 'Figure out means to understand something after thinking about it carefully, or to solve a problem. It is slightly more informal than work out, which can be used in the same way. Compare: make out (to hear or see something with difficulty), work out (to calculate or solve).', '2026-03-30 07:58:13.455589+00', NULL, NULL, 'en', '{}', false, 'Two words. Starts with f___ o___.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('7ae11835-a85b-4f93-856d-0a2e1b1c1f22', 1682, 'gap_fill', 'B1', 'phrasal_verbs', 'Despite not wanting to go, she decided to _____ with the plan and went to the interview.', 'go through', NULL, NULL, NULL, NULL, 'To do or experience something difficult — to follow through with a plan.', 'Go through with something means to do something you had planned or agreed to do, despite doubts or reluctance. Compare: go through (to experience something difficult), go ahead (to proceed with a plan). The with is essential — go through with makes clear you are completing something you almost didn''t.', '2026-03-30 07:58:13.455589+00', NULL, NULL, 'en', '{}', false, 'Two words. Starts with g___ t___.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('d2e2fb62-dccd-4cc1-9353-dd36a6bd8aa6', 1683, 'gap_fill', 'B1', 'phrasal_verbs', 'She always _____ her younger sister when other children were unkind to her.', 'stood up for', NULL, NULL, NULL, NULL, 'To defend someone — the past tense of standing in their corner.', 'Stand up for someone or something means to defend them or speak in their support, especially when they are being treated unfairly. Compare: stand up to (to resist or confront someone with more power), speak up (to say something, especially when it is difficult to do so).', '2026-03-30 07:58:13.455589+00', NULL, NULL, 'en', '{}', false, 'Three words: a verb + two prepositions. Starts with s___ u___ f___.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('dc3213cd-f26b-45fb-82cc-986d74f1180b', 1684, 'gap_fill', 'B2', 'phrasal_verbs', 'The whole project _____ when the main investor pulled out at the last minute.', 'fell apart', NULL, NULL, NULL, NULL, 'To collapse or break down completely — like a poorly built structure.', 'Fall apart means to break into pieces, or — figuratively — to collapse or fail completely. Compare: fall through (a specific plan or deal fails to happen), break down (a machine stops working, or a situation deteriorates), fall out (people argue and damage a relationship).', '2026-03-30 07:58:13.455589+00', NULL, NULL, 'en', '{}', false, 'Two words: past tense of "fall" + a___.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('b69fcff9-5cfe-41f1-bdb5-5cb54412c8d0', 1685, 'gap_fill', 'B2', 'phrasal_verbs', 'I''ve been _____ calling the dentist for months — I really need to stop putting it off.', 'putting off', NULL, NULL, NULL, '[{"answer": "postponing", "feedback": "Good — postponing captures the meaning well, but the answer is the phrasal verb putting off, which is what the sentence is testing."}]', 'Continuously delaying something you should do.', 'Put off doing something means to delay or postpone it, often because you don''t want to do it. It is also used transitively: don''t let the price put you off (discourage you). Compare: put back (to reschedule to a later time), delay, postpone.', '2026-03-30 07:58:13.455589+00', NULL, NULL, 'en', '{}', false, 'Two words: -ing form + o___.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('551c410e-824f-44e4-a900-1d9d9d87ce2f', 1686, 'gap_fill', 'C1', 'phrasal_verbs', 'Despite everything that had happened, she managed to _____ her dignity throughout the ordeal.', 'hold onto', NULL, NULL, NULL, NULL, 'To keep something — to not let it go, especially something abstract like dignity.', 'Hold onto something means to keep or maintain something, especially with effort. It can be used literally (hold onto the railing) or figuratively (hold onto your principles, hold onto hope). Compare: hold out (to resist or last), hold on (to wait, or to grip something).', '2026-03-30 07:58:13.455589+00', NULL, NULL, 'en', '{}', false, 'Two words. Starts with h___ o___.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('f9088d89-f4c4-4f6c-81e5-fbb25b62c61d', 1687, 'gap_fill', 'C1', 'phrasal_verbs', 'It took him years to _____ the shame of failing so publicly.', 'live down', NULL, NULL, NULL, NULL, 'To recover from public embarrassment over time — to make people forget about it.', 'Live something down means to escape from the embarrassment or shame of a past mistake — usually used in the negative: he''ll never live it down. It implies that the memory of the event continues to follow someone. Compare: get over (to recover from something emotionally), put behind you (to stop letting something affect you).', '2026-03-30 07:58:13.455589+00', NULL, NULL, 'en', '{}', false, 'Two words. Starts with l___ d___.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('f556ec2a-1fa7-49d2-b60f-b3b954bd7eff', 1688, 'gap_fill', 'C1', 'phrasal_verbs', 'She didn''t fully _____ the implications of signing the contract until it was too late.', 'take in', NULL, NULL, NULL, NULL, 'To fully understand or absorb information.', 'Take in means to fully understand or absorb information — often used when there is a lot to process or when something is surprising. It can also mean to deceive someone (she was taken in by his story) or to provide shelter (they took in refugees). Context determines the meaning.', '2026-03-30 07:58:13.455589+00', NULL, NULL, 'en', '{}', false, 'Two words. Starts with t___ i___.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('8e128371-d4af-4f35-ac9f-85af9a8fbb5c', 1716, 'gap_fill', 'C1', 'business_phrasal_verbs', 'The board agreed to _____ the dividend payment until the company returned to profitability.', 'hold off', NULL, NULL, NULL, NULL, 'To delay something — to keep it back temporarily.', 'Hold off means to delay doing something, often while waiting for a better moment or more information. In business it is used for decisions, payments, and announcements. Compare: put off (to postpone — more general), defer (more formal, used for payments and obligations), hold back (to restrain or withhold something).', '2026-03-30 08:25:59.401228+00', NULL, NULL, 'en', '{}', false, 'Two words. Starts with h___ o___.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('cd985a95-e459-472c-944a-13cb82be76a5', 1717, 'gap_fill', 'C1', 'business_phrasal_verbs', 'The new compliance framework will _____ all departments, including those that were previously exempt.', 'apply to', NULL, NULL, NULL, NULL, 'To affect — when a rule covers a particular group or thing.', 'Apply to means to be relevant to or affect a particular group or situation. In legal and business contexts it is essential. Compare: pertain to (more formal), relate to (more general), cover (to include within scope). Apply to is also used when submitting an application for a job or funding.', '2026-03-30 08:25:59.401228+00', NULL, NULL, 'en', '{}', false, 'Two words. Starts with a___ t___.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('2e4bb124-a1d3-4b1a-88e8-82bb99690c5e', 1718, 'gap_fill', 'C1', 'business_phrasal_verbs', 'Despite the difficult conditions, the company managed to _____ a profit for the third consecutive year.', 'turn out', NULL, NULL, NULL, NULL, 'To produce or generate a result, often a positive one like a profit.', 'Turn out a profit or result means to produce or achieve it. It implies success despite conditions that might have made it difficult. Compare: generate (more formal), produce, deliver. Turn out also means to result or end in a particular way: it turned out better than expected.', '2026-03-30 08:25:59.401228+00', NULL, NULL, 'en', '{}', false, 'Two words. Starts with t___ o___.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('d7f374c9-6f71-4134-80ee-3607deaf1404', 1849, 'gap_fill', 'A2', 'spanish', '_______ de hacer la reserva, es importante leer las condiciones de cancelación.', 'Antes', NULL, NULL, NULL, NULL, NULL, '"Antes de + infinitivo" = before doing something. Indica que una acción precede a otra.', '2026-04-06 16:43:51.906934+00', NULL, NULL, 'es', '{Spanish}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('008f196b-5de1-48d4-b2b8-63754cee45b3', 1850, 'gap_fill', 'A2', 'spanish', 'Cuando vivía en Madrid, _______ al Retiro casi todos los fines de semana.', 'iba', NULL, NULL, NULL, NULL, NULL, 'El imperfecto "iba" describe una acción habitual en el pasado. "Casi todos los fines de semana" indica repetición.', '2026-04-06 16:43:51.906934+00', NULL, NULL, 'es', '{Spanish}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('35796b02-900b-4cf5-acbc-bcba4440cc0d', 1689, 'gap_fill', 'C1', 'phrasal_verbs', 'The government tried to _____ the strikers, but they refused to return to work.', 'face down', NULL, NULL, NULL, NULL, 'To confront someone with such firmness that they back off — staring them out.', 'Face down means to confront someone and force them to back down through strength or determination. It implies a direct and confident confrontation. Compare: face up to (to accept a difficult truth or situation), stand up to (to resist someone with power or authority).', '2026-03-30 07:58:13.455589+00', NULL, NULL, 'en', '{}', false, 'Two words. Starts with f___ d___.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('8d9c8ce6-ce44-4376-89df-9c2f1f6215eb', 1690, 'gap_fill', 'C1', 'phrasal_verbs', 'It took time, but she eventually _____ terms with the fact that the relationship was over.', 'came to', NULL, NULL, NULL, NULL, 'To eventually accept or reach a particular state of mind.', 'Come to terms with something means to gradually accept a difficult or painful reality. It implies a process of adjustment rather than an immediate reaction. Compare: get over (to recover from something), make peace with (to accept something and stop fighting it), come round to (to gradually start agreeing with something).', '2026-03-30 07:58:13.455589+00', NULL, NULL, 'en', '{}', false, 'Two words: past of "come" + t___.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('578dd3e0-a445-46d3-b9ce-2ee6f6792bfa', 1988, 'sentence_building', 'B1', 'travel', 'Mi vuelo se ha retrasado dos horas.', 'My flight has been delayed by two hours.', '["my", "flight", "has", "been", "delayed", "by", "two", "hours", "cancelled", "for", "one", "late"]', NULL, NULL, '[{"answer": "My flight has been delayed for two hours.", "feedback": "Also correct — \"delayed for\" is natural and widely used. \"Delayed by\" is the more formal phrasing."}]', NULL, '"Has been delayed" is present perfect passive. Use "by" to express the amount of delay.', '2026-04-13 09:19:30.039983+00', NULL, NULL, 'en', '{Travel}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('7ee04579-c794-4c8a-8a40-9c3a3500dc59', 2106, 'sentence_building', 'B2', 'grammar', NULL, 'I''m not used to getting up so early.', '["I''m", "not", "used", "to", "getting", "up", "so", "early", "get", "such"]', NULL, NULL, NULL, NULL, '"Be used to + -ing" means being accustomed to something: "used to getting up".', '2026-06-01 07:13:28.516357+00', NULL, NULL, 'en', '{Gerund}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('87fe0a60-abae-4ba5-a47d-80690df1f3aa', 2107, 'sentence_building', 'B2', 'grammar', NULL, 'Neither of us was aware of the change.', '["neither", "of", "us", "was", "aware", "the", "change", "were", "about"]', NULL, NULL, NULL, NULL, '"Neither of us" takes a singular verb in formal English: "was aware".', '2026-06-01 07:13:28.516357+00', NULL, NULL, 'en', '{Agreement}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('b3b13993-33a4-412e-8a90-b3ab4454249a', 176, 'multiple_choice', 'B2', 'relative_clauses_which', 'My car, ___ I only bought last year, has broken down.', 'which', '["that", "which", "who", "what"]', NULL, NULL, NULL, 'Non-defining relative clause (with commas) — referring to a thing.', 'Which in non-defining relative clauses (with commas).', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{"Relative clause"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('52176b03-909e-43c2-9677-6b93d5659fed', 1726, 'multiple_choice', 'A1', 'sport', 'How many lengths of a standard 25-metre pool do you need to swim to complete one kilometre?', 'forty', '["forty", "twenty", "fifty", "thirty"]', NULL, NULL, NULL, '1 km = 1000m. Divide that by 25.', 'A standard short-course pool is 25 metres long. One kilometre is 1,000 metres, so you need to swim 40 lengths. Many swimmers count lengths to track their distance. A 50-metre pool is called a long-course pool and is used for Olympic competitions.', '2026-03-30 08:52:38.502672+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('a4a2df8e-9b9c-4447-aa65-2e6b18fd4a6a', 178, 'multiple_choice', 'B2', 'causative_get', 'I must get my bike ___.', 'repaired', '["repair", "repaired", "repairing", "to repair"]', NULL, NULL, NULL, 'Get + object + past participle (someone else repairs it for you).', 'Get + object + past participle (causative).', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{Causative}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('7806e255-fe5d-4b45-a367-d438ccb33727', 1719, 'gap_fill', 'C1', 'business_phrasal_verbs', 'The CFO was brought in to _____ the books and identify where the losses were coming from.', 'go through', NULL, NULL, NULL, NULL, 'To examine carefully — to look closely through every detail.', 'Go through the books (or the accounts) means to examine financial records carefully and systematically. It implies thoroughness. Compare: audit (a formal external examination), look over (a quicker review), scrutinise (to examine very carefully). Going through the books is often done to detect errors, fraud, or inefficiency.', '2026-03-30 08:25:59.401228+00', NULL, NULL, 'en', '{}', false, 'Two words. Starts with g___ t___.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('fc45cca3-4743-44eb-931d-21de7b79bfe0', 1691, 'gap_fill', 'C2', 'phrasal_verbs', 'When the funding collapsed, the team had to _____ their existing knowledge and improvise.', 'fall back on', NULL, NULL, NULL, '[{"answer": "show", "feedback": "Also correct — \"show their existing knowledge\" works well here."}]', 'To rely on something as a backup when the main option fails.', 'Fall back on something means to use a resource, skill, or option when other things have failed — a backup or safety net. Compare: draw on (to make use of a skill or experience), rely on (to depend on something), resort to (to use something as a last option, often with a negative implication).', '2026-03-30 07:58:13.455589+00', NULL, NULL, 'en', '{}', false, 'Three words. Starts with f___ b___ o___.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('952cc111-7aa8-4188-a634-da7dbc755e83', 179, 'multiple_choice', 'B1', 'linking_but', 'I wanted to go out, ___ it was raining.', 'but', '["so", "but", "because", "and"]', NULL, NULL, NULL, 'Contrast — wanted X, but something prevented it.', 'But for contrast.', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{"Linking word"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('2d2cfee6-e8d5-4857-ac34-f54ca90c0de3', 1692, 'gap_fill', 'C2', 'phrasal_verbs', 'The investigation _____ serious flaws in the way the data had been collected and reported.', 'brought to light', NULL, NULL, NULL, NULL, 'An idiom: to reveal or expose hidden facts. Literally, to bring something out of darkness.', 'Bring to light means to reveal something that was previously hidden or unknown. It is a formal expression common in journalism, legal, and investigative contexts. Compare: uncover, expose, reveal. The passive (was brought to light) is equally common.', '2026-03-30 07:58:13.455589+00', NULL, NULL, 'en', '{}', false, 'Three words. Starts with b___ t___ l___.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('32c91a7a-d1a1-4300-a98f-d4facb4a3604', 1693, 'gap_fill', 'C2', 'phrasal_verbs', 'She had a difficult childhood, but she managed to _____ and build a successful career.', 'rise above it', NULL, NULL, NULL, NULL, 'An idiom: to not let difficulty defeat you — to mentally elevate yourself beyond it.', 'Rise above something means to not allow a negative situation, criticism, or difficulty to affect you or stop you from progressing. It implies strength of character and resilience. Compare: overcome, transcend, get past. Often used with it: she rose above it.', '2026-03-30 07:58:13.455589+00', NULL, NULL, 'en', '{}', false, 'Three words. Starts with r___ a___ i___.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('b0d9bba5-25df-4184-a213-e4edc97678b3', 1694, 'gap_fill', 'C2', 'phrasal_verbs', 'The scandal eventually _____, damaging the careers of everyone involved.', 'came out', NULL, NULL, NULL, NULL, 'When hidden information eventually becomes public.', 'Come out means to become publicly known — used for secrets, scandals, or information that was previously hidden. Compare: come to light (similar but more formal), leak out (information escapes gradually), break (news breaks when it becomes public). Come out has several other meanings (to be released, to declare one''s sexuality) — context makes it clear.', '2026-03-30 07:58:13.455589+00', NULL, NULL, 'en', '{}', false, 'Two words: past of "come" + o___.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('c218b9e7-4cf1-4276-b70e-220547a34214', 1695, 'gap_fill', 'C2', 'phrasal_verbs', 'Despite the enormous pressure of the final months, the team managed to _____ and deliver the project on time.', 'see it through', NULL, NULL, NULL, '[{"answer": "respond", "feedback": "Respond captures part of the idea, but the phrasal verb is see it through — meaning to continue until the very end despite difficulties."}]', 'An idiom: to finish something difficult that you''ve started, no matter what.', 'See something through means to continue with a task or commitment until it is completely finished, despite difficulties. Compare: follow through (to complete what you started), go through with (to do something you planned despite reluctance), stay the course (to continue despite difficulties). The it is often included even when the object is implied.', '2026-03-30 07:58:13.455589+00', NULL, NULL, 'en', '{}', false, 'Three words. Starts with s___ i___ t___.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('832846e5-1198-4362-bf21-00b55dbbe9d9', 1237, 'multiple_choice', 'B1', 'business_phrasal_verbs', 'The finance team will _____ the costs and report back next week.', 'look into', '["look into", "look over", "look up", "look after"]', NULL, NULL, NULL, 'To investigate — peer inside to find out.', 'Look into means to investigate or examine something in detail. Compare: the committee is looking into the issue.', '2026-03-18 19:58:52.376507+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('e07ea954-3e91-434b-adc7-35bce547537c', 1812, 'multiple_choice', 'A2', 'spanish', 'Elige la frase en pretérito perfecto compuesto:', 'He visitado París tres veces', '["He visitado París tres veces", "Visité París tres veces", "Visitaba París tres veces", "Visito París tres veces"]', NULL, NULL, NULL, NULL, 'El pretérito perfecto compuesto se forma con el presente de haber + participio pasado: he/has/ha + visitado.', '2026-04-06 16:43:09.309376+00', NULL, NULL, 'es', '{Spanish}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('01754c48-cae1-4ac1-b0d9-e2ff7a12a986', 1813, 'multiple_choice', 'A2', 'spanish', '"Cuando era pequeña, _____ al parque todos los domingos con mi familia."', 'iba', '["iba", "fui", "he ido", "voy"]', NULL, NULL, NULL, NULL, 'El imperfecto describe acciones habituales o repetidas en el pasado. "Todos los domingos" indica repetición.', '2026-04-06 16:43:09.309376+00', NULL, NULL, 'es', '{Spanish}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('cd9cba5e-626e-4f1d-82c1-5d80e5d6faa9', 1814, 'multiple_choice', 'A2', 'spanish', '¿Cuál es el significado de "ponerse rojo"?', 'ruborizarse de vergüenza', '["ruborizarse de vergüenza", "pintarse la cara de rojo", "enfadarse mucho", "estar de muy mal humor"]', NULL, NULL, NULL, NULL, '"Ponerse + adjetivo" describe un cambio de estado. "Ponerse rojo" = blushing, normalmente por vergüenza.', '2026-04-06 16:43:09.309376+00', NULL, NULL, 'es', '{Spanish}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('cfea1474-77fd-4264-95a2-b51301645354', 1082, 'gap_fill', 'C2', 'business_phrasal_verbs', 'The new CEO immediately set about _______ the bloated management structure that had developed under her predecessor.', 'cutting back on', NULL, NULL, NULL, '["doing away with", "streamlining", "slimming down"]', 'To reduce in scale.', 'To cut back on means to significantly reduce. To do away with is stronger — it means to eliminate completely.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Business phrasal verb","Financial vocabulary"}', false, 'Form: be + verb-ing.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('bfb14d59-6e43-4628-ac56-5782f034c846', 1851, 'gap_fill', 'A2', 'spanish', 'La recepcionista me _______ que el desayuno se servía entre las siete y las diez.', 'informó', NULL, NULL, NULL, NULL, NULL, '"Informar" en pretérito indefinido, tercera persona singular: informó.', '2026-04-06 16:43:51.906934+00', NULL, NULL, 'es', '{Spanish}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('424e9a5e-a3a8-428d-8232-d5946dec9444', 1852, 'gap_fill', 'A2', 'spanish', 'Prefiero las habitaciones _______ a las interiores porque me gusta la luz natural.', 'exteriores', NULL, NULL, NULL, NULL, NULL, '"Habitación exterior" da a la calle o al jardín. "Habitación interior" da al patio interior. Adjetivo plural femenino.', '2026-04-06 16:43:51.906934+00', NULL, NULL, 'es', '{Spanish}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('bc01ff8c-6ac8-47c7-af5e-92e314231e9a', 1853, 'gap_fill', 'A2', 'spanish', 'Se me _______ completamente que teníamos que facturar el equipaje con antelación.', 'olvidó', NULL, NULL, NULL, NULL, NULL, '"Olvidársele a alguien" = to forget. Se me olvidó = I forgot (literally: it forgot itself to me).', '2026-04-06 16:43:51.906934+00', NULL, NULL, 'es', '{Spanish}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('92496402-0f58-4146-8060-2a82bc556a3d', 2109, 'sentence_building', 'B2', 'grammar', NULL, 'It''s worth booking the tickets in advance.', '["it''s", "worth", "booking", "the", "tickets", "in", "advance", "book", "to", "worthy"]', NULL, NULL, NULL, NULL, '"It''s worth + -ing" recommends something: "worth booking".', '2026-06-01 07:13:28.516357+00', NULL, NULL, 'en', '{Gerund}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('55a526a4-b5f6-44f2-a42a-2d7c274fa2fc', 2110, 'sentence_building', 'C1', 'grammar', 'Nunca he visto una puesta de sol tan bonita.', 'Never have I seen such a beautiful sunset.', '["never", "have", "I", "seen", "such", "a", "beautiful", "sunset", "had", "saw", "so"]', NULL, NULL, NULL, NULL, 'Negative inversion: after "Never" the subject and auxiliary swap — "Never have I seen".', '2026-06-01 07:13:28.516357+00', NULL, NULL, 'en', '{Inversion}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('7d49a218-8db8-4345-baac-e30e56b6937c', 2111, 'sentence_building', 'C1', 'grammar', 'Si hubiera sabido lo del retraso, habría esperado.', 'Had I known about the delay, I would have waited.', '["had", "I", "known", "about", "the", "delay", "would", "have", "waited", "if", "know", "wait"]', NULL, NULL, NULL, NULL, 'Inverted third conditional: "Had I known" replaces "If I had known".', '2026-06-01 07:13:28.516357+00', NULL, NULL, 'en', '{Conditional}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('9e925ecb-345b-42fd-98ff-f52ad08fe501', 1083, 'gap_fill', 'C2', 'business_phrasal_verbs', 'The smaller firm was worried the partnership would allow the larger company to _______ their intellectual property.', 'get hold of', NULL, NULL, NULL, '["walk away with", "take over"]', 'To obtain or acquire — physically or commercially.', 'To get hold of something means to obtain or acquire it, often implying some difficulty or effort involved.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Business phrasal verb"}', false, 'Common in spoken business English.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('47bbf07a-804b-4703-ac81-700806008f16', 1084, 'gap_fill', 'C2', 'business_phrasal_verbs', 'Both parties eventually _______ their entrenched positions and reached a compromise.', 'backed away from', NULL, NULL, NULL, '["moved away from", "stepped back from"]', 'To withdraw from (a position, demand).', 'To back away from a position means to withdraw from it, often under pressure. Similar to step back from or move away from.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Business phrasal verb"}', false, 'The opposite of "doubling down".', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('4be02d5c-f0ac-402e-8028-051e26e6cba3', 1085, 'gap_fill', 'C2', 'business_phrasal_verbs', 'The company''s aggressive pricing strategy is designed to _______ less well-funded competitors.', 'squeeze out', NULL, NULL, NULL, '["drive out", "force out", "push out"]', 'To force out (competitors) by aggressive tactics.', 'To squeeze out competitors means to force them out of the market — typically through price pressure, superior resources, or aggressive tactics.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Business phrasal verb","Business vocabulary"}', false, 'Like pushing toothpaste from a tube.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('f95c692a-c9cb-4a3d-8b50-f564203c3b4e', 1117, 'multiple_choice', 'A1', 'bathroom_vocabulary', 'The material used to fill the gaps between tiles is called _______.', 'grout', '["grout", "sealant", "plaster", "filler"]', NULL, NULL, NULL, 'A cement-like mixture filling the gaps between tiles.', 'Grout is the material that fills the joints between tiles. It is typically cement-based and available in a range of colours. It is applied after the tiles are set.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Bathroom vocabulary","Confusable words"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('5b10f5cd-8db3-474d-8b7b-d5778ddfa059', 1118, 'multiple_choice', 'A1', 'bathroom_vocabulary', 'The flat regularly shaped things we stick to a surface are called _______.', 'tiles', '["glue", "sealant", "grout", "tiles"]', NULL, NULL, NULL, 'Flat squares or rectangles stuck to walls or floors.', 'Tiles in English include tiles for floors, walls, ceilings and any surface. We don''t use different words for different types, but can combine words: floor tiles, ceiling tiles etc. ', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Bathroom vocabulary","Confusable words"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('b9f72d6e-46d9-4347-a5ef-c85669eb2651', 1119, 'multiple_choice', 'A1', 'bathroom_vocabulary', 'Small plastic crosses used to keep equal space between tiles are called tile _______.', 'spacers', '["spacers", "clips", "guides", "holders"]', NULL, NULL, NULL, 'Plastic tools that maintain even spacing — placed between tiles during installation.', 'Tile spacers are small plastic crosses placed between tiles during installation to maintain a consistent joint width before the grout is applied.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Bathroom vocabulary"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('69b7e7cf-f747-464c-8ee7-8f001aa99270', 1120, 'multiple_choice', 'A1', 'bathroom_vocabulary', 'The flat thing we stand on in a shower which collects water is called a _______.', 'shower tray', '["shower tray", "shower trail", "shower train", "shower trae"]', NULL, NULL, NULL, 'The base of a shower that catches water and channels it to a drain.', 'A shower tray micht sometimes also be referred to as only a tray once it is established we are talking about bathrooms.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Bathroom vocabulary"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('749b63e9-74d9-494f-bda1-3cda39c27ef1', 1086, 'gap_fill', 'C2', 'business_vocabulary', 'After the scandal, the PR team worked overtime to _______ the reputational damage as quickly as possible.', 'contain', NULL, NULL, NULL, '["limit", "minimise", "minimise the impact of"]', 'To manage and limit (damage, a problem).', 'To contain damage means to limit it and prevent it from spreading further. Damage containment is a standard term in PR and crisis management.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Business phrasal verb"}', false, 'Like a container holding back a leak.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('09a1c3f0-c179-4f6d-b682-9ac436693372', 1756, 'multiple_choice', 'A2', 'sport', 'Me _____ al gimnasio tres veces a la semana para hacer crossfit.', 'apunto', '["apunto", "voy", "llevo", "salgo"]', NULL, NULL, NULL, NULL, 'Apuntarse al gimnasio (o a una clase) significa registrarse o hacerse socio. También se usa: ir al gimnasio, hacerse miembro, darse de alta. En inglés: to join the gym, to sign up for a class.', '2026-03-30 08:52:38.502672+00', NULL, NULL, 'es', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('90e6894e-e95e-438a-915a-e0180ba9b0be', 1757, 'multiple_choice', 'A2', 'sport', 'Antes de nadar, siempre hago un _____ de diez minutos para no hacerme daño.', 'calentamiento', '["calentamiento", "descanso", "masaje", "estiramiento"]', NULL, NULL, NULL, NULL, 'El calentamiento (warm-up) es el conjunto de ejercicios suaves que se hacen antes de la actividad principal para preparar los músculos y reducir el riesgo de lesión. Lo opuesto es el enfriamiento o vuelta a la calma (cool-down). En inglés: warm-up.', '2026-03-30 08:52:38.502672+00', NULL, NULL, 'es', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('3f39e9d1-d071-407a-9490-b4476fb5c7f3', 1758, 'multiple_choice', 'A2', 'sport', 'El pádel se juega _____ — dos jugadores por equipo.', 'en dobles', '["en dobles", "en equipo", "en grupo", "en solitario"]', NULL, NULL, NULL, NULL, 'El pádel casi siempre se juega en dobles (dos contra dos). También se puede decir en parejas. A veces se juega en individuales (uno contra uno), pero es menos habitual. En inglés: in doubles, in pairs.', '2026-03-30 08:52:38.502672+00', NULL, NULL, 'es', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('1cdf53c5-6025-4ee6-bb71-76a006f26a89', 1759, 'multiple_choice', 'A2', 'sport', 'Después de correr una hora, estaba _____ — no podía moverme del sofá.', 'agotado', '["agotado", "aburrido", "animado", "relajado"]', NULL, NULL, NULL, NULL, 'Agotado/a significa extremadamente cansado, sin energía. Es más intenso que simplemente cansado. Sinónimos: exhausto, sin fuerzas, hecho polvo (coloquial). En inglés: exhausted, drained, shattered (British informal).', '2026-03-30 08:52:38.502672+00', NULL, NULL, 'es', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('3d701d14-ca0a-460e-92a8-455e4bcefc91', 1760, 'multiple_choice', 'A2', 'sport', 'En yoga, la _____ es tan importante como el movimiento — tienes que respirar de forma consciente todo el tiempo.', 'respiración', '["respiración", "postura", "música", "ropa"]', NULL, NULL, NULL, NULL, 'La respiración (breathing) es fundamental en el yoga — cada movimiento se coordina con una inhalación o exhalación. Respirar bien mejora la concentración, la relajación y la ejecución de las posturas. En inglés: breath, breathing, breathwork.', '2026-03-30 08:52:38.502672+00', NULL, NULL, 'es', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('1f83c1c7-9e8c-4fb0-a985-3c54246563dc', 1761, 'multiple_choice', 'A2', 'sport', 'Levanto _____ tres veces por semana para ganar fuerza y tonificar los músculos.', 'pesas', '["pesas", "clases", "proteínas", "series"]', NULL, NULL, NULL, NULL, 'Levantar pesas (to lift weights) es una de las formas más efectivas de desarrollar fuerza muscular. También se dice hacer pesas, entrenar con pesas, o entrenamiento de fuerza. En inglés: weight training, strength training, lifting weights.', '2026-03-30 08:52:38.502672+00', NULL, NULL, 'es', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('100d538d-d182-4373-a5e8-21dea0b0779c', 1762, 'multiple_choice', 'A2', 'sport', 'La clase de spinning _____ a las siete de la mañana — tienes que llegar un poco antes para coger bici.', 'empieza', '["empieza", "termina", "dura", "abre"]', NULL, NULL, NULL, NULL, 'Empezar (to start/begin) es un verbo irregular: empieza (él/ella), empiezo (yo). Se usa para hablar de horarios de clases, entrenamientos y eventos. También se puede decir: la clase es a las siete, la clase comienza a las siete.', '2026-03-30 08:52:38.502672+00', NULL, NULL, 'es', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('64455211-50d0-4f63-b1dc-0572b2d3b252', 1763, 'multiple_choice', 'A2', 'sport', 'Después del entrenamiento, siempre _____ bien para evitar el dolor muscular al día siguiente.', 'me estiro', '["me estiro", "me ducho", "me peso", "me cambio"]', NULL, NULL, NULL, NULL, 'Estirarse (to stretch) es esencial después del ejercicio para reducir la tensión muscular y mejorar la flexibilidad. Es un verbo reflexivo: me estiro, te estiras, se estira. El sustantivo es el estiramiento. En inglés: to stretch, stretching, cool-down stretch.', '2026-03-30 08:52:38.502672+00', NULL, NULL, 'es', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('e51645b1-9e7a-406f-ae52-b3fd5b2cf341', 1764, 'multiple_choice', 'A2', 'sport', 'Corro una hora cada mañana — es mi forma favorita de _____ el estrés del trabajo.', 'liberar', '["liberar", "aumentar", "ignorar", "evitar"]', NULL, NULL, NULL, NULL, 'Liberar el estrés (to release/relieve stress) es una de las razones más comunes para hacer ejercicio. También se dice: desconectar, desestresarse, relajarse. El ejercicio físico libera endorfinas, que mejoran el estado de ánimo. En inglés: to release stress, to relieve stress, to unwind, to decompress.', '2026-03-30 08:52:38.502672+00', NULL, NULL, 'es', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('22ba9955-770d-4634-bc6c-92a9187e1661', 1765, 'multiple_choice', 'A2', 'sport', 'Mi entrenador dice que lo más importante no es la intensidad sino la _____ — hacer ejercicio con regularidad a lo largo del tiempo.', 'constancia', '["constancia", "velocidad", "intensidad", "equipamiento"]', NULL, NULL, NULL, NULL, 'La constancia (consistency) es el principio más importante en cualquier programa de ejercicio. Significa hacer algo de forma regular y sostenida a lo largo del tiempo, aunque algunos días sea poco. Sinónimos: regularidad, disciplina, perseverancia. En inglés: consistency, dedication, perseverance.', '2026-03-30 08:52:38.502672+00', NULL, NULL, 'es', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('a1b0f8dd-329b-4184-a240-b7dff1a147b7', 1854, 'gap_fill', 'A2', 'spanish', 'Después de tanto caminar por la ciudad, _______ sentarme y descansar un momento.', 'necesitaba', NULL, NULL, NULL, NULL, NULL, 'El imperfecto describe una necesidad o estado en un momento del pasado.', '2026-04-06 16:43:51.906934+00', NULL, NULL, 'es', '{Spanish}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('beaf4c35-6085-4c32-b9ca-bb1421760ecd', 1124, 'multiple_choice', 'A2', 'bathroom_vocabulary', 'A _______ finish on a tile reflects light and appears shiny.', 'glossy', '["glossy", "matte", "satin", "textured"]', NULL, NULL, NULL, 'Shiny and reflective — opposite of matte.', 'A glossy finish reflects light and gives tiles a shiny appearance. It is popular for walls but can be slippery underfoot, making it less suitable for floor applications in wet areas.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Bathroom vocabulary","Confusable words"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('f5ba8790-2ffe-4755-9ac7-5fee6f9ea3f3', 1777, 'multiple_choice', 'B1', 'travel', 'What is a "connecting flight"?', 'a second flight you take after landing at an intermediate airport', '["a second flight you take after landing at an intermediate airport", "a flight shared between two airlines", "a flight that connects two nearby cities", "a direct flight with no stops"]', NULL, NULL, NULL, 'A second flight that "connects" you onwards from the first one''s arrival airport.', 'A connecting flight is the onward flight you take after a layover at an intermediate airport. If your first flight is delayed and you miss your connection, the airline is usually responsible for rebooking you. A tight connection means you have very little time to change planes — always check the minimum connection time before booking.', '2026-03-30 09:41:12.599621+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('726d7885-f334-492c-b54e-34ebc2b59901', 1778, 'multiple_choice', 'B1', 'travel', 'What does it mean to "go backpacking"?', 'to travel independently on a low budget, staying in hostels and carrying your belongings in a rucksack', '["to travel independently on a low budget, staying in hostels and carrying your belongings in a rucksack", "to go hiking in the mountains with a large backpack", "to travel by coach across multiple countries", "to take a guided tour of a region"]', NULL, NULL, NULL, 'Travelling cheaply with everything you need carried on your back, often staying in hostels.', 'Backpacking describes a style of independent, budget travel where travellers carry everything in a backpack and move between destinations flexibly. It is popular among young travellers and gap-year students. Compare: package holiday (everything pre-arranged), luxury travel, slow travel (spending longer in fewer places).', '2026-03-30 09:41:12.599621+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('b454e7f0-e825-4ece-be2d-524cffeca2d3', 1779, 'multiple_choice', 'B2', 'travel', 'What does "travel on a budget" mean?', 'to travel while spending as little money as possible', '["to travel while spending as little money as possible", "to plan a trip with a fixed total cost", "to use a travel agent to book in advance", "to travel only during off-peak periods"]', NULL, NULL, NULL, 'A budget = a financial limit. Travelling within or below that limit.', 'Travelling on a budget means minimising expenses — choosing cheap accommodation, cooking your own food, using public transport, and looking for free attractions. Budget travel has been transformed by the internet, which makes it easy to compare prices, find last-minute deals, and book directly. Compare: luxury travel, backpacking, slow travel.', '2026-03-30 09:41:12.599621+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('8f95b1c3-12d0-4834-95ee-cf8c1b190e62', 2050, 'error_correction', 'A2', 'grammar', 'She don''t like coffee in the morning.', 'She doesn''t like coffee in the morning.', '[]', NULL, NULL, NULL, NULL, 'With "he/she/it" in the present simple, the negative auxiliary is "doesn''t", not "don''t".', '2026-06-01 07:05:45.329436+00', NULL, NULL, 'en', '{"Auxiliary verb"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('2a25297e-8f24-4099-80f4-7a8c7057d916', 2051, 'error_correction', 'A2', 'grammar', 'They was waiting for the bus when it started to rain.', 'They were waiting for the bus when it started to rain.', '[]', NULL, NULL, NULL, NULL, '"They" takes "were" in the past continuous, not "was" — the verb must agree with the plural subject.', '2026-06-01 07:05:45.329436+00', NULL, NULL, 'en', '{Agreement}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('b4968431-a3b7-4c3d-ba62-7926775cbffd', 2052, 'error_correction', 'A2', 'grammar', 'I have went to the dentist yesterday.', 'I went to the dentist yesterday.', '[]', NULL, NULL, NULL, NULL, '"Yesterday" marks finished past time, so we use the past simple "went", not the present perfect "have went".', '2026-06-01 07:05:45.329436+00', NULL, NULL, 'en', '{Tense}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('f0df5730-ede7-4fd3-8af2-5abc7e3386ee', 2053, 'error_correction', 'A2', 'grammar', 'He can to swim very well.', 'He can swim very well.', '[]', NULL, NULL, NULL, NULL, 'After a modal verb like "can", we use the bare infinitive — "can swim", never "can to swim".', '2026-06-01 07:05:45.329436+00', NULL, NULL, 'en', '{"Modal verb"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('0ba1a828-63d3-4179-938b-8687f08f3aed', 2054, 'error_correction', 'A2', 'grammar', 'We didn''t went to the party last night.', 'We didn''t go to the party last night.', '[]', NULL, NULL, NULL, NULL, 'After the auxiliary "didn''t", the main verb stays in its base form: "didn''t go", not "didn''t went".', '2026-06-01 07:05:45.329436+00', NULL, NULL, 'en', '{"Auxiliary verb"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('26ac8335-007d-4fdf-bb3d-d62d5df164d0', 2055, 'error_correction', 'A2', 'grammar', 'Does she likes her new job?', 'Does she like her new job?', '[]', NULL, NULL, NULL, NULL, 'In a question with "does", the main verb has no -s: "Does she like…?", not "likes".', '2026-06-01 07:05:45.329436+00', NULL, NULL, 'en', '{"Auxiliary verb"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('e1ec18ef-3cce-407b-b9b3-fc35a7f13565', 2056, 'error_correction', 'A2', 'grammar', 'My brother have two cats and a dog.', 'My brother has two cats and a dog.', '[]', NULL, NULL, NULL, NULL, '"My brother" is third-person singular, so it takes "has", not "have".', '2026-06-01 07:05:45.329436+00', NULL, NULL, 'en', '{Agreement}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('86911d75-eafb-4a5e-8b14-bc06a7ec82aa', 2057, 'error_correction', 'A2', 'grammar', 'You must to wear a seatbelt in the car.', 'You must wear a seatbelt in the car.', '[]', NULL, NULL, NULL, NULL, '"Must" is a modal, so it is followed by the bare infinitive — "must wear", not "must to wear".', '2026-06-01 07:05:45.329436+00', NULL, NULL, 'en', '{"Modal verb"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('a9b818ca-ecf2-48de-9769-f154c5b16951', 2058, 'error_correction', 'A2', 'grammar', 'There is many people at the station today.', 'There are many people at the station today.', '[]', NULL, NULL, NULL, NULL, '"Many people" is plural, so the verb is "are", not "is".', '2026-06-01 07:05:45.329436+00', NULL, NULL, 'en', '{Agreement}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('36d1df57-2cfd-4490-96b4-bd2d67d3a5a4', 2059, 'error_correction', 'A2', 'grammar', 'I am living here since 2019.', 'I have lived here since 2019.', '[]', NULL, NULL, NULL, NULL, 'With "since 2019" we use the present perfect "have lived" to link past to present, not the present continuous.', '2026-06-01 07:05:45.329436+00', NULL, NULL, 'en', '{Tense}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('9c0fa5e7-d5b2-4331-b614-e15e5f55507d', 2060, 'error_correction', 'B2', 'grammar', 'By the time we arrived, the film had already start.', 'By the time we arrived, the film had already started.', '[]', NULL, NULL, NULL, NULL, 'The past perfect needs the past participle: "had already started", not "had already start".', '2026-06-01 07:05:45.329436+00', NULL, NULL, 'en', '{Tense}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('17fdb00f-d691-4ce0-ba76-a59dece9cc22', 2061, 'error_correction', 'B2', 'grammar', 'If I would have known, I would have called you.', 'If I had known, I would have called you.', '[]', NULL, NULL, NULL, NULL, 'In a third conditional, the "if" clause uses the past perfect "had known", never "would have".', '2026-06-01 07:05:45.329436+00', NULL, NULL, 'en', '{Conditional}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('a861a5ed-61be-4b61-a59d-695f6e238e76', 2062, 'error_correction', 'B2', 'grammar', 'She must be forgotten about the meeting.', 'She must have forgotten about the meeting.', '[]', NULL, NULL, NULL, NULL, 'To deduce about the past we use "must have + past participle": "must have forgotten", not "must be forgotten".', '2026-06-01 07:05:45.329436+00', NULL, NULL, 'en', '{"Modal verb"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('582556e9-1996-4063-803b-adbe39c625a6', 2063, 'error_correction', 'B2', 'grammar', 'I look forward to hear from you soon.', 'I look forward to hearing from you soon.', '[]', NULL, NULL, NULL, NULL, 'Here "to" is a preposition, so it is followed by the -ing form: "look forward to hearing".', '2026-06-01 07:05:45.329436+00', NULL, NULL, 'en', '{Gerund}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('d833ca15-af6d-42df-ad87-24c9a69ef992', 2064, 'error_correction', 'B2', 'grammar', 'He''s been working here for he left university.', 'He''s been working here since he left university.', '[]', NULL, NULL, NULL, NULL, '"Since" introduces a point in time ("since he left"); "for" would need a length of time.', '2026-06-01 07:05:45.329436+00', NULL, NULL, 'en', '{"Preposition of time"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('204fd6de-f4ae-4ee6-8994-6da5cdc46972', 1125, 'multiple_choice', 'A2', 'bathroom_vocabulary', 'The thing which we look in to see ourselves is called a _______.', 'mirror', '["mirror", "reflection", "reflective", "miror"]', NULL, NULL, NULL, 'A reflective surface — what you check yourself in.', 'Mirrors come in many shpes and sizes, and sometimes we combine words to describe them: full-length mirror, fitted mirror etc. ', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Bathroom vocabulary","Confusable words"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('5bf556b3-29f5-4d71-81a1-dbf5fe009e7b', 1781, 'gap_fill', 'B1', 'travel', 'We arrived at the airport with plenty of time to _____ before the flight.', 'check in', NULL, NULL, NULL, '[{"answer": "spare", "feedback": "Yes, ''time to spare'' means having extra or surplus time — a natural idiomatic fit."}, {"answer": "get through security", "feedback": "Yes, getting through security is one of the main things you do at the airport before a flight."}, {"answer": "board", "feedback": "Yes, ''board'' works too — though you usually board at the gate rather than at the airport generally."}, {"answer": "relax", "feedback": "Yes, ''relax'' fits — plenty of travellers do exactly that before their flight."}]', 'The first thing you do when you arrive at the airport — register for your flight and drop off your bags.', 'Check in at an airport means to register for your flight, show your passport and booking, drop off any hold luggage, and receive your boarding pass. You can check in online (usually 24–48 hours before departure) or at the airport. Compare: check in to a hotel (to register at reception on arrival), check out (to pay and leave).', '2026-03-30 09:41:12.599621+00', NULL, NULL, 'en', '{}', false, 'Two-word verb (not the hyphenated noun). Starts with c___ i___.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('11c53075-07e0-424c-8b08-8f62f8eadc12', 1796, 'multiple_choice', 'A2', 'travel', 'En el aeropuerto, ¿dónde facturas el equipaje antes de subir al avión?', 'en el mostrador de facturación', '["en el mostrador de facturación", "en la puerta de embarque", "en la recogida de equipajes", "en la aduana"]', NULL, NULL, NULL, NULL, 'El mostrador de facturación (check-in desk) es donde registras tu vuelo, depositas las maletas grandes y recibes la tarjeta de embarque. La puerta de embarque es donde subes al avión. La recogida de equipajes es donde recoges las maletas al llegar. La aduana es donde los oficiales comprueban lo que traes al país.', '2026-03-30 09:41:12.599621+00', NULL, NULL, 'es', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('f1639d5f-d01a-4ab3-9624-f526b71c14e4', 1797, 'multiple_choice', 'A2', 'travel', '¿Qué significa "vuelo sin escalas"?', 'un vuelo directo que no para en ningún aeropuerto intermedio', '["un vuelo directo que no para en ningún aeropuerto intermedio", "un vuelo muy corto", "un vuelo nocturno", "un vuelo de bajo coste"]', NULL, NULL, NULL, NULL, 'Un vuelo sin escalas (non-stop flight) va directamente del origen al destino sin parar. Un vuelo con escala para en un aeropuerto intermedio — a veces solo para repostar, otras veces para cambiar de avión. Conocer esta diferencia es muy útil al reservar billetes.', '2026-03-30 09:41:12.599621+00', NULL, NULL, 'es', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('fa21ac76-d2c3-45e5-970b-e3a53d5a580b', 1798, 'multiple_choice', 'A2', 'travel', '¿Qué es el "equipaje de mano"?', 'la bolsa o mochila pequeña que llevas contigo en el avión', '["la bolsa o mochila pequeña que llevas contigo en el avión", "la maleta grande que facturan en bodega", "el equipaje que llega dañado", "la etiqueta que ponen en la maleta"]', NULL, NULL, NULL, NULL, 'El equipaje de mano (hand luggage / carry-on) es el que llevas en la cabina del avión contigo. Tiene límites de tamaño y peso según la aerolínea. El equipaje facturado (checked luggage) va en la bodega del avión. Es importante consultar las restricciones de cada compañía antes de viajar.', '2026-03-30 09:41:12.599621+00', NULL, NULL, 'es', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('a422ede9-a16e-47f5-9af4-5938b2961674', 1799, 'multiple_choice', 'A2', 'travel', '¿Qué haces cuando "haces el check-out" en un hotel?', 'pagas la cuenta y dejas la habitación al final de tu estancia', '["pagas la cuenta y dejas la habitación al final de tu estancia", "te registras en la recepción al llegar", "reservas una habitación por internet", "pides el desayuno a la habitación"]', NULL, NULL, NULL, NULL, 'Hacer el check-out (salida) es el proceso de pagar la cuenta y entregar la llave al final de tu estancia. Normalmente se hace antes del mediodía. El check-in (llegada) es el proceso contrario — registrarte al llegar. En inglés también se usa to check out y to check in como verbos.', '2026-03-30 09:41:12.599621+00', NULL, NULL, 'es', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('66db0ac9-b593-4b6f-854d-0a553960882c', 1800, 'multiple_choice', 'A2', 'travel', '¿Qué significa que un vuelo está "retrasado"?', 'el vuelo sale más tarde de lo previsto', '["el vuelo sale más tarde de lo previsto", "el vuelo ha sido cancelado", "el avión ha aterrizado antes de tiempo", "el vuelo está completo"]', NULL, NULL, NULL, NULL, 'Retrasado (delayed) significa que el vuelo sale o llega más tarde de la hora prevista. Si el retraso es significativo, los pasajeros tienen derechos como comida, bebida o alojamiento dependiendo de la duración. Un vuelo cancelado (cancelled) no sale en absoluto. Es importante conocer tus derechos como pasajero.', '2026-03-30 09:41:12.599621+00', NULL, NULL, 'es', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('d0c8f538-ab46-479d-bc6d-b3601b1938a5', 1801, 'multiple_choice', 'A2', 'travel', '¿Qué es un "albergue"?', 'un alojamiento económico con habitaciones compartidas, popular entre viajeros jóvenes', '["un alojamiento económico con habitaciones compartidas, popular entre viajeros jóvenes", "un hotel de lujo", "un apartamento turístico", "una pensión familiar"]', NULL, NULL, NULL, NULL, 'Un albergue (hostel) es un tipo de alojamiento barato donde los viajeros comparten habitaciones y zonas comunes. Es muy popular entre mochileros y viajeros jóvenes. En inglés se llama hostel. Una pensión es una alternativa más privada y familiar. Un parador es un tipo de hotel de lujo típico español, a menudo en edificios históricos.', '2026-03-30 09:41:12.599621+00', NULL, NULL, 'es', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('5851afa4-ef5f-4628-9fbf-c35985c29164', 1802, 'multiple_choice', 'A2', 'travel', '¿Qué necesitas para entrar en la mayoría de los países extranjeros?', 'el pasaporte', '["el pasaporte", "el carné de conducir", "la tarjeta sanitaria", "el DNI"]', NULL, NULL, NULL, NULL, 'El pasaporte (passport) es el documento oficial que permite viajar a otros países. El DNI (Documento Nacional de Identidad) sirve para viajar dentro de la Unión Europea, pero no para países fuera de ella. Algunos países también requieren un visado (visa) — un permiso especial para entrar. Siempre comprueba los requisitos antes de viajar.', '2026-03-30 09:41:12.599621+00', NULL, NULL, 'es', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('51f4df2f-3e4c-403b-9d2b-5ba545f872bb', 1803, 'multiple_choice', 'A2', 'travel', '¿Qué es el "seguro de viaje"?', 'una póliza que te protege si algo sale mal durante el viaje', '["una póliza que te protege si algo sale mal durante el viaje", "el precio total del viaje", "un descuento para viajeros frecuentes", "una tarjeta de fidelidad de una aerolínea"]', NULL, NULL, NULL, NULL, 'El seguro de viaje (travel insurance) cubre imprevistos como cancelaciones, pérdida de equipaje, asistencia médica en el extranjero, y retrasos. Es muy recomendable contratarlo antes de cualquier viaje. En inglés: to take out travel insurance (contratar un seguro de viaje). Sin seguro, los gastos médicos en el extranjero pueden ser muy elevados.', '2026-03-30 09:41:12.599621+00', NULL, NULL, 'es', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('d9b0b67b-e4cf-48a3-90bf-24bf1602b6aa', 1815, 'multiple_choice', 'A2', 'spanish', '¿Cuál es la comparación correcta?', 'Este hotel es más cómodo que el otro', '["Este hotel es más cómodo que el otro", "Este hotel es más cómodo de el otro", "Este hotel es más cómodo que el otro es", "Este hotel es mayor cómodo que el otro"]', NULL, NULL, NULL, NULL, 'La comparación de superioridad: más + adjetivo + que. Nunca "de el" cuando se comparan dos elementos directamente.', '2026-04-06 16:43:09.309376+00', NULL, NULL, 'es', '{Spanish}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('4617cab3-d8f8-4273-97c4-29b8c3dfa8eb', 1804, 'multiple_choice', 'A2', 'travel', '¿Qué significa "temporada alta" en el contexto del turismo?', 'el período del año en que hay más turistas y los precios son más altos', '["el período del año en que hay más turistas y los precios son más altos", "la época con el mejor clima del año", "el período con los vuelos más baratos", "la temporada de descuentos en hoteles"]', NULL, NULL, NULL, NULL, 'La temporada alta (peak season) es cuando un destino recibe más visitantes — generalmente en verano o durante las vacaciones. Los precios de vuelos y hoteles son más caros. La temporada baja (low season) o temporada media (shoulder season) ofrecen precios más bajos y menos aglomeraciones. Viajar fuera de temporada alta puede ser más económico y agradable.', '2026-03-30 09:41:12.599621+00', NULL, NULL, 'es', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('fb20ad9f-4ac5-4c56-a84d-07e0e3e2b254', 1805, 'multiple_choice', 'A2', 'travel', '¿Qué es un "itinerario" de viaje?', 'un plan detallado con las fechas, destinos y actividades del viaje', '["un plan detallado con las fechas, destinos y actividades del viaje", "el billete de avión", "la guía turística de un destino", "el mapa de una ciudad"]', NULL, NULL, NULL, NULL, 'Un itinerario de viaje es el plan que detalla cada etapa del viaje — fechas, vuelos, hoteles, actividades y traslados. Las agencias de viajes y las plataformas de reservas online generan itinerarios automáticamente. En inglés se usa la misma palabra: itinerary. Tener un buen itinerario ayuda a organizar el tiempo y evitar imprevistos.', '2026-03-30 09:41:12.599621+00', NULL, NULL, 'es', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('d3668d9a-ba33-4dc2-be92-4c2c9969a559', 1774, 'multiple_choice', 'A1', 'travel', 'What do you call the person who carries your bags at a hotel?', 'a porter', '["a valet", "a concierge", "a porter", "a buttons"]', NULL, NULL, NULL, 'From the Latin "portare" — to carry. The hotel staff member who carries your luggage.', 'A porter carries guests'' luggage in a hotel. In American English the same role is called a bellboy or bellhop. In Spain, hotel porters were historically called a buttons. A concierge helps with bookings and recommendations. A valet parks cars or assists with personal care.', '2026-03-30 09:41:12.599621+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('04635165-21fc-45de-b9a0-046a24ab735b', 1791, 'gap_fill', 'C2', 'travel', 'The resort''s marketing relied heavily on _____ — the idea that guests were not merely booking a holiday, but purchasing a transformation of self.', 'aspiration', NULL, NULL, NULL, '[{"answer": "hype", "feedback": "Hype is close — it captures the inflated, image-driven nature of the marketing. The precise word here is aspiration, which implies the deeper idea of selling a better version of yourself."}, {"answer": "image", "feedback": "Image is a reasonable answer — luxury brands do sell an image. The more specific word here is aspiration, which goes a step further: not just an image, but the desire to transform yourself."}]', 'A strong desire or hope — what people aim for, often beyond their current reality.', 'Aspiration refers to a strong desire to achieve something better — a higher social status, a different life, or personal transformation. Luxury travel marketing frequently appeals to aspiration rather than the practical features of a destination. Related: aspirational (adjective), aspirationally priced (priced to suggest exclusivity without being truly unaffordable).', '2026-03-30 09:41:12.599621+00', NULL, NULL, 'en', '{}', false, 'Single word. Starts with a___.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('0bd8542d-d05a-45b7-9b67-f6739cdb2429', 1126, 'multiple_choice', 'A2', 'bathroom_vocabulary', 'The thing we put our towels on is called a towel _______.', 'rail', '["rule", "rail", "rale", "rile"]', NULL, NULL, NULL, 'A horizontal bar for hanging towels.', 'Towel rails are put close to baths, showers and basins to keep towels ''handy'', where we need them. Often now bathrooms have ''heated towel rails''. ', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Bathroom vocabulary"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('c9344932-e05e-44e6-b11c-2775122c213d', 1807, 'multiple_choice', 'A2', 'spanish', '¿Cuál de estas frases es correcta?', 'La puerta está abierta', '["La puerta está abierta", "La puerta es abierta", "La puerta está abierto", "La puerta es abierto"]', NULL, NULL, NULL, NULL, 'Con participios que describen estados resultantes de una acción usamos "estar", y el participio concuerda con el sustantivo.', '2026-04-06 16:43:09.309376+00', NULL, NULL, 'es', '{Spanish}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('9a405283-1ba0-45f6-a45d-d59ead80f57e', 1808, 'multiple_choice', 'A2', 'spanish', '¿Cuál es la forma correcta? "Ayer _____ mucho calor en Madrid."', 'hizo', '["hizo", "hacía", "ha hecho", "hace"]', NULL, NULL, NULL, NULL, 'Para hablar del tiempo en un momento concreto y terminado del pasado, usamos el pretérito indefinido. Hacer → hizo.', '2026-04-06 16:43:09.309376+00', NULL, NULL, 'es', '{Spanish}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('31ee1a6a-5479-4df6-94af-c1abca3d1a93', 1809, 'multiple_choice', 'A2', 'spanish', '"¿Has visto mi móvil?" "Sí, _____ vi encima de la mesa del salón."', 'lo', '["lo", "le", "la", "se"]', NULL, NULL, NULL, NULL, '"Lo" sustituye a un objeto directo masculino. El móvil es masculino, así que usamos "lo".', '2026-04-06 16:43:09.309376+00', NULL, NULL, 'es', '{Spanish}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('09b8a18b-d094-41f6-b895-4a10321f7289', 1810, 'multiple_choice', 'A2', 'spanish', '¿Cuál de estas frases usa "para" correctamente?', 'Estudio español para comunicarme mejor', '["Estudio español para comunicarme mejor", "Gracias para tu ayuda", "Salí para las diez de la noche", "Lo hizo para que llovía"]', NULL, NULL, NULL, NULL, '"Para" expresa finalidad o propósito. "Gracias por" (not para). "Salí a las diez" (use "a" for time).', '2026-04-06 16:43:09.309376+00', NULL, NULL, 'es', '{Spanish}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('f4505806-6d48-4902-9f7d-d6f5391c9f07', 1059, 'multiple_choice', 'A1', 'business_phrasal_verbs', 'Please _______ the form completely before you submit your application.', 'fill in', '["fill in", "fill up", "fill through", "fill over"]', NULL, NULL, NULL, 'To complete a form — write in the blanks.', 'To fill in (or fill out) a form means to complete it by writing all the required information. Both are correct — fill out is more common in American English.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Business phrasal verb"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('d14b3ba2-8f0a-4e17-be4c-b379547093c7', 1100, 'multiple_choice', 'B2', 'business_vocabulary', 'After three consecutive years of losses, the company was declared _______.', 'insolvent', '["insolvent", "bankrupt", "illiquid", "indebted"]', NULL, NULL, NULL, 'Unable to pay debts — but it''s the formal/technical term, not the everyday one.', 'Insolvent means unable to pay debts as they fall due. Bankrupt is the legal status that follows — when a court formally declares insolvency. Both are acceptable answers here.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Business vocabulary","Financial vocabulary","Confusable words"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('c565ef82-c4cc-41f5-be1b-bef743fcbac4', 1816, 'multiple_choice', 'A2', 'spanish', '¿Cuál es la frase correcta?', 'El restaurante que te recomendé está muy bien', '["El restaurante que te recomendé está muy bien", "El restaurante quien te recomendé está muy bien", "El restaurante cual te recomendé está muy bien", "El restaurante qué te recomendé está muy bien"]', NULL, NULL, NULL, NULL, 'Para cosas, usamos el pronombre relativo "que". "Quien" se reserva para personas.', '2026-04-06 16:43:09.309376+00', NULL, NULL, 'es', '{Spanish}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('7e4d6b20-341e-49f1-b2d0-c37d2983e025', 1817, 'multiple_choice', 'A2', 'spanish', '¿Qué expresa "Tienes que descansar más"?', 'una obligación o necesidad', '["una obligación o necesidad", "un deseo personal", "una posibilidad", "una sugerencia muy educada"]', NULL, NULL, NULL, NULL, '"Tener que + infinitivo" expresa obligación personal. Es más directo que "debería" (consejo) o "poder" (posibilidad).', '2026-04-06 16:43:09.309376+00', NULL, NULL, 'es', '{Spanish}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('18b043f6-9e86-4540-8c77-5da4fb6a52d1', 1818, 'multiple_choice', 'A2', 'spanish', '¿Cuál de estas frases describe una acción que ocurre ahora mismo?', 'Está estudiando para el examen', '["Está estudiando para el examen", "Estudia para el examen", "Estudió para el examen", "Ha estudiado para el examen"]', NULL, NULL, NULL, NULL, '"Estar + gerundio" describe una acción en progreso en el momento en que se habla.', '2026-04-06 16:43:09.309376+00', NULL, NULL, 'es', '{Spanish}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('9f4037d5-a5cd-4b12-8811-6f3d81b773bf', 1819, 'multiple_choice', 'A2', 'spanish', '¿Cuál es el participio pasado de "escribir"?', 'escrito', '["escrito", "escribido", "escribto", "escribiendo"]', NULL, NULL, NULL, NULL, '"Escribir" tiene participio irregular: escrito. Otros irregulares frecuentes: volver → vuelto, poner → puesto, hacer → hecho.', '2026-04-06 16:43:09.309376+00', NULL, NULL, 'es', '{Spanish}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('37552f18-6811-4a09-ac38-08bfa430fcf6', 1820, 'multiple_choice', 'A2', 'spanish', '¿Cuál de estas frases es correcta?', 'El museo está en el centro de la ciudad', '["El museo está en el centro de la ciudad", "El museo es en el centro de la ciudad", "El museo está siendo en el centro", "El museo es situado en el centro"]', NULL, NULL, NULL, NULL, 'Para indicar la ubicación de personas, cosas y lugares usamos "estar", no "ser".', '2026-04-06 16:43:09.309376+00', NULL, NULL, 'es', '{Spanish}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('883a374e-023a-4727-bd1e-c7d6503d4641', 1821, 'multiple_choice', 'A2', 'spanish', '¿En qué orden va de más frecuente a menos frecuente?', 'siempre, normalmente, a veces, nunca', '["siempre, normalmente, a veces, nunca", "nunca, a veces, normalmente, siempre", "a veces, siempre, nunca, normalmente", "normalmente, nunca, siempre, a veces"]', NULL, NULL, NULL, NULL, 'La escala de frecuencia: siempre (100%) > normalmente > a veces > casi nunca > nunca (0%).', '2026-04-06 16:43:09.309376+00', NULL, NULL, 'es', '{Spanish}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('d10c6b40-bf0c-437e-bf32-de5527411e84', 1822, 'multiple_choice', 'A2', 'spanish', '¿Cuál de estas palabras NO describe un estado de ánimo?', 'estrecho', '["estrecho", "enfadado", "triste", "contento"]', NULL, NULL, NULL, NULL, '"Estrecho" significa narrow/tight y describe una dimensión física, no un estado emocional.', '2026-04-06 16:43:09.309376+00', NULL, NULL, 'es', '{Spanish}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('ed9961f7-8bb1-4902-b582-b9272b35f2f3', 1823, 'multiple_choice', 'A2', 'spanish', '¿Cuál es la forma correcta? "La boda _____ el año pasado en un pueblo cerca de Sevilla."', 'fue', '["fue", "era", "ha sido", "es"]', NULL, NULL, NULL, NULL, 'Para eventos puntuales con tiempo definido ("el año pasado"), usamos el pretérito indefinido. Ser → fue.', '2026-04-06 16:43:09.309376+00', NULL, NULL, 'es', '{Spanish}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('5d94fb89-7ba1-4dbf-8663-3b354aa67e54', 1824, 'multiple_choice', 'A2', 'spanish', '¿Cuál de estas palabras describe un espacio con mucha luz y mucho sitio?', 'amplio', '["amplio", "estrecho", "oscuro", "ruidoso"]', NULL, NULL, NULL, NULL, '"Amplio" = spacious/wide. "Estrecho" = narrow. "Oscuro" = dark. "Ruidoso" = noisy.', '2026-04-06 16:43:09.309376+00', NULL, NULL, 'es', '{Spanish}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('98f490d9-3bd4-43bd-a501-13825438f3f2', 1825, 'multiple_choice', 'A2', 'spanish', '¿Qué expresa "Deberías comer más verdura"?', 'un consejo o recomendación', '["un consejo o recomendación", "una orden directa", "una prohibición", "una predicción del futuro"]', NULL, NULL, NULL, NULL, '"Deber en condicional (debería) + infinitivo" da consejos de forma educada. "Debes" sería más directo.', '2026-04-06 16:43:09.309376+00', NULL, NULL, 'es', '{Spanish}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('823ef0fc-0b57-4cc5-8537-d07e16035b93', 1826, 'multiple_choice', 'A2', 'spanish', '¿Cuál es el significado de "Llevo tres horas esperando el autobús"?', 'He estado esperando el autobús durante tres horas', '["He estado esperando el autobús durante tres horas", "Esperé el autobús hace tres horas", "Voy a esperar tres horas más", "Espero el autobús tres horas cada día"]', NULL, NULL, NULL, NULL, '"Llevar + tiempo + gerundio" indica la duración de una acción que empezó en el pasado y continúa ahora.', '2026-04-06 16:43:09.309376+00', NULL, NULL, 'es', '{Spanish}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('cf0f9068-45a0-4396-8abf-dcf92d5926ce', 1827, 'multiple_choice', 'A2', 'spanish', '¿Cuál es la diferencia principal entre "ir" y "venir"?', 'ir = alejarse del hablante; venir = acercarse al hablante', '["ir = alejarse del hablante; venir = acercarse al hablante", "ir = en transporte; venir = a pie", "ir = formal; venir = informal", "No hay ninguna diferencia en el uso cotidiano"]', NULL, NULL, NULL, NULL, '"Ir" indica movimiento hacia otro lugar. "Venir" implica movimiento hacia donde está el hablante.', '2026-04-06 16:43:09.309376+00', NULL, NULL, 'es', '{Spanish}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('84a3e2c1-fbd3-4385-991d-a609cc7cb200', 1828, 'multiple_choice', 'A2', 'spanish', '¿Cuál de estas frases usa el imperfecto para describir el contexto de una situación pasada?', 'La sala estaba llena de gente cuando llegamos', '["La sala estaba llena de gente cuando llegamos", "Llegamos al hotel a las nueve", "Pedimos dos habitaciones dobles", "El tren salió con una hora de retraso"]', NULL, NULL, NULL, NULL, 'El imperfecto describe el ambiente o estado en que se encontraba algo en un momento del pasado.', '2026-04-06 16:43:09.309376+00', NULL, NULL, 'es', '{Spanish}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('c8ad5a05-8691-4a86-a43d-90d4a17bc300', 1829, 'multiple_choice', 'A2', 'spanish', '¿Cuál de estas expresiones introduce una opinión personal?', 'En mi opinión, este barrio es muy tranquilo', '["En mi opinión, este barrio es muy tranquilo", "El barrio tiene cinco parques", "El barrio fue construido en los años 60", "El barrio está al norte de la ciudad"]', NULL, NULL, NULL, NULL, '"En mi opinión", "Creo que", "Me parece que" son expresiones para introducir opiniones personales.', '2026-04-06 16:43:09.309376+00', NULL, NULL, 'es', '{Spanish}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('f211da17-fe84-4759-97f1-06636c649af8', 1830, 'multiple_choice', 'A2', 'spanish', '¿Cuál es la frase correcta?', 'No tengo ningún problema', '["No tengo ningún problema", "No tengo ninguno problema", "Tengo ningún problema", "No tengo ningún problemas"]', NULL, NULL, NULL, NULL, '"Ningún" va antes de un sustantivo masculino singular. La oración negativa lleva "no" antes del verbo.', '2026-04-06 16:43:09.309376+00', NULL, NULL, 'es', '{Spanish}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('1d777a8a-f9d8-494b-aa1c-b06647516bfc', 1831, 'multiple_choice', 'A2', 'spanish', '¿Cuándo usamos "conocer" en lugar de "saber"?', 'Para hablar de personas, lugares o cosas con los que estamos familiarizados', '["Para hablar de personas, lugares o cosas con los que estamos familiarizados", "Para hablar de hechos o habilidades que hemos aprendido", "Para hablar del pasado exclusivamente", "Para hacer preguntas formales"]', NULL, NULL, NULL, NULL, 'Conocer = estar familiarizado con (personas, lugares, cosas). Saber = tener conocimiento de hechos o habilidades.', '2026-04-06 16:43:09.309376+00', NULL, NULL, 'es', '{Spanish}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('fbc90041-1cbc-4c91-b992-e2167968f2d8', 1127, 'multiple_choice', 'B1', 'bathroom_vocabulary', 'Tiles made from clay fired at very high temperatures, making them very dense and water-resistant, are called _______ tiles.', 'porcelain', '["porcelain", "ceramic", "terracotta", "marble"]', NULL, NULL, NULL, 'A high-quality ceramic — fired at very high temperatures.', 'Porcelain tiles are fired at higher temperatures than ceramic tiles, making them denser, harder, and more water-resistant. They are ideal for wet areas and high-traffic floors.', '2026-03-11 18:12:09.553883+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('27c60fb1-9f1b-41ee-9c9e-187f82767871', 1811, 'multiple_choice', 'A2', 'spanish', '¿Cuál es la frase correcta?', 'Me duele la barriga', '["Me duele la barriga", "Me duele las barrigas", "Me duelen la barriga", "Duelo la barriga"]', NULL, NULL, NULL, NULL, '"Doler" funciona como "gustar": me duele (singular) con un sustantivo singular. El sujeto real es "la barriga".', '2026-04-06 16:43:09.309376+00', NULL, NULL, 'es', '{Spanish}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('60a2a33d-cb82-4d96-838a-75999e79bf91', 1857, 'sentence_auction', 'A1', 'grammar', 'Theme: Past simple — regular -ed verbs', 'auction', '[{"correct": true, "sentence": "She worked in a hotel last summer.", "explanation": "Correct! work → worked — a regular past simple."}, {"correct": false, "sentence": "He plaied football yesterday.", "explanation": "Wrong — the correct spelling is ''played''. When a verb ends in vowel + y, just add -d: play → played."}, {"correct": true, "sentence": "We watched a great film on Friday.", "explanation": "Correct! watch → watched — a regular -ed ending."}, {"correct": false, "sentence": "They stoped at the traffic lights.", "explanation": "Wrong — stop ends in consonant-vowel-consonant, so double the final consonant: stopped."}, {"correct": true, "sentence": "I visited my grandmother last week.", "explanation": "Correct! visit → visited — a regular past simple."}, {"correct": false, "sentence": "She droped her keys on the floor.", "explanation": "Wrong — drop ends in consonant-vowel-consonant, so double the final p: dropped."}]', NULL, NULL, NULL, NULL, NULL, '2026-04-07 18:43:55.499559+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('77493b51-05df-4a9b-9deb-46e4bdb8d905', 1858, 'sentence_auction', 'A2', 'grammar', 'Theme: Comparative adjectives — -er or more?', 'auction', '[{"correct": true, "sentence": "The new café is cheaper than the old one.", "explanation": "Correct! Short adjective: cheap → cheaper."}, {"correct": false, "sentence": "This exercise is more easy than the last one.", "explanation": "Wrong — easy takes -ier, not more: easier."}, {"correct": true, "sentence": "The city centre is more exciting than the suburbs.", "explanation": "Correct! Long adjective (3+ syllables): use more + adjective."}, {"correct": false, "sentence": "He is more tall than his brother.", "explanation": "Wrong — short one-syllable adjectives take -er: taller."}, {"correct": true, "sentence": "My new phone is better than my old one.", "explanation": "Correct! Good is irregular: better."}, {"correct": false, "sentence": "Today is more hotter than yesterday.", "explanation": "Wrong — never use more AND -er together. Just hotter."}]', NULL, NULL, NULL, NULL, NULL, '2026-04-07 18:43:55.499559+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('3f9cd9ac-fe4e-4681-8c12-a02a553d4b71', 1859, 'sentence_auction', 'A1', 'grammar', 'Theme: Possessives — my, your, his, her, its, our, their', 'auction', '[{"correct": true, "sentence": "My sister loves coffee.", "explanation": "Correct! My = belonging to me — no apostrophe needed."}, {"correct": false, "sentence": "She forgot her''s bag on the bus.", "explanation": "Wrong — possessives never need an apostrophe: just ''her bag''."}, {"correct": true, "sentence": "The dog is wagging its tail.", "explanation": "Correct! Its (no apostrophe) means belonging to it."}, {"correct": false, "sentence": "Him phone is always on silent.", "explanation": "Wrong — use the possessive adjective: ''His phone is always on silent.''"}, {"correct": true, "sentence": "Our teacher gives us a lot of homework.", "explanation": "Correct! Our = belonging to us — correctly used before a noun."}]', NULL, NULL, NULL, NULL, NULL, '2026-04-07 18:43:55.499559+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('07e6a4f3-581c-476c-813b-9d8df64bde71', 1860, 'sentence_auction', 'A2', 'grammar', 'Theme: How much / How many — countable or uncountable?', 'auction', '[{"correct": true, "sentence": "How much milk do you need?", "explanation": "Correct! Milk is uncountable — use how much."}, {"correct": false, "sentence": "How much eggs do we need for the omelette?", "explanation": "Wrong — eggs are countable: How many eggs?"}, {"correct": true, "sentence": "How many people came to the party?", "explanation": "Correct! People is countable — use how many."}, {"correct": false, "sentence": "How many water did you drink today?", "explanation": "Wrong — water is uncountable: How much water?"}, {"correct": true, "sentence": "How much time do we have before the meeting?", "explanation": "Correct! Time as an amount is uncountable — how much is right."}, {"correct": false, "sentence": "How much chairs are in the meeting room?", "explanation": "Wrong — chairs are countable: How many chairs?"}]', NULL, NULL, NULL, NULL, NULL, '2026-04-07 18:43:55.499559+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('81b34527-bf58-43cc-9f6b-79c20cdf7d5f', 1861, 'sentence_auction', 'A1', 'vocabulary', 'Food and drink — everyday words at the table', 'auction', '[{"correct": true, "sentence": "I''d like a glass of orange juice, please.", "explanation": "Correct! ''A glass of'' is the right container for juice."}, {"correct": false, "sentence": "She ate a spaghetti for lunch.", "explanation": "Wrong — spaghetti is uncountable: no article needed. ''She ate spaghetti for lunch.''"}, {"correct": true, "sentence": "Would you like some soup?", "explanation": "Correct! Soup is uncountable — ''some soup'' is right."}, {"correct": false, "sentence": "Can I have a bread, please?", "explanation": "Wrong — bread is uncountable: ''some bread'' or ''a piece of bread''."}, {"correct": true, "sentence": "He always has cereal for breakfast.", "explanation": "Correct! Cereal is uncountable — no article needed."}]', NULL, NULL, NULL, NULL, NULL, '2026-04-07 18:43:55.499559+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('b3f94406-2ae9-45d8-bd7e-3f3e4a388f01', 1862, 'sentence_auction', 'A2', 'vocabulary', 'Getting around — transport and directions', 'auction', '[{"correct": true, "sentence": "Turn left at the traffic lights.", "explanation": "Correct! ''Turn left/right'' is the standard phrase for giving directions."}, {"correct": false, "sentence": "Go straight until you arrive to the station.", "explanation": "Wrong — we arrive at a place, not ''to'' it: ''arrive at the station''."}, {"correct": true, "sentence": "The bus stop is on the right, just past the pharmacy.", "explanation": "Correct! ''On the right'' and ''just past'' are both natural, standard phrases."}, {"correct": false, "sentence": "I go to work in foot every day.", "explanation": "Wrong — the preposition is ''on'': ''I go to work on foot.''"}, {"correct": true, "sentence": "We took a taxi from the airport to the hotel.", "explanation": "Correct! ''Take a taxi from... to...'' is the standard structure."}]', NULL, NULL, NULL, NULL, NULL, '2026-04-07 18:43:55.499559+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('f9a6ee7d-68b1-4297-aafb-d09521ef6ed8', 1128, 'multiple_choice', 'B1', 'bathroom_vocabulary', 'A bath that stands alone in the room, not fixed against a wall, is called a _______ bath.', 'freestanding', '["freestanding", "floating", "standalone", "open"]', NULL, NULL, NULL, 'Not attached to a wall — stands on its own.', 'A freestanding bath stands independently from the walls and creates a focal point in the bathroom. It is a popular choice in high-end and contemporary bathroom designs.', '2026-03-11 18:12:09.553883+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('8df9564b-3a34-4754-a36c-64e288798356', 1239, 'multiple_choice', 'B1', 'business_phrasal_verbs', 'We need to _____ our competitors'' pricing strategy before we set our own.', 'look into', '["look into", "go over", "draw up", "bring forward"]', NULL, NULL, NULL, 'To investigate — research to find out.', 'Look into means to research or investigate something carefully before making a decision.', '2026-03-18 19:58:52.376507+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('e01c1567-089f-47c6-9436-48ea89f385e4', 1863, 'sentence_auction', 'A1', 'vocabulary', 'Numbers, days and months — getting the basics right', 'auction', '[{"correct": true, "sentence": "My birthday is on the fifteenth of March.", "explanation": "Correct! ''On the + ordinal + of + month'' is the standard British date format."}, {"correct": false, "sentence": "The meeting is in Monday.", "explanation": "Wrong — use ''on'' with days of the week: ''on Monday''."}, {"correct": true, "sentence": "The office is open from nine to five.", "explanation": "Correct! ''From... to...'' is the standard structure for giving times."}, {"correct": false, "sentence": "She was borned on the twelfth of April.", "explanation": "Wrong — born is already the past participle: ''She was born on the twelfth of April.''"}, {"correct": true, "sentence": "The train leaves at quarter past eight.", "explanation": "Correct! Quarter past eight = 8:15 — a standard time expression."}]', NULL, NULL, NULL, NULL, NULL, '2026-04-07 18:43:55.499559+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('2156e98b-93c7-4ac4-967e-36ae0086e6b9', 1864, 'sentence_auction', 'A2', 'vocabulary', 'Describing people — appearance and personality', 'auction', '[{"correct": true, "sentence": "She has long brown hair and blue eyes.", "explanation": "Correct! ''Has + adjective + noun'' is the standard structure for describing appearance."}, {"correct": false, "sentence": "He is having a beard.", "explanation": "Wrong — physical features use simple have, not the continuous: ''He has a beard.''"}, {"correct": true, "sentence": "My manager is quite tall and very friendly.", "explanation": "Correct! Natural description using two adjectives after ''is''."}, {"correct": false, "sentence": "She looks like intelligent.", "explanation": "Wrong — ''look like'' is followed by a noun. For adjectives, just say: ''She looks intelligent.''"}, {"correct": true, "sentence": "He is in his thirties and wears glasses.", "explanation": "Correct! ''In his thirties'' and ''wears glasses'' are both standard phrases."}]', NULL, NULL, NULL, NULL, NULL, '2026-04-07 18:43:55.499559+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('459579e5-37da-4d10-8f85-74a880d980fd', 1865, 'sentence_auction', 'A2', 'grammar', 'Animals — true, false or just silly?', 'auction', '[{"correct": true, "sentence": "A cat has four legs and a tail.", "explanation": "Correct! True and grammatically perfect — has, four, a."}, {"correct": false, "sentence": "Fishes live in the sea and in lakes.", "explanation": "Wrong — the plural of fish is usually just ''fish'': ''Fish live in the sea and in lakes.''"}, {"correct": true, "sentence": "A dog wags its tail when it is happy.", "explanation": "Correct! Its (no apostrophe) = belonging to it — used correctly here."}, {"correct": false, "sentence": "Elephants is the biggest land animal on earth.", "explanation": "Wrong — elephants is plural, so use ''are'': ''Elephants are the biggest land animals on earth.''"}, {"correct": true, "sentence": "Birds can fly, but penguins can''t.", "explanation": "Correct! Short negative with can''t — perfectly formed."}]', NULL, NULL, NULL, NULL, NULL, '2026-04-07 18:43:55.499559+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('d9befc3f-1995-428e-84bb-b8317b6b3ed5', 1866, 'sentence_auction', 'A1', 'grammar', 'The classroom — things you can touch right now', 'auction', '[{"correct": true, "sentence": "There is a pen on the table.", "explanation": "Correct! There is + singular noun — perfect."}, {"correct": false, "sentence": "There is two students absent today.", "explanation": "Wrong — with a plural noun, use ''there are'': ''There are two students absent today.''"}, {"correct": true, "sentence": "Can you open the window, please?", "explanation": "Correct! Can + infinitive for polite requests — natural classroom English."}, {"correct": false, "sentence": "The teacher writed the answer on the board.", "explanation": "Wrong — write is an irregular verb. Past simple = wrote: ''The teacher wrote the answer on the board.''"}, {"correct": true, "sentence": "Put your phone on the desk when the class starts.", "explanation": "Correct! Natural classroom instruction — imperative + when clause."}]', NULL, NULL, NULL, NULL, NULL, '2026-04-07 18:43:55.499559+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('e90a351e-b45b-4ea5-8da9-f225f950a7e1', 1867, 'sentence_auction', 'B1', 'grammar', 'Theme: Present perfect — just, already, yet and ever', 'auction', '[{"correct": true, "sentence": "I''ve just finished the report — it''s on your desk.", "explanation": "Correct! Just + present perfect = a very recent action. Position: between have and past participle."}, {"correct": false, "sentence": "Have you eaten already dinner?", "explanation": "Wrong — already goes after the auxiliary or at the end: ''Have you already eaten dinner?'' or ''Have you eaten dinner already?''"}, {"correct": true, "sentence": "She hasn''t replied to the email yet.", "explanation": "Correct! Yet goes at the end of negative sentences and questions."}, {"correct": false, "sentence": "I yet haven''t received the invoice.", "explanation": "Wrong — yet goes at the end: ''I haven''t received the invoice yet.''"}, {"correct": true, "sentence": "Have you ever been to Japan?", "explanation": "Correct! Ever goes between the auxiliary and past participle when asking about life experience."}, {"correct": false, "sentence": "He has just went to the bank.", "explanation": "Wrong — just needs the past participle, not the past simple: ''He has just gone to the bank.''"}]', NULL, NULL, NULL, NULL, NULL, '2026-04-07 18:44:44.094478+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('a1ddb437-3fe2-4c54-bd31-bca7c0e0b118', 1868, 'sentence_auction', 'B2', 'grammar', 'Theme: Verb patterns — suggest, recommend, need and want', 'auction', '[{"correct": true, "sentence": "I suggest taking the train — it''s much faster.", "explanation": "Correct! Suggest is followed by a gerund (-ing form)."}, {"correct": false, "sentence": "She recommended to visit the old quarter.", "explanation": "Wrong — recommend takes a gerund: ''recommended visiting the old quarter''."}, {"correct": true, "sentence": "He needs to check the reservation before tomorrow.", "explanation": "Correct! Need + to + infinitive — standard verb pattern."}, {"correct": false, "sentence": "I suggest to leave before the rush hour.", "explanation": "Wrong — suggest takes -ing: ''I suggest leaving before the rush hour.''"}, {"correct": true, "sentence": "They recommended staying at the Palas Hotel.", "explanation": "Correct! Recommend + -ing (gerund) — the correct pattern."}]', NULL, NULL, NULL, NULL, NULL, '2026-04-07 18:44:44.094478+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('e3218d85-5f46-4d3b-8759-162736562612', 1869, 'sentence_auction', 'B1', 'grammar', 'Theme: Phrasal verb word order — where does the object go?', 'auction', '[{"correct": true, "sentence": "Can you look this word up for me?", "explanation": "Correct! Separable phrasal verb — a noun object can go before or after the particle."}, {"correct": false, "sentence": "Can you look up it?", "explanation": "Wrong — when the object is a pronoun, it must go between verb and particle: ''Can you look it up?''"}, {"correct": true, "sentence": "She turned the offer down without hesitation.", "explanation": "Correct! Turn down is separable — the noun object can follow the particle."}, {"correct": false, "sentence": "He turned down it immediately.", "explanation": "Wrong — pronoun objects must come before the particle: ''He turned it down immediately.''"}, {"correct": true, "sentence": "They called the meeting off at the last minute.", "explanation": "Correct! Call off is separable — noun object can go before or after the particle."}]', NULL, NULL, NULL, NULL, NULL, '2026-04-07 18:44:44.094478+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('823a2852-ecaa-476c-90bc-3ee8beabd094', 1129, 'multiple_choice', 'B1', 'bathroom_vocabulary', 'When a customer asks for a price before they decide to buy, we give them a _______.', 'quote', '["quote", "invoice", "receipt", "bill"]', NULL, NULL, NULL, 'A formal price estimate given before purchase.', 'A quote (or quotation) gives the customer a fixed price before they commit to a purchase. An invoice is issued after the sale has been agreed and goods have been supplied.', '2026-03-11 18:12:09.553883+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('5a05b22b-0ee4-445e-847d-f221e74f4453', 1870, 'sentence_auction', 'B2', 'grammar', 'Theme: Wish and if only — imagining things were different', 'auction', '[{"correct": true, "sentence": "I wish I spoke better Spanish.", "explanation": "Correct! Wish + past simple = a present situation you want to be different."}, {"correct": false, "sentence": "I wish I would have more free time.", "explanation": "Wrong — don''t use would after wish for present situations: ''I wish I had more free time.''"}, {"correct": true, "sentence": "If only I hadn''t sent that email!", "explanation": "Correct! If only + past perfect = regret about a past action."}, {"correct": false, "sentence": "She wishes she can speak English fluently.", "explanation": "Wrong — use a past form after wish: ''She wishes she could speak English fluently.''"}, {"correct": true, "sentence": "I wish you were here right now.", "explanation": "Correct! Wish + were (past simple) = a present wish — perfectly formed."}]', NULL, NULL, NULL, NULL, NULL, '2026-04-07 18:44:44.094478+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('7cb70ee7-8d9b-4199-8d65-b6a06d2620c4', 1871, 'sentence_auction', 'B1', 'vocabulary', 'Travel and holidays — the right verb or noun', 'auction', '[{"correct": true, "sentence": "We checked in at the hotel at three o''clock.", "explanation": "Correct! ''Check in'' is the standard phrasal verb for arriving at a hotel."}, {"correct": false, "sentence": "She made a reservation on the restaurant for Saturday.", "explanation": "Wrong — we make a reservation at a restaurant, not ''on'': ''at the restaurant''."}, {"correct": true, "sentence": "The flight was delayed by two hours because of bad weather.", "explanation": "Correct! ''Delayed by'' for the amount of time and ''because of'' for the reason — both correct."}, {"correct": false, "sentence": "They arrived to the airport with plenty of time.", "explanation": "Wrong — arrive at or in, never ''to'': ''They arrived at the airport.''"}, {"correct": true, "sentence": "He packed his suitcase the night before the trip.", "explanation": "Correct! ''Pack a suitcase'' is the right collocation — natural and standard."}]', NULL, NULL, NULL, NULL, NULL, '2026-04-07 18:44:44.094478+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('2d9b05d3-9bc2-493d-8cb3-74de75a79cf9', 1872, 'sentence_auction', 'B2', 'vocabulary', 'Make or do? — getting the collocation right', 'auction', '[{"correct": true, "sentence": "She made a great impression at the interview.", "explanation": "Correct! ''Make an impression'' is the right collocation."}, {"correct": false, "sentence": "He did a mistake in the final report.", "explanation": "Wrong — the correct collocation is ''make a mistake'', not ''do a mistake''."}, {"correct": true, "sentence": "Can you do me a favour?", "explanation": "Correct! ''Do a favour'' is the right collocation — never ''make a favour''."}, {"correct": false, "sentence": "I really need to make some exercise this week.", "explanation": "Wrong — the correct collocation is ''do exercise'', not ''make exercise''."}, {"correct": true, "sentence": "They made a decision very quickly.", "explanation": "Correct! ''Make a decision'' is a standard and correct collocation."}]', NULL, NULL, NULL, NULL, NULL, '2026-04-07 18:44:44.094478+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('9330c551-79b9-419f-975e-f78f642dd43b', 1873, 'sentence_auction', 'B1', 'vocabulary', 'Feelings and emotions — precise vocabulary', 'auction', '[{"correct": true, "sentence": "I was exhausted after the long journey.", "explanation": "Correct! Exhausted = extremely tired — a precise and natural word choice."}, {"correct": false, "sentence": "She felt very boring during the presentation.", "explanation": "Wrong — boring describes the thing, not the person: ''She felt bored during the presentation.''"}, {"correct": true, "sentence": "He was embarrassed when he forgot her name.", "explanation": "Correct! Embarrassed = feeling awkward or ashamed — used correctly here."}, {"correct": false, "sentence": "The horror film was very frightened.", "explanation": "Wrong — frightened describes people who feel fear. The film itself was frightening."}, {"correct": true, "sentence": "We were all relieved when the exam was finally over.", "explanation": "Correct! Relieved = happy that something worrying has ended — precisely used."}]', NULL, NULL, NULL, NULL, NULL, '2026-04-07 18:44:44.094478+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('90197198-5a57-48b6-9c03-0415e6de2a0a', 1874, 'sentence_auction', 'B2', 'vocabulary', 'Work and career — professional vocabulary', 'auction', '[{"correct": true, "sentence": "She was promoted to senior manager last year.", "explanation": "Correct! ''Be promoted to + position'' is the standard phrase."}, {"correct": false, "sentence": "She was fired from her work for arriving late every day.", "explanation": "Wrong — we say ''fired from her job'', not ''her work''. Job is the right word for a specific position."}, {"correct": true, "sentence": "The company made ten employees redundant last month.", "explanation": "Correct! ''Make someone redundant'' = they lose their job due to restructuring — standard British English."}, {"correct": false, "sentence": "He applied for the job in the internet.", "explanation": "Wrong — you apply for a job ''on'' the internet, not ''in'': ''he applied on the internet''."}, {"correct": true, "sentence": "She is currently on maternity leave.", "explanation": "Correct! ''On maternity leave'' is the correct fixed phrase."}]', NULL, NULL, NULL, NULL, NULL, '2026-04-07 18:44:44.094478+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('6cf465d4-d911-43e2-ac7f-1165f22541d2', 1875, 'sentence_auction', 'B1', 'grammar', 'Holiday disasters — did it all go wrong?', 'auction', '[{"correct": true, "sentence": "We missed our flight because of a traffic jam.", "explanation": "Correct! ''Miss a flight'' is the right collocation — not ''lose a flight''."}, {"correct": false, "sentence": "She lost her plane at the airport.", "explanation": "Wrong — you miss a plane or flight, not ''lose'' it: ''She missed her flight at the airport.''"}, {"correct": true, "sentence": "The hotel had overbooked and we had to move to a different room.", "explanation": "Correct! Overbook = take more reservations than available — natural and correct."}, {"correct": false, "sentence": "Our luggage was losted on the way to the hotel.", "explanation": "Wrong — lost is already the irregular past participle: ''Our luggage was lost on the way.''"}, {"correct": true, "sentence": "Fortunately, the airline compensated us for the delay.", "explanation": "Correct! ''Compensate + for'' is the right preposition — used correctly here."}]', NULL, NULL, NULL, NULL, NULL, '2026-04-07 18:44:44.094478+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('1641e976-d284-4246-bdeb-0734e45524ae', 1876, 'sentence_auction', 'B2', 'grammar', 'Hotel English — what would a receptionist actually say?', 'auction', '[{"correct": true, "sentence": "Certainly, I''ll arrange a taxi for you straight away.", "explanation": "Correct! Natural, polite hotel English — ''certainly'' and ''straight away'' are both appropriate."}, {"correct": false, "sentence": "I am apologising for the inconvenience, sir.", "explanation": "Wrong — we don''t use the continuous for a speech act apology: ''I apologise for the inconvenience.''"}, {"correct": true, "sentence": "I''m afraid your room won''t be ready until three o''clock.", "explanation": "Correct! ''I''m afraid...'' is the standard polite way to deliver bad news in hotel English."}, {"correct": false, "sentence": "Could you fill your name here, please?", "explanation": "Wrong — ''fill'' alone needs a complement: ''fill in your name'' or ''write your name here''."}, {"correct": true, "sentence": "Please don''t hesitate to contact us if you need anything at all.", "explanation": "Correct! A classic, polite hotel phrase — grammatically perfect and appropriately formal."}]', NULL, NULL, NULL, NULL, NULL, '2026-04-07 18:44:44.094478+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('5b1361e2-cef6-4d93-b971-3210cba0b79c', 1877, 'sentence_auction', 'C1', 'grammar', 'Theme: The subjunctive — suggest, insist, recommend + that clause', 'auction', '[{"correct": true, "sentence": "The manager insisted that every member of staff attend the briefing.", "explanation": "Correct! Formal subjunctive: use the base form (attend, not attends) after ''insist that''."}, {"correct": false, "sentence": "I suggest that he should to revise the proposal.", "explanation": "Wrong — no ''to'' after a modal: ''I suggest that he should revise'' or ''I suggest he revise the proposal.''"}, {"correct": true, "sentence": "It is essential that the report be submitted by Friday.", "explanation": "Correct! Formal subjunctive: ''be'' (not ''is'') after ''it is essential that''."}, {"correct": false, "sentence": "I suggest that he should goes over the figures again.", "explanation": "Wrong — after should, use the base form: ''should go over the figures again''."}, {"correct": true, "sentence": "The contract stipulates that payment be made within 30 days.", "explanation": "Correct! Formal subjunctive with ''stipulate that'' — ''be made'', not ''is made''."}]', NULL, NULL, NULL, NULL, NULL, '2026-04-07 18:45:38.090437+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('bd1adab7-4478-4954-8e36-1cf2b90f94a0', 1878, 'sentence_auction', 'C2', 'grammar', 'Theme: Ellipsis — words we can (and cannot) leave out', 'auction', '[{"correct": true, "sentence": "She asked if I was coming, and I said I was.", "explanation": "Correct! ''I was'' stands for ''I was coming'' — correct ellipsis after the auxiliary."}, {"correct": false, "sentence": "He wanted to leave early, and so wanted she.", "explanation": "Wrong — after ''so'' in a follow-on clause, invert the auxiliary: ''and so did she''."}, {"correct": true, "sentence": "I haven''t seen that film, but I''d love to.", "explanation": "Correct! ''To'' stands for ''to see it'' — natural ellipsis after a modal."}, {"correct": false, "sentence": "A: Do you want some coffee? B: Yes, I want.", "explanation": "Wrong — the verb needs an object or auxiliary to stand alone: ''Yes, I do'' or ''Yes please.''"}, {"correct": true, "sentence": "She was exhausted, but he wasn''t.", "explanation": "Correct! ''Wasn''t'' stands for ''wasn''t exhausted'' — clean and natural ellipsis."}]', NULL, NULL, NULL, NULL, NULL, '2026-04-07 18:45:38.090437+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('f9a039c1-e657-42bb-95aa-dc2168ff4d31', 1879, 'sentence_auction', 'C1', 'grammar', 'Theme: Nominalisation — turning verbs and adjectives into formal nouns', 'auction', '[{"correct": true, "sentence": "The introduction of the new policy led to significant improvements.", "explanation": "Correct! ''Introduction'' (from ''introduce'') — formal nominalisation used naturally."}, {"correct": false, "sentence": "The company made an announcement about to close the factory.", "explanation": "Wrong — after ''about'', use a gerund: ''an announcement about closing the factory''."}, {"correct": true, "sentence": "His refusal to cooperate caused considerable delays.", "explanation": "Correct! ''Refusal'' (from ''refuse'') — formal nominalisation used precisely."}, {"correct": false, "sentence": "There was an increasing of complaints following the changes.", "explanation": "Wrong — ''increasing'' is not a noun here. Use ''an increase in complaints''."}, {"correct": true, "sentence": "The effectiveness of the campaign was measured over three months.", "explanation": "Correct! ''Effectiveness'' (from ''effective'') — correctly formed abstract noun."}]', NULL, NULL, NULL, NULL, NULL, '2026-04-07 18:45:38.090437+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('8fc8927e-8f20-43d0-a8b3-8dff2d63d9ce', 1880, 'sentence_auction', 'C2', 'grammar', 'Theme: Hedging — expressing uncertainty and distance formally', 'auction', '[{"correct": true, "sentence": "The data would appear to suggest a correlation between the two variables.", "explanation": "Correct! ''Would appear to'' softens the claim — precise academic hedging."}, {"correct": true, "sentence": "There tends to be a significant increase in sales during the summer months.", "explanation": "Correct! ''Tends to be'' = hedged generalisation — appropriate academic language."}, {"correct": false, "sentence": "Research suggest that sleep deprivation effects performance.", "explanation": "Wrong — two errors: ''research suggests'' (third-person singular) and ''affects'' (verb), not ''effects'' (noun)."}, {"correct": true, "sentence": "It could be argued that the policy has had limited success.", "explanation": "Correct! ''Could be argued'' = distanced academic hedging — used correctly."}, {"correct": false, "sentence": "The findings clearly proves that the treatment is effective.", "explanation": "Wrong — ''findings'' is plural: ''The findings clearly prove that...''"}]', NULL, NULL, NULL, NULL, NULL, '2026-04-07 18:45:38.090437+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('b13c219a-b766-49f3-b727-9526ef29ce85', 1881, 'sentence_auction', 'C1', 'vocabulary', 'Formal synonyms — one precise word works better', 'auction', '[{"correct": true, "sentence": "The board approved the proposal to restructure the department.", "explanation": "Correct! ''Approved'' is a precise, formal synonym for ''said yes to'' — appropriate register."}, {"correct": false, "sentence": "The director refuted strongly the accusations in public.", "explanation": "Wrong — adverb placement: the adverb should come before the verb or at the end: ''strongly refuted the accusations''."}, {"correct": true, "sentence": "The audit revealed several discrepancies in the accounts.", "explanation": "Correct! ''Revealed'' and ''discrepancies'' are both precise, appropriate formal vocabulary."}, {"correct": false, "sentence": "He made a research into the competitor''s pricing strategy.", "explanation": "Wrong — research is uncountable (no article) and collocates with ''do'', not ''make'': ''He did research into...''"}, {"correct": true, "sentence": "The company''s turnover has declined sharply over the past quarter.", "explanation": "Correct! ''Turnover'', ''declined'' and ''sharply'' are all precise, formal business vocabulary."}]', NULL, NULL, NULL, NULL, NULL, '2026-04-07 18:45:38.090437+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('64f51ce9-d400-4edf-b752-fc3f586a0f6a', 1882, 'sentence_auction', 'C2', 'vocabulary', 'Register — does this feel formal, neutral or all wrong?', 'auction', '[{"correct": true, "sentence": "I am writing to enquire about the terms of the proposed agreement.", "explanation": "Correct! Consistent formal register throughout — appropriate for business correspondence."}, {"correct": false, "sentence": "The CEO is well chuffed with the quarterly results.", "explanation": "Wrong — ''well chuffed'' is very informal British slang, completely out of place in a business context."}, {"correct": true, "sentence": "We regret to inform you that your application has been unsuccessful.", "explanation": "Correct! Consistent, appropriate formal register — classic professional English."}, {"correct": false, "sentence": "The board was like, totally impressed by the presentation, to be fair.", "explanation": "Wrong — ''like'', ''totally'' and ''to be fair'' are conversational fillers — completely inappropriate in formal writing."}, {"correct": true, "sentence": "Please find attached the documents you requested at our meeting.", "explanation": "Correct! ''Please find attached'' is a formal, standard business phrase — perfectly consistent register."}]', NULL, NULL, NULL, NULL, NULL, '2026-04-07 18:45:38.090437+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('800a10d7-60b0-4009-8bbf-7f42b4b8abb8', 534, 'multiple_choice', 'C2', 'idioms', 'He''s been burning the ___ at both ends lately and needs rest.', 'candle', '["fire", "candle", "torch", "lamp"]', NULL, NULL, NULL, 'Working too hard — an idiom about a wax light.', 'Burn the candle at both ends = work excessively, leaving little time for rest.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Fixed expression"}', true, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('52e5ca17-a0d3-4ca3-9c64-8bb82e17f07b', 1883, 'sentence_auction', 'C1', 'vocabulary', 'Collocations — the right word with the right word', 'auction', '[{"correct": true, "sentence": "The new policy will have a significant impact on staff working conditions.", "explanation": "Correct! ''Have an impact on'' is the right collocation — not ''make an impact on''."}, {"correct": false, "sentence": "The results made a big influence on the decision to expand.", "explanation": "Wrong — you ''have an influence'', not ''make an influence'': ''had a big influence on the decision''."}, {"correct": true, "sentence": "We need to take the client''s concerns into account.", "explanation": "Correct! ''Take into account'' = standard collocation meaning to consider something carefully."}, {"correct": false, "sentence": "She did a great effort to meet the deadline.", "explanation": "Wrong — the collocation is ''make an effort'', not ''do an effort'': ''She made a great effort.''"}, {"correct": true, "sentence": "The proposal raised some valid concerns about data security.", "explanation": "Correct! ''Raise concerns'' and ''valid concerns'' are both correct and precise collocations."}]', NULL, NULL, NULL, NULL, NULL, '2026-04-07 18:45:38.090437+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('e3eb0e9f-fb44-49c3-af4c-16e220e413ed', 1884, 'sentence_auction', 'C2', 'vocabulary', 'Idioms in context — do they fit naturally?', 'auction', '[{"correct": true, "sentence": "After the merger, the new CEO had to hit the ground running.", "explanation": "Correct! ''Hit the ground running'' = start working effectively immediately — fits the business context perfectly."}, {"correct": false, "sentence": "The project was under the weather from the very beginning.", "explanation": "Wrong — ''under the weather'' means feeling ill, not in difficulty. Use ''in trouble'' or ''off to a bad start''."}, {"correct": true, "sentence": "She burned the midnight oil to finish the proposal in time.", "explanation": "Correct! ''Burn the midnight oil'' = work late into the night — perfectly appropriate here."}, {"correct": false, "sentence": "The negotiation was a blessing in a disguise for the company.", "explanation": "Wrong — the idiom has no article before ''disguise'': ''a blessing in disguise''."}, {"correct": true, "sentence": "Getting the contract was the icing on the cake after a difficult quarter.", "explanation": "Correct! ''The icing on the cake'' = an extra benefit added to something already good — used correctly."}]', NULL, NULL, NULL, NULL, NULL, '2026-04-07 18:45:38.090437+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('5670c59c-69db-497f-884a-9839f5a0b9cd', 1885, 'sentence_auction', 'C1', 'grammar', 'Famous quotations — is the grammar flawless?', 'auction', '[{"correct": true, "sentence": "To be or not to be, that is the question.", "explanation": "Correct! Shakespeare — grammatically flawless: infinitive + infinitive, demonstrative that + be."}, {"correct": false, "sentence": "I have a dream that one day this nation will risen and live out the true meaning of its creed.", "explanation": "Wrong — after ''will'', use the base form (infinitive): ''will rise'', not ''will risen''."}, {"correct": true, "sentence": "It does not matter how slowly you go as long as you do not stop.", "explanation": "Correct! Attributed to Confucius — grammatically clean throughout."}, {"correct": false, "sentence": "Ask not what your country can do for you — ask what you can do for it your country.", "explanation": "Wrong — word order error at the end: ''what you can do for your country.''"}, {"correct": true, "sentence": "The only thing we have to fear is fear itself.", "explanation": "Correct! Franklin D. Roosevelt — ''have to'' = obligation, cleft structure — grammatically impeccable."}]', NULL, NULL, NULL, NULL, NULL, '2026-04-07 18:45:38.090437+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('6d65ca04-2031-407d-97d3-76209cf98754', 1886, 'sentence_auction', 'C2', 'grammar', 'Newspaper headlines — real grammar or headline shorthand?', 'auction', '[{"correct": true, "sentence": "Scientists discover new species in Amazon rainforest.", "explanation": "Correct! Headlines use simple present for past events and often omit articles — both conventions are standard."}, {"correct": false, "sentence": "CEO to stepped down amid fraud investigation.", "explanation": "Wrong — after ''to'', use the base form: ''to step down'', not ''to stepped down''."}, {"correct": true, "sentence": "Shares soar as inflation falls to three-year low.", "explanation": "Correct! Present simple for completed events in headlines — standard journalistic convention."}, {"correct": false, "sentence": "Three peoples arrested after city centre protests.", "explanation": "Wrong — ''people'' is already plural: ''Three people arrested after city centre protests.''"}, {"correct": true, "sentence": "New report calls on government to tackle housing crisis.", "explanation": "Correct! ''Call on someone to do something'' — correct and natural headline language."}]', NULL, NULL, NULL, NULL, NULL, '2026-04-07 18:45:38.090437+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('698a668d-1f73-4fb9-9356-bf3cd02fce3b', 1887, 'sentence_auction', 'A2', 'spanish', 'Theme: El pretérito indefinido — verbos regulares e irregulares', 'auction', '[{"correct": true, "sentence": "Ayer comí paella en un restaurante muy bueno.", "explanation": "Correct! comer → comí — regular -er verb in pretérito indefinido."}, {"correct": false, "sentence": "El año pasado nosotros visitaron Madrid.", "explanation": "Incorrecto — visitaron es tercera persona plural. Con nosotros: visitamos."}, {"correct": true, "sentence": "Ella fue al médico el jueves pasado.", "explanation": "Correct! ir → fue — irregular pretérito indefinido, very common."}, {"correct": false, "sentence": "Yo hicé los deberes anoche.", "explanation": "Incorrecto — hacer es irregular en pretérito: hice (no accent, no -é ending)."}, {"correct": true, "sentence": "Anteayer llegaron mis padres de vacaciones.", "explanation": "Correct! llegar → llegaron — regular -ar verb, third person plural."}]', NULL, NULL, NULL, NULL, NULL, '2026-04-07 18:46:33.85208+00', NULL, NULL, 'es', '{Gramática}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('e23465d2-3891-4e14-9b40-fb44c901f52f', 1888, 'sentence_auction', 'A2', 'spanish', 'Theme: Los verbos reflexivos — el pronombre correcto', 'auction', '[{"correct": true, "sentence": "Me levanto a las siete todos los días.", "explanation": "Correct! Yo → me — the right reflexive pronoun for levantarse."}, {"correct": false, "sentence": "Ella se despierta y luego te duchas.", "explanation": "Incorrecto — pronombre incorrecto. Ella → se: ''Ella se despierta y luego se ducha.''"}, {"correct": true, "sentence": "Nos sentamos cerca de la ventana en el restaurante.", "explanation": "Correct! Nosotros → nos — correct reflexive pronoun for sentarse."}, {"correct": false, "sentence": "Ellos se llaman Pedro y Ana, y yo llamo Miguel.", "explanation": "Incorrecto — falta el pronombre reflexivo para yo: ''yo me llamo Miguel''."}, {"correct": true, "sentence": "Por las noches, él se relaja viendo la tele.", "explanation": "Correct! Él → se — correct reflexive pronoun for relajarse."}]', NULL, NULL, NULL, NULL, NULL, '2026-04-07 18:46:33.85208+00', NULL, NULL, 'es', '{Gramática}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('468bae17-1524-4e24-8240-1ebd43af6bfb', 1889, 'sentence_auction', 'A2', 'spanish', 'Theme: El presente de indicativo — verbos irregulares', 'auction', '[{"correct": true, "sentence": "Yo tengo mucho trabajo esta semana.", "explanation": "Correct! tener → tengo — irregular yo form."}, {"correct": false, "sentence": "Nosotros venemos al trabajo en metro.", "explanation": "Incorrecto — venir → venimos, not venemos."}, {"correct": true, "sentence": "Ella quiere hablar con el director hoy.", "explanation": "Correct! querer → quiere — stem-change e→ie."}, {"correct": false, "sentence": "Yo sabo la respuesta a todas las preguntas.", "explanation": "Incorrecto — saber es irregular en la forma yo: sé, not sabo."}, {"correct": true, "sentence": "Ellos tienen que trabajar el fin de semana.", "explanation": "Correct! tener → tienen — correct third person plural form."}]', NULL, NULL, NULL, NULL, NULL, '2026-04-07 18:46:33.85208+00', NULL, NULL, 'es', '{Gramática}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('2aa1badc-7ed2-442b-bb02-08fd05070031', 1890, 'sentence_auction', 'A2', 'spanish', 'Theme: Hay que / Tener que / Deber — expresar obligación', 'auction', '[{"correct": true, "sentence": "Hay que reservar mesa con antelación.", "explanation": "Correct! Hay que + infinitive = impersonal obligation — no subject needed."}, {"correct": false, "sentence": "Tienes que de llegar antes de las nueve.", "explanation": "Incorrecto — no hay ''de'' después de tener que: ''Tienes que llegar antes de las nueve.''"}, {"correct": true, "sentence": "Debes hablar con el responsable del hotel.", "explanation": "Correct! Deber + infinitive = should/must — used correctly here."}, {"correct": false, "sentence": "Hay que nosotros confirmar la reserva.", "explanation": "Incorrecto — hay que es impersonal, no puede tener sujeto: ''Hay que confirmar la reserva.''"}, {"correct": true, "sentence": "Tengo que terminar el informe antes del mediodía.", "explanation": "Correct! Tener que + infinitive = personal obligation — perfectly formed."}]', NULL, NULL, NULL, NULL, NULL, '2026-04-07 18:46:33.85208+00', NULL, NULL, 'es', '{Gramática}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('f3cd06c9-2b87-4498-90ed-6ce5cbbd1583', 1891, 'sentence_auction', 'A2', 'spanish', 'En el hotel — vocabulario esencial', 'auction', '[{"correct": true, "sentence": "Quisiera reservar una habitación doble para dos noches.", "explanation": "Correct! Quisiera is the polite conditional form of querer — essential hotel Spanish."}, {"correct": false, "sentence": "La habitación tiene mucha vistas al mar.", "explanation": "Incorrecto — vistas is feminine plural: ''muchas vistas al mar''."}, {"correct": true, "sentence": "El hotel tiene piscina, gimnasio y servicio de habitaciones.", "explanation": "Correct! Standard hotel description — all vocabulary used correctly."}, {"correct": false, "sentence": "¿A qué hora es el salida?", "explanation": "Incorrecto — salida is feminine: la salida. ''¿A qué hora es la salida?''"}, {"correct": true, "sentence": "Por favor, ¿puede traerme más toallas a la habitación?", "explanation": "Correct! Natural, polite request for room service — perfect grammar and register."}]', NULL, NULL, NULL, NULL, NULL, '2026-04-07 18:46:33.85208+00', NULL, NULL, 'es', '{Vocabulario}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('d9e769fb-60cc-4784-a72d-7c156c54a1f3', 1892, 'sentence_auction', 'A2', 'spanish', 'La comida y la bebida — ¿qué hay en el menú?', 'auction', '[{"correct": true, "sentence": "De primero voy a tomar la sopa del día.", "explanation": "Correct! De primero = for the first course — standard restaurant Spanish."}, {"correct": false, "sentence": "Para beber, voy a tomar una agua sin gas.", "explanation": "Incorrecto — agua is feminine but takes un/el (special rule for words starting with stressed a-): ''un agua sin gas''."}, {"correct": true, "sentence": "¿Me puede traer la carta, por favor?", "explanation": "Correct! La carta = the menu — standard restaurant phrase."}, {"correct": false, "sentence": "¿Está incluido el servicio in el precio?", "explanation": "Incorrecto — preposición incorrecta (¡ojo, ''in'' es inglés!): use ''en'': ''¿Está incluido el servicio en el precio?''"}, {"correct": true, "sentence": "De postre me gustaría el flan con nata.", "explanation": "Correct! De postre = for dessert — natural restaurant Spanish."}]', NULL, NULL, NULL, NULL, NULL, '2026-04-07 18:46:33.85208+00', NULL, NULL, 'es', '{Vocabulario}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('ca8fab22-53f8-4c5a-a5ce-c369dd09c71f', 1893, 'sentence_auction', 'A2', 'spanish', 'La ropa y los colores', 'auction', '[{"correct": true, "sentence": "Llevo una camiseta azul y unos vaqueros.", "explanation": "Correct! Llevar = to wear — the standard verb for clothing in Spanish."}, {"correct": false, "sentence": "Él lleva un chaqueta marrón y corbata.", "explanation": "Incorrecto — chaqueta is feminine: una chaqueta. ''Él lleva una chaqueta marrón y corbata.''"}, {"correct": true, "sentence": "¿Tienes esta camisa en talla mediana?", "explanation": "Correct! Standard shop phrase — natural and correct."}, {"correct": false, "sentence": "Esos zapatos cuestan ciento euros.", "explanation": "Incorrecto — 100 = cien; ciento is only used in compounds like 101 (ciento uno): ''Esos zapatos cuestan cien euros.''"}, {"correct": true, "sentence": "Me gusta más el vestido verde que el rojo.", "explanation": "Correct! Comparative with más... que — correctly formed."}]', NULL, NULL, NULL, NULL, NULL, '2026-04-07 18:46:33.85208+00', NULL, NULL, 'es', '{Vocabulario}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('06e1de29-86ca-4805-940b-c4270a5caeb2', 1894, 'sentence_auction', 'A2', 'spanish', 'De compras — frases y vocabulario', 'auction', '[{"correct": true, "sentence": "¿Cuánto cuesta esta bolsa de cuero?", "explanation": "Correct! Standard shopping question — natural and correct."}, {"correct": false, "sentence": "Estoy buscando un regalo por mi madre.", "explanation": "Incorrecto — for people, use para: ''un regalo para mi madre''."}, {"correct": true, "sentence": "Voy a pagar con tarjeta, si es posible.", "explanation": "Correct! Standard payment phrase — perfect register and grammar."}, {"correct": false, "sentence": "¿Puedo probarse estos pantalones?", "explanation": "Incorrecto — the reflexive pronoun must match the subject (yo → me): ''¿Puedo probarme estos pantalones?''"}, {"correct": true, "sentence": "Esta tienda tiene muchas rebajas en verano.", "explanation": "Correct! Rebajas = sales — standard vocabulary used correctly."}]', NULL, NULL, NULL, NULL, NULL, '2026-04-07 18:46:33.85208+00', NULL, NULL, 'es', '{Vocabulario}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('deec6ed1-8952-4b7e-84de-b67bb6e8cf40', 1895, 'sentence_auction', 'A2', 'spanish', 'Los falsos amigos — ¡cuidado con estas palabras!', 'auction', '[{"correct": true, "sentence": "Voy a la biblioteca para estudiar — tienen wifi gratis.", "explanation": "Correct! Biblioteca = library (where you read and study, not buy books)."}, {"correct": false, "sentence": "Necesito comprar un libro — voy a la biblioteca.", "explanation": "Incorrecto — you buy books in a librería (bookshop), not a biblioteca (library). ¡Falso amigo!"}, {"correct": true, "sentence": "Estoy muy emocionada — mañana empiezo mi nuevo trabajo.", "explanation": "Correct! Emocionada = excited (NOT emotional — that would be emotiva). A common false friend to know!"}, {"correct": false, "sentence": "Estoy muy embarazada porque llegué tarde a la reunión.", "explanation": "Incorrecto — embarazada means pregnant, not embarrassed! Use avergonzada: ''Estoy muy avergonzada porque llegué tarde.''"}, {"correct": true, "sentence": "Tengo una cita con el dentista el viernes.", "explanation": "Correct! Cita = appointment (and also a romantic date — context makes the difference)."}]', NULL, NULL, NULL, NULL, NULL, '2026-04-07 18:46:33.85208+00', NULL, NULL, 'es', '{Vocabulario}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('44b6d501-5e21-4a14-8052-7198ac15bc5f', 1896, 'sentence_auction', 'A2', 'spanish', '¿Tú o usted? — ¿formal o informal?', 'auction', '[{"correct": true, "sentence": "Buenos días, señora García. ¿Cómo está usted?", "explanation": "Correct! Usted = formal — the right choice for a polite greeting to someone you don''t know well."}, {"correct": false, "sentence": "Disculpe, señor Director, ¿tienes un momento?", "explanation": "Incorrecto — mixing formal address (señor Director) with the informal tú form (tienes). Use usted: ''¿tiene un momento?''"}, {"correct": true, "sentence": "Hola, ¿cómo estás? ¿Qué tal el fin de semana?", "explanation": "Correct! Tú form — appropriate between friends or colleagues of the same level."}, {"correct": false, "sentence": "Buenas tardes. ¿Podría usted decirme dónde está la recepción? ¿Y tú, qué quieres?", "explanation": "Incorrecto — switching from usted to tú when speaking to the same person is inconsistent and rude."}, {"correct": true, "sentence": "Oye, ¿puedes echarme una mano con esto?", "explanation": "Correct! Tú form — perfectly appropriate in an informal, friendly context."}]', NULL, NULL, NULL, NULL, NULL, '2026-04-07 18:46:33.85208+00', NULL, NULL, 'es', '{Gramática}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('ba90a2ff-3e2a-44f5-8623-4071483ff49c', 181, 'multiple_choice', 'B1', 'prepositions_by', 'The report must be finished ___ Friday.', 'by', '["until", "by", "on", "at"]', NULL, NULL, NULL, 'Deadline — must be done at or before that point.', 'By for deadlines (not later than).', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{"Preposition of time"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('5ceec80f-2bba-427f-89c9-b2874942bd48', 180, 'multiple_choice', 'B2', 'inversion_conditional', '___ I known, I would have told you.', 'Had', '["If", "Had", "Would", "Should"]', NULL, NULL, NULL, 'Formal conditional with inversion, replacing "If I had known".', 'Inversion in third conditional (Had I known = If I had known).', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{Inversion}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('3054c06e-802e-4dd5-86da-715a1d931e68', 182, 'multiple_choice', 'B2', 'modals_should_have', 'You ___ told me earlier. Now it''s too late.', 'should have', '["should", "should have", "must", "must have"]', NULL, NULL, NULL, 'Past regret — looking back at what didn''t happen. Form: ___ + past participle.', 'Should have + past participle for criticism of past actions.', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{"Modal verb"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('b31d017d-7dbf-49e9-aa0d-8440df31d4f5', 188, 'multiple_choice', 'B2', 'be_used_to', 'Don''t worry about the noise. I ___ in the city.', 'am used to living', '["used to living", "am used to living", "use to live", "am using to live"]', NULL, NULL, NULL, 'Accustomed to — followed by -ing form. Different from "used to" (past habit)!', 'Be used to + gerund (accustomed to).', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{"Past tense"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('68e033ab-26a0-4b93-871c-0477e2273ed7', 190, 'multiple_choice', 'B2', 'nominal_relative_clauses', '___ matters most is your happiness.', 'What', '["That", "What", "Which", "Who"]', NULL, NULL, NULL, '= "the thing that" — starts a noun clause.', 'What as subject of the sentence (= the thing that).', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{"Relative clause"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('dafab9f2-9197-43ae-9179-92724f3c6a55', 191, 'multiple_choice', 'B1', 'modals_may_permission', '___ I use your phone?', 'May', '["Ought to", "Must", "May", "Need"]', NULL, NULL, NULL, 'Formal permission request — politer than "can".', 'May for formal permission.', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{"Modal verb"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('afa4186f-ae15-4650-8f4f-bb295bf90529', 193, 'multiple_choice', 'B1', 'will_spontaneous', 'The phone''s ringing. I ___ it.', 'will answer', '["answer", "will answer", "am answering", "going to answer"]', NULL, NULL, NULL, 'Decision made right now, at this moment — phone''s ringing, you''re responding.', 'Will for spontaneous decisions.', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{"Future form"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('1bb879c1-ced4-4c6f-9539-41eb85548032', 195, 'multiple_choice', 'B1', 'too_adjective', 'I''m ___ tired to go out tonight.', 'too', '["a lot of", "too", "so", "enough"]', NULL, NULL, NULL, 'Excessively — to the point that you can''t do something.', 'Too + adjective + to (more than wanted/needed).', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{"Too & enough"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('09bd9a4a-3d23-4480-b271-7acb423d045a', 196, 'multiple_choice', 'B2', 'had_better', 'You ___ leave now or you''ll be late.', 'had better', '["should better", "would better", "had better", "have better"]', NULL, NULL, NULL, 'Strong advice with implied consequence if you don''t.', 'Had better for strong advice (something bad might happen if you don''t).', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{"Modal verb"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('647da761-0050-420d-9592-21d95afa614a', 198, 'multiple_choice', 'B2', 'linking_however', 'The weather was terrible. ___, we had a great time.', 'However', '["In spite of", "However", "Although", "Despite"]', NULL, NULL, NULL, 'Strong contrast between two ideas, used at the start of a new sentence.', 'However for formal contrast (usually after a full stop).', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{"Linking word"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('17ca038d-b73c-4771-ac19-c2f0a117e0d7', 199, 'multiple_choice', 'B1', 'possessive_s', 'That''s ___ car.', 'John''s', '["John", "Johns", "John''s", "Johns''"]', NULL, NULL, NULL, 'Possessive — apostrophe + s.', 'Apostrophe + s for possession.', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{Possessive}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('aa9747fd-39e4-4ddf-bbd8-c86e9a7a4607', 423, 'gap_fill', 'C1', 'modal_perfects', 'She ___ (must / forget) about the meeting. She''s not here.', 'must have forgotten', NULL, '["must''ve forgotten"]', NULL, NULL, 'Strong logical certainty about the past.', 'Must have + past participle for logical deduction about the past (very probable).', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Modal verb"}', false, 'Form: must have + past participle.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('8935954b-67cd-4005-8078-ac836b48af33', 425, 'gap_fill', 'C1', 'modal_perfects', 'You ___ (should / tell) me earlier. Now it''s too late.', 'should have told', NULL, '["should''ve told"]', NULL, NULL, 'Past regret — should have done it earlier.', 'Should have + past participle for criticism or regret about the past.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Modal verb"}', false, 'Form: should have + past participle.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('768667f5-f6e1-4595-b0e5-78807b2d24c9', 427, 'gap_fill', 'C1', 'modal_perfects', 'She ___ (needn''t / buy) so much food. Half of it was wasted.', 'needn''t have bought', NULL, NULL, NULL, NULL, 'She did buy it, but it wasn''t necessary — wasted purchase.', 'Needn''t have + past participle: it wasn''t necessary, but she did it anyway.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Modal verb"}', false, 'Form: needn''t have + past participle.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('000f0061-0907-4781-aa1e-0c29ed499bb4', 428, 'gap_fill', 'C1', 'modal_perfects', 'You ___ (could / warn) us about the traffic.', 'could have warned', NULL, '["could''ve warned"]', NULL, NULL, 'Past criticism — they had the option but didn''t take it.', 'Could have + past participle: you had the ability/opportunity but didn''t do it.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Modal verb"}', false, 'Form: could have + past participle.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('69efdf7d-4f88-444b-85cd-030df9c0e4d4', 429, 'gap_fill', 'C2', 'modal_perfects', 'He ___ (may / misunderstand) the instructions.', 'may have misunderstood', NULL, NULL, NULL, NULL, 'Past possibility — uncertain.', 'May have + past participle for possibility in the past (slightly more formal than might).', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Modal verb"}', false, 'Form: may have + past participle.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('d353713d-7428-42b0-bec7-e6243d1a9fb7', 431, 'gap_fill', 'C1', 'modal_perfects', 'You ___ (not / need / worry). Everything turned out fine.', 'needn''t have worried', NULL, NULL, NULL, NULL, 'You worried, but it wasn''t necessary — relief in hindsight.', 'Needn''t have worried = you worried but it was unnecessary.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Modal verb"}', false, 'Form: needn''t have + past participle.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('020fcd36-f984-4c33-af71-1dc27f9ddf1e', 433, 'gap_fill', 'C2', 'modal_perfects', 'The letter ___ (ought to / arrive) by now.', 'ought to have arrived', NULL, NULL, NULL, NULL, 'Past expectation that hasn''t materialised.', 'Ought to have + past participle: expected but possibly didn''t happen.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Modal verb"}', false, 'Form: ought to have + past participle.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('65931d19-cc9d-4efd-9975-f85dd407c070', 434, 'gap_fill', 'C1', 'modal_perfects', 'I ___ (not / should / eat) so much at dinner. I feel terrible.', 'shouldn''t have eaten', NULL, NULL, NULL, NULL, 'Past regret — done something wrong with consequences now.', 'Shouldn''t have + past participle for regret about a past action.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Modal verb"}', false, 'Form: shouldn''t have + past participle.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('973aebb7-e59b-4ae2-987e-273c75f06fef', 203, 'gap_fill', 'A1', 'present_simple', 'They ___ (work) in a hospital.', 'work', NULL, NULL, NULL, NULL, 'They/we/you don''t add -s.', 'Present simple with they: use the base verb.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Present tense"}', false, 'Only he/she/it gets the -s.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('ac5cf53a-bc9a-45e8-a92e-33cea6f8515d', 206, 'gap_fill', 'A1', 'present_simple', 'My mother ___ (teach) at a school.', 'teaches', NULL, NULL, NULL, NULL, 'Verbs ending in -ch take -es in 3rd person.', 'Verbs ending in -ch: add -es for third person.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Present tense"}', false, 'Teach → teaches. Watch → watches.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('8c00e8cd-51bb-45bf-b41b-dddb01852875', 209, 'gap_fill', 'A1', 'present_simple', 'I ___ (have) two brothers.', 'have', NULL, NULL, NULL, NULL, 'I/you/we/they use the base form.', 'Have with I/you/we/they: use have (not has).', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Present tense"}', false, 'Only he/she/it has the -s form.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('d786ef43-4d10-4a6c-aa43-43dd04dc35c4', 212, 'gap_fill', 'A1', 'present_simple', 'My dad ___ (drive) to work every day.', 'drives', NULL, NULL, NULL, NULL, 'My dad = he. Add -s.', 'Third person singular: add -s to the verb.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Present tense"}', false, 'He drives, she runs, it works.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('db4f5b3a-0c5f-4459-a06a-416bd376e407', 213, 'gap_fill', 'A1', 'present_simple', 'I ___ (not understand) this word.', 'don''t understand', NULL, NULL, NULL, NULL, 'I + don''t + verb.', 'Negative present simple: don''t + base verb.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Present tense"}', false, 'Don''t = do not.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('ba0b141c-aee8-4243-8699-6f5bd98104e5', 215, 'gap_fill', 'A1', 'present_simple', 'The sun ___ (rise) in the east.', 'rises', NULL, NULL, NULL, NULL, 'The sun = it. Add -s.', 'Present simple for general truths and facts.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Present tense"}', false, 'Like: it rises, it sets, it shines.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('17f561a3-fc30-4129-b5d1-49cd23c2fa85', 216, 'gap_fill', 'A1', 'present_continuous', 'I ___ (read) a book right now.', 'am reading', NULL, NULL, NULL, NULL, 'Action happening right now — present continuous.', 'Present continuous: am/is/are + verb-ing. For actions happening now.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Present tense"}', false, 'Form: am/is/are + verb-ing.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('4abb7d85-7c84-4901-988f-f3fec0093ef0', 217, 'gap_fill', 'A1', 'present_continuous', 'She ___ (not sleep) at the moment.', 'isn''t sleeping', NULL, NULL, NULL, NULL, 'She → is + not + verb-ing.', 'Negative present continuous: isn''t + verb-ing.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Present tense"}', false, 'Isn''t = is not.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('e0ed1a3a-bea4-4cae-8556-514e11cb16e9', 218, 'gap_fill', 'A1', 'present_continuous', 'They ___ (play) football in the park.', 'are playing', NULL, NULL, NULL, NULL, 'They → are + verb-ing.', 'Present continuous with they: are + verb-ing.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Present tense"}', false, 'They are playing, we are watching.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('3f48f58a-2e24-4a1a-ac83-d10bdf57af29', 219, 'gap_fill', 'A2', 'present_continuous', 'What ___ you doing this weekend?', 'are', NULL, NULL, NULL, '[{"answer": "are doing", "feedback": "Correct — the two blanks together make are...doing, the present continuous for future plans."}]', 'Question + you → ___ + you + verb-ing?', 'Present continuous for future plans already arranged.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Present tense"}', false, 'What ___ you doing?', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('5e10af30-d631-4a90-b515-53b9e7484b00', 220, 'gap_fill', 'A1', 'present_continuous', 'He ___ (sit) in the garden.', 'is sitting', NULL, NULL, NULL, NULL, 'He → is + verb-ing.', 'Present continuous: is + verb-ing. Double the final consonant: sit → sitting.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Present tense"}', false, 'Sit → sitting (the t doubles).', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('473bfe91-29b7-4ef2-9eac-aa5d774039d7', 224, 'gap_fill', 'A1', 'present_continuous', 'Look! It ___ (rain).', 'is raining', NULL, NULL, NULL, NULL, '"Look!" — happening right now.', 'Present continuous for things happening at the moment of speaking.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Present tense"}', false, 'Form: is + verb-ing.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('f5a0b974-f97f-4f71-8162-25a91e573800', 225, 'gap_fill', 'A2', 'present_continuous', '___ she coming to the party tonight?', 'Is', NULL, '["Will...come"]', 'Future simple is also ok here', NULL, 'Question with she — short verb first.', 'Questions in present continuous: Is + subject + verb-ing.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Present tense"}', false, '___ + she + coming?', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('23d16345-056c-43ac-bd94-5fb81e5a92dd', 232, 'gap_fill', 'A2', 'past_simple', 'I ___ (not know) the answer, but now I do.', 'didn''t know', NULL, NULL, NULL, NULL, 'Past negative — didn''t + base verb.', 'Past simple negative: didn''t + base verb.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Past tense"}', false, 'Didn''t + know (not "didn''t knew").', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('00fda781-5c24-4ac8-887f-9752a213e331', 235, 'gap_fill', 'A2', 'past_simple', 'What ___ you do last weekend?', 'did', NULL, NULL, NULL, NULL, 'Past question with "what".', 'Past simple questions: did + subject + base verb.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Past tense"}', false, 'What + ___ + you + base verb?', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('4e36e2f4-6aa8-4d82-a911-055bb9b34ccd', 236, 'gap_fill', 'A2', 'past_simple', 'We ___ (eat) pizza for dinner.', 'ate', NULL, NULL, NULL, NULL, 'Past simple — what we ate.', 'Eat is irregular: eat → ate → eaten.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Past tense"}', false, 'Eat → ate. Irregular.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('807e35d1-4032-4075-ab45-ec63e38f9e78', 237, 'gap_fill', 'A2', 'past_simple', 'I ___ (wake) up late this morning.', 'woke', NULL, '["got"]', 'Got is fine, but uses a different verb.', NULL, 'Past simple — when you woke up.', 'Wake is irregular: wake → woke → woken.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Past tense"}', false, 'Wake → woke. Irregular.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('b5bfd738-597e-42d0-bf1f-c8ba8dd0010a', 238, 'gap_fill', 'A2', 'past_simple', 'She ___ (study) French at university when she was young.', 'studied', NULL, NULL, NULL, NULL, 'Past simple of "study".', 'Verbs ending in consonant + y: change y to -ied.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Past tense"}', false, 'Consonant + y → -ied: study → studied.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('be956fa2-6345-44c6-8337-355689019b1c', 239, 'gap_fill', 'A2', 'past_simple', 'He ___ (leave) the office early last Friday.', 'left', NULL, NULL, NULL, NULL, '"Last Friday" — past simple.', 'Leave is irregular: leave → left → left.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Past tense"}', false, 'Leave → left. Irregular.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('cdffa396-8a0c-405c-ac27-3d2ca837e80c', 240, 'gap_fill', 'A2', 'past_simple', 'The children ___ (play) in the garden all afternoon.', 'played', NULL, NULL, NULL, NULL, 'Past simple of "play" — regular verb.', 'Regular past simple: add -ed to the base verb.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Past tense"}', false, 'Verb + -ed for regular past simple.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('749beca2-41fa-458d-b9a1-43c68ecf9fe3', 249, 'gap_fill', 'A1', 'articles', 'Is there ___ bank near here?', 'a', NULL, NULL, NULL, NULL, 'First mention, countable noun.', 'Use a when talking about one of many (any bank).', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{Article}', false, 'A bank = one bank (you don''t know which).', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('b9199fac-5434-4bd7-965e-523a9d422dff', 253, 'gap_fill', 'A1', 'prepositions_of_time', 'I don''t work ___ Sundays.', 'on', NULL, NULL, NULL, NULL, 'Days of the week take a particular preposition.', 'Use on with days: on Sunday, on Monday.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Preposition of time"}', false, '___ Sunday, ___ Friday, ___ Monday.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('7113bacc-dffb-4252-9c4f-71e9430d1497', 254, 'gap_fill', 'A2', 'prepositions_of_time', 'She was born ___ 1995.', 'in', NULL, NULL, NULL, NULL, 'Years take a particular preposition.', 'Use in with years: in 1995, in 2020.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Preposition of time"}', false, '___ 1995, ___ 2010, ___ 2026.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('14a45468-155d-4851-a56c-9d763cbeb3ea', 257, 'gap_fill', 'A1', 'prepositions_of_time', 'I go to bed ___ night.', 'at', NULL, NULL, NULL, NULL, '"Night" takes its own preposition (one of the few exceptions).', 'Use at with night: at night (not in night).', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Preposition of time"}', false, '___ night. (But: in the morning, in the afternoon, in the evening.)', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('b6aebd34-6567-4c05-ad24-8c5bcda1e9da', 259, 'gap_fill', 'A1', 'prepositions_of_time', 'It''s very cold ___ winter.', 'in', NULL, NULL, NULL, NULL, 'Seasons take a particular preposition.', 'Use in with seasons: in winter, in summer.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Preposition of time"}', false, '___ summer, ___ winter, ___ spring.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('f015c55c-0d78-4b92-a0d1-3305f353c861', 260, 'gap_fill', 'A2', 'prepositions_of_time', 'I''ll see you ___ two weeks.', 'in', NULL, NULL, NULL, NULL, '"After X time from now" → a particular preposition.', 'Use in for future time periods: in two weeks, in an hour.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Preposition of time"}', false, '___ two weeks = two weeks from now.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('df771371-83df-42d9-bd8a-e4125bd0f31f', 2048, 'gap_fill', 'C1', 'bathroom_vocabulary', 'If a customer installs a product themselves without using a qualified plumber, it may _______ the warranty.', 'void', NULL, NULL, NULL, NULL, 'To make a contract or guarantee legally invalid — to cancel its protection.', 'To void a warranty means to make it invalid. Most manufacturers require professional installation to keep the warranty in force.', '2026-04-16 07:40:24.456408+00', NULL, NULL, 'en', '{}', false, 'Single word. Starts with v___.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('55e75a98-06c0-4bb5-a44b-76efad5462a2', 261, 'gap_fill', 'A1', 'prepositions_of_place', 'The cat is ___ the table.', 'on', NULL, NULL, NULL, NULL, 'On a horizontal surface (the cat sits on top).', 'On = on top of the surface. Under = below.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Preposition of place"}', false, '___ the table, ___ the floor.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('a5e97fd5-4873-4efc-a582-cbc4857422a1', 263, 'gap_fill', 'A1', 'prepositions_of_place', 'I''ll meet you ___ the bus stop.', 'at', NULL, NULL, NULL, NULL, 'Specific point — meeting place.', 'Use at with specific points or locations.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Preposition of place"}', false, '___ the bus stop, ___ the door, ___ the corner.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('53697f20-6e27-4f2d-9a1a-884a23e0c861', 264, 'gap_fill', 'A1', 'prepositions_of_place', 'The picture is ___ the wall.', 'on', NULL, NULL, NULL, NULL, 'On a vertical surface.', 'Use on with surfaces: on the wall, on the floor.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Preposition of place"}', false, '___ the wall, ___ the ceiling, ___ the door.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('168e04de-e384-4081-9758-bde6a0c3d559', 265, 'gap_fill', 'A2', 'prepositions_of_place', 'The bank is ___ the supermarket and the pharmacy.', 'between', NULL, NULL, NULL, NULL, 'Two things on either side.', 'Between shows position in the middle of two things.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Preposition of place"}', false, '___ A and B — paired with "and".', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('17544e4c-0749-4629-87fc-64659941fbdb', 267, 'gap_fill', 'A2', 'prepositions_of_place', 'The restaurant is ___ front of the cinema.', 'in', NULL, NULL, NULL, NULL, 'Phrase: "___ front of".', 'In front of = on the opposite side from behind.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Preposition of place"}', false, '___ front of, ___ the middle of, ___ the corner of.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('346f782a-be23-4f61-b1e2-9d7f55f44163', 268, 'gap_fill', 'A1', 'prepositions_of_place', 'There are books ___ the shelf.', 'on', NULL, NULL, NULL, NULL, 'Books rest on a horizontal surface.', 'Use on with shelves and surfaces.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Preposition of place"}', false, '___ a shelf, ___ a table.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('6ba720d8-246e-4b66-b5b2-6c152589f68f', 269, 'gap_fill', 'A2', 'prepositions_of_place', 'The pharmacy is ___ to the bakery.', 'next', NULL, NULL, NULL, NULL, 'Phrase: "___ to" = beside.', 'Next to = very close, beside.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Preposition of place"}', false, '___ to = right beside.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('aa86a31a-edcd-4b92-8111-1ee8998147f9', 270, 'gap_fill', 'A1', 'prepositions_of_place', 'The keys are ___ my bag.', 'in', NULL, NULL, NULL, NULL, 'Inside the bag.', 'Use in with containers and enclosed spaces.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Preposition of place"}', false, '___ = inside something.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('db4d06f2-494f-4cff-94b5-d8a9d3611000', 280, 'gap_fill', 'A1', 'there_is_there_are', '___ three bedrooms in my flat.', 'There are', NULL, NULL, NULL, NULL, 'Three bedrooms — plural.', 'There are + plural noun.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"There is/are"}', false, '___ + plural noun.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('cfd8dcb7-704b-4f94-927c-2c290c4b9a3e', 281, 'gap_fill', 'A1', 'there_is_there_are', '___ any milk in the fridge?', 'Is there', NULL, NULL, NULL, NULL, 'Question with singular.', 'Questions: Is there + singular/uncountable noun.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"There is/are"}', false, '___ + a/any + singular noun?', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('93c2a0f4-3941-4457-9dda-713da0b49d3a', 282, 'gap_fill', 'A1', 'there_is_there_are', '___ any shops on this street?', 'Are there', NULL, NULL, NULL, NULL, 'Question with plural.', 'Questions: Are there + plural noun.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"There is/are"}', false, '___ + any + plural noun?', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('71c059a7-bc9a-4d81-a60e-361db31250fe', 283, 'gap_fill', 'A1', 'there_is_there_are', 'There ___ (not be) a garden.', 'isn''t', NULL, NULL, NULL, NULL, 'Negative — there + is + not.', 'Negative: There isn''t + singular noun.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"There is/are"}', false, 'Isn''t = is not.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('23046b22-d9da-4957-a9ac-4886eeb56f52', 284, 'gap_fill', 'A2', 'there_is_there_are', 'There ___ (not be) any restaurants near the hotel.', 'aren''t', NULL, NULL, NULL, NULL, 'Plural negative.', 'Negative plural: There aren''t + plural noun.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"There is/are"}', false, 'Aren''t = are not.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('768e437e-cb66-4486-974f-e29030ca897e', 285, 'gap_fill', 'A1', 'there_is_there_are', '___ a park in your town?', 'Is there', NULL, NULL, NULL, NULL, 'Question form, singular.', 'Yes/No questions: Is there...? / Are there...?', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"There is/are"}', false, '___ + a + park?', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('f695996a-4213-4b0d-947b-80332e851896', 294, 'gap_fill', 'A2', 'comparatives', 'He runs ___ (fast) than his brother.', 'faster', NULL, NULL, NULL, NULL, 'Short adjective + -er.', 'Short adjectives/adverbs: add -er for comparatives.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{Comparative}', false, 'Fast → faster.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('7938474c-24af-4b1f-82ff-7defc21d5921', 295, 'gap_fill', 'A2', 'superlatives', 'It was the ___ (happy) day of my life.', 'happiest', NULL, NULL, NULL, NULL, 'Adjective ending in -y changes spelling.', 'Adjectives ending in -y: change to -iest. Happy → happiest.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{Superlative}', false, 'Happy → happiest.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('94aa452d-905a-40a0-9cec-6e476d1249cc', 250, 'multiple_choice', 'A2', 'articles', 'I love ___ chocolate.', '(no article)', '["a", "the", "those", "(no article)"]', NULL, NULL, NULL, 'General love of an uncountable thing → no article needed.', 'We don''t use an article before uncountable nouns when talking about them in general: "I love chocolate", "She drinks coffee", "He likes music".', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{Article}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('6901d99e-c9f0-4594-9a1c-bb4d4cd21838', 276, 'gap_fill', 'A2', 'can_and_cant', '___ I use your phone?', 'Can', NULL, NULL, NULL, '[{"answer": "May", "feedback": "\"May I\" is more formal — also correct, just a different register."}]', 'Asking permission with the same word as ability.', '''Can'' is most common and informal. ''Could'' is a little more polite. ''May'' is the most formal and polite option.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Modal verb"}', false, '___ I + base verb?', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('739f0e03-9bcc-4448-972a-427f2690b782', 297, 'gap_fill', 'A1', 'have_got', 'She ___ (h... got) blue eyes.', 'has got', NULL, NULL, 'British English uses have/has got, where Americans use have/has.', NULL, 'She/he/it → ___ + got.', 'He/she/it has got for third person.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Have got"}', false, '"Has", not "have", for he/she/it.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('94dddddf-9358-45e1-a591-5fc1b6323887', 298, 'gap_fill', 'A1', 'have_got', '___ you got any brothers?', 'Have', NULL, NULL, 'British English uses have/has got, where Americans use have/has.', NULL, 'Question form: ___ you got...?', 'Questions: Have + subject + got...?', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Have got"}', false, '___ + you + got + ...?', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('e25b911d-8433-4341-973b-15e3f82c0e31', 299, 'gap_fill', 'A1', 'have_got', 'He ___ (not h... got) a car.', 'hasn''t got', NULL, NULL, 'British English uses have/has got, where Americans use have/has.', NULL, 'He + ___ + got — negative.', 'Negative: hasn''t got / haven''t got.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Have got"}', false, 'Hasn''t = has not.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('93538c69-1cb4-4043-825b-c2c84272b86e', 300, 'gap_fill', 'A1', 'have_got', 'We ___ (not h... got) any homework today.', 'haven''t got', NULL, NULL, 'British English uses have/has got, where Americans use have/has.', NULL, 'We + ___ + got — negative.', 'Haven''t got = don''t have.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Have got"}', false, 'Haven''t = have not.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('bc97ba6f-6d42-4b3f-a6a1-f7fd7eb359c0', 435, 'gap_fill', 'C1', 'advanced_passive', 'The new policy is said ___ (benefit) thousands of workers.', 'to benefit', NULL, NULL, NULL, NULL, '"X is said ___ Y" — passive reporting structure.', 'Impersonal passive: Subject + is said/believed/thought + to + infinitive.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Passive voice"}', false, 'Form: be said + to + base verb.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('b5027639-61e2-4a58-b13e-ce51c04fe31e', 436, 'gap_fill', 'C1', 'advanced_passive', 'He is believed ___ (leave) the country last week.', 'to have left', NULL, NULL, NULL, NULL, 'Past action in passive reporting structure.', 'Impersonal passive with past reference: is believed + to have + past participle.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Passive voice"}', false, 'Form: be believed + to have + past participle.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('f470558e-522d-40f1-b752-ca95c0f925a8', 437, 'gap_fill', 'C2', 'advanced_passive', 'The suspect is thought ___ (hide) in the mountains at the moment.', 'to be hiding', NULL, '["to be in hiding"]', NULL, NULL, 'Ongoing action in passive reporting structure.', 'Impersonal passive + continuous: is thought + to be + verb-ing.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Passive voice"}', false, 'Form: be thought + to be + verb-ing.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('7954114a-c723-40d4-9caf-b51af0e2ef52', 438, 'gap_fill', 'C1', 'advanced_passive', 'The building ___ (demolish) by the time we arrived.', 'had been demolished', NULL, NULL, NULL, NULL, 'Action completed before another past action — passive.', 'Past perfect passive: had been + past participle.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Passive voice"}', false, 'Form: had been + past participle.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('70b4e724-424e-4a42-8f91-62c9003d1448', 439, 'gap_fill', 'C1', 'advanced_passive', 'She doesn''t like ___ (tell) what to do.', 'being told', NULL, NULL, NULL, NULL, 'Passive form after a verb of liking/disliking.', 'Passive gerund: being + past participle after verbs like like, hate, enjoy.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Passive voice"}', false, 'Form: being + past participle.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('9caea07b-f114-42f3-b5ab-e70be6aed0f1', 440, 'gap_fill', 'C2', 'advanced_passive', 'The proposal is expected ___ (approve) by the board tomorrow.', 'to be approved', NULL, NULL, NULL, NULL, 'Passive infinitive after "expected".', 'Impersonal passive + passive infinitive: is expected + to be + past participle.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Passive voice"}', false, 'Form: to be + past participle.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('f995dfb3-8ba0-411f-9d40-b91f625f0c6a', 441, 'gap_fill', 'C1', 'advanced_passive', 'They want ___ (promote) by the end of the year.', 'to be promoted', NULL, '["a promotion"]', 'An alternative structure, says the same thing.', NULL, 'Want + passive infinitive.', 'Passive infinitive: to be + past participle after want, expect, hope.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Passive voice"}', false, 'Form: to be + past participle.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('f5653194-849b-41e8-b946-edd28b163658', 442, 'gap_fill', 'C1', 'advanced_passive', 'Having ___ (inform) of the changes, the staff adapted quickly.', 'been informed', NULL, NULL, NULL, NULL, 'Perfect passive participle clause — passive + completed.', 'Perfect passive participle: Having been + past participle.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Passive voice"}', false, 'Form: Having been + past participle.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('ce555b13-f404-4849-afd8-0d86bd66efff', 446, 'gap_fill', 'C1', 'collocations', 'We need to ___ into account all the possible risks.', 'take', NULL, NULL, NULL, NULL, 'Phrase: "___ into account" = consider.', 'Take into account = consider. A very common formal collocation.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{Collocation}', false, 'Same verb as in "___ measures" and "___ steps".', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('f2c9f090-91e6-48b0-9c06-350fdc70e153', 447, 'gap_fill', 'C1', 'collocations', 'The news ___ a huge impact on the stock market.', 'had', NULL, NULL, NULL, NULL, '"___ an impact" — the same verb as for events affecting things.', 'Have an impact on = affect or influence something significantly.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{Collocation}', false, '___ an impact, ___ an effect, ___ an influence.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('a1880fa4-effa-418f-b868-f81f96935d87', 448, 'gap_fill', 'C2', 'collocations', 'The government is ___ under pressure to reform the healthcare system.', 'coming', NULL, NULL, NULL, NULL, 'Idiom: "be ___ under pressure" = receiving pressure.', 'Come under pressure = face increasing demands to do something.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{Collocation}', false, 'Form: be + verb-ing + under pressure.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('1d3d1989-a1a5-4f9a-b366-de1552eff9e6', 449, 'gap_fill', 'C1', 'collocations', 'I''d like to ___ your attention to the safety instructions.', 'draw', NULL, NULL, NULL, NULL, '"___ attention to" — formal phrase for highlighting.', 'Draw attention to = make people notice something important.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{Collocation}', false, 'Same verb as in "___ a conclusion" and "___ a parallel".', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('f4301a47-603b-454c-8eb7-324d0718a340', 450, 'gap_fill', 'C1', 'collocations', 'We must ___ priority to the most urgent cases.', 'give', NULL, NULL, NULL, NULL, '"___ priority to" — common phrase.', 'Give priority to = treat something as most important.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{Collocation}', false, '___ priority, ___ permission, ___ advice — same verb.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('a7214dfe-c3ca-4176-b609-55dea2903e72', 451, 'gap_fill', 'C1', 'collocations', 'The committee has ___ to the conclusion that changes are needed.', 'come', NULL, NULL, NULL, NULL, '"___ to a conclusion" — verb of arrival.', 'Come to a conclusion / reach a conclusion = decide after consideration.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{Collocation}', false, '___ to a conclusion, ___ to an agreement, ___ to a decision.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('4b8b293d-71b8-4e62-b7a3-b375fa1e4e6a', 452, 'gap_fill', 'C2', 'collocations', 'The results ___ a sharp contrast with last year''s figures.', 'draw', NULL, NULL, NULL, NULL, '"___ a contrast" — formal phrase for highlighting differences.', 'Draw/present a contrast = show differences between two things.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{Collocation}', false, 'Same verb as ___ a comparison, ___ a parallel.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('3739ea1a-dcbe-4b7a-90cc-d8198e6337fb', 453, 'gap_fill', 'C1', 'collocations', 'She ___ a key role in the success of the project.', 'played', NULL, NULL, NULL, NULL, '"___ a role" — common pairing.', 'Play a role in = contribute to, be involved in.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{Collocation}', false, '___ a role, ___ a part — like in theatre.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('76420909-2d40-4ee3-ac03-eb2df4d58c58', 1089, 'multiple_choice', 'A1', 'business_vocabulary', 'Your _______ is the money you receive each month for your work.', 'salary', '["salary", "budget", "bonus", "revenue"]', NULL, NULL, NULL, 'A fixed monthly amount — not a bonus, not total company income.', 'A salary is a fixed regular payment, usually monthly. Compare: wage = typically paid weekly or hourly; bonus = extra payment for good performance.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Business vocabulary","HR vocabulary","Confusable words"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('7e5b24c8-bfb1-4af3-b0e2-0c628eabbf07', 1090, 'multiple_choice', 'A1', 'business_vocabulary', 'A _______ is a person who owns part of a company.', 'shareholder', '["shareholder", "stakeholder", "creditor", "debtor"]', NULL, NULL, NULL, 'The clue is in the word — they own part of something specific.', 'A shareholder owns shares in a company and has a financial stake in its profits. A stakeholder is broader — anyone affected by the company''s activities, including employees and customers.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Business vocabulary","Confusable words"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('62c989ca-3082-43f6-af81-ca242cf89919', 1091, 'multiple_choice', 'A1', 'business_vocabulary', 'A written plan that shows how money will be spent is called a _______.', 'budget', '["budget", "invoice", "receipt", "forecast"]', NULL, NULL, NULL, 'It''s a *plan*, not a prediction, a receipt, or a request for payment.', 'A budget is a financial plan — what money is available and how it will be spent. Compare: forecast = a prediction of future financial performance; invoice = a request for payment.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Business vocabulary","Financial vocabulary"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('94bbf101-9df6-4168-97c5-ec0b8535df7f', 1526, 'multiple_choice', 'A1', 'business_vocabulary', 'A(n) _____ is a written list of goods or services provided, with the amount owed.', 'invoice', '["invoice", "receipt", "contract", "payslip"]', NULL, NULL, NULL, 'Sent *before* payment, not given *after* payment.', 'An invoice is sent by a supplier to request payment. A receipt is given after payment has been made. Both are essential documents in business.', '2026-03-26 08:02:12.742714+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('40c0edf6-7327-4f6c-b3dc-1873503cbde4', 1527, 'multiple_choice', 'A1', 'business_vocabulary', 'A _____ is a legal agreement between two or more people or companies.', 'contract', '["contract", "deadline", "memo", "brief"]', NULL, NULL, NULL, 'You sign this at the start of a working relationship.', 'A contract is a binding legal agreement. It sets out the terms and conditions that all parties must follow. Always read a contract carefully before signing.', '2026-03-26 08:02:12.742714+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('d5f36441-9930-446b-a82d-8bf4b02fd963', 1528, 'multiple_choice', 'A1', 'business_vocabulary', 'The _____ is the latest time by which a piece of work must be finished.', 'deadline', '["deadline", "schedule", "agenda", "target"]', NULL, NULL, NULL, 'Literally: the *line* by which something is *due*.', 'A deadline is the latest date or time by which something must be completed. Missing a deadline can have serious consequences in business.', '2026-03-26 08:02:12.742714+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('7eb7824d-852f-4eca-bb2b-5f3b1d597465', 1529, 'multiple_choice', 'A1', 'business_vocabulary', 'A person you work with is called a _____.', 'colleague', '["colleague", "companion", "supplier", "employer"]', NULL, NULL, NULL, 'Someone in the same workplace — not a friend, not a supplier.', 'A colleague is someone you work with. A companion is a person who accompanies you in something. A supplier provides goods or services. An employer is the company or person who employs you.', '2026-03-26 08:02:12.742714+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('3938bf76-33ad-4719-a031-aacd857bad2a', 1530, 'multiple_choice', 'A1', 'business_vocabulary', 'The _____ is the total amount of money a business receives from sales over a period of time.', 'turnover', '["turnover", "profit", "salary", "commission"]', NULL, NULL, NULL, 'Not the profit — it''s the full amount coming in before costs.', 'Turnover (also called revenue or sales) is the total income generated before costs are deducted. Profit is what remains after all costs have been subtracted from turnover.', '2026-03-26 08:02:12.742714+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('52e19c11-16a0-4fd3-a3bd-c04a6e89f461', 1097, 'multiple_choice', 'B1', 'business_vocabulary', 'The company decided to focus on its most profitable products and _______ its operations.', 'streamline', '["streamline", "downsize", "restructure", "outsource"]', NULL, NULL, NULL, 'Making things *simpler and more efficient* — not cutting staff or reorganising.', 'To streamline operations means to simplify and make more efficient — removing unnecessary steps or roles. Compare: downsize = to reduce the size of the workforce; restructure = to reorganise departments or reporting lines.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Business vocabulary"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('dfcf8bd8-cf5c-4082-8672-657065277978', 308, 'multiple_choice', 'A2', 'present_simple', 'The train ___ at 6:30.', 'leaves', '["leave", "leaves", "leaving", "is leave"]', NULL, NULL, NULL, 'The train = it. Add -s.', 'Present simple for timetables and schedules.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Present tense"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('1c202815-c33a-4320-8d00-d5c93eada6fa', 309, 'multiple_choice', 'A1', 'present_simple', 'I ___ from Italy.', 'am', '["is", "am", "are", "be"]', NULL, NULL, NULL, 'I + verb "to be" in present.', 'To be: I am, you are, he/she is, we/they are.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Present tense"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('505a8134-25e5-4755-b545-07a505a8f665', 310, 'multiple_choice', 'A1', 'present_simple', '___ your father work here?', 'Does', '["Do", "Does", "Is", "Are"]', NULL, NULL, NULL, 'Your father = he. Question form needs an auxiliary.', 'Third person questions: Does + subject + base verb.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Present tense"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('f274f195-06e0-4394-b2ca-c1f97d669077', 311, 'multiple_choice', 'A2', 'present_simple', 'My parents ___ in a small village.', 'live', '["lives", "live", "living", "is living"]', NULL, NULL, NULL, 'My parents = they. No -s.', 'With plural subjects (parents): use the base verb.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Present tense"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('49040b98-8813-45ab-abb0-9b78887052d5', 312, 'multiple_choice', 'A1', 'present_simple', 'She ___ English and French.', 'speaks', '["speak", "speaks", "speaking", "is speak"]', NULL, NULL, NULL, 'She + verb — add -s.', 'Third person singular: add -s.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Present tense"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('351c6a31-5e46-4b10-b899-57d489d16eab', 313, 'multiple_choice', 'A2', 'present_simple', 'What ___ you do at the weekend?', 'do', '["does", "do", "are", "is"]', NULL, NULL, NULL, 'Question with "you".', 'What do you do? = asking about habits/routines.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Present tense"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('3be645b1-741b-4342-a5d1-922753585a8c', 314, 'multiple_choice', 'A1', 'present_simple', 'It ___ a lot in England.', 'rains', '["rain", "rains", "raining", "is rain"]', NULL, NULL, NULL, 'It + verb — add -s.', 'Third person (it): add -s. For facts and general truths.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Present tense"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('b22d95be-9b96-4066-8fd7-77e43fb8a19a', 315, 'multiple_choice', 'A2', 'present_simple', 'She never ___ breakfast.', 'eats', '["eat", "eats", "eating", "is eat"]', NULL, NULL, NULL, 'She + verb — add -s. (Even with "never" before it.)', 'After he/she/it + adverb of frequency: verb takes -s.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Present tense"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('5da467b7-dc49-4437-a7dd-530bdab2c3d0', 1098, 'multiple_choice', 'B1', 'business_vocabulary', 'The company has decided to _______ its IT support to an external company in Eastern Europe.', 'outsource', '["outsource", "delegate", "transfer", "subcontract"]', NULL, NULL, NULL, 'Sending work *outside* the company, to another one. Not just delegating internally.', 'To outsource means to pay an external company to do work that could be done in-house. Companies outsource to reduce costs or access specialist skills. Compare: delegate = to assign tasks to someone within the company.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Business vocabulary"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('fe8f24ca-fd6f-4460-b828-9fe6d29bc26e', 1536, 'multiple_choice', 'B1', 'business_vocabulary', 'A financial _____ is an estimate of future income and expenses over a set period.', 'forecast', '["forecast", "audit", "invoice", "projection"]', NULL, NULL, NULL, 'A prediction, not a plan. Weather people do these too.', 'A forecast is a forward-looking financial estimate. It differs from a budget in that a budget is a plan, whereas a forecast is an updated prediction based on current performance.', '2026-03-26 08:02:12.742714+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('4f249c59-5f18-481a-b260-85ec91180dc2', 1108, 'gap_fill', 'C1', 'business_vocabulary', 'A private _______ firm takes controlling stakes in companies, improves them, and sells them for a profit.', 'equity', NULL, NULL, NULL, NULL, 'The opposite of debt financing — it''s about ownership stakes.', 'Private equity refers to investment funds that take controlling stakes in private (non-listed) companies, restructure them to increase their value, and then sell them for a profit.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Business vocabulary","Financial vocabulary"}', false, 'What shareholders have in a company; also a word for fairness.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('db43740e-ad3b-4eb5-92fd-a75ff96bbe93', 1109, 'gap_fill', 'C1', 'business_vocabulary', 'The company''s current ratio fell below 1.0 for the first time, raising serious _______ concerns.', 'liquidity', NULL, NULL, NULL, NULL, 'Being able to pay short-term bills — how easily assets turn into cash.', 'Liquidity refers to a company''s ability to meet its short-term financial obligations. A current ratio below 1.0 means current liabilities exceed current assets — a warning sign.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Business vocabulary","Financial vocabulary"}', false, 'If you can sell something quickly without losing value, it has high _______.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('32d6ad65-3b8a-4b17-99a9-75967d504a35', 1110, 'gap_fill', 'C1', 'business_vocabulary', 'The new product created a genuine competitive _______, protecting the company''s market position for years.', 'advantage', NULL, NULL, NULL, NULL, 'A common pairing with "competitive" — what gives you the edge.', 'A competitive advantage is something that allows a company to outperform its rivals — lower costs, a unique product, a strong brand, or proprietary technology.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Business vocabulary",Collocation}', false, NULL, 'noun');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('a1f11ad6-4efa-497d-8df2-3cd2192d333d', 1111, 'gap_fill', 'C1', 'business_vocabulary', 'Companies in highly regulated sectors must ensure full _______ with all applicable laws and industry standards.', 'compliance', NULL, NULL, NULL, NULL, 'Acting *in line with* rules. The verb is "to comply".', 'Compliance means acting in accordance with all relevant laws, regulations, and internal policies. Compliance departments exist specifically to manage this in regulated industries.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Business vocabulary"}', false, 'What you''d be in if you followed every regulation perfectly.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('f75ee8fc-eeb6-46ab-8526-15afb802465b', 316, 'multiple_choice', 'A1', 'present_continuous', 'Sshhhhhh, be quiet! The baby ___.', 'is sleeping', '["sleeps", "is sleeping", "sleep", "sleeping"]', NULL, NULL, NULL, 'Right now (the baby is asleep) — present continuous.', 'Present continuous: is + verb-ing for something happening now.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Present tense"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('98711e11-b18e-4a2b-afc5-297e1471db82', 317, 'multiple_choice', 'A1', 'present_continuous', 'What are you ___?', 'doing', '["do", "does", "doing", "did"]', NULL, NULL, NULL, '"Are you" → present continuous, needs verb-ing.', 'Present continuous question: What are you doing?', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Present tense"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('c5111c65-429b-43f1-94c3-8f2db04902ce', 318, 'multiple_choice', 'A2', 'present_continuous', 'They ___ a new house at the moment.', 'are building', '["build", "are building", "builds", "building"]', NULL, NULL, NULL, '"At the moment" — happening right now.', 'Present continuous for actions in progress around now.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Present tense"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('2fe2a9f4-2f45-44ed-91ae-94e69e30f18d', 319, 'multiple_choice', 'A1', 'present_continuous', 'She ___ right now. Can I take a message?', 'is working', '["works", "is working", "work", "working"]', NULL, NULL, NULL, '"Right now" — happening at this moment.', 'Right now = happening at this moment → present continuous.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Present tense"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('3105237a-1310-48bd-ab34-a1e388820adc', 320, 'multiple_choice', 'A2', 'present_continuous', 'I ___ a really good book this week.', 'am reading', '["read", "am reading", "reads", "reading"]', NULL, NULL, NULL, '"This week" — ongoing, present continuous.', 'Present continuous for temporary situations around now.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Present tense"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('ac587346-a194-49d3-9ff8-1c2b56c130f7', 321, 'multiple_choice', 'A1', 'present_continuous', 'The children ___ in the garden.', 'are playing', '["play", "plays", "are playing", "is playing"]', NULL, NULL, NULL, 'Children = they → are + verb-ing.', 'Plural subject (children) + are + verb-ing.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Present tense"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('4ccd6d5c-1b8e-4287-8a9b-b3bc978363ac', 322, 'multiple_choice', 'A2', 'present_continuous', 'He ___ to the gym today. He''s ill.', 'isn''t going', '["doesn''t go", "isn''t going", "don''t go", "not going"]', NULL, NULL, NULL, '"Today" + he''s ill = not going. Negative present continuous.', 'Negative present continuous: isn''t + verb-ing.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Present tense"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('681558b2-1f7d-4e7f-8ec2-2b7aa84216d9', 332, 'multiple_choice', 'A2', 'past_simple', 'I ___ a sandwich for lunch.', 'had', '["have", "has", "had", "having"]', NULL, NULL, NULL, 'Past simple of "have".', 'Have is irregular: have → had. Past actions.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Past tense"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('64898632-54e0-4552-bd37-0a5e4ec01d90', 333, 'multiple_choice', 'A2', 'past_simple', 'Where ___ you go on holiday?', 'did', '["do", "did", "was", "were"]', NULL, NULL, NULL, 'Past question with "where".', 'Where did you go? Past simple question structure.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Past tense"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('3b886898-2854-4e95-9bdb-c8042ffd664d', 338, 'multiple_choice', 'A2', 'past_simple', 'He ___ me a present for my birthday.', 'gave', '["give", "gave", "given", "giving"]', NULL, NULL, NULL, 'Past simple of "give" — irregular.', 'Give is irregular: give → gave → given.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Past tense"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('423004e5-75d6-4197-b495-2dd829fe588a', 339, 'multiple_choice', 'A2', 'past_simple', '___ there many people at the concert?', 'Were', '["Was", "Were", "Did", "Do"]', NULL, NULL, NULL, 'Question with "there" + plural in past.', 'There were (plural) / There was (singular) for past.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Past tense"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('be46389f-6905-4252-86b1-10d05ec6844f', 711, 'odd_one_out', 'C1', 'idioms', 'Which idiom does NOT relate to success?', 'break the ice', '["hit the nail on the head", "break the ice", "make headway", "bear fruit"]', NULL, NULL, NULL, NULL, '"Break the ice" means to start a conversation in a social setting, not about success.', '2026-02-20 19:09:17.848852+00', NULL, NULL, 'en', '{"Fixed expression"}', true, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('845e4f00-bb26-4dc9-a9fa-3608838ad675', 1159, 'odd_one_out', 'B1', 'idioms', 'Which of these idioms does NOT mean to avoid or delay something?', 'face the music', '["beat around the bush", "drag your feet", "sit on the fence", "face the music"]', NULL, NULL, NULL, NULL, '"Face the music" means to accept the consequences of your actions. The others — beat around the bush, drag your feet, and sit on the fence — all suggest avoiding or delaying something.', '2026-03-16 08:29:27.085219+00', NULL, NULL, 'en', '{}', true, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('f080553b-55e8-4f60-8e74-82fbb4d640c4', 1169, 'odd_one_out', 'C1', 'idioms', 'Which of these expressions does NOT suggest that someone is being evasive?', 'an open book', '["beating around the bush", "economising with the truth", "an open book", "sitting on the fence"]', NULL, NULL, NULL, NULL, '"An open book" describes someone who is transparent and easy to understand — not evasive. Beating around the bush, economising with the truth, and sitting on the fence all suggest a reluctance to be direct.', '2026-03-16 08:29:27.085219+00', NULL, NULL, 'en', '{}', true, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('bd469c87-4f87-4761-8d1c-9b188ff404c0', 1095, 'multiple_choice', 'A2', 'business_vocabulary', 'When two companies join together to form one new company, it is called a _______.', 'merger', '["merger", "takeover", "acquisition", "partnership"]', NULL, NULL, NULL, 'Two into one, equally. A takeover is one-sided.', 'A merger is when two companies combine to form one new company. A takeover (or acquisition) is when one company buys another — the bought company loses its independence.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Business vocabulary","Confusable words"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('d50f2e9c-bf3f-4dc7-bc00-3d29a2a4f55a', 1096, 'multiple_choice', 'A2', 'business_vocabulary', 'A formal request for a job is called a job _______.', 'application', '["application", "interview", "contract", "proposal"]', NULL, NULL, NULL, 'The document you send *first*, before anything else happens.', 'A job application is the formal process of applying for a position — usually a written form plus a CV. Compare: interview = the next stage; contract = the agreement signed if you are offered the job.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Business vocabulary","HR vocabulary"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('288a5dbe-3ee2-4956-8c56-bb612a4ca926', 1535, 'multiple_choice', 'A2', 'business_vocabulary', 'The person or company that buys goods or services from a business is called a _____.', 'client', '["client", "supplier", "shareholder", "contractor"]', NULL, NULL, NULL, 'They *pay* the business. Not the one supplying goods to it.', 'A client (or customer) is the person or organisation that purchases goods or services. A supplier provides goods or services to the business. Keeping clients satisfied is central to any business.', '2026-03-26 08:02:12.742714+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('5b052a00-c4ce-4b40-a82d-aa0a442307ff', 1130, 'multiple_choice', 'B1', 'bathroom_vocabulary', 'A shower room where the floor is waterproofed and slopes to a drain, with no tray or door, is called a _______ room.', 'wet', '["wet", "open", "drain", "level"]', NULL, NULL, NULL, '___ room — a fully waterproof bathroom with no shower tray.', 'A wet room is a fully waterproofed bathroom where the shower has no enclosure — the floor is graded to a drain. It is a popular choice in contemporary bathroom design.', '2026-03-11 18:12:09.553883+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('785c40ba-c669-42c2-9225-9204fbe1ac8d', 1131, 'multiple_choice', 'B1', 'bathroom_vocabulary', 'A piece of bathroom furniture that combines a sink with storage cupboards underneath is called a _______ unit.', 'vanity', '["vanity", "storage", "basin", "cabinet"]', NULL, NULL, NULL, 'A unit combining sink and storage — also a furniture piece for makeup.', 'A vanity unit combines a basin with a cabinet below, providing storage and a clean, finished look. It is a standard feature in both contemporary and traditional bathroom designs.', '2026-03-11 18:12:09.553883+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('fa634673-153a-45ab-8516-9280c5597613', 1099, 'multiple_choice', 'B2', 'business_vocabulary', 'The sudden resignation of the CEO had a significant _______ effect on the company''s share price.', 'knock-on', '["knock-on", "follow-on", "carry-on", "spin-off"]', NULL, NULL, NULL, 'Like dominoes — one event triggers, or causes, the next.', 'A knock-on effect is a secondary consequence — one event causes another, which then causes another. Very common in business and economics.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Business vocabulary",Collocation}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('f1b62ba1-a8f6-475b-b872-f013c5de4d78', 1539, 'multiple_choice', 'B2', 'business_vocabulary', 'The process of investigating a company''s finances and operations before a merger or acquisition is called _____ diligence.', 'due', '["due", "full", "proper", "careful"]', NULL, NULL, NULL, 'Latin-sounding adjective — paired with "diligence" or "process".', 'Due diligence is the thorough investigation carried out before a major business transaction. It assesses financial health, legal risks, and operational performance to avoid costly surprises.', '2026-03-26 08:02:12.742714+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('437a2c2f-e396-4818-ae1f-57c1cfee2857', 1540, 'multiple_choice', 'B2', 'business_vocabulary', 'A _____ is a standard or point of reference used to measure performance or make comparisons.', 'benchmark', '["benchmark", "threshold", "indicator", "metric"]', NULL, NULL, NULL, 'A standard to *measure against* — originally a surveyor''s mark on a bench.', 'A benchmark is a reference point used to evaluate performance. Benchmarking against competitors or industry standards helps companies identify areas for improvement.', '2026-03-26 08:02:12.742714+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('b1ec8bd9-50ee-4c26-9dfd-19df821a3561', 541, 'multiple_choice', 'C1', 'idioms', 'Don''t put all your eggs in one ___.', 'basket', '["bowl", "box", "bag", "basket"]', NULL, NULL, NULL, 'Don''t take a single big risk — an idiom about woven containers.', 'Don''t put all your eggs in one basket = don''t risk everything on one plan.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Fixed expression"}', true, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('6e5dd919-46ba-4fd3-9d2c-9d7b6e9d6710', 542, 'multiple_choice', 'C1', 'idioms', 'The project is still up in the ___.', 'air', '["sky", "air", "wind", "clouds"]', NULL, NULL, NULL, 'Undecided — an idiom about what we breathe.', 'Up in the air = uncertain, not yet decided.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Fixed expression"}', true, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('f550e604-cea9-4b0c-be66-53cca5985660', 544, 'multiple_choice', 'C1', 'idioms', 'The new policy has opened a ___ of worms.', 'can', '["tin", "box", "can", "bag"]', NULL, NULL, NULL, 'Created lots of complications — an idiom about a metal container of bait.', 'Open a can of worms = create a complicated problem.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Fixed expression"}', true, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('c4986b53-d8e2-4074-acd9-eb69844cf231', 545, 'multiple_choice', 'C1', 'idioms', 'He hit the ___ on the head with his analysis.', 'nail', '["hammer", "nail", "screw", "pin"]', NULL, NULL, NULL, 'Identified exactly — an idiom about a metal pin and a hammer.', 'Hit the nail on the head = describe exactly what is true.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Fixed expression"}', true, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('f248c442-f74e-438d-b95d-d627494c4ec6', 1116, 'gap_fill', 'C2', 'business_vocabulary', 'The process of buying back shares from the public market to reduce the number in circulation is called a share _______.', 'buyback', NULL, NULL, NULL, '["repurchase"]', 'A compound noun — what the company does when it acquires its own shares.', 'A share buyback means a company repurchases its own shares from the open market, reducing the number in circulation and typically increasing the value of remaining shares.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Business vocabulary","Financial vocabulary",Collocation}', false, 'Two simple words joined: a verb and a direction.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('cfe6478f-18cb-464c-b55c-b1738dd8cd86', 340, 'multiple_choice', 'A2', 'past_simple', 'I ___ to bed early last night because I was tired.', 'went', '["go", "went", "gone", "going"]', NULL, NULL, NULL, '"Last night" — past simple. Go is irregular.', 'Go is irregular: go → went.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Past tense"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('f3745ee4-98ad-46b9-98c8-93e84ad954d6', 341, 'multiple_choice', 'A1', 'daily_routines', 'I ___ up at 7 o''clock every morning.', 'get', '["back", "get", "stand", "go"]', NULL, NULL, NULL, 'A two-word verb meaning to wake up and stand up.', 'Get up = leave your bed in the morning. Also: wake up.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{Vocabulary}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('4707e90b-474a-4967-a04f-754a6ba5f8ec', 342, 'multiple_choice', 'A1', 'daily_routines', 'I ___ a shower before breakfast.', 'have', '["make", "do", "have", "go"]', NULL, NULL, NULL, 'You don''t "do" a shower — different verb.', 'Have a shower / have a bath. British English usage.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{Vocabulary}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('ad027481-c1fa-4010-a779-cad280252782', 343, 'multiple_choice', 'A1', 'daily_routines', 'She ___ to work by train.', 'goes', '["has", "goes", "go", "does"]', NULL, NULL, NULL, 'She + verb — add -s.', 'Go to work = travel to your workplace.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{Vocabulary}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('ab2400f0-90b4-45e5-8bbd-0524dfed2246', 344, 'multiple_choice', 'A1', 'daily_routines', 'I ___ lunch at 1 pm.', 'have', '["do", "go", "have", "take"]', NULL, NULL, NULL, 'Same verb as for breakfast and dinner.', 'Have lunch / have dinner / have breakfast.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{Vocabulary}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('d7e20a9a-2094-4322-ae3a-e35993b42d24', 345, 'multiple_choice', 'A2', 'daily_routines', 'He ___ the housework at the weekend.', 'does', '["makes", "does", "has", "goes"]', NULL, NULL, NULL, '"___ the housework" — a different verb from "make".', 'Do the housework / do the washing / do the ironing.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{Vocabulary}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('c24bce20-99bf-4d4a-ba37-553317236958', 346, 'multiple_choice', 'A1', 'daily_routines', 'I ___ my teeth twice a day.', 'brush', '["wash", "clean", "brush", "do"]', NULL, NULL, NULL, 'The verb that goes with teeth.', 'Brush your teeth = clean with a toothbrush.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{Vocabulary}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('2a838220-7418-42a6-b193-dc675c15501f', 347, 'multiple_choice', 'A1', 'daily_routines', 'She ___ dressed and goes to school.', 'gets', '["makes", "puts", "does", "gets"]', NULL, NULL, NULL, '"___ dressed" — same verb as "get up".', 'Get dressed = put on your clothes.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{Vocabulary}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('9b47f0eb-946e-4d2e-948e-588e63927801', 348, 'multiple_choice', 'A2', 'daily_routines', 'I usually ___ to bed at 11 pm.', 'go', '["sleep", "go", "have", "make"]', NULL, NULL, NULL, '"___ to bed" — the same verb as "___ home".', 'Go to bed = go to sleep for the night.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{Vocabulary}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('a7e4e608-b910-4511-b05e-2714c6256499', 349, 'multiple_choice', 'A1', 'daily_routines', 'We ___ breakfast at 8 am.', 'have', '["do", "go", "have", "take"]', NULL, NULL, NULL, 'Same verb as "have lunch" and "have dinner".', 'Have breakfast = eat your morning meal.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{Vocabulary}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('ad9ce188-288e-4a4d-84bd-d71b62af9d6f', 350, 'multiple_choice', 'A2', 'daily_routines', 'He ___ his homework after dinner.', 'does', '["makes", "does", "has", "gets"]', NULL, NULL, NULL, '"___ homework" — same verb as "___ the housework".', 'Do homework / do exercise / do your best.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{Vocabulary}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('1d2a4590-126c-4a0c-897e-f012fa0c182d', 351, 'multiple_choice', 'A1', 'food_and_drink', 'Can I have a ___ of water, please?', 'glass', '["cup", "glass", "plate", "dish"]', NULL, NULL, NULL, 'A container for water — usually made of glass.', 'A glass of water / a glass of wine / a glass of juice.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{Vocabulary}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('2e5e52e0-fd79-434a-933b-732a3be117c6', 459, 'gap_fill', 'C2', 'participle_clauses', 'The road ___ (block) by a fallen tree, we had to find an alternative route.', 'being blocked', NULL, NULL, NULL, NULL, 'Passive participle clause: present continuous passive form.', 'Absolute participle clause: independent subject + participle.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Participle clause"}', false, '= "Because the road was being blocked..."', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('3683f9c5-9b6a-4184-9dc8-df6f0ff1fb7f', 460, 'gap_fill', 'C1', 'participle_clauses', '___ (not know) what to say, she remained silent.', 'Not knowing', NULL, NULL, NULL, NULL, 'Negative participle: "Not + verb-ing".', 'Negative participle clause: Not + -ing form.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Participle clause"}', false, '= "Because she didn''t know..."', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('d1bdf403-ac13-410d-96a7-61a3ededc292', 461, 'gap_fill', 'C1', 'participle_clauses', 'The children, ___ (exhaust) after the long walk, fell asleep immediately.', 'exhausted', NULL, NULL, NULL, NULL, 'Past participle describing the children — passive.', 'Reduced relative clause: who were exhausted → exhausted.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Participle clause"}', false, '= "who were ___..."', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('61a48267-16cb-4114-8e7d-1b3a1af6ec3c', 462, 'gap_fill', 'C2', 'participle_clauses', '___ (not / invite) to the meeting, I can''t tell you what was discussed.', 'Not having been invited', NULL, NULL, NULL, NULL, 'Negative + perfect passive participle.', 'Perfect passive participle (negative): Not having been + past participle.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Participle clause"}', false, 'Form: Not having been + past participle.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('9ebb7687-34b9-4345-8eb8-cfbf75dba8c3', 463, 'gap_fill', 'C1', 'participle_clauses', 'The city, ___ (found) in the 12th century, has a rich history.', 'founded', NULL, NULL, NULL, NULL, 'Past participle = passive — was founded in the 12th century.', 'Past participle = which was founded. Reduced relative clause.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Participle clause"}', false, '= "which was ___..."', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('009fe9ab-ffb6-4f7d-af1b-7d558adb1bd6', 464, 'gap_fill', 'C1', 'advanced_vocabulary', 'The negotiations reached a ___ when neither side would compromise.', 'deadlock', NULL, NULL, NULL, NULL, 'Position where neither side can move forward — stalemate.', 'Deadlock/stalemate/impasse = a situation where no progress can be made.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{}', false, 'Like a chess game with no possible move.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('32c91b37-f6c2-4ff7-a638-d4716a579688', 465, 'gap_fill', 'C1', 'advanced_vocabulary', 'Her speech was so ___ that everyone in the audience was moved.', 'compelling', NULL, NULL, NULL, NULL, 'So persuasive that it moved the audience.', 'Compelling/eloquent = powerfully persuasive or expressive.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{}', false, 'Sharing a root with "compel" — to force or strongly attract.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('556f174f-d46d-4557-b895-9b244e1807d8', 466, 'gap_fill', 'C2', 'advanced_vocabulary', 'The report ___ the need for immediate action on climate change.', 'underscores', NULL, NULL, NULL, NULL, 'Emphasises strongly — formal verb.', 'Underscore/underline/highlight = emphasise the importance of something.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{}', false, 'Like underlining text — to draw attention to it.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('acb7120a-99c6-4157-9c30-77606f2daabb', 467, 'gap_fill', 'C1', 'advanced_vocabulary', 'There has been a ___ increase in the cost of living.', 'substantial', NULL, NULL, NULL, NULL, 'A large, significant amount.', 'Substantial/significant/considerable = large and important.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{}', false, 'Sharing a root with "substance" — having real weight.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('d028f7bd-4ecf-42a5-bc7e-c0cff6e708a4', 469, 'gap_fill', 'C2', 'advanced_vocabulary', 'The new evidence ___ the original theory.', 'contradicts', NULL, '["supports", "confirms"]', 'Supports/confirms = strengthen a previous position.', NULL, 'Says the opposite — disproves something.', 'Contradict/undermine = go against or weaken a previous position.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{}', false, '"Contra-" = against. To speak against.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('7325eba7-d865-47ed-ab39-b077506c4f76', 470, 'gap_fill', 'C1', 'advanced_vocabulary', 'They reached a ___ agreement after months of negotiations.', 'tentative', NULL, NULL, NULL, NULL, 'Provisional, not final — could still change.', 'Tentative/preliminary = not final, subject to change.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{}', false, 'From "tentar" — to try. A trial agreement.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('12ab37a6-4895-4800-8650-3deab0389219', 471, 'gap_fill', 'C1', 'advanced_vocabulary', 'The government has pledged to ___ the root causes of poverty.', 'tackle', NULL, '["investigate"]', NULL, NULL, 'Deal with directly — face a problem head-on.', 'Tackle/address = deal with a problem seriously.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{}', false, 'Like in rugby — confronting the issue physically.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('101ab3b8-dcd2-4858-b914-01ba1b994c0b', 472, 'gap_fill', 'C2', 'advanced_vocabulary', 'The author''s latest novel has received ___ critical acclaim.', 'widespread', NULL, NULL, NULL, NULL, 'Compound: "wide" + ___ — happening in many places.', 'Widespread/universal acclaim = praise from many critics.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{}', false, '___ across the country, ___ public support.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('a15a1c2b-7cd6-4485-92b7-3077bc4cc3c7', 473, 'gap_fill', 'C1', 'advanced_vocabulary', 'There is a growing ___ that the current system is unsustainable.', 'consensus', NULL, NULL, NULL, NULL, 'General agreement among a group.', 'Consensus = general agreement among a group of people.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{}', false, 'Latin: con- (together) + sentire (feel) — feeling together.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('f1da8dce-1337-4ad9-be38-43635fa745f3', 474, 'gap_fill', 'C1', 'advanced_vocabulary', 'The policy has had far-___ consequences for the economy.', 'reaching', NULL, NULL, NULL, NULL, 'Compound: "far-___" — extending widely.', 'Far-reaching = having a wide and significant effect.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{}', false, 'Effects that ___ far into the future.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('9d8f5778-3c6f-440b-9435-1a0e5db549c4', 475, 'gap_fill', 'C2', 'advanced_vocabulary', 'The two accounts of the event are completely at ___ with each other.', 'odds', NULL, NULL, NULL, NULL, 'Idiom: "at ___ with" = in conflict with.', 'At odds with = in conflict or disagreement with.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{}', false, 'The two accounts disagree — they''re at ___ .', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('cf84e4df-ac1b-45e0-bde3-85e0c15a120d', 476, 'gap_fill', 'C1', 'advanced_vocabulary', 'The findings ___ light on a previously unknown aspect of the disease.', 'shed', NULL, NULL, NULL, NULL, 'Phrase: "___ light on" = to reveal/clarify.', 'Shed/throw/cast light on = reveal new information about something.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{}', false, 'Like turning on a torch in a dark room.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('f8a4cbea-0a91-4b0d-af94-306160983eea', 477, 'gap_fill', 'C1', 'advanced_vocabulary', 'The situation calls ___ immediate intervention.', 'for', NULL, NULL, NULL, NULL, '"Call ___" = require, demand.', 'Call for = require, demand. A formal expression.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{}', false, 'The situation demands action.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('dcb34959-45d7-4cf3-a731-f82cfc88bf42', 478, 'gap_fill', 'C2', 'advanced_vocabulary', 'She was ___ to the idea at first but eventually came round.', 'averse', NULL, NULL, NULL, NULL, 'Strongly opposed/disinclined.', 'Averse/opposed/resistant to = against something initially.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{}', false, 'Sharing a root with "aversion" — turning away from.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('abc11f05-bcc2-420d-a088-e2620c92d48a', 479, 'gap_fill', 'C1', 'wish_and_regret', 'I wish I ___ (not say) that. She looked really hurt.', 'hadn''t said', NULL, NULL, NULL, NULL, 'Past regret about what was said.', 'Wish + past perfect for regrets about the past.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Wish & regret"}', false, 'Form: wish + past perfect (had/hadn''t + past participle).', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('d2178647-e561-4bf5-91c8-f7394ad102ee', 480, 'gap_fill', 'C1', 'wish_and_regret', 'If only we ___ (have) more time. The deadline is tomorrow.', 'had', NULL, NULL, NULL, NULL, 'Present wish — we don''t have more time now.', 'If only + past simple for wishes about the present situation.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Wish & regret"}', false, 'If only + past simple = wishing about the present.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('b3f81547-2b5b-4172-8412-af0170a00903', 481, 'gap_fill', 'C1', 'wish_and_regret', 'I wish she ___ (stop) interrupting me.', 'would stop', NULL, '["''d stop"]', NULL, NULL, 'Wish about someone else''s annoying behaviour.', 'Wish + would for complaints about annoying habits or situations.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Wish & regret"}', false, 'Form: wish + would + base verb (irritation).', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('143e17b0-bdab-41d0-a23e-4844a9f7fb06', 482, 'gap_fill', 'C1', 'wish_and_regret', 'He wishes he ___ (can / afford) a bigger house.', 'could afford', NULL, '["''d afford"]', NULL, NULL, 'Wish about ability or possibility.', 'Wish + could for desires about present abilities: wish + past simple of can.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Wish & regret"}', false, 'Form: wish + could + base verb.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('70c09c80-09a5-43c0-ba42-d0d170f74f24', 484, 'gap_fill', 'C2', 'wish_and_regret', 'I wish it ___ (not rain) every single day. I''m so tired of it.', 'wouldn''t rain', NULL, NULL, NULL, NULL, 'Wish about an irritating ongoing situation.', 'Wish + wouldn''t or didn''t for dissatisfaction with current situations.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Wish & regret"}', false, 'Form: wish + wouldn''t + base verb.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('736a917b-ac81-4637-bd70-a6e56d679e3c', 485, 'gap_fill', 'C1', 'wish_and_regret', 'She wishes she ___ (take) that job offer when she had the chance.', 'had taken', NULL, '["''d taken"]', NULL, NULL, 'Past regret — didn''t take the offer.', 'Wish + past perfect: regret about a missed opportunity.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Wish & regret"}', false, 'Form: wish + past perfect (had + past participle).', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('901f7a3a-97a4-4775-9ac3-6e6b6e22f70e', 486, 'gap_fill', 'C1', 'reported_speech', 'She denied ___ (take) the money.', 'taking', NULL, NULL, NULL, NULL, '"Deny" takes the -ing form, not "to + infinitive".', 'Deny + gerund: She denied taking / having taken.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Reported speech"}', false, 'Some verbs (deny, admit, accuse) take -ing.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('953be6a5-a278-41e1-85d9-53230a0f1620', 487, 'gap_fill', 'C1', 'reported_speech', 'He urged the committee ___ (reconsider) their decision.', 'to reconsider', NULL, NULL, NULL, NULL, '"Urge" takes person + to + infinitive.', 'Urge + object + to infinitive: urge someone to do something.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Reported speech"}', false, 'Form: urge + object + to + base verb.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('a11750f2-c78d-4451-9d76-7a14e4c12abc', 488, 'gap_fill', 'C1', 'reported_speech', 'She insisted ___ paying for the dinner.', 'on', NULL, NULL, NULL, NULL, '"Insist" takes a specific preposition.', 'Insist on + gerund: She insisted on paying.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Reported speech"}', false, 'Insist ___ + -ing form.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('0ca04b67-b697-4961-bc78-46881fcf7b33', 489, 'gap_fill', 'C2', 'reported_speech', 'The witness ___ to having seen the suspect near the scene.', 'admitted', NULL, NULL, NULL, NULL, 'Acknowledged having seen — formal verb.', 'Admit to + gerund: formally accept that something is true.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Reported speech"}', false, 'Often pairs with "to having + past participle".', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('6a7be384-f159-4d11-9da5-f755a324b7da', 490, 'gap_fill', 'C1', 'reported_speech', 'He accused me ___ lying about the incident.', 'of', NULL, NULL, NULL, NULL, '"Accuse" takes a specific preposition.', 'Accuse someone of + gerund: claim someone did something wrong.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Reported speech"}', false, 'Accuse someone ___ + -ing form.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('5d86bbc0-0ec2-4918-b12b-d38f3d865f5c', 491, 'gap_fill', 'C1', 'reported_speech', 'She warned us ___ (not / go) near the river.', 'not to go', NULL, NULL, NULL, NULL, 'Negative warning — don''t go.', 'Warn + object + not to + infinitive.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Reported speech"}', false, 'Form: warn + person + ___ + to + base verb.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('bf3acb47-a3ec-401c-afe3-2da5049d9cb9', 492, 'gap_fill', 'C1', 'reported_speech', 'He congratulated her ___ passing the exam.', 'on', NULL, NULL, NULL, NULL, '"Congratulate" takes a specific preposition.', 'Congratulate someone on + gerund/noun.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Reported speech"}', false, 'Congratulate someone ___ + -ing form.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('924de50a-0141-4e57-8fc8-156a3b97b450', 493, 'gap_fill', 'C2', 'reported_speech', 'The spokesperson ___ to comment on the allegations.', 'declined', NULL, NULL, NULL, NULL, 'Formal verb meaning to politely refuse.', 'Decline/refuse to + infinitive: politely or firmly say no.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Reported speech"}', false, 'Sharing a root with "decline" (to go down).', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('5f1d7845-79bf-44c9-90e5-85a6a4547891', 494, 'gap_fill', 'C2', 'subjunctive', 'It is essential that every employee ___ (attend) the safety briefing.', 'attend', NULL, NULL, NULL, NULL, 'Subjunctive after "essential that" — base form only.', 'Subjunctive after essential/important/vital: base verb (no -s), even with he/she.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{Subjunctive}', false, 'No -s on the verb, even with "every employee".', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('8cbec145-d72a-41e4-8f71-4f6171f9d323', 495, 'gap_fill', 'C2', 'subjunctive', 'The board recommended that the CEO ___ (resign).', 'resign', NULL, NULL, NULL, NULL, 'Subjunctive after "recommend that".', 'Subjunctive after recommend/suggest/propose: base verb.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{Subjunctive}', false, 'Base form, even for he/she/it.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('c838825f-132d-4a74-b99f-5a3c7f4e619c', 496, 'gap_fill', 'C2', 'subjunctive', 'It is vital that this information ___ (remain) confidential.', 'remain', NULL, NULL, NULL, NULL, 'Subjunctive after "vital that".', 'Subjunctive: remain (not remains). Formal English structure.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{Subjunctive}', false, 'Base form (no -s for "it").', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('1e226b6a-e601-445d-b7ab-a07000be558f', 497, 'gap_fill', 'C2', 'subjunctive', 'Were she ___ (ask) me, I would gladly help.', 'to ask', NULL, NULL, NULL, NULL, 'Inversion conditional with "to-infinitive".', 'Formal: Were + subject + to infinitive = If she were to ask me.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{Subjunctive}', false, 'Same as "If she were to ask me...".', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('3033adcb-8555-4ff1-ab94-fb236aefbafe', 498, 'gap_fill', 'C1', 'formal_structures', 'Much ___ I admire her work, I disagree with her conclusions.', 'as', NULL, NULL, NULL, NULL, 'Concession structure: "Much ___ I X, Y".', 'Much as/though = although/even though. Formal concessive structure.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Formal register"}', false, 'Same as "Although I admire her work...".', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('6d1e725e-113d-4d08-92f2-c1178c675d7b', 499, 'gap_fill', 'C2', 'formal_structures', '___ it not been for your support, we would have failed.', 'Had', NULL, NULL, NULL, NULL, 'Inversion replacing "If it had not been for".', 'Had it not been for = If it had not been for. Formal inversion.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Formal register"}', false, 'Form: ___ + subject + past participle.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('091207f2-f6ff-4135-a79d-603863bb715d', 500, 'gap_fill', 'C1', 'formal_structures', 'However hard she ___ (try), she couldn''t solve the problem.', 'tried', NULL, NULL, NULL, NULL, 'After "However hard...", use a tense matching the time context.', 'However + adjective/adverb + subject + verb. Means no matter how hard.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Formal register"}', false, 'Past context (couldn''t solve) → past simple.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('a479ab25-edf1-4ebc-852c-1abe08cc329f', 504, 'multiple_choice', 'C1', 'advanced_phrasal_verbs', 'She ___ the job offer because the salary was too low.', 'turned down', '["turned off", "turned out", "turned up", "turned down"]', NULL, NULL, NULL, 'To reject (an offer, an invitation).', 'Turn down = reject, refuse an offer or invitation.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Phrasal verb"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('be00554d-73f8-47b7-8e81-e1095e8e49aa', 505, 'multiple_choice', 'C1', 'advanced_phrasal_verbs', 'The police are ___ the case thoroughly.', 'looking into', '["looking over", "looking out", "looking up", "looking into"]', NULL, NULL, NULL, 'Investigating thoroughly — peering inside.', 'Look into = investigate, examine in detail.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Phrasal verb"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('9615bbc3-e834-4394-b01b-c603adc8d423', 506, 'multiple_choice', 'C2', 'advanced_phrasal_verbs', 'It later ___ that he had been lying all along.', 'came out', '["came up", "came round", "came out", "came off"]', NULL, NULL, NULL, 'To become known publicly — for a secret to surface.', 'Come out = become known, be revealed publicly.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Phrasal verb"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('ef45b6cd-6b4d-4410-bc42-8c6a748a9c76', 507, 'multiple_choice', 'C1', 'advanced_phrasal_verbs', 'I ___ the idea of moving abroad when I was younger.', 'toyed with', '["messed about", "played up", "toyed with", "fooled around"]', NULL, NULL, NULL, 'To consider an idea casually, without commitment.', 'Toy with an idea = consider something casually without commitment.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Phrasal verb"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('4ae86c05-2ec5-4f07-a4a6-92f8178abea7', 509, 'multiple_choice', 'C2', 'advanced_phrasal_verbs', 'The initial enthusiasm has ___ and people are losing interest.', 'worn off', '["worn out", "worn through", "worn down", "worn off"]', NULL, NULL, NULL, 'To fade gradually — like writing on an eraser.', 'Wear off = gradually disappear or lose effect.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Phrasal verb"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('3e07c7b3-3543-42f4-b6ef-a4d57b5c8154', 511, 'multiple_choice', 'C1', 'advanced_phrasal_verbs', 'The project ___ much more expensive than we expected.', 'turned out', '["turned in", "turned out", "turned over", "turned up"]', NULL, NULL, NULL, 'To prove to be (often unexpectedly).', 'Turn out = end up being, prove to be in the end.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Phrasal verb"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('90e93878-5f18-404d-8575-5f91f2b9f02d', 514, 'multiple_choice', 'C1', 'advanced_phrasal_verbs', 'The fire ___ before the firefighters arrived.', 'broke out', '["broke down", "broke out", "broke off", "broke up"]', NULL, NULL, NULL, 'To start suddenly (fires, wars, diseases).', 'Break out = start suddenly (fire, war, disease, argument).', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Phrasal verb"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('fcac3ac7-748d-45f8-905a-8862855d61ad', 515, 'multiple_choice', 'C2', 'advanced_phrasal_verbs', 'She ___ her responsibilities admirably during the crisis.', 'lived up to', '["lived through", "lived down", "lived on", "lived up to"]', NULL, NULL, NULL, 'To meet or fulfil expectations.', 'Live up to = meet expectations or standards.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Phrasal verb"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('7a2b416e-051f-43f5-99ff-22bdc1b597bf', 516, 'multiple_choice', 'C1', 'formal_register', 'The results are ___ with previous research findings.', 'consistent', '["resistant", "consistent", "persistent", "insistent"]', NULL, NULL, NULL, 'Matching, in agreement with — formal register.', 'Consistent with = in agreement with, matching previous evidence.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Formal register"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('ebea0f4e-706c-4d4e-863e-c135f8d45e50', 517, 'multiple_choice', 'C1', 'formal_register', 'The study ___ several important questions about the methodology.', 'raises', '["rises", "arises", "raises", "arouses"]', NULL, NULL, NULL, 'To bring up (questions, concerns) — formal.', 'Raise questions = bring questions to attention. Raise is transitive (needs an object).', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Formal register"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('0ac21427-d608-48e7-b2d2-ec91bb04a7b8', 518, 'multiple_choice', 'C2', 'formal_register', 'The evidence is largely ___, making it difficult to draw conclusions.', 'anecdotal', '["applicable", "anecdotal", "analogous", "analytical"]', NULL, NULL, NULL, 'Based on individual stories rather than systematic data.', 'Anecdotal = based on personal accounts rather than systematic research.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Formal register"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('d6d6f332-346d-4ccf-83c0-cc405398c46d', 519, 'multiple_choice', 'C1', 'formal_register', 'The proposal was met with ___ opposition from the board.', 'fierce', '["strongly", "hard", "heavy", "fierce"]', NULL, NULL, NULL, 'Very strong, intense (especially of opposition or competition).', 'Fierce opposition = very strong, intense resistance to something.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Formal register"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('f52134d3-c63f-4012-a769-f021484c4ca9', 520, 'multiple_choice', 'C1', 'formal_register', 'We need to ___ this issue before it escalates.', 'address', '["access", "address", "assess", "dress"]', NULL, NULL, NULL, 'Formal verb meaning to deal with (a problem, an issue).', 'Address an issue = deal with or discuss a problem formally.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Formal register"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('a1134201-e5a2-4814-a0d3-05da49e3429a', 521, 'multiple_choice', 'C2', 'formal_register', 'The findings ___ a complex relationship between diet and health.', 'reveal', '["reverse", "revise", "reveal", "revolve"]', NULL, NULL, NULL, 'Shows or makes visible — formal.', 'Reveal = show or make known something previously hidden.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Formal register"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('37e23b91-8471-47d6-bbc2-429085b2b521', 522, 'multiple_choice', 'C1', 'formal_register', 'The report provides a ___ analysis of the economic situation.', 'comprehensive', '["comprehensible", "compulsory", "compulsive", "comprehensive"]', NULL, NULL, NULL, 'Covering everything — leaves nothing out.', 'Comprehensive = complete, covering all aspects thoroughly.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Formal register"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('177ee61d-ad10-4206-9bad-f2a06025071c', 523, 'multiple_choice', 'C1', 'formal_register', 'The policy has been ___ criticised by human rights organisations.', 'widely', '["broadly", "largely", "vastly", "widely"]', NULL, NULL, NULL, 'Across a broad range — by many people.', 'Widely criticised = criticised by many people/groups.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Formal register"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('9b016624-d7d9-40cd-bd8e-44f623e5520f', 524, 'multiple_choice', 'C2', 'formal_register', 'The minister ___ allegations of corruption.', 'refuted', '["referred", "refused", "reflected", "refuted"]', NULL, NULL, NULL, 'Formal verb meaning to deny or disprove with arguments.', 'Refute = deny and disprove allegations or claims.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Formal register"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('d31d3461-4bcc-4be3-847d-045662d96961', 525, 'multiple_choice', 'C1', 'formal_register', 'There are ___ implications for public health policy.', 'significant', '["signified", "signed", "significant", "signalling"]', NULL, NULL, NULL, 'Important, having meaningful consequences.', 'Significant implications = important consequences or effects.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Formal register"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('ef80fd09-49fd-4a07-b6c7-c9938ba61753', 526, 'multiple_choice', 'C1', 'formal_register', 'The project is ___ to be completed by December.', 'due', '["set", "bound", "owed", "due"]', NULL, NULL, NULL, 'Expected to happen by a certain time.', 'Due to = scheduled/expected to happen at a particular time.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Formal register"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('ee18f988-d95e-4239-ac82-e0bd99979bd3', 527, 'multiple_choice', 'C2', 'formal_register', 'The government has ___ new legislation to combat online fraud.', 'enacted', '["enforced", "endorsed", "enacted", "engaged"]', NULL, NULL, NULL, 'To make into law — formal verb for legislation.', 'Enact legislation = formally pass a new law.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Formal register"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('2903e7e4-3697-4213-9127-682953c81daf', 528, 'multiple_choice', 'C1', 'formal_register', 'The committee will ___ their findings next month.', 'publish', '["promote", "publish", "publicise", "presenting"]', NULL, NULL, NULL, 'To make publicly available (a report, a book).', 'Publish findings = formally release research results.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Formal register"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('71b4a5d4-465c-4473-9e93-8cc2f30c9d4d', 529, 'multiple_choice', 'C2', 'formal_register', 'The new policy is ___ to affect millions of workers.', 'poised', '["paused", "placed", "poised", "posed"]', NULL, NULL, NULL, 'Ready and likely to happen — on the verge of.', 'Poised to = ready and about to do something.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Formal register"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('726f10f8-9f18-48ad-80e7-03de6f1de1cf', 530, 'multiple_choice', 'C1', 'formal_register', 'Further research is ___ to confirm these initial findings.', 'warranted', '["willed", "warranted", "wanted", "wished"]', NULL, NULL, NULL, 'Justified, deserved — formal.', 'Warranted = justified, necessary. Formal academic usage.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Formal register"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('5701133d-de55-4f69-9d42-71503d559958', 533, 'multiple_choice', 'C1', 'idioms', 'The exam was a piece of ___. I finished in 30 minutes.', 'cake', '["pie", "cake", "biscuit", "bread"]', NULL, NULL, NULL, 'Very easy — a sweet idiom.', 'A piece of cake = very easy to do.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Fixed expression"}', true, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('70c79614-6515-42cc-835a-b1e6838e4eb6', 535, 'multiple_choice', 'C1', 'idioms', 'The new regulations are a ___ in the right direction.', 'step', '["jump", "walk", "move", "step"]', NULL, NULL, NULL, 'Progress — what you take when walking forward.', 'A step in the right direction = positive progress toward a goal.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Fixed expression"}', true, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('c9842212-d7b5-41be-bf1c-6af0f8d4bee6', 536, 'multiple_choice', 'C1', 'idioms', 'I think we should call it a ___ and finish the meeting.', 'day', '["break", "night", "day", "time"]', NULL, NULL, NULL, 'To stop work for now — an idiom about a 24-hour period.', 'Call it a day = decide to stop working on something.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Fixed expression"}', true, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('2d904451-d63c-4665-bc15-531edadabe5b', 537, 'multiple_choice', 'C2', 'idioms', 'The company is in hot ___ after the financial scandal.', 'water', '["air", "fire", "steam", "water"]', NULL, NULL, NULL, 'In trouble — an idiom about a hot liquid.', 'In hot water = in trouble, facing serious problems.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Fixed expression"}', true, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('b550d44b-bb0b-49c6-a6ba-cc89bb054219', 538, 'multiple_choice', 'C1', 'idioms', 'She always goes the extra ___ for her students.', 'mile', '["step", "length", "way", "mile"]', NULL, NULL, NULL, 'Make extra effort — an idiom about distance.', 'Go the extra mile = make more effort than expected.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Fixed expression"}', true, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('3ccb05b2-84f0-464d-8147-b6f41337b668', 549, 'multiple_choice', 'C2', 'confusing_words', 'She ___ to the new environment remarkably quickly.', 'adapted', '["adept", "adopted", "adapted", "adhered"]', NULL, NULL, NULL, 'To adjust to new conditions. (Don''t confuse with "adopted" — to take in.)', 'Adapt = adjust to new conditions. Adopt = take on/accept something new.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Confusable words"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('0435ca21-8e56-4334-ad58-f714005f74bd', 550, 'multiple_choice', 'C1', 'confusing_words', 'The report ___ several important factors.', 'overlooks', '["oversees", "overtakes", "overcomes", "overlooks"]', NULL, NULL, NULL, 'To miss or fail to notice. (Don''t confuse with "oversees" = supervises.)', 'Overlook = fail to notice. Oversee = supervise.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Confusable words"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('5cb70e00-a280-4503-b72b-df4848d6cc74', 551, 'multiple_choice', 'C1', 'confusing_words', 'I found her argument very ___.', 'compelling', '["compulsive", "competitive", "compulsory", "compelling"]', NULL, NULL, NULL, 'So persuasive that it captures attention.', 'Compelling = powerfully convincing. Compulsory = obligatory.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Confusable words"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('31f44de4-1283-4378-8281-020af06640b0', 552, 'multiple_choice', 'C2', 'confusing_words', 'His comments were taken completely out of ___.', 'context', '["content", "contact", "contract", "context"]', NULL, NULL, NULL, 'The surrounding circumstances that give meaning.', 'Out of context = without the surrounding information that gives meaning.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Confusable words"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('c428d849-eb35-4e82-9a62-886da9a5b6a1', 553, 'multiple_choice', 'C1', 'confusing_words', 'The two concepts are often ___ but they are quite different.', 'confused', '["confided", "confused", "confirmed", "confusing"]', NULL, NULL, NULL, 'Mistakenly treated as identical. (Compare: "confusing" describes what causes confusion.)', 'Confused = mistaken for each other. Often used in passive voice.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Confusable words"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('8120f8df-ed7a-44e7-9065-de50b65be3fd', 555, 'multiple_choice', 'C2', 'confusing_words', 'The data ___ our hypothesis about climate trends.', 'corroborates', '["communicates", "corroborates", "commemorates", "collaborates"]', NULL, NULL, NULL, 'To confirm with additional evidence — formal.', 'Corroborate = confirm or give support to evidence.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Confusable words"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('8d38f87e-af22-4f1c-85d8-da647572de41', 556, 'multiple_choice', 'C1', 'confusing_words', 'The ___ of residents opposed the construction project.', 'majority', '["mass", "most", "main", "majority"]', NULL, NULL, NULL, 'More than half of a group.', 'The majority of = more than half. Used with countable nouns.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Confusable words"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('a67f1c84-da8f-469a-871e-3a70dafa946d', 557, 'multiple_choice', 'C1', 'confusing_words', 'Her ___ reaction was one of disbelief.', 'initial', '["initiative", "initiated", "initiating", "initial"]', NULL, NULL, NULL, 'First, original — at the very start.', 'Initial = first, happening at the beginning.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Confusable words"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('9177c4e1-ba58-4c5e-9ad5-46b32454f4d7', 558, 'multiple_choice', 'C2', 'confusing_words', 'The government''s response was widely ___ as inadequate.', 'perceived', '["conceived", "deceived", "perceived", "received"]', NULL, NULL, NULL, 'To be regarded or seen as something.', 'Perceive as = see or regard something in a particular way.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Confusable words"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('f9eff91c-6b93-405c-92f7-6891692dcb3d', 559, 'multiple_choice', 'C1', 'confusing_words', 'She made a ___ effort to improve her presentation skills.', 'conscious', '["conscientious", "consecutive", "conspicuous", "conscious"]', NULL, NULL, NULL, 'Deliberate, intentional. (Different from "conscience" = sense of right/wrong.)', 'Conscious effort = deliberate, intentional effort.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Confusable words"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('cb3e5741-df83-4dd5-9107-786a7ff149a9', 564, 'multiple_choice', 'C1', 'relative_clauses', 'The reason ___ she left has never been explained.', 'why', '["which", "why", "that", "what"]', NULL, NULL, NULL, 'Relative pronoun for a reason.', 'The reason why + clause. Why introduces the relative clause. This sentence would be fine without why. ', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Relative clause"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('7dfac322-16ea-4ab5-88e2-3a56a511bd37', 565, 'multiple_choice', 'C2', 'advanced_grammar', '___ should you attempt to repair this equipment yourself.', 'Under no circumstances', '["No wonder", "Under no circumstances", "By no means only", "In no time"]', NULL, NULL, NULL, 'Strong negative — never, in any situation.', 'Under no circumstances + inversion = you must never do this.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('53d12e02-7f57-43e7-b736-44efdeea5f42', 567, 'multiple_choice', 'C1', 'advanced_grammar', 'The more you practise, the ___ you''ll become.', 'better', '["best", "better", "good", "well"]', NULL, NULL, NULL, 'Comparative completing "the more X, the more Y".', 'The more...the more/better: double comparative structure.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('bfe3c7c1-f4d6-4584-8d48-094c8497896d', 568, 'multiple_choice', 'C2', 'advanced_grammar', 'Little ___ she know what was about to happen.', 'did', '["had", "did", "would", "was"]', NULL, NULL, NULL, 'Fixed inversion phrase — "Little ___ she know".', 'Little did + subject + know: inversion for emphasis on lack of knowledge.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('9856c627-8a97-483b-a2a0-a2d62e057c01', 569, 'multiple_choice', 'C1', 'advanced_grammar', 'She acted as ___ nothing had happened.', 'if', '["when", "though", "while", "if"]', NULL, NULL, NULL, 'Hypothetical comparison — "as ___ nothing had happened".', 'As if / as though + past perfect for unreal past comparisons.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('f5531d38-0858-4934-821d-b547978e857c', 570, 'multiple_choice', 'C1', 'advanced_grammar', 'I''d rather you ___ mention this to anyone.', 'didn''t', '["won''t", "don''t", "wouldn''t", "didn''t"]', NULL, NULL, NULL, '"I''d rather you" + past simple expressing preference.', 'I''d rather + subject + past simple for preferences about others'' actions.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('32788bab-2546-4f32-9b3f-18b3db6be4ba', 572, 'multiple_choice', 'C1', 'advanced_grammar', 'It''s high time we ___ about our future.', 'thought', '["thinking", "think", "to think", "thought"]', NULL, NULL, NULL, '"It''s high time" + past simple expressing overdue need.', 'It''s high time + past simple: it should have happened already.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('f5cf2fda-9578-4d72-a165-1f0f08a7ce97', 577, 'multiple_choice', 'C2', 'advanced_grammar', 'The proposal, ___ promising on paper, proved impractical.', 'while', '["despite", "while", "even", "however"]', NULL, NULL, NULL, 'Concessive clause — "___ promising on paper, but..."', 'While + adjective: concessive clause. While promising = although it was promising. Whilst would also work well here, and suits the formality of the rest of the text.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('a6397f3c-3dab-4192-ac8b-a4803dbc0a65', 578, 'multiple_choice', 'C1', 'advanced_grammar', 'On no ___ should this door be left unlocked.', 'account', '["occasion", "terms", "account", "condition"]', NULL, NULL, NULL, 'Idiom: "On no ___" = under no circumstances.', 'On no account = under no circumstances. Emphatic negative.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('f9b2d1e5-e159-4bd7-94c3-85980de522fe', 579, 'multiple_choice', 'C2', 'advanced_grammar', 'So ___ was the damage that the building had to be demolished.', 'extensive', '["extent", "extending", "extensive", "extended"]', NULL, NULL, NULL, 'Inverted "So + adjective" — "So ___ was the damage that..."', 'So + adjective + was + subject + that: inverted structure for emphasis.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('b7756bf6-1abd-499f-a5c7-5455bdb110b1', 580, 'multiple_choice', 'C1', 'advanced_grammar', 'He left without so much ___ saying goodbye.', 'as', '["than", "as", "like", "that"]', NULL, NULL, NULL, 'Idiom: "without so much ___" = not even.', 'Without so much as + gerund = without even doing something.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('195942a0-a0bf-459b-8609-0538af3fdfb9', 584, 'multiple_choice', 'C1', 'nuance', 'The decision was taken ___ the interests of public safety.', 'in', '["by", "at", "for", "in"]', NULL, NULL, NULL, 'Phrase: "___ the interests of" = for the sake of.', 'In the interests of = for the sake of, to protect or promote.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Confusable words"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('ac3557b3-6b15-445d-a7ad-73bb8a614a1a', 585, 'multiple_choice', 'C1', 'nuance', 'She was ___ critical of the government''s handling of the crisis.', 'outspokenly', '["outspoken", "outspoking", "outspoke", "outspokenly"]', NULL, NULL, NULL, 'Critically and openly — speaking out.', 'Outspokenly critical = openly and directly critical.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Confusable words"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('4d827185-9a98-4ee7-990c-f5ab6ee414ba', 586, 'multiple_choice', 'C2', 'nuance', 'The scandal ___ a shadow over the entire organisation.', 'cast', '["threw", "put", "set", "cast"]', NULL, NULL, NULL, 'Idiom: ___ a shadow over = create doubt or trouble.', 'Cast a shadow over = have a negative effect on. Formal/literary.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Confusable words"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('2e8e7c4d-0b7b-407c-88bd-39e6b26bcc4f', 587, 'multiple_choice', 'C1', 'nuance', 'He made a passing ___ to the incident but didn''t elaborate.', 'reference', '["comment", "mention", "remark", "reference"]', NULL, NULL, NULL, 'A mention or allusion — making a passing one.', 'Make a passing reference to = mention briefly without detail.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Confusable words"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('80a91e1f-0533-4bed-a2f5-af65e08b1ce1', 589, 'multiple_choice', 'C2', 'nuance', 'Her contribution to the field cannot be ___.', 'overstated', '["overlooked", "overturned", "overrated", "overstated"]', NULL, NULL, NULL, 'Cannot be exaggerated — her contribution was massive.', 'Cannot be overstated = is extremely important (so important you can''t exaggerate it).', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Confusable words"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('a6962694-5c66-48c5-b356-eb14903d5647', 590, 'multiple_choice', 'C1', 'nuance', 'The two countries have a ___ of cooperation going back decades.', 'track record', '["track line", "track route", "track path", "track record"]', NULL, NULL, NULL, 'A history of past performance — like in racing.', 'Track record = history of past achievements or performance.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Confusable words"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('bba6c793-c923-4d29-817a-947e24931adb', 591, 'multiple_choice', 'C1', 'nuance', 'We need to ___ a balance between cost and quality.', 'strike', '["hit", "make", "strike", "search"]', NULL, NULL, NULL, 'Idiom: ___ a balance = find equilibrium between two things.', 'Strike a balance = find a satisfactory compromise between two things.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Confusable words"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('e42b2d2c-12fa-4685-8cea-4fbcf2cb3ee7', 592, 'multiple_choice', 'C2', 'nuance', 'The author ___ a convincing case for educational reform.', 'makes', '["does", "makes", "puts", "sets"]', NULL, NULL, NULL, 'Common verb pairing — ___ a case = present an argument.', 'Make a case for = argue persuasively in favour of something.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Confusable words"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('1c9a4f31-45a6-46a1-ad2a-9f0accbde7bd', 593, 'multiple_choice', 'C1', 'nuance', 'She has a ___ for languages and picks them up quickly.', 'flair', '["flare", "fare", "fair", "flair"]', NULL, NULL, NULL, 'A natural talent or aptitude.', 'A flair for = a natural talent or ability for something.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Confusable words"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('11309884-66ba-4d2f-b0a0-4227ee7542b6', 594, 'multiple_choice', 'C1', 'nuance', 'The manager ___ full responsibility for the error.', 'took', '["gave", "made", "took", "had"]', NULL, NULL, NULL, '___ responsibility = accept the consequences.', 'Take responsibility = accept that you are accountable.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Confusable words"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('a928f1f5-6833-49cb-911c-8b4f7b1d31e8', 595, 'multiple_choice', 'C2', 'nuance', 'The policy is ___ with controversy.', 'fraught', '["filled", "packed", "loaded", "fraught"]', NULL, NULL, NULL, 'Filled with (problems, controversy, difficulty).', 'Fraught with = full of (problems, danger, controversy). Formal register.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Confusable words"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('74d740b1-7f36-4722-a176-949f27621a79', 596, 'multiple_choice', 'C1', 'nuance', 'I''m writing to ___ my interest in the position.', 'express', '["suppress", "press", "express", "impress"]', NULL, NULL, NULL, 'To communicate (feelings, interest) — formal.', 'Express interest = formally communicate that you are interested.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Confusable words"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('323fbde7-b66e-4e7d-83c1-b29221dac944', 597, 'multiple_choice', 'C1', 'nuance', 'The evidence ___ to a clear pattern of negligence.', 'points', '["guides", "directs", "points", "aims"]', NULL, NULL, NULL, 'To indicate, suggest — formal usage with "to".', 'Point to = indicate, suggest. Evidence points to a conclusion.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Confusable words"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('6b914f5a-4aca-46bc-968f-09cdea9aedce', 598, 'multiple_choice', 'C2', 'nuance', 'She delivered the speech with remarkable ___ and grace.', 'poise', '["pause", "noise", "pose", "poise"]', NULL, NULL, NULL, 'Calm composure — like a tightrope walker.', 'Poise = calm confidence and composure, especially under pressure.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Confusable words"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('ec9fe704-b4a9-43a0-b5f9-b9c961afc0ff', 599, 'multiple_choice', 'C1', 'nuance', 'The negotiations have reached a ___ point.', 'critical', '["critique", "critical", "critic", "criteria"]', NULL, NULL, NULL, 'Decisive moment — a turning point.', 'Critical point = very important, decisive moment.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Confusable words"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('07216aac-ad16-449b-9595-7c140d2789a1', 600, 'multiple_choice', 'C1', 'nuance', 'His explanation left a lot to be ___.', 'desired', '["wished", "hoped", "wanted", "desired"]', NULL, NULL, NULL, 'Idiom: "leave a lot to be ___" = be inadequate.', 'Leave a lot to be desired = be unsatisfactory, not good enough.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Confusable words"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('2504fde5-2139-4573-a453-e21a462781c7', 1132, 'gap_fill', 'B2', 'bathroom_vocabulary', 'The time between when a customer places an order and when the goods arrive is called the _______ time.', 'lead', NULL, NULL, NULL, NULL, 'The waiting time between order and delivery.', 'Lead time is the period between placing an order and receiving delivery. In a bathroom showroom, lead times for special-order tiles or bespoke items can be several weeks.', '2026-03-11 18:12:09.553883+00', NULL, NULL, 'en', '{}', false, 'Compound noun: ___ + time.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('9380ab9e-169e-4912-84e3-130313c99748', 1133, 'gap_fill', 'B2', 'bathroom_vocabulary', 'The price charged before tax is added is called the _______ price.', 'net', NULL, NULL, NULL, NULL, 'Before tax is added — the basic price.', 'The net price is the price before IVA (or VAT) or other taxes are applied. The gross price is the total including tax. Trade customers are usually quoted net prices.', '2026-03-11 18:12:09.553883+00', NULL, NULL, 'en', '{}', false, '___ vs gross: ___ = without extras.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('95f28280-5265-4547-abbb-ade9709c95f8', 1134, 'gap_fill', 'B2', 'bathroom_vocabulary', 'A tile with a surface that provides extra grip to prevent slipping is described as _______.', 'slip-resistant', NULL, NULL, NULL, '["non-slip", "anti-slip"]', 'Compound adjective — prevents slipping.', 'Slip-resistant tiles have a textured or treated surface that provides grip underfoot. They are essential for wet floors such as shower trays, bathroom floors, and outdoor spaces.', '2026-03-11 18:12:09.553883+00', NULL, NULL, 'en', '{}', false, 'Like "water-resistant" or "fire-resistant".', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('e58027a4-8637-4abf-9326-0bf85baebf4e', 1135, 'gap_fill', 'B2', 'bathroom_vocabulary', 'A document listing all the items in an order, with their quantities and prices, and the total amount owed, is called an _______.', 'invoice', NULL, NULL, NULL, NULL, 'A formal bill listing items and prices.', 'An invoice is a formal document issued after a sale that lists items supplied, quantities, unit prices, and the total amount due. It is used for payment and record-keeping.', '2026-03-11 18:12:09.553883+00', NULL, NULL, 'en', '{}', false, 'From Latin "invenire" — to come upon, find.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('882295fa-8e39-4513-b0e3-69958edfd6e7', 1136, 'gap_fill', 'C2', 'bathroom_vocabulary', 'A tile whose edges have been precisely machine-cut after firing, allowing it to be laid with very thin grout joints, is called a _______ tile.', 'rectified', NULL, NULL, NULL, NULL, 'Tiles precision-cut after firing — for thin grout joints.', 'Rectified tiles are cut to exact dimensions after firing, ensuring perfectly straight edges. This allows them to be laid with minimal grout joints — as thin as 1–2mm — creating a seamless, contemporary finish.', '2026-03-11 18:12:09.553883+00', NULL, NULL, 'en', '{}', false, 'From "rectus" (Latin for straight).', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('377e35e2-e110-42bf-a191-19d40253c2fd', 1139, 'gap_fill', 'C1', 'bathroom_vocabulary', 'The detailed document listing all materials, finishes, dimensions, and quantities for a bathroom project is called the _______.', 'specification', NULL, NULL, NULL, '["spec"]', 'A detailed plan listing all materials and dimensions.', 'A specification (or spec) sets out exactly what will be supplied — tile references, dimensions, finishes, and quantities. It forms the basis of a formal quotation and avoids misunderstandings during the project.', '2026-03-11 18:12:09.553883+00', NULL, NULL, 'en', '{}', false, 'Often shortened to "spec" in trade conversations.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('f6b8d853-226d-41e0-b253-818c04d46bc2', 1141, 'gap_fill', 'C1', 'bathroom_vocabulary', 'The manufacturer''s written promise to repair or replace a product that develops a fault within a stated period is called a _______.', 'warranty', NULL, NULL, NULL, '["guarantee"]', 'The manufacturer''s promise to repair or replace.', 'A warranty is the manufacturer''s formal commitment to address defects within a specified period. High-end tiles and sanitaryware often carry extended warranties of 10 to 25 years, which can be a strong selling point.', '2026-03-11 18:12:09.553883+00', NULL, NULL, 'en', '{}', false, 'Sharing a root with "warrant" (to guarantee).', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('60712c31-92de-4b78-b7bc-245f2477b270', 1142, 'gap_fill', 'C1', 'bathroom_vocabulary', 'The overall visual identity of a bathroom — its combination of materials, colours, textures, and style — is referred to as its _______.', 'aesthetic', NULL, NULL, NULL, NULL, 'The overall visual style and feel.', 'The aesthetic of a bathroom describes its overall look and feel — the coherent combination of tiles, fixtures, lighting, and accessories that creates a distinctive style. High-end clients often arrive with a clear aesthetic vision.', '2026-03-11 18:12:09.553883+00', NULL, NULL, 'en', '{}', false, 'From Greek aisthētikos — relating to perception.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('373ce6b5-1fe2-4b0b-a21f-513244e55160', 1143, 'gap_fill', 'C2', 'bathroom_vocabulary', 'A product designed and made to meet one specific customer''s exact requirements is described as _______.', 'bespoke', NULL, NULL, NULL, '["custom-made", "custom", "made-to-order"]', 'Custom-made for one specific customer.', 'Bespoke means made specifically to a customer''s individual requirements — custom dimensions, finishes, or configurations not available off the shelf. Bespoke products command a premium and require longer lead times.', '2026-03-11 18:12:09.553883+00', NULL, NULL, 'en', '{}', false, 'Old English: "be-spoken for" — already promised.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('212d2a13-04e5-4d1f-926c-3ff1eafb6ba1', 1144, 'gap_fill', 'C1', 'bathroom_vocabulary', 'When a customer is unhappy with a product, the process of resolving the problem professionally is called handling a _______.', 'complaint', NULL, NULL, NULL, NULL, 'A customer''s formal expression of dissatisfaction.', 'Handling complaints effectively is essential in high-end retail. A professional response — acknowledging the issue, apologising sincerely, and offering a clear solution — protects the customer relationship and the company''s reputation.', '2026-03-11 18:12:09.553883+00', NULL, NULL, 'en', '{}', false, 'Sharing a root with "plaintiff" (one who complains in court).', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('b27bfee6-532f-4b46-ba43-33c624f7f246', 1244, 'gap_fill', 'B1', 'business_phrasal_verbs', 'The new regulations will _____ how we operate significantly.', 'impact on', NULL, NULL, NULL, NULL, 'To affect — formal verb with a preposition.', 'Impact on means to have an effect on something. In business English, impact is frequently used as a verb: the changes impacted on our workflow.', '2026-03-18 19:58:52.376507+00', NULL, NULL, 'en', '{}', false, 'Same as "have an impact ___".', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('61ba5ef5-b721-473b-adde-f48d43fb1932', 1479, 'gap_fill', 'C1', 'phrasal_verbs', 'In her speech, she _____ decades of personal experience to make her argument compelling.', 'drew on', NULL, NULL, NULL, '["drew upon"]', 'To make use of (experience, knowledge).', 'Draw on means to make use of a source of knowledge, experience, or skill. Compare: call on, tap into, leverage.', '2026-03-18 20:30:31.624632+00', NULL, NULL, 'en', '{}', false, 'Like drawing water from a well.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('bd6cf602-dd75-47da-b5d2-9039ca9f4080', 1480, 'gap_fill', 'C1', 'phrasal_verbs', 'The launch has been _____ to take advantage of the pre-Christmas market.', 'brought forward', NULL, NULL, NULL, NULL, 'To move (a date, deadline) earlier.', 'Bring forward means to move an event or deadline to an earlier date. The opposite is push back.', '2026-03-18 20:30:31.624632+00', NULL, NULL, 'en', '{}', false, 'Opposite of "pushed back".', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('510450f3-8d37-41ec-9523-c911154f2e75', 1483, 'gap_fill', 'C2', 'phrasal_verbs', 'The evidence presented at the trial fully _____ the prosecution''s original theory.', 'bore out', NULL, NULL, NULL, NULL, 'To confirm (a theory, a prediction) with evidence.', 'Bear out means to confirm or support a claim, theory, or suspicion. Compare: corroborate, back up, substantiate.', '2026-03-18 20:30:31.624632+00', NULL, NULL, 'en', '{}', false, 'Past simple of "bear out".', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('466dd080-4775-44fb-a3e3-92c737250c18', 1485, 'gap_fill', 'C2', 'phrasal_verbs', 'His early struggles as an immigrant _____ a fierce determination that defined his entire career.', 'fed into', NULL, NULL, NULL, NULL, 'To contribute to (a result, a determination).', 'Feed into means to contribute to or influence something larger. It describes how one factor or experience becomes part of, and shapes, something else.', '2026-03-18 20:30:31.624632+00', NULL, NULL, 'en', '{}', false, 'Like a stream feeding into a river.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('86a1ba68-9cc3-42e9-bda2-562917e9e4f2', 99, 'gap_fill', 'B1', 'everyday_expressions', '___ (H_ _ / W_ _ _) about going for a walk?', 'how', NULL, NULL, NULL, '[{"answer": "what", "feedback": "This works too — ''What about going for a walk?'' is just as natural as ''How about…''. Both are common ways of making suggestions."}]', 'Making suggestions', 'Both ''How about'' and ''What about'' are used for making suggestions.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{"Fixed expression"}', false, '"How about..." or "What about..." — both work for suggestions.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('93f58c97-4047-4d36-ae51-8c346b563e2a', 2301, 'gap_fill', 'B2', 'sport', 'The team played well, ___ they still lost.', 'but', '[]', NULL, NULL, '[{"answer": "yet", "feedback": "Also correct — \"yet\" works as a contrast linker here too."}]', 'A linking word showing contrast.', '"But" (or "yet") links two contrasting ideas: played well, but lost.', '2026-06-01 07:35:54.312658+00', NULL, NULL, 'en', '{Grammar}', false, 'Three letters ("but" or "yet").', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('5d3d69c3-deb9-4418-b413-1dd85849e9a5', 1255, 'multiple_choice', 'A1', 'phrasal_verbs', 'Can you _____ the TV? It''s too loud.', 'turn down', '["turn down", "turn off", "turn up", "turn on"]', NULL, NULL, NULL, 'To reduce volume — opposite of "turn up".', 'Turn down means to reduce the volume or level of something. Turn up means the opposite — to increase it.', '2026-03-18 19:58:52.376507+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('d84369bb-d11a-4d75-9cdb-73ae1637660d', 1256, 'multiple_choice', 'A1', 'phrasal_verbs', 'I need to _____ some words in the dictionary.', 'look up', '["look up", "look out", "look after", "look into"]', NULL, NULL, NULL, 'To find information (in a dictionary, online).', 'Look up means to search for information in a reference source such as a dictionary or the internet.', '2026-03-18 19:58:52.376507+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('14d592f5-5069-4c65-b82a-c332e8fbfc65', 1257, 'multiple_choice', 'A2', 'phrasal_verbs', 'She _____ her little brother while their parents were away.', 'looked after', '["looked after", "looked up", "looked into", "looked over"]', NULL, NULL, NULL, 'To take care of someone or something.', 'Look after means to take care of someone or something.', '2026-03-18 19:58:52.376507+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('d3798a08-30f3-4dd9-a3fb-d2bb655101a2', 1258, 'multiple_choice', 'A1', 'phrasal_verbs', 'Don''t forget to _____ the lights when you leave.', 'turn off', '["turn off", "turn on", "turn up", "turn down"]', NULL, NULL, NULL, 'To deactivate (lights, a device).', 'Turn off means to stop a device or light from working. The opposite is turn on.', '2026-03-18 19:58:52.376507+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('74b64e51-177e-4ed0-ad62-3b180b078f3a', 1259, 'multiple_choice', 'A2', 'phrasal_verbs', 'He _____ going to the gym last month. It''s a pity.', 'gave up', '["gave up", "gave in", "gave out", "gave away"]', NULL, NULL, NULL, 'To stop a habit or activity — like surrendering to it.', 'Give up means to stop doing something, especially a habit. Compare: quit. It can be positive or negative.', '2026-03-18 19:58:52.376507+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('5c87ce78-90f6-46c6-9907-c396f86b5b80', 1260, 'multiple_choice', 'A1', 'phrasal_verbs', 'What time do you _____ in the morning?', 'get up', '["get up", "get on", "get out", "get in"]', NULL, NULL, NULL, 'To rise from bed — start the day.', 'Get up means to rise from bed in the morning. Compare: wake up (to stop sleeping) and get up (to physically leave the bed).', '2026-03-18 19:58:52.376507+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('2121d310-da0d-41c9-9440-45f07a949356', 1261, 'multiple_choice', 'A2', 'phrasal_verbs', 'We''re _____ of milk — can you buy some?', 'running out', '["running out", "running off", "running over", "running up"]', NULL, NULL, NULL, 'To have very little of something left — supply almost gone.', 'Run out of means to have no more of something left. Compare: we''ve run out of time / money / ideas.', '2026-03-18 19:58:52.376507+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('ec3483fd-df84-45af-9819-ede7e213a644', 1262, 'multiple_choice', 'A1', 'phrasal_verbs', 'Can you _____ the music? I can''t hear it properly.', 'turn up', '["turn up", "turn on", "turn off", "turn down"]', NULL, NULL, NULL, 'To increase volume — opposite of "turn down".', 'Turn up means to increase the volume or level of something. The opposite is turn down.', '2026-03-18 19:58:52.376507+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('b52dd337-cacd-41da-9cf9-8bc05b963f7a', 1263, 'multiple_choice', 'A2', 'phrasal_verbs', 'We _____ an old friend walking through the park yesterday.', 'ran into', '["ran into", "ran over", "ran after", "ran out of"]', NULL, NULL, NULL, 'To meet by chance — encounter unexpectedly.', 'Run into someone means to meet them unexpectedly. Compare: bump into, come across.', '2026-03-18 19:58:52.376507+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('cf69316f-5699-462d-9850-8453e1329d18', 1264, 'multiple_choice', 'A2', 'phrasal_verbs', 'The flight was _____ by two hours because of bad weather.', 'held up', '["held up", "held on", "held out", "held back"]', NULL, NULL, NULL, 'To delay — block the progress of.', 'Hold up means to delay something or someone. Compare: the traffic held us up / the project was held up by poor weather.', '2026-03-18 19:58:52.376507+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('86896e00-4468-4e42-993e-6d7c20deeef2', 1376, 'gap_fill', 'B1', 'prepositions', 'She is very good _____ managing her time.', 'at', NULL, NULL, NULL, NULL, 'Always: "good ___ + -ing".', 'Good at is the correct collocation. Compare: bad at, brilliant at, hopeless at.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}', false, 'The same as "skilled ___" or "talented ___".', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('e8a2f4a6-9366-415e-aa62-b8b9d6c51c7f', 43, 'multiple_choice', 'B2', 'articles', 'I play ___ piano.', 'the', '["a", "an", "the", "(no article)"]', NULL, NULL, NULL, 'Musical instruments take this article.', 'Musical instruments take ''the'', but sports do not use an article.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{Article}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('ba2a27f9-1781-4393-bd84-114c989e0698', 2049, 'multiple_choice', 'B2', 'articles', 'My sister plays ___ tennis.', '(no article)', '["a", "an", "the", "(no article)"]', NULL, NULL, NULL, 'Sports take no article — unlike musical instruments.', NULL, '2026-05-21 07:43:22.140299+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('6a48f545-9771-4302-8672-d271df89c1e4', 1382, 'gap_fill', 'B1', 'prepositions', 'She''s been working at the same company ___ over five years.', 'for', NULL, NULL, NULL, NULL, 'Used with a length of time.', 'Work for a company (not at in this context). For five years expresses duration — use for, not since, with a period of time.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}', false, 'Three letters. Goes with "years", "a long time", etc.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('5734af6e-f9a2-4139-aa79-7b42db30a9fe', 1572, 'gap_fill', 'B1', 'prepositions', 'The project was completed on time and ___ budget — a rare achievement.', 'under', NULL, NULL, NULL, NULL, 'Below the planned amount — financially impressive.', 'On time means punctually, not late. Under budget means spending less than planned. The opposite expressions are behind schedule and over budget.', '2026-03-26 08:02:12.742714+00', NULL, NULL, 'en', '{"Fixed expression"}', false, 'Five letters. Starts with u___.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('fcb6b1fc-559c-4c15-b543-f17146de11b8', 966, 'gap_fill', 'C2', 'phrasal_verbs', 'Don''t let her relaxed manner ___ your judgement — she is an exceptionally tough negotiator.', 'throw off', NULL, NULL, NULL, '["put"]', 'To deceive or mislead — disturb someone''s perception.', 'To throw someone off means to confuse or mislead them. Put off has a similar meaning — both suggest causing someone to lose focus or misjudge a situation.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Phrasal verb"}', false, 'Two words. Starts with t___ o___.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('e79cbb7a-0317-4db9-8116-d7b44947de4c', 2137, 'multiple_choice', 'A2', 'prepositions', 'The picture is ___ the wall.', 'on', '["on", "in", "at", "under"]', NULL, NULL, NULL, 'Touching a flat vertical surface.', 'We use "on" for contact with a flat surface: "on the wall".', '2026-06-01 07:16:29.304337+00', NULL, NULL, 'en', '{"Preposition of place"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('9b688ca9-62b1-4fdf-9c15-62b87c4c29bc', 1396, 'multiple_choice', 'A1', 'vocabulary', 'Which word means the opposite of "remember"?', 'forget', '["forget", "recall", "think", "know"]', NULL, NULL, NULL, 'To not be able to recall something.', 'Forget means to fail to remember something. Recall and remember are synonyms.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('db04808e-2334-4995-bdbe-6d6a93b4d89e', 1397, 'multiple_choice', 'A2', 'vocabulary', 'Which word describes someone who always arrives on time?', 'punctual', '["punctual", "lazy", "tidy", "careful"]', NULL, NULL, NULL, 'Always arriving on time — never late.', 'Punctual means arriving exactly on time, without being late. It comes from the Latin punctum, meaning point (of time).', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('d8c670ec-fb61-49b0-bbac-df74a978a684', 1398, 'multiple_choice', 'A1', 'vocabulary', 'What do you call the meal you eat in the morning?', 'breakfast', '["breakfast", "lunch", "supper", "snack"]', NULL, NULL, NULL, 'The first meal of the day — breaks the night''s fast.', 'Breakfast is the first meal of the day. The word literally means breaking the fast from the night before.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('48d26b28-f2f0-47a5-b239-bbb66e97feba', 1399, 'multiple_choice', 'A2', 'vocabulary', 'Which word means to feel very tired?', 'exhausted', '["exhausted", "anxious", "bored", "confused"]', NULL, NULL, NULL, 'Beyond tired — completely drained.', 'Exhausted means extremely tired, with no energy left. It is stronger than simply tired.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('65e1d9a7-2695-437f-9810-940d4f365a4c', 1400, 'multiple_choice', 'A1', 'vocabulary', 'Which of these is something you set before going to sleep?', 'an alarm', '["an alarm", "a schedule", "a habit", "a routine"]', NULL, NULL, NULL, 'A device that makes a noise to wake you up.', 'An alarm (clock) is a device or setting that wakes you up at a chosen time.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('069bbead-fca8-470e-8ad0-0efbed01f682', 1403, 'multiple_choice', 'A1', 'vocabulary', 'What do you call the things you do every day at the same time?', 'a routine', '["a routine", "a hobby", "a task", "an event"]', NULL, NULL, NULL, 'A daily pattern of activities done regularly.', 'A routine is a sequence of actions regularly followed. It implies regularity and repetition.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('09cec244-dafe-48d8-8c3e-4fbef48068ea', 1404, 'multiple_choice', 'A2', 'vocabulary', 'Which word describes someone who finds it hard to wake up early?', 'a night owl', '["a night owl", "an early bird", "a workaholic", "a homebody"]', NULL, NULL, NULL, 'A bird-related metaphor for someone active at night.', 'A night owl is a person who prefers to be awake and active at night. An early bird is the opposite — someone who wakes up early.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('62a0c6a4-e587-43da-b092-c66eeb94a813', 1405, 'multiple_choice', 'A2', 'vocabulary', 'Which of these means to sleep for a short time during the day?', 'to nap', '["to nap", "to doze off", "to rest", "to oversleep"]', NULL, NULL, NULL, 'Verb meaning to sleep briefly during the day.', 'To nap means a short, intentional sleep during the day. Doze off means to fall asleep unintentionally.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('b0121906-9a8d-4c3c-acd5-f0b4ccab01b8', 1410, 'gap_fill', 'B1', 'vocabulary', 'A good morning routine can help you feel more _____ and ready for the day ahead.', 'focused', NULL, NULL, NULL, NULL, 'Concentrated and ready for the day.', 'Focused means giving full attention to something. It is a common adjective when discussing productivity and concentration.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}', false, 'Past participle as adjective.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('518b1589-4031-4ab4-9bee-96b893302450', 1456, 'multiple_choice', 'B1', 'phrasal_verbs', 'She found it hard to _____ her grandmother''s death.', 'get over', '["get over", "get through", "get by", "get away"]', NULL, NULL, NULL, 'To recover from something difficult emotionally.', 'Get over means to recover from something upsetting or difficult, such as an illness, loss, or disappointment.', '2026-03-18 20:30:31.624632+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('fe8de01a-df3a-4b09-b15a-4c962e08d03b', 1457, 'multiple_choice', 'B1', 'phrasal_verbs', 'He _____ running last year and now he does a 5k every morning.', 'took up', '["took up", "took on", "took off", "took over"]', NULL, NULL, NULL, 'To start a new activity or hobby.', 'Take up means to start a new hobby, sport, or activity.', '2026-03-18 20:30:31.624632+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('44174638-fe46-4ed9-8b7f-4980f0cbda34', 1458, 'multiple_choice', 'B1', 'phrasal_verbs', 'The heating _____ on the coldest night of the year.', 'broke down', '["broke down", "broke up", "broke off", "broke out"]', NULL, NULL, NULL, 'To stop working (machines, vehicles, systems).', 'Break down means to stop working. It can also describe losing emotional control or the failure of a relationship or negotiation.', '2026-03-18 20:30:31.624632+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('116e7218-9f00-4d91-a315-13cd7682beab', 1459, 'multiple_choice', 'B1', 'phrasal_verbs', 'Despite the interruptions, she _____ with her presentation.', 'carried on', '["carried on", "carried out", "carried off", "carried over"]', NULL, NULL, NULL, 'To continue (despite obstacles or interruptions).', 'Carry on means to continue doing something despite difficulties or interruptions.', '2026-03-18 20:30:31.624632+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('bdccfbd9-790c-4eeb-a426-55be107e6115', 1460, 'multiple_choice', 'B1', 'phrasal_verbs', 'Do you _____ well with your new colleagues?', 'get along', '["get along", "get over", "get through", "get behind"]', NULL, NULL, NULL, 'To have a good relationship with someone.', 'Get along (with someone) means to have a friendly, harmonious relationship with them. Get on is also used in the same way.', '2026-03-18 20:30:31.624632+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('ca47c50f-4009-46e4-ac1e-ad49a7d75d52', 1466, 'multiple_choice', 'B2', 'phrasal_verbs', 'She felt badly _____ when her best friend forgot her birthday.', 'let down', '["let down", "let off", "let out", "let up"]', NULL, NULL, NULL, 'To disappoint someone — fail their expectations.', 'Let down means to disappoint someone, especially by failing to do what was expected. The noun letdown describes the feeling of disappointment.', '2026-03-18 20:30:31.624632+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('1b1f41a5-3bba-4ea9-b53b-9181836810ae', 1467, 'multiple_choice', 'B2', 'phrasal_verbs', 'The smaller company was gradually _____ by a larger competitor.', 'taken over', '["taken over", "taken up", "taken on", "taken off"]', NULL, NULL, NULL, 'To acquire control of (a company, a department).', 'Take over means to gain control of something, such as a company, country, or role.', '2026-03-18 20:30:31.624632+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('5cb8b271-e4d8-40b4-8da3-b65e43dbd7d6', 1468, 'multiple_choice', 'B2', 'phrasal_verbs', 'Can you _____ the invoice I sent? I want to make sure the figures are right.', 'go over', '["go over", "go on", "go along", "go back"]', NULL, NULL, NULL, 'To review carefully — check every detail.', 'Go over means to check or review something carefully. Compare: look over, go through.', '2026-03-18 20:30:31.624632+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('bd9830c8-92e7-43d9-975f-7b2c62a4461d', 2302, 'gap_fill', 'B2', 'sport', 'If she ___ harder, she would have won.', 'had trained', '[]', NULL, NULL, NULL, 'Third conditional — the "if" clause.', 'Third conditional: the "if" clause uses the past perfect "had trained".', '2026-06-01 07:35:54.312658+00', NULL, NULL, 'en', '{Conditional}', false, '"had + past participle".', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('54557e10-83ab-4e2a-b58f-411c6a3a2757', 2303, 'gap_fill', 'B2', 'sport', 'The coach made the players ___ ten laps.', 'run', '[]', NULL, NULL, NULL, '"make somebody ___ something" takes the bare infinitive.', '"Make somebody do something" uses the bare infinitive: "made the players run".', '2026-06-01 07:35:54.312658+00', NULL, NULL, 'en', '{Grammar}', false, 'No "to" before it.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('bf2eca15-0138-4901-885f-4822dbb972c9', 2304, 'gap_fill', 'B2', 'sport', 'Cycling is far ___ demanding than it looks.', 'more', '[]', NULL, NULL, NULL, 'Comparative form with a longer adjective.', 'Longer adjectives form the comparative with "more": "more demanding".', '2026-06-01 07:35:54.312658+00', NULL, NULL, 'en', '{Comparative}', false, 'Four letters.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('e04e7443-f9eb-49b4-94be-21eec7d7c80c', 2305, 'multiple_choice', 'B2', 'sport', 'The injury prevented him ___ competing.', 'from', '["from", "of", "to", "for"]', NULL, NULL, NULL, '"prevent somebody ___ doing something".', 'The pattern is "prevent somebody from (doing) something".', '2026-06-01 07:35:54.312658+00', NULL, NULL, 'en', '{Preposition}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('6f41ae7e-1613-490a-930b-2bdfd0754abd', 2306, 'multiple_choice', 'B2', 'sport', 'She''s not used ___ training at high altitude.', 'to', '["to", "with", "for", "at"]', NULL, NULL, NULL, '"be used ___ doing something" = accustomed to it.', '"Be used to + -ing" means accustomed to: "not used to training".', '2026-06-01 07:35:54.312658+00', NULL, NULL, 'en', '{Preposition}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('0d1dca53-61dd-4721-81c2-726c879c0070', 2307, 'multiple_choice', 'B2', 'sport', 'By the time the whistle blew, we ___ already scored.', 'had', '["had", "have", "did", "were"]', NULL, NULL, NULL, 'Past perfect for the earlier of two past events.', 'Past perfect "had scored" marks the earlier of two past events.', '2026-06-01 07:35:54.312658+00', NULL, NULL, 'en', '{Tense}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('7ad683a6-a854-40b3-9d40-145a0ef3afd6', 2308, 'multiple_choice', 'B2', 'sport', 'The harder you train, the ___ you become.', 'fitter', '["fitter", "fit", "fittest", "more fit"]', NULL, NULL, NULL, 'Comparative correlative: "the more…, the ___…".', 'The comparative correlative: "The harder …, the fitter …".', '2026-06-01 07:35:54.312658+00', NULL, NULL, 'en', '{Comparative}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('7bd265df-d48e-4ad9-8b00-d4162ec332db', 1486, 'multiple_choice', 'A1', 'hotel_vocabulary', 'A guest wants to pay and leave the hotel. They need to _____.', 'check out', '["check out", "check in", "check up", "check over"]', NULL, NULL, NULL, 'To pay and leave the hotel — opposite of "check in".', 'Check out means to pay your bill and leave a hotel. Check in means to arrive and register. These are the two most essential hotel phrasal verbs.', '2026-03-23 08:55:51.646247+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('7200ecc5-395d-4489-b04c-f0e2b3395385', 1487, 'multiple_choice', 'A1', 'hotel_vocabulary', 'A _____ room has one large bed for two people.', 'double', '["double", "twin", "single", "suite"]', NULL, NULL, NULL, 'One large bed for two — twice the size of a single.', 'A double room has one large bed. A twin room has two single beds. A single room has one small bed for one person.', '2026-03-23 08:55:51.646247+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('709557c6-64b2-404b-a44d-39fc239ce4b6', 1488, 'multiple_choice', 'A1', 'hotel_vocabulary', 'The guest hung a sign on the door: "Do Not _____".', 'Disturb', '["Disturb", "Enter", "Knock", "Wait"]', NULL, NULL, NULL, '"Do Not ___" — to interrupt or bother.', 'Do Not Disturb is a standard hotel sign guests use to let staff know they do not want to be interrupted — for cleaning, housekeeping, or any other reason.', '2026-03-23 08:55:51.646247+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('4bdec156-8be5-4d30-8252-0a565523352b', 1489, 'multiple_choice', 'A1', 'hotel_vocabulary', 'Guests go to the _____ desk when they arrive, have a question, or need help.', 'reception', '["reception", "kitchen", "concierge", "porter"]', NULL, NULL, NULL, 'The hotel''s front desk — where guests are received.', 'The reception desk (or front desk) is the central point of contact for guests in a hotel. The receptionist handles check-ins, check-outs, and general queries.', '2026-03-23 08:55:51.646247+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('225845fd-c230-4cb8-b2ba-59e0fb18d92a', 1473, 'gap_fill', 'B2', 'phrasal_verbs', 'She _____ a convincing excuse to avoid going to the party.', 'made up', NULL, NULL, NULL, NULL, 'To invent (an excuse, a story).', 'Make up can mean to invent a story, excuse, or explanation — often one that is not true. It can also mean to reconcile after an argument.', '2026-03-18 20:30:31.624632+00', NULL, NULL, 'en', '{}', false, 'Like making something out of nothing.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('4fd2b16c-9634-496d-b4ed-4f5530d3b2cf', 1490, 'multiple_choice', 'A1', 'hotel_vocabulary', 'The lift takes guests to the correct _____ of the hotel.', 'floor', '["floor", "side", "section", "wing"]', NULL, NULL, NULL, 'Floors of a building — first, second, third.', 'Floor refers to a level of the building. In British English, the ground floor is at street level; the first floor is one level up.', '2026-03-23 08:55:51.646247+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('90025480-32b7-4935-936d-c11457bec43c', 1491, 'multiple_choice', 'A2', 'hotel_vocabulary', 'The team responsible for cleaning rooms and changing towels is called _____.', 'housekeeping', '["housekeeping", "catering", "maintenance", "security"]', NULL, NULL, NULL, 'The team that keeps the rooms clean and tidy.', 'Housekeeping is the department that cleans guest rooms, changes linen and towels, and maintains the general tidiness of the hotel.', '2026-03-23 08:55:51.646247+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('c84388e2-25e7-4f7c-b5fe-9fe5e73be857', 1492, 'multiple_choice', 'A2', 'hotel_vocabulary', 'The hotel asked for a _____ of €50 when the guest checked in, to cover any extra charges.', 'deposit', '["deposit", "discount", "receipt", "refund"]', NULL, NULL, NULL, 'An upfront payment to cover potential extra charges.', 'A deposit is an amount of money paid in advance as security. It is returned to the guest at check-out if no additional charges were incurred.', '2026-03-23 08:55:51.646247+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('00c563d7-4049-4491-aee4-d4e55e323df9', 1493, 'multiple_choice', 'A2', 'hotel_vocabulary', 'The room has a private bathroom inside it. It is described as _____.', 'en suite', '["en suite", "ground floor", "deluxe", "adjacent"]', NULL, NULL, NULL, 'French phrase meaning "in succession" — bathroom attached to room.', 'En suite (from French) means the bathroom is inside and private to the room, rather than shared. It is a very common term in British hotel and accommodation listings.', '2026-03-23 08:55:51.646247+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('22dcf2b6-414b-4786-a6bc-ea9b53272fa4', 1494, 'multiple_choice', 'A2', 'hotel_vocabulary', 'The guest is travelling alone and only needs one bed. They should book a _____ room.', 'single', '["single", "double", "twin", "family"]', NULL, NULL, NULL, 'One person, one bed.', 'A single room is designed for one person. It typically has one small bed. Compare: double (one large bed for two), twin (two single beds).', '2026-03-23 08:55:51.646247+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('9e30f64a-3b75-457f-85ed-04c734eecc18', 1495, 'multiple_choice', 'A2', 'hotel_vocabulary', 'The _____ floor is at street level — you don''t need the lift to reach it.', 'ground', '["ground", "base", "lobby", "entry"]', NULL, NULL, NULL, '___ floor — at street level. (UK English; US says "first floor".)', 'In British English, the ground floor is the floor at street level. In American English this is called the first floor. It is important to know for giving directions to guests.', '2026-03-23 08:55:51.646247+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('7aadf918-912d-47b5-877e-8d3aa4fb8aef', 1496, 'multiple_choice', 'B1', 'hotel_vocabulary', 'A guest asks if they can stay until 2pm instead of the usual 12pm. They are requesting a _____ check-out.', 'late', '["late", "extended", "flexible", "delayed"]', NULL, NULL, NULL, 'Beyond the standard check-out time.', 'Late check-out allows a guest to stay in their room beyond the standard check-out time, usually for an additional charge. It is one of the most common special requests.', '2026-03-23 08:55:51.646247+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('bd964319-6c20-4ae1-b8fa-83cf8d750a17', 1497, 'multiple_choice', 'B1', 'hotel_vocabulary', 'July and August are the hotel''s _____ season — prices are higher and rooms book up quickly.', 'peak', '["peak", "off", "shoulder", "quiet"]', NULL, NULL, NULL, '___ season — highest demand, highest prices.', 'Peak season is the period of highest demand, when prices are highest. Off-peak (or low season) is when demand and prices are lower. Shoulder season falls between the two.', '2026-03-23 08:55:51.646247+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('92987cf5-b424-433a-b9cf-ec3385cedd71', 1498, 'multiple_choice', 'B1', 'hotel_vocabulary', 'A guest booked a room but did not arrive or cancel. They are recorded as a _____.', 'no-show', '["no-show", "walk-in", "early bird", "drop-in"]', NULL, NULL, NULL, 'A guest who didn''t show up and didn''t cancel.', 'A no-show is a guest who has a confirmed reservation but fails to arrive without cancelling. Hotels typically charge a no-show fee equivalent to one night''s stay.', '2026-03-23 08:55:51.646247+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('99bdb6b7-552b-4ecd-91d8-84e500b16c33', 1499, 'multiple_choice', 'B1', 'hotel_vocabulary', 'A guest arrives without a reservation. They are known as a _____ guest.', 'walk-in', '["walk-in", "drop-off", "passing", "casual"]', NULL, NULL, NULL, 'A guest who arrives without a booking — walks straight in.', 'A walk-in guest arrives without a prior reservation and requests a room on the spot. Reception staff need to check live availability and offer the appropriate rate.', '2026-03-23 08:55:51.646247+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('dacfffae-09c4-4664-a12a-8a9916b1ab82', 1500, 'multiple_choice', 'B2', 'hotel_vocabulary', 'The price charged per room per night before any discounts are applied is known as the _____ rate.', 'rack', '["rack", "net", "corporate", "seasonal"]', NULL, NULL, NULL, '___ rate — the standard listed price before any discounts.', 'The rack rate is the full, published price of a room — the maximum rate before any discounts. Most guests pay less than the rack rate through promotions, loyalty programmes, or corporate agreements.', '2026-03-23 08:55:51.646247+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('00c17197-7994-44e0-beeb-0d0f2d833bbc', 1556, 'multiple_choice', 'A1', 'prepositions', 'The remote control is _____ the sofa — can you check down the back?', 'under', '["under", "over", "through", "beside"]', NULL, NULL, NULL, 'Below — beneath a piece of furniture.', 'Under means below or beneath something. Compare: on the sofa (resting on top), under the sofa (below it).', '2026-03-26 08:02:12.742714+00', NULL, NULL, 'en', '{"Preposition of place"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('dc0e5373-678e-4062-bb2c-4f6c0dcc4736', 1557, 'multiple_choice', 'A1', 'prepositions', 'There''s a café _____ the hotel — just walk out of the main entrance.', 'opposite', '["opposite", "beside", "behind", "along"]', NULL, NULL, NULL, 'Across from — facing each other.', 'Opposite means directly facing something on the other side of a road or space. Compare: next to (beside), behind (at the back of).', '2026-03-26 08:02:12.742714+00', NULL, NULL, 'en', '{"Preposition of place"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('1d689139-607b-4d67-9f59-386ff41f1032', 1559, 'multiple_choice', 'A1', 'prepositions', 'She sat _____ her two colleagues at the conference table.', 'between', '["between", "among", "beside", "opposite"]', NULL, NULL, NULL, 'Two specific items — one on each side.', 'Between is used for position in the middle of two specific things. Among is used with groups of three or more.', '2026-03-26 08:02:12.742714+00', NULL, NULL, 'en', '{"Preposition of place"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('e5b6c67e-fa1b-4e7d-8a85-dbe5679a121e', 1560, 'multiple_choice', 'A1', 'prepositions', 'The hotel is _____ the main road — you can''t miss it.', 'on', '["on", "in", "at", "by"]', NULL, NULL, NULL, '___ a road — same preposition as "on a street".', 'On is used with roads and streets: on the main road, on Oxford Street. In is used for enclosed spaces and cities: in the city centre.', '2026-03-26 08:02:12.742714+00', NULL, NULL, 'en', '{"Preposition of place"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('6830598d-6605-41c3-ad91-ba7af2814a81', 1561, 'multiple_choice', 'A2', 'prepositions', 'We walked _____ the park on our way home from the restaurant.', 'through', '["through", "across", "along", "past"]', NULL, NULL, NULL, '___ a park — entering one side and exiting the other.', 'Through means moving from one side to the other inside something. Across means from one side to the other over a surface. Along means following a path or route.', '2026-03-26 08:02:12.742714+00', NULL, NULL, 'en', '{"Preposition of movement"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('1ff6ff15-a99a-494c-8ab4-5fad2c4b8515', 1562, 'multiple_choice', 'A2', 'prepositions', 'The meeting was cancelled _____ short notice — nobody had time to prepare.', 'at', '["at", "on", "in", "with"]', NULL, NULL, NULL, 'Phrase: "___ short notice" = with little warning.', 'At short notice is a fixed expression meaning with very little warning or preparation time. Compare: at the last minute, at a moment''s notice.', '2026-03-26 08:02:12.742714+00', NULL, NULL, 'en', '{"Preposition of time","Fixed expression"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('0445c7f3-d6aa-4869-b6f8-a0258d75b731', 1563, 'multiple_choice', 'A2', 'prepositions', 'She''s been learning Spanish _____ about six months.', 'for', '["for", "since", "during", "over"]', NULL, NULL, NULL, 'Six months = duration. ___ + period of time.', 'For is used with a period of time (for six months, for two years). Since is used with a specific point in time (since January, since last year).', '2026-03-26 08:02:12.742714+00', NULL, NULL, 'en', '{"Preposition of time"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('9e2f567f-c09d-4a5f-a770-2839b0773bf1', 1564, 'multiple_choice', 'A2', 'prepositions', 'The shop is open _____ Monday _____ Saturday.', 'from / to', '["from / to", "between / and", "since / until", "at / on"]', NULL, NULL, NULL, 'A range with start and end. ___ X ___ Y.', 'From... to is used to express a range or span — of time, distance, or sequence. From Monday to Saturday means covering those days inclusively.', '2026-03-26 08:02:12.742714+00', NULL, NULL, 'en', '{"Preposition of time"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('256a3af1-e9f0-493d-aec5-2fba5bcf57f9', 1565, 'multiple_choice', 'A2', 'prepositions', 'I''ll be back _____ an hour — don''t start without me.', 'in', '["in", "after", "within", "by"]', NULL, NULL, NULL, '___ an hour = 60 minutes from now.', 'In + time period means after that amount of time has passed: in an hour = one hour from now. By means no later than a specific time.', '2026-03-26 08:02:12.742714+00', NULL, NULL, 'en', '{"Preposition of time"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('7c801101-71c7-4476-9bc0-011ab9b6498e', 1566, 'multiple_choice', 'B1', 'prepositions', 'She succeeded _____ getting the job despite having very little experience.', 'in', '["in", "at", "with", "on"]', NULL, NULL, NULL, 'Always: "succeeded ___ + -ing".', 'Succeed in doing something is the correct collocation. Compare: fail at, be good at, have difficulty in.', '2026-03-26 08:02:12.742714+00', NULL, NULL, 'en', '{"Dependent preposition"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('bd1936d1-704c-417e-9a07-c3ecfe917b2d', 1568, 'multiple_choice', 'B1', 'prepositions', 'He''s very dedicated _____ his work — he''s always the last to leave the office.', 'to', '["to", "for", "in", "at"]', NULL, NULL, NULL, 'Always: "dedicated ___ + something".', 'Dedicated to is the correct collocation. Compare: committed to, devoted to, passionate about.', '2026-03-26 08:02:12.742714+00', NULL, NULL, 'en', '{"Dependent preposition"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('656359bc-9c03-4b7b-94e2-ded5b3904bbd', 1512, 'gap_fill', 'C2', 'hotel_vocabulary', 'The hotel''s post-stay survey generated a _____ score of 72, which the general manager considered satisfactory but not exceptional.', 'Net Promoter', NULL, NULL, NULL, NULL, 'Survey metric measuring customer satisfaction (-100 to 100).', 'Net Promoter Score (NPS) measures guest loyalty by asking how likely they are to recommend the hotel. Scores range from -100 to +100. Above 50 is generally considered excellent in hospitality.', '2026-03-23 08:55:51.646247+00', NULL, NULL, 'en', '{}', false, 'Often abbreviated "NPS".', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('72a60e7a-2688-460c-9281-973ebf3712d6', 1567, 'multiple_choice', 'B1', 'prepositions', 'The new rules apply to everyone _____ exception.', 'without', '["without", "during", "beyond", "apart from"]', NULL, NULL, NULL, '___ exception = no exception.', 'Without exception is a fixed phrase meaning applying to absolutely everyone or everything, with no exclusions.', '2026-03-26 08:02:12.742714+00', NULL, NULL, 'en', '{"Fixed expression"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('e46a8256-0cb0-421f-b9fe-4a7f6b1b7d7e', 1569, 'multiple_choice', 'B2', 'prepositions', 'The decision was made _____ favour of the larger proposal after a lengthy debate.', 'in', '["in", "to", "for", "with"]', NULL, NULL, NULL, 'Phrase: "___ favour of" = supporting.', 'In favour of means in support of or preferring something. Compare: in favour of (supporting), against (opposing), in opposition to.', '2026-03-26 08:02:12.742714+00', NULL, NULL, 'en', '{"Fixed expression","Dependent preposition"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('6e10d633-dbbe-4e59-b896-09e4796f6126', 1570, 'multiple_choice', 'B2', 'prepositions', '_____ regard to your recent application, we are pleased to inform you that you have been shortlisted.', 'With', '["With", "Into", "As", "On"]', NULL, NULL, NULL, 'Formal phrase: "___ regard to" = concerning.', 'With regard to is a formal phrase used to introduce the subject of a letter or email. Compare: regarding, with reference to, concerning.', '2026-03-26 08:02:12.742714+00', NULL, NULL, 'en', '{"Fixed expression","Formal register"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('9b78a756-d8f8-4eda-83d1-f0ab6fbc1e6d', 1606, 'multiple_choice', 'A1', 'travel', 'What is a ''boarding pass''?', 'A document that allows you to get on a plane', '["A document that allows you to get on a plane", "A ticket for a train", "A room key in a hotel", "A type of passport"]', NULL, NULL, NULL, 'Document that allows you to board a plane.', 'A boarding pass is the document you receive after check-in that shows your seat number and allows you to board the plane.', '2026-03-27 08:23:03.995534+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('f9a69878-ae63-4112-a13e-c7660f1c15e9', 1607, 'multiple_choice', 'A1', 'travel', 'Which of these do you need to travel to most foreign countries?', 'a passport', '["a passport", "a boarding card", "a suitcase", "a travel guide"]', NULL, NULL, NULL, 'Official document needed for international travel.', 'A passport is the official government document needed to cross international borders. A boarding card is only needed once you are already at the airport.', '2026-03-27 08:23:03.995534+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('047a1f89-6202-4e32-92d2-7a01a364e6f4', 1608, 'multiple_choice', 'A2', 'travel', 'Where do you go to collect your bags after a flight?', 'the baggage claim', '["the baggage claim", "the departure gate", "the duty-free shop", "the check-in desk"]', NULL, NULL, NULL, 'The area where bags are collected after a flight.', 'Baggage claim (also "baggage reclaim" in British English) is the area in arrivals where passengers collect their checked luggage from a conveyor belt.', '2026-03-27 08:23:03.995534+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('bcf705eb-3da4-49c8-9f74-4ca4461e41b5', 1609, 'multiple_choice', 'A2', 'travel', 'What does ''return ticket'' mean?', 'a ticket to go somewhere and come back', '["a ticket to go somewhere and come back", "a ticket that cannot be changed", "a ticket for two people", "a refund for a cancelled flight"]', NULL, NULL, NULL, 'A ticket for going AND coming back.', 'A return ticket covers travel to a destination and back. A single (or one-way) ticket covers only one direction.', '2026-03-27 08:23:03.995534+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('c5c10152-967d-4ef1-9cb2-c2ae421d9fdd', 1610, 'multiple_choice', 'A2', 'travel', 'What is a ''hostel''?', 'a cheap place to stay, often with shared rooms', '["a cheap place to stay, often with shared rooms", "a luxury hotel", "a private villa", "a campsite"]', NULL, NULL, NULL, 'Budget accommodation, often with shared facilities.', 'A hostel offers budget accommodation, typically with dormitory-style shared rooms. They are popular with backpackers and younger travellers.', '2026-03-27 08:23:03.995534+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('ab32ab91-a079-4298-8907-b527c612dbc4', 1611, 'multiple_choice', 'A2', 'travel', 'What does ''delayed'' mean when talking about a flight?', 'it is leaving later than planned', '["it is leaving later than planned", "it has been cancelled", "it has landed early", "it is fully booked"]', NULL, NULL, NULL, 'Departing later than scheduled.', 'Delayed means the departure or arrival is later than the scheduled time. Cancelled means the flight will not operate at all.', '2026-03-27 08:23:03.995534+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('109566bf-fb80-40a9-a336-717e87a1c80c', 1612, 'multiple_choice', 'A2', 'travel', 'What is ''hand luggage''?', 'bags you take onto the plane with you', '["bags you take onto the plane with you", "bags stored under the plane", "a type of suitcase", "luggage sent ahead to the hotel"]', NULL, NULL, NULL, 'Bags small enough to take onboard with you.', 'Hand luggage (also "carry-on" in American English) is the bag you take into the cabin with you. It must fit in the overhead locker or under the seat.', '2026-03-27 08:23:03.995534+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('29e6dbce-f524-412c-8a56-4374aaaf2f04', 1613, 'multiple_choice', 'A2', 'travel', 'Which word means the opposite of ''departure''?', 'arrival', '["arrival", "return", "boarding", "landing"]', NULL, NULL, NULL, 'When you reach your destination — opposite of departure.', 'Departure and arrival are opposites. Departure = leaving; arrival = reaching your destination.', '2026-03-27 08:23:03.995534+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('c2d0d9f9-2f1f-4fde-a264-57e31c06a140', 1614, 'multiple_choice', 'A2', 'travel', 'What do you do when you ''check in'' to a hotel?', 'you register at the reception desk when you arrive', '["you register at the reception desk when you arrive", "you leave your room at the end of your stay", "you book a room in advance", "you pay for your stay"]', NULL, NULL, NULL, 'To register at a hotel''s reception when you arrive.', 'To check in to a hotel means to register at the front desk when you arrive. To check out means to leave and settle your bill.', '2026-03-27 08:23:03.995534+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('a325a679-30b1-45d7-9a48-00306705de70', 1615, 'multiple_choice', 'A2', 'travel', 'What is ''customs'' at an airport?', 'a place where officials check what you are bringing into the country', '["a place where officials check what you are bringing into the country", "a shop selling local souvenirs", "a place to exchange money", "a waiting area for flights"]', NULL, NULL, NULL, 'Where officials check what you''re bringing into a country.', 'Customs is the border control area where officials check whether passengers are bringing prohibited or taxable goods into the country.', '2026-03-27 08:23:03.995534+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('29fa0704-9684-4893-a8fe-9af1b7b7a17d', 1616, 'multiple_choice', 'B1', 'travel', 'Which word best completes the sentence: "Please _______ your seat belt during take-off."', 'fasten', '["fasten", "close", "lock", "tighten"]', NULL, NULL, NULL, 'To secure (a seatbelt) — opposite of unfasten.', 'Fasten your seatbelt is the standard instruction on flights. We fasten (or buckle) a seatbelt — not close or lock.', '2026-03-27 08:23:03.995534+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('a63e3a26-5945-455c-9142-d96f517eb803', 1617, 'multiple_choice', 'B1', 'travel', 'What does ''jet lag'' mean?', 'tiredness caused by travelling across time zones', '["tiredness caused by travelling across time zones", "a delay caused by bad weather", "an extra charge for heavy luggage", "a type of direct flight"]', NULL, NULL, NULL, 'Tiredness from crossing time zones — your body clock is out of sync.', 'Jet lag is the tiredness and disorientation caused by rapidly crossing multiple time zones. Your body clock struggles to adjust to the new local time.', '2026-03-27 08:23:03.995534+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('eced5a99-c9c7-47c1-ba74-de6103cc90bd', 1618, 'multiple_choice', 'B1', 'travel', 'Which of these is NOT a type of accommodation?', 'an itinerary', '["an itinerary", "a bed and breakfast", "a self-catering apartment", "a guesthouse"]', NULL, NULL, NULL, 'Three of the four options are types of accommodation. The fourth is a travel plan.', 'An itinerary is a travel plan or schedule — it is not a type of accommodation. The others (B&B, self-catering apartment, guesthouse) are all places to stay.', '2026-03-27 08:23:03.995534+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('5af2f435-5b39-482f-92ac-6461a353555e', 1619, 'multiple_choice', 'B2', 'travel', 'What does it mean to ''travel on a shoestring''?', 'to travel with very little money', '["to travel with very little money", "to travel very slowly", "to travel without luggage", "to travel alone"]', NULL, NULL, NULL, 'Idiom about a thin string — travelling with very little money.', '"Travel on a shoestring" means to travel with very little money, spending as little as possible. A shoestring budget = an extremely tight budget.', '2026-03-27 08:23:03.995534+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('93dee835-4ead-4763-92bb-2c490742f19d', 1620, 'multiple_choice', 'B2', 'travel', 'Which phrase describes a flight with no stops between origin and destination?', 'a non-stop flight', '["a non-stop flight", "a connecting flight", "an open-ended flight", "a charter flight"]', NULL, NULL, NULL, 'A direct flight — no stops between origin and destination.', 'A non-stop flight goes directly from origin to destination with no intermediate stops. A connecting flight requires changing planes at another airport.', '2026-03-27 08:23:03.995534+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('0e78be5a-910a-4a9e-af7a-8df7aa2db691', 1621, 'gap_fill', 'B1', 'travel', 'We need to _______ of the hotel before noon, or we''ll be charged for another night.', 'check out', NULL, NULL, NULL, '[{"answer": "get out", "feedback": "Close — but get out of doesn''t carry the specific meaning of settling your bill and handing back your key. The correct phrasal verb for leaving a hotel officially is check out."}]', 'To pay and leave the hotel — opposite of "check in".', '"Check out of" a hotel means to leave officially and return your key, usually by a set time. Note the preposition: check out of (not from) a hotel.', '2026-03-27 08:23:03.995534+00', NULL, NULL, 'en', '{}', false, 'Common phrasal verb in hospitality.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('5031f565-bb7a-48f6-bc1a-36c311b7183d', 1622, 'gap_fill', 'B1', 'travel', 'I always _______ travel insurance before going abroad, just in case something goes wrong.', 'take out', NULL, NULL, NULL, NULL, '___ + insurance — to obtain a policy.', '"Take out" insurance means to buy or obtain a policy. This is a fixed collocation — we take out insurance, a loan, or a subscription.', '2026-03-27 08:23:03.995534+00', NULL, NULL, 'en', '{}', false, 'Same as "___ a loan" or "___ a subscription".', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('cb584889-d3a9-4ecd-8b1c-6d5785006404', 1623, 'gap_fill', 'B2', 'travel', 'The airline offered us a full refund because the delay was completely beyond their _______.', 'control', NULL, NULL, NULL, NULL, 'Phrase: "beyond their ___" = outside their power.', '"Beyond their control" means the airline was not responsible for the situation. It was caused by external factors they could not influence.', '2026-03-27 08:23:03.995534+00', NULL, NULL, 'en', '{}', false, 'Idiom often used in formal contexts.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('4bad01be-af55-4a8b-b88f-46f48c134691', 1624, 'gap_fill', 'B2', 'travel', 'After twelve hours of travelling, we were completely _______ and went straight to bed.', 'worn out', NULL, NULL, NULL, NULL, 'Completely exhausted — like a worn-out shoe.', '"Worn out" is a phrasal adjective meaning extremely tired. It is commonly used after long journeys or periods of physical effort.', '2026-03-27 08:23:03.995534+00', NULL, NULL, 'en', '{}', false, 'Past participle form of "wear out".', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('296ea50a-f0d8-469a-b25d-0b7e74390b46', 1626, 'gap_fill', 'C1', 'travel', 'The airline industry has come _______ increasing scrutiny over its environmental impact.', 'under', NULL, NULL, NULL, NULL, 'Phrase: "come ___ scrutiny" = subjected to.', '"Come under scrutiny" means to be examined carefully or critically. Scrutiny = close, critical inspection. The airline industry faces scrutiny over its carbon footprint.', '2026-03-27 08:23:03.995534+00', NULL, NULL, 'en', '{}', false, 'Same as in "come ___ pressure".', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('ee57831c-7b1c-4eba-9048-19ca63f17348', 1627, 'gap_fill', 'C1', 'travel', 'She had a natural _______ for languages, picking up basic phrases wherever she travelled.', 'knack', NULL, NULL, NULL, NULL, 'Natural talent for picking something up.', 'A knack is a natural talent or ability for something, often acquired through practice. "She had a knack for languages" = it came easily and naturally to her.', '2026-03-27 08:23:03.995534+00', NULL, NULL, 'en', '{}', false, 'Informal alternative to "flair".', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('22ece213-234f-4ee9-ad89-d62f882986fe', 1628, 'gap_fill', 'C1', 'travel', 'The remote island was completely _______ from the outside world, accessible only by a twice-weekly ferry.', 'cut off', NULL, NULL, NULL, NULL, 'Isolated from communication or transport.', '"Cut off from" means isolated or separated from contact with something. An island cut off from the outside world has no regular connection to it.', '2026-03-27 08:23:03.995534+00', NULL, NULL, 'en', '{}', false, 'Phrasal verb — past participle as adjective.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('41e39ca8-8b5d-4a4a-aea1-c96f10267528', 1631, 'gap_fill', 'C1', 'travel', 'The immigration officer scrutinised his documents with _______ attention to detail before allowing him through.', 'meticulous', NULL, NULL, NULL, NULL, 'Extremely careful with detail — leaves nothing unchecked.', 'Meticulous means showing great attention to detail and care. "Meticulous attention to detail" is a common collocation used in formal or professional contexts.', '2026-03-27 08:23:03.995534+00', NULL, NULL, 'en', '{}', false, 'Latin "meticulosus" — fearful, then careful.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('85a6a50c-9db9-4181-9265-f6f52efba64a', 1632, 'gap_fill', 'C2', 'travel', 'The hidden surcharges of the budget airline far _______ the initially attractive ticket price.', 'outweighed', NULL, NULL, NULL, NULL, 'To be greater than — like one side of a balance is heavier.', '"Outweigh" means to be greater in weight, value, or importance than something else. The hidden costs were more significant than the cheap headline price.', '2026-03-27 08:23:03.995534+00', NULL, NULL, 'en', '{}', false, 'Compound verb: out + weigh.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('48a9a661-f45d-4268-a1c5-b3e014b819a0', 1633, 'gap_fill', 'C1', 'travel', 'The sudden surge in tourist numbers has pushed the city''s infrastructure to _______ point.', 'breaking', NULL, NULL, NULL, NULL, '___ point — the limit of what something can bear.', '"Pushing to breaking point" means reaching the limit of what something can bear before it collapses or fails. Infrastructure under strain from overtourism is a common context.', '2026-03-27 08:23:03.995534+00', NULL, NULL, 'en', '{}', false, 'Same as in "boiling ___".', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('b140b704-9c5a-4e0b-adf7-23babf40a64c', 1634, 'gap_fill', 'C2', 'travel', 'Years of underinvestment have left the country''s tourism sector in a state of _______.', 'stagnation', NULL, NULL, NULL, NULL, 'A state of no progress — like still water that doesn''t move.', 'Stagnation means a state of no growth, movement, or development. "A state of stagnation" = the sector has stopped developing or improving.', '2026-03-27 08:23:03.995534+00', NULL, NULL, 'en', '{}', false, 'Sharing a root with "stagnant".', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('12562d46-02cc-4761-ae22-3c837ab71207', 1635, 'gap_fill', 'C1', 'travel', 'The travel writer had an _______ ability to capture the essence of a place in just a few sentences.', 'uncanny', NULL, NULL, NULL, NULL, 'Mysterious or strangely accurate ability.', 'Uncanny means strange and difficult to explain, often in a way that feels almost supernatural. "An uncanny ability" = a remarkably unusual and impressive natural talent.', '2026-03-27 08:23:03.995534+00', NULL, NULL, 'en', '{}', false, 'An "___" feeling is unsettling because it''s strange.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('199fb1e4-2aab-4714-ab94-3615fc157258', 1636, 'multiple_choice', 'A1', 'sport', 'How many players are in a standard football team?', 'eleven', '["eleven", "nine", "twelve", "ten"]', NULL, NULL, NULL, 'A football team has this many players.', 'A standard football (soccer) team has 11 players on the pitch at a time, plus substitutes on the bench.', '2026-03-27 08:23:03.995534+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('7a272192-41d0-49f4-bbcb-d73fac88e6c9', 1637, 'multiple_choice', 'A1', 'sport', 'In which sport do players try to hit a ball into a hole using a club?', 'golf', '["golf", "cricket", "hockey", "polo"]', NULL, NULL, NULL, 'A sport played outdoors with clubs and a small white ball.', 'In golf, players use clubs to hit a small ball into a series of holes across a course, trying to use as few shots as possible.', '2026-03-27 08:23:03.995534+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('78f0350f-e451-4c30-9276-1e08d50f4799', 1638, 'multiple_choice', 'A2', 'sport', 'What do we call it when a footballer scores three goals in one match?', 'a hat-trick', '["a hat-trick", "a treble", "a triple", "a three-timer"]', NULL, NULL, NULL, 'Three goals (or successes) by one player in one match.', 'A hat-trick means scoring three goals in a single match. The term originally comes from cricket but is now used widely in football and other sports.', '2026-03-27 08:23:03.995534+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('7b53cd8c-fcc0-4722-be95-6063a5e89054', 1639, 'multiple_choice', 'A2', 'sport', 'What do you call the person who enforces the rules during a football match?', 'a referee', '["a referee", "a coach", "a manager", "a linesman"]', NULL, NULL, NULL, 'The official who enforces rules in a match.', 'A referee enforces the rules during a football match. A linesman (now called an assistant referee) helps by flagging for offside and out-of-play decisions.', '2026-03-27 08:23:03.995534+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('eb90ce82-971f-4b2c-83ed-868bdd8f51e0', 1640, 'multiple_choice', 'A2', 'sport', 'What is the name of the area where a football match is played?', 'a pitch', '["a pitch", "a court", "a track", "a ring"]', NULL, NULL, NULL, 'The grass area where football is played.', 'In football, the playing area is called a pitch. A court is used in tennis or basketball; a track in athletics; a ring in boxing.', '2026-03-27 08:23:03.995534+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('604f7436-c2c0-4da4-b662-a0b027d65bbb', 1641, 'multiple_choice', 'A2', 'sport', 'What does ''draw'' mean in sport?', 'when both teams finish with the same score', '["when both teams finish with the same score", "when a team wins by one point", "when a match is cancelled", "when a team scores in extra time"]', NULL, NULL, NULL, 'When neither team wins — same score.', 'A draw (British English) or tie means both teams or players finish with the same score. It is neither a win nor a loss.', '2026-03-27 08:23:03.995534+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('a9257422-72d8-4404-bf42-76e3c7aac434', 1642, 'multiple_choice', 'A2', 'sport', 'Which of these is a water sport?', 'swimming', '["swimming", "cycling", "gymnastics", "archery"]', NULL, NULL, NULL, 'A sport done in water.', 'Swimming is a water sport. Cycling and gymnastics take place on land; archery uses a bow and arrow on a range.', '2026-03-27 08:23:03.995534+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('581fe9e6-a282-496e-afc5-c64c7d973a9c', 1643, 'multiple_choice', 'A2', 'sport', 'What do we call the global multi-sport competition held every four years?', 'the Olympic Games', '["the Olympic Games", "the World Cup", "the Commonwealth Games", "the Grand Prix"]', NULL, NULL, NULL, 'A four-yearly global multi-sport competition.', 'The Olympic Games is a global multi-sport competition held every four years. The FIFA World Cup is football-only; the Grand Prix is motorsport.', '2026-03-27 08:23:03.995534+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('e784e9b4-bb83-4e51-b8d7-8d4c6e20b487', 1644, 'multiple_choice', 'A2', 'sport', 'What does a cyclist wear to protect their head?', 'a helmet', '["a helmet", "a cap", "a visor", "a mask"]', NULL, NULL, NULL, 'Head protection worn by cyclists.', 'Cyclists wear a helmet to protect their head in case of a fall. A cap offers no protection; a visor only covers the eyes; a mask covers the face.', '2026-03-27 08:23:03.995534+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('dd949327-9eec-4fd8-b159-931d8e7cf445', 1645, 'multiple_choice', 'A2', 'sport', 'What is a ''penalty'' in football?', 'a free kick taken from the penalty spot after a foul in the box', '["a free kick taken from the penalty spot after a foul in the box", "a red card given to a player", "a goal that is disallowed", "a substitution made during the match"]', NULL, NULL, NULL, 'A free kick from the spot after a foul in the box.', 'A penalty in football is a direct free kick from the penalty spot, awarded when a foul is committed inside the penalty area (the box).', '2026-03-27 08:23:03.995534+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('e16d84d3-47dc-42f7-b591-b22bbfc2d193', 1646, 'multiple_choice', 'B1', 'sport', 'What does it mean when a sports team is ''relegated''?', 'moved down to a lower division', '["moved down to a lower division", "moved up to a higher division", "banned from competing", "given a financial penalty"]', NULL, NULL, NULL, 'Sent down to a lower league.', 'Relegation means a team is moved down to a lower division of a league at the end of the season, usually because they finished near the bottom.', '2026-03-27 08:23:03.995534+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('1cc308c9-340f-43eb-a4ff-1e932be2475e', 1647, 'multiple_choice', 'B1', 'sport', 'In cricket, what is a ''century''?', 'when a batsman scores 100 runs in one innings', '["when a batsman scores 100 runs in one innings", "when a team wins by 100 runs", "a match lasting 100 overs", "a team''s 100th victory"]', NULL, NULL, NULL, 'A century in cricket = 100 runs.', 'In cricket, a century means a batsman has scored 100 runs in a single innings. It is considered a significant individual achievement.', '2026-03-27 08:23:03.995534+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('665534b0-efdd-40cd-8d11-8b3747085245', 1648, 'multiple_choice', 'B2', 'sport', 'What does it mean to ''pull a muscle''?', 'to injure a muscle by overstretching it', '["to injure a muscle by overstretching it", "to strengthen a muscle through training", "to feel general pain after exercise", "to cramp suddenly during a race"]', NULL, NULL, NULL, 'Stretching a muscle too far — common sports injury.', '"Pull a muscle" means to overstretch or partially tear a muscle, causing pain. It is a common sports injury, often happening suddenly during intense effort.', '2026-03-27 08:23:03.995534+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('b379715b-e73e-4b75-b8d6-90456b393b1a', 1649, 'multiple_choice', 'B1', 'sport', 'What is the term for the benefit a team gains from playing in front of their own supporters?', 'home advantage', '["home advantage", "home ground", "local support", "crowd effect"]', NULL, NULL, NULL, 'The benefit of playing at your own ground with your own fans.', 'Home advantage refers to the benefit a team gains from playing in their own stadium, supported by their own fans. Research shows it genuinely affects results.', '2026-03-27 08:23:03.995534+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('232baa20-ac8f-44c6-b2b0-f17f34da1420', 1650, 'multiple_choice', 'B2', 'sport', 'What does ''seeded'' mean in the context of a tennis tournament?', 'ranked to avoid other top players in the early rounds', '["ranked to avoid other top players in the early rounds", "chosen to represent your country", "given a wildcard entry", "automatically placed in the final"]', NULL, NULL, NULL, 'A ranking system to keep top players apart in early rounds.', 'In tennis tournaments, seeded players are ranked and placed in the draw so that the top players are less likely to meet each other in the early rounds.', '2026-03-27 08:23:03.995534+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('f4c1621a-2bba-4686-85ef-fc0b7c6fa50a', 1651, 'gap_fill', 'B1', 'sport', 'After months of intensive training, she finally _______ a personal best in the 5km race.', 'set', NULL, NULL, NULL, '[{"answer": "ran", "feedback": "Good instinct — but the correct collocation is set a personal best, not ran one. You set a record or PB in English."}]', 'Common verb pairing — ___ a personal best, ___ a record.', '"Set a personal best" (PB) means achieving your best-ever performance in a particular event. Athletes set records; coaches set training plans.', '2026-03-27 08:23:03.995534+00', NULL, NULL, 'en', '{}', false, 'Same as in "___ a goal".', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('2cffa53d-99bb-40d7-b75c-73edc0d9d97f', 1652, 'gap_fill', 'B1', 'sport', 'The striker was _______ after receiving two yellow cards in the same match.', 'sent off', NULL, NULL, NULL, NULL, 'Removed from the game — usually after a red card.', '"Sent off" means a player was shown a red card and ordered to leave the pitch. Two yellow cards in the same match also result in a player being sent off.', '2026-03-27 08:23:03.995534+00', NULL, NULL, 'en', '{}', false, 'Form: past simple passive.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('644bfe23-3c76-4da2-83ad-615f12b2f033', 1653, 'gap_fill', 'B2', 'sport', 'Despite being _______ at half-time, the team managed to turn the game around and win 3-2.', 'two goals down', NULL, NULL, NULL, NULL, 'Behind by two goals at half-time.', '"Two goals down" means losing by two goals at that point in the match. It is a compound adjective used after a verb: "they were two goals down at half-time".', '2026-03-27 08:23:03.995534+00', NULL, NULL, 'en', '{}', false, 'Phrase: "X goals ___" = losing by X.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('5ece3423-2d98-45d4-a6d2-9bc8692bc51e', 1654, 'gap_fill', 'B2', 'sport', 'The young athlete _______ the sport at the age of twelve and never looked back.', 'took up', NULL, NULL, NULL, NULL, 'To start (a sport, a hobby).', '"Take up" a sport means to start doing it regularly, often as a new hobby or serious pursuit.', '2026-03-27 08:23:03.995534+00', NULL, NULL, 'en', '{}', false, 'Form: past simple. Common with sports.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('cdff7109-9e82-45e1-ad02-dab170d4dceb', 1655, 'gap_fill', 'B2', 'sport', 'The marathon runner _______ the wall at kilometre thirty but pushed through to finish the race.', 'hit', NULL, NULL, NULL, NULL, '___ the wall — marathon runner''s point of exhaustion.', '"Hit the wall" is an idiom meaning to reach a point of physical or mental exhaustion where you feel you cannot continue. It is especially common in long-distance running.', '2026-03-27 08:23:03.995534+00', NULL, NULL, 'en', '{}', false, 'Idiom: "hitting the wall".', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('49382129-aded-41fd-b0f2-84c4bf45669e', 1656, 'gap_fill', 'C1', 'sport', 'The sprinter was _______ after traces of a banned substance were found in her sample.', 'disqualified', NULL, NULL, NULL, NULL, 'Officially banned from competition.', 'Disqualified means officially excluded from a competition, usually for breaking the rules — such as failing a drugs test. The disqualification strips any results or medals.', '2026-03-27 08:23:03.995534+00', NULL, NULL, 'en', '{}', false, 'Dis- (not) + qualified = not allowed to compete.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('3904c51d-99c2-44d9-8244-202e00e95f9d', 1657, 'gap_fill', 'C1', 'sport', 'After a decade at the top of the sport, the reigning champion finally _______ to a younger rival.', 'succumbed', NULL, NULL, NULL, NULL, 'Lost to — finally gave way.', '"Succumb to" means to fail to resist something or someone, often after a long struggle. Here, the champion eventually lost to a younger rival despite fighting to stay at the top.', '2026-03-27 08:23:03.995534+00', NULL, NULL, 'en', '{}', false, 'Latin "succumbere" — to lie under.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('473ce27a-2e1a-4ed0-bcab-24eb6fb12ddc', 1658, 'gap_fill', 'C1', 'sport', 'The team''s pre-season training was _______ building the physical and mental resilience needed for a long campaign.', 'geared towards', NULL, NULL, NULL, NULL, 'Aimed at — designed for a specific purpose.', '"Geared towards" means designed or focused on achieving a particular aim. Pre-season training was specifically designed to build resilience for the long season ahead.', '2026-03-27 08:23:03.995534+00', NULL, NULL, 'en', '{}', false, 'Like gears in a machine — specifically configured.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('2ee11364-6669-46f1-96ad-894e6d096ce4', 1659, 'gap_fill', 'C1', 'sport', 'The referee''s controversial decision _______ a wave of protest from the home supporters.', 'sparked', NULL, NULL, NULL, NULL, 'Triggered (a reaction, a response) suddenly.', '"Spark" means to cause or trigger something, especially a strong reaction. The controversial decision immediately caused a wave of protest.', '2026-03-27 08:23:03.995534+00', NULL, NULL, 'en', '{}', false, 'Like a spark starting a fire.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('f4f7acb3-4e55-448b-9966-ce4471c3fe66', 1660, 'gap_fill', 'C1', 'sport', 'His performance in the final was nothing short of _______, breaking two world records in the process.', 'extraordinary', NULL, NULL, NULL, NULL, 'Beyond the ordinary — exceptional.', '"Nothing short of extraordinary" is a strong emphatic phrase meaning truly remarkable. "Nothing short of X" = X and nothing less than X.', '2026-03-27 08:23:03.995534+00', NULL, NULL, 'en', '{}', false, 'Extra + ordinary = above the ordinary.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('3162b10f-3343-42e2-9285-dd0a6494970e', 1661, 'gap_fill', 'C1', 'sport', 'Years of financial mismanagement left the club on the _______ of administration.', 'brink', NULL, NULL, NULL, NULL, 'On the ___ of = at the edge of.', '"On the brink of" means very close to the edge of something, usually negative. "On the brink of administration" = the club was very close to financial collapse.', '2026-03-27 08:23:03.995534+00', NULL, NULL, 'en', '{}', false, 'Same as "on the verge of".', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('0a696e69-6830-449d-b694-ef194d6d6033', 1662, 'gap_fill', 'C1', 'sport', 'The veteran boxer relied on _______ rather than power to outpoint his younger, stronger opponent.', 'guile', NULL, NULL, NULL, NULL, 'Cunning, clever skill — relying on tricks rather than strength.', 'Guile means cunning intelligence and the ability to deceive or outwit an opponent. A veteran boxer may use guile — clever tactics and ring-craft — rather than physical power.', '2026-03-27 08:23:03.995534+00', NULL, NULL, 'en', '{}', false, 'Sharing a root with "wily".', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('19651b8e-409e-47ec-ab6c-8d603af384a0', 1663, 'gap_fill', 'C1', 'sport', 'The underdog team _______ the odds to reach the final, defeating three higher-ranked opponents.', 'defied', NULL, NULL, NULL, NULL, 'To go against — to refuse to follow expectations.', '"Defy the odds" means to succeed despite it being considered very unlikely. The underdog was not expected to reach the final but managed to do so.', '2026-03-27 08:23:03.995534+00', NULL, NULL, 'en', '{}', false, 'Sharing a root with "defiance".', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('b870b2c1-0b74-49b0-8f55-89682024c307', 1664, 'gap_fill', 'C2', 'sport', 'Financial _______ meant the club could no longer compete with the wealthiest teams for top signings.', 'constraints', NULL, NULL, NULL, NULL, 'Restrictive limits — what holds you back.', 'Constraints are limitations or restrictions, especially on money or resources. Financial constraints prevented the club from competing for expensive players.', '2026-03-27 08:23:03.995534+00', NULL, NULL, 'en', '{}', false, 'Sharing a root with "constrain".', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('1b40fdc6-14d1-4b24-8012-f01cfe673f26', 1665, 'gap_fill', 'C1', 'sport', 'Her _______ commitment to daily training set her apart from competitors with similar natural ability.', 'unwavering', NULL, NULL, NULL, NULL, 'Never wavering — completely consistent.', '"Unwavering" means never changing or weakening; completely steady and committed. "Unwavering commitment" = total, consistent dedication without ever giving up.', '2026-03-27 08:23:03.995534+00', NULL, NULL, 'en', '{}', false, 'Un- (not) + wavering = not changing.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('76c82d14-c56c-40c8-aec1-872bedb0b9f9', 1666, 'multiple_choice', 'A1', 'phrasal_verbs', 'It''s cold outside — _____ your coat before you leave.', 'put on', '["put on", "put off", "put up", "put in"]', NULL, NULL, NULL, 'Adding a layer of clothing — the verb for getting dressed in something.', 'Put on means to place clothing or accessories on your body. The opposite is take off (to remove clothing). Both are essential verbs for everyday conversation.', '2026-03-30 07:58:13.455589+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('c7f80a25-1b42-4846-84cc-bbb4d89285a9', 1667, 'multiple_choice', 'A1', 'phrasal_verbs', 'I''m tired. I need to _____ at about ten o''clock tonight.', 'go to bed', '["go to bed", "go off", "go up", "go back"]', NULL, NULL, NULL, 'The phrase for retiring for the night — getting under the covers.', 'Go to bed means to get into bed in order to sleep. Compare: go to sleep (the moment you fall asleep) and wake up (to stop sleeping). These three are the most common verbs for talking about sleep routines.', '2026-03-30 07:58:13.455589+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('64e4f1e6-6119-4801-88e2-02bde8acbac0', 1668, 'multiple_choice', 'A1', 'phrasal_verbs', 'The police had to _____ the road after the accident.', 'close off', '["close off", "shut up", "put off", "close up"]', NULL, NULL, NULL, 'To block access to an area, often with tape or barriers.', 'Close off means to block a road or area so that people cannot go through it. The police often close off roads after accidents. Compare: block off (the same idea — to stop people passing through).', '2026-03-30 07:58:13.455589+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('76490fcb-9bb7-4afe-93d4-35f9a0e1b3fc', 1669, 'multiple_choice', 'A1', 'phrasal_verbs', 'I forgot my phone. I need to _____ home and get it.', 'go back', '["go back", "go off", "go out", "go over"]', NULL, NULL, NULL, 'Returning to a place you''ve come from.', 'Go back means to return to a place you were before. Compare: come back (return to where the speaker is) and go back (return to a previous location). Both are extremely common in everyday English.', '2026-03-30 07:58:13.455589+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('9cfb5046-0f3a-405d-819e-81e76c93ee50', 1670, 'multiple_choice', 'A2', 'phrasal_verbs', 'She was feeling sad, but her friends managed to _____ her _____.', 'cheer up', '["cheer up", "calm down", "fill in", "sort out"]', NULL, NULL, NULL, 'Lifting someone''s mood when they''re feeling low.', 'Cheer up means to become happier, or to make someone else feel happier. It can be used as a command (Cheer up!) or as a transitive verb (Her friends cheered her up). Compare: cheer on (to encourage someone in a competition).', '2026-03-30 07:58:13.455589+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('123a8f8e-dbf4-4e69-9384-4cfa8a5a28f9', 1671, 'multiple_choice', 'A2', 'phrasal_verbs', 'Please _____ — the doctor will see you in a few minutes.', 'sit down', '["sit down", "stand up", "lie down", "bend down"]', NULL, NULL, NULL, 'Taking a seat — moving from standing to a chair.', 'Sit down means to move from a standing position into a seated one. The opposite is stand up. Lie down means to move into a horizontal position. These position verbs are essential for giving and following instructions.', '2026-03-30 07:58:13.455589+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('6f51d4a0-aeb3-4d06-aff9-f7a29071f1bc', 1672, 'multiple_choice', 'A2', 'phrasal_verbs', 'Can you _____ the kids while I do the shopping?', 'pick up', '["pick up", "pick on", "pick out", "pick at"]', NULL, NULL, NULL, 'Collecting someone (children, parcels) from where they are.', 'Pick up has several meanings: to lift something from a surface, to collect someone from a place, or to learn something informally. Here it means to collect the kids from a different place. It is one of the most versatile phrasal verbs in English.', '2026-03-30 07:58:13.455589+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('1e1e60e3-2d97-40fe-a2a8-343c767ba552', 955, 'gap_fill', 'B1', 'phrasal_verbs', 'Don''t worry about the house while you''re away — I''ll _______ it.', 'look after', NULL, NULL, NULL, NULL, 'To take care of someone or something.', 'To look after someone or something means to take care of it — making sure it is safe, clean, or well-maintained.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Phrasal verb"}', false, 'Two words. Starts with l___ a___.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('0c6d1f93-6072-4d16-9e4f-f19b79160e45', 1673, 'multiple_choice', 'A2', 'phrasal_verbs', 'She needs to _____ — she''s getting very stressed and it''s not good for her.', 'calm down', '["calm down", "cheer up", "set up", "break down"]', NULL, NULL, NULL, 'Becoming less stressed or angry — the opposite of getting worked up.', 'Calm down means to become less anxious, angry, or excited — or to help someone else do so. It can be used as a command (Calm down!) or transitively (She tried to calm him down). Compare: cheer up (become happier) and cool down (reduce temperature or anger).', '2026-03-30 07:58:13.455589+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('ec4ad139-8c9f-4dd7-84c0-13e818b9f196', 1674, 'multiple_choice', 'A2', 'phrasal_verbs', 'We need to _____ early tomorrow — the train leaves at six.', 'set off', '["set off", "set up", "set on", "set back"]', NULL, NULL, NULL, 'Beginning a journey — leaving from where you are.', 'Set off means to begin a journey. It is interchangeable with set out in most contexts. Compare: leave (more neutral), depart (more formal). Set off can also mean to trigger something, like an alarm — context makes the meaning clear.', '2026-03-30 07:58:13.455589+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('ab35a007-4faa-4924-9e42-5053bc35fbe9', 1675, 'multiple_choice', 'A2', 'phrasal_verbs', 'I don''t understand this exercise. Can you _____ it for me?', 'go over', '["go over", "go up", "go back", "go on"]', NULL, NULL, NULL, 'Reviewing something carefully, step by step.', 'Go over something means to explain or review it carefully. It is slightly more informal than go through, which implies working through something step by step. Both are extremely useful for classroom and workplace contexts.', '2026-03-30 07:58:13.455589+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('c93dbde6-d871-455a-bfa7-6f90e221782e', 1676, 'multiple_choice', 'B1', 'phrasal_verbs', 'They used to be very close, but they _____ over a stupid argument last year.', 'fell out', '["fell out", "fell apart", "fell behind", "fell through"]', NULL, NULL, NULL, 'When friends stop being friends because of an argument.', 'Fall out (with someone) means to have an argument that damages or ends a friendship or relationship. Compare: fall apart (something breaks or collapses), fall behind (not keep up with progress), fall through (a plan fails). Note: fall out does not need an object — you say they fell out, not they fell out each other.', '2026-03-30 07:58:13.455589+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('48007e00-6c04-4893-a992-9eccbc073430', 1677, 'multiple_choice', 'B1', 'phrasal_verbs', 'She _____ an interesting point about the cost of the project in the meeting.', 'brought up', '["brought up", "brought in", "brought about", "brought out"]', NULL, NULL, NULL, 'Raising or mentioning a topic in a conversation or meeting.', 'Bring up a point or topic means to introduce it into a conversation or discussion. It is also used to mean to raise a child (she was brought up in Madrid). Bring about means to cause something. Bring out means to produce or release something. Context is key.', '2026-03-30 07:58:13.455589+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('7668b50c-3b8f-4324-ba3a-1646576399f4', 1678, 'multiple_choice', 'B1', 'phrasal_verbs', 'Don''t worry — I''ll _____ the problem. Just give me a couple of days.', 'sort out', '["sort out", "sort through", "sort over", "sort up"]', NULL, NULL, NULL, 'Solving a problem or organising something that''s in disorder.', 'Sort out means to resolve a problem, organise something, or deal with a situation. It is very common in British English. Compare: work out (solve a problem through effort), figure out (understand or solve something). Sort through means to go through a collection of things and organise them.', '2026-03-30 07:58:13.455589+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('d02b4077-85e6-4a3a-bd02-eae0f2edfaf8', 1679, 'multiple_choice', 'B2', 'phrasal_verbs', 'It took her a while, but she eventually _____ to doing her tax return.', 'got round', '["got round", "got over", "got through", "got along"]', NULL, NULL, NULL, 'Finally doing something you''ve been putting off — that tax return.', 'Get round to (doing) something means to finally find the time to do something you have been delaying. It implies the task was on your list but kept being postponed. Compare: get over (recover from something), get through (finish or survive something difficult).', '2026-03-30 07:58:13.455589+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('7b9abf44-f8db-4a9b-9289-d018f10da4d3', 1680, 'multiple_choice', 'B2', 'phrasal_verbs', 'She _____ a bad cold just before her holiday and had to rest for a week.', 'came down with', '["came down with", "came up with", "came across", "came round"]', NULL, NULL, NULL, 'Catching an illness — the verb for becoming ill.', 'Come down with an illness means to begin to suffer from it, usually quite suddenly. Compare: come up with (to think of an idea or solution), come across (to find something unexpectedly), come round (to regain consciousness, or to change your opinion).', '2026-03-30 07:58:13.455589+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('9f98c418-bf10-4381-8b72-15aae5b111a0', 1696, 'multiple_choice', 'A1', 'business_phrasal_verbs', 'We need to _____ the new employee when she starts work on Monday.', 'train up', '["train up", "sort out", "bring up", "check in"]', NULL, NULL, NULL, 'To prepare someone for a job by teaching them the skills they need.', 'Train up someone/train someone up means to give them the key information they need before a task or event. It is very common in professional contexts.', '2026-03-30 08:25:59.401228+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('8cbaa036-eba6-4415-903f-d1f603033cf3', 1697, 'multiple_choice', 'A1', 'business_phrasal_verbs', 'Could you _____ the main points of the meeting in an email afterwards?', 'write up', '["write up", "write off", "write down", "write in"]', NULL, NULL, NULL, 'To produce a formal written record of something — like meeting minutes.', 'Write up means to produce a written record or summary of something, such as notes, a report, or meeting minutes. Compare: write off (to cancel a debt, or to decide something is not worth pursuing), write down (to note something quickly).', '2026-03-30 08:25:59.401228+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('728b094c-5038-40e3-b515-23945d47aee8', 957, 'gap_fill', 'B2', 'phrasal_verbs', 'The deal _______ at the last minute because of a legal disagreement.', 'fell through', NULL, NULL, NULL, NULL, 'To fail unexpectedly — like falling through a trapdoor.', 'If a deal or plan falls through, it fails to happen — usually at a late stage, after seeming likely to succeed.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Phrasal verb"}', false, 'Two words. Past tense. Starts with f___ t___.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('40f6e26e-29a6-4d27-b1d9-bb4ca1d5773d', 958, 'gap_fill', 'B2', 'phrasal_verbs', 'Unfortunately, the project was _______ due to a lack of funding.', 'called off', NULL, NULL, NULL, '[{"answer": "cancelled", "feedback": "Good — \"cancelled\" works here. \"Called off\" is the more idiomatic phrasal verb in English."}, {"answer": "canceled", "feedback": "Good — \"cancelled\" works here. \"Called off\" is the more idiomatic phrasal verb in English."}]', 'To cancel — same phrasal verb as cancelling a search.', 'To call something off means to cancel it, usually an event or plan that had already been arranged.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Phrasal verb"}', false, 'Two words. Past tense. Starts with c___ o___.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('850d2639-45bd-4a34-8b67-97c4b80c1554', 959, 'gap_fill', 'C1', 'phrasal_verbs', 'He managed to _______ any serious consequences despite breaking the rules.', 'get away with', NULL, NULL, NULL, NULL, 'To avoid punishment for wrongdoing.', 'To get away with something means to do something wrong without being caught or punished.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Phrasal verb"}', false, 'Three words. Starts with g___ a___ w___.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('e301a649-f54d-430e-97eb-aeba72cf440a', 960, 'gap_fill', 'C1', 'phrasal_verbs', 'It took years, but she finally _______ her parents'' high expectations.', 'lived up to', NULL, NULL, NULL, NULL, 'To meet or fulfil expectations.', 'To live up to expectations means to be as good as people hoped or expected. If you fail to meet those standards, you don''t live up to them.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Phrasal verb"}', false, 'Three words. Past tense. Starts with l___ u___ t___.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('6661749c-170f-4fc8-8447-7c6d8b5604db', 967, 'gap_fill', 'C2', 'phrasal_verbs', 'Her genuine enthusiasm for the subject _______ in every lecture she gave.', 'shone through', NULL, NULL, NULL, '["came through"]', 'To become evident — like sunlight breaking through clouds.', 'To shine through means to be clearly visible or evident, even when something might be expected to hide it. Come through has a similar meaning.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Phrasal verb"}', false, 'Two words. Past tense. Starts with s___ t___.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('11cbf5f5-370c-4d5b-8e94-bea71b726b26', 968, 'gap_fill', 'C2', 'phrasal_verbs', 'The new director promised to _______ the outdated practices that had held the company back.', 'do away with', NULL, NULL, NULL, '["get rid of", "phase out"]', 'To eliminate or get rid of (something outdated).', 'To do away with something means to abolish or eliminate it completely. Stronger than phase out, which implies a gradual process.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Phrasal verb"}', false, 'Three words. Starts with d___ a___ w___.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('99d2b08e-788c-4184-867a-c3f85aa147f7', 984, 'gap_fill', 'B1', 'hotel_vocabulary', 'When I checked in, I had to leave my credit card details to cover any _______ — extra charges for minibar use or room damage.', 'incidentals', NULL, NULL, NULL, NULL, 'Small extra charges that come up during your stay (minibar, damages).', 'Incidentals are additional charges beyond the room rate — minibar use, phone calls, laundry, or damage. Hotels hold a pre-authorisation on your card to cover these.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Hotel vocabulary"}', false, 'Plural noun. Eleven letters. Starts with i___.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('89befc44-c0e9-4f50-bc5c-1e1c4a9c8423', 985, 'gap_fill', 'B1', 'hotel_vocabulary', 'We arrived two hours before the official _______ time, but the hotel let us in straight away.', 'check-in', NULL, NULL, NULL, '["check in"]', '___ time = the official time you can register at the hotel.', 'Check-in time is the earliest you can access your room. Check-out time is the latest you must leave. Early check-in or late check-out can often be arranged, sometimes for a fee.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Hotel vocabulary",Collocation}', false, 'Hyphenated noun. c___-i___.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('202e85ae-51aa-4a59-8187-9645cbfd31e7', 986, 'gap_fill', 'B2', 'hotel_vocabulary', 'Because we were returning guests, the hotel gave us a free room _______ — we moved from a standard double to a junior suite.', 'upgrade', NULL, NULL, NULL, NULL, 'To move to a higher room category — like an airline ___.', 'An upgrade means moving to a better room — larger, higher floor, or a suite — at no extra cost. Hotels offer these as a gesture of goodwill, especially to loyal guests.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Hotel vocabulary"}', false, 'Seven letters. Starts with u___. The opposite of downgrade.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('825c9681-5e1b-4c10-8ae1-e2d79bf1c8c9', 987, 'gap_fill', 'B2', 'hotel_vocabulary', 'The hotel operates a strict _______ policy — if you cancel less than 48 hours before arrival, you are charged in full.', 'cancellation', NULL, NULL, NULL, NULL, '___ policy = the rules around cancelling a booking.', 'A cancellation policy sets out the terms for cancelling a booking. Many hotels charge a full or partial fee if you cancel within a specified window before arrival.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Hotel vocabulary",Collocation}', false, 'Noun from the verb "cancel". Twelve letters.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('58bf113f-112f-49b8-9ebd-1b6987bb5083', 988, 'gap_fill', 'B2', 'hotel_vocabulary', 'The maid performed _______ service in the evening — she turned down the beds and left chocolates on the pillow.', 'turn-down', NULL, NULL, NULL, '["turndown"]', '___ service = the evening service preparing the room for sleep.', 'Turn-down service is an evening housekeeping visit — the maid folds back the bedcovers, dims the lights, and often leaves a small treat such as chocolates.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Hotel vocabulary",Collocation}', false, 'Hyphenated noun. t___-d___.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('4b7aff66-4e48-4dee-a92d-98c1993aeee3', 989, 'gap_fill', 'C1', 'hotel_vocabulary', 'The hotel''s _______ rate last August reached 97% — nearly every room was occupied.', 'occupancy', NULL, NULL, NULL, NULL, '___ rate = the percentage of rooms filled.', 'Occupancy rate is the percentage of rooms that are occupied at any given time. A 97% occupancy rate means almost every room is filled — an excellent result for the hotel.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Hotel vocabulary","Business vocabulary"}', false, 'Nine letters. Starts with o___. Noun from "occupy".', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('153d76ff-90de-4210-8d25-74234b97d190', 990, 'gap_fill', 'C1', 'hotel_vocabulary', 'The hotel uses _______ pricing — room rates change automatically according to demand and availability.', 'dynamic', NULL, NULL, NULL, NULL, '___ pricing = prices that change in real time based on demand.', 'Dynamic pricing means rates change automatically based on demand, season, and availability. When the hotel is nearly full, prices rise; when it is quiet, they fall.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Hotel vocabulary","Business vocabulary"}', false, 'Seven letters. Starts with d___. The opposite of static.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('19bed391-4124-462f-8447-0ee9c2bfeabc', 1698, 'multiple_choice', 'A1', 'business_phrasal_verbs', 'We need to _____ the project proposal before the board meeting next week.', 'finish off', '["finish off", "wrap off", "put off", "call off"]', NULL, NULL, NULL, 'To complete the final stage of a task.', 'Finish off means to complete the final part of something. It is used when a task is almost done and you need to do the last bit. Compare: wrap up (to finish something completely, often a meeting or project).', '2026-03-30 08:25:59.401228+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('a23c8040-1108-48cf-bb33-04b211ff5075', 1699, 'multiple_choice', 'A2', 'business_phrasal_verbs', 'The new regional manager will _____ responsibility for all southern offices from next month.', 'take over', '["take over", "take on", "take up", "take off"]', NULL, NULL, NULL, 'To assume responsibility for something previously handled by someone else.', 'Take over responsibility or a role means to assume control or authority for it. Compare: take on (to accept new work or responsibilities), take up (to start a new activity or use space/time). Take over often implies replacing someone else in a role.', '2026-03-30 08:25:59.401228+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('7a5de67b-9e20-42b9-b434-e290e843c021', 1700, 'multiple_choice', 'A2', 'business_phrasal_verbs', 'Sales have been slow this quarter. We need to _____ a new marketing strategy.', 'come up with', '["come up with", "come across", "come down on", "come round"]', NULL, NULL, NULL, 'To produce or invent an idea — what designers and creatives do.', 'Come up with means to think of or produce an idea, solution, or plan. It is one of the most useful phrasal verbs in business English. Compare: come across (to find something unexpectedly or to make a particular impression), think up (to invent or devise something).', '2026-03-30 08:25:59.401228+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('eb2eb704-5a5d-43c1-874d-c027b7b6b634', 1701, 'multiple_choice', 'A2', 'business_phrasal_verbs', 'The supplier let us down badly. We need to _____ an alternative as soon as possible.', 'look for', '["look for", "look up", "look after", "look into"]', NULL, NULL, NULL, 'To search for something — the basic verb for trying to find.', 'Look for means to search for something or someone. Compare: look up (to find information in a reference source), look into (to investigate), look after (to take care of). In business, look for is essential for talking about sourcing, recruitment, and procurement.', '2026-03-30 08:25:59.401228+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('2853f140-62b3-4071-90a9-e8a63a8d8dd4', 1702, 'multiple_choice', 'A2', 'business_phrasal_verbs', 'The project manager asked the team to _____ the schedule before the client presentation.', 'go through', '["go through", "go in", "go back", "go along"]', NULL, NULL, NULL, 'To examine something carefully from start to finish.', 'Go through something means to examine or review it carefully, step by step. It is slightly more thorough than go over, which implies a quicker check. Both are common in business meetings. Compare: run through (to review quickly, often in a presentation context).', '2026-03-30 08:25:59.401228+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('048b519e-41f9-4751-9adb-684e630a577c', 1703, 'multiple_choice', 'A2', 'business_phrasal_verbs', 'After six months of negotiations, both companies decided to _____ the deal.', 'call off', '["call off", "call up", "call in", "call on"]', NULL, NULL, NULL, 'To cancel something that was planned — like a meeting or event.', 'Call off means to cancel something that was planned, such as a deal, meeting, or event. Compare: call up (to telephone someone, or to summon someone), call in (to ask for expert help, or to report sick), call on (to visit someone or to ask someone to do something).', '2026-03-30 08:25:59.401228+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('7ab3a348-cfaa-433a-9572-6444e79043e8', 1704, 'multiple_choice', 'A1', 'business_phrasal_verbs', 'I need to _____ with my manager before I can confirm the decision.', 'check in', '["check in", "check out", "check up", "check off"]', NULL, NULL, NULL, 'To briefly contact someone to update them or get input.', 'Check in with someone means to make brief contact to report progress, share an update, or ask for approval. It is very common in modern workplace English. Compare: check out (to investigate something, or to leave a hotel), check up on (to monitor someone''s progress or behaviour).', '2026-03-30 08:25:59.401228+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('2814d6a9-1638-42b3-a8ca-7140cc304217', 1705, 'multiple_choice', 'A1', 'business_phrasal_verbs', 'Can we _____ the agenda before the meeting starts so everyone knows what we''re covering?', 'run through', '["run through", "run out of", "run up", "run away"]', NULL, NULL, NULL, 'To quickly review something step by step before starting.', 'Run through something means to go through it quickly to check or explain it. It is very common in presentation and meeting contexts. Compare: go through (more thorough), go over (a quick check), run over (to exceed a time limit, or to review quickly — similar to run through in some contexts).', '2026-03-30 08:25:59.401228+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('4948fbb1-db60-4436-99e9-4165c25aff27', 1706, 'multiple_choice', 'B1', 'business_phrasal_verbs', 'The new software has really _____ the time it takes to process invoices.', 'cut down on', '["cut down on", "cut out", "cut up", "cut off"]', NULL, NULL, NULL, 'To reduce the amount of something — like time or expenses.', 'Cut down on something means to reduce it. In business, cut down on time, costs, or waste is very common. Compare: cut back (to reduce expenditure or activity more broadly), cut out (to remove something entirely), cut off (to stop a supply or communication). All are useful but have distinct meanings.', '2026-03-30 08:25:59.401228+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('518c4812-8eab-40cb-8943-e87d151519f1', 1707, 'multiple_choice', 'B1', 'business_phrasal_verbs', 'We need to _____ the new pricing structure to the sales team before it goes live.', 'roll out', '["roll out", "roll back", "roll over", "roll up"]', NULL, NULL, NULL, 'To launch something new across an organisation — like pricing or software.', 'Roll out means to introduce or launch something in stages, often across an organisation or market. Compare: roll back (to reverse a decision or policy), phase in (to introduce gradually over time). The noun rollout is widely used in business and technology contexts.', '2026-03-30 08:25:59.401228+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('6483aa69-0565-4e4f-9b54-2caf127a953d', 1708, 'multiple_choice', 'B1', 'business_phrasal_verbs', 'The project is _____ schedule — we''re going to need to bring in extra support.', 'falling behind', '["falling behind", "falling off", "falling through", "falling out"]', NULL, NULL, NULL, 'Not keeping up with a schedule — the team is slipping.', 'Fall behind schedule means to be progressing more slowly than planned. Compare: fall off (to decrease or decline), fall through (a plan fails completely), fall out (people argue). Behind schedule contrasts with on schedule (on time) and ahead of schedule (earlier than planned).', '2026-03-30 08:25:59.401228+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('4b2ea923-ea9e-459d-a33e-2e346eac892c', 1709, 'multiple_choice', 'B2', 'business_phrasal_verbs', 'The CEO brought in a consultant to _____ the business and identify areas for improvement.', 'look over', '["look over", "look up", "look after", "look around"]', NULL, NULL, NULL, 'To examine something carefully to check for problems or improvements.', 'Look over something means to examine or review it carefully. In a business context it is used for documents, processes, and organisations. Compare: look into (to investigate a specific issue in depth), go over (to review or check something), audit (a more formal and thorough examination).', '2026-03-30 08:25:59.401228+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('c47e38e8-8ba6-4f2d-b20f-7b31e08a6b6c', 1710, 'multiple_choice', 'B2', 'business_phrasal_verbs', 'After years of losses, the company finally managed to _____ its finances.', 'turn around', '["turn around", "turn over", "turn down", "turn out"]', NULL, NULL, NULL, 'To improve a failing business or situation — making it head in a new direction.', 'Turn around a business or situation means to reverse its decline and make it successful again. Compare: turn over (to generate revenue — the company turns over £2m a year), turn down (to reject), turn out (to produce a result — it turned out well). The noun turnaround describes the recovery itself.', '2026-03-30 08:25:59.401228+00', NULL, NULL, 'en', '{}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('2134364d-fb23-4060-a228-cc8909d2b0fe', 1711, 'gap_fill', 'B1', 'business_phrasal_verbs', 'The marketing team needs to _____ a proposal for the new campaign by the end of the week.', 'put together', NULL, NULL, NULL, NULL, 'To prepare or assemble something — like a proposal or report.', 'Put together means to prepare, create, or assemble something — a document, a team, a plan, or a presentation. It is one of the most versatile phrasal verbs in business English. Compare: draw up (more formal, often used for contracts and official documents), come up with (to think of an idea), pull together (to combine efforts).', '2026-03-30 08:25:59.401228+00', NULL, NULL, 'en', '{}', false, 'Two words. Starts with p___ t___.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('24e8a7e1-3823-4c44-b444-be132ab2aa95', 1712, 'gap_fill', 'B1', 'business_phrasal_verbs', 'The negotiations have been _____ for weeks — both sides need to reach a decision soon.', 'dragging on', NULL, NULL, NULL, NULL, 'Continuing for too long — like a slow, never-ending negotiation.', 'Drag on means to continue for longer than expected or desired, implying tedium or frustration. It is used for meetings, negotiations, disputes, and processes. Compare: drag out (to deliberately prolong something), go on (more neutral — to continue), run on (to exceed a planned time limit).', '2026-03-30 08:25:59.401228+00', NULL, NULL, 'en', '{}', false, 'Two words: -ing form + o___.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('9b6c0111-1be5-4b7a-94ec-6703ff5d8bc9', 1713, 'gap_fill', 'B1', 'business_phrasal_verbs', 'We need to _____ who is responsible for each part of the project before we start.', 'set out', NULL, NULL, NULL, NULL, 'To clearly state or define something at the start.', 'Set out means to explain or describe something clearly and systematically — a plan, responsibilities, or objectives. Compare: lay out (very similar — to present or arrange information clearly), spell out (to explain in very explicit detail), draw up (to prepare a formal document).', '2026-03-30 08:25:59.401228+00', NULL, NULL, 'en', '{}', false, 'Two words. Starts with s___ o___.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('5d85ea46-f637-4c80-87f5-0ebd0871fbf0', 1714, 'gap_fill', 'B2', 'business_phrasal_verbs', 'Demand for the product has been _____ since the price increase — sales are down 15%.', 'tailing off', NULL, NULL, NULL, '[{"answer": "slow", "feedback": "Slow is close in meaning, but the specific phrasal verb here is tailing off — which implies a gradual decline over time rather than simply being slow."}]', 'Gradually decreasing — like a tail getting thinner toward the end.', 'Tail off means to gradually decrease or diminish, especially after a period of growth or activity. It implies a slow decline rather than a sudden drop. Compare: fall off (a similar decline, slightly more abrupt), drop off (a more neutral decrease), level off (to stop changing and remain stable).', '2026-03-30 08:25:59.401228+00', NULL, NULL, 'en', '{}', false, 'Two words: -ing form + o___.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('0180d184-bf76-4cc9-9d55-91ba08d0589b', 1715, 'gap_fill', 'B2', 'business_phrasal_verbs', 'The company has decided to _____ its loss-making European division to focus on its core markets.', 'sell off', NULL, NULL, NULL, NULL, 'To sell parts of a business that aren''t profitable, often urgently.', 'Sell off means to sell something, often at a reduced price or as part of a restructuring. It implies the seller no longer wants to keep the asset. Compare: divest (more formal), spin off (to separate a division into an independent company), offload (to sell something you want to get rid of).', '2026-03-30 08:25:59.401228+00', NULL, NULL, 'en', '{}', false, 'Two words. Starts with s___ o___.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('4eb55bc4-da25-480a-a640-ba0e69af8ef7', 991, 'gap_fill', 'C1', 'hotel_vocabulary', 'A partial _______ was authorised after several guests complained about construction noise throughout their stay.', 'refund', NULL, NULL, NULL, NULL, 'Money returned to a customer.', 'A refund is money returned to a guest, usually as compensation for a problem during their stay. Partial refund means only part of the cost is returned.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Hotel vocabulary"}', false, 'Six letters. Starts with r___. The prefix means "back".', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('522844d8-3c84-4946-b916-da17cf9fabec', 992, 'gap_fill', 'C1', 'hotel_vocabulary', 'The hotel chain is investing heavily in the _______ of its oldest property in the city centre.', 'refurbishment', NULL, NULL, NULL, '["renovation", "restoration"]', 'Renovation — making something old look new again.', 'A refurbishment is a significant programme of renovation and updating — new furniture, fittings, and décor. Renovation and restoration are close synonyms.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Hotel vocabulary"}', false, 'Thirteen letters. From the verb "refurbish".', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('7df8f58b-8bc2-44c9-81c2-6f79e6985767', 993, 'gap_fill', 'C1', 'hotel_vocabulary', 'Staff training focused on managing the entire guest _______ — from the first online search to the post-stay review.', 'journey', NULL, NULL, NULL, '["experience"]', 'Marketing term — the customer ___ from awareness to loyalty.', 'The guest journey (or guest experience) covers every stage of a hotel stay — from the first search online, through check-in, the stay itself, check-out, and the post-stay review.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Hotel vocabulary",Collocation}', false, 'Seven letters. Starts with j___. The customer''s path.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('fcbf2492-ab9d-42f0-9e6f-d2efebd97a6f', 994, 'gap_fill', 'C2', 'hotel_vocabulary', 'The new general manager introduced _______ service protocols to ensure consistency across all 14 properties in the group.', 'standardised', NULL, NULL, NULL, '["standardized", "consistent", "unified"]', 'Made uniform across all locations — for consistency.', 'Standardised protocols ensure every property in a group delivers the same level of service, regardless of location. Consistency is a key goal in hotel chain management.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Hotel vocabulary"}', false, 'Twelve letters. British spelling (-ised, not -ized).', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('90398186-c85a-4823-a941-25cb0bcf9950', 995, 'gap_fill', 'C2', 'hotel_vocabulary', 'The hotel''s reputation for _______ service — anticipating guests'' needs before they are expressed — sets it apart from its competitors.', 'proactive', NULL, NULL, NULL, '["anticipatory", "personalised", "attentive"]', 'Acting before being asked — anticipating needs.', 'Proactive service means anticipating guests'' needs before they have to ask — for example, offering an umbrella when rain is forecast. It is considered the hallmark of luxury hospitality.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Hotel vocabulary",Collocation}', false, 'Nine letters. Starts with p___. The opposite of reactive.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('49c9a646-62eb-4307-9130-5940b2fee305', 996, 'gap_fill', 'C2', 'hotel_vocabulary', 'When a guest''s room is not yet ready on early arrival, good front desk staff will offer _______ storage and direct them to the hotel''s facilities.', 'luggage', NULL, NULL, NULL, '["baggage"]', '___ storage = where bags are kept temporarily.', 'Luggage storage means keeping guests'' bags securely while their room is not yet ready, or after check-out. A well-run front desk always offers this as a matter of course.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Hotel vocabulary","Uncountable noun"}', false, 'Seven letters. Starts with l___. Synonym of baggage.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('b285f240-44af-4a4d-884d-6384b7833e18', 2078, 'error_correction', 'C1', 'grammar', 'No sooner had the manager spoke than everyone fell silent.', 'No sooner had the manager spoken than everyone fell silent.', '[]', NULL, NULL, NULL, NULL, 'After "had", we need the past participle: "had … spoken", not "spoke".', '2026-06-01 07:05:45.329436+00', NULL, NULL, 'en', '{Tense}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('edb26421-2e4b-4b5e-8ef2-3f7113ea073b', 2079, 'error_correction', 'C1', 'grammar', 'Each of the candidates were asked the same question.', 'Each of the candidates was asked the same question.', '[]', NULL, NULL, NULL, NULL, '"Each of …" is singular, so it takes "was asked", not "were asked".', '2026-06-01 07:05:45.329436+00', NULL, NULL, 'en', '{Agreement}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('0d71dcd2-ae83-4da8-a728-faa52657672a', 2080, 'error_correction', 'A2', 'spanish', 'Yo tengo veinte años y vivo en Madrid desde hace tres año.', 'Yo tengo veinte años y vivo en Madrid desde hace tres años.', '[]', NULL, NULL, NULL, NULL, 'After "tres" (three) the noun is plural: "tres años". Numbers above one always take the plural noun in Spanish.', '2026-06-01 07:05:45.329436+00', NULL, NULL, 'es', '{Agreement}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('0b25f713-03d0-4fbc-8d59-4f47e384ec2b', 2081, 'error_correction', 'A2', 'spanish', 'Ella es profesora y trabaja en una escuela muy grande, ¿no? — Sí, ella es.', 'Ella es profesora y trabaja en una escuela muy grande, ¿no? — Sí, lo es.', '[]', NULL, NULL, NULL, NULL, 'Spanish replies with the neuter pronoun "lo": "Sí, lo es" stands in for the whole idea, where English just says "Yes, she is".', '2026-06-01 07:05:45.329436+00', NULL, NULL, 'es', '{Pronoun}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('0dd1e4b8-7386-4e7e-92db-fdf80ef2e7e6', 2082, 'error_correction', 'A2', 'spanish', 'Ayer fuimos a la playa y nadábamos en el mar toda la tarde.', 'Ayer fuimos a la playa y nadamos en el mar toda la tarde.', '[]', NULL, NULL, NULL, NULL, 'A completed action with "ayer" takes the preterite "nadamos", not the imperfect "nadábamos".', '2026-06-01 07:05:45.329436+00', NULL, NULL, 'es', '{Tense}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('f3cd76e9-1145-4ddc-aa95-e809511ffc42', 2083, 'error_correction', 'A2', 'spanish', 'Me gusta mucho los libros de aventuras.', 'Me gustan mucho los libros de aventuras.', '[]', NULL, NULL, NULL, NULL, 'With "gustar", the verb agrees with the thing liked: "los libros" is plural, so it must be "me gustan".', '2026-06-01 07:05:45.329436+00', NULL, NULL, 'es', '{Agreement}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('04028b8d-f39e-4a23-b9e1-5bd950e01909', 2084, 'error_correction', 'A2', 'spanish', 'No he visto a María desde hace mucho tiempo, pero la llamé mañana.', 'No he visto a María desde hace mucho tiempo, pero la llamaré mañana.', '[]', NULL, NULL, NULL, NULL, '"Mañana" (tomorrow) needs the future "la llamaré", not the preterite "la llamé".', '2026-06-01 07:05:45.329436+00', NULL, NULL, 'es', '{Tense}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('d160a06b-d667-43c8-8248-d9ecf03cc0b9', 2085, 'error_correction', 'A2', 'spanish', 'Siempre como en casa porque no me gusta los restaurantes.', 'Siempre como en casa porque no me gustan los restaurantes.', '[]', NULL, NULL, NULL, NULL, 'With "gustar", "los restaurantes" is plural, so the verb must be "gustan", not "gusta".', '2026-06-01 07:05:45.329436+00', NULL, NULL, 'es', '{Agreement}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('e81324b4-7fb6-4417-8318-f98b2c304e41', 2086, 'error_correction', 'A2', 'spanish', 'Estoy muy cansado porque he trabajado mucho hoy en la mañana.', 'Estoy muy cansado porque he trabajado mucho hoy por la mañana.', '[]', NULL, NULL, NULL, NULL, 'Spanish says "por la mañana" for "in the morning", not "en la mañana".', '2026-06-01 07:05:45.329436+00', NULL, NULL, 'es', '{Preposition}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('fced92b1-6251-4386-9517-d383c16cf43d', 2087, 'error_correction', 'A2', 'spanish', 'Si tendría más tiempo, viajaría por todo el mundo.', 'Si tuviera más tiempo, viajaría por todo el mundo.', '[]', NULL, NULL, NULL, NULL, 'In an "if" clause about the unreal present, Spanish uses the imperfect subjunctive "tuviera", not the conditional "tendría".', '2026-06-01 07:05:45.329436+00', NULL, NULL, 'es', '{Conditional}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('052f8c38-21bb-437f-ac4d-3af6ef8e4bfc', 2088, 'error_correction', 'A2', 'spanish', 'Hace mucho frío, así que voy a poner el abrigo.', 'Hace mucho frío, así que voy a ponerme el abrigo.', '[]', NULL, NULL, NULL, NULL, 'Putting on your own clothing is reflexive in Spanish: "ponerme el abrigo", not just "poner".', '2026-06-01 07:05:45.329436+00', NULL, NULL, 'es', '{Pronoun}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('7afcb744-fe8e-4378-ac87-fe7563a918d6', 2089, 'error_correction', 'A2', 'spanish', 'El año pasado he visitado Francia con mis amigos.', 'El año pasado visité Francia con mis amigos.', '[]', NULL, NULL, NULL, NULL, '"El año pasado" is finished past time, so it takes the preterite "visité", not the present perfect "he visitado".', '2026-06-01 07:05:45.329436+00', NULL, NULL, 'es', '{Tense}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('cebb8d6a-4d73-40e5-a3b6-80730e708d7d', 2120, 'sentence_building', 'A2', 'spanish', 'Build in Spanish: I don''t have any money.', 'No tengo dinero.', '["no", "tengo", "dinero", "tienes", "ningún", "nada", "el"]', NULL, NULL, NULL, NULL, 'Spanish negation: "No tengo dinero". Note Spanish needs no word for "any" here.', '2026-06-01 07:13:28.516357+00', NULL, NULL, 'es', '{Negation}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('5e6ed857-d5a4-4c5e-a5ec-a59f1ab4b0f4', 2121, 'sentence_building', 'A2', 'spanish', 'Build in Spanish: She gets up early every day.', 'Ella se levanta temprano todos los días.', '["ella", "se", "levanta", "temprano", "todos", "los", "días", "levantan", "cada", "tarde", "el"]', NULL, NULL, NULL, NULL, 'Reflexive verb in the present: "se levanta" (gets [him/herself] up). The pronoun "se" is essential.', '2026-06-01 07:13:28.516357+00', NULL, NULL, 'es', '{Reflexive}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('5790ed3c-5df2-4971-8f72-6e4467369bf0', 2122, 'sentence_building', 'A2', 'spanish', 'Build in Spanish: We went to the beach yesterday.', 'Ayer fuimos a la playa.', '["ayer", "fuimos", "a", "la", "playa", "vamos", "el", "fueron", "mar"]', NULL, NULL, NULL, NULL, 'Preterite for a completed past action: "fuimos a la playa" with the time marker "ayer".', '2026-06-01 07:13:28.516357+00', NULL, NULL, 'es', '{Tense}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('55004f7c-9a4d-49e4-8e74-9717ba0c22ac', 2123, 'sentence_building', 'A2', 'spanish', 'Build in Spanish: I have to study tonight.', 'Tengo que estudiar esta noche.', '["tengo", "que", "estudiar", "esta", "noche", "tienes", "de", "estudio", "mañana"]', NULL, NULL, NULL, NULL, 'Obligation with "tener que + infinitive": "Tengo que estudiar".', '2026-06-01 07:13:28.516357+00', NULL, NULL, 'es', '{"Modal verb"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('2f0280e1-e1d3-4b48-aa95-262b39a3a1a1', 2124, 'sentence_building', 'A2', 'spanish', 'Build in Spanish: Do you like Spanish food?', '¿Te gusta la comida española?', '["te", "gusta", "la", "comida", "española", "gustas", "el", "gustan", "francesa"]', NULL, NULL, NULL, NULL, 'With "gustar", the verb agrees with "la comida" (singular): "¿Te gusta…?".', '2026-06-01 07:13:28.516357+00', NULL, NULL, 'es', '{Agreement}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('64be210d-99f8-4dd2-9fc5-7e1b33764ab5', 2125, 'sentence_building', 'A2', 'spanish', 'Build in Spanish: There are many people here.', 'Hay mucha gente aquí.', '["hay", "mucha", "gente", "aquí", "muchos", "están", "allí", "mucho"]', NULL, NULL, NULL, NULL, '"Hay" means "there is/are" and never changes form: "Hay mucha gente".', '2026-06-01 07:13:28.516357+00', NULL, NULL, 'es', '{Agreement}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('5239494a-c852-40b2-8eba-1fd2be4a34f1', 2126, 'sentence_building', 'A2', 'spanish', 'Build in Spanish: He''s taller than his brother.', 'Él es más alto que su hermano.', '["él", "es", "más", "alto", "que", "su", "hermano", "mucho", "como", "está", "mayor"]', NULL, NULL, NULL, NULL, 'Comparative in Spanish: "más alto que" = "taller than".', '2026-06-01 07:13:28.516357+00', NULL, NULL, 'es', '{Comparative}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('e7ee4744-2ef1-4315-abf2-ecc17d5e55b5', 2127, 'sentence_building', 'A2', 'spanish', 'Build in Spanish: I''m going to call you tomorrow.', 'Voy a llamarte mañana.', '["voy", "a", "llamarte", "mañana", "vas", "de", "llamo", "te", "ayer"]', NULL, NULL, NULL, NULL, 'Near future with "ir a + infinitive": "Voy a llamarte", with the pronoun attached to the infinitive.', '2026-06-01 07:13:28.516357+00', NULL, NULL, 'es', '{Tense}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('4785558f-b13d-4115-98cc-2a36e3d60277', 2128, 'sentence_building', 'A2', 'spanish', 'Build in Spanish: We were watching TV when she arrived.', 'Estábamos viendo la tele cuando ella llegó.', '["estábamos", "viendo", "la", "tele", "cuando", "ella", "llegó", "estamos", "vimos", "llega", "veíamos"]', NULL, NULL, NULL, NULL, 'Imperfect for the background action ("estábamos viendo") interrupted by a preterite ("llegó").', '2026-06-01 07:13:28.516357+00', NULL, NULL, 'es', '{Tense}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('063092f8-1fa2-4c94-8772-0ddf98737400', 2129, 'sentence_building', 'A2', 'spanish', 'Build in Spanish: You should drink more water.', 'Deberías beber más agua.', '["deberías", "beber", "más", "agua", "debes", "de", "bebes", "mucho", "leche"]', NULL, NULL, NULL, NULL, 'Advice with the conditional "deberías" = "you should".', '2026-06-01 07:13:28.516357+00', NULL, NULL, 'es', '{Conditional}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('baf46ad4-5006-4d32-b812-12b58abe142c', 2160, 'multiple_choice', 'A2', 'spanish', 'Voy ___ la playa este fin de semana.', 'a', '["a", "en", "de", "por"]', NULL, NULL, NULL, 'In Spanish, movement towards a place uses this one-letter word.', 'Spanish uses "a" for movement towards a place: "voy a la playa".', '2026-06-01 07:16:29.304337+00', NULL, NULL, 'es', '{Preposition}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('f18e4e95-c421-41c5-8280-e54fa4c710b1', 2161, 'multiple_choice', 'A2', 'spanish', 'El libro está ___ la mesa.', 'en', '["en", "a", "de", "por"]', NULL, NULL, NULL, 'Spanish uses one word for both "on" and "in" when showing location.', 'Spanish "en" covers both "on" and "in" for location: "en la mesa".', '2026-06-01 07:16:29.304337+00', NULL, NULL, 'es', '{Preposition}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('23e0039b-1103-4cc0-b174-05963c44d5de', 2162, 'multiple_choice', 'A2', 'spanish', 'Este regalo es ___ mi madre.', 'para', '["para", "por", "de", "a"]', NULL, NULL, NULL, 'The gift is intended for her — Spanish has a special word for purpose/recipient.', '"Para" shows the intended recipient or purpose: "para mi madre".', '2026-06-01 07:16:29.304337+00', NULL, NULL, 'es', '{Preposition}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('5bf28e37-b689-4e06-98b3-0985c64da369', 2163, 'multiple_choice', 'A2', 'spanish', 'Salimos ___ Madrid a las ocho.', 'de', '["de", "a", "en", "por"]', NULL, NULL, NULL, 'Leaving "from" a place.', '"De" shows origin — leaving "from" a place: "salimos de Madrid".', '2026-06-01 07:16:29.304337+00', NULL, NULL, 'es', '{Preposition}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('7a888672-17d1-4db2-8005-55e69556a6cf', 2164, 'multiple_choice', 'A2', 'spanish', 'Estudio español ___ las tardes.', 'por', '["por", "en", "a", "de"]', NULL, NULL, NULL, '"___ las tardes" = in/during the afternoons.', '"Por las tardes" means "in the afternoons" — Spanish uses "por" for parts of the day.', '2026-06-01 07:16:29.304337+00', NULL, NULL, 'es', '{Preposition}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('2304fad0-c6ef-45d0-b979-4f4643d6a6bc', 2165, 'multiple_choice', 'A2', 'spanish', 'Trabajo ___ una empresa grande.', 'en', '["en", "a", "de", "por"]', NULL, NULL, NULL, 'You work inside it — same word as location.', '"En" is used for the place where you work: "trabajo en una empresa".', '2026-06-01 07:16:29.304337+00', NULL, NULL, 'es', '{Preposition}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('f0793139-b3b4-4ac9-b1ea-20c244c54110', 2166, 'multiple_choice', 'A2', 'spanish', 'Gracias ___ tu ayuda.', 'por', '["por", "para", "de", "a"]', NULL, NULL, NULL, '"Gracias ___" = thanks for something received.', '"Gracias por" thanks someone for something: "gracias por tu ayuda".', '2026-06-01 07:16:29.304337+00', NULL, NULL, 'es', '{Preposition}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('32de6d8a-1288-48a6-a983-1b4281b48379', 2167, 'multiple_choice', 'A2', 'spanish', 'Vamos a viajar ___ tren.', 'en', '["en", "por", "a", "de"]', NULL, NULL, NULL, 'Spanish says "___ tren / ___ coche" for means of transport — not the English "by".', 'Spanish says "en tren / en coche" for means of transport — unlike English "by train".', '2026-06-01 07:16:29.304337+00', NULL, NULL, 'es', '{Preposition}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('ff2eda42-9676-4f15-96b1-f0b3e6bbf910', 2168, 'multiple_choice', 'A2', 'spanish', 'La carta es ___ Juan.', 'de', '["de", "a", "en", "para"]', NULL, NULL, NULL, 'Shows possession — "of/from".', '"De" shows possession or origin: "la carta es de Juan".', '2026-06-01 07:16:29.304337+00', NULL, NULL, 'es', '{Preposition}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('3e3114aa-5124-47e2-8ee3-838508d00faf', 2169, 'multiple_choice', 'A2', 'spanish', 'Vivo cerca ___ la estación.', 'de', '["de", "a", "en", "por"]', NULL, NULL, NULL, '"cerca ___" = near to.', '"Cerca de" means "near to": "cerca de la estación".', '2026-06-01 07:16:29.304337+00', NULL, NULL, 'es', '{Preposition}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('b7a0dc39-a71d-40af-b4c0-11cf490f7eef', 2170, 'multiple_choice', 'A2', 'vocabulary', 'I need to ___ a decision about the job.', 'make', '["make", "do", "think", "get"]', NULL, NULL, NULL, 'We "___ a decision" in English — a fixed verb-noun pairing.', 'We "make a decision" in English — "make" is the verb that collocates with "decision".', '2026-06-01 07:21:37.506938+00', NULL, NULL, 'en', '{Collocation}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('5cc0e841-56fd-4ead-8c78-56c8f9381d4e', 2171, 'multiple_choice', 'A2', 'vocabulary', 'She''s very ___ — she always helps people.', 'kind', '["kind", "tall", "fast", "late"]', NULL, NULL, NULL, 'A word for a caring, generous personality.', '"Kind" describes a caring, generous person who helps others.', '2026-06-01 07:21:37.506938+00', NULL, NULL, 'en', '{Vocabulary}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('154e7e73-6eec-4847-b8fc-8c5e95103cfb', 2172, 'multiple_choice', 'A2', 'vocabulary', 'Can you ___ me the salt, please?', 'pass', '["pass", "bring", "show", "send"]', NULL, NULL, NULL, 'Hand it across the table to someone nearby.', 'To "pass" something means to hand it across to someone nearby.', '2026-06-01 07:21:37.506938+00', NULL, NULL, 'en', '{Vocabulary}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('1ebce7d4-69ff-4683-a667-6b5b5e6b0a9f', 2173, 'multiple_choice', 'A2', 'vocabulary', 'We had a lot of ___ on holiday.', 'fun', '["fun", "funny", "happy", "joke"]', NULL, NULL, NULL, 'Uncountable noun in the phrase "have ___".', '"Fun" is an uncountable noun used in the phrase "have fun".', '2026-06-01 07:21:37.506938+00', NULL, NULL, 'en', '{Vocabulary}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('37d025c4-5138-48d6-99f2-de4f797cc6ff', 2174, 'multiple_choice', 'A2', 'vocabulary', 'He ___ his homework every evening.', 'does', '["does", "makes", "takes", "writes"]', NULL, NULL, NULL, 'We "___ homework" in English, not "make" it.', 'We "do homework" in English — "do", not "make".', '2026-06-01 07:21:37.506938+00', NULL, NULL, 'en', '{Collocation}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('714cc0fa-a053-47c4-a6cb-5cb65dd3abcb', 2175, 'multiple_choice', 'A2', 'vocabulary', 'The film was really ___. I nearly fell asleep.', 'boring', '["boring", "bored", "fun", "excited"]', NULL, NULL, NULL, 'Describes the film itself, not how a person feels.', 'An "-ing" adjective ("boring") describes the thing; an "-ed" adjective ("bored") describes how a person feels.', '2026-06-01 07:21:37.506938+00', NULL, NULL, 'en', '{Vocabulary}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('0e28a78b-69ae-44ca-8789-534d7fb2b347', 2176, 'multiple_choice', 'A2', 'vocabulary', 'I usually ___ the bus to work.', 'take', '["take", "make", "do", "drive"]', NULL, NULL, NULL, 'We "___ the bus/train" when we travel as a passenger.', 'We "take the bus/train" when travelling as a passenger.', '2026-06-01 07:21:37.506938+00', NULL, NULL, 'en', '{Collocation}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('f79bfc31-0509-4375-9d6e-cb850eac584e', 2177, 'multiple_choice', 'A2', 'vocabulary', 'There isn''t ___ milk in the fridge.', 'much', '["much", "many", "lot", "few"]', NULL, NULL, NULL, 'Used with uncountable nouns in negative sentences.', 'We use "much" with uncountable nouns like "milk", especially in negatives.', '2026-06-01 07:21:37.506938+00', NULL, NULL, 'en', '{Quantifier}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('e555edf1-2736-4b7e-9906-651300982cae', 2178, 'multiple_choice', 'A2', 'vocabulary', 'She''s good at ___ photos.', 'taking', '["taking", "making", "doing", "getting"]', NULL, NULL, NULL, '"___ a photo" uses a specific verb in English.', 'We "take a photo" in English — "take" is the verb that collocates with "photo".', '2026-06-01 07:21:37.506938+00', NULL, NULL, 'en', '{Collocation}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('0ac873c1-fe41-45b5-9c2c-723f6098e4ed', 2179, 'multiple_choice', 'A2', 'vocabulary', 'Could you ___ the music down a bit?', 'turn', '["turn", "put", "make", "get"]', NULL, NULL, NULL, '"___ the volume down" — adjust the level.', '"Turn down" means to lower the volume or level of something.', '2026-06-01 07:21:37.506938+00', NULL, NULL, 'en', '{Vocabulary}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('80654e17-c7fe-45b2-9d09-336d15c42dd9', 2180, 'gap_fill', 'B2', 'vocabulary', 'The negotiations finally reached a ___ after months of talks.', 'breakthrough', '[]', NULL, NULL, NULL, 'A sudden, important success after a long effort.', 'A "breakthrough" is a sudden, important advance after a long effort.', '2026-06-01 07:21:37.506938+00', NULL, NULL, 'en', '{Vocabulary}', false, 'Starts with "break".', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('63ba28b9-776d-49d7-8d55-051b9f34092e', 2181, 'gap_fill', 'B2', 'vocabulary', 'I''d like to ___ a complaint about the service.', 'make', '[]', NULL, NULL, NULL, '"___ a complaint" — the standard verb collocation.', 'We "make a complaint" in English — "make", not "do".', '2026-06-01 07:21:37.506938+00', NULL, NULL, 'en', '{Collocation}', false, 'It is not "do".', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('0b8cd7b6-8681-4bf2-a753-9ecb5b23993d', 2182, 'gap_fill', 'B2', 'vocabulary', 'Their argument had a serious ___ on the whole team.', 'impact', '[]', NULL, NULL, '[{"answer": "effect", "feedback": "Also correct — \"effect on\" works just as well as \"impact on\" here."}]', 'A strong influence or result.', '"Impact on" and "effect on" both work here — both mean a strong influence or result.', '2026-06-01 07:21:37.506938+00', NULL, NULL, 'en', '{Vocabulary}', false, 'Starts with "im" (or "ef" for the alternative).', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('b7f73f3a-8cee-4148-90b8-f9b1b7038f18', 2183, 'gap_fill', 'B2', 'vocabulary', 'He gave a very ___ explanation that everyone understood.', 'clear', '[]', NULL, NULL, NULL, 'Easy to follow; the opposite of confusing.', 'A "clear" explanation is easy to follow and understand.', '2026-06-01 07:21:37.506938+00', NULL, NULL, 'en', '{Vocabulary}', false, 'Five letters.', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('951654c4-973c-451f-9050-c6eec097fc23', 2184, 'gap_fill', 'B2', 'vocabulary', 'The company is trying to ___ costs this year.', 'cut', '[]', NULL, NULL, '[{"answer": "reduce", "feedback": "Also correct — \"reduce costs\" is a perfect synonym for \"cut costs\"."}]', 'Make them smaller.', '"Cut costs" and "reduce costs" both mean to make them smaller; "cut" is more informal.', '2026-06-01 07:21:37.506938+00', NULL, NULL, 'en', '{Collocation}', false, 'Three letters ("cut") or six ("reduce").', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('45dde333-fa54-4182-b11c-7161b90e66bf', 2185, 'multiple_choice', 'B2', 'vocabulary', 'The new manager is highly ___ of her team.', 'supportive', '["supportive", "support", "supportable", "supporting"]', NULL, NULL, NULL, 'Choose the correct adjective form to follow "highly".', '"Supportive" is the adjective form needed after "highly".', '2026-06-01 07:21:37.506938+00', NULL, NULL, 'en', '{"Word formation"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('05c68f12-70a6-45de-a560-f2f0f159d506', 2186, 'multiple_choice', 'B2', 'vocabulary', 'We need to ___ a solution as soon as possible.', 'find', '["find", "make", "do", "put"]', NULL, NULL, NULL, '"___ a solution" — the natural verb collocation.', 'We "find a solution" in English — "find" is the natural verb here.', '2026-06-01 07:21:37.506938+00', NULL, NULL, 'en', '{Collocation}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('bfdb9fa7-18a5-4fb7-a9ac-b3c3f742e131', 2187, 'multiple_choice', 'B2', 'vocabulary', 'His behaviour was completely ___.', 'unacceptable', '["unacceptable", "unaccept", "acceptance", "accepting"]', NULL, NULL, NULL, 'Choose the negative adjective form.', '"Unacceptable" is the correct negative adjective form.', '2026-06-01 07:21:37.506938+00', NULL, NULL, 'en', '{"Word formation"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('42fa07f1-d0e8-41e4-bb50-1b912379f63b', 2188, 'multiple_choice', 'B2', 'vocabulary', 'The results were ___ disappointing.', 'deeply', '["deeply", "deep", "depth", "deepen"]', NULL, NULL, NULL, 'You need an adverb to modify the adjective "disappointing".', '"Deeply" is the adverb needed to modify the adjective "disappointing".', '2026-06-01 07:21:37.506938+00', NULL, NULL, 'en', '{"Word formation"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('5468abb7-3e63-47ad-8281-30298c542a42', 2189, 'multiple_choice', 'B2', 'vocabulary', 'She made a ___ effort to improve.', 'conscious', '["conscious", "conscience", "consciously", "consciousness"]', NULL, NULL, NULL, 'You need an adjective before the noun "effort".', '"Conscious" is the adjective that fits before the noun "effort".', '2026-06-01 07:21:37.506938+00', NULL, NULL, 'en', '{"Word formation"}', false, NULL, NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('77fdf0be-959c-4985-ae00-4e8bfc3db9fb', 2190, 'gap_fill', 'C1', 'vocabulary', 'The evidence was too ___ to support a conviction.', 'flimsy', '[]', NULL, NULL, NULL, 'Weak and unconvincing.', '"Flimsy" evidence is weak and unconvincing.', '2026-06-01 07:21:37.506938+00', NULL, NULL, 'en', '{Vocabulary}', false, 'Starts with "fl".', NULL);
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags, is_idiomatic, hint2, hint_word_class) VALUES ('7b4b12f5-793c-444e-82ea-76b6c43f009b', 2191, 'gap_fill', 'C1', 'vocabulary', 'Her ___ remarks offended several colleagues.', 'tactless', '[]', NULL, NULL, NULL, 'Lacking sensitivity in what one says.', '"Tactless" means lacking sensitivity in what one says — the opposite of "tactful".', '2026-06-01 07:21:37.506938+00', NULL, NULL, 'en', '{Vocabulary}', false, 'The opposite of "tactful".', NULL);
